import sys
import os
import struct
from collections import deque


def extract_channel(pixel, mask):
    if mask == 0:
        return 0
    s = 0
    temp = mask
    while temp & 1 == 0:
        s += 1
        temp >>= 1
    v = (pixel & mask) >> s
    n = bin(mask).count('1')
    m = (1 << n) - 1
    if m == 0:
        return 0
    return (v * 255 + m // 2) // m


def read_bmp(filepath):
    with open(filepath, 'rb') as f:
        data = f.read()

    if len(data) < 14 or data[0:2] != b'BM':
        return None

    bf_off_bits = struct.unpack_from('<I', data, 10)[0]

    dib_size = struct.unpack_from('<I', data, 14)[0]
    width = struct.unpack_from('<i', data, 18)[0]
    height = struct.unpack_from('<i', data, 22)[0]
    bpp = struct.unpack_from('<H', data, 28)[0]
    compression = struct.unpack_from('<I', data, 30)[0]
    colors_used = struct.unpack_from('<I', data, 46)[0]

    if compression not in (0, 3):
        return ('error', compression)

    if compression == 3 and bpp != 32:
        return ('error', compression)

    top_down = height < 0
    abs_height = abs(height)

    # Read masks for BI_BITFIELDS
    red_mask = green_mask = blue_mask = 0
    if compression == 3:
        if dib_size == 40:
            red_mask = struct.unpack_from('<I', data, 14 + 40)[0]
            green_mask = struct.unpack_from('<I', data, 14 + 44)[0]
            blue_mask = struct.unpack_from('<I', data, 14 + 48)[0]
        elif dib_size in (108, 124):
            red_mask = struct.unpack_from('<I', data, 14 + 40)[0]
            green_mask = struct.unpack_from('<I', data, 14 + 44)[0]
            blue_mask = struct.unpack_from('<I', data, 14 + 48)[0]

    # Build palette for indexed images
    palette = []
    if bpp in (1, 4, 8):
        palette_offset = 14 + dib_size
        num_colors = colors_used if colors_used != 0 else (1 << bpp)
        for i in range(num_colors):
            off = palette_offset + i * 4
            b = data[off]
            g = data[off + 1]
            r = data[off + 2]
            palette.append((r, g, b))

    # Compute row stride (padded to multiple of 4 bytes)
    row_stride = ((width * bpp + 31) // 32) * 4

    # Read pixels into a 2D boolean grid (True = ink)
    pixels = [[False] * width for _ in range(abs_height)]

    for y in range(abs_height):
        if top_down:
            stored_row = y
        else:
            stored_row = abs_height - 1 - y

        row_offset = bf_off_bits + stored_row * row_stride

        for x in range(width):
            if bpp == 1:
                byte_idx = x // 8
                bit_idx = 7 - (x % 8)
                color_idx = (data[row_offset + byte_idx] >> bit_idx) & 1
                r, g, b = palette[color_idx]
            elif bpp == 4:
                byte_idx = x // 2
                if x % 2 == 0:
                    color_idx = (data[row_offset + byte_idx] >> 4) & 0xF
                else:
                    color_idx = data[row_offset + byte_idx] & 0xF
                r, g, b = palette[color_idx]
            elif bpp == 8:
                color_idx = data[row_offset + x]
                r, g, b = palette[color_idx]
            elif bpp == 24:
                off = row_offset + x * 3
                b = data[off]
                g = data[off + 1]
                r = data[off + 2]
            elif bpp == 32:
                pixel_val = struct.unpack_from('<I', data, row_offset + x * 4)[0]
                if compression == 3:
                    r = extract_channel(pixel_val, red_mask)
                    g = extract_channel(pixel_val, green_mask)
                    b = extract_channel(pixel_val, blue_mask)
                else:
                    off = row_offset + x * 4
                    b = data[off]
                    g = data[off + 1]
                    r = data[off + 2]
            else:
                continue

            if (299 * r + 587 * g + 114 * b) // 1000 < 128:
                pixels[y][x] = True

    return ('ok', width, abs_height, bpp, dib_size, top_down, pixels)


def find_components(pixels, width, height):
    visited = [[False] * width for _ in range(height)]
    components = []

    for y in range(height):
        for x in range(width):
            if pixels[y][x] and not visited[y][x]:
                queue = deque()
                queue.append((x, y))
                visited[y][x] = True
                count = 0
                min_x, max_x, min_y, max_y = x, x, y, y

                while queue:
                    cx, cy = queue.popleft()
                    count += 1
                    if cx < min_x:
                        min_x = cx
                    if cx > max_x:
                        max_x = cx
                    if cy < min_y:
                        min_y = cy
                    if cy > max_y:
                        max_y = cy

                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if dx == 0 and dy == 0:
                                continue
                            nx, ny = cx + dx, cy + dy
                            if 0 <= nx < width and 0 <= ny < height:
                                if pixels[ny][nx] and not visited[ny][nx]:
                                    visited[ny][nx] = True
                                    queue.append((nx, ny))

                components.append((x, y, min_x, min_y, max_x, max_y, count))

    return components


def main():
    directory = sys.argv[1]

    files = [f for f in os.listdir(directory) if f.endswith('.bmp')]
    files.sort(key=lambda f: f.encode('utf-8'))

    for fname in files:
        filepath = os.path.join(directory, fname)
        result = read_bmp(filepath)

        if result is None:
            continue

        if result[0] == 'error':
            print(f"== {fname}")
            print(f"error: unsupported compression {result[1]}")
        else:
            _, width, height, bpp, dib_size, top_down, pixels = result
            components = find_components(pixels, width, height)

            ink_count = sum(1 for row in pixels for val in row if val)
            orientation = "top-down" if top_down else "bottom-up"

            print(f"== {fname}")
            print(f"size {width}x{height} bpp {bpp} header {dib_size} {orientation} ink {ink_count}")
            print(f"components {len(components)}")

            for (fx, fy, min_x, min_y, max_x, max_y, cnt) in components:
                print(f"{fx},{fy} bbox {min_x},{min_y}-{max_x},{max_y} pixels {cnt}")


if __name__ == '__main__':
    main()

import * as fs from 'fs';
import * as path from 'path';

function extractChannel(pixel: number, mask: number): number {
    let s = 0;
    let temp = mask;
    while ((temp & 1) === 0) {
        s++;
        temp >>>= 1;
    }
    let n = 0;
    temp = mask;
    while (temp > 0) {
        if (temp & 1) n++;
        temp >>>= 1;
    }
    const m = (1 << n) - 1;
    const v = (pixel & mask) >>> s;
    return Math.floor((v * 255 + Math.floor(m / 2)) / m);
}

function processFile(filePath: string, fileName: string): void {
    const data = fs.readFileSync(filePath);

    const bfOffBits = data.readUInt32LE(10);
    const dibSize = data.readUInt32LE(14);
    const width = data.readInt32LE(18);
    const heightRaw = data.readInt32LE(22);
    const bpp = data.readUInt16LE(28);
    const compression = data.readUInt32LE(30);
    const colorsUsed = data.readUInt32LE(46);

    if (compression !== 0 && compression !== 3) {
        console.log(`== ${fileName}`);
        console.log(`error: unsupported compression ${compression}`);
        return;
    }

    const absHeight = Math.abs(heightRaw);
    const bottomUp = heightRaw > 0;

    let redMask = 0, greenMask = 0, blueMask = 0;
    if (compression === 3) {
        redMask = data.readUInt32LE(54);
        greenMask = data.readUInt32LE(58);
        blueMask = data.readUInt32LE(62);
    }

    const paletteOffset = 14 + dibSize;
    const paletteEntries = colorsUsed === 0 ? (1 << bpp) : colorsUsed;

    let rowBytes: number;
    if (bpp === 1) {
        rowBytes = Math.ceil(width / 8);
    } else if (bpp === 4) {
        rowBytes = Math.ceil(width / 2);
    } else if (bpp === 8) {
        rowBytes = width;
    } else if (bpp === 24) {
        rowBytes = width * 3;
    } else if (bpp === 32) {
        rowBytes = width * 4;
    } else {
        return;
    }
    rowBytes = (rowBytes + 3) & ~3;

    const ink: boolean[][] = [];
    let inkCount = 0;

    for (let y = 0; y < absHeight; y++) {
        ink[y] = new Array(width).fill(false);
        const storedRow = bottomUp ? (absHeight - 1 - y) : y;
        const rowOffset = bfOffBits + storedRow * rowBytes;

        for (let x = 0; x < width; x++) {
            let r: number, g: number, b: number;

            if (bpp === 1) {
                const byteIdx = x >> 3;
                const bitIdx = 7 - (x & 7);
                const byteVal = data[rowOffset + byteIdx];
                const idx = (byteVal >> bitIdx) & 1;
                const palOff = paletteOffset + idx * 4;
                b = data[palOff];
                g = data[palOff + 1];
                r = data[palOff + 2];
            } else if (bpp === 4) {
                const byteIdx = x >> 1;
                const nibbleShift = (x & 1) === 0 ? 4 : 0;
                const byteVal = data[rowOffset + byteIdx];
                const idx = (byteVal >> nibbleShift) & 0xF;
                const palOff = paletteOffset + idx * 4;
                b = data[palOff];
                g = data[palOff + 1];
                r = data[palOff + 2];
            } else if (bpp === 8) {
                const idx = data[rowOffset + x];
                const palOff = paletteOffset + idx * 4;
                b = data[palOff];
                g = data[palOff + 1];
                r = data[palOff + 2];
            } else if (bpp === 24) {
                const pxOff = rowOffset + x * 3;
                b = data[pxOff];
                g = data[pxOff + 1];
                r = data[pxOff + 2];
            } else {
                // bpp === 32
                const pxOff = rowOffset + x * 4;
                if (compression === 0) {
                    b = data[pxOff];
                    g = data[pxOff + 1];
                    r = data[pxOff + 2];
                } else {
                    const pixel = data.readUInt32LE(pxOff);
                    r = extractChannel(pixel, redMask);
                    g = extractChannel(pixel, greenMask);
                    b = extractChannel(pixel, blueMask);
                }
            }

            const lum = Math.floor((299 * r + 587 * g + 114 * b) / 1000);
            if (lum < 128) {
                ink[y][x] = true;
                inkCount++;
            }
        }
    }

    // Connected components with 8-connectivity
    const visited: boolean[][] = Array.from({ length: absHeight }, () => new Array(width).fill(false));
    const components: { firstX: number; firstY: number; minX: number; minY: number; maxX: number; maxY: number; count: number }[] = [];

    const dx = [-1, 0, 1, -1, 1, -1, 0, 1];
    const dy = [-1, -1, -1, 0, 0, 1, 1, 1];

    for (let y = 0; y < absHeight; y++) {
        for (let x = 0; x < width; x++) {
            if (ink[y][x] && !visited[y][x]) {
                const queue: number[] = [y * width + x];
                visited[y][x] = true;
                let minX = x, maxX = x, minY = y, maxY = y, count = 0;
                let head = 0;

                while (head < queue.length) {
                    const pos = queue[head++];
                    const cx = pos % width;
                    const cy = (pos / width) | 0;
                    count++;
                    if (cx < minX) minX = cx;
                    if (cx > maxX) maxX = cx;
                    if (cy < minY) minY = cy;
                    if (cy > maxY) maxY = cy;

                    for (let d = 0; d < 8; d++) {
                        const nx = cx + dx[d];
                        const ny = cy + dy[d];
                        if (nx >= 0 && nx < width && ny >= 0 && ny < absHeight && ink[ny][nx] && !visited[ny][nx]) {
                            visited[ny][nx] = true;
                            queue.push(ny * width + nx);
                        }
                    }
                }

                components.push({ firstX: x, firstY: y, minX, minY, maxX, maxY, count });
            }
        }
    }

    console.log(`== ${fileName}`);
    console.log(`size ${width}x${absHeight} bpp ${bpp} header ${dibSize} ${bottomUp ? 'bottom-up' : 'top-down'} ink ${inkCount}`);
    console.log(`components ${components.length}`);
    for (const comp of components) {
        console.log(`${comp.firstX},${comp.firstY} bbox ${comp.minX},${comp.minY}-${comp.maxX},${comp.maxY} pixels ${comp.count}`);
    }
}

