import Foundation

func readU16LE(_ d: [UInt8], _ o: Int) -> UInt16 {
    return UInt16(d[o]) | (UInt16(d[o+1]) << 8)
}

func readU32LE(_ d: [UInt8], _ o: Int) -> UInt32 {
    return UInt32(d[o]) | (UInt32(d[o+1]) << 8) | (UInt32(d[o+2]) << 16) | (UInt32(d[o+3]) << 24)
}

func readI32LE(_ d: [UInt8], _ o: Int) -> Int32 {
    return Int32(bitPattern: readU32LE(d, o))
}

func trailingZeros(_ x: UInt32) -> Int {
    if x == 0 { return 32 }
    var count = 0
    var v = x
    while v & 1 == 0 {
        count += 1
        v >>= 1
    }
    return count
}

func popcount32(_ x: UInt32) -> Int {
    var count = 0
    var v = x
    while v != 0 {
        count += Int(v & 1)
        v >>= 1
    }
    return count
}

func extractChannel(_ pixel: UInt32, mask: UInt32) -> Int {
    let s = trailingZeros(mask)
    let n = popcount32(mask)
    let v = (pixel & mask) >> UInt32(s)
    let m = UInt32((1 << n) - 1)
    return Int((v &* 255 + m / 2) / m)
}

func isInk(r: Int, g: Int, b: Int) -> Bool {
    return (299 * r + 587 * g + 114 * b) / 1000 < 128
}

func processFile(path: String, name: String) {
    guard let data = try? Data(contentsOf: URL(fileURLWithPath: path)) else { return }
    let bytes = [UInt8](data)
    let fileLen = bytes.count

    guard fileLen >= 14 else { return }
    guard bytes[0] == 0x42 && bytes[1] == 0x4D else { return }

    let bfOffBits = Int(readU32LE(bytes, 10))

    let dibOff = 14
    guard fileLen >= dibOff + 4 else { return }
    let dibSize = Int(readU32LE(bytes, dibOff))

    guard dibSize == 40 || dibSize == 108 || dibSize == 124 else { return }
    guard fileLen >= dibOff + 40 else { return }

    let width = Int(readI32LE(bytes, dibOff + 4))
    let heightRaw = Int(readI32LE(bytes, dibOff + 8))
    let height = abs(heightRaw)
    let bottomUp = heightRaw > 0
    let bpp = Int(readU16LE(bytes, dibOff + 14))
    let compression = Int(readU32LE(bytes, dibOff + 16))
    let coloursUsed = Int(readU32LE(bytes, dibOff + 32))

    let supported = (compression == 0) || (compression == 3 && bpp == 32)
    if !supported {
        print("== \(name)")
        print("error: unsupported compression \(compression)")
        return
    }

    var redMask: UInt32 = 0, greenMask: UInt32 = 0, blueMask: UInt32 = 0
    if compression == 3 {
        let maskOff = dibOff + 40
        if fileLen >= maskOff + 12 {
            redMask = readU32LE(bytes, maskOff)
            greenMask = readU32LE(bytes, maskOff + 4)
            blueMask = readU32LE(bytes, maskOff + 8)
        }
    }

    let colorTableOff = dibOff + dibSize
    var colorTable: [(Int, Int, Int)] = []
    if bpp == 1 || bpp == 4 || bpp == 8 {
        let numColors = coloursUsed > 0 ? coloursUsed : (1 << bpp)
        colorTable.reserveCapacity(numColors)
        for i in 0..<numColors {
            let off = colorTableOff + i * 4
            if off + 3 < fileLen {
                let b = Int(bytes[off])
                let g = Int(bytes[off + 1])
                let r = Int(bytes[off + 2])
                colorTable.append((r, g, b))
            } else {
                colorTable.append((0, 0, 0))
            }
        }
    }

    let rowBytes: Int
    switch bpp {
    case 1:  rowBytes = ((width + 7) / 8 + 3) & ~3
    case 4:  rowBytes = ((width + 1) / 2 + 3) & ~3
    case 8:  rowBytes = (width + 3) & ~3
    case 24: rowBytes = (width * 3 + 3) & ~3
    case 32: rowBytes = width * 4
    default: return
    }

    var ink = [[Bool]](repeating: [Bool](repeating: false, count: width), count: height)
    var inkCount = 0

    for storedRow in 0..<height {
        let y: Int
        if bottomUp {
            y = height - 1 - storedRow
        } else {
            y = storedRow
        }
        let rowOff = bfOffBits + storedRow * rowBytes

        for x in 0..<width {
            var r = 0, g = 0, b = 0

            switch bpp {
            case 1:
                let byteIdx = x / 8
                let bitIdx = 7 - (x % 8)
                let off = rowOff + byteIdx
                if off < fileLen {
                    let idx = Int((bytes[off] >> bitIdx) & 1)
                    if idx < colorTable.count { (r, g, b) = colorTable[idx] }
                }
            case 4:
                let byteIdx = x / 2
                let off = rowOff + byteIdx
                if off < fileLen {
                    let idx: Int
                    if x % 2 == 0 { idx = Int(bytes[off] >> 4) & 0xF }
                    else { idx = Int(bytes[off]) & 0xF }
                    if idx < colorTable.count { (r, g, b) = colorTable[idx] }
                }
            case 8:
                let off = rowOff + x
                if off < fileLen {
                    let idx = Int(bytes[off])
                    if idx < colorTable.count { (r, g, b) = colorTable[idx] }
                }
            case 24:
                let off = rowOff + x * 3
                if off + 2 < fileLen {
                    b = Int(bytes[off]); g = Int(bytes[off+1]); r = Int(bytes[off+2])
                }
            case 32:
                if compression == 0 {
                    let off = rowOff + x * 4
                    if off + 2 < fileLen {
                        b = Int(bytes[off]); g = Int(bytes[off+1]); r = Int(bytes[off+2])
                    }
                } else {
                    let off = rowOff + x * 4
                    if off + 3 < fileLen {
                        let pixel = readU32LE(bytes, off)
                        r = extractChannel(pixel, mask: redMask)
                        g = extractChannel(pixel, mask: greenMask)
                        b = extractChannel(pixel, mask: blueMask)
                    }
                }
            default: break
            }

            if isInk(r: r, g: g, b: b) {
                ink[y][x] = true
                inkCount += 1
            }
        }
    }

    var visited = [[Bool]](repeating: [Bool](repeating: false, count: width), count: height)
    var components: [(fx: Int, fy: Int, mnx: Int, mny: Int, mxx: Int, mxy: Int, cnt: Int)] = []

    let dx = [-1, 0, 1, -1, 0, 1, -1, 1]
    let dy = [-1, -1, -1, 0, 0, 0, 1, 1]

    for y in 0..<height {
        for x in 0..<width {
            if ink[y][x] && !visited[y][x] {
                var queue: [(Int, Int)] = [(x, y)]
                visited[y][x] = true
                var cnt = 0
                var mnx = x, mxx = x, mny = y, mxy = y
                var head = 0
                while head < queue.count {
                    let (cx, cy) = queue[head]
                    head += 1
                    cnt += 1
                    if cx < mnx { mnx = cx }
                    if cx > mxx { mxx = cx }
                    if cy < mny { mny = cy }
                    if cy > mxy { mxy = cy }
                    for i in 0..<8 {
                        let nx = cx + dx[i]
                        let ny = cy + dy[i]
                        if nx >= 0 && nx < width && ny >= 0 && ny < height {
                            if ink[ny][nx] && !visited[ny][nx] {
                                visited[ny][nx] = true
                                queue.append((nx, ny))
                            }
                        }
                    }
                }
                components.append((fx: x, fy: y, mnx: mnx, mny: mny, mxx: mxx, mxy: mxy, cnt: cnt))
            }
        }
    }

    print("== \(name)")
    print("size \(width)x\(height) bpp \(bpp) header \(dibSize) \(bottomUp ? "bottom-up" : "top-down") ink \(inkCount)")
    print("components \(components.count)")
    for c in components {
        print("\(c.fx),\(c.fy) bbox \(c.mnx),\(c.mny)-\(c.mxx),\(c.mxy) pixels \(c.cnt)")
    }
}

