import Foundation

func readU16LE(_ d: [UInt8], _ o: Int) -> UInt16 {
    return UInt16(d[o]) | (UInt16(d[o+1]) << 8)
}

func readU32LE(_ d: [UInt8], _ o: Int) -> UInt32 {
    return UInt32(d[o]) | (UInt32(d[o+1]) << 8) | (UInt32(d[o+2]) << 16) | (UInt32(d[o+3]) << 24)
}

func readI32LE(_ d: [UInt8], _ o: Int) -> Int32 {
    return Int32(bitPattern: readU32LE(d, o))
}

func trailingZeros(_ x: UInt32) -> Int {
    if x == 0 { return 32 }
    var count = 0
    var v = x
    while v & 1 == 0 {
        count += 1
        v >>= 1
    }
    return count
}

func popcount32(_ x: UInt32) -> Int {
    var count = 0
    var v = x
    while v != 0 {
        count += Int(v & 1)
        v >>= 1
    }
    return count
}

func extractChannel(_ pixel: UInt32, mask: UInt32) -> Int {
    let s = trailingZeros(mask)
    let n = popcount32(mask)
    let v = (pixel & mask) >> UInt32(s)
    let m = UInt32((1 << n) - 1)
    return Int((v &* 255 + m / 2) / m)
}

func isInk(r: Int, g: Int, b: Int) -> Bool {
    return (299 * r + 587 * g + 114 * b) / 1000 < 128
}

func processFile(path: String, name: String) {
    guard let data = try? Data(contentsOf: URL(fileURLWithPath: path)) else { return }
    let bytes = [UInt8](data)
    let fileLen = bytes.count

    guard fileLen >= 14 else { return }
    guard bytes[0] == 0x42 && bytes[1] == 0x4D else { return }

    let bfOffBits = Int(readU32LE(bytes, 10))

    let dibOff = 14
    guard fileLen >= dibOff + 4 else { return }
    let dibSize = Int(readU32LE(bytes, dibOff))

    guard dibSize == 40 || dibSize == 108 || dibSize == 124 else { return }
    guard fileLen >= dibOff + 40 else { return }

    let width = Int(readI32LE(bytes, dibOff + 4))
    let heightRaw = Int(readI32LE(bytes, dibOff + 8))
    let height = abs(heightRaw)
    let bottomUp = heightRaw > 0
    let bpp = Int(readU16LE(bytes, dibOff + 14))
