    case 32: rowBytes = width * 4
    default: return
    }

    var ink = [[Bool]](repeating: [Bool](repeating: false, count: width), count: height)
    var inkCount = 0

    for storedRow in 0..<height {
        let y: Int
        if bottomUp {
