                    if idx < colorTable.count { (r, g, b) = colorTable[idx] }
                }
            case 4:
                let byteIdx = x / 2
                let off = rowOff + byteIdx
                if off < fileLen {
                    let idx: Int
                    if x % 2 == 0 { idx = Int(bytes[off] >> 4) & 0xF }
                    else { idx = Int(bytes[off]) & 0xF }
                    if idx < colorTable.count { (r, g, b) = colorTable[idx] }
                }
            case 8:
                let off = rowOff + x
                if off < fileLen {
                    let idx = Int(bytes[off])
                    if idx < colorTable.count { (r, g, b) = colorTable[idx] }
                }
            case 24:
                let off = rowOff + x * 3
                if off + 2 < fileLen {
                    b = Int(bytes[off]); g = Int(bytes[off+1]); r = Int(bytes[off+2])
                }
            case 32:
                if compression == 0 {
                    let off = rowOff + x * 4
                    if off + 2 < fileLen {
                        b = Int(bytes[off]); g = Int(bytes[off+1]); r = Int(bytes[off+2])
                    }
                } else {
                    let off = rowOff + x * 4
                    if off + 3 < fileLen {
                        let pixel = readU32LE(bytes, off)
                        r = extractChannel(pixel, mask: redMask)
                        g = extractChannel(pixel, mask: greenMask)
                        b = extractChannel(pixel, mask: blueMask)
                    }
                }
            default: break
            }

            if isInk(r: r, g: g, b: b) {
                ink[y][x] = true
                inkCount += 1
            }
        }
    }

    var visited = [[Bool]](repeating: [Bool](repeating: false, count: width), count: height)
    var components: [(fx: Int, fy: Int, mnx: Int, mny: Int, mxx: Int, mxy: Int, cnt: Int)] = []

    let dx = [-1, 0, 1, -1, 1, -1, 0, 1]
    let dy = [-1, -1, -1, 0, 0, 1, 1, 1]

    for y in 0..<height {
        for x in 0..<width {
            if ink[y][x] && !visited[y][x] {
