static int type_to_num(const char *t) {
    if (strcmp(t, "A") == 0) return 1;
    if (strcmp(t, "AAAA") == 0) return 28;
    if (strcmp(t, "MX") == 0) return 15;
    if (strcmp(t, "TXT") == 0) return 16;
    if (strcmp(t, "CNAME") == 0) return 5;
    return -1;
}

static const char *num_to_type(int t) {
    switch (t) {
        case 1: return "A";
        case 28: return "AAAA";
        case 15: return "MX";
        case 16: return "TXT";
        case 5: return "CNAME";
        default: return NULL;
    }
}

static void print_rcode(int rcode) {
    switch (rcode) {
        case 0: printf("NOERROR"); break;
        case 1: printf("FORMERR"); break;
        case 2: printf("SERVFAIL"); break;
        case 3: printf("NXDOMAIN"); break;
        case 4: printf("NOTIMP"); break;
        case 5: printf("REFUSED"); break;
        default: printf("RCODE%d", rcode); break;
    }
}

static int dns_read_name(const uint8_t *msg, int msglen, int pos,
                         char *out, int outsize, int *new_pos) {
    int out_len = 0;
    int first = 1;
    int cur = pos;
    int stream_end = -1;
    int loops = 0;

    while (loops++ < 128) {
        if (cur < 0 || cur >= msglen) {
            out[0] = '\0';
            *new_pos = pos;
            return -1;
        }
        uint8_t b = msg[cur];
        if (b == 0) {
            if (stream_end == -1) stream_end = cur + 1;
            break;
        }
        if ((b & 0xC0) == 0xC0) {
            if (cur + 1 >= msglen) {
                out[0] = '\0';
                *new_pos = pos;
                return -1;
            }
            int ptr = ((b & 0x3F) << 8) | msg[cur + 1];
            if (stream_end == -1) stream_end = cur + 2;
            cur = ptr;
            continue;
        }
        cur++;
        if (cur + b > msglen) {
            out[0] = '\0';
            *new_pos = pos;
            return -1;
        }
        if (!first) {
            if (out_len < outsize - 1) out[out_len++] = '.';
        }
        first = 0;
        for (int i = 0; i < b; i++) {
            if (out_len < outsize - 1)
                out[out_len++] = tolower((unsigned char)msg[cur + i]);
        }
        cur += b;
    }
    out[out_len] = '\0';
    *new_pos = (stream_end == -1) ? cur : stream_end;
    return 0;
}

static void print_name(const char *name) {
    if (name[0] == '\0') printf(".");
    else printf("%s", name);
}

static void print_aaaa(const uint8_t *addr) {
    uint16_t groups[8];
    for (int i = 0; i < 8; i++)
        groups[i] = (addr[i * 2] << 8) | addr[i * 2 + 1];

    int best_start = -1, best_len = 0;
    for (int i = 0; i < 8;) {
        if (groups[i] == 0) {
            int j = i;
            while (j < 8 && groups[j] == 0) j++;
            if (j - i >= 2 && j - i > best_len) {
                best_start = i;
                best_len = j - i;
            }
            i = j;
        } else {
            i++;
        }
    }

    int started = 0;
    for (int i = 0; i < 8;) {
        if (i == best_start) {
            if (!started) printf(":");
            printf(":");
            started = 1;
            i += best_len;
        } else {
            if (started) printf(":");
            printf("%x", groups[i]);
            started = 1;
            i++;
        }
    }
}

static void print_txt(const uint8_t *rdata, int rdlen) {
    int pos = 0;
    int first = 1;
    while (pos < rdlen) {
        if (!first) printf(" ");
        first = 0;
        int slen = rdata[pos++];
        printf("\"");
        for (int i = 0; i < slen && pos < rdlen; i++, pos++) {
            uint8_t c = rdata[pos];
            if (c == '"') printf("\\\"");
            else if (c == '\\') printf("\\\\");
            else if (c >= 0x20 && c <= 0x7E) putchar(c);
            else printf("\\%03d", c);
        }
        printf("\"");
    }
}

static int build_query(const char *name, int qtype, uint16_t id, uint8_t *buf) {
    int pos = 0;
    buf[pos++] = (id >> 8) & 0xFF;
    buf[pos++] = id & 0xFF;
    buf[pos++] = 0x01; buf[pos++] = 0x00;
    buf[pos++] = 0x00; buf[pos++] = 0x01;
    buf[pos++] = 0x00; buf[pos++] = 0x00;
    buf[pos++] = 0x00; buf[pos++] = 0x00;
    buf[pos++] = 0x00; buf[pos++] = 0x00;

    char nc[MAX_NAME];
    strncpy(nc, name, sizeof(nc) - 1);
    nc[sizeof(nc) - 1] = '\0';
    int nlen = strlen(nc);
    if (nlen > 0 && nc[nlen - 1] == '.') nc[--nlen] = '\0';

    char *p = nc;
    while (*p) {
        char *dot = strchr(p, '.');
        int ll;
        if (dot) ll = (int)(dot - p);
        else ll = (int)strlen(p);
        if (ll > 0) {
            buf[pos++] = (uint8_t)ll;
            memcpy(buf + pos, p, ll);
            pos += ll;
        }
        if (dot) p = dot + 1;
        else break;
    }
    buf[pos++] = 0;

    buf[pos++] = (qtype >> 8) & 0xFF;
    buf[pos++] = qtype & 0xFF;
    buf[pos++] = 0x00;
    buf[pos++] = 0x01;
    return pos;
}

static int read_exact(int fd, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        int n = (int)read(fd, buf + total, len - total);
        if (n <= 0) return -1;
        total += n;
    }
    return 0;
}

static void write_exact(int fd, const uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        int n = (int)write(fd, buf + total, len - total);
        if (n <= 0) break;
        total += n;
    }
}

static void parse_and_print(const uint8_t *msg, int msglen,
                            const char *qname, const char *qtype_str) {
    if (msglen < 12) return;
    uint16_t flags = (msg[2] << 8) | msg[3];
    int rcode = flags & 0x0F;
    uint16_t qdcount = (msg[4] << 8) | msg[5];
    uint16_t ancount = (msg[6] << 8) | msg[7];

    printf("%s %s ", qname, qtype_str);
    print_rcode(rcode);
    printf("\n");

    int pos = 12;
    for (int i = 0; i < qdcount; i++) {
        char tmp[MAX_NAME];
        int np;
        dns_read_name(msg, msglen, pos, tmp, sizeof(tmp), &np);
        pos = np + 4;
    }

    for (int i = 0; i < ancount; i++) {
        char owner[MAX_NAME];
