    }
}

static void normalize_query_name(const char *in, char *out, int outsize) {
    int len = (int)strlen(in);
    if (len > 0 && in[len - 1] == '.') len--;
    if (len >= outsize) len = outsize - 1;
    for (int i = 0; i < len; i++)
        out[i] = tolower((unsigned char)in[i]);
    out[len] = '\0';
    if (len == 0) {
        out[0] = '.';
        out[1] = '\0';
