import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';

const dir = process.argv[2];
const config = JSON.parse(fs.readFileSync(path.join(dir, 'config.json'), 'utf-8'));
const tokensRaw = fs.readFileSync(path.join(dir, 'tokens.txt'), 'utf-8');

function trimSpacesTabs(s: string): string {
    let start = 0, end = s.length;
    while (start < end && (s[start] === ' ' || s[start] === '\t')) start++;
    while (end > start && (s[end - 1] === ' ' || s[end - 1] === '\t')) end--;
    return s.slice(start, end);
}

const lines = tokensRaw.split('\n');
const tokens: string[] = [];
for (const line of lines) {
    const trimmed = trimSpacesTabs(line);
    if (trimmed !== '') {
        tokens.push(trimmed);
    }
}

function isValidBase64url(s: string): boolean {
    if (s.length === 0) return false;
    if (s.length % 4 === 1) return false;
    for (let i = 0; i < s.length; i++) {
        const c = s.charCodeAt(i);
        if (!((c >= 65 && c <= 90) || (c >= 97 && c <= 122) || (c >= 48 && c <= 57) || c === 45 || c === 95)) {
            return false;
        }
    }
    return true;
}

function base64urlDecode(s: string): Buffer {
    let b64 = s.replace(/-/g, '+').replace(/_/g, '/');
    const pad = (4 - (b64.length % 4)) % 4;
    b64 += '='.repeat(pad);
    return Buffer.from(b64, 'base64');
}

function isJsonObject(s: string): boolean {
    try {
        const obj = JSON.parse(s);
        return obj !== null && typeof obj === 'object' && !Array.isArray(obj);
    } catch {
        return false;
    }
}

function checkToken(token: string): string {
    const segments = token.split('.');
    if (segments.length !== 3) return 'MALFORMED';

    for (const seg of segments) {
        if (seg === '') return 'MALFORMED';
        if (!isValidBase64url(seg)) return 'MALFORMED';
    }

    let headerStr: string, payloadStr: string;
    try {
        headerStr = base64urlDecode(segments[0]).toString('utf-8');
        payloadStr = base64urlDecode(segments[1]).toString('utf-8');
    } catch {
        return 'MALFORMED';
    }

    if (!isJsonObject(headerStr)) return 'MALFORMED';
    if (!isJsonObject(payloadStr)) return 'MALFORMED';

    let header: any, payload: any;
    try {
        header = JSON.parse(headerStr);
        payload = JSON.parse(payloadStr);
    } catch {
        return 'MALFORMED';
    }

    // Rule 2: UNSUPPORTED_ALG
    if (typeof header.alg !== 'string' || !['HS256', 'HS384', 'HS512'].includes(header.alg)) {
        return 'UNSUPPORTED_ALG';
    }

    // Rule 3: UNKNOWN_KEY
    if (typeof header.kid !== 'string') return 'UNKNOWN_KEY';
    const key = (config.keys as any[]).find((k: any) => k.kid === header.kid);
    if (!key) return 'UNKNOWN_KEY';

    // Rule 4: ALG_MISMATCH
    if (key.alg !== header.alg) return 'ALG_MISMATCH';

    // Rule 5: BAD_SIGNATURE
    const signingInput = segments[0] + '.' + segments[1];
    const secret = base64urlDecode(key.k);
    const hashName = header.alg.replace('HS', 'sha');
    const expectedSig = crypto.createHmac(hashName, secret).update(signingInput, 'ascii').digest();
    const actualSig = base64urlDecode(segments[2]);
    if (actualSig.length !== expectedSig.length) return 'BAD_SIGNATURE';
    if (!crypto.timingSafeEqual(expectedSig, actualSig)) return 'BAD_SIGNATURE';

    // Rule 6: EXPIRED
    if (payload.exp !== undefined) {
        if (config.now >= payload.exp + config.leeway) return 'EXPIRED';
    }

    // Rule 7: NOT_YET_VALID
    if (payload.nbf !== undefined) {
        if (config.now + config.leeway < payload.nbf) return 'NOT_YET_VALID';
    }

    // Rule 8: BAD_ISSUER
    if (payload.iss !== config.issuer) return 'BAD_ISSUER';

    // Rule 9: BAD_AUDIENCE
    const aud = payload.aud;
    if (aud === undefined) return 'BAD_AUDIENCE';
    if (typeof aud === 'string') {
        if (aud !== config.audience) return 'BAD_AUDIENCE';
    } else if (Array.isArray(aud)) {
        if (!aud.includes(config.audience)) return 'BAD_AUDIENCE';
    } else {
        return 'BAD_AUDIENCE';
    }

    // VALID
    const sub = payload.sub;
    const scope = payload.scope;
    let scopes = '';
    if (typeof scope === 'string' && scope !== '') {
        const parts = scope.split(' ').filter((s: string) => s !== '');
        const unique = [...new Set(parts)];
        unique.sort();
        scopes = unique.join(',');
    }

    return `VALID sub=${sub} scope=${scopes}`;
}

