#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

/* ===== JSON Value ===== */
typedef enum { JT_NULL, JT_BOOL, JT_NUM, JT_STR, JT_ARR, JT_OBJ } JType;
typedef struct JVal {
    JType type;
    union {
        int bval;
        double nval;
        char *sval;
        struct { struct JVal **items; int len, cap; } arr;
        struct { char **keys; struct JVal **vals; int len, cap; } obj;
    };
} JVal;

/* ===== Parser ===== */
typedef struct { const char *src; int pos, len; } P;

static JVal *jv_new(JType t) {
    JVal *v = calloc(1, sizeof(JVal));
    v->type = t;
    return v;
}
static void arr_push(JVal *a, JVal *item) {
    if (a->arr.len >= a->arr.cap) {
        a->arr.cap = a->arr.cap ? a->arr.cap * 2 : 4;
        a->arr.items = realloc(a->arr.items, a->arr.cap * sizeof(JVal*));
    }
    a->arr.items[a->arr.len++] = item;
}
static void obj_push(JVal *o, char *key, JVal *val) {
    if (o->obj.len >= o->obj.cap) {
        o->obj.cap = o->obj.cap ? o->obj.cap * 2 : 4;
        o->obj.keys = realloc(o->obj.keys, o->obj.cap * sizeof(char*));
        o->obj.vals = realloc(o->obj.vals, o->obj.cap * sizeof(JVal*));
    }
    o->obj.keys[o->obj.len] = key;
    o->obj.vals[o->obj.len] = val;
    o->obj.len++;
}

static void skip_ws(P *p) {
    while (p->pos < p->len) {
        char c = p->src[p->pos];
        if (c==' '||c=='\t'||c=='\n'||c=='\r') p->pos++;
        else break;
    }
}

static void encode_cp(int cp, char *buf, int *n) {
    if (cp < 0x80) { buf[0]=cp; *n=1; }
    else if (cp < 0x800) { buf[0]=0xC0|(cp>>6); buf[1]=0x80|(cp&0x3F); *n=2; }
    else if (cp < 0x10000) { buf[0]=0xE0|(cp>>12); buf[1]=0x80|((cp>>6)&0x3F); buf[2]=0x80|(cp&0x3F); *n=3; }
    else { buf[0]=0xF0|(cp>>18); buf[1]=0x80|((cp>>12)&0x3F); buf[2]=0x80|((cp>>6)&0x3F); buf[3]=0x80|(cp&0x3F); *n=4; }
}

static int parse_hex4(P *p) {
    int v = 0;
    for (int i = 0; i < 4; i++) {
        char c = p->src[p->pos++];
        if (c>='0'&&c<='9') v = v*16+(c-'0');
        else if (c>='a'&&c<='f') v = v*16+(c-'a'+10);
        else v = v*16+(c-'A'+10);
    }
    return v;
}

static char *parse_str(P *p) {
    p->pos++; /* skip " */
    int cap = 64, len = 0;
    char *buf = malloc(cap);
    while (p->src[p->pos] != '"') {
        if (p->pos >= p->len) break;
        char c = p->src[p->pos];
        if (c == '\\') {
            p->pos++;
            c = p->src[p->pos++];
            char tmp[4]; int n = 0;
            switch (c) {
                case '"': tmp[0]='"'; n=1; break;
                case '\\': tmp[0]='\\'; n=1; break;
                case '/': tmp[0]='/'; n=1; break;
                case 'b': tmp[0]='\b'; n=1; break;
                case 'f': tmp[0]='\f'; n=1; break;
                case 'n': tmp[0]='\n'; n=1; break;
                case 'r': tmp[0]='\r'; n=1; break;
                case 't': tmp[0]='\t'; n=1; break;
                case 'u': {
                    int cp = parse_hex4(p);
                    if (cp >= 0xD800 && cp <= 0xDBFF) {
                        /* high surrogate, expect \uXXXX low */
                        if (p->src[p->pos]=='\\' && p->src[p->pos+1]=='u') {
                            p->pos += 2;
                            int lo = parse_hex4(p);
                            cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                        }
                    }
                    encode_cp(cp, tmp, &n);
                    break;
                }
                default: tmp[0]=c; n=1; break;
            }
            if (len + n >= cap) { cap = (len+n)*2; buf = realloc(buf, cap); }
            memcpy(buf+len, tmp, n); len += n;
        } else {
            if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
            buf[len++] = c;
            p->pos++;
        }
    }
    p->pos++; /* skip " */
    buf[len] = 0;
    return buf;
}

static JVal *parse_value(P *p) {
    skip_ws(p);
    char c = p->src[p->pos];
    if (c == '"') {
        JVal *v = jv_new(JT_STR);
        v->sval = parse_str(p);
        return v;
    }
    if (c == '{') {
        p->pos++;
        JVal *o = jv_new(JT_OBJ);
        skip_ws(p);
        if (p->src[p->pos] == '}') { p->pos++; return o; }
        while (1) {
            skip_ws(p);
            char *key = parse_str(p);
            skip_ws(p);
            p->pos++; /* : */
            JVal *val = parse_value(p);
            obj_push(o, key, val);
            skip_ws(p);
            if (p->src[p->pos] == ',') { p->pos++; continue; }
            if (p->src[p->pos] == '}') { p->pos++; break; }
            break;
        }
        return o;
    }
    if (c == '[') {
        p->pos++;
        JVal *a = jv_new(JT_ARR);
        skip_ws(p);
        if (p->src[p->pos] == ']') { p->pos++; return a; }
        while (1) {
            JVal *item = parse_value(p);
            arr_push(a, item);
            skip_ws(p);
            if (p->src[p->pos] == ',') { p->pos++; continue; }
            if (p->src[p->pos] == ']') { p->pos++; break; }
            break;
        }
        return a;
    }
    if (c == 't') { p->pos += 4; JVal *v = jv_new(JT_BOOL); v->bval=1; return v; }
    if (c == 'f') { p->pos += 5; JVal *v = jv_new(JT_BOOL); v->bval=0; return v; }
    if (c == 'n') { p->pos += 4; return jv_new(JT_NULL); }
    /* number */
    char *end;
    double d = strtod(p->src + p->pos, &end);
    p->pos = (int)(end - p->src);
    JVal *v = jv_new(JT_NUM);
    v->nval = d;
    return v;
}

/* ===== Utilities ===== */
static JVal *obj_get(JVal *o, const char *key) {
    if (!o || o->type != JT_OBJ) return NULL;
    for (int i = 0; i < o->obj.len; i++)
        if (strcmp(o->obj.keys[i], key) == 0) return o->obj.vals[i];
    return NULL;
}

static int utf8_cp_count(const char *s) {
    int n = 0;
    while (*s) {
        if (((unsigned char)*s & 0xC0) != 0x80) n++;
        s++;
    }
    return n;
}

static int is_int(double d) {
    if (d != d) return 0; /* NaN */
    return d == floor(d);
}

/* Deep equality */
static int deep_eq(JVal *a, JVal *b) {
    if (a->type != b->type) return 0;
    switch (a->type) {
        case JT_NULL: return 1;
        case JT_BOOL: return a->bval == b->bval;
        case JT_NUM: return a->nval == b->nval;
        case JT_STR: return strcmp(a->sval, b->sval) == 0;
        case JT_ARR:
            if (a->arr.len != b->arr.len) return 0;
            for (int i = 0; i < a->arr.len; i++)
                if (!deep_eq(a->arr.items[i], b->arr.items[i])) return 0;
            return 1;
        case JT_OBJ:
            if (a->obj.len != b->obj.len) return 0;
            for (int i = 0; i < a->obj.len; i++) {
                JVal *bv = obj_get(b, a->obj.keys[i]);
                if (!bv) return 0;
                if (!deep_eq(a->obj.vals[i], bv)) return 0;
            }
            return 1;
    }
    return 0;
}

/* ===== JSON Pointer helpers ===== */
static char *encode_token(const char *raw) {
    int n = strlen(raw);
    char *out = malloc(n*2+1);
    int j = 0;
    for (int i = 0; i < n; i++) {
        if (raw[i]=='~') { out[j++]='~'; out[j++]='0'; }
        else if (raw[i]=='/') { out[j++]='~'; out[j++]='1'; }
        else out[j++] = raw[i];
    }
    out[j] = 0;
    return out;
}

static char *append_ptr(const char *base, const char *raw_token) {
    char *enc = encode_token(raw_token);
    int blen = strlen(base);
    int tlen = strlen(enc);
    char *out = malloc(blen + 1 + tlen + 1);
    memcpy(out, base, blen);
    out[blen] = '/';
    memcpy(out+blen+1, enc, tlen+1);
    free(enc);
    return out;
}

static char *append_ptr_raw(const char *base, const char *encoded_token) {
    int blen = strlen(base);
    int tlen = strlen(encoded_token);
    char *out = malloc(blen + 1 + tlen + 1);
    memcpy(out, base, blen);
    out[blen] = '/';
    memcpy(out+blen+1, encoded_token, tlen+1);
    return out;
}

static char *decode_ptr_token(const char *enc) {
    int n = strlen(enc);
    char *out = malloc(n+1);
    int j = 0;
    for (int i = 0; i < n; i++) {
        if (enc[i]=='~' && i+1 < n) {
            if (enc[i+1]=='0') { out[j++]='~'; i++; }
            else if (enc[i+1]=='1') { out[j++]='/'; i++; }
            else out[j++] = enc[i];
        } else out[j++] = enc[i];
    }
    out[j] = 0;
    return out;
}

/* ===== Error Set ===== */
typedef struct { char *il, *sl; } Err;
typedef struct { Err *a; int len, cap; } ESet;

static void es_init(ESet *e) { e->a=NULL; e->len=0; e->cap=0; }
static void es_add(ESet *e, const char *il, const char *sl) {
    if (e->len >= e->cap) { e->cap = e->cap?e->cap*2:16; e->a = realloc(e->a, e->cap*sizeof(Err)); }
    e->a[e->len].il = strdup(il);
    e->a[e->len].sl = strdup(sl);
    e->len++;
}
static void es_free(ESet *e) {
    for (int i = 0; i < e->len; i++) { free(e->a[i].il); free(e->a[i].sl); }
    free(e->a);
}
static int err_cmp(const void *a, const void *b) {
    const Err *ea = a, *eb = b;
    int c = strcmp(ea->il, eb->il);
    if (c) return c;
    return strcmp(ea->sl, eb->sl);
}
static void es_sort_dedup(ESet *e) {
    if (e->len == 0) return;
    qsort(e->a, e->len, sizeof(Err), err_cmp);
    int w = 1;
    for (int i = 1; i < e->len; i++) {
        if (strcmp(e->a[i].il, e->a[w-1].il) || strcmp(e->a[i].sl, e->a[w-1].sl)) {
            e->a[w++] = e->a[i];
        } else {
            free(e->a[i].il); free(e->a[i].sl);
        }
    }
    e->len = w;
}

/* ===== Validator ===== */
static JVal *g_root;

static int type_match(JVal *inst, const char *tname) {
    if (strcmp(tname,"null")==0) return inst->type==JT_NULL;
    if (strcmp(tname,"boolean")==0) return inst->type==JT_BOOL;
    if (strcmp(tname,"object")==0) return inst->type==JT_OBJ;
    if (strcmp(tname,"array")==0) return inst->type==JT_ARR;
    if (strcmp(tname,"number")==0) return inst->type==JT_NUM;
    if (strcmp(tname,"string")==0) return inst->type==JT_STR;
    if (strcmp(tname,"integer")==0) return inst->type==JT_NUM && is_int(inst->nval);
    return 0;
}

static int schema_accepts(JVal *schema, const char *sloc, JVal *inst, const char *iloc);
static void validate(JVal *schema, const char *sloc, JVal *inst, const char *iloc, ESet *errs);

static int schema_accepts(JVal *schema, const char *sloc, JVal *inst, const char *iloc) {
    ESet tmp; es_init(&tmp);
    validate(schema, sloc, inst, iloc, &tmp);
    int r = (tmp.len == 0);
    es_free(&tmp);
    return r;
}

static void validate(JVal *schema, const char *sloc, JVal *inst, const char *iloc, ESet *errs) {
    if (schema->type == JT_BOOL) {
        if (!schema->bval) es_add(errs, iloc, sloc);
        return;
    }
    if (schema->type != JT_OBJ) return;

    /* type */
    JVal *kw;
    kw = obj_get(schema, "type");
    if (kw) {
        int ok = 0;
        if (kw->type == JT_STR) {
            ok = type_match(inst, kw->sval);
        } else if (kw->type == JT_ARR) {
            for (int i = 0; i < kw->arr.len; i++) {
                if (kw->arr.items[i]->type == JT_STR && type_match(inst, kw->arr.items[i]->sval)) { ok=1; break; }
            }
        }
        if (!ok) { char *sl = append_ptr(sloc,"type"); es_add(errs, iloc, sl); free(sl); }
    }

    /* enum */
    kw = obj_get(schema, "enum");
    if (kw && kw->type == JT_ARR) {
        int ok = 0;
        for (int i = 0; i < kw->arr.len; i++)
            if (deep_eq(inst, kw->arr.items[i])) { ok=1; break; }
        if (!ok) { char *sl = append_ptr(sloc,"enum"); es_add(errs, iloc, sl); free(sl); }
    }

    /* const */
    kw = obj_get(schema, "const");
    if (kw) {
        if (!deep_eq(inst, kw)) { char *sl = append_ptr(sloc,"const"); es_add(errs, iloc, sl); free(sl); }
    }

    /* numeric keywords */
    if (inst->type == JT_NUM) {
        kw = obj_get(schema, "minimum");
        if (kw && kw->type==JT_NUM && !(inst->nval >= kw->nval)) { char *sl=append_ptr(sloc,"minimum"); es_add(errs,iloc,sl); free(sl); }
        kw = obj_get(schema, "maximum");
        if (kw && kw->type==JT_NUM && !(inst->nval <= kw->nval)) { char *sl=append_ptr(sloc,"maximum"); es_add(errs,iloc,sl); free(sl); }
        kw = obj_get(schema, "exclusiveMinimum");
        if (kw && kw->type==JT_NUM && !(inst->nval > kw->nval)) { char *sl=append_ptr(sloc,"exclusiveMinimum"); es_add(errs,iloc,sl); free(sl); }
        kw = obj_get(schema, "exclusiveMaximum");
        if (kw && kw->type==JT_NUM && !(inst->nval < kw->nval)) { char *sl=append_ptr(sloc,"exclusiveMaximum"); es_add(errs,iloc,sl); free(sl); }
    }

    /* string keywords */
    if (inst->type == JT_STR) {
        int slen = utf8_cp_count(inst->sval);
        kw = obj_get(schema, "minLength");
        if (kw && kw->type==JT_NUM && !(slen >= (int)kw->nval)) { char *sl=append_ptr(sloc,"minLength"); es_add(errs,iloc,sl); free(sl); }
        kw = obj_get(schema, "maxLength");
        if (kw && kw->type==JT_NUM && !(slen <= (int)kw->nval)) { char *sl=append_ptr(sloc,"maxLength"); es_add(errs,iloc,sl); free(sl); }
    }

    /* array keywords */
    if (inst->type == JT_ARR) {
        kw = obj_get(schema, "minItems");
        if (kw && kw->type==JT_NUM && !(inst->arr.len >= (int)kw->nval)) { char *sl=append_ptr(sloc,"minItems"); es_add(errs,iloc,sl); free(sl); }
        kw = obj_get(schema, "maxItems");
        if (kw && kw->type==JT_NUM && !(inst->arr.len <= (int)kw->nval)) { char *sl=append_ptr(sloc,"maxItems"); es_add(errs,iloc,sl); free(sl); }
        kw = obj_get(schema, "uniqueItems");
        if (kw && kw->type==JT_BOOL && kw->bval) {
            int dup = 0;
            for (int i = 0; i < inst->arr.len && !dup; i++)
                for (int j = i+1; j < inst->arr.len; j++)
                    if (deep_eq(inst->arr.items[i], inst->arr.items[j])) { dup=1; break; }
            if (dup) { char *sl=append_ptr(sloc,"uniqueItems"); es_add(errs,iloc,sl); free(sl); }
        }
        /* prefixItems */
        kw = obj_get(schema, "prefixItems");
        if (kw && kw->type == JT_ARR) {
            int n = kw->arr.len < inst->arr.len ? kw->arr.len : inst->arr.len;
            for (int i = 0; i < n; i++) {
                char idx[32]; sprintf(idx,"%d",i);
                char *niloc = append_ptr(iloc, idx);
                char *nsl = append_ptr(append_ptr(sloc,"prefixItems"), idx);
                validate(kw->arr.items[i], nsl, inst->arr.items[i], niloc, errs);
                free(niloc); free(nsl);
            }
        }
        /* items */
        kw = obj_get(schema, "items");
        if (kw) {
            int start = 0;
            JVal *pi = obj_get(schema, "prefixItems");
            if (pi && pi->type == JT_ARR) start = pi->arr.len;
            for (int i = start; i < inst->arr.len; i++) {
                char idx[32]; sprintf(idx,"%d",i);
                char *niloc = append_ptr(iloc, idx);
                char *nsl = append_ptr(sloc, "items");
                validate(kw, nsl, inst->arr.items[i], niloc, errs);
                free(niloc); free(nsl);
            }
        }
    }

    /* object keywords */
    if (inst->type == JT_OBJ) {
        kw = obj_get(schema, "minProperties");
        if (kw && kw->type==JT_NUM && !(inst->obj.len >= (int)kw->nval)) { char *sl=append_ptr(sloc,"minProperties"); es_add(errs,iloc,sl); free(sl); }
        kw = obj_get(schema, "maxProperties");
        if (kw && kw->type==JT_NUM && !(inst->obj.len <= (int)kw->nval)) { char *sl=append_ptr(sloc,"maxProperties"); es_add(errs,iloc,sl); free(sl); }
        /* required */
        kw = obj_get(schema, "required");
        if (kw && kw->type == JT_ARR) {
            for (int i = 0; i < kw->arr.len; i++) {
                if (kw->arr.items[i]->type != JT_STR) continue;
                if (!obj_get(inst, kw->arr.items[i]->sval)) {
                    char idx[32]; sprintf(idx,"%d",i);
                    char *sl = append_ptr(append_ptr(sloc,"required"), idx);
                    es_add(errs, iloc, sl);
                    free(sl);
                }
            }
        }
        /* properties */
        JVal *props = obj_get(schema, "properties");
        if (props && props->type == JT_OBJ) {
            for (int i = 0; i < props->obj.len; i++) {
                JVal *member = obj_get(inst, props->obj.keys[i]);
                if (member) {
                    char *niloc = append_ptr(iloc, props->obj.keys[i]);
                    char *nsl = append_ptr(append_ptr(sloc,"properties"), props->obj.keys[i]);
                    validate(props->obj.vals[i], nsl, member, niloc, errs);
                    free(niloc); free(nsl);
                }
            }
        }
        /* additionalProperties */
        kw = obj_get(schema, "additionalProperties");
        if (kw) {
            for (int i = 0; i < inst->obj.len; i++) {
                int in_props = 0;
                if (props && props->type == JT_OBJ && obj_get(props, inst->obj.keys[i])) in_props = 1;
                if (!in_props) {
                    char *niloc = append_ptr(iloc, inst->obj.keys[i]);
                    char *nsl = append_ptr(sloc, "additionalProperties");
                    validate(kw, nsl, inst->obj.vals[i], niloc, errs);
                    free(niloc); free(nsl);
                }
            }
        }
    }

    /* $ref */
    kw = obj_get(schema, "$ref");
    if (kw && kw->type == JT_STR) {
        JVal *target = NULL;
        char *tsloc = NULL;
        if (strcmp(kw->sval, "#") == 0) {
            target = g_root;
            tsloc = strdup("#");
        } else if (strncmp(kw->sval, "#/$defs/", 8) == 0) {
            const char *name_enc = kw->sval + 8;
            char *name = decode_ptr_token(name_enc);
            JVal *defs = obj_get(g_root, "$defs");
            if (defs) target = obj_get(defs, name);
            free(name);
            tsloc = strdup(kw->sval);
        }
        if (target) validate(target, tsloc, inst, iloc, errs);
        free(tsloc);
    }

    /* allOf */
    kw = obj_get(schema, "allOf");
    if (kw && kw->type == JT_ARR) {
        for (int i = 0; i < kw->arr.len; i++) {
            char idx[32]; sprintf(idx,"%d",i);
            char *nsl = append_ptr(append_ptr(sloc,"allOf"), idx);
            validate(kw->arr.items[i], nsl, inst, iloc, errs);
            free(nsl);
        }
    }

    /* anyOf */
    kw = obj_get(schema, "anyOf");
    if (kw && kw->type == JT_ARR) {
        int ok = 0;
        for (int i = 0; i < kw->arr.len; i++) {
            char idx[32]; sprintf(idx,"%d",i);
            char *nsl = append_ptr(append_ptr(sloc,"anyOf"), idx);
            if (schema_accepts(kw->arr.items[i], nsl, inst, iloc)) { ok=1; free(nsl); break; }
            free(nsl);
        }
        if (!ok) { char *sl=append_ptr(sloc,"anyOf"); es_add(errs,iloc,sl); free(sl); }
    }

    /* oneOf */
    kw = obj_get(schema, "oneOf");
    if (kw && kw->type == JT_ARR) {
        int cnt = 0;
        for (int i = 0; i < kw->arr.len; i++) {
            char idx[32]; sprintf(idx,"%d",i);
            char *nsl = append_ptr(append_ptr(sloc,"oneOf"), idx);
            if (schema_accepts(kw->arr.items[i], nsl, inst, iloc)) cnt++;
            free(nsl);
        }
        if (cnt != 1) { char *sl=append_ptr(sloc,"oneOf"); es_add(errs,iloc,sl); free(sl); }
    }

    /* not */
    kw = obj_get(schema, "not");
    if (kw) {
        char *nsl = append_ptr(sloc, "not");
        if (schema_accepts(kw, nsl, inst, iloc)) {
            es_add(errs, iloc, nsl);
        }
        free(nsl);
    }

    /* if/then/else */
    kw = obj_get(schema, "if");
    if (kw) {
        char *ifsl = append_ptr(sloc, "if");
        int ifok = schema_accepts(kw, ifsl, inst, iloc);
        free(ifsl);
        if (ifok) {
            JVal *then_kw = obj_get(schema, "then");
            if (then_kw) {
                char *nsl = append_ptr(sloc, "then");
                validate(then_kw, nsl, inst, iloc, errs);
                free(nsl);
            }
        } else {
            JVal *else_kw = obj_get(schema, "else");
            if (else_kw) {
                char *nsl = append_ptr(sloc, "else");
                validate(else_kw, nsl, inst, iloc, errs);
                free(nsl);
            }
        }
    }
}

/* ===== Main ===== */
static char *read_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc(sz + 1);
    fread(buf, 1, sz, f);
    buf[sz] = 0;
    fclose(f);
    return buf;
}

int main(int argc, char **argv) {
    if (argc < 2) return 1;
    char dir[4096];
    strncpy(dir, argv[1], sizeof(dir)-1);
    dir[sizeof(dir)-1] = 0;

    char spath[4200], ipath[4200];
    snprintf(spath, sizeof(spath), "%s/schema.json", dir);
    snprintf(ipath, sizeof(ipath), "%s/instances.json", dir);

    char *sbuf = read_file(spath);
    char *ibuf = read_file(ipath);

    P ps = {sbuf, 0, (int)strlen(sbuf)};
    JVal *schema = parse_value(&ps);
    g_root = schema;

    P pi = {ibuf, 0, (int)strlen(ibuf)};
    JVal *instances = parse_value(&pi);

    int nvalid = 0, ninvalid = 0;
    int ninst = instances->arr.len;
    for (int i = 0; i < ninst; i++) {
        ESet errs; es_init(&errs);
        validate(schema, "#", instances->arr.items[i], "#", &errs);
        es_sort_dedup(&errs);
        if (errs.len == 0) {
            printf("%d: valid\n", i);
            nvalid++;
        } else {
            printf("%d: invalid (%d)\n", i, errs.len);
            for (int j = 0; j < errs.len; j++)
                printf("  %s %s\n", errs.a[j].il, errs.a[j].sl);
            ninvalid++;
        }
        es_free(&errs);
    }
    printf("valid=%d invalid=%d\n", nvalid, ninvalid);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdint.h>

#define MAXL 30
#define B 1000000000U
#define MAX_CURR 1000
#define MAX_ACCT 10000
#define MAX_LINE 100000
#define MAX_REJ 10000

/* ============ BigInt (unsigned, base 10^9) ============ */
typedef struct { uint32_t d[MAXL]; int n; } BI;

static void bi_zero(BI *a){ a->n=1; a->d[0]=0; }
static void bi_copy(BI *dst, const BI *src){ dst->n=src->n; memcpy(dst->d,src->d,src->n*sizeof(uint32_t)); }
static int bi_is_zero(const BI *a){ return a->n==1 && a->d[0]==0; }

static void bi_norm(BI *a){ while(a->n>1 && a->d[a->n-1]==0) a->n--; }

static int bi_cmp(const BI *a, const BI *b){
    if(a->n!=b->n) return a->n>b->n?1:-1;
    for(int i=a->n-1;i>=0;i--) if(a->d[i]!=b->d[i]) return a->d[i]>b->d[i]?1:-1;
    return 0;
}

static void bi_add(BI *r, const BI *a, const BI *b){
    uint64_t carry=0; int n=a->n>b->n?a->n:b->n;
    for(int i=0;i<n;i++){
        uint64_t s=(i<a->n?a->d[i]:0)+(i<b->n?b->d[i]:0)+carry;
        r->d[i]=(uint32_t)(s%B); carry=s/B;
    }
    if(carry) r->d[n++]=(uint32_t)carry;
    r->n=n; bi_norm(r);
}

static void bi_sub(BI *r, const BI *a, const BI *b){ /* a>=b */
    uint64_t borrow=0; int n=a->n;
    for(int i=0;i<n;i++){
        uint64_t bv=(i<b->n?b->d[i]:0)+borrow;
        if((uint64_t)a->d[i]>=bv){ r->d[i]=(uint32_t)(a->d[i]-bv); borrow=0; }
        else { r->d[i]=(uint32_t)((uint64_t)a->d[i]+B-bv); borrow=1; }
    }
    r->n=n; bi_norm(r);
}

static void bi_add_small(BI *a, uint32_t v){
    uint64_t carry=v;
    for(int i=0;i<a->n&&carry;i++){
        uint64_t s=(uint64_t)a->d[i]+carry;
        a->d[i]=(uint32_t)(s%B); carry=s/B;
    }
    if(carry&&a->n<MAXL){ a->d[a->n++]=(uint32_t)carry; }
}

static void bi_mul(BI *r, const BI *a, const BI *b){
    if(bi_is_zero(a)||bi_is_zero(b)){ bi_zero(r); return; }
    memset(r->d,0,(a->n+b->n)*sizeof(uint32_t));
    for(int i=0;i<a->n;i++){
        uint64_t carry=0;
        for(int j=0;j<b->n;j++){
            uint64_t p=(uint64_t)a->d[i]*b->d[j]+r->d[i+j]+carry;
            r->d[i+j]=(uint32_t)(p%B); carry=p/B;
        }
        if(carry) r->d[i+b->n]+=(uint32_t)carry;
    }
    r->n=a->n+b->n; bi_norm(r);
}

static void bi_mul_small(BI *r, const BI *a, uint32_t m){
    if(m==0||bi_is_zero(a)){ bi_zero(r); return; }
    uint64_t carry=0;
    for(int i=0;i<a->n;i++){
        uint64_t p=(uint64_t)a->d[i]*m+carry;
        r->d[i]=(uint32_t)(p%B); carry=p/B;
    }
    r->n=a->n;
    if(carry){ r->d[r->n++]=(uint32_t)carry; }
    bi_norm(r);
}

static uint32_t bi_div_small(BI *a, uint32_t d){
    uint64_t rem=0;
    for(int i=a->n-1;i>=0;i--){
        uint64_t cur=rem*B+a->d[i];
        a->d[i]=(uint32_t)(cur/d); rem=cur%d;
    }
    bi_norm(a); return (uint32_t)rem;
}

static void bi_divmod(BI *q, BI *r, const BI *a, const BI *b){
    if(bi_cmp(a,b)<0){ bi_zero(q); bi_copy(r,a); return; }
    bi_zero(r); bi_zero(q); q->n=a->n;
    for(int i=a->n-1;i>=0;i--){
        /* r = r*B + a->d[i] */
        if(r->n<MAXL){ memmove(r->d+1,r->d,r->n*sizeof(uint32_t)); r->n++; }
        r->d[0]=a->d[i];
        bi_norm(r);
        uint32_t qd=0;
        if(bi_cmp(r,b)>=0){
            if(r->n>b->n){
                uint64_t top2=(uint64_t)r->d[r->n-1]*B+(r->n>=2?r->d[r->n-2]:0);
                qd=(uint32_t)(top2/b->d[b->n-1]);
                if(qd>=B) qd=B-1;
            } else {
                qd=r->d[r->n-1]/b->d[b->n-1];
            }
            BI tmp; bi_mul_small(&tmp,b,qd);
            if(bi_cmp(r,&tmp)>0){ /* ok */ }
            else if(bi_cmp(r,&tmp)==0){ /* ok */ }
            else { qd--; bi_mul_small(&tmp,b,qd); }
            bi_sub(r,r,&tmp);
            /* adjust up if needed */
            while(bi_cmp(r,b)>=0){ bi_sub(r,r,b); qd++; }
        }
        q->d[i]=qd;
    }
    while(q->n>1&&q->d[q->n-1]==0) q->n--;
    bi_norm(r);
}

static void bi_pow10(BI *r, int e){
    bi_zero(r); r->d[0]=1; r->n=1;
    for(int i=0;i<e;i++) bi_mul_small(r,r,10);
}

static void bi_from_u64(BI *r, uint64_t v){
    r->n=1; r->d[0]=0;
    if(v==0) return;
    while(v>0){ r->d[r->n-1]=(uint32_t)(v%B); v/=B; if(v>0) r->n++; }
    if(r->n==0) r->n=1;
}

/* ============ Decimal ============ */
typedef struct { int sign; BI abs; int scale; } Dec;

static void dec_zero(Dec *d){ d->sign=0; bi_zero(&d->abs); d->scale=0; }

static void dec_round(Dec *d, int ts){
    if(d->sign==0){ d->scale=ts; return; }
    if(d->scale<ts){
        int diff=ts-d->scale;
        BI p10; bi_pow10(&p10,diff);
        bi_mul(&d->abs,&d->abs,&p10);
        d->scale=ts; return;
    }
    if(d->scale==ts) return;
    int diff=d->scale-ts;
    BI div; bi_pow10(&div,diff);
    BI q,r; bi_divmod(&q,&r,&d->abs,&div);
    /* half = div/2 */
    BI half; bi_copy(&half,&div); bi_div_small(&half,2);
    int c=bi_cmp(&r,&half);
    if(c>0){ bi_add_small(&q,1); }
    else if(c==0){
        uint32_t ld=q.d[0]%10;
        if(ld%2!=0) bi_add_small(&q,1);
    }
    d->abs=q; d->scale=ts;
    if(bi_is_zero(&d->abs)) d->sign=0;
}

static void dec_add(Dec *r, const Dec *a, const Dec *b){
    int ts=a->scale>b->scale?a->scale:b->scale;
    Dec ta=*a, tb=*b;
    dec_round(&ta,ts); dec_round(&tb,ts);
    if(ta.sign==0){ *r=tb; return; }
    if(tb.sign==0){ *r=ta; return; }
    if(ta.sign==tb.sign){
        bi_add(&r->abs,&ta.abs,&tb.abs); r->sign=ta.sign; r->scale=ts;
    } else {
        int c=bi_cmp(&ta.abs,&tb.abs);
        if(c==0){ r->sign=0; bi_zero(&r->abs); r->scale=ts; }
        else if(c>0){ bi_sub(&r->abs,&ta.abs,&tb.abs); r->sign=ta.sign; r->scale=ts; }
        else { bi_sub(&r->abs,&tb.abs,&ta.abs); r->sign=tb.sign; r->scale=ts; }
    }
    if(bi_is_zero(&r->abs)) r->sign=0;
}

static void dec_mul(Dec *r, const Dec *a, const Dec *b){
    if(a->sign==0||b->sign==0){ dec_zero(r); r->scale=a->scale+b->scale; return; }
    r->sign=a->sign*b->sign;
    bi_mul(&r->abs,&a->abs,&b->abs);
    r->scale=a->scale+b->scale;
}

