}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdint.h>

#define MAXL 60
#define B 1000000000U
#define MAX_CURR 1000
#define MAX_ACCT 10000
#define MAX_LINE 100000
#define MAX_REJ 10000
#define MAX_TARG 256

/* ============ BigInt (unsigned, base 10^9) ============ */
typedef struct { uint32_t d[MAXL]; int n; } BI;

static void bi_zero(BI *a){ a->n=1; a->d[0]=0; }
static void bi_copy(BI *dst, const BI *src){ dst->n=src->n; memcpy(dst->d,src->d,src->n*sizeof(uint32_t)); }
static int bi_is_zero(const BI *a){ return a->n==1 && a->d[0]==0; }
static void bi_norm(BI *a){ while(a->n>1 && a->d[a->n-1]==0) a->n--; }

static int bi_cmp(const BI *a, const BI *b){
    if(a->n!=b->n) return a->n>b->n?1:-1;
    for(int i=a->n-1;i>=0;i--) if(a->d[i]!=b->d[i]) return a->d[i]>b->d[i]?1:-1;
    return 0;
}

static void bi_add(BI *r, const BI *a, const BI *b){
    uint64_t carry=0; int n=a->n>b->n?a->n:b->n;
    for(int i=0;i<n;i++){
        uint64_t s=(uint64_t)(i<a->n?a->d[i]:0)+(i<b->n?b->d[i]:0)+carry;
        r->d[i]=(uint32_t)(s%B); carry=s/B;
    }
    if(carry) r->d[n++]=(uint32_t)carry;
    r->n=n; bi_norm(r);
}

static void bi_sub(BI *r, const BI *a, const BI *b){ /* requires a>=b */
    uint64_t borrow=0; int n=a->n;
    for(int i=0;i<n;i++){
        uint64_t bv=(i<b->n?(uint64_t)b->d[i]:0)+borrow;
        if((uint64_t)a->d[i]>=bv){ r->d[i]=(uint32_t)(a->d[i]-bv); borrow=0; }
        else { r->d[i]=(uint32_t)((uint64_t)a->d[i]+B-bv); borrow=1; }
    }
    r->n=n; bi_norm(r);
}

static void bi_add_small(BI *a, uint32_t v){
    uint64_t carry=v;
    for(int i=0;i<a->n&&carry;i++){
        uint64_t s=(uint64_t)a->d[i]+carry;
        a->d[i]=(uint32_t)(s%B); carry=s/B;
    }
    if(carry&&a->n<MAXL){ a->d[a->n++]=(uint32_t)carry; }
}

static void bi_mul(BI *r, const BI *a, const BI *b){
    if(bi_is_zero(a)||bi_is_zero(b)){ bi_zero(r); return; }
    memset(r->d,0,(a->n+b->n)*sizeof(uint32_t));
    for(int i=0;i<a->n;i++){
        uint64_t carry=0;
        for(int j=0;j<b->n;j++){
            uint64_t p=(uint64_t)a->d[i]*b->d[j]+r->d[i+j]+carry;
            r->d[i+j]=(uint32_t)(p%B); carry=p/B;
        }
        if(carry) r->d[i+b->n]+=(uint32_t)carry;
    }
    r->n=a->n+b->n; bi_norm(r);
}

static void bi_mul_small(BI *r, const BI *a, uint32_t m){
    if(m==0||bi_is_zero(a)){ bi_zero(r); return; }
    uint64_t carry=0;
    for(int i=0;i<a->n;i++){
        uint64_t p=(uint64_t)a->d[i]*m+carry;
        r->d[i]=(uint32_t)(p%B); carry=p/B;
    }
    r->n=a->n;
    if(carry){ r->d[r->n++]=(uint32_t)carry; }
    bi_norm(r);
}

static uint32_t bi_div_small(BI *a, uint32_t d){
    uint64_t rem=0;
    for(int i=a->n-1;i>=0;i--){
        uint64_t cur=rem*B+a->d[i];
        a->d[i]=(uint32_t)(cur/d); rem=cur%d;
    }
    bi_norm(a); return (uint32_t)rem;
}

static void bi_from_u32(BI *r, uint32_t v){
    r->n=1; r->d[0]=v;
}

static void bi_divmod(BI *q, BI *r, const BI *a, const BI *b){
    if(bi_is_zero(b)){ bi_zero(q); bi_zero(r); return; }
    if(bi_cmp(a,b)<0){ bi_zero(q); bi_copy(r,a); return; }
    if(b->n==1){
        bi_copy(q,a);
        uint32_t rem=bi_div_small(q,b->d[0]);
        bi_from_u32(r,rem);
        return;
    }
    /* General long division with binary search per digit */
    bi_zero(r);
    q->n=a->n;
    for(int i=a->n-1;i>=0;i--){
        /* r = r*B + a->d[i] */
        if(r->n<MAXL){
            memmove(r->d+1,r->d,r->n*sizeof(uint32_t));
            r->n++;
        }
        r->d[0]=a->d[i];
        bi_norm(r);
        /* binary search for qd in [0,B-1]: qd*b <= r */
        uint32_t lo=0, hi=B-1;
        while(lo<hi){
            uint32_t mid=lo+(hi-lo+1)/2;
            BI tmp; bi_mul_small(&tmp,b,mid);
            if(bi_cmp(&tmp,r)<=0) lo=mid;
            else hi=mid-1;
        }
        uint32_t qd=lo;
        BI tmp; bi_mul_small(&tmp,b,qd);
        bi_sub(r,r,&tmp);
        q->d[i]=qd;
    }
    while(q->n>1&&q->d[q->n-1]==0) q->n--;
    bi_norm(r);
}

/* ============ Decimal ============ */
typedef struct { int sign; BI abs; int scale; } Dec;

static void dec_zero(Dec *d){ d->sign=0; bi_zero(&d->abs); d->scale=0; }

static void dec_round(Dec *d, int ts){
    if(d->sign==0){ d->scale=ts; return; }
    if(d->scale<ts){
        int diff=ts-d->scale;
        for(int i=0;i<diff;i++) bi_mul_small(&d->abs,&d->abs,10);
        d->scale=ts; return;
    }
    if(d->scale==ts) return;
    int diff=d->scale-ts;
    /* divide abs by 10^diff, get quotient and remainder */
    BI q,r;
    bi_copy(&q,&d->abs);
    bi_zero(&r);
    for(int i=0;i<diff;i++){
        uint32_t rem=bi_div_small(&q,10);
        bi_mul_small(&r,&r,10);
        bi_add_small(&r,rem);
    }
    /* half = 5 * 10^(diff-1) */
    BI half; bi_zero(&half); half.d[0]=5; half.n=1;
    for(int i=0;i<diff-1;i++) bi_mul_small(&half,&half,10);
    int c=bi_cmp(&r,&half);
    if(c>0){ bi_add_small(&q,1); }
    else if(c==0){
        uint32_t ld=q.d[0]%10;
        if(ld%2!=0) bi_add_small(&q,1);
    }
    d->abs=q; d->scale=ts;
    if(bi_is_zero(&d->abs)) d->sign=0;
}

static void dec_add(Dec *r, const Dec *a, const Dec *b){
    int ts=a->scale>b->scale?a->scale:b->scale;
    Dec ta,tb;
    bi_copy(&ta.abs,&a->abs); ta.sign=a->sign; ta.scale=a->scale;
    bi_copy(&tb.abs,&b->abs); tb.sign=b->sign; tb.scale=b->scale;
    dec_round(&ta,ts); dec_round(&tb,ts);
    if(ta.sign==0){ *r=tb; return; }
    if(tb.sign==0){ *r=ta; return; }
    if(ta.sign==tb.sign){
        bi_add(&r->abs,&ta.abs,&tb.abs); r->sign=ta.sign; r->scale=ts;
    } else {
        int c=bi_cmp(&ta.abs,&tb.abs);
        if(c==0){ r->sign=0; bi_zero(&r->abs); r->scale=ts; }
        else if(c>0){ bi_sub(&r->abs,&ta.abs,&tb.abs); r->sign=ta.sign; r->scale=ts; }
        else { bi_sub(&r->abs,&tb.abs,&ta.abs); r->sign=tb.sign; r->scale=ts; }
    }
    if(bi_is_zero(&r->abs)) r->sign=0;
}

static void dec_mul(Dec *r, const Dec *a, const Dec *b){
    if(a->sign==0||b->sign==0){ dec_zero(r); r->scale=a->scale+b->scale; return; }
    r->sign=a->sign*b->sign;
    bi_mul(&r->abs,&a->abs,&b->abs);
    r->scale=a->scale+b->scale;
}

static void dec_negate(Dec *d){
    if(d->sign!=0) d->sign=-d->sign;
}

/* ============ Globals ============ */
typedef struct { char code[32]; int minor; } Curr;
typedef struct { char name[256]; int cidx; Dec bal; Dec limit; int active; } Acct;

static Curr currs[MAX_CURR]; static int ncurr=0;
static Acct accts[MAX_ACCT]; static int nacct=0;
static char rejs[MAX_REJ][512]; static int nrej=0;

static int find_curr(const char *code){
    for(int i=0;i<ncurr;i++) if(strcmp(currs[i].code,code)==0) return i;
    return -1;
}
static int find_acct(const char *name){
    for(int i=0;i<nacct;i++) if(accts[i].active && strcmp(accts[i].name,name)==0) return i;
    return -1;
}

/* ============ Parsing ============ */
static char *get_tok(char **p){
    while(**p==' '||**p=='\t') (*p)++;
    if(**p==0||**p=='\n'||**p=='\r') return NULL;
    char *s=*p;
    while(**p&&**p!=' '&&**p!='\t'&&**p!='\n'&&**p!='\r') (*p)++;
    if(**p){ **p=0; (*p)++; }
    return s;
}

static void parse_dec(Dec *d, const char *s){
    d->sign=1; d->scale=0; bi_zero(&d->abs);
    if(*s=='-'){ d->sign=-1; s++; }
    else if(*s=='+'){ s++; }
    int frac_digits=0;
    const char *p=s;
    while(*p>='0'&&*p<='9') p++;
    if(*p=='.'){ p++; while(*p>='0'&&*p<='9'){ frac_digits++; p++; } }
    d->scale=frac_digits;
    BI result; bi_zero(&result);
    p=s;
    while(*p>='0'&&*p<='9'){
        bi_mul_small(&result,&result,10);
        bi_add_small(&result,(uint32_t)(*p-'0'));
        p++;
    }
    if(*p=='.') p++;
    while(*p>='0'&&*p<='9'){
        bi_mul_small(&result,&result,10);
        bi_add_small(&result,(uint32_t)(*p-'0'));
        p++;
    }
    d->abs=result;
    if(bi_is_zero(&d->abs)) d->sign=0;
}

static void parse_bi(BI *r, const char *s){
    bi_zero(r);
    while(*s>='0'&&*s<='9'){
        bi_mul_small(r,r,10);
        bi_add_small(r,(uint32_t)(*s-'0'));
        s++;
    }
}

/* ============ Formatting ============ */
static void bi_to_str(const BI *a, char *buf){
    if(bi_is_zero(a)){ buf[0]='0'; buf[1]=0; return; }
    BI tmp; bi_copy(&tmp,a);
    char rev[600]; int len=0;
    while(!bi_is_zero(&tmp)){
        uint32_t rem=bi_div_small(&tmp,10);
        rev[len++]='0'+(char)rem;
    }
    for(int i=0;i<len;i++) buf[i]=rev[len-1-i];
    buf[len]=0;
}

static void fmt_money(const Dec *d, int minor, char *buf){
    Dec tmp;
    bi_copy(&tmp.abs,&d->abs); tmp.sign=d->sign; tmp.scale=d->scale;
    dec_round(&tmp,minor);
    if(tmp.sign==0||bi_is_zero(&tmp.abs)){
        buf[0]='0'; int pos=1;
        if(minor>0){ buf[pos++]='.'; for(int i=0;i<minor;i++) buf[pos++]='0'; }
        buf[pos]=0; return;
    }
    int pos=0;
    if(tmp.sign<0) buf[pos++]='-';
    /* integer part = abs / 10^minor, frac part = abs % 10^minor */
    BI ipart,fpart;
    bi_copy(&ipart,&tmp.abs);
    bi_zero(&fpart);
    for(int i=0;i<minor;i++){
        uint32_t rem=bi_div_small(&ipart,10);
        bi_mul_small(&fpart,&fpart,10);
        bi_add_small(&fpart,rem);
    }
    char ibuf[600]; bi_to_str(&ipart,ibuf);
    int ilen=(int)strlen(ibuf);
    int first_group=ilen%3; if(first_group==0) first_group=3;
    for(int i=0;i<ilen;i++){
        if(i>0&&(i-first_group)%3==0) buf[pos++]=',';
        buf[pos++]=ibuf[i];
    }
    if(minor>0){
        buf[pos++]='.';
        char fbuf[600]; bi_to_str(&fpart,fbuf);
        int flen=(int)strlen(fbuf);
        for(int i=0;i<minor-flen;i++) buf[pos++]='0';
        for(int i=0;i<flen;i++) buf[pos++]=fbuf[i];
    }
    buf[pos]=0;
}

/* ============ Main ============ */
int main(int argc, char *argv[]){
    if(argc<2){ fprintf(stderr,"Usage: %s <dir>\n",argv[0]); return 1; }
    char path[4096];
    snprintf(path,sizeof(path),"%s/ledger.txt",argv[1]);
    FILE *f=fopen(path,"r");
    if(!f){ perror("open"); return 1; }

    char line[MAX_LINE];
    int lineno=0;

    while(fgets(line,sizeof(line),f)){
        lineno++;
        int len=(int)strlen(line);
        while(len>0&&(line[len-1]=='\n'||line[len-1]=='\r')) line[--len]=0;

        /* check blank/comment */
        int blank=1;
        for(int i=0;i<len;i++){ if(line[i]!=' '&&line[i]!='\t'){ blank=0; break; } }
        if(blank) continue;
        int fi=0; while(fi<len&&(line[fi]==' '||line[fi]=='\t')) fi++;
        if(fi<len&&line[fi]=='#') continue;

        /* tokenize into array to avoid destroying the line */
        char *tokens[512]; int ntok=0;
        {
            char *p=line;
            char *t;
            while((t=get_tok(&p))!=NULL && ntok<512){
                tokens[ntok++]=t;
            }
        }
        if(ntok==0) continue;
        char *cmd=tokens[0];

        if(strcmp(cmd,"currency")==0){
            if(ntok<3) continue;
            char *code=tokens[1];
            int mi=atoi(tokens[2]);
            int ci=find_curr(code);
            if(ci<0){
                ci=ncurr++;
                strcpy(currs[ci].code,code);
                currs[ci].minor=mi;
            } else {
                currs[ci].minor=mi;
            }
        }
        else if(strcmp(cmd,"open")==0){
            if(ntok<3) continue;
            char *name=tokens[1];
            char *code=tokens[2];
            char *lim=(ntok>=4)?tokens[3]:NULL;
            if(find_acct(name)>=0){
                snprintf(rejs[nrej++],512,"line %d: REJECT account exists %s",lineno,name);
                continue;
            }
            int ci=find_curr(code);
            if(ci<0) continue;
            Acct *a=&accts[nacct++];
            strcpy(a->name,name);
            a->cidx=ci;
            dec_zero(&a->bal);
            dec_zero(&a->limit);
            if(lim){
                parse_dec(&a->limit,lim);
                dec_round(&a->limit,currs[ci].minor);
            }
            a->active=1;
        }
        else if(strcmp(cmd,"deposit")==0){
            if(ntok<3) continue;
            char *name=tokens[1];
            char *amt=tokens[2];
            int ai=find_acct(name);
            if(ai<0){ snprintf(rejs[nrej++],512,"line %d: REJECT unknown account %s",lineno,name); continue; }
            int mi=currs[accts[ai].cidx].minor;
            Dec a; parse_dec(&a,amt);
            dec_round(&a,mi);
            if(a.sign<=0){ snprintf(rejs[nrej++],512,"line %d: REJECT non-positive amount",lineno); continue; }
            dec_add(&accts[ai].bal,&accts[ai].bal,&a);
        }
        else if(strcmp(cmd,"withdraw")==0){
            if(ntok<3) continue;
            char *name=tokens[1];
            char *amt=tokens[2];
            int ai=find_acct(name);
            if(ai<0){ snprintf(rejs[nrej++],512,"line %d: REJECT unknown account %s",lineno,name); continue; }
            int mi=currs[accts[ai].cidx].minor;
            Dec a; parse_dec(&a,amt);
            dec_round(&a,mi);
            if(a.sign<=0){ snprintf(rejs[nrej++],512,"line %d: REJECT non-positive amount",lineno); continue; }
            /* check: bal - amt + limit >= 0 */
            Dec neg_a=a; dec_negate(&neg_a);
            Dec temp; dec_add(&temp,&accts[ai].bal,&neg_a);
            Dec check; dec_add(&check,&temp,&accts[ai].limit);
            if(check.sign<0){
                snprintf(rejs[nrej++],512,"line %d: REJECT insufficient funds %s",lineno,name);
                continue;
            }
            accts[ai].bal=temp;
        }
        else if(strcmp(cmd,"transfer")==0){
            if(ntok<4) continue;
            char *fn=tokens[1], *tn=tokens[2], *amt=tokens[3];
            int fi2=find_acct(fn), ti=find_acct(tn);
            if(fi2<0){ snprintf(rejs[nrej++],512,"line %d: REJECT unknown account %s",lineno,fn); continue; }
            if(ti<0){ snprintf(rejs[nrej++],512,"line %d: REJECT unknown account %s",lineno,tn); continue; }
            if(accts[fi2].cidx!=accts[ti].cidx){ snprintf(rejs[nrej++],512,"line %d: REJECT currency mismatch",lineno); continue; }
            int mi=currs[accts[fi2].cidx].minor;
            Dec a; parse_dec(&a,amt);
            dec_round(&a,mi);
            if(a.sign<=0){ snprintf(rejs[nrej++],512,"line %d: REJECT non-positive amount",lineno); continue; }
            Dec neg_a=a; dec_negate(&neg_a);
            Dec temp; dec_add(&temp,&accts[fi2].bal,&neg_a);
            Dec check; dec_add(&check,&temp,&accts[fi2].limit);
            if(check.sign<0){
                snprintf(rejs[nrej++],512,"line %d: REJECT insufficient funds %s",lineno,fn);
                continue;
            }
            accts[fi2].bal=temp;
            dec_add(&accts[ti].bal,&accts[ti].bal,&a);
        }
        else if(strcmp(cmd,"convert")==0){
            if(ntok<5) continue;
            char *fn=tokens[1], *tn=tokens[2], *amt=tokens[3], *rate=tokens[4];
            int fi2=find_acct(fn), ti=find_acct(tn);
            if(fi2<0){ snprintf(rejs[nrej++],512,"line %d: REJECT unknown account %s",lineno,fn); continue; }
            if(ti<0){ snprintf(rejs[nrej++],512,"line %d: REJECT unknown account %s",lineno,tn); continue; }
            int mi=currs[accts[fi2].cidx].minor;
            Dec a; parse_dec(&a,amt);
            dec_round(&a,mi);
            if(a.sign<=0){ snprintf(rejs[nrej++],512,"line %d: REJECT non-positive amount",lineno); continue; }
            Dec neg_a=a; dec_negate(&neg_a);
            Dec temp; dec_add(&temp,&accts[fi2].bal,&neg_a);
            Dec check; dec_add(&check,&temp,&accts[fi2].limit);
            if(check.sign<0){
                snprintf(rejs[nrej++],512,"line %d: REJECT insufficient funds %s",lineno,fn);
                continue;
            }
            Dec rt; parse_dec(&rt,rate);
            Dec result; dec_mul(&result,&a,&rt);
            int tmi=currs[accts[ti].cidx].minor;
            dec_round(&result,tmi);
            accts[fi2].bal=temp;
            dec_add(&accts[ti].bal,&accts[ti].bal,&result);
        }
        else if(strcmp(cmd,"interest")==0){
            if(ntok<3) continue;
            char *name=tokens[1], *rate=tokens[2];
            int ai=find_acct(name);
            if(ai<0){ snprintf(rejs[nrej++],512,"line %d: REJECT unknown account %s",lineno,name); continue; }
            Dec rt; parse_dec(&rt,rate);
            Dec gain; dec_mul(&gain,&accts[ai].bal,&rt);
            int mi=currs[accts[ai].cidx].minor;
            dec_round(&gain,mi);
            dec_add(&accts[ai].bal,&accts[ai].bal,&gain);
        }
        else if(strcmp(cmd,"split")==0){
            if(ntok<4) continue;
            char *fn=tokens[1], *amt=tokens[2];
            int ntarg=ntok-3;
            if(ntarg<=0) continue;
            /* Parse targets: tokens[3..ntok-1] are "name:weight" */
            char tnames[MAX_TARG][256];
            BI weights[MAX_TARG];
            for(int i=0;i<ntarg;i++){
                char *s=tokens[3+i];
                char *colon=strchr(s,':');
                if(!colon){ ntarg=0; break; }
                int nlen=(int)(colon-s);
                if(nlen>=256) nlen=255;
                memcpy(tnames[i],s,nlen);
                tnames[i][nlen]=0;
                parse_bi(&weights[i],colon+1);
            }
            if(ntarg==0) continue;
            /* Check 1: unknown accounts in order of appearance */
            int fi2=find_acct(fn);
            if(fi2<0){ snprintf(rejs[nrej++],512,"line %d: REJECT unknown account %s",lineno,fn); continue; }
            int tidx[MAX_TARG];
            int bad=0;
            for(int i=0;i<ntarg;i++){
                int ti=find_acct(tnames[i]);
                if(ti<0){ snprintf(rejs[nrej++],512,"line %d: REJECT unknown account %s",lineno,tnames[i]); bad=1; break; }
                tidx[i]=ti;
            }
            if(bad) continue;
            /* Check 2: currency mismatch */
            for(int i=0;i<ntarg;i++){
                if(accts[tidx[i]].cidx!=accts[fi2].cidx){
                    snprintf(rejs[nrej++],512,"line %d: REJECT currency mismatch",lineno);
                    bad=1; break;
                }
            }
            if(bad) continue;
            /* Check 3: non-positive amount */
            int mi=currs[accts[fi2].cidx].minor;
            Dec a; parse_dec(&a,amt);
            dec_round(&a,mi);
            if(a.sign<=0){ snprintf(rejs[nrej++],512,"line %d: REJECT non-positive amount",lineno); continue; }
            /* Check 4: insufficient funds */
            Dec neg_a=a; dec_negate(&neg_a);
            Dec temp; dec_add(&temp,&accts[fi2].bal,&neg_a);
            Dec check; dec_add(&check,&temp,&accts[fi2].limit);
            if(check.sign<0){
                snprintf(rejs[nrej++],512,"line %d: REJECT insufficient funds %s",lineno,fn);
                continue;
            }
            /* Perform split */
            /* A = a.abs (number of minor units) */
            BI A; bi_copy(&A,&a.abs);
            /* Compute W = sum of weights */
            BI W; bi_zero(&W);
            for(int i=0;i<ntarg;i++) bi_add(&W,&W,&weights[i]);
            /* Compute base[i] = floor(A*wi/W), rem[i] = (A*wi) mod W */
            BI base[MAX_TARG], rem[MAX_TARG];
            BI sum_base; bi_zero(&sum_base);
            for(int i=0;i<ntarg;i++){
                BI aw; bi_mul(&aw,&A,&weights[i]);
                bi_divmod(&base[i],&rem[i],&aw,&W);
                bi_add(&sum_base,&sum_base,&base[i]);
            }
            BI leftover; bi_sub(&leftover,&A,&sum_base);
            int lo=0;
            if(!bi_is_zero(&leftover)){
                /* leftover < ntarg, fits in one limb */
                lo=(int)leftover.d[0];
            }
            /* Sort by rem descending, stable (ties: lower index first) */
            int order[MAX_TARG];
            for(int i=0;i<ntarg;i++) order[i]=i;
            for(int i=1;i<ntarg;i++){
                int key=order[i];
                int j=i-1;
                while(j>=0){
                    int c=bi_cmp(&rem[order[j]],&rem[key]);
                    if(c<0||(c==0&&order[j]>key)){
                        order[j+1]=order[j]; j--;
                    } else break;
                }
                order[j+1]=key;
            }
            /* Apply */
            for(int i=0;i<ntarg;i++){
                Dec add; add.sign=1; add.scale=mi;
                bi_copy(&add.abs,&base[i]);
                if(bi_is_zero(&add.abs)) add.sign=0;
                /* check if gets extra */
                for(int k=0;k<lo;k++){
                    if(order[k]==i){ bi_add_small(&add.abs,1); add.sign=1; break; }
                }
                if(add.sign!=0)
                    dec_add(&accts[tidx[i]].bal,&accts[tidx[i]].bal,&add);
            }
            accts[fi2].bal=temp;
        }
    }
    fclose(f);

    /* Output rejections */
    for(int i=0;i<nrej;i++) printf("%s\n",rejs[i]);
    printf("\n");

    /* Sort accounts by name (byte-wise ascending) */
    for(int i=0;i<nacct;i++){
        for(int j=i+1;j<nacct;j++){
            if(accts[j].active && accts[i].active && strcmp(accts[j].name,accts[i].name)<0){
                Acct tmp=accts[i]; accts[i]=accts[j]; accts[j]=tmp;
            }
        }
    }
    for(int i=0;i<nacct;i++){
        if(!accts[i].active) continue;
        char buf[1000];
        fmt_money(&accts[i].bal,currs[accts[i].cidx].minor,buf);
        printf("%s %s %s\n",accts[i].name,currs[accts[i].cidx].code,buf);
    }
    printf("\n");

    /* Totals per currency */
    int used[MAX_CURR]; memset(used,0,sizeof(used));
    for(int i=0;i<nacct;i++){
        if(accts[i].active) used[accts[i].cidx]=1;
    }
    int corder[MAX_CURR]; int ncord=0;
    for(int i=0;i<ncurr;i++) if(used[i]) corder[ncord++]=i;
    for(int i=0;i<ncord;i++){
        for(int j=i+1;j<ncord;j++){
            if(strcmp(currs[corder[j]].code,currs[corder[i]].code)<0){
                int tmp=corder[i]; corder[i]=corder[j]; corder[j]=tmp;
            }
        }
    }
    for(int ci=0;ci<ncord;ci++){
        int c=corder[ci];
        Dec total; dec_zero(&total);
        int count=0;
        for(int i=0;i<nacct;i++){
            if(accts[i].active && accts[i].cidx==c){
                dec_add(&total,&total,&accts[i].bal);
                count++;
            }
        }
        char buf[1000];
        fmt_money(&total,currs[c].minor,buf);
        printf("total %s %s (%d accounts)\n",currs[c].code,buf,count);
    }

    return 0;
}

use std::collections::HashSet;
use std::env;
use std::fs;

#[derive(Debug, Clone, PartialEq)]
enum Value {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Value>),
    Obj(Vec<(String, Value)>),
}

struct Parser {
    input: Vec<u8>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { input: s.as_bytes().to_vec(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn peek(&self) -> u8 {
        self.input[self.pos]
    }

    fn eat(&mut self) -> u8 {
        let c = self.input[self.pos];
        self.pos += 1;
        c
    }

    fn expect(&mut self, c: u8) {
        assert_eq!(self.eat(), c);
    }

    fn parse_value(&mut self) -> Value {
        self.skip_ws();
        match self.peek() {
            b'n' => { self.pos += 4; Value::Null }
            b't' => { self.pos += 4; Value::Bool(true) }
            b'f' => { self.pos += 5; Value::Bool(false) }
            b'"' => Value::Str(self.parse_string()),
            b'[' => self.parse_array(),
            b'{' => self.parse_object(),
            _ => self.parse_number(),
        }
    }

    fn parse_string(&mut self) -> String {
        self.expect(b'"');
        let mut result = String::new();
        let mut byte_buf: Vec<u8> = Vec::new();
        loop {
            let c = self.eat();
            if c == b'"' {
                if !byte_buf.is_empty() {
                    result.push_str(std::str::from_utf8(&byte_buf).unwrap());
                    byte_buf.clear();
                }
                break;
            }
            if c == b'\\' {
                if !byte_buf.is_empty() {
                    result.push_str(std::str::from_utf8(&byte_buf).unwrap());
                    byte_buf.clear();
                }
                let e = self.eat();
                match e {
                    b'"' => result.push('"'),
                    b'\\' => result.push('\\'),
                    b'/' => result.push('/'),
                    b'b' => result.push('\u{0008}'),
                    b'f' => result.push('\u{000C}'),
                    b'n' => result.push('\n'),
                    b'r' => result.push('\r'),
                    b't' => result.push('\t'),
                    b'u' => {
                        let cp = self.parse_hex4();
                        if cp >= 0xD800 && cp <= 0xDBFF {
                            self.expect(b'\\');
                            self.expect(b'u');
                            let cp2 = self.parse_hex4();
                            let combined = ((cp as u32 - 0xD800) * 0x400 + (cp2 as u32 - 0xDC00) + 0x10000) as u32;
                            result.push(char::from_u32(combined).unwrap());
                        } else {
                            result.push(char::from_u32(cp as u32).unwrap());
                        }
                    }
                    _ => unreachable!(),
                }
            } else {
                byte_buf.push(c);
            }
        }
        result
    }

    fn parse_hex4(&mut self) -> u16 {
        let mut val: u16 = 0;
        for _ in 0..4 {
            let c = self.eat();
            let d = match c {
                b'0'..=b'9' => c - b'0',
                b'a'..=b'f' => c - b'a' + 10,
                b'A'..=b'F' => c - b'A' + 10,
                _ => unreachable!(),
            };
            val = val * 16 + (d as u16);
        }
        val
    }

    fn parse_number(&mut self) -> Value {
        let start = self.pos;
        if self.peek() == b'-' { self.pos += 1; }
        if self.peek() == b'0' { self.pos += 1; }
        else { while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; } }
        if self.pos < self.input.len() && self.input[self.pos] == b'.' {
            self.pos += 1;
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        if self.pos < self.input.len() && (self.input[self.pos] == b'e' || self.input[self.pos] == b'E') {
            self.pos += 1;
            if self.pos < self.input.len() && (self.input[self.pos] == b'+' || self.input[self.pos] == b'-') { self.pos += 1; }
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        let s = std::str::from_utf8(&self.input[start..self.pos]).unwrap();
        Value::Num(s.parse::<f64>().unwrap())
    }

    fn parse_array(&mut self) -> Value {
        self.expect(b'[');
        self.skip_ws();
        let mut items = Vec::new();
        if self.peek() != b']' {
            loop {
                items.push(self.parse_value());
                self.skip_ws();
                if self.peek() == b',' { self.pos += 1; self.skip_ws(); }
                else { break; }
            }
        }
        self.expect(b']');
        Value::Arr(items)
    }

    fn parse_object(&mut self) -> Value {
        self.expect(b'{');
        self.skip_ws();
        let mut members = Vec::new();
        if self.peek() != b'}' {
            loop {
                let key = self.parse_string();
                self.skip_ws();
                self.expect(b':');
                self.skip_ws();
                let val = self.parse_value();
                members.push((key, val));
                self.skip_ws();
                if self.peek() == b',' { self.pos += 1; self.skip_ws(); }
                else { break; }
            }
        }
        self.expect(b'}');
        Value::Obj(members)
    }
}

fn deep_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Null, Value::Null) => true,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Num(x), Value::Num(y)) => x == y,
        (Value::Str(x), Value::Str(y)) => x == y,
        (Value::Arr(x), Value::Arr(y)) => {
            x.len() == y.len() && x.iter().zip(y.iter()).all(|(a, b)| deep_equal(a, b))
        }
        (Value::Obj(x), Value::Obj(y)) => {
            x.len() == y.len() && x.iter().all(|(k, v)| {
                y.iter().any(|(k2, v2)| k == k2 && deep_equal(v, v2))
            })
        }
        _ => false,
    }
}

fn check_type(instance: &Value, type_name: &str) -> bool {
    match (instance, type_name) {
        (Value::Null, "null") => true,
        (Value::Bool(_), "boolean") => true,
        (Value::Num(_), "number") => true,
        (Value::Num(n), "integer") => n.fract() == 0.0,
        (Value::Str(_), "string") => true,
        (Value::Arr(_), "array") => true,
        (Value::Obj(_), "object") => true,
        _ => false,
    }
}

fn escape_token(token: &str) -> String {
    let mut result = String::new();
    for c in token.chars() {
        match c {
            '~' => result.push_str("~0"),
            '/' => result.push_str("~1"),
            _ => result.push(c),
        }
    }
    result
}

fn unescape_token(token: &str) -> String {
    let mut result = String::new();
    let mut chars = token.chars();
    while let Some(c) = chars.next() {
        if c == '~' {
            if let Some(next) = chars.next() {
                match next {
                    '0' => result.push('~'),
                    '1' => result.push('/'),
                    _ => { result.push('~'); result.push(next); }
                }
            } else {
                result.push('~');
            }
        } else {
            result.push(c);
        }
    }
    result
}

fn resolve_ref<'a>(ref_str: &str, root: &'a Value) -> (&'a Value, String) {
    if ref_str == "#" {
        return (root, "#".to_string());
    }
    if ref_str.starts_with("#/$defs/") {
        let token = &ref_str[8..];
        let name = unescape_token(token);
        if let Value::Obj(members) = root {
            if let Some((_, defs)) = members.iter().find(|(k, _)| k == "$defs") {
                if let Value::Obj(defs_members) = defs {
                    if let Some((_, schema)) = defs_members.iter().find(|(k, _)| k == &name) {
                        return (schema, ref_str.to_string());
                    }
                }
            }
        }
    }
    (root, "#".to_string())
}

fn validate(
    instance: &Value,
    schema: &Value,
    inst_loc: &str,
    schema_loc: &str,
    errors: &mut HashSet<(String, String)>,
    root: &Value,
) {
    if let Value::Bool(b) = schema {
        if !b {
            errors.insert((inst_loc.to_string(), schema_loc.to_string()));
        }
        return;
    }

    let obj = match schema {
        Value::Obj(m) => m,
        _ => return,
    };

    let get = |name: &str| -> Option<&Value> {
        obj.iter().find(|(k, _)| k == name).map(|(_, v)| v)
    };

    // type
    if let Some(type_val) = get("type") {
        let matches = match type_val {
            Value::Str(s) => check_type(instance, s),
            Value::Arr(arr) => arr.iter().any(|t| {
                if let Value::Str(s) = t { check_type(instance, s) } else { false }
            }),
            _ => true,
        };
        if !matches {
            errors.insert((inst_loc.to_string(), format!("{}/type", schema_loc)));
        }
    }

    // enum
    if let Some(enum_val) = get("enum") {
        if let Value::Arr(arr) = enum_val {
            if !arr.iter().any(|e| deep_equal(e, instance)) {
                errors.insert((inst_loc.to_string(), format!("{}/enum", schema_loc)));
            }
        }
    }

    // const
    if let Some(const_val) = get("const") {
        if !deep_equal(const_val, instance) {
            errors.insert((inst_loc.to_string(), format!("{}/const", schema_loc)));
        }
    }

    // Numeric keywords
    if let Value::Num(n) = instance {
        if let Some(v) = get("minimum") {
            if let Value::Num(m) = v { if !(n >= m) { errors.insert((inst_loc.to_string(), format!("{}/minimum", schema_loc))); } }
        }
        if let Some(v) = get("maximum") {
            if let Value::Num(m) = v { if !(n <= m) { errors.insert((inst_loc.to_string(), format!("{}/maximum", schema_loc))); } }
        }
        if let Some(v) = get("exclusiveMinimum") {
            if let Value::Num(m) = v { if !(*n > *m) { errors.insert((inst_loc.to_string(), format!("{}/exclusiveMinimum", schema_loc))); } }
        }
        if let Some(v) = get("exclusiveMaximum") {
            if let Value::Num(m) = v { if !(*n < *m) { errors.insert((inst_loc.to_string(), format!("{}/exclusiveMaximum", schema_loc))); } }
        }
    }

    // String keywords
    if let Value::Str(s) = instance {
        let len = s.chars().count();
        if let Some(v) = get("minLength") {
            if let Value::Num(m) = v { if (len as f64) < *m { errors.insert((inst_loc.to_string(), format!("{}/minLength", schema_loc))); } }
        }
        if let Some(v) = get("maxLength") {
            if let Value::Num(m) = v { if (len as f64) > *m { errors.insert((inst_loc.to_string(), format!("{}/maxLength", schema_loc))); } }
        }
    }

    // Array keywords
    if let Value::Arr(arr) = instance {
        let count = arr.len() as f64;
        if let Some(v) = get("minItems") {
            if let Value::Num(m) = v { if count < *m { errors.insert((inst_loc.to_string(), format!("{}/minItems", schema_loc))); } }
        }
        if let Some(v) = get("maxItems") {
            if let Value::Num(m) = v { if count > *m { errors.insert((inst_loc.to_string(), format!("{}/maxItems", schema_loc))); } }
        }
        if let Some(v) = get("uniqueItems") {
            if let Value::Bool(true) = v {
                let mut dup = false;
                for i in 0..arr.len() {
                    for j in (i + 1)..arr.len() {
                        if deep_equal(&arr[i], &arr[j]) { dup = true; break; }
                    }
                    if dup { break; }
                }
                if dup { errors.insert((inst_loc.to_string(), format!("{}/uniqueItems", schema_loc))); }
            }
        }

        // prefixItems
        let prefix_len = if let Some(v) = get("prefixItems") {
            if let Value::Arr(pi) = v {
                for (i, sub) in pi.iter().enumerate() {
                    if i < arr.len() {
                        validate(&arr[i], sub, &format!("{}/{}", inst_loc, i), &format!("{}/prefixItems/{}", schema_loc, i), errors, root);
                    }
                }
                pi.len()
            } else { 0 }
        } else { 0 };

        // items
        if let Some(v) = get("items") {
            for i in prefix_len..arr.len() {
                validate(&arr[i], v, &format!("{}/{}", inst_loc, i), &format!("{}/items", schema_loc), errors, root);
            }
        }
    }

    // Object keywords
    if let Value::Obj(members) = instance {
        let count = members.len() as f64;
        if let Some(v) = get("minProperties") {
            if let Value::Num(m) = v { if count < *m { errors.insert((inst_loc.to_string(), format!("{}/minProperties", schema_loc))); } }
        }
        if let Some(v) = get("maxProperties") {
            if let Value::Num(m) = v { if count > *m { errors.insert((inst_loc.to_string(), format!("{}/maxProperties", schema_loc))); } }
        }

        // required
        if let Some(v) = get("required") {
            if let Value::Arr(req) = v {
                for (j, name) in req.iter().enumerate() {
                    if let Value::Str(n) = name {
                        if !members.iter().any(|(k, _)| k == n) {
                            errors.insert((inst_loc.to_string(), format!("{}/required/{}", schema_loc, j)));
                        }
                    }
                }
            }
        }

        // properties
        let prop_keys: HashSet<&str> = if let Some(v) = get("properties") {
            if let Value::Obj(props) = v {
                props.iter().map(|(k, _)| k.as_str()).collect()
            } else { HashSet::new() }
        } else { HashSet::new() };

        if let Some(v) = get("properties") {
            if let Value::Obj(props) = v {
                for (key, val) in members {
                    if let Some((_, sub)) = props.iter().find(|(k, _)| k == key) {
                        validate(val, sub, &format!("{}/{}", inst_loc, escape_token(key)), &format!("{}/properties/{}", schema_loc, escape_token(key)), errors, root);
                    }
                }
            }
        }

        // additionalProperties
        if let Some(v) = get("additionalProperties") {
            for (key, val) in members {
                if !prop_keys.contains(key.as_str()) {
                    validate(val, v, &format!("{}/{}", inst_loc, escape_token(key)), &format!("{}/additionalProperties", schema_loc), errors, root);
                }
            }
        }
    }

    // allOf
    if let Some(v) = get("allOf") {
        if let Value::Arr(arr) = v {
            for (i, sub) in arr.iter().enumerate() {
                validate(instance, sub, inst_loc, &format!("{}/allOf/{}", schema_loc, i), errors, root);
            }
        }
    }

    // anyOf
    if let Some(v) = get("anyOf") {
        if let Value::Arr(arr) = v {
            let any_accepted = arr.iter().enumerate().any(|(i, sub)| {
                let mut temp = HashSet::new();
                validate(instance, sub, inst_loc, &format!("{}/anyOf/{}", schema_loc, i), &mut temp, root);
                temp.is_empty()
            });
            if !any_accepted {
                errors.insert((inst_loc.to_string(), format!("{}/anyOf", schema_loc)));
            }
        }
    }

    // oneOf
    if let Some(v) = get("oneOf") {
        if let Value::Arr(arr) = v {
            let count = arr.iter().enumerate().filter(|(i, sub)| {
                let mut temp = HashSet::new();
                validate(instance, sub, inst_loc, &format!("{}/oneOf/{}", schema_loc, i), &mut temp, root);
                temp.is_empty()
            }).count();
            if count != 1 {
                errors.insert((inst_loc.to_string(), format!("{}/oneOf", schema_loc)));
            }
        }
    }

    // not
    if let Some(v) = get("not") {
        let mut temp = HashSet::new();
        validate(instance, v, inst_loc, &format!("{}/not", schema_loc), &mut temp, root);
        if temp.is_empty() {
            errors.insert((inst_loc.to_string(), format!("{}/not", schema_loc)));
        }
    }

    // if/then/else
    if let Some(if_val) = get("if") {
        let mut temp = HashSet::new();
        validate(instance, if_val, inst_loc, &format!("{}/if", schema_loc), &mut temp, root);
        if temp.is_empty() {
            if let Some(then_val) = get("then") {
                validate(instance, then_val, inst_loc, &format!("{}/then", schema_loc), errors, root);
            }
        } else {
            if let Some(else_val) = get("else") {
                validate(instance, else_val, inst_loc, &format!("{}/else", schema_loc), errors, root);
            }
        }
    }

    // $ref
    if let Some(v) = get("$ref") {
        if let Value::Str(ref_str) = v {
            let (ref_schema, ref_loc) = resolve_ref(ref_str, root);
            validate(instance, ref_schema, inst_loc, &ref_loc, errors, root);
        }
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let schema_str = fs::read_to_string(format!("{}/schema.json", dir)).unwrap();
    let instances_str = fs::read_to_string(format!("{}/instances.json", dir)).unwrap();

    let mut p1 = Parser::new(&schema_str);
    let schema = p1.parse_value();

    let mut p2 = Parser::new(&instances_str);
    let instances = p2.parse_value();

    let instances_arr = match instances {
        Value::Arr(a) => a,
        _ => panic!("instances must be an array"),
    };

    let mut valid_count = 0usize;
    let mut invalid_count = 0usize;

    for (n, inst) in instances_arr.iter().enumerate() {
        let mut errors = HashSet::new();
        validate(inst, &schema, "#", "#", &mut errors, &schema);

        if errors.is_empty() {
            println!("{}: valid", n);
            valid_count += 1;
        } else {
            let mut sorted: Vec<(String, String)> = errors.into_iter().collect();
            sorted.sort();
            println!("{}: invalid ({})", n, sorted.len());
            for (inst_loc, schema_loc) in &sorted {
                println!("  {} {}", inst_loc, schema_loc);
            }
            invalid_count += 1;
        }
    }

    println!("valid={} invalid={}", valid_count, invalid_count);
}

import Foundation

// MARK: - JSON Value

indirect enum JSONValue {
    case null
    case bool(Bool)
    case number(Double)
    case string(String)
    case array([JSONValue])
    case object([String: JSONValue])
}

// MARK: - JSON Parser

struct JSONParser {
    let input: [Character]
    var pos: Int = 0

    init(_ s: String) {
        input = Array(s)
    }

    mutating func parse() -> JSONValue {
        skipWS()
        let v = parseValue()
        skipWS()
        return v
    }

    mutating func skipWS() {
        while pos < input.count {
            let c = input[pos]
            if c == " " || c == "\t" || c == "\n" || c == "\r" { pos += 1 }
            else { break }
        }
    }

    mutating func parseValue() -> JSONValue {
        skipWS()
        guard pos < input.count else { fatalError("EOF") }
        switch input[pos] {
        case "{": return parseObject()
        case "[": return parseArray()
        case "\"": return .string(parseString())
        case "t": pos += 4; return .bool(true)
        case "f": pos += 5; return .bool(false)
        case "n": pos += 4; return .null
        default: return parseNumber()
        }
    }

    mutating func parseObject() -> JSONValue {
        pos += 1
        var obj: [String: JSONValue] = [:]
        skipWS()
        if pos < input.count && input[pos] == "}" { pos += 1; return .object(obj) }
        while true {
            skipWS()
            let key = parseString()
            skipWS()
            pos += 1 // ':'
            let val = parseValue()
            obj[key] = val
            skipWS()
            if pos < input.count && input[pos] == "," { pos += 1 } else { break }
        }
        skipWS()
        pos += 1 // '}'
        return .object(obj)
    }

    mutating func parseArray() -> JSONValue {
        pos += 1
        var arr: [JSONValue] = []
        skipWS()
        if pos < input.count && input[pos] == "]" { pos += 1; return .array(arr) }
        while true {
            arr.append(parseValue())
            skipWS()
            if pos < input.count && input[pos] == "," { pos += 1 } else { break }
        }
        skipWS()
        pos += 1 // ']'
        return .array(arr)
    }

    mutating func parseString() -> String {
        pos += 1 // opening "
        var result = ""
        while pos < input.count && input[pos] != "\"" {
            if input[pos] == "\\" {
                pos += 1
                switch input[pos] {
                case "\"": result.append("\""); pos += 1
                case "\\": result.append("\\"); pos += 1
                case "/": result.append("/"); pos += 1
                case "b": result.append("\u{08}"); pos += 1
                case "f": result.append("\u{0C}"); pos += 1
                case "n": result.append("\n"); pos += 1
                case "r": result.append("\r"); pos += 1
                case "t": result.append("\t"); pos += 1
                case "u":
                    pos += 1
                    let code = parseHex4()
                    if code >= 0xD800 && code <= 0xDBFF {
                        pos += 1 // '\'
                        pos += 1 // 'u'
                        let low = parseHex4()
                        let cp = 0x10000 + (code - 0xD800) * 0x400 + (low - 0xDC00)
                        result.append(Character(UnicodeScalar(cp)!))
                    } else {
                        result.append(Character(UnicodeScalar(code)!))
                    }
                default: fatalError("bad escape")
                }
            } else {
                result.append(input[pos])
                pos += 1
            }
        }
        pos += 1 // closing "
        return result
    }

    mutating func parseHex4() -> UInt32 {
        var val: UInt32 = 0
        for _ in 0..<4 {
            val <<= 4
            let c = input[pos]
            if c >= "0" && c <= "9" { val += UInt32(c.asciiValue! - 48) }
            else if c >= "a" && c <= "f" { val += UInt32(c.asciiValue! - 87) }
            else if c >= "A" && c <= "F" { val += UInt32(c.asciiValue! - 55) }
            else { fatalError("bad hex") }
            pos += 1
        }
        return val
    }

    mutating func parseNumber() -> JSONValue {
        let start = pos
        if pos < input.count && input[pos] == "-" { pos += 1 }
        if pos < input.count && input[pos] == "0" {
            pos += 1
        } else {
            while pos < input.count && input[pos] >= "0" && input[pos] <= "9" { pos += 1 }
        }
        if pos < input.count && input[pos] == "." {
            pos += 1
            while pos < input.count && input[pos] >= "0" && input[pos] <= "9" { pos += 1 }
        }
        if pos < input.count && (input[pos] == "e" || input[pos] == "E") {
            pos += 1
            if pos < input.count && (input[pos] == "+" || input[pos] == "-") { pos += 1 }
            while pos < input.count && input[pos] >= "0" && input[pos] <= "9" { pos += 1 }
        }
        let s = String(input[start..<pos])
        return .number(Double(s)!)
    }
}

// MARK: - Deep Equality

func deepEqual(_ a: JSONValue, _ b: JSONValue) -> Bool {
    switch (a, b) {
    case (.null, .null): return true
    case (.bool(let x), .bool(let y)): return x == y
    case (.number(let x), .number(let y)): return x == y
    case (.string(let x), .string(let y)): return x == y
    case (.array(let x), .array(let y)):
        if x.count != y.count { return false }
        for i in 0..<x.count { if !deepEqual(x[i], y[i]) { return false } }
        return true
    case (.object(let x), .object(let y)):
        if x.count != y.count { return false }
        for (k, v) in x {
            guard let w = y[k] else { return false }
            if !deepEqual(v, w) { return false }
        }
        return true
    default: return false
    }
}

// MARK: - JSON Pointer Formatting

func formatPointer(_ tokens: [String]) -> String {
    var r = "#"
    for t in tokens {
        let esc = t.replacingOccurrences(of: "~", with: "~0")
                   .replacingOccurrences(of: "/", with: "~1")
        r += "/" + esc
    }
    return r
}

// MARK: - Type Checking

func matchesType(_ inst: JSONValue, _ typeName: String) -> Bool {
    switch (inst, typeName) {
    case (.null, "null"): return true
    case (.bool(_), "boolean"): return true
    case (.number(_), "number"): return true
    case (.number(let n), "integer"): return n == n.rounded(.down)
    case (.string(_), "string"): return true
    case (.array(_), "array"): return true
    case (.object(_), "object"): return true
    default: return false
    }
}

func checkType(_ inst: JSONValue, _ typeVal: JSONValue) -> Bool {
    var names: [String] = []
    switch typeVal {
    case .string(let s): names = [s]
    case .array(let arr):
        for v in arr { if case .string(let s) = v { names.append(s) } }
    default: return true
    }
    for n in names { if matchesType(inst, n) { return true } }
    return false
}

// MARK: - $ref Resolution

func resolveRef(_ ref: String, _ rootSchema: JSONValue) -> (JSONValue, [String]) {
    if ref == "#" { return (rootSchema, []) }
    let prefix = "#/$defs/"
    if ref.hasPrefix(prefix) {
        let encoded = String(ref.dropFirst(prefix.count))
        let name = encoded.replacingOccurrences(of: "~1", with: "/")
                          .replacingOccurrences(of: "~0", with: "~")
        if case .object(let rootObj) = rootSchema,
           case .object(let defs)? = rootObj["$defs"],
           let target = defs[name] {
            return (target, ["$defs", name])
        }
    }
    fatalError("Cannot resolve: \(ref)")
}

// MARK: - Validator

func validate(instance: JSONValue, schema: JSONValue,
              instLoc: [String], schemaLoc: [String],
              rootSchema: JSONValue) -> Set<(String, String)> {
    var errors = Set<(String, String)>()

    if case .bool(let b) = schema {
        if !b { errors.insert((formatPointer(instLoc), formatPointer(schemaLoc))) }
        return errors
    }

    guard case .object(let sObj) = schema else { return errors }

    // type
    if let typeVal = sObj["type"] {
        if !checkType(instance, typeVal) {
            errors.insert((formatPointer(instLoc), formatPointer(schemaLoc + ["type"])))
        }
    }

    // enum
    if case .array(let enumArr)? = sObj["enum"] {
        var found = false
        for e in enumArr { if deepEqual(instance, e) { found = true; break } }
        if !found {
            errors.insert((formatPointer(instLoc), formatPointer(schemaLoc + ["enum"])))
        }
    }

    // const
    if let constVal = sObj["const"] {
        if !deepEqual(instance, constVal) {
            errors.insert((formatPointer(instLoc), formatPointer(schemaLoc + ["const"])))
        }
    }

    // Number keywords
    if case .number(let num) = instance {
        if case .number(let v)? = sObj["minimum"] {
            if num < v { errors.insert((formatPointer(instLoc), formatPointer(schemaLoc + ["minimum"]))) }
        }
        if case .number(let v)? = sObj["maximum"] {
            if num > v { errors.insert((formatPointer(instLoc), formatPointer(schemaLoc + ["maximum"]))) }
        }
        if case .number(let v)? = sObj["exclusiveMinimum"] {
            if num <= v { errors.insert((formatPointer(instLoc), formatPointer(schemaLoc + ["exclusiveMinimum"]))) }
        }
        if case .number(let v)? = sObj["exclusiveMaximum"] {
            if num >= v { errors.insert((formatPointer(instLoc), formatPointer(schemaLoc + ["exclusiveMaximum"]))) }
        }
    }

    // String keywords
    if case .string(let s) = instance {
        let len = s.count
        if case .number(let v)? = sObj["minLength"] {
            if Double(len) < v { errors.insert((formatPointer(instLoc), formatPointer(schemaLoc + ["minLength"]))) }
        }
        if case .number(let v)? = sObj["maxLength"] {
            if Double(len) > v { errors.insert((formatPointer(instLoc), formatPointer(schemaLoc + ["maxLength"]))) }
        }
    }

    // Array keywords
    if case .array(let arr) = instance {
        if case .number(let v)? = sObj["minItems"] {
            if Double(arr.count) < v { errors.insert((formatPointer(instLoc), formatPointer(schemaLoc + ["minItems"]))) }
        }
        if case .number(let v)? = sObj["maxItems"] {
            if Double(arr.count) > v { errors.insert((formatPointer(instLoc), formatPointer(schemaLoc + ["maxItems"]))) }
        }
        if case .bool(let b)? = sObj["uniqueItems"], b {
            outer: for i in 0..<arr.count {
                for j in (i+1)..<arr.count {
                    if deepEqual(arr[i], arr[j]) {
                        errors.insert((formatPointer(instLoc), formatPointer(schemaLoc + ["uniqueItems"])))
                        break outer
                    }
                }
            }
        }
        var prefixLen = 0
        if case .array(let prefixSchemas)? = sObj["prefixItems"] {
            prefixLen = prefixSchemas.count
            for i in 0..<min(arr.count, prefixSchemas.count) {
                let sub = validate(instance: arr[i], schema: prefixSchemas[i],
                                   instLoc: instLoc + [String(i)],
                                   schemaLoc: schemaLoc + ["prefixItems", String(i)],
                                   rootSchema: rootSchema)
                errors.formUnion(sub)
            }
        }
        if let itemsSchema = sObj["items"] {
            for i in prefixLen..<arr.count {
                let sub = validate(instance: arr[i], schema: itemsSchema,
                                   instLoc: instLoc + [String(i)],
                                   schemaLoc: schemaLoc + ["items"],
                                   rootSchema: rootSchema)
                errors.formUnion(sub)
            }
        }
    }

    // Object keywords
    if case .object(let obj) = instance {
        var propKeys: Set<String> = []
        if case .object(let props)? = sObj["properties"] {
            propKeys = Set(props.keys)
            for (key, propSchema) in props {
                if let memberVal = obj[key] {
                    let sub = validate(instance: memberVal, schema: propSchema,
                                       instLoc: instLoc + [key],
                                       schemaLoc: schemaLoc + ["properties", key],
                                       rootSchema: rootSchema)
                    errors.formUnion(sub)
                }
            }
        }
        if case .array(let reqArr)? = sObj["required"] {
            for (j, reqVal) in reqArr.enumerated() {
                if case .string(let name) = reqVal {
                    if obj[name] == nil {
                        errors.insert((formatPointer(instLoc), formatPointer(schemaLoc + ["required", String(j)])))
                    }
                }
            }
        }
        if let addPropsSchema = sObj["additionalProperties"] {
            for (key, val) in obj {
                if !propKeys.contains(key) {
                    let sub = validate(instance: val, schema: addPropsSchema,
                                       instLoc: instLoc + [key],
                                       schemaLoc: schemaLoc + ["additionalProperties"],
                                       rootSchema: rootSchema)
                    errors.formUnion(sub)
                }
            }
        }
        if case .number(let v)? = sObj["minProperties"] {
            if Double(obj.count) < v { errors.insert((formatPointer(instLoc), formatPointer(schemaLoc + ["minProperties"]))) }
        }
        if case .number(let v)? = sObj["maxProperties"] {
            if Double(obj.count) > v { errors.insert((formatPointer(instLoc), formatPointer(schemaLoc + ["maxProperties"]))) }
        }
    }

    // Applicators

    // allOf
    if case .array(let allOfArr)? = sObj["allOf"] {
        for (i, subSchema) in allOfArr.enumerated() {
            let sub = validate(instance: instance, schema: subSchema,
                               instLoc: instLoc,
                               schemaLoc: schemaLoc + ["allOf", String(i)],
                               rootSchema: rootSchema)
            errors.formUnion(sub)
        }
    }

    // anyOf
    if case .array(let anyOfArr)? = sObj["anyOf"] {
        var anyAccepted = false
        for subSchema in anyOfArr {
            let sub = validate(instance: instance, schema: subSchema,
                               instLoc: instLoc,
                               schemaLoc: schemaLoc + ["anyOf", "0"],
                               rootSchema: rootSchema)
            if sub.isEmpty { anyAccepted = true; break }
        }
        if !anyAccepted {
            errors.insert((formatPointer(instLoc), formatPointer(schemaLoc + ["anyOf"])))
        }
    }

    // oneOf
    if case .array(let oneOfArr)? = sObj["oneOf"] {
        var count = 0
        for subSchema in oneOfArr {
            let sub = validate(instance: instance, schema: subSchema,
                               instLoc: instLoc,
                               schemaLoc: schemaLoc + ["oneOf", "0"],
                               rootSchema: rootSchema)
            if sub.isEmpty { count += 1 }
        }
        if count != 1 {
            errors.insert((formatPointer(instLoc), formatPointer(schemaLoc + ["oneOf"])))
        }
    }

    // not
    if let notSchema = sObj["not"] {
        let sub = validate(instance: instance, schema: notSchema,
                           instLoc: instLoc,
                           schemaLoc: schemaLoc + ["not"],
                           rootSchema: rootSchema)
        if sub.isEmpty {
            errors.insert((formatPointer(instLoc), formatPointer(schemaLoc + ["not"])))
        }
    }

    // if/then/else
    if let ifSchema = sObj["if"] {
        let ifErrors = validate(instance: instance, schema: ifSchema,
                                instLoc: instLoc,
                                schemaLoc: schemaLoc + ["if"],
                                rootSchema: rootSchema)
        if ifErrors.isEmpty {
            if let thenSchema = sObj["then"] {
                let sub = validate(instance: instance, schema: thenSchema,
                                   instLoc: instLoc,
                                   schemaLoc: schemaLoc + ["then"],
                                   rootSchema: rootSchema)
                errors.formUnion(sub)
            }
        } else {
            if let elseSchema = sObj["else"] {
                let sub = validate(instance: instance, schema: elseSchema,
                                   instLoc: instLoc,
                                   schemaLoc: schemaLoc + ["else"],
                                   rootSchema: rootSchema)
                errors.formUnion(sub)
            }
        }
    }

    // $ref
    if case .string(let ref)? = sObj["$ref"] {
        let (refSchema, refLoc) = resolveRef(ref, rootSchema)
        let sub = validate(instance: instance, schema: refSchema,
                           instLoc: instLoc,
                           schemaLoc: refLoc,
                           rootSchema: rootSchema)
        errors.formUnion(sub)
    }

    return errors
}

// MARK: - UTF-8 byte comparison for sorting

func utf8Less(_ a: String, _ b: String) -> Bool {
    let ab = Array(a.utf8)
    let bb = Array(b.utf8)
    let n = min(ab.count, bb.count)
    for i in 0..<n {
        if ab[i] < bb[i] { return true }
        if ab[i] > bb[i] { return false }
    }
    return ab.count < bb.count
}

// MARK: - Main

let args = CommandLine.arguments
guard args.count >= 2 else { fatalError("Usage: main <dir>") }
let dir = args[1]

let schemaStr = try! String(contentsOfFile: dir + "/schema.json", encoding: .utf8)
let instancesStr = try! String(contentsOfFile: dir + "/instances.json", encoding: .utf8)

var sp = JSONParser(schemaStr)
let schema = sp.parse()

var ip = JSONParser(instancesStr)
let instancesVal = ip.parse()

guard case .array(let instArr) = instancesVal else { fatalError("instances must be array") }

var validCount = 0
var invalidCount = 0
var outputLines: [String] = []

for (n, inst) in instArr.enumerated() {
    let errors = validate(instance: inst, schema: schema,
                          instLoc: [], schemaLoc: [], rootSchema: schema)
    if errors.isEmpty {
        outputLines.append("\(n): valid")
        validCount += 1
    } else {
        outputLines.append("\(n): invalid (\(errors.count))")
        let sorted = errors.sorted { (a, b) in
            if utf8Less(a.0, b.0) { return true }
            if utf8Less(b.0, a.0) { return false }
            return utf8Less(a.1, b.1)
        }
        for (instLoc, schemaLoc) in sorted {
            outputLines.append("  \(instLoc) \(schemaLoc)")
        }
        invalidCount += 1
    }
}

outputLines.append("valid=\(validCount) invalid=\(invalidCount)")
print(outputLines.joined(separator: "\n"))

import Foundation

// MARK: - JSON Value

indirect enum JSONValue {
    case null
    case bool(Bool)
    case number(Double)
    case string(String)
    case array([JSONValue])
    case object([(String, JSONValue)])
}

// MARK: - JSON Parser

struct JSONParser {
    let input: [Character]
    var pos: Int = 0

    init(_ s: String) {
        input = Array(s)
    }

    mutating func parse() -> JSONValue {
        skipWS()
        let v = parseValue()
        skipWS()
        return v
    }

    mutating func skipWS() {
        while pos < input.count {
            let c = input[pos]
            if c == " " || c == "\t" || c == "\n" || c == "\r" { pos += 1 }
            else { break }
        }
    }

    mutating func parseValue() -> JSONValue {
        skipWS()
        guard pos < input.count else { fatalError("EOF") }
        switch input[pos] {
        case "{": return parseObject()
        case "[": return parseArray()
        case "\"": return .string(parseString())
        case "t": pos += 4; return .bool(true)
        case "f": pos += 5; return .bool(false)
        case "n": pos += 4; return .null
        default: return parseNumber()
        }
    }

    mutating func parseObject() -> JSONValue {
        pos += 1
        var obj: [(String, JSONValue)] = []
        skipWS()
        if pos < input.count && input[pos] == "}" { pos += 1; return .object(obj) }
        while true {
            skipWS()
            let key = parseString()
            skipWS()
            pos += 1 // ':'
            let val = parseValue()
            obj.append((key, val))
            skipWS()
            if pos < input.count && input[pos] == "," { pos += 1 } else { break }
        }
        skipWS()
        pos += 1 // '}'
        return .object(obj)
    }

    mutating func parseArray() -> JSONValue {
        pos += 1
        var arr: [JSONValue] = []
        skipWS()
        if pos < input.count && input[pos] == "]" { pos += 1; return .array(arr) }
        while true {
            arr.append(parseValue())
            skipWS()
            if pos < input.count && input[pos] == "," { pos += 1 } else { break }
        }
        skipWS()
        pos += 1 // ']'
        return .array(arr)
    }

    mutating func parseString() -> String {
        pos += 1 // opening "
        var result = ""
        while pos < input.count && input[pos] != "\"" {
            if input[pos] == "\\" {
                pos += 1
                switch input[pos] {
                case "\"": result.append("\""); pos += 1
                case "\\": result.append("\\"); pos += 1
                case "/": result.append("/"); pos += 1
                case "b": result.append("\u{08}"); pos += 1
                case "f": result.append("\u{0C}"); pos += 1
                case "n": result.append("\n"); pos += 1
                case "r": result.append("\r"); pos += 1
                case "t": result.append("\t"); pos += 1
                case "u":
                    pos += 1
                    let code = parseHex4()
                    if code >= 0xD800 && code <= 0xDBFF {
                        pos += 1 // '\'
                        pos += 1 // 'u'
                        let low = parseHex4()
                        let cp = 0x10000 + (code - 0xD800) * 0x400 + (low - 0xDC00)
                        result.append(Character(UnicodeScalar(cp)!))
                    } else {
                        result.append(Character(UnicodeScalar(code)!))
                    }
                default: fatalError("bad escape")
                }
            } else {
                result.append(input[pos])
                pos += 1
            }
        }
        pos += 1 // closing "
        return result
    }

    mutating func parseHex4() -> UInt32 {
        var val: UInt32 = 0
        for _ in 0..<4 {
            val <<= 4
            let c = input[pos]
            if c >= "0" && c <= "9" { val += UInt32(c.asciiValue! - 48) }
            else if c >= "a" && c <= "f" { val += UInt32(c.asciiValue! - 87) }
            else if c >= "A" && c <= "F" { val += UInt32(c.asciiValue! - 55) }
            else { fatalError("bad hex") }
            pos += 1
        }
        return val
    }

    mutating func parseNumber() -> JSONValue {
        let start = pos
        if pos < input.count && input[pos] == "-" { pos += 1 }
        if pos < input.count && input[pos] == "0" {
            pos += 1
        } else {
            while pos < input.count && input[pos] >= "0" && input[pos] <= "9" { pos += 1 }
        }
        if pos < input.count && input[pos] == "." {
            pos += 1
            while pos < input.count && input[pos] >= "0" && input[pos] <= "9" { pos += 1 }
        }
        if pos < input.count && (input[pos] == "e" || input[pos] == "E") {
            pos += 1
            if pos < input.count && (input[pos] == "+" || input[pos] == "-") { pos += 1 }
            while pos < input.count && input[pos] >= "0" && input[pos] <= "9" { pos += 1 }
        }
        let s = String(input[start..<pos])
        return .number(Double(s)!)
    }
}

// MARK: - Object helpers

func objLookup(_ obj: [(String, JSONValue)], _ key: String) -> JSONValue? {
    for (k, v) in obj {
        if k.unicodeScalars.elementsEqual(key.unicodeScalars) { return v }
    }
    return nil
}

func objKeys(_ obj: [(String, JSONValue)]) -> [String] {
    return obj.map { $0.0 }
}

// MARK: - Deep Equality

func deepEqual(_ a: JSONValue, _ b: JSONValue) -> Bool {
    switch (a, b) {
    case (.null, .null): return true
    case (.bool(let x), .bool(let y)): return x == y
    case (.number(let x), .number(let y)): return x == y
    case (.string(let x), .string(let y)):
        return x.unicodeScalars.elementsEqual(y.unicodeScalars)
    case (.array(let x), .array(let y)):
        if x.count != y.count { return false }
        for i in 0..<x.count { if !deepEqual(x[i], y[i]) { return false } }
        return true
    case (.object(let x), .object(let y)):
        if x.count != y.count { return false }
        for (k, v) in x {
            guard let w = objLookup(y, k) else { return false }
            if !deepEqual(v, w) { return false }
        }
        return true
    default: return false
    }
}

// MARK: - JSON Pointer Formatting

func formatPointer(_ tokens: [String]) -> String {
    var r = "#"
    for t in tokens {
        let esc = t.replacingOccurrences(of: "~", with: "~0")
                   .replacingOccurrences(of: "/", with: "~1")
        r += "/" + esc
    }
    return r
}

// MARK: - Type Checking

func matchesType(_ inst: JSONValue, _ typeName: String) -> Bool {
    switch (inst, typeName) {
    case (.null, "null"): return true
    case (.bool(_), "boolean"): return true
    case (.number(_), "number"): return true
    case (.number(let n), "integer"): return n == n.rounded(.down)
    case (.string(_), "string"): return true
    case (.array(_), "array"): return true
    case (.object(_), "object"): return true
    default: return false
    }
}

func checkType(_ inst: JSONValue, _ typeVal: JSONValue) -> Bool {
    var names: [String] = []
    switch typeVal {
    case .string(let s): names = [s]
    case .array(let arr):
        for v in arr { if case .string(let s) = v { names.append(s) } }
    default: return true
    }
    for n in names { if matchesType(inst, n) { return true } }
    return false
}

// MARK: - $ref Resolution

func resolveRef(_ ref: String, _ rootSchema: JSONValue) -> (JSONValue, [String]) {
    if ref == "#" { return (rootSchema, []) }
    let prefix = "#/$defs/"
    if ref.hasPrefix(prefix) {
        let encoded = String(ref.dropFirst(prefix.count))
        let name = encoded.replacingOccurrences(of: "~1", with: "/")
                          .replacingOccurrences(of: "~0", with: "~")
        if case .object(let rootObj) = rootSchema,
           case .object(let defs)? = objLookup(rootObj, "$defs"),
           let target = objLookup(defs, name) {
            return (target, ["$defs", name])
        }
    }
    fatalError("Cannot resolve: \(ref)")
}

// MARK: - Error Pair

struct ErrorPair: Hashable {
    let inst: String
    let schema: String
}

// MARK: - Validator

func validate(instance: JSONValue, schema: JSONValue,
              instLoc: [String], schemaLoc: [String],
              rootSchema: JSONValue) -> Set<ErrorPair> {
    var errors = Set<ErrorPair>()

    if case .bool(let b) = schema {
        if !b { errors.insert(ErrorPair(inst: formatPointer(instLoc), schema: formatPointer(schemaLoc))) }
        return errors
    }

    guard case .object(let sObj) = schema else { return errors }

    // type
    if let typeVal = objLookup(sObj, "type") {
        if !checkType(instance, typeVal) {
            errors.insert(ErrorPair(inst: formatPointer(instLoc), schema: formatPointer(schemaLoc + ["type"])))
        }
    }

    // enum
    if case .array(let enumArr)? = objLookup(sObj, "enum") {
        var found = false
        for e in enumArr { if deepEqual(instance, e) { found = true; break } }
        if !found {
            errors.insert(ErrorPair(inst: formatPointer(instLoc), schema: formatPointer(schemaLoc + ["enum"])))
        }
    }

    // const
    if let constVal = objLookup(sObj, "const") {
        if !deepEqual(instance, constVal) {
            errors.insert(ErrorPair(inst: formatPointer(instLoc), schema: formatPointer(schemaLoc + ["const"])))
        }
    }

    // Number keywords
    if case .number(let num) = instance {
        if case .number(let v)? = objLookup(sObj, "minimum") {
            if num < v { errors.insert(ErrorPair(inst: formatPointer(instLoc), schema: formatPointer(schemaLoc + ["minimum"]))) }
        }
        if case .number(let v)? = objLookup(sObj, "maximum") {
            if num > v { errors.insert(ErrorPair(inst: formatPointer(instLoc), schema: formatPointer(schemaLoc + ["maximum"]))) }
        }
        if case .number(let v)? = objLookup(sObj, "exclusiveMinimum") {
            if num <= v { errors.insert(ErrorPair(inst: formatPointer(instLoc), schema: formatPointer(schemaLoc + ["exclusiveMinimum"]))) }
        }
        if case .number(let v)? = objLookup(sObj, "exclusiveMaximum") {
            if num >= v { errors.insert(ErrorPair(inst: formatPointer(instLoc), schema: formatPointer(schemaLoc + ["exclusiveMaximum"]))) }
        }
    }

    // String keywords
    if case .string(let s) = instance {
        let len = s.unicodeScalars.count
        if case .number(let v)? = objLookup(sObj, "minLength") {
            if Double(len) < v { errors.insert(ErrorPair(inst: formatPointer(instLoc), schema: formatPointer(schemaLoc + ["minLength"]))) }
        }
        if case .number(let v)? = objLookup(sObj, "maxLength") {
            if Double(len) > v { errors.insert(ErrorPair(inst: formatPointer(instLoc), schema: formatPointer(schemaLoc + ["maxLength"]))) }
        }
    }

    // Array keywords
    if case .array(let arr) = instance {
        if case .number(let v)? = objLookup(sObj, "minItems") {
            if Double(arr.count) < v { errors.insert(ErrorPair(inst: formatPointer(instLoc), schema: formatPointer(schemaLoc + ["minItems"]))) }
        }
        if case .number(let v)? = objLookup(sObj, "maxItems") {
            if Double(arr.count) > v { errors.insert(ErrorPair(inst: formatPointer(instLoc), schema: formatPointer(schemaLoc + ["maxItems"]))) }
        }
        if case .bool(let b)? = objLookup(sObj, "uniqueItems"), b {
            outer: for i in 0..<arr.count {
                for j in (i+1)..<arr.count {
                    if deepEqual(arr[i], arr[j]) {
                        errors.insert(ErrorPair(inst: formatPointer(instLoc), schema: formatPointer(schemaLoc + ["uniqueItems"])))
                        break outer
                    }
                }
            }
        }
        var prefixLen = 0
        if case .array(let prefixSchemas)? = objLookup(sObj, "prefixItems") {
            prefixLen = prefixSchemas.count
            for i in 0..<min(arr.count, prefixSchemas.count) {
                let sub = validate(instance: arr[i], schema: prefixSchemas[i],
                                   instLoc: instLoc + [String(i)],
                                   schemaLoc: schemaLoc + ["prefixItems", String(i)],
                                   rootSchema: rootSchema)
                errors.formUnion(sub)
            }
        }
        if let itemsSchema = objLookup(sObj, "items") {
            for i in prefixLen..<arr.count {
                let sub = validate(instance: arr[i], schema: itemsSchema,
                                   instLoc: instLoc + [String(i)],
                                   schemaLoc: schemaLoc + ["items"],
                                   rootSchema: rootSchema)
                errors.formUnion(sub)
            }
        }
    }

    // Object keywords
    if case .object(let obj) = instance {
        var propKeys: [String] = []
        if case .object(let props)? = objLookup(sObj, "properties") {
            propKeys = objKeys(props)
            for (key, propSchema) in props {
                if let memberVal = objLookup(obj, key) {
                    let sub = validate(instance: memberVal, schema: propSchema,
                                       instLoc: instLoc + [key],
                                       schemaLoc: schemaLoc + ["properties", key],
                                       rootSchema: rootSchema)
                    errors.formUnion(sub)
                }
            }
        }
        if case .array(let reqArr)? = objLookup(sObj, "required") {
            for (j, reqVal) in reqArr.enumerated() {
                if case .string(let name) = reqVal {
                    if objLookup(obj, name) == nil {
                        errors.insert(ErrorPair(inst: formatPointer(instLoc), schema: formatPointer(schemaLoc + ["required", String(j)])))
                    }
                }
            }
        }
        if let addPropsSchema = objLookup(sObj, "additionalProperties") {
            for (key, val) in obj {
                var inProps = false
                for pk in propKeys {
                    if pk.unicodeScalars.elementsEqual(key.unicodeScalars) { inProps = true; break }
                }
                if !inProps {
                    let sub = validate(instance: val, schema: addPropsSchema,
                                       instLoc: instLoc + [key],
                                       schemaLoc: schemaLoc + ["additionalProperties"],
                                       rootSchema: rootSchema)
                    errors.formUnion(sub)
                }
            }
        }
        if case .number(let v)? = objLookup(sObj, "minProperties") {
            if Double(obj.count) < v { errors.insert(ErrorPair(inst: formatPointer(instLoc), schema: formatPointer(schemaLoc + ["minProperties"]))) }
        }
        if case .number(let v)? = objLookup(sObj, "maxProperties") {
            if Double(obj.count) > v { errors.insert(ErrorPair(inst: formatPointer(instLoc), schema: formatPointer(schemaLoc + ["maxProperties"]))) }
        }
    }

    // Applicators

    // allOf
    if case .array(let allOfArr)? = objLookup(sObj, "allOf") {
        for (i, subSchema) in allOfArr.enumerated() {
            let sub = validate(instance: instance, schema: subSchema,
                               instLoc: instLoc,
                               schemaLoc: schemaLoc + ["allOf", String(i)],
                               rootSchema: rootSchema)
            errors.formUnion(sub)
        }
    }

    // anyOf
    if case .array(let anyOfArr)? = objLookup(sObj, "anyOf") {
        var anyAccepted = false
        for (i, subSchema) in anyOfArr.enumerated() {
            let sub = validate(instance: instance, schema: subSchema,
                               instLoc: instLoc,
                               schemaLoc: schemaLoc + ["anyOf", String(i)],
                               rootSchema: rootSchema)
            if sub.isEmpty { anyAccepted = true; break }
        }
        if !anyAccepted {
            errors.insert(ErrorPair(inst: formatPointer(instLoc), schema: formatPointer(schemaLoc + ["anyOf"])))
        }
    }

    // oneOf
    if case .array(let oneOfArr)? = objLookup(sObj, "oneOf") {
        var count = 0
        for (i, subSchema) in oneOfArr.enumerated() {
            let sub = validate(instance: instance, schema: subSchema,
                               instLoc: instLoc,
                               schemaLoc: schemaLoc + ["oneOf", String(i)],
                               rootSchema: rootSchema)
            if sub.isEmpty { count += 1 }
        }
        if count != 1 {
            errors.insert(ErrorPair(inst: formatPointer(instLoc), schema: formatPointer(schemaLoc + ["oneOf"])))
        }
    }

    // not
    if let notSchema = objLookup(sObj, "not") {
        let sub = validate(instance: instance, schema: notSchema,
                           instLoc: instLoc,
                           schemaLoc: schemaLoc + ["not"],
                           rootSchema: rootSchema)
        if sub.isEmpty {
            errors.insert(ErrorPair(inst: formatPointer(instLoc), schema: formatPointer(schemaLoc + ["not"])))
        }
    }

    // if/then/else
    if let ifSchema = objLookup(sObj, "if") {
        let ifErrors = validate(instance: instance, schema: ifSchema,
                                instLoc: instLoc,
                                schemaLoc: schemaLoc + ["if"],
                                rootSchema: rootSchema)
        if ifErrors.isEmpty {
            if let thenSchema = objLookup(sObj, "then") {
                let sub = validate(instance: instance, schema: thenSchema,
                                   instLoc: instLoc,
                                   schemaLoc: schemaLoc + ["then"],
                                   rootSchema: rootSchema)
                errors.formUnion(sub)
            }
        } else {
            if let elseSchema = objLookup(sObj, "else") {
                let sub = validate(instance: instance, schema: elseSchema,
                                   instLoc: instLoc,
                                   schemaLoc: schemaLoc + ["else"],
                                   rootSchema: rootSchema)
                errors.formUnion(sub)
            }
        }
    }

    // $ref
    if case .string(let ref)? = objLookup(sObj, "$ref") {
        let (refSchema, refLoc) = resolveRef(ref, rootSchema)
        let sub = validate(instance: instance, schema: refSchema,
                           instLoc: instLoc,
                           schemaLoc: refLoc,
                           rootSchema: rootSchema)
        errors.formUnion(sub)
    }

    return errors
}

// MARK: - UTF-8 byte comparison for sorting

func utf8Less(_ a: String, _ b: String) -> Bool {
    let ab = Array(a.utf8)
    let bb = Array(b.utf8)
    let n = min(ab.count, bb.count)
    for i in 0..<n {
        if ab[i] < bb[i] { return true }
        if ab[i] > bb[i] { return false }
    }
    return ab.count < bb.count
}

// MARK: - Main

let args = CommandLine.arguments
guard args.count >= 2 else { fatalError("Usage: main <dir>") }
let dir = args[1]

let schemaStr = try! String(contentsOfFile: dir + "/schema.json", encoding: .utf8)
let instancesStr = try! String(contentsOfFile: dir + "/instances.json", encoding: .utf8)

var sp = JSONParser(schemaStr)
let schema = sp.parse()

var ip = JSONParser(instancesStr)
let instancesVal = ip.parse()

guard case .array(let instArr) = instancesVal else { fatalError("instances must be array") }

var validCount = 0
var invalidCount = 0
var outputLines: [String] = []

for (n, inst) in instArr.enumerated() {
    let errors = validate(instance: inst, schema: schema,
                          instLoc: [], schemaLoc: [], rootSchema: schema)
    if errors.isEmpty {
        outputLines.append("\(n): valid")
        validCount += 1
    } else {
        outputLines.append("\(n): invalid (\(errors.count))")
        let sorted = errors.sorted { (a, b) in
            if utf8Less(a.inst, b.inst) { return true }
            if utf8Less(b.inst, a.inst) { return false }
            return utf8Less(a.schema, b.schema)
        }
        for ep in sorted {
            outputLines.append("  \(ep.inst) \(ep.schema)")
        }
        invalidCount += 1
    }
}

outputLines.append("valid=\(validCount) invalid=\(invalidCount)")
print(outputLines.joined(separator: "\n"))

