// ============ CommonCrypto FFI ============

const CC_SHA256_LEN: usize = 32;
const CC_SHA384_LEN: usize = 48;
const CC_SHA512_LEN: usize = 64;

const kCCHmacAlgSHA256: i32 = 2;
const kCCHmacAlgSHA384: i32 = 3;
const kCCHmacAlgSHA512: i32 = 4;

#[link(name = "System", kind = "dylib")]
extern "C" {
    fn CCHmac(algorithm: i32, key: *const u8, key_len: usize, data: *const u8, data_len: usize, mac_out: *mut u8);
}

fn hmac(alg: &str, key: &[u8], data: &[u8]) -> Vec<u8> {
    let (cc_alg, mac_len) = match alg {
        "HS256" => (kCCHmacAlgSHA256, CC_SHA256_LEN),
        "HS384" => (kCCHmacAlgSHA384, CC_SHA384_LEN),
        "HS512" => (kCCHmacAlgSHA512, CC_SHA512_LEN),
        _ => unreachable!(),
    };
    let mut mac = vec![0u8; mac_len];
    unsafe {
        CCHmac(cc_alg, key.as_ptr(), key.len(), data.as_ptr(), data.len(), mac.as_mut_ptr());
    }
    mac
}

// ============ JSON Parser ============

#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    Str(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

impl JsonValue {
    fn get(&self, key: &str) -> Option<&JsonValue> {
        if let JsonValue::Object(pairs) = self {
            for (k, v) in pairs {
                if k == key { return Some(v); }
            }
        }
        None
    }
    fn as_str(&self) -> Option<&str> {
        if let JsonValue::Str(s) = self { Some(s) } else { None }
    }
    fn as_f64(&self) -> Option<f64> {
        if let JsonValue::Number(n) = self { Some(*n) } else { None }
    }
    fn as_array(&self) -> Option<&[JsonValue]> {
        if let JsonValue::Array(a) = self { Some(a) } else { None }
    }
}

struct JsonParser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> JsonParser<'a> {
    fn new(input: &'a str) -> Self {
        JsonParser { input: input.as_bytes(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn peek(&self) -> Option<u8> {
        if self.pos < self.input.len() { Some(self.input[self.pos]) } else { None }
    }

    fn parse_value(&mut self) -> Result<JsonValue, String> {
        self.skip_ws();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => self.parse_string().map(JsonValue::Str),
            Some(b't') => self.parse_lit(b"true").map(|_| JsonValue::Bool(true)),
            Some(b'f') => self.parse_lit(b"false").map(|_| JsonValue::Bool(false)),
            Some(b'n') => self.parse_lit(b"null").map(|_| JsonValue::Null),
            Some(c) if c == b'-' || c.is_ascii_digit() => self.parse_number(),
            _ => Err(format!("unexpected char at pos {}", self.pos)),
        }
    }

    fn parse_lit(&mut self, lit: &[u8]) -> Result<(), String> {
        if self.input[self.pos..].starts_with(lit) {
            self.pos += lit.len();
            Ok(())
        } else {
            Err("literal mismatch".to_string())
        }
    }

    fn parse_object(&mut self) -> Result<JsonValue, String> {
        self.pos += 1;
        let mut pairs = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b'}') { self.pos += 1; return Ok(JsonValue::Object(pairs)); }
        loop {
            self.skip_ws();
            let key = self.parse_string()?;
            self.skip_ws();
            if self.peek() != Some(b':') { return Err("expected :".to_string()); }
            self.pos += 1;
            let value = self.parse_value()?;
            pairs.push((key, value));
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b'}') => { self.pos += 1; return Ok(JsonValue::Object(pairs)); }
                _ => return Err("expected , or }".to_string()),
            }
        }
    }

    fn parse_array(&mut self) -> Result<JsonValue, String> {
        self.pos += 1;
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b']') { self.pos += 1; return Ok(JsonValue::Array(items)); }
        loop {
            let value = self.parse_value()?;
            items.push(value);
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b']') => { self.pos += 1; return Ok(JsonValue::Array(items)); }
                _ => return Err("expected , or ]".to_string()),
            }
        }
    }

    fn parse_string(&mut self) -> Result<String, String> {
        if self.peek() != Some(b'"') { return Err("expected string".to_string()); }
        self.pos += 1;
        let mut bytes: Vec<u8> = Vec::new();
        loop {
            if self.pos >= self.input.len() { return Err("unterminated string".to_string()); }
            let c = self.input[self.pos];
            match c {
                b'"' => { self.pos += 1; return String::from_utf8(bytes).map_err(|_| "invalid utf8".to_string()); }
                b'\\' => {
                    self.pos += 1;
                    if self.pos >= self.input.len() { return Err("unterminated escape".to_string()); }
                    let esc = self.input[self.pos];
                    self.pos += 1;
                    match esc {
                        b'"' => bytes.push(b'"'),
                        b'\\' => bytes.push(b'\\'),
                        b'/' => bytes.push(b'/'),
                        b'b' => bytes.push(0x08),
                        b'f' => bytes.push(0x0C),
                        b'n' => bytes.push(b'\n'),
                        b'r' => bytes.push(b'\r'),
                        b't' => bytes.push(b'\t'),
                        b'u' => {
                            let cp = self.parse_hex4()?;
                            if (0xD800..0xDC00).contains(&cp) {
                                if self.pos + 1 < self.input.len() && self.input[self.pos] == b'\\' && self.input[self.pos + 1] == b'u' {
                                    self.pos += 2;
                                    let cp2 = self.parse_hex4()?;
                                    if (0xDC00..0xE000).contains(&cp2) {
                                        let combined = 0x10000 + ((cp - 0xD800) << 10) + (cp2 - 0xDC00);
                                        let ch = char::from_u32(combined).unwrap_or('\u{FFFD}');
                                        let mut buf = [0u8; 4];
                                        bytes.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                                    } else {
                                        bytes.extend_from_slice("\u{FFFD}".as_bytes());
                                        bytes.extend_from_slice("\u{FFFD}".as_bytes());
                                    }
                                } else {
                                    bytes.extend_from_slice("\u{FFFD}".as_bytes());
                                }
                            } else {
                                let ch = char::from_u32(cp).unwrap_or('\u{FFFD}');
                                let mut buf = [0u8; 4];
                                bytes.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                            }
                        }
                        _ => return Err("invalid escape".to_string()),
                    }
                }
                _ => { bytes.push(c); self.pos += 1; }
            }
        }
    }

    fn parse_hex4(&mut self) -> Result<u32, String> {
        if self.pos + 4 > self.input.len() { return Err("unexpected end in \\u".to_string()); }
        let hex = std::str::from_utf8(&self.input[self.pos..self.pos + 4]).map_err(|_| "invalid hex".to_string())?;
        self.pos += 4;
        u32::from_str_radix(hex, 16).map_err(|_| "invalid hex".to_string())
    }

    fn parse_number(&mut self) -> Result<JsonValue, String> {
        let start = self.pos;
        if self.peek() == Some(b'-') { self.pos += 1; }
        while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        if self.pos < self.input.len() && self.input[self.pos] == b'.' {
            self.pos += 1;
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        if self.pos < self.input.len() && (self.input[self.pos] == b'e' || self.input[self.pos] == b'E') {
            self.pos += 1;
            if self.pos < self.input.len() && (self.input[self.pos] == b'+' || self.input[self.pos] == b'-') { self.pos += 1; }
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        let s = std::str::from_utf8(&self.input[start..self.pos]).map_err(|_| "invalid number".to_string())?;
        let n: f64 = s.parse().map_err(|_| "invalid number".to_string())?;
        Ok(JsonValue::Number(n))
    }
}

fn parse_json(s: &str) -> Result<JsonValue, String> {
    let mut parser = JsonParser::new(s);
    let val = parser.parse_value()?;
    parser.skip_ws();
    if parser.pos != parser.input.len() { return Err("trailing content".to_string()); }
    Ok(val)
}

// ============ Base64url ============

fn base64url_valid(s: &str) -> bool {
    if s.len() % 4 == 1 { return false; }
    s.as_bytes().iter().all(|&c| match c {
        b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' => true,
        _ => false,
    })
}

fn base64url_decode(s: &str) -> Option<Vec<u8>> {
    if !base64url_valid(s) { return None; }
    let mut result = Vec::new();
    let mut bits: u32 = 0;
    let mut nbits: u32 = 0;
    for &c in s.as_bytes() {
        let val: u32 = match c {
            b'A'..=b'Z' => (c - b'A') as u32,
            b'a'..=b'z' => (c - b'a' + 26) as u32,
            b'0'..=b'9' => (c - b'0' + 52) as u32,
            b'-' => 62,
            b'_' => 63,
            _ => return None,
        };
        bits = (bits << 6) | val;
        nbits += 6;
        if nbits >= 8 {
            nbits -= 8;
            result.push((bits >> nbits) as u8);
            bits &= (1u32 << nbits) - 1;
        }
    }
    Some(result)
}

// ============ Config ============

struct KeyEntry {
    kid: String,
    alg: String,
    k_bytes: Vec<u8>,
}

struct Config {
    now: f64,
    leeway: f64,
    issuer: String,
    audience: String,
    keys: Vec<KeyEntry>,
}

fn load_config(path: &str) -> Config {
    let content = fs::read_to_string(path).expect("cannot read config.json");
    let json = parse_json(&content).expect("invalid config.json");
    let now = json.get("now").and_then(|v| v.as_f64()).expect("missing now");
    let leeway = json.get("leeway").and_then(|v| v.as_f64()).expect("missing leeway");
    let issuer = json.get("issuer").and_then(|v| v.as_str()).expect("missing issuer").to_string();
    let audience = json.get("audience").and_then(|v| v.as_str()).expect("missing audience").to_string();
    let keys_json = json.get("keys").and_then(|v| v.as_array()).expect("missing keys");
    let mut keys = Vec::new();
    for k in keys_json {
        let kid = k.get("kid").and_then(|v| v.as_str()).expect("key missing kid").to_string();
        let alg = k.get("alg").and_then(|v| v.as_str()).expect("key missing alg").to_string();
        let k_str = k.get("k").and_then(|v| v.as_str()).expect("key missing k");
        let k_bytes = base64url_decode(k_str).expect("invalid k in key");
        keys.push(KeyEntry { kid, alg, k_bytes });
    }
    Config { now, leeway, issuer, audience, keys }
}

// ============ JWT Verification ============

fn verify_token(token: &str, config: &Config) -> String {
    // Rule 1: MALFORMED
    let parts: Vec<&str> = token.split('.').collect();
    if parts.len() != 3 { return "MALFORMED".to_string(); }
    for &p in &parts {
        if p.is_empty() { return "MALFORMED".to_string(); }
        if !base64url_valid(p) { return "MALFORMED".to_string(); }
    }
    let header_bytes = match base64url_decode(parts[0]) { Some(b) => b, None => return "MALFORMED".to_string() };
    let payload_bytes = match base64url_decode(parts[1]) { Some(b) => b, None => return "MALFORMED".to_string() };
    let sig_bytes = match base64url_decode(parts[2]) { Some(b) => b, None => return "MALFORMED".to_string() };

    let header_str = match String::from_utf8(header_bytes) { Ok(s) => s, Err(_) => return "MALFORMED".to_string() };
    let payload_str = match String::from_utf8(payload_bytes) { Ok(s) => s, Err(_) => return "MALFORMED".to_string() };

    let header = match parse_json(&header_str) { Ok(j) => j, Err(_) => return "MALFORMED".to_string() };
    let payload = match parse_json(&payload_str) { Ok(j) => j, Err(_) => return "MALFORMED".to_string() };

    if !matches!(header, JsonValue::Object(_)) { return "MALFORMED".to_string(); }
    if !matches!(payload, JsonValue::Object(_)) { return "MALFORMED".to_string(); }

    // Rule 2: UNSUPPORTED_ALG
    let alg = match header.get("alg") {
        Some(JsonValue::Str(s)) => {
            if s == "HS256" || s == "HS384" || s == "HS512" { s.clone() }
            else { return "UNSUPPORTED_ALG".to_string(); }
        }
        _ => return "UNSUPPORTED_ALG".to_string(),
    };

    // Rule 3: UNKNOWN_KEY
    let kid = match header.get("kid") {
        Some(JsonValue::Str(s)) => s.clone(),
        _ => return "UNKNOWN_KEY".to_string(),
    };
    let key_entry = match config.keys.iter().find(|k| k.kid == kid) {
        Some(k) => k,
        None => return "UNKNOWN_KEY".to_string(),
    };

    // Rule 4: ALG_MISMATCH
    if key_entry.alg != alg { return "ALG_MISMATCH".to_string(); }

    // Rule 5: BAD_SIGNATURE
    let signing_input = format!("{}.{}", parts[0], parts[1]);
    let expected_sig = hmac(&alg, &key_entry.k_bytes, signing_input.as_bytes());
    if sig_bytes != expected_sig { return "BAD_SIGNATURE".to_string(); }

    // Rule 6: EXPIRED
    if let Some(exp_val) = payload.get("exp") {
        if let Some(exp_num) = exp_val.as_f64() {
            if config.now >= exp_num + config.leeway { return "EXPIRED".to_string(); }
        }
    }

    // Rule 7: NOT_YET_VALID
    if let Some(nbf_val) = payload.get("nbf") {
        if let Some(nbf_num) = nbf_val.as_f64() {
            if config.now + config.leeway < nbf_num { return "NOT_YET_VALID".to_string(); }
        }
    }

    // Rule 8: BAD_ISSUER
    match payload.get("iss") {
        Some(JsonValue::Str(s)) if s == &config.issuer => {}
        _ => return "BAD_ISSUER".to_string(),
    }

    // Rule 9: BAD_AUDIENCE
    match payload.get("aud") {
        Some(JsonValue::Str(s)) => {
            if s != &config.audience { return "BAD_AUDIENCE".to_string(); }
        }
        Some(JsonValue::Array(arr)) => {
            let found = arr.iter().any(|item| {
                if let JsonValue::Str(s) = item { s == &config.audience } else { false }
            });
            if !found { return "BAD_AUDIENCE".to_string(); }
        }
        _ => return "BAD_AUDIENCE".to_string(),
    }

    // VALID
    let sub = payload.get("sub").and_then(|v| v.as_str()).unwrap_or("").to_string();
    let scopes_str = payload.get("scope").and_then(|v| v.as_str()).unwrap_or("");
    let mut scopes: Vec<String> = scopes_str.split(' ').filter(|s| !s.is_empty()).map(|s| s.to_string()).collect();
    scopes.sort();
    scopes.dedup();
    let scopes_joined = scopes.join(",");
    format!("VALID sub={} scope={}", sub, scopes_joined)
}

// ============ Main ============

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("usage: {} <dir>", args[0]);
        process::exit(1);
    }
    let dir = &args[1];
    let config_path = format!("{}/config.json", dir);
    let tokens_path = format!("{}/tokens.txt", dir);

    let config = load_config(&config_path);
    let tokens_content = fs::read_to_string(&tokens_path).expect("cannot read tokens.txt");

    let mut valid_count = 0usize;
    let mut invalid_count = 0usize;
    let mut output_lines: Vec<String> = Vec::new();
    let mut n = 0usize;

    for line in tokens_content.split('\n') {
        let trimmed = line.trim_matches(|c| c == ' ' || c == '\t' || c == '\r');
        if trimmed.is_empty() { continue; }
        n += 1;
        let result = verify_token(trimmed, &config);
        if result == "VALID" || result.starts_with("VALID ") {
            valid_count += 1;
        } else {
            invalid_count += 1;
        }
        output_lines.push(format!("{}: {}", n, result));
    }

    for line in &output_lines {
        println!("{}", line);
    }
    println!();
    println!("valid={} invalid={}", valid_count, invalid_count);
}

