    static JVal buildTextStatsOutputSchema() {
        JVal schema = new JVal(JVal.OBJ);
        schema.objVal.put("type", JVal.str("object"));
        JVal props = new JVal(JVal.OBJ);
        JVal wordsProp = new JVal(JVal.OBJ);
        wordsProp.objVal.put("type", JVal.str("integer"));
        props.objVal.put("words", wordsProp);
        JVal cpProp = new JVal(JVal.OBJ);
        cpProp.objVal.put("type", JVal.str("integer"));
