    static String handleToolsCall(JVal idVal, JVal paramsVal) {
        if (paramsVal == null || !paramsVal.objVal.containsKey("name")) {
            return errResponse(idVal, -32602, "Invalid params");
        }
        JVal nameVal = paramsVal.objVal.get("name");
        if (nameVal.type != JVal.STR) {
            return errResponse(idVal, -32602, "Invalid params");
        }
        String toolName = nameVal.strVal;
        String[] knownTools = {"kv_set","kv_get","kv_list","sum","text_stats"};
        boolean known = false;
        for (String t : knownTools) { if (t.equals(toolName)) { known = true; break; } }
        if (!known) {
            return errResponse(idVal, -32602, "Unknown tool: " + toolName);
        }

        JVal argsVal = paramsVal.objVal.containsKey("arguments") ? paramsVal.objVal.get("arguments") : null;
        boolean argsAbsent = !paramsVal.objVal.containsKey("arguments");
        if (!argsAbsent && (argsVal == null || argsVal.type != JVal.OBJ)) {
            return toolFailure("arguments must be an object");
        }
        LinkedHashMap<String, JVal> args = (argsAbsent || argsVal == null) ? new LinkedHashMap<>() : argsVal.objVal;

        // Define tool schemas: propNames, propTypes, propRequired, propMinLength, propMinItems
        String[] propNames;
        String[] propTypes;
        boolean[] propRequired;
        boolean[] propMinLength; // whether minLength:1 applies
        boolean[] propMinItems;  // whether minItems:1 applies

        switch (toolName) {
            case "kv_set":
                propNames = new String[]{"key","value"};
                propTypes = new String[]{"string","string"};
                propRequired = new boolean[]{true,true};
                propMinLength = new boolean[]{true,false};
                propMinItems = new boolean[]{false,false};
                break;
            case "kv_get":
                propNames = new String[]{"key"};
                propTypes = new String[]{"string"};
                propRequired = new boolean[]{true};
                propMinLength = new boolean[]{true};
                propMinItems = new boolean[]{false};
                break;
            case "kv_list":
                propNames = new String[]{"prefix"};
                propTypes = new String[]{"string"};
                propRequired = new boolean[]{false};
                propMinLength = new boolean[]{false};
                propMinItems = new boolean[]{false};
                break;
            case "sum":
                propNames = new String[]{"numbers"};
                propTypes = new String[]{"array"};
                propRequired = new boolean[]{true};
                propMinLength = new boolean[]{false};
                propMinItems = new boolean[]{true};
                break;
            case "text_stats":
                propNames = new String[]{"text"};
                propTypes = new String[]{"string"};
                propRequired = new boolean[]{true};
                propMinLength = new boolean[]{false};
                propMinItems = new boolean[]{false};
                break;
            default: return toolFailure("unknown tool");
        }

        // Step 2: check unknown arguments
        Set<String> knownProps = new HashSet<>();
        for (String p : propNames) knownProps.add(p);
        List<String> unknown = new ArrayList<>();
        for (String k : args.keySet()) {
            if (!knownProps.contains(k)) unknown.add(k);
        }
        if (!unknown.isEmpty()) {
            Collections.sort(unknown, Main::compareByCodePoint);
            return toolFailure("unknown argument: " + unknown.get(0));
        }

        // Step 3: validate each property in schema order
        for (int i = 0; i < propNames.length; i++) {
            String pn = propNames[i];
            boolean present = args.containsKey(pn);
            JVal pv = present ? args.get(pn) : null;
            if (!present) {
                if (propRequired[i]) return toolFailure("missing required argument: " + pn);
                continue;
            }
            if (propTypes[i].equals("string")) {
                if (pv.type != JVal.STR) return toolFailure("argument " + pn + " must be a string");
                if (propMinLength[i] && pv.strVal.isEmpty()) return toolFailure("argument " + pn + " must not be empty");
            } else if (propTypes[i].equals("array")) {
                if (pv.type != JVal.ARR) return toolFailure("argument " + pn + " must be an array of integers");
                for (JVal el : pv.arrVal) {
                    if (el.type != JVal.NUM || !el.numIsInt) return toolFailure("argument " + pn + " must be an array of integers");
                }
                if (propMinItems[i] && pv.arrVal.isEmpty()) return toolFailure("argument " + pn + " must not be empty");
            }
        }

        // Execute tool
        switch (toolName) {
            case "kv_set": {
                String key = args.get("key").strVal;
                String value = args.get("value").strVal;
                boolean existed = kvStore.containsKey(key);
                kvStore.put(key, value);
                return toolSuccess(existed ? "updated " + key : "created " + key);
            }
            case "kv_get": {
                String key = args.get("key").strVal;
                if (!kvStore.containsKey(key)) return toolFailure("key not found: " + key);
                return toolSuccess(kvStore.get(key));
            }
            case "kv_list": {
                String prefix = args.containsKey("prefix") ? args.get("prefix").strVal : "";
                List<String> keys = new ArrayList<>();
                for (String k : kvStore.keySet()) {
                    if (prefix.isEmpty() || k.startsWith(prefix)) keys.add(k);
                }
                keys.sort(Main::compareByCodePoint);
                JVal S = new JVal(JVal.OBJ);
                JVal keysArr = new JVal(JVal.ARR);
                for (String k : keys) keysArr.arrVal.add(JVal.str(k));
                S.objVal.put("keys", keysArr);
                S.objVal.put("count", JVal.numInt(keys.size()));
                return toolSuccessStructured(S);
            }
            case "sum": {
                JVal numsArr = args.get("numbers");
                long sum = 0;
                int count = numsArr.arrVal.size();
                for (JVal el : numsArr.arrVal) {
                    sum += el.numLong;
                }
                JVal S = new JVal(JVal.OBJ);
                S.objVal.put("sum", JVal.numLong(sum));
                S.objVal.put("count", JVal.numInt(count));
                return toolSuccessStructured(S);
            }
            case "text_stats": {
                String text = args.get("text").strVal;
                int words = countWords(text);
                int codepoints = text.codePointCount(0, text.length());
                int utf8bytes = text.getBytes(StandardCharsets.UTF_8).length;
                JVal S = new JVal(JVal.OBJ);
                S.objVal.put("words", JVal.numInt(words));
                S.objVal.put("codepoints", JVal.numInt(codepoints));
                S.objVal.put("utf8_bytes", JVal.numInt(utf8bytes));
                return toolSuccessStructured(S);
            }
        }
        return toolFailure("internal error");
    }

    static int countWords(String text) {
        int words = 0;
        boolean inWord = false;
        int i = 0;
        while (i < text.length()) {
            int cp = text.codePointAt(i);
            if (cp == 0x20 || cp == 0x09 || cp == 0x0A || cp == 0x0D) {
                inWord = false;
            } else {
                if (!inWord) { words++; inWord = true; }
            }
            i += Character.charCount(cp);
        }
        return words;
    }

    static int compareByCodePoint(String a, String b) {
        int i = 0, j = 0;
        while (i < a.length() && j < b.length()) {
            int cpA = a.codePointAt(i);
            int cpB = b.codePointAt(j);
            if (cpA != cpB) return Integer.compare(cpA, cpB);
            i += Character.charCount(cpA);
            j += Character.charCount(cpB);
        }
        if (i < a.length()) return 1;
        if (j < b.length()) return -1;
        return 0;
    }

    static String toolSuccess(String text) {
        JVal result = new JVal(JVal.OBJ);
        JVal content = new JVal(JVal.ARR);
        JVal block = new JVal(JVal.OBJ);
        block.objVal.put("type", JVal.str("text"));
        block.objVal.put("text", JVal.str(text));
        content.arrVal.add(block);
        result.objVal.put("content", content);
        result.objVal.put("isError", new JVal(JVal.BOOL, false));
        return resultObj(result);
    }

    static String toolSuccessStructured(JVal S) {
        JVal result = new JVal(JVal.OBJ);
        JVal content = new JVal(JVal.ARR);
        JVal block = new JVal(JVal.OBJ);
        block.objVal.put("type", JVal.str("text"));
        block.objVal.put("text", JVal.str(serialize(S)));
        content.arrVal.add(block);
        result.objVal.put("content", content);
        result.objVal.put("structuredContent", S);
        result.objVal.put("isError", new JVal(JVal.BOOL, false));
        return resultObj(result);
    }

    static String toolFailure(String message) {
        JVal result = new JVal(JVal.OBJ);
        JVal content = new JVal(JVal.ARR);
        JVal block = new JVal(JVal.OBJ);
        block.objVal.put("type", JVal.str("text"));
        block.objVal.put("text", JVal.str(message));
        content.arrVal.add(block);
        result.objVal.put("content", content);
        result.objVal.put("isError", new JVal(JVal.BOOL, true));
        return resultObj(result);
    }

    static String resultObj(JVal result) {
        JVal resp = new JVal(JVal.OBJ);
        resp.objVal.put("jsonrpc", JVal.str("2.0"));
        resp.objVal.put("result", result);
        return serialize(resp);
    }

    static String okResponse(JVal id, JVal result) {
        JVal resp = new JVal(JVal.OBJ);
        resp.objVal.put("jsonrpc", JVal.str("2.0"));
        resp.objVal.put("id", id);
        resp.objVal.put("result", result);
        return serialize(resp);
    }

    static String errResponse(JVal id, int code, String message) {
        JVal resp = new JVal(JVal.OBJ);
        resp.objVal.put("jsonrpc", JVal.str("2.0"));
        resp.objVal.put("id", id);
        JVal err = new JVal(JVal.OBJ);
        err.objVal.put("code", JVal.numInt(code));
        err.objVal.put("message", JVal.str(message));
        resp.objVal.put("error", err);
        return serialize(resp);
    }

    // === JSON Value ===
    static class JVal {
        static final int NULL=0, BOOL=1, NUM=2, STR=3, ARR=4, OBJ=5;
        int type;
        boolean boolVal;
        String numRaw;
        boolean numIsInt;
        long numLong;
        double numDouble;
        String strVal;
        ArrayList<JVal> arrVal;
        LinkedHashMap<String, JVal> objVal;

        JVal(int type) {
            this.type = type;
            if (type == ARR) arrVal = new ArrayList<>();
            if (type == OBJ) objVal = new LinkedHashMap<>();
        }
        JVal(int type, boolean b) { this.type = type; this.boolVal = b; }
        static JVal str(String s) { JVal v = new JVal(STR); v.strVal = s; return v; }
        static JVal numInt(long n) { JVal v = new JVal(NUM); v.numRaw = Long.toString(n); v.numIsInt = true; v.numLong = n; v.numDouble = n; return v; }
        static JVal numLong(long n) { return numInt(n); }
    }

    // === JSON Serializer ===
    static String serialize(JVal v) {
        StringBuilder sb = new StringBuilder();
        ser(v, sb);
        return sb.toString();
    }

    static void ser(JVal v, StringBuilder sb) {
        if (v == null) { sb.append("null"); return; }
        switch (v.type) {
            case JVal.NULL: sb.append("null"); break;
            case JVal.BOOL: sb.append(v.boolVal ? "true" : "false"); break;
            case JVal.NUM: sb.append(v.numRaw); break;
            case JVal.STR: serStr(v.strVal, sb); break;
            case JVal.ARR:
                sb.append('[');
                for (int i = 0; i < v.arrVal.size(); i++) {
                    if (i > 0) sb.append(',');
                    ser(v.arrVal.get(i), sb);
                }
                sb.append(']');
                break;
            case JVal.OBJ:
                sb.append('{');
                boolean first = true;
                for (Map.Entry<String, JVal> e : v.objVal.entrySet()) {
                    if (!first) sb.append(',');
                    first = false;
                    serStr(e.getKey(), sb);
                    sb.append(':');
                    ser(e.getValue(), sb);
                }
                sb.append('}');
                break;
        }
    }

    static void serStr(String s, StringBuilder sb) {
        sb.append('"');
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                default:
                    if (c < 0x20) {
                        sb.append(String.format("\\u%04x", (int)c));
                    } else {
                        sb.append(c);
                    }
            }
        }
        sb.append('"');
    }

    // === JSON Parser ===
    static int pos;
    static String src;

    static JVal parseJson(String s) {
        src = s;
        pos = 0;
        skipWs();
        JVal v = parseValue();
        skipWs();
        if (pos < src.length()) throw new RuntimeException("trailing garbage");
        return v;
    }

    static void skipWs() {
        while (pos < src.length()) {
            char c = src.charAt(pos);
            if (c == ' ' || c == '\t' || c == '\n' || c == '\r') pos++;
            else break;
        }
    }

    static JVal parseValue() {
        skipWs();
        if (pos >= src.length()) throw new RuntimeException("unexpected end");
        char c = src.charAt(pos);
        if (c == '{') return parseObj();
        if (c == '[') return parseArr();
        if (c == '"') return parseStr();
        if (c == 't') return parseLit("true", new JVal(JVal.BOOL, true));
        if (c == 'f') return parseLit("false", new JVal(JVal.BOOL, false));
        if (c == 'n') return parseLit("null", new JVal(JVal.NULL));
        if (c == '-' || (c >= '0' && c <= '9')) return parseNum();
        throw new RuntimeException("unexpected char: " + c);
    }

    static JVal parseLit(String lit, JVal val) {
        if (!src.startsWith(lit, pos)) throw new RuntimeException("bad literal");
        pos += lit.length();
        return val;
    }

    static JVal parseStr() {
        if (src.charAt(pos) != '"') throw new RuntimeException("expected quote");
        pos++;
        StringBuilder sb = new StringBuilder();
        while (pos < src.length()) {
            char c = src.charAt(pos);
            if (c == '"') { pos++; return JVal.str(sb.toString()); }
            if (c == '\\') {
                pos++;
                if (pos >= src.length()) throw new RuntimeException("bad escape");
                char e = src.charAt(pos);
                switch (e) {
                    case '"': sb.append('"'); break;
                    case '\\': sb.append('\\'); break;
                    case '/': sb.append('/'); break;
                    case 'b': sb.append('\b'); break;
                    case 'f': sb.append('\f'); break;
                    case 'n': sb.append('\n'); break;
                    case 'r': sb.append('\r'); break;
                    case 't': sb.append('\t'); break;
                    case 'u':
                        pos++;
                        if (pos + 4 > src.length()) throw new RuntimeException("bad unicode escape");
                        String hex = src.substring(pos, pos + 4);
                        int cp = Integer.parseInt(hex, 16);
                        sb.append((char) cp);
                        pos += 3;
                        break;
                    default: throw new RuntimeException("bad escape: " + e);
                }
                pos++;
            } else {
                sb.append(c);
                pos++;
            }
        }
        throw new RuntimeException("unterminated string");
    }

    static JVal parseNum() {
        int start = pos;
        if (pos < src.length() && src.charAt(pos) == '-') pos++;
        if (pos >= src.length()) throw new RuntimeException("bad number");
        if (src.charAt(pos) == '0') {
            pos++;
        } else if (src.charAt(pos) >= '1' && src.charAt(pos) <= '9') {
            while (pos < src.length() && src.charAt(pos) >= '0' && src.charAt(pos) <= '9') pos++;
        } else {
            throw new RuntimeException("bad number");
        }
        boolean isInt = true;
        if (pos < src.length() && src.charAt(pos) == '.') {
            isInt = false;
            pos++;
            if (pos >= src.length() || src.charAt(pos) < '0' || src.charAt(pos) > '9') throw new RuntimeException("bad number");
            while (pos < src.length() && src.charAt(pos) >= '0' && src.charAt(pos) <= '9') pos++;
        }
        if (pos < src.length() && (src.charAt(pos) == 'e' || src.charAt(pos) == 'E')) {
            isInt = false;
            pos++;
            if (pos < src.length() && (src.charAt(pos) == '+' || src.charAt(pos) == '-')) pos++;
            if (pos >= src.length() || src.charAt(pos) < '0' || src.charAt(pos) > '9') throw new RuntimeException("bad number");
            while (pos < src.length() && src.charAt(pos) >= '0' && src.charAt(pos) <= '9') pos++;
        }
        String raw = src.substring(start, pos);
        JVal v = new JVal(JVal.NUM);
        v.numRaw = raw;
        v.numIsInt = isInt;
        if (isInt) {
            v.numLong = Long.parseLong(raw);
            v.numDouble = v.numLong;
        } else {
            v.numDouble = Double.parseDouble(raw);
            v.numLong = (long) v.numDouble;
        }
        return v;
    }

    static JVal parseObj() {
        if (src.charAt(pos) != '{') throw new RuntimeException("expected {");
        pos++;
        JVal obj = new JVal(JVal.OBJ);
        skipWs();
        if (pos < src.length() && src.charAt(pos) == '}') { pos++; return obj; }
        while (true) {
            skipWs();
            if (pos >= src.length() || src.charAt(pos) != '"') throw new RuntimeException("expected key");
            JVal key = parseStr();
            skipWs();
            if (pos >= src.length() || src.charAt(pos) != ':') throw new RuntimeException("expected colon");
            pos++;
            JVal val = parseValue();
            obj.objVal.put(key.strVal, val);
            skipWs();
            if (pos >= src.length()) throw new RuntimeException("expected } or ,");
            if (src.charAt(pos) == '}') { pos++; return obj; }
            if (src.charAt(pos) == ',') { pos++; continue; }
            throw new RuntimeException("expected } or ,");
        }
    }

    static JVal parseArr() {
        if (src.charAt(pos) != '[') throw new RuntimeException("expected [");
        pos++;
        JVal arr = new JVal(JVal.ARR);
        skipWs();
        if (pos < src.length() && src.charAt(pos) == ']') { pos++; return arr; }
        while (true) {
            JVal val = parseValue();
            arr.arrVal.add(val);
            skipWs();
            if (pos >= src.length()) throw new RuntimeException("expected ] or ,");
            if (src.charAt(pos) == ']') { pos++; return arr; }
            if (src.charAt(pos) == ',') { pos++; continue; }
            throw new RuntimeException("expected ] or ,");
        }
    }
}

// main.ts - MCP server (protocol revision 2025-06-18, stdio transport)

// ============ Custom JSON Parser with number format tracking ============

interface JsonNumber {
  __jsonNumber: true;
  value: number;
  isInteger: boolean;
}

function isJsonNumber(v: any): v is JsonNumber {
  return v !== null && typeof v === 'object' && v.__jsonNumber === true && typeof v.value === 'number' && typeof v.isInteger === 'boolean';
}

function parseJsonStrict(text: string): any {
  let pos = 0;

  function fail(): never { throw new Error('Parse error'); }

  function skipWs(): void {
    while (pos < text.length) {
      const c = text[pos];
      if (c === ' ' || c === '\t' || c === '\n' || c === '\r') pos++;
      else break;
    }
  }

  function expect(ch: string): void {
    if (pos >= text.length || text[pos] !== ch) fail();
    pos++;
  }

  function parseValue(): any {
    skipWs();
    if (pos >= text.length) fail();
    const c = text[pos];
    if (c === '{') return parseObject();
    if (c === '[') return parseArray();
    if (c === '"') return parseString();
    if (c === 't') return parseLit('true', true);
    if (c === 'f') return parseLit('false', false);
    if (c === 'n') return parseLit('null', null);
    if (c === '-' || (c >= '0' && c <= '9')) return parseNumber();
    fail();
  }

  function parseLit(lit: string, val: any): any {
    for (let i = 0; i < lit.length; i++) {
      if (pos + i >= text.length || text[pos + i] !== lit[i]) fail();
    }
    pos += lit.length;
    return val;
  }

  function parseString(): string {
    expect('"');
    let result = '';
    while (pos < text.length) {
      const c = text[pos];
      if (c === '"') { pos++; return result; }
      if (c === '\\') {
        pos++;
        if (pos >= text.length) fail();
        const e = text[pos]; pos++;
        switch (e) {
          case '"': result += '"'; break;
          case '\\': result += '\\'; break;
          case '/': result += '/'; break;
          case 'b': result += '\b'; break;
          case 'f': result += '\f'; break;
          case 'n': result += '\n'; break;
          case 'r': result += '\r'; break;
          case 't': result += '\t'; break;
          case 'u': {
            let hex = '';
            for (let i = 0; i < 4; i++) {
              if (pos >= text.length) fail();
              const h = text[pos];
              if (!((h >= '0' && h <= '9') || (h >= 'a' && h <= 'f') || (h >= 'A' && h <= 'F'))) fail();
              hex += h; pos++;
            }
            result += String.fromCharCode(parseInt(hex, 16));
            break;
          }
          default: fail();
        }
      } else {
        if (c.charCodeAt(0) < 0x20) fail();
        result += c; pos++;
      }
    }
    fail();
  }

  function parseNumber(): JsonNumber {
    const start = pos;
    if (text[pos] === '-') pos++;
    if (pos >= text.length) fail();
    if (text[pos] === '0') { pos++; }
    else if (text[pos] >= '1' && text[pos] <= '9') {
      while (pos < text.length && text[pos] >= '0' && text[pos] <= '9') pos++;
    } else fail();

    let isInteger = true;
    if (pos < text.length && text[pos] === '.') {
      isInteger = false; pos++;
      if (pos >= text.length || text[pos] < '0' || text[pos] > '9') fail();
      while (pos < text.length && text[pos] >= '0' && text[pos] <= '9') pos++;
    }
    if (pos < text.length && (text[pos] === 'e' || text[pos] === 'E')) {
      isInteger = false; pos++;
      if (pos < text.length && (text[pos] === '+' || text[pos] === '-')) pos++;
      if (pos >= text.length || text[pos] < '0' || text[pos] > '9') fail();
      while (pos < text.length && text[pos] >= '0' && text[pos] <= '9') pos++;
    }
    return { __jsonNumber: true, value: Number(text.slice(start, pos)), isInteger };
  }

  function parseObject(): any {
    expect('{'); skipWs();
    const obj: any = Object.create(null);
    if (pos < text.length && text[pos] === '}') { pos++; return obj; }
    while (true) {
      skipWs();
      if (pos >= text.length || text[pos] !== '"') fail();
      const key = parseString();
      skipWs(); expect(':');
      obj[key] = parseValue();
      skipWs();
      if (pos >= text.length) fail();
      if (text[pos] === '}') { pos++; return obj; }
      if (text[pos] === ',') { pos++; continue; }
      fail();
    }
  }

  function parseArray(): any[] {
    expect('['); skipWs();
    const arr: any[] = [];
    if (pos < text.length && text[pos] === ']') { pos++; return arr; }
    while (true) {
      arr.push(parseValue());
      skipWs();
      if (pos >= text.length) fail();
      if (text[pos] === ']') { pos++; return arr; }
      if (text[pos] === ',') { pos++; continue; }
      fail();
    }
  }

  const result = parseValue();
  skipWs();
  if (pos !== text.length) fail();
  return result;
}

// ============ Helpers ============

function isValidId(v: any): boolean {
  if (typeof v === 'string') return true;
  if (isJsonNumber(v) && v.isInteger) return true;
  return false;
}

function unwrapId(v: any): any {
  if (isJsonNumber(v)) return v.value;
  return v;
}

function compareByCodePoint(a: string, b: string): number {
  const aPts = [...a];
  const bPts = [...b];
  const len = Math.min(aPts.length, bPts.length);
  for (let i = 0; i < len; i++) {
    const diff = aPts[i].codePointAt(0)! - bPts[i].codePointAt(0)!;
    if (diff !== 0) return diff;
  }
  return aPts.length - bPts.length;
}

function countWords(text: string): number {
  let count = 0;
  let inWord = false;
  for (const ch of text) {
    if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r') {
      inWord = false;
    } else {
      if (!inWord) { count++; inWord = true; }
    }
  }
  return count;
}

function codePointCount(text: string): number {
  return [...text].length;
}

function utf8ByteLength(text: string): number {
  return Buffer.byteLength(text, 'utf8');
}

// ============ Tool Definitions ============

const TOOL_DEFS = [
  {
    name: "kv_set",
    title: "Set a value",
    description: "Store a string value under a key, replacing any previous value.",
    inputSchema: {
      type: "object",
