        text: { type: "string" }
      },
      required: ["text"],
      additionalProperties: false
    },
    outputSchema: {
      type: "object",
      properties: {
        words: { type: "integer" },
        codepoints: { type: "integer" },
        utf8_bytes: { type: "integer" }
      },
      required: ["words", "codepoints", "utf8_bytes"]
    },
    annotations: { readOnlyHint: true }
  }
];

const VALID_METHODS = new Set(["initialize", "ping", "tools/list", "tools/call"]);
const TOOL_NAMES = new Set(TOOL_DEFS.map(t => t.name));
const SUPPORTED_VERSIONS = new Set(["2025-06-18", "2025-03-26", "2024-11-05"]);

// ============ Server State ============

let initialized = false;
const kvStore = new Map<string, string>();

// ============ Argument Validation ============

function validateArguments(toolDef: any, args: any): string | null {
  // args is already confirmed to be an object (or absent treated as {})
  const schema = toolDef.inputSchema;
  const props = schema.properties;
  const required: string[] = schema.required || [];
  const propNames = Object.keys(props);

  // Check for unknown arguments
  const argKeys = Object.keys(args);
  const unknownKeys = argKeys.filter(k => !(k in props));
  if (unknownKeys.length > 0) {
    unknownKeys.sort(compareByCodePoint);
    return `unknown argument: ${unknownKeys[0]}`;
  }

  // Validate each property in schema order
  for (const name of propNames) {
    const propSchema = props[name];
    const isRequired = required.includes(name);
    const hasProp = name in args;

    if (!hasProp) {
      if (isRequired) return `missing required argument: ${name}`;
      continue;
    }

    const val = args[name];

    // Type check
    if (propSchema.type === "string") {
      if (typeof val !== 'string') return `argument ${name} must be a string`;
      if (propSchema.minLength === 1 && val.length === 0) return `argument ${name} must not be empty`;
    } else if (propSchema.type === "array") {
      if (!Array.isArray(val)) return `argument ${name} must be an array of integers`;
      const items = propSchema.items;
      if (items && items.type === "integer") {
        for (const elem of val) {
          if (!isJsonNumber(elem) || !elem.isInteger) {
            return `argument ${name} must be an array of integers`;
          }
        }
      }
      if (propSchema.minItems === 1 && val.length === 0) return `argument ${name} must not be empty`;
    }
  }

  return null;
}

// ============ Tool Execution ============

function executeTool(name: string, args: any): any {
  switch (name) {
    case "kv_set": {
      const key = args["key"] as string;
      const value = args["value"] as string;
      const existed = kvStore.has(key);
      kvStore.set(key, value);
      return { content: [{ type: "text", text: existed ? `updated ${key}` : `created ${key}` }], isError: false };
    }
    case "kv_get": {
      const key = args["key"] as string;
      if (!kvStore.has(key)) {
        return { content: [{ type: "text", text: `key not found: ${key}` }], isError: true };
      }
      return { content: [{ type: "text", text: kvStore.get(key)! }], isError: false };
    }
    case "kv_list": {
      const prefix = (typeof args["prefix"] === 'string') ? args["prefix"] : "";
      let keys: string[] = [];
      for (const k of kvStore.keys()) {
        if (k.startsWith(prefix)) keys.push(k);
      }
      keys.sort(compareByCodePoint);
      const structured = { keys, count: keys.length };
      return {
        content: [{ type: "text", text: JSON.stringify(structured) }],
        structuredContent: structured,
        isError: false
      };
    }
    case "sum": {
      const numbers = args["numbers"] as JsonNumber[];
      let total = 0;
      for (const n of numbers) total += n.value;
      const structured = { sum: total, count: numbers.length };
      return {
        content: [{ type: "text", text: JSON.stringify(structured) }],
        structuredContent: structured,
        isError: false
      };
    }
    case "text_stats": {
      const text = args["text"] as string;
      const structured = {
        words: countWords(text),
        codepoints: codePointCount(text),
        utf8_bytes: utf8ByteLength(text)
      };
      return {
        content: [{ type: "text", text: JSON.stringify(structured) }],
        structuredContent: structured,
        isError: false
      };
    }
    default:
      return { content: [{ type: "text", text: "Unknown tool" }], isError: true };
  }
}

// ============ Method Dispatch ============

function dispatch(method: string, params: any, id: any): any {
  switch (method) {
    case "initialize": {
      if (initialized) {
        return { jsonrpc: "2.0", id, error: { code: -32600, message: "Already initialized" } };
      }
      if (params === undefined || params === null || typeof params !== 'object' || Array.isArray(params)) {
        return { jsonrpc: "2.0", id, error: { code: -32602, message: "Invalid params" } };
      }
      const pv = params["protocolVersion"];
      if (pv === undefined || typeof pv !== 'string') {
        return { jsonrpc: "2.0", id, error: { code: -32602, message: "Invalid params" } };
      }
      initialized = true;
      const version = SUPPORTED_VERSIONS.has(pv) ? pv : "2025-06-18";
      return {
        jsonrpc: "2.0", id,
        result: {
          protocolVersion: version,
          capabilities: { tools: { listChanged: false } },
          serverInfo: { name: "cb2-kv", title: "CB2 key-value server", version: "1.4.2" }
        }
      };
    }
    case "ping": {
      return { jsonrpc: "2.0", id, result: {} };
    }
    case "tools/list": {
      return { jsonrpc: "2.0", id, result: { tools: TOOL_DEFS } };
    }
    case "tools/call": {
      if (params === undefined || params === null || typeof params !== 'object' || Array.isArray(params)) {
        // params absent or not object - but 6b should have caught "present but not object"
        // If params is absent, name is missing
        return { jsonrpc: "2.0", id, error: { code: -32602, message: "Invalid params" } };
      }
      const name = params["name"];
      if (name === undefined || typeof name !== 'string') {
        return { jsonrpc: "2.0", id, error: { code: -32602, message: "Invalid params" } };
      }
      if (!TOOL_NAMES.has(name)) {
        return { jsonrpc: "2.0", id, error: { code: -32602, message: `Unknown tool: ${name}` } };
      }
      const toolDef = TOOL_DEFS.find(t => t.name === name)!;

      // Get arguments
      let args: any = {};
      if ("arguments" in params) {
        const rawArgs = params["arguments"];
        if (rawArgs === null || typeof rawArgs !== 'object' || Array.isArray(rawArgs) || isJsonNumber(rawArgs)) {
          return { jsonrpc: "2.0", id, result: { content: [{ type: "text", text: "arguments must be an object" }], isError: true } };
        }
        args = rawArgs;
      }

      // Validate arguments
      const validationError = validateArguments(toolDef, args);
      if (validationError) {
        return { jsonrpc: "2.0", id, result: { content: [{ type: "text", text: validationError }], isError: true } };
      }

      // Execute tool
      const toolResult = executeTool(name, args);
      return { jsonrpc: "2.0", id, result: toolResult };
    }
    default:
      return { jsonrpc: "2.0", id, error: { code: -32601, message: "Method not found" } };
  }
}

// ============ Line Processing ============

function processLine(line: string): string | null {
  // Strip trailing CR
  if (line.endsWith('\r')) line = line.slice(0, -1);

  // Ignore empty lines or lines with only spaces, tabs, CR
  if (/^[ \t\r]*$/.test(line)) return null;

  // Rule 1: Parse JSON
  let msg: any;
  try {
    msg = parseJsonStrict(line);
  } catch {
    return JSON.stringify({ jsonrpc: "2.0", id: null, error: { code: -32700, message: "Parse error" } });
  }

  // Rule 2: Not an object
  if (msg === null || typeof msg !== 'object' || Array.isArray(msg) || isJsonNumber(msg)) {
    return JSON.stringify({ jsonrpc: "2.0", id: null, error: { code: -32600, message: "Invalid Request" } });
  }

  // Rule 3: Client response (no method, has result or error)
  if (!("method" in msg) && ("result" in msg || "error" in msg)) {
    return null;
  }

  // Rule 4: Invalid request checks
  const hasId = "id" in msg;
  const idValid = hasId && isValidId(msg["id"]);
  const jsonrpcOk = msg["jsonrpc"] === "2.0";
  const methodOk = typeof msg["method"] === "string";

  if (!jsonrpcOk || !methodOk || (hasId && !idValid)) {
    const responseId = idValid ? unwrapId(msg["id"]) : null;
    return JSON.stringify({ jsonrpc: "2.0", id: responseId, error: { code: -32600, message: "Invalid Request" } });
  }

  // Rule 5: Notification (no id)
  if (!hasId) {
    return null;
  }

  // Rule 6: Request
  const id = unwrapId(msg["id"]);
  const method = msg["method"] as string;

  // 6a: method not recognized
  if (!VALID_METHODS.has(method)) {
    return JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32601, message: "Method not found" } });
  }

  // 6b: params present but not an object
  if ("params" in msg) {
    const p = msg["params"];
    if (p === null || typeof p !== 'object' || Array.isArray(p) || isJsonNumber(p)) {
      return JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32602, message: "Invalid params" } });
    }
  }

  // 6c: not initialized and not initialize/ping
  if (!initialized && method !== "initialize" && method !== "ping") {
    return JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32002, message: "Server not initialized" } });
  }

  // 6d: dispatch
  const params = "params" in msg ? msg["params"] : undefined;
  return JSON.stringify(dispatch(method, params, id));
}

// ============ Main ============

async function main(): Promise<void> {
  const chunks: Buffer[] = [];
  for await (const chunk of process.stdin) {
    chunks.push(chunk as Buffer);
  }
  const input = Buffer.concat(chunks).toString('utf-8');
  const lines = input.split('\n');
  const outputs: string[] = [];

  for (const line of lines) {
    const resp = processLine(line);
    if (resp !== null) {
      outputs.push(resp);
    }
  }

  if (outputs.length > 0) {
    process.stdout.write(outputs.join('\n') + '\n');
  }
  process.exit(0);
}

main();

