#define ROTR32(x,n) (((x)>>(n))|((x)<<(32-(n))))
static void sha256_compress(uint32_t st[8], const uint8_t blk[64]){
    uint32_t W[64];
    for(int i=0;i<16;i++) W[i]=((uint32_t)blk[i*4]<<24)|((uint32_t)blk[i*4+1]<<16)|((uint32_t)blk[i*4+2]<<8)|blk[i*4+3];
    for(int i=16;i<64;i++){
        uint32_t s0=ROTR32(W[i-15],7)^ROTR32(W[i-15],18)^(W[i-15]>>3);
        uint32_t s1=ROTR32(W[i-2],17)^ROTR32(W[i-2],19)^(W[i-2]>>10);
        W[i]=W[i-16]+s0+W[i-7]+s1;
    }
    uint32_t a=st[0],b=st[1],c=st[2],d=st[3],e=st[4],f=st[5],g=st[6],h=st[7];
    for(int i=0;i<64;i++){
        uint32_t S1=ROTR32(e,6)^ROTR32(e,11)^ROTR32(e,25);
        uint32_t ch=(e&f)^((~e)&g);
        uint32_t t1=h+S1+ch+sha256_K[i]+W[i];
        uint32_t S0=ROTR32(a,2)^ROTR32(a,13)^ROTR32(a,22);
        uint32_t maj=(a&b)^(a&c)^(b&c);
        uint32_t t2=S0+maj;
        h=g;g=f;f=e;e=d+t1;d=c;c=b;b=a;a=t1+t2;
    }
    st[0]+=a;st[1]+=b;st[2]+=c;st[3]+=d;st[4]+=e;st[5]+=f;st[6]+=g;st[7]+=h;
}
static void sha256(const uint8_t*msg,size_t len,uint8_t out[32]){
    uint32_t st[8]; memcpy(st,sha256_H0,32);
    size_t i=0;
    while(len-i>=64){sha256_compress(st,msg+i);i+=64;}
    uint8_t buf[128]; memset(buf,0,128);
    size_t rem=len-i;
    memcpy(buf,msg+i,rem);
    buf[rem]=0x80;
    size_t padlen=(rem<56)?64:128;
    uint64_t bits=(uint64_t)len*8;
    buf[padlen-1]=(uint8_t)bits; buf[padlen-2]=(uint8_t)(bits>>8);
    buf[padlen-3]=(uint8_t)(bits>>16); buf[padlen-4]=(uint8_t)(bits>>24);
    buf[padlen-5]=(uint8_t)(bits>>32); buf[padlen-6]=(uint8_t)(bits>>40);
    buf[padlen-7]=(uint8_t)(bits>>48); buf[padlen-8]=(uint8_t)(bits>>56);
    sha256_compress(st,buf);
    if(padlen==128) sha256_compress(st,buf+64);
    for(int j=0;j<8;j++){out[j*4]=st[j]>>24;out[j*4+1]=st[j]>>16;out[j*4+2]=st[j]>>8;out[j*4+3]=st[j];}
}

