/* ==================== HMAC ==================== */
static void hmac_sha256(const uint8_t*key,size_t klen,const uint8_t*msg,size_t mlen,uint8_t out[32]){
    uint8_t k[64];memset(k,0,64);
    if(klen>64){sha256(key,klen,k);klen=32;}
    else{memcpy(k,key,klen);}
    uint8_t ipad[64],opad[64];
    for(int i=0;i<64;i++){ipad[i]=k[i]^0x36;opad[i]=k[i]^0x5c;}
    uint8_t *buf=malloc(64+mlen);
    memcpy(buf,ipad,64);memcpy(buf+64,msg,mlen);
    uint8_t inner[32];sha256(buf,64+mlen,inner);free(buf);
    buf=malloc(64+32);
    memcpy(buf,opad,64);memcpy(buf+64,inner,32);
    sha256(buf,96,out);free(buf);
}
static void hmac_sha512_generic(const uint8_t*key,size_t klen,const uint8_t*msg,size_t mlen,uint8_t*out,int outbytes,const uint64_t*H0){
    uint8_t k[128];memset(k,0,128);
    if(klen>128){uint8_t h[64];sha512_generic(key,klen,h,64,sha512_H0);memcpy(k,h,64);klen=64;}
    else{memcpy(k,key,klen);}
    uint8_t ipad[128],opad[128];
    for(int i=0;i<128;i++){ipad[i]=k[i]^0x36;opad[i]=k[i]^0x5c;}
    uint8_t *buf=malloc(128+mlen);
    memcpy(buf,ipad,128);memcpy(buf+128,msg,mlen);
    uint8_t inner[64];sha512_generic(buf,128+mlen,inner,64,sha512_H0);free(buf);
    buf=malloc(128+64);
    memcpy(buf,opad,128);memcpy(buf+128,inner,64);
    sha512_generic(buf,192,out,outbytes,H0);free(buf);
}
static void hmac_sha384(const uint8_t*key,size_t klen,const uint8_t*msg,size_t mlen,uint8_t out[48]){
    hmac_sha512_generic(key,klen,msg,mlen,out,48,sha384_H0);
}
static void hmac_sha512(const uint8_t*key,size_t klen,const uint8_t*msg,size_t mlen,uint8_t out[64]){
    hmac_sha512_generic(key,klen,msg,mlen,out,64,sha512_H0);
}

/* ==================== Base64url ==================== */
static int b64url_valid(const char*s,size_t len){
    if(len%4==1) return 0;
    for(size_t i=0;i<len;i++){
        char c=s[i];
        if(!((c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='-'||c=='_')) return 0;
    }
    return 1;
}
static int b64val(char c){
    if(c>='A'&&c<='Z') return c-'A';
    if(c>='a'&&c<='z') return c-'a'+26;
    if(c>='0'&&c<='9') return c-'0'+52;
    if(c=='-') return 62;
    if(c=='_') return 63;
    return -1;
}
static uint8_t*b64url_decode(const char*s,size_t len,size_t*outlen){
    size_t n=(len/4)*3+(len%4==2?1:(len%4==3?2:0));
    uint8_t*out=malloc(n+1);
    size_t j=0;
    for(size_t i=0;i+4<=len;i+=4){
        int a=b64val(s[i]),b=b64val(s[i+1]),c=b64val(s[i+2]),d=b64val(s[i+3]);
        out[j++]=(a<<2)|(b>>4);
        out[j++]=((b&0xF)<<4)|(c>>2);
        out[j++]=((c&0x3)<<6)|d;
    }
    size_t rem=len%4;
    if(rem==2){
        int a=b64val(s[len-2]),b=b64val(s[len-1]);
        out[j++]=(a<<2)|(b>>4);
    }else if(rem==3){
        int a=b64val(s[len-3]),b=b64val(s[len-2]),c=b64val(s[len-1]);
        out[j++]=(a<<2)|(b>>4);
        out[j++]=((b&0xF)<<4)|(c>>2);
    }
    *outlen=j;
    return out;
}

/* ==================== JSON Parser ==================== */
typedef enum{JNULL,JBOOL,JNUM,JSTR,JARR,JOBJ}jtype;
typedef struct jval{
    jtype type;
    int bval;
    double nval;
    char*sval;
    struct{struct jval**items;size_t count;}arr;
    struct{char**keys;struct jval**vals;size_t count;}obj;
}jval;

typedef struct{const char*p;const char*end;int err;}jctx;

static void jskip(jctx*c){while(c->p<c->end&&(*c->p==' '||*c->p=='\t'||*c->p=='\n'||*c->p=='\r'))c->p++;}
static jval*jparse(jctx*c);

static char*jparse_str_raw(jctx*c){
    if(c->p>=c->end||*c->p!='"'){c->err=1;return NULL;}
    c->p++;
    size_t cap=64,len=0;
    char*buf=malloc(cap);
    while(c->p<c->end&&*c->p!='"'){
        if(len+4>=cap){cap*=2;buf=realloc(buf,cap);}
        if(*c->p=='\\'){
            c->p++;
            if(c->p>=c->end){c->err=1;buf[len]=0;return buf;}
            switch(*c->p){
                case '"':buf[len++]='"';c->p++;break;
                case '\\':buf[len++]='\\';c->p++;break;
                case '/':buf[len++]='/';c->p++;break;
                case 'b':buf[len++]='\b';c->p++;break;
                case 'f':buf[len++]='\f';c->p++;break;
                case 'n':buf[len++]='\n';c->p++;break;
                case 'r':buf[len++]='\r';c->p++;break;
                case 't':buf[len++]='\t';c->p++;break;
                case 'u':{
                    c->p++;
                    if(c->p+4>c->end){c->err=1;buf[len]=0;return buf;}
                    unsigned cp=0;
                    for(int i=0;i<4;i++){
                        char ch=c->p[i];int v;
                        if(ch>='0'&&ch<='9')v=ch-'0';
                        else if(ch>='a'&&ch<='f')v=ch-'a'+10;
                        else if(ch>='A'&&ch<='F')v=ch-'A'+10;
                        else{c->err=1;buf[len]=0;return buf;}
                        cp=(cp<<4)|v;
                    }
                    c->p+=4;
                    if(cp>=0xD800&&cp<=0xDBFF&&c->p+6<=c->end&&c->p[0]=='\\'&&c->p[1]=='u'){
                        unsigned lo=0;
                        for(int i=2;i<6;i++){
                            char ch=c->p[i];int v;
                            if(ch>='0'&&ch<='9')v=ch-'0';
                            else if(ch>='a'&&ch<='f')v=ch-'a'+10;
                            else if(ch>='A'&&ch<='F')v=ch-'A'+10;
                            else{c->err=1;buf[len]=0;return buf;}
                            lo=(lo<<4)|v;
                        }
                        if(lo>=0xDC00&&lo<=0xDFFF){
                            cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                            c->p+=6;
                        }
                    }
                    if(cp<0x80){buf[len++]=cp;}
                    else if(cp<0x800){buf[len++]=0xC0|(cp>>6);buf[len++]=0x80|(cp&0x3F);}
                    else if(cp<0x10000){buf[len++]=0xE0|(cp>>12);buf[len++]=0x80|((cp>>6)&0x3F);buf[len++]=0x80|(cp&0x3F);}
                    else{buf[len++]=0xF0|(cp>>18);buf[len++]=0x80|((cp>>12)&0x3F);buf[len++]=0x80|((cp>>6)&0x3F);buf[len++]=0x80|(cp&0x3F);}
                    break;
                }
                default:c->err=1;buf[len]=0;return buf;
            }
        }else{
            buf[len++]=*c->p;c->p++;
        }
    }
    if(c->p>=c->end){c->err=1;buf[len]=0;return buf;}
    c->p++; /* skip closing " */
    buf[len]=0;
    return buf;
}

static jval*jparse(jctx*c){
    if(c->err)return NULL;
    jskip(c);
    if(c->p>=c->end){c->err=1;return NULL;}
    jval*v=calloc(1,sizeof(jval));
    if(*c->p=='{'){
        c->p++;v->type=JOBJ;
        size_t cap=8;v->obj.keys=malloc(cap*sizeof(char*));v->obj.vals=malloc(cap*sizeof(jval*));
        jskip(c);
        if(c->p<c->end&&*c->p=='}'){c->p++;return v;}
        while(1){
            jskip(c);
            char*key=jparse_str_raw(c);
            if(c->err){c->err=1;return v;}
            jskip(c);
            if(c->p>=c->end||*c->p!=':'){c->err=1;return v;}
            c->p++;
            jval*val=jparse(c);
            if(c->err){c->err=1;return v;}
            if(v->obj.count>=cap){cap*=2;v->obj.keys=realloc(v->obj.keys,cap*sizeof(char*));v->obj.vals=realloc(v->obj.vals,cap*sizeof(jval*));}
            v->obj.keys[v->obj.count]=key;
            v->obj.vals[v->obj.count]=val;
            v->obj.count++;
            jskip(c);
            if(c->p<c->end&&*c->p==','){c->p++;continue;}
            if(c->p<c->end&&*c->p=='}'){c->p++;break;}
            c->err=1;return v;
        }
        return v;
    }else if(*c->p=='['){
        c->p++;v->type=JARR;
        size_t cap=8;v->arr.items=malloc(cap*sizeof(jval*));
        jskip(c);
        if(c->p<c->end&&*c->p==']'){c->p++;return v;}
        while(1){
            jval*val=jparse(c);
            if(c->err){c->err=1;return v;}
            if(v->arr.count>=cap){cap*=2;v->arr.items=realloc(v->arr.items,cap*sizeof(jval*));}
            v->arr.items[v->arr.count++]=val;
            jskip(c);
            if(c->p<c->end&&*c->p==','){c->p++;continue;}
            if(c->p<c->end&&*c->p==']'){c->p++;break;}
            c->err=1;return v;
        }
        return v;
    }else if(*c->p=='"'){
        v->type=JSTR;v->sval=jparse_str_raw(c);
        if(c->err){c->err=1;return v;}
        return v;
    }else if(*c->p=='t'){
        if(c->end-c->p>=4&&memcmp(c->p,"true",4)==0){c->p+=4;v->type=JBOOL;v->bval=1;}
        else{c->err=1;}
        return v;
    }else if(*c->p=='f'){
        if(c->end-c->p>=5&&memcmp(c->p,"false",5)==0){c->p+=5;v->type=JBOOL;v->bval=0;}
        else{c->err=1;}
        return v;
    }else if(*c->p=='n'){
        if(c->end-c->p>=4&&memcmp(c->p,"null",4)==0){c->p+=4;}
        else{c->err=1;}
        v->type=JNULL;return v;
    }else{
        char*endp;
        v->type=JNUM;
        v->nval=strtod(c->p,&endp);
        if(endp==c->p){c->err=1;return v;}
        c->p=endp;
        return v;
    }
}

static jval*jobj_get(jval*obj,const char*key){
    if(!obj||obj->type!=JOBJ)return NULL;
    for(size_t i=0;i<obj->obj.count;i++){
        if(obj->obj.keys[i]&&strcmp(obj->obj.keys[i],key)==0) return obj->obj.vals[i];
    }
    return NULL;
}
static int jobj_has(jval*obj,const char*key){
    if(!obj||obj->type!=JOBJ)return 0;
    for(size_t i=0;i<obj->obj.count;i++){
        if(obj->obj.keys[i]&&strcmp(obj->obj.keys[i],key)==0) return 1;
    }
    return 0;
}

/* ==================== Main ==================== */
int main(int argc,char**argv){
    if(argc<2){fprintf(stderr,"Usage: %s <dir>\n",argv[0]);return 1;}
    char*dir=argv[1];
    /* Read config.json */
    char cpath[4096];snprintf(cpath,sizeof(cpath),"%s/config.json",dir);
    FILE*f=fopen(cpath,"rb");
    if(!f){perror("config");return 1;}
    fseek(f,0,SEEK_END);long fsz=ftell(f);fseek(f,0,SEEK_SET);
    char*cbuf=malloc(fsz+1);fread(cbuf,1,fsz,f);cbuf[fsz]=0;fclose(f);
    jctx jc={cbuf,cbuf+fsz,0};
    jval*cfg=jparse(&jc);

    double now=jobj_get(cfg,"now")->nval;
    double leeway=jobj_get(cfg,"leeway")->nval;
    char*issuer=jobj_get(cfg,"issuer")?jobj_get(cfg,"issuer")->sval:NULL;
    char*audience=jobj_get(cfg,"audience")?jobj_get(cfg,"audience")->sval:NULL;
    jval*keys_arr=jobj_get(cfg,"keys");

    /* Read tokens.txt */
    char tpath[4096];snprintf(tpath,sizeof(tpath),"%s/tokens.txt",dir);
    f=fopen(tpath,"rb");
    if(!f){perror("tokens");return 1;}
    fseek(f,0,SEEK_END);fsz=ftell(f);fseek(f,0,SEEK_SET);
    char*tbuf=malloc(fsz+1);fread(tbuf,1,fsz,f);tbuf[fsz]=0;fclose(f);

    /* Split into lines */
    char**lines=NULL;int nlines=0;
    {
        char*p=tbuf;
        while(*p){
            char*nl=strchr(p,'\n');
            char*line;
            if(nl){*nl=0;line=p;p=nl+1;}
            else{line=p;p=p+strlen(p);}
            while(*line==' '||*line=='\t')line++;
            char*end=line+strlen(line)-1;
            while(end>=line&&(*end==' '||*end=='\t')){*end=0;end--;}
            if(*line){
                nlines++;lines=realloc(lines,nlines*sizeof(char*));
                lines[nlines-1]=line;
            }
        }
    }

    int valid_count=0,invalid_count=0;

    for(int li=0;li<nlines;li++){
        char*tok=lines[li];
        const char*result=NULL;
        char sub_out[4096]={0};
        char scope_out[4096]={0};

        /* Rule 1: MALFORMED */
        char*dot1=strchr(tok,'.');
        char*dot2=dot1?strchr(dot1+1,'.'):NULL;
        char*dot3=dot2?strchr(dot2+1,'.'):NULL;
        if(!dot1||!dot2||dot3){result="MALFORMED";goto emit;}
        size_t hlen=dot1-tok;
        size_t plen=dot2-dot1-1;
        size_t slen=tok+strlen(tok)-dot2-1;
        char*hseg=malloc(hlen+1);memcpy(hseg,tok,hlen);hseg[hlen]=0;
        char*pseg=malloc(plen+1);memcpy(pseg,dot1+1,plen);pseg[plen]=0;
        char*sseg=malloc(slen+1);memcpy(sseg,dot2+1,slen);sseg[slen]=0;

        if(hlen==0||plen==0||slen==0){result="MALFORMED";goto emit;}
        if(!b64url_valid(hseg,hlen)||!b64url_valid(pseg,plen)||!b64url_valid(sseg,slen)){result="MALFORMED";goto emit;}

        size_t hdec_len,pdec_len,sdec_len;
        uint8_t*hdec=b64url_decode(hseg,hlen,&hdec_len);
        uint8_t*pdec=b64url_decode(pseg,plen,&pdec_len);
        uint8_t*sdec=b64url_decode(sseg,slen,&sdec_len);

        /* Parse header and payload as JSON */
        jctx hc={(char*)hdec,(char*)hdec+hdec_len,0};
        jval*header=jparse(&hc);
        /* Check all input consumed */
        if(!hc.err){jskip(&hc);if(hc.p<hc.end)hc.err=1;}
        jctx pc={(char*)pdec,(char*)pdec+pdec_len,0};
        jval*payload=jparse(&pc);
        if(!pc.err){jskip(&pc);if(pc.p<pc.end)pc.err=1;}

        if(!header||hc.err||header->type!=JOBJ||!payload||pc.err||payload->type!=JOBJ){result="MALFORMED";goto emit;}

        /* Rule 2: UNSUPPORTED_ALG */
        jval*alg_v=jobj_get(header,"alg");
        if(!alg_v||alg_v->type!=JSTR||!alg_v->sval){result="UNSUPPORTED_ALG";goto emit;}
        char*alg=alg_v->sval;
        int alg_id=0;
        if(strcmp(alg,"HS256")==0)alg_id=0;
        else if(strcmp(alg,"HS384")==0)alg_id=1;
        else if(strcmp(alg,"HS512")==0)alg_id=2;
        else{result="UNSUPPORTED_ALG";goto emit;}

        /* Rule 3: UNKNOWN_KEY */
        jval*kid_v=jobj_get(header,"kid");
        if(!kid_v||kid_v->type!=JSTR||!kid_v->sval){result="UNKNOWN_KEY";goto emit;}
        char*kid=kid_v->sval;
        jval*key_obj=NULL;
        if(keys_arr&&keys_arr->type==JARR){
            for(size_t ki=0;ki<keys_arr->arr.count;ki++){
                jval*ko=keys_arr->arr.items[ki];
                jval*kkid=jobj_get(ko,"kid");
                if(kkid&&kkid->type==JSTR&&kkid->sval&&strcmp(kkid->sval,kid)==0){key_obj=ko;break;}
            }
        }
        if(!key_obj){result="UNKNOWN_KEY";goto emit;}

        /* Rule 4: ALG_MISMATCH */
        jval*key_alg_v=jobj_get(key_obj,"alg");
        if(!key_alg_v||key_alg_v->type!=JSTR||!key_alg_v->sval||strcmp(key_alg_v->sval,alg)!=0){result="ALG_MISMATCH";goto emit;}

        /* Rule 5: BAD_SIGNATURE */
        jval*key_k_v=jobj_get(key_obj,"k");
        if(!key_k_v||key_k_v->type!=JSTR||!key_k_v->sval){result="BAD_SIGNATURE";goto emit;}
        size_t secret_len;
        uint8_t*secret=b64url_decode(key_k_v->sval,strlen(key_k_v->sval),&secret_len);
        size_t si_len=hlen+1+plen;
        char*si=malloc(si_len+1);
        memcpy(si,hseg,hlen);si[hlen]='.';memcpy(si+hlen+1,pseg,plen);si[si_len]=0;
        uint8_t hmac_out[64];
        if(alg_id==0) hmac_sha256(secret,secret_len,(uint8_t*)si,si_len,hmac_out);
        else if(alg_id==1) hmac_sha384(secret,secret_len,(uint8_t*)si,si_len,hmac_out);
        else hmac_sha512(secret,secret_len,(uint8_t*)si,si_len,hmac_out);
        size_t expected_len=(alg_id==0)?32:(alg_id==1)?48:64;
        if(sdec_len!=expected_len||memcmp(sdec,hmac_out,expected_len)!=0){result="BAD_SIGNATURE";goto emit;}

        /* Rule 6: EXPIRED */
        if(jobj_has(payload,"exp")){
            jval*exp_v=jobj_get(payload,"exp");
            if(exp_v&&exp_v->type==JNUM){
                if(now>=exp_v->nval+leeway){result="EXPIRED";goto emit;}
            }
        }

        /* Rule 7: NOT_YET_VALID */
        if(jobj_has(payload,"nbf")){
            jval*nbf_v=jobj_get(payload,"nbf");
            if(nbf_v&&nbf_v->type==JNUM){
                if(now+leeway<nbf_v->nval){result="NOT_YET_VALID";goto emit;}
            }
        }

        /* Rule 8: BAD_ISSUER */
        {
            jval*iss_v=jobj_get(payload,"iss");
            if(!iss_v||iss_v->type!=JSTR||!iss_v->sval||!issuer||strcmp(iss_v->sval,issuer)!=0){result="BAD_ISSUER";goto emit;}
        }

        /* Rule 9: BAD_AUDIENCE */
        {
            jval*aud_v=jobj_get(payload,"aud");
            if(!aud_v){result="BAD_AUDIENCE";goto emit;}
            if(aud_v->type==JSTR){
                if(!audience||!aud_v->sval||strcmp(aud_v->sval,audience)!=0){result="BAD_AUDIENCE";goto emit;}
            }else if(aud_v->type==JARR){
                int found=0;
                for(size_t ai=0;ai<aud_v->arr.count;ai++){
                    jval*el=aud_v->arr.items[ai];
                    if(el&&el->type==JSTR&&el->sval&&audience&&strcmp(el->sval,audience)==0){found=1;break;}
                }
                if(!found){result="BAD_AUDIENCE";goto emit;}
            }else{result="BAD_AUDIENCE";goto emit;}
        }

        /* VALID */
        {
            jval*sub_v=jobj_get(payload,"sub");
            if(sub_v&&sub_v->type==JSTR&&sub_v->sval){
                strncpy(sub_out,sub_v->sval,sizeof(sub_out)-1);
            }
            jval*scope_v=jobj_get(payload,"scope");
            if(scope_v&&scope_v->type==JSTR&&scope_v->sval&&scope_v->sval[0]){
                char**scopes=NULL;int nsc=0;
                char*sp=strdup(scope_v->sval);
                char*tok2=strtok(sp," ");
                while(tok2){
                    if(tok2[0]){
                        scopes=realloc(scopes,(nsc+1)*sizeof(char*));
                        scopes[nsc++]=tok2;
                    }
                    tok2=strtok(NULL," ");
                }
                /* sort */
                for(int a=0;a<nsc;a++)for(int b=a+1;b<nsc;b++){
                    if(strcmp(scopes[a],scopes[b])>0){char*t=scopes[a];scopes[a]=scopes[b];scopes[b]=t;}
                }
                /* dedup and join */
                int first=1;
                for(int a=0;a<nsc;a++){
                    if(a>0&&strcmp(scopes[a],scopes[a-1])==0)continue;
                    if(!first)strcat(scope_out,",");
                    strcat(scope_out,scopes[a]);
                    first=0;
                }
                free(sp);free(scopes);
            }
            valid_count++;
        }
        emit:
        printf("%d: ",li+1);
        if(result){printf("%s\n",result);invalid_count++;}
        else{printf("VALID sub=%s scope=%s\n",sub_out,scope_out);}
    }

    printf("\nvalid=%d invalid=%d\n",valid_count,invalid_count);
    return 0;
}

import Foundation

// MARK: - JSON Value
enum JSONValue {
    case null
    case bool(Bool)
    case int(Int64)
    case double(Double)
    case string(String)
    case array([JSONValue])
    case object([(String, JSONValue)])
}

// MARK: - JSON Parser
struct JSONParser {
    let chars: [Character]
    var pos: Int = 0

    init(_ s: String) { chars = Array(s) }

    mutating func parse() -> JSONValue? {
        skipWS()
        guard let v = parseValue() else { return nil }
        skipWS()
        if pos != chars.count { return nil }
        return v
    }

    mutating func skipWS() {
        while pos < chars.count {
            let c = chars[pos]
            if c == " " || c == "\t" || c == "\n" || c == "\r" { pos += 1 } else { break }
        }
    }

    mutating func parseValue() -> JSONValue? {
        guard pos < chars.count else { return nil }
        switch chars[pos] {
        case "{": return parseObject()
        case "[": return parseArray()
        case "\"":
            guard let s = parseString() else { return nil }
            return .string(s)
        case "t": return parseLit("true", .bool(true))
        case "f": return parseLit("false", .bool(false))
        case "n": return parseLit("null", .null)
        default:
            if chars[pos] == "-" || (chars[pos] >= "0" && chars[pos] <= "9") { return parseNumber() }
            return nil
        }
    }

    mutating func parseLit(_ lit: String, _ val: JSONValue) -> JSONValue? {
        for c in lit {
            guard pos < chars.count && chars[pos] == c else { return nil }
            pos += 1
        }
        return val
    }

    mutating func parseString() -> String? {
        guard pos < chars.count && chars[pos] == "\"" else { return nil }
        pos += 1
        var result = ""
        while pos < chars.count {
            let c = chars[pos]
            if c == "\"" { pos += 1; return result }
            if c == "\\" {
                pos += 1
                guard pos < chars.count else { return nil }
                let e = chars[pos]
                switch e {
                case "\"": result.append("\""); pos += 1
                case "\\": result.append("\\"); pos += 1
                case "/": result.append("/"); pos += 1
                case "b": result.append("\u{08}"); pos += 1
                case "f": result.append("\u{0C}"); pos += 1
                case "n": result.append("\n"); pos += 1
                case "r": result.append("\r"); pos += 1
                case "t": result.append("\t"); pos += 1
                case "u":
                    pos += 1
                    guard pos + 4 <= chars.count else { return nil }
                    let hex = String(chars[pos..<pos+4])
                    guard let code = UInt32(hex, radix: 16) else { return nil }
                    pos += 4
                    if code >= 0xD800 && code <= 0xDBFF {
                        guard pos + 1 < chars.count && chars[pos] == "\\" && chars[pos+1] == "u" else { return nil }
                        pos += 2
                        guard pos + 4 <= chars.count else { return nil }
                        let hex2 = String(chars[pos..<pos+4])
                        guard let code2 = UInt32(hex2, radix: 16) else { return nil }
                        pos += 4
                        guard code2 >= 0xDC00 && code2 <= 0xDFFF else { return nil }
                        let cp = 0x10000 + (code - 0xD800) * 0x400 + (code2 - 0xDC00)
                        guard let sc = Unicode.Scalar(cp) else { return nil }
                        result.append(Character(sc))
                    } else if code >= 0xDC00 && code <= 0xDFFF {
                        return nil
                    } else {
                        guard let sc = Unicode.Scalar(code) else { return nil }
                        result.append(Character(sc))
                    }
                default: return nil
                }
            } else {
                result.append(c); pos += 1
            }
        }
        return nil
    }

    mutating func parseNumber() -> JSONValue? {
        var isFloat = false
        var s = ""
        if pos < chars.count && chars[pos] == "-" { s.append("-"); pos += 1 }
        guard pos < chars.count else { return nil }
        if chars[pos] == "0" {
            s.append("0"); pos += 1
            if pos < chars.count && chars[pos] >= "0" && chars[pos] <= "9" { return nil }
        } else if chars[pos] >= "1" && chars[pos] <= "9" {
            while pos < chars.count && chars[pos] >= "0" && chars[pos] <= "9" { s.append(chars[pos]); pos += 1 }
        } else { return nil }
        if pos < chars.count && chars[pos] == "." {
            isFloat = true; s.append("."); pos += 1
            guard pos < chars.count && chars[pos] >= "0" && chars[pos] <= "9" else { return nil }
            while pos < chars.count && chars[pos] >= "0" && chars[pos] <= "9" { s.append(chars[pos]); pos += 1 }
        }
        if pos < chars.count && (chars[pos] == "e" || chars[pos] == "E") {
            isFloat = true; s.append(chars[pos]); pos += 1
            if pos < chars.count && (chars[pos] == "+" || chars[pos] == "-") { s.append(chars[pos]); pos += 1 }
            guard pos < chars.count && chars[pos] >= "0" && chars[pos] <= "9" else { return nil }
            while pos < chars.count && chars[pos] >= "0" && chars[pos] <= "9" { s.append(chars[pos]); pos += 1 }
        }
        if isFloat {
            guard let d = Double(s) else { return nil }
            return .double(d)
        } else {
            guard let i = Int64(s) else { return nil }
            return .int(i)
        }
    }

    mutating func parseArray() -> JSONValue? {
        pos += 1; skipWS()
        var arr: [JSONValue] = []
        if pos < chars.count && chars[pos] == "]" { pos += 1; return .array(arr) }
        while true {
            skipWS()
            guard let v = parseValue() else { return nil }
            arr.append(v)
            skipWS()
            guard pos < chars.count else { return nil }
            if chars[pos] == "," { pos += 1; continue }
            if chars[pos] == "]" { pos += 1; return .array(arr) }
            return nil
        }
    }

    mutating func parseObject() -> JSONValue? {
        pos += 1; skipWS()
        var pairs: [(String, JSONValue)] = []
        if pos < chars.count && chars[pos] == "}" { pos += 1; return .object(pairs) }
        while true {
            skipWS()
            guard pos < chars.count && chars[pos] == "\"" else { return nil }
            guard let key = parseString() else { return nil }
            skipWS()
            guard pos < chars.count && chars[pos] == ":" else { return nil }
            pos += 1; skipWS()
            guard let val = parseValue() else { return nil }
            pairs.append((key, val))
            skipWS()
            guard pos < chars.count else { return nil }
            if chars[pos] == "," { pos += 1; continue }
            if chars[pos] == "}" { pos += 1; return .object(pairs) }
            return nil
        }
    }
}

// MARK: - JSON Serializer
func jsonString(_ s: String) -> String {
    var r = "\""
    for sc in s.unicodeScalars {
        switch sc {
        case "\"": r += "\\\""
        case "\\": r += "\\\\"
        case "\n": r += "\\n"
        case "\r": r += "\\r"
        case "\t": r += "\\t"
        default:
            if sc.value < 0x20 { r += String(format: "\\u%04x", sc.value) }
            else { r.unicodeScalars.append(sc) }
        }
    }
    r += "\""
    return r
}

func jsonSer(_ v: JSONValue) -> String {
    switch v {
    case .null: return "null"
    case .bool(true): return "true"
    case .bool(false): return "false"
    case .int(let i): return String(i)
    case .double(let d):
        if d == d.rounded() && d.isFinite && abs(d) < 1e18 { return String(Int64(d)) }
        return String(d)
    case .string(let s): return jsonString(s)
    case .array(let a): return "[" + a.map(jsonSer).joined(separator: ",") + "]"
    case .object(let p):
        return "{" + p.map { jsonString($0.0) + ":" + jsonSer($0.1) }.joined(separator: ",") + "}"
    }
}

// MARK: - Helpers
func objGet(_ obj: [(String, JSONValue)], _ key: String) -> JSONValue? {
    var r: JSONValue? = nil
    for (k, v) in obj { if k == key { r = v } }
    return r
}

func objHas(_ obj: [(String, JSONValue)], _ key: String) -> Bool {
    for (k, _) in obj { if k == key { return true } }
    return false
}

func isValidId(_ v: JSONValue) -> Bool {
    switch v {
    case .string: return true
    case .int: return true
    default: return false
    }
}

func makeError(_ id: JSONValue, _ code: Int, _ msg: String) -> String {
    return jsonSer(.object([
        ("jsonrpc", .string("2.0")),
        ("id", id),
        ("error", .object([("code", .int(Int64(code))), ("message", .string(msg))]))
    ]))
}

func makeResult(_ id: JSONValue, _ result: JSONValue) -> String {
    return jsonSer(.object([
        ("jsonrpc", .string("2.0")),
        ("id", id),
        ("result", result)
    ]))
}

// MARK: - Tool Definitions
struct ToolProp {
    let name: String
    let type: String // "string" or "array"
    let required: Bool
    let minLength1: Bool
    let minItems1: Bool
}

struct ToolDef {
    let name: String
    let props: [ToolProp]
    let hasOutputSchema: Bool
}

let toolDefs: [ToolDef] = [
    ToolDef(name: "kv_set", props: [
        ToolProp(name: "key", type: "string", required: true, minLength1: true, minItems1: false),
        ToolProp(name: "value", type: "string", required: true, minLength1: false, minItems1: false)
    ], hasOutputSchema: false),
    ToolDef(name: "kv_get", props: [
        ToolProp(name: "key", type: "string", required: true, minLength1: true, minItems1: false)
    ], hasOutputSchema: false),
    ToolDef(name: "kv_list", props: [
        ToolProp(name: "prefix", type: "string", required: false, minLength1: false, minItems1: false)
    ], hasOutputSchema: true),
    ToolDef(name: "sum", props: [
        ToolProp(name: "numbers", type: "array", required: true, minLength1: false, minItems1: true)
    ], hasOutputSchema: true),
    ToolDef(name: "text_stats", props: [
        ToolProp(name: "text", type: "string", required: true, minLength1: false, minItems1: false)
    ], hasOutputSchema: true)
]

func buildToolsList() -> JSONValue {
    func propSchema(_ p: ToolProp) -> (String, JSONValue) {
        var fields: [(String, JSONValue)] = [("type", .string(p.type))]
        if p.type == "array" {
            fields.append(("items", .object([("type", .string("integer"))])))
        }
        if p.minLength1 { fields.append(("minLength", .int(1))) }
        if p.minItems1 { fields.append(("minItems", .int(1))) }
        return (p.name, .object(fields))
    }
    func toolObj(_ t: ToolDef, extra: [(String, JSONValue)]) -> JSONValue {
        var fields: [(String, JSONValue)] = [
            ("name", .string(t.name)),
            ("title", .string(toolTitle(t.name))),
            ("description", .string(toolDesc(t.name))),
            ("inputSchema", .object([
                ("type", .string("object")),
                ("properties", .object(t.props.map { propSchema($0) })),
                ("required", .array(t.props.filter { $0.required }.map { .string($0.name) })),
                ("additionalProperties", .bool(false))
            ]))
        ]
        fields.append(contentsOf: extra)
        return .object(fields)
    }
    func outputSchema_kv_list() -> JSONValue {
        return .object([
            ("type", .string("object")),
            ("properties", .object([
                ("keys", .object([("type", .string("array")), ("items", .object([("type", .string("string"))]))])),
                ("count", .object([("type", .string("integer"))]))
            ])),
            ("required", .array([.string("keys"), .string("count")]))
        ])
    }
    func outputSchema_sum() -> JSONValue {
        return .object([
            ("type", .string("object")),
            ("properties", .object([
                ("sum", .object([("type", .string("integer"))])),
                ("count", .object([("type", .string("integer"))]))
            ])),
            ("required", .array([.string("sum"), .string("count")]))
        ])
    }
    func outputSchema_text_stats() -> JSONValue {
        return .object([
            ("type", .string("object")),
            ("properties", .object([
                ("words", .object([("type", .string("integer"))])),
                ("codepoints", .object([("type", .string("integer"))])),
                ("utf8_bytes", .object([("type", .string("integer"))]))
            ])),
            ("required", .array([.string("words"), .string("codepoints"), .string("utf8_bytes")]))
        ])
    }

    let tools: [JSONValue] = [
        toolObj(toolDefs[0], extra: []),
        toolObj(toolDefs[1], extra: []),
        toolObj(toolDefs[2], extra: [("outputSchema", outputSchema_kv_list())]),
        toolObj(toolDefs[3], extra: [
            ("outputSchema", outputSchema_sum()),
            ("annotations", .object([("readOnlyHint", .bool(true)), ("idempotentHint", .bool(true))]))
        ]),
        toolObj(toolDefs[4], extra: [
            ("outputSchema", outputSchema_text_stats()),
            ("annotations", .object([("readOnlyHint", .bool(true))]))
        ])
    ]
    return .object([("tools", .array(tools))])
}

func toolTitle(_ n: String) -> String {
    switch n {
    case "kv_set": return "Set a value"
    case "kv_get": return "Get a value"
    case "kv_list": return "List keys"
    case "sum": return "Sum integers"
    case "text_stats": return "Text statistics"
    default: return ""
    }
}
func toolDesc(_ n: String) -> String {
    switch n {
    case "kv_set": return "Store a string value under a key, replacing any previous value."
    case "kv_get": return "Return the value stored under a key."
    case "kv_list": return "List the stored keys that start with a prefix, sorted by Unicode code point."
    case "sum": return "Add up a non-empty list of integers."
    case "text_stats": return "Count the words, Unicode code points and UTF-8 bytes of a text."
    default: return ""
    }
}

// MARK: - Server State
var initialized = false
var store: [String: String] = [:]

// MARK: - Tool Execution
func makeToolSuccess(_ text: String) -> JSONValue {
    return .object([
        ("content", .array([.object([("type", .string("text")), ("text", .string(text))])])),
        ("isError", .bool(false))
    ])
}

func makeToolSuccessStructured(_ structured: JSONValue) -> JSONValue {
    let text = jsonSer(structured)
    return .object([
        ("content", .array([.object([("type", .string("text")), ("text", .string(text))])])),
        ("structuredContent", structured),
        ("isError", .bool(false))
    ])
}

func makeToolFailure(_ msg: String) -> JSONValue {
    return .object([
        ("content", .array([.object([("type", .string("text")), ("text", .string(msg))])])),
        ("isError", .bool(true))
    ])
}

func validateAndRunTool(_ toolName: String, _ args: JSONValue) -> JSONValue {
    // args is guaranteed to be .object or we handle it
    let argsObj: [(String, JSONValue)]
    switch args {
    case .object(let p): argsObj = p
    default: return makeToolFailure("arguments must be an object")
    }

    guard let tdef = toolDefs.first(where: { $0.name == toolName }) else {
        return makeToolFailure("unknown tool")
    }

    let definedNames = Set(tdef.props.map { $0.name })

    // Check unknown arguments
    var unknowns: [String] = []
    for (k, _) in argsObj {
        if !definedNames.contains(k) { unknowns.append(k) }
    }
    if !unknowns.isEmpty {
        unknowns.sort { a, b in
            a.unicodeScalars.lexicographicallyPrecedes(b.unicodeScalars)
        }
        return makeToolFailure("unknown argument: \(unknowns[0])")
    }

    // Validate each property in order
    for prop in tdef.props {
        let val = objGet(argsObj, prop.name)
        if val == nil {
            if prop.required {
                return makeToolFailure("missing required argument: \(prop.name)")
            }
            continue
        }
        let v = val!
        // Type check
        switch prop.type {
        case "string":
            if case .string = v {} else {
                return makeToolFailure("argument \(prop.name) must be a string")
            }
            if prop.minLength1 {
                if case .string(let s) = v, s.isEmpty {
                    return makeToolFailure("argument \(prop.name) must not be empty")
                }
            }
        case "array":
            if case .array(let arr) = v {
                for elem in arr {
                    if case .int = elem {} else {
                        return makeToolFailure("argument \(prop.name) must be an array of integers")
                    }
                }
                if prop.minItems1 && arr.isEmpty {
                    return makeToolFailure("argument \(prop.name) must not be empty")
                }
            } else {
                return makeToolFailure("argument \(prop.name) must be an array of integers")
            }
        default: break
        }
    }

    // Execute tool
    switch toolName {
    case "kv_set":
        let key: String
        let value: String
        if case .string(let k) = objGet(argsObj, "key")! { key = k } else { return makeToolFailure("internal") }
        if case .string(let v) = objGet(argsObj, "value")! { value = v } else { return makeToolFailure("internal") }
        let existed = store[key] != nil
        store[key] = value
        return makeToolSuccess(existed ? "updated \(key)" : "created \(key)")

    case "kv_get":
        let key: String
        if case .string(let k) = objGet(argsObj, "key")! { key = k } else { return makeToolFailure("internal") }
        if let val = store[key] {
            return makeToolSuccess(val)
        } else {
            return makeToolFailure("key not found: \(key)")
        }

    case "kv_list":
        var prefix = ""
        if let pv = objGet(argsObj, "prefix") {
            if case .string(let p) = pv { prefix = p }
        }
        var keys: [String] = []
        for (k, _) in store {
            if k.hasPrefix(prefix) { keys.append(k) }
        }
        keys.sort { a, b in a.unicodeScalars.lexicographicallyPrecedes(b.unicodeScalars) }
        let structured: JSONValue = .object([
            ("keys", .array(keys.map { .string($0) })),
            ("count", .int(Int64(keys.count)))
        ])
        return makeToolSuccessStructured(structured)

    case "sum":
        var sum: Int64 = 0
        var count: Int64 = 0
        if case .array(let arr) = objGet(argsObj, "numbers")! {
            for elem in arr {
                if case .int(let i) = elem { sum += i; count += 1 }
            }
        }
        let structured: JSONValue = .object([
            ("sum", .int(sum)),
            ("count", .int(count))
        ])
        return makeToolSuccessStructured(structured)

    case "text_stats":
        let text: String
        if case .string(let t) = objGet(argsObj, "text")! { text = t } else { return makeToolFailure("internal") }
        var words = 0
        var inWord = false
        for sc in text.unicodeScalars {
            if sc == " " || sc == "\t" || sc == "\n" || sc == "\r" {
                inWord = false
            } else {
                if !inWord { words += 1; inWord = true }
            }
        }
        let cp = text.unicodeScalars.count
        let ub = text.utf8.count
        let structured: JSONValue = .object([
            ("words", .int(Int64(words))),
            ("codepoints", .int(Int64(cp))),
            ("utf8_bytes", .int(Int64(ub)))
        ])
        return makeToolSuccessStructured(structured)

    default:
        return makeToolFailure("unknown tool")
    }
}

// MARK: - Main Processing
func processLine(_ line: String) -> String? {
    // Check if line is empty or whitespace-only (spaces, tabs, CR)
    var allWS = true
    for c in line {
        if c != " " && c != "\t" && c != "\r" { allWS = false; break }
    }
    if allWS { return nil }

    // Parse JSON
    var parser = JSONParser(line)
    guard let parsed = parser.parse() else {
        return makeError(.null, -32700, "Parse error")
    }

    // Must be object
    guard case .object(let obj) = parsed else {
        return makeError(.null, -32600, "Invalid Request")
    }

    // Rule 3: response from client (no method, has result or error)
    let hasMethod = objHas(obj, "method")
    let hasResult = objHas(obj, "result")
    let hasError = objHas(obj, "error")
    if !hasMethod && (hasResult || hasError) {
        return nil
    }

    // Rule 4: invalid request check
    let jsonrpcVal = objGet(obj, "jsonrpc")
    let isJsonrpc20: Bool
    if let jv = jsonrpcVal, case .string(let s) = jv, s == "2.0" {
        isJsonrpc20 = true
    } else {
        isJsonrpc20 = false
    }

    let methodVal = objGet(obj, "method")
    let methodStr: String?
    if let mv = methodVal, case .string(let m) = mv { methodStr = m } else { methodStr = nil }

    let hasId = objHas(obj, "id")
    let idVal = objGet(obj, "id")
    let idValid: Bool
    if hasId {
        idValid = idVal != nil && isValidId(idVal!)
    } else {
        idValid = true // no id member, not triggering this check
    }

    if !isJsonrpc20 || methodStr == nil || (hasId && !idValid) {
        let respId: JSONValue = (hasId && idValid) ? idVal! : .null
        return makeError(respId, -32600, "Invalid Request")
    }

    // Rule 5: notification (valid object without id)
    if !hasId {
        return nil
    }

    // Rule 6: request
    let id = idVal!
    let method = methodStr!

    // 6a: method not found
    let validMethods = ["initialize", "ping", "tools/list", "tools/call"]
    if !validMethods.contains(method) {
        return makeError(id, -32601, "Method not found")
    }

    // 6b: params present but not object
    let paramsVal = objGet(obj, "params")
    let paramsObj: [(String, JSONValue)]?
    if let pv = paramsVal {
        if case .object(let p) = pv { paramsObj = p }
        else { return makeError(id, -32602, "Invalid params") }
    } else {
        paramsObj = nil
    }

    // 6c: not initialized check
    if !initialized && method != "initialize" && method != "ping" {
        return makeError(id, -32002, "Server not initialized")
    }

    // 6d: dispatch
    switch method {
    case "initialize":
        if initialized {
            return makeError(id, -32600, "Already initialized")
        }
        guard let po = paramsObj else {
            return makeError(id, -32602, "Invalid params")
        }
        guard let pv = objGet(po, "protocolVersion"), case .string(let ver) = pv else {
            return makeError(id, -32602, "Invalid params")
        }
        initialized = true
        let echoVer: String
        if ver == "2025-06-18" || ver == "2025-03-26" || ver == "2024-11-05" {
            echoVer = ver
        } else {
            echoVer = "2025-06-18"
        }
        let result: JSONValue = .object([
            ("protocolVersion", .string(echoVer)),
            ("capabilities", .object([("tools", .object([("listChanged", .bool(false))]))])),
            ("serverInfo", .object([
                ("name", .string("cb2-kv")),
                ("title", .string("CB2 key-value server")),
                ("version", .string("1.4.2"))
            ]))
        ])
        return makeResult(id, result)

    case "ping":
        return makeResult(id, .object([]))

    case "tools/list":
        return makeResult(id, buildToolsList())

    case "tools/call":
        guard let po = paramsObj else {
            return makeError(id, -32602, "Invalid params")
        }
        guard let nv = objGet(po, "name"), case .string(let name) = nv else {
            return makeError(id, -32602, "Invalid params")
        }
        let knownTools = Set(toolDefs.map { $0.name })
        if !knownTools.contains(name) {
            return makeError(id, -32602, "Unknown tool: \(name)")
        }
        // Get arguments
        let argsVal: JSONValue
        if let av = objGet(po, "arguments") {
            argsVal = av
        } else {
            argsVal = .object([])
        }
        let toolResult = validateAndRunTool(name, argsVal)
        return makeResult(id, toolResult)

    default:
        return makeError(id, -32601, "Method not found")
    }
}

