    // Check empty/whitespace
    var allWS = true
    for c in line {
        if c != " " && c != "\t" && c != "\r" { allWS = false; break }
    }
    if allWS { continue }

    if let resp = processLine(line) {
        output += resp + "\n"
    }
}

print(output, terminator: "")
exit(0)

