// MARK: - JSON Serializer
func jsonString(_ s: String) -> String {
    var r = "\""
    for sc in s.unicodeScalars {
        switch sc {
        case "\"": r += "\\\""
        case "\\": r += "\\\\"
        case "\n": r += "\\n"
        case "\r": r += "\\r"
        case "\t": r += "\\t"
        default:
            if sc.value < 0x20 { r += String(format: "\\u%04x", sc.value) }
            else { r.unicodeScalars.append(sc) }
        }
    }
    r += "\""
    return r
}

func jsonSer(_ v: JSONValue) -> String {
    switch v {
    case .null: return "null"
    case .bool(true): return "true"
    case .bool(false): return "false"
    case .int(let i): return String(i)
    case .double(let d):
        if d == d.rounded() && d.isFinite && abs(d) < 1e18 { return String(Int64(d)) }
        return String(d)
    case .string(let s): return jsonString(s)
    case .array(let a): return "[" + a.map(jsonSer).joined(separator: ",") + "]"
    case .object(let p):
        return "{" + p.map { jsonString($0.0) + ":" + jsonSer($0.1) }.joined(separator: ",") + "}"
    }
}

// MARK: - Helpers
func objGet(_ obj: [(String, JSONValue)], _ key: String) -> JSONValue? {
    var r: JSONValue? = nil
    for (k, v) in obj { if k == key { r = v } }
    return r
}

func objHas(_ obj: [(String, JSONValue)], _ key: String) -> Bool {
    for (k, _) in obj { if k == key { return true } }
    return false
}

func isValidId(_ v: JSONValue) -> Bool {
    switch v {
    case .string: return true
    case .int: return true
    default: return false
    }
}

func makeError(_ id: JSONValue, _ code: Int, _ msg: String) -> String {
    return jsonSer(.object([
        ("jsonrpc", .string("2.0")),
        ("id", id),
        ("error", .object([("code", .int(Int64(code))), ("message", .string(msg))]))
    ]))
}

func makeResult(_ id: JSONValue, _ result: JSONValue) -> String {
    return jsonSer(.object([
        ("jsonrpc", .string("2.0")),
        ("id", id),
        ("result", result)
    ]))
}

// MARK: - Tool Definitions
struct ToolProp {
    let name: String
    let type: String // "string" or "array"
    let required: Bool
    let minLength1: Bool
    let minItems1: Bool
}

struct ToolDef {
    let name: String
    let props: [ToolProp]
    let hasOutputSchema: Bool
}

let toolDefs: [ToolDef] = [
    ToolDef(name: "kv_set", props: [
        ToolProp(name: "key", type: "string", required: true, minLength1: true, minItems1: false),
        ToolProp(name: "value", type: "string", required: true, minLength1: false, minItems1: false)
    ], hasOutputSchema: false),
    ToolDef(name: "kv_get", props: [
        ToolProp(name: "key", type: "string", required: true, minLength1: true, minItems1: false)
    ], hasOutputSchema: false),
    ToolDef(name: "kv_list", props: [
        ToolProp(name: "prefix", type: "string", required: false, minLength1: false, minItems1: false)
    ], hasOutputSchema: true),
    ToolDef(name: "sum", props: [
        ToolProp(name: "numbers", type: "array", required: true, minLength1: false, minItems1: true)
    ], hasOutputSchema: true),
    ToolDef(name: "text_stats", props: [
        ToolProp(name: "text", type: "string", required: true, minLength1: false, minItems1: false)
    ], hasOutputSchema: true)
]

func buildToolsList() -> JSONValue {
    func propSchema(_ p: ToolProp) -> (String, JSONValue) {
        var fields: [(String, JSONValue)] = [("type", .string(p.type))]
        if p.type == "array" {
            fields.append(("items", .object([("type", .string("integer"))])))
        }
        if p.minLength1 { fields.append(("minLength", .int(1))) }
        if p.minItems1 { fields.append(("minItems", .int(1))) }
        return (p.name, .object(fields))
    }
    func toolObj(_ t: ToolDef, extra: [(String, JSONValue)]) -> JSONValue {
        let requiredProps = t.props.filter { $0.required }.map { .string($0.name) }
        var inputSchemaFields: [(String, JSONValue)] = [
            ("type", .string("object")),
            ("properties", .object(t.props.map { propSchema($0) }))
        ]
        if !requiredProps.isEmpty {
            inputSchemaFields.append(("required", .array(requiredProps)))
        }
        inputSchemaFields.append(("additionalProperties", .bool(false)))

        var fields: [(String, JSONValue)] = [
            ("name", .string(t.name)),
            ("title", .string(toolTitle(t.name))),
            ("description", .string(toolDesc(t.name))),
            ("inputSchema", .object(inputSchemaFields))
        ]
        fields.append(contentsOf: extra)
        return .object(fields)
    }
    func outputSchema_kv_list() -> JSONValue {
        return .object([
            ("type", .string("object")),
            ("properties", .object([
                ("keys", .object([("type", .string("array")), ("items", .object([("type", .string("string"))]))])),
                ("count", .object([("type", .string("integer"))]))
            ])),
            ("required", .array([.string("keys"), .string("count")]))
        ])
    }
    func outputSchema_sum() -> JSONValue {
        return .object([
            ("type", .string("object")),
            ("properties", .object([
                ("sum", .object([("type", .string("integer"))])),
                ("count", .object([("type", .string("integer"))]))
            ])),
            ("required", .array([.string("sum"), .string("count")]))
        ])
    }
    func outputSchema_text_stats() -> JSONValue {
        return .object([
            ("type", .string("object")),
            ("properties", .object([
                ("words", .object([("type", .string("integer"))])),
                ("codepoints", .object([("type", .string("integer"))])),
                ("utf8_bytes", .object([("type", .string("integer"))]))
            ])),
            ("required", .array([.string("words"), .string("codepoints"), .string("utf8_bytes")]))
        ])
    }

    let tools: [JSONValue] = [
        toolObj(toolDefs[0], extra: []),
        toolObj(toolDefs[1], extra: []),
        toolObj(toolDefs[2], extra: [("outputSchema", outputSchema_kv_list())]),
        toolObj(toolDefs[3], extra: [
            ("outputSchema", outputSchema_sum()),
            ("annotations", .object([("readOnlyHint", .bool(true)), ("idempotentHint", .bool(true))]))
        ]),
        toolObj(toolDefs[4], extra: [
            ("outputSchema", outputSchema_text_stats()),
            ("annotations", .object([("readOnlyHint", .bool(true))]))
        ])
    ]
    return .object([("tools", .array(tools))])
}

func toolTitle(_ n: String) -> String {
    switch n {
    case "kv_set": return "Set a value"
    case "kv_get": return "Get a value"
    case "kv_list": return "List keys"
    case "sum": return "Sum integers"
    case "text_stats": return "Text statistics"
    default: return ""
    }
}
func toolDesc(_ n: String) -> String {
    switch n {
    case "kv_set": return "Store a string value under a key, replacing any previous value."
    case "kv_get": return "Return the value stored under a key."
    case "kv_list": return "List the stored keys that start with a prefix, sorted by Unicode code point."
    case "sum": return "Add up a non-empty list of integers."
    case "text_stats": return "Count the words, Unicode code points and UTF-8 bytes of a text."
    default: return ""
    }
}

// MARK: - Server State
var initialized = false
var store: [String: String] = [:]

// MARK: - Tool Execution
func makeToolSuccess(_ text: String) -> JSONValue {
    return .object([
        ("content", .array([.object([("type", .string("text")), ("text", .string(text))])])),
        ("isError", .bool(false))
    ])
}

func makeToolSuccessStructured(_ structured: JSONValue) -> JSONValue {
    let text = jsonSer(structured)
    return .object([
        ("content", .array([.object([("type", .string("text")), ("text", .string(text))])])),
        ("structuredContent", structured),
        ("isError", .bool(false))
    ])
}

func makeToolFailure(_ msg: String) -> JSONValue {
    return .object([
        ("content", .array([.object([("type", .string("text")), ("text", .string(msg))])])),
        ("isError", .bool(true))
    ])
}

func validateAndRunTool(_ toolName: String, _ args: JSONValue) -> JSONValue {
    let argsObj: [(String, JSONValue)]
    switch args {
    case .object(let p): argsObj = p
    default: return makeToolFailure("arguments must be an object")
    }

    guard let tdef = toolDefs.first(where: { $0.name == toolName }) else {
        return makeToolFailure("unknown tool")
    }

    let definedNames = Set(tdef.props.map { $0.name })

    // Check unknown arguments
    var unknowns: [String] = []
    for (k, _) in argsObj {
        if !definedNames.contains(k) { unknowns.append(k) }
    }
    if !unknowns.isEmpty {
        unknowns.sort { a, b in
            a.unicodeScalars.lexicographicallyPrecedes(b.unicodeScalars)
        }
        return makeToolFailure("unknown argument: \(unknowns[0])")
    }

    // Validate each property in order
    for prop in tdef.props {
        let val = objGet(argsObj, prop.name)
        if val == nil {
            if prop.required {
                return makeToolFailure("missing required argument: \(prop.name)")
            }
            continue
        }
        let v = val!
        // Type check
        switch prop.type {
        case "string":
            if case .string = v {} else {
                return makeToolFailure("argument \(prop.name) must be a string")
            }
            if prop.minLength1 {
                if case .string(let s) = v, s.isEmpty {
                    return makeToolFailure("argument \(prop.name) must not be empty")
                }
            }
        case "array":
            if case .array(let arr) = v {
                for elem in arr {
                    if case .int = elem {} else {
                        return makeToolFailure("argument \(prop.name) must be an array of integers")
                    }
                }
                if prop.minItems1 && arr.isEmpty {
                    return makeToolFailure("argument \(prop.name) must not be empty")
                }
            } else {
                return makeToolFailure("argument \(prop.name) must be an array of integers")
            }
        default: break
        }
    }

    // Execute tool
    switch toolName {
    case "kv_set":
        let key: String
        let value: String
        if case .string(let k) = objGet(argsObj, "key")! { key = k } else { return makeToolFailure("internal") }
        if case .string(let v) = objGet(argsObj, "value")! { value = v } else { return makeToolFailure("internal") }
        let existed = store[key] != nil
        store[key] = value
        return makeToolSuccess(existed ? "updated \(key)" : "created \(key)")

    case "kv_get":
        let key: String
        if case .string(let k) = objGet(argsObj, "key")! { key = k } else { return makeToolFailure("internal") }
        if let val = store[key] {
            return makeToolSuccess(val)
        } else {
            return makeToolFailure("key not found: \(key)")
        }

    case "kv_list":
        var prefix = ""
        if let pv = objGet(argsObj, "prefix") {
            if case .string(let p) = pv { prefix = p }
        }
        var keys: [String] = []
        for (k, _) in store {
            if k.hasPrefix(prefix) { keys.append(k) }
        }
        keys.sort { a, b in a.unicodeScalars.lexicographicallyPrecedes(b.unicodeScalars) }
        let structured: JSONValue = .object([
            ("keys", .array(keys.map { .string($0) })),
            ("count", .int(Int64(keys.count)))
        ])
        return makeToolSuccessStructured(structured)

    case "sum":
        var sum: Int64 = 0
        var count: Int64 = 0
        if case .array(let arr) = objGet(argsObj, "numbers")! {
            for elem in arr {
                if case .int(let i) = elem { sum += i; count += 1 }
            }
        }
        let structured: JSONValue = .object([
            ("sum", .int(sum)),
            ("count", .int(count))
        ])
        return makeToolSuccessStructured(structured)

    case "text_stats":
        let text: String
        if case .string(let t) = objGet(argsObj, "text")! { text = t } else { return makeToolFailure("internal") }
        var words = 0
        var inWord = false
        for sc in text.unicodeScalars {
            if sc == " " || sc == "\t" || sc == "\n" || sc == "\r" {
                inWord = false
            } else {
                if !inWord { words += 1; inWord = true }
            }
        }
        let cp = text.unicodeScalars.count
        let ub = text.utf8.count
        let structured: JSONValue = .object([
            ("words", .int(Int64(words))),
            ("codepoints", .int(Int64(cp))),
            ("utf8_bytes", .int(Int64(ub)))
        ])
        return makeToolSuccessStructured(structured)

    default:
        return makeToolFailure("unknown tool")
    }
}

// MARK: - Main Processing
func processLine(_ line: String) -> String? {
    // Check if line is empty or whitespace-only (spaces, tabs, CR)
    var allWS = true
    for c in line {
        if c != " " && c != "\t" && c != "\r" { allWS = false; break }
    }
    if allWS { return nil }

    // Parse JSON
    var parser = JSONParser(line)
    guard let parsed = parser.parse() else {
        return makeError(.null, -32700, "Parse error")
    }

    // Must be object
    guard case .object(let obj) = parsed else {
        return makeError(.null, -32600, "Invalid Request")
    }

    // Rule 3: response from client (no method, has result or error)
    let hasMethod = objHas(obj, "method")
    let hasResult = objHas(obj, "result")
    let hasError = objHas(obj, "error")
    if !hasMethod && (hasResult || hasError) {
        return nil
    }

    // Rule 4: invalid request check
    let jsonrpcVal = objGet(obj, "jsonrpc")
    let isJsonrpc20: Bool
    if let jv = jsonrpcVal, case .string(let s) = jv, s == "2.0" {
        isJsonrpc20 = true
    } else {
        isJsonrpc20 = false
    }

    let methodVal = objGet(obj, "method")
    let methodStr: String?
    if let mv = methodVal, case .string(let m) = mv { methodStr = m } else { methodStr = nil }

    let hasId = objHas(obj, "id")
    let idVal = objGet(obj, "id")
    let idValid: Bool
    if hasId {
        idValid = idVal != nil && isValidId(idVal!)
    } else {
        idValid = true
    }

    if !isJsonrpc20 || methodStr == nil || (hasId && !idValid) {
        let respId: JSONValue = (hasId && idValid) ? idVal! : .null
        return makeError(respId, -32600, "Invalid Request")
    }

    // Rule 5: notification (valid object without id)
    if !hasId {
        return nil
    }

    // Rule 6: request
    let id = idVal!
    let method = methodStr!

    // 6a: method not found
    let validMethods = ["initialize", "ping", "tools/list", "tools/call"]
    if !validMethods.contains(method) {
        return makeError(id, -32601, "Method not found")
    }

    // 6b: params present but not object
    let paramsVal = objGet(obj, "params")
    let paramsObj: [(String, JSONValue)]?
    if let pv = paramsVal {
        if case .object(let p) = pv { paramsObj = p }
        else { return makeError(id, -32602, "Invalid params") }
    } else {
        paramsObj = nil
    }

    // 6c: not initialized check
    if !initialized && method != "initialize" && method != "ping" {
        return makeError(id, -32002, "Server not initialized")
    }

    // 6d: dispatch
    switch method {
    case "initialize":
        if initialized {
            return makeError(id, -32600, "Already initialized")
        }
        guard let po = paramsObj else {
            return makeError(id, -32602, "Invalid params")
        }
        guard let pv = objGet(po, "protocolVersion"), case .string(let ver) = pv else {
            return makeError(id, -32602, "Invalid params")
        }
        initialized = true
        let echoVer: String
        if ver == "2025-06-18" || ver == "2025-03-26" || ver == "2024-11-05" {
            echoVer = ver
        } else {
            echoVer = "2025-06-18"
        }
        let result: JSONValue = .object([
            ("protocolVersion", .string(echoVer)),
            ("capabilities", .object([("tools", .object([("listChanged", .bool(false))]))])),
            ("serverInfo", .object([
                ("name", .string("cb2-kv")),
                ("title", .string("CB2 key-value server")),
                ("version", .string("1.4.2"))
            ]))
        ])
        return makeResult(id, result)

    case "ping":
        return makeResult(id, .object([]))

    case "tools/list":
        return makeResult(id, buildToolsList())

    case "tools/call":
        guard let po = paramsObj else {
            return makeError(id, -32602, "Invalid params")
        }
        guard let nv = objGet(po, "name"), case .string(let name) = nv else {
            return makeError(id, -32602, "Invalid params")
        }
        let knownTools = Set(toolDefs.map { $0.name })
        if !knownTools.contains(name) {
            return makeError(id, -32602, "Unknown tool: \(name)")
        }
        let argsVal: JSONValue
        if let av = objGet(po, "arguments") {
            argsVal = av
        } else {
            argsVal = .object([])
        }
        let toolResult = validateAndRunTool(name, argsVal)
        return makeResult(id, toolResult)

    default:
        return makeError(id, -32601, "Method not found")
    }
}

// MARK: - Main
let stdin = FileHandle.standardInput
let data = stdin.readDataToEndOfFile()
let inputStr = String(data: data, encoding: .utf8) ?? ""

var output = ""
let lines = inputStr.components(separatedBy: "\n")
for rawLine in lines {
    var line = rawLine
    if line.hasSuffix("\r") {
        line = String(line.dropLast())
    }
    var allWS = true
    for c in line {
        if c != " " && c != "\t" && c != "\r" { allWS = false; break }
    }
    if allWS { continue }

    if let resp = processLine(line) {
        output += resp + "\n"
    }
}

print(output, terminator: "")
exit(0)

use std::io::{self, BufRead, Write};
use std::collections::HashMap;

#[derive(Debug, Clone)]
enum Json {
    Null,
    Bool(bool),
    Int(i64),
    Float(f64),
    Str(String),
    Array(Vec<Json>),
    Object(Vec<(String, Json)>),
}

impl Json {
    fn get(&self, key: &str) -> Option<&Json> {
        if let Json::Object(pairs) = self {
            for (k, v) in pairs {
                if k == key { return Some(v); }
            }
        }
        None
    }
    fn is_object(&self) -> bool { matches!(self, Json::Object(_)) }
    fn is_string(&self) -> bool { matches!(self, Json::Str(_)) }
    fn as_str(&self) -> Option<&str> { if let Json::Str(s) = self { Some(s) } else { None } }
    fn as_bool(&self) -> Option<bool> { if let Json::Bool(b) = self { Some(*b) } else { None } }
    fn as_int(&self) -> Option<i64> { if let Json::Int(i) = self { Some(*i) } else { None } }
    fn as_array(&self) -> Option<&[Json]> { if let Json::Array(a) = self { Some(a) } else { None } }
    fn is_valid_id(&self) -> bool { matches!(self, Json::Str(_) | Json::Int(_)) }
}

// --- Parser ---
struct Parser<'a> {
    s: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self { Parser { s: s.as_bytes(), pos: 0 } }

    fn parse(&mut self) -> Result<Json, ()> {
        self.skip_ws();
        let v = self.parse_value()?;
        self.skip_ws();
        if self.pos != self.s.len() { return Err(()); }
        Ok(v)
    }

    fn skip_ws(&mut self) {
        while self.pos < self.s.len() {
            match self.s[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn peek(&self) -> Option<u8> { self.s.get(self.pos).copied() }
    fn eat(&mut self, c: u8) -> Result<(), ()> {
        if self.peek() == Some(c) { self.pos += 1; Ok(()) } else { Err(()) }
    }

    fn parse_value(&mut self) -> Result<Json, ()> {
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => Ok(Json::Str(self.parse_string()?)),
            Some(b't') => { self.expect_lit(b"true")?; Ok(Json::Bool(true)) }
            Some(b'f') => { self.expect_lit(b"false")?; Ok(Json::Bool(false)) }
            Some(b'n') => { self.expect_lit(b"null")?; Ok(Json::Null) }
            Some(b'-') | Some(b'0')..=Some(b'9') => self.parse_number(),
            _ => Err(()),
        }
    }

    fn expect_lit(&mut self, lit: &[u8]) -> Result<(), ()> {
        if self.s[self.pos..].starts_with(lit) { self.pos += lit.len(); Ok(()) } else { Err(()) }
    }

    fn parse_object(&mut self) -> Result<Json, ()> {
        self.eat(b'{')?;
        let mut pairs = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b'}') { self.pos += 1; return Ok(Json::Object(pairs)); }
        loop {
            self.skip_ws();
            let key = self.parse_string()?;
            self.skip_ws();
            self.eat(b':')?;
            self.skip_ws();
            let val = self.parse_value()?;
            pairs.push((key, val));
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b'}') => { self.pos += 1; break; }
                _ => return Err(()),
            }
        }
        Ok(Json::Object(pairs))
    }

    fn parse_array(&mut self) -> Result<Json, ()> {
        self.eat(b'[')?;
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b']') { self.pos += 1; return Ok(Json::Array(items)); }
        loop {
            self.skip_ws();
            let val = self.parse_value()?;
            items.push(val);
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b']') => { self.pos += 1; break; }
                _ => return Err(()),
            }
        }
        Ok(Json::Array(items))
    }

    fn parse_string(&mut self) -> Result<String, ()> {
        self.eat(b'"')?;
        let mut out = Vec::new();
        loop {
            if self.pos >= self.s.len() { return Err(()); }
            let c = self.s[self.pos];
            match c {
                b'"' => { self.pos += 1; break; }
                b'\\' => {
                    self.pos += 1;
                    if self.pos >= self.s.len() { return Err(()); }
                    match self.s[self.pos] {
                        b'"' => { out.push(b'"'); self.pos += 1; }
                        b'\\' => { out.push(b'\\'); self.pos += 1; }
                        b'/' => { out.push(b'/'); self.pos += 1; }
                        b'b' => { out.push(0x08); self.pos += 1; }
                        b'f' => { out.push(0x0C); self.pos += 1; }
                        b'n' => { out.push(b'\n'); self.pos += 1; }
                        b'r' => { out.push(b'\r'); self.pos += 1; }
                        b't' => { out.push(b'\t'); self.pos += 1; }
                        b'u' => {
                            self.pos += 1;
                            let cp = self.parse_hex4()?;
                            if (0xD800..=0xDBFF).contains(&cp) {
                                self.eat(b'\\')?;
                                self.eat(b'u')?;
                                let lo = self.parse_hex4()?;
                                if !(0xDC00..=0xDFFF).contains(&lo) { return Err(()); }
                                let full = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                                let ch = char::from_u32(full).ok_or(())?;
                                let mut buf = [0u8; 4];
                                out.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                            } else if (0xDC00..=0xDFFF).contains(&cp) {
                                return Err(());
                            } else {
                                let ch = char::from_u32(cp).ok_or(())?;
                                let mut buf = [0u8; 4];
                                out.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                            }
                        }
                        _ => return Err(()),
                    }
                }
                0x00..=0x1F => return Err(()),
                _ => { out.push(c); self.pos += 1; }
            }
        }
        String::from_utf8(out).map_err(|_| ())
    }

    fn parse_hex4(&mut self) -> Result<u32, ()> {
        if self.pos + 4 > self.s.len() { return Err(()); }
        let mut val: u32 = 0;
        for i in 0..4 {
            let c = self.s[self.pos + i];
            let d = match c {
                b'0'..=b'9' => (c - b'0') as u32,
                b'a'..=b'f' => (c - b'a' + 10) as u32,
                b'A'..=b'F' => (c - b'A' + 10) as u32,
                _ => return Err(()),
            };
            val = val * 16 + d;
        }
        self.pos += 4;
        Ok(val)
    }

    fn parse_number(&mut self) -> Result<Json, ()> {
        let start = self.pos;
        let mut is_float = false;
        if self.peek() == Some(b'-') { self.pos += 1; }
        // int part
        match self.peek() {
            Some(b'0') => { self.pos += 1; }
            Some(b'1'..=b'9') => { while matches!(self.peek(), Some(b'0'..=b'9')) { self.pos += 1; } }
            _ => return Err(()),
        }
        // frac
        if self.peek() == Some(b'.') {
            is_float = true;
            self.pos += 1;
            if !matches!(self.peek(), Some(b'0'..=b'9')) { return Err(()); }
            while matches!(self.peek(), Some(b'0'..=b'9')) { self.pos += 1; }
        }
        // exp
        if matches!(self.peek(), Some(b'e') | Some(b'E')) {
            is_float = true;
            self.pos += 1;
            if matches!(self.peek(), Some(b'+') | Some(b'-')) { self.pos += 1; }
            if !matches!(self.peek(), Some(b'0'..=b'9')) { return Err(()); }
            while matches!(self.peek(), Some(b'0'..=b'9')) { self.pos += 1; }
        }
        let num_str = &self.s[start..self.pos];
        let num_str = std::str::from_utf8(num_str).map_err(|_| ())?;
        if is_float {
            let v: f64 = num_str.parse().map_err(|_| ())?;
            Ok(Json::Float(v))
        } else {
            let v: i64 = num_str.parse().map_err(|_| ())?;
            Ok(Json::Int(v))
        }
    }
}

// --- Serializer ---
fn ser(j: &Json) -> String {
    let mut s = String::new();
    ser_into(j, &mut s);
    s
}

fn ser_into(j: &Json, out: &mut String) {
    match j {
        Json::Null => out.push_str("null"),
        Json::Bool(true) => out.push_str("true"),
        Json::Bool(false) => out.push_str("false"),
        Json::Int(i) => { out.push_str(&i.to_string()); }
        Json::Float(f) => { out.push_str(&f.to_string()); }
        Json::Str(s) => {
            out.push('"');
            for c in s.chars() {
                match c {
                    '"' => out.push_str("\\\""),
                    '\\' => out.push_str("\\\\"),
                    '\n' => out.push_str("\\n"),
                    '\r' => out.push_str("\\r"),
                    '\t' => out.push_str("\\t"),
                    '\u{08}' => out.push_str("\\b"),
                    '\u{0C}' => out.push_str("\\f"),
                    c if (c as u32) < 0x20 => { out.push_str(&format!("\\u{:04x}", c as u32)); }
                    c => out.push(c),
                }
            }
            out.push('"');
        }
        Json::Array(items) => {
            out.push('[');
            for (i, item) in items.iter().enumerate() {
                if i > 0 { out.push(','); }
                ser_into(item, out);
            }
            out.push(']');
        }
        Json::Object(pairs) => {
            out.push('{');
            for (i, (k, v)) in pairs.iter().enumerate() {
                if i > 0 { out.push(','); }
                ser_into(&Json::Str(k.clone()), out);
                out.push(':');
                ser_into(v, out);
            }
            out.push('}');
        }
    }
}

fn obj(pairs: Vec<(&str, Json)>) -> Json {
    Json::Object(pairs.into_iter().map(|(k, v)| (k.to_string(), v)).collect())
}
fn arr(items: Vec<Json>) -> Json { Json::Array(items) }
fn js(s: &str) -> Json { Json::Str(s.to_string()) }
fn ji(i: i64) -> Json { Json::Int(i) }
fn jb(b: bool) -> Json { Json::Bool(b) }

// --- Tool definitions ---
