// --- Server state ---
struct Server {
    initialized: bool,
    kv: HashMap<String, String>,
}

impl Server {
    fn new() -> Self { Server { initialized: false, kv: HashMap::new() } }

    fn process_line(&mut self, line: &str) -> Option<String> {
        // Rule 1: parse JSON
        let json = match Parser::new(line).parse() {
            Ok(v) => v,
            Err(_) => return Some(ser(&obj(vec![
                ("jsonrpc", js("2.0")),
                ("id", Json::Null),
                ("error", obj(vec![("code", ji(-32700)), ("message", js("Parse error"))])),
            ]))),
        };

        // Rule 2: not an object
        if !json.is_object() {
            return Some(ser(&obj(vec![
                ("jsonrpc", js("2.0")),
                ("id", Json::Null),
                ("error", obj(vec![("code", ji(-32600)), ("message", js("Invalid Request"))])),
            ])));
        }

        // Rule 3: response from client (no method, has result or error)
        if json.get("method").is_none() && (json.get("result").is_some() || json.get("error").is_some()) {
            return None;
        }

        // Rule 4: invalid request checks
        let jsonrpc_ok = json.get("jsonrpc").map_or(false, |v| v.as_str() == Some("2.0"));
        let method_val = json.get("method");
        let method_str = method_val.and_then(|v| v.as_str());
        let id_present = json.get("id").is_some();
        let id_val = json.get("id");
        let id_valid = id_val.map_or(false, |v| v.is_valid_id());

        if !jsonrpc_ok || method_str.is_none() || (id_present && !id_valid) {
            let out_id = if id_present && id_valid { id_val.unwrap().clone() } else { Json::Null };
            return Some(ser(&obj(vec![
                ("jsonrpc", js("2.0")),
                ("id", out_id),
                ("error", obj(vec![("code", ji(-32600)), ("message", js("Invalid Request"))])),
            ])));
        }

        // Rule 5: notification (no id)
        if !id_present {
            return None;
        }

        // Rule 6: request
        let id = id_val.unwrap().clone();
        let method = method_str.unwrap();

        // 6a: method not found
        if method != "initialize" && method != "ping" && method != "tools/list" && method != "tools/call" {
            return Some(ser(&obj(vec![
                ("jsonrpc", js("2.0")),
                ("id", id),
                ("error", obj(vec![("code", ji(-32601)), ("message", js("Method not found"))])),
            ])));
        }

        // 6b: params present but not object
        if let Some(p) = json.get("params") {
            if !p.is_object() {
                return Some(ser(&obj(vec![
                    ("jsonrpc", js("2.0")),
                    ("id", id),
                    ("error", obj(vec![("code", ji(-32602)), ("message", js("Invalid params"))])),
                ])));
            }
        }

        // 6c: not initialized
        if !self.initialized && method != "initialize" && method != "ping" {
            return Some(ser(&obj(vec![
                ("jsonrpc", js("2.0")),
                ("id", id),
                ("error", obj(vec![("code", ji(-32002)), ("message", js("Server not initialized"))])),
            ])));
        }

        // 6d: dispatch
        let result = match method {
            "initialize" => self.handle_initialize(json.get("params")),
            "ping" => Ok(obj(vec![])),
            "tools/list" => Ok(build_tools_list_result()),
            "tools/call" => self.handle_tools_call(json.get("params")),
            _ => unreachable!(),
        };

        match result {
            Ok(res) => Some(ser(&obj(vec![
                ("jsonrpc", js("2.0")),
                ("id", id),
                ("result", res),
            ]))),
            Err((code, msg)) => Some(ser(&obj(vec![
                ("jsonrpc", js("2.0")),
                ("id", id),
                ("error", obj(vec![("code", ji(code)), ("message", js(&msg))])),
            ]))),
        }
    }

    fn handle_initialize(&mut self, params: Option<&Json>) -> Result<Json, (i32, String)> {
        if self.initialized {
            return Err((-32600, "Already initialized".to_string()));
        }
        let params = match params {
            Some(p) => p,
            None => return Err((-32602, "Invalid params".to_string())),
        };
        let pv = match params.get("protocolVersion") {
            Some(Json::Str(s)) => s.clone(),
            _ => return Err((-32602, "Invalid params".to_string())),
        };
        self.initialized = true;
        let version = match pv.as_str() {
            "2025-06-18" | "2025-03-26" | "2024-11-05" => pv,
            _ => "2025-06-18".to_string(),
        };
        Ok(obj(vec![
            ("protocolVersion", js(&version)),
            ("capabilities", obj(vec![
                ("tools", obj(vec![("listChanged", jb(false))])),
            ])),
            ("serverInfo", obj(vec![
                ("name", js("cb2-kv")),
                ("title", js("CB2 key-value server")),
                ("version", js("1.4.2")),
            ])),
        ]))
    }

    fn handle_tools_call(&mut self, params: Option<&Json>) -> Result<Json, (i32, String)> {
        let params = match params {
            Some(p) => p,
            None => return Err((-32602, "Invalid params".to_string())),
        };
        let name = match params.get("name") {
            Some(Json::Str(s)) => s.clone(),
            _ => return Err((-32602, "Invalid params".to_string())),
        };

        let tools = tool_defs();
        let tool = match tools.iter().find(|t| t.name == name) {
            Some(t) => t,
            None => return Err((-32602, format!("Unknown tool: {}", name))),
        };

        // Get arguments
        let args: &Json;
        let empty_args = Json::Object(vec![]);
        match params.get("arguments") {
            None => args = &empty_args,
            Some(a) => {
                if !a.is_object() {
                    return Ok(tool_failure("arguments must be an object"));
                }
                args = a;
            }
        }

        // Validate arguments
        if let Some(err) = validate_args(tool, args) {
            return Ok(tool_failure(&err));
        }

        // Execute tool
        self.execute_tool(tool, args)
    }

    fn execute_tool(&mut self, tool: &ToolDef, args: &Json) -> Result<Json, (i32, String)> {
        match tool.name {
            "kv_set" => {
                let key = args.get("key").and_then(|v| v.as_str()).unwrap().to_string();
                let value = args.get("value").and_then(|v| v.as_str()).unwrap().to_string();
                let existed = self.kv.contains_key(&key);
                self.kv.insert(key.clone(), value);
                let text = if existed { format!("updated {}", key) } else { format!("created {}", key) };
                Ok(tool_success_text(text))
            }
            "kv_get" => {
                let key = args.get("key").and_then(|v| v.as_str()).unwrap().to_string();
                match self.kv.get(&key) {
                    Some(val) => Ok(tool_success_text(val.clone())),
                    None => Ok(tool_failure(&format!("key not found: {}", key))),
                }
            }
            "kv_list" => {
                let prefix = args.get("prefix").and_then(|v| v.as_str()).unwrap_or("").to_string();
                let mut keys: Vec<String> = self.kv.keys()
                    .filter(|k| k.starts_with(&prefix))
                    .cloned()
                    .collect();
                keys.sort();
                let count = keys.len() as i64;
                let structured = obj(vec![
                    ("keys", arr(keys.into_iter().map(|k| Json::Str(k)).collect())),
                    ("count", ji(count)),
                ]);
                Ok(tool_success_structured(structured))
            }
            "sum" => {
                let numbers = args.get("numbers").and_then(|v| v.as_array()).unwrap();
                let mut total: i64 = 0;
                for n in numbers {
                    total += n.as_int().unwrap();
                }
                let structured = obj(vec![
                    ("sum", ji(total)),
                    ("count", ji(numbers.len() as i64)),
                ]);
                Ok(tool_success_structured(structured))
            }
            "text_stats" => {
                let text = args.get("text").and_then(|v| v.as_str()).unwrap().to_string();
                let words = count_words(&text);
                let codepoints = text.chars().count() as i64;
                let utf8_bytes = text.len() as i64;
                let structured = obj(vec![
                    ("words", ji(words as i64)),
                    ("codepoints", ji(codepoints)),
                    ("utf8_bytes", ji(utf8_bytes)),
                ]);
                Ok(tool_success_structured(structured))
            }
            _ => unreachable!(),
        }
    }
}

fn count_words(text: &str) -> usize {
    let mut count = 0;
    let mut in_word = false;
    for c in text.chars() {
        if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
            in_word = false;
        } else {
            if !in_word {
                count += 1;
                in_word = true;
            }
        }
    }
    count
}

fn tool_success_text(text: String) -> Json {
    obj(vec![
        ("content", arr(vec![obj(vec![("type", js("text")), ("text", js(&text))])])),
        ("isError", jb(false)),
    ])
}

fn tool_success_structured(structured: Json) -> Json {
    let text = ser(&structured);
    obj(vec![
        ("content", arr(vec![obj(vec![("type", js("text")), ("text", js(&text))])])),
        ("structuredContent", structured),
        ("isError", jb(false)),
    ])
}

fn tool_failure(msg: &str) -> Json {
    obj(vec![
        ("content", arr(vec![obj(vec![("type", js("text")), ("text", js(msg))])])),
        ("isError", jb(true)),
    ])
}

fn validate_args(tool: &ToolDef, args: &Json) -> Option<String> {
    // Check for unknown arguments
    let valid_props: Vec<&str> = tool.properties.iter().map(|p| p.name).collect();
    if let Json::Object(pairs) = args {
        let mut unknowns: Vec<&str> = Vec::new();
        for (k, _) in pairs {
            if !valid_props.contains(&k.as_str()) {
                unknowns.push(k.as_str());
            }
        }
        if !unknowns.is_empty() {
            unknowns.sort();
            return Some(format!("unknown argument: {}", unknowns[0]));
        }
    }

    // Check each property in schema order
    for prop in &tool.properties {
        let val = args.get(prop.name);
        let is_required = tool.required.contains(&prop.name);

        if val.is_none() {
            if is_required {
                return Some(format!("missing required argument: {}", prop.name));
            }
            continue;
        }

        let val = val.unwrap();

        // Type check
        match prop.ty {
            "string" => {
                if !val.is_string() {
                    return Some(format!("argument {} must be a string", prop.name));
                }
                if prop.min_len {
                    let s = val.as_str().unwrap();
                    if s.is_empty() {
                        return Some(format!("argument {} must not be empty", prop.name));
                    }
                }
            }
            "array_int" => {
                if let Some(items) = val.as_array() {
                    // check all items are integers
                    for item in items {
                        if item.as_int().is_none() {
                            return Some(format!("argument {} must be an array of integers", prop.name));
                        }
                    }
                    if prop.min_len && items.is_empty() {
                        return Some(format!("argument {} must not be empty", prop.name));
                    }
                } else {
                    return Some(format!("argument {} must be an array of integers", prop.name));
                }
            }
            _ => {}
        }
    }

    None
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    let mut out = stdout.lock();
    let mut server = Server::new();

    for line_result in stdin.lock().lines() {
        let line = match line_result {
            Ok(l) => l,
            Err(_) => break,
        };
        // Check if line is empty or only spaces/tabs/CR
        if line.is_empty() || line.chars().all(|c| c == ' ' || c == '\t' || c == '\r') {
            continue;
        }
        // Strip trailing \r for CRLF
        let line = line.trim_end_matches('\r');
        if line.is_empty() { continue; }

        if let Some(response) = server.process_line(line) {
            out.write_all(response.as_bytes()).unwrap();
            out.write_all(b"\n").unwrap();
        }
    }

    out.flush().unwrap();
}

use std::io::{self, BufRead, Write};
use std::collections::HashMap;

#[derive(Debug, Clone)]
enum Json {
    Null,
    Bool(bool),
    Int(i64),
    Float(f64),
    Str(String),
    Array(Vec<Json>),
    Object(Vec<(String, Json)>),
}

impl Json {
    fn get(&self, key: &str) -> Option<&Json> {
        if let Json::Object(pairs) = self {
            for (k, v) in pairs {
                if k == key { return Some(v); }
            }
        }
        None
    }
    fn is_object(&self) -> bool { matches!(self, Json::Object(_)) }
    fn is_string(&self) -> bool { matches!(self, Json::Str(_)) }
    fn as_str(&self) -> Option<&str> { if let Json::Str(s) = self { Some(s) } else { None } }
    fn as_bool(&self) -> Option<bool> { if let Json::Bool(b) = self { Some(*b) } else { None } }
    fn as_int(&self) -> Option<i64> { if let Json::Int(i) = self { Some(*i) } else { None } }
    fn as_array(&self) -> Option<&[Json]> { if let Json::Array(a) = self { Some(a) } else { None } }
    fn is_valid_id(&self) -> bool { matches!(self, Json::Str(_) | Json::Int(_)) }
}

// --- Parser ---
struct Parser<'a> {
    s: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self { Parser { s: s.as_bytes(), pos: 0 } }

    fn parse(&mut self) -> Result<Json, ()> {
        self.skip_ws();
        let v = self.parse_value()?;
        self.skip_ws();
        if self.pos != self.s.len() { return Err(()); }
        Ok(v)
    }

    fn skip_ws(&mut self) {
        while self.pos < self.s.len() {
            match self.s[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn peek(&self) -> Option<u8> { self.s.get(self.pos).copied() }
    fn eat(&mut self, c: u8) -> Result<(), ()> {
        if self.peek() == Some(c) { self.pos += 1; Ok(()) } else { Err(()) }
    }

    fn parse_value(&mut self) -> Result<Json, ()> {
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => Ok(Json::Str(self.parse_string()?)),
            Some(b't') => { self.expect_lit(b"true")?; Ok(Json::Bool(true)) }
            Some(b'f') => { self.expect_lit(b"false")?; Ok(Json::Bool(false)) }
            Some(b'n') => { self.expect_lit(b"null")?; Ok(Json::Null) }
            Some(c) if c == b'-' || (c >= b'0' && c <= b'9') => self.parse_number(),
            _ => Err(()),
        }
    }

    fn expect_lit(&mut self, lit: &[u8]) -> Result<(), ()> {
        if self.s[self.pos..].starts_with(lit) { self.pos += lit.len(); Ok(()) } else { Err(()) }
    }

    fn parse_object(&mut self) -> Result<Json, ()> {
        self.eat(b'{')?;
        let mut pairs = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b'}') { self.pos += 1; return Ok(Json::Object(pairs)); }
        loop {
            self.skip_ws();
            let key = self.parse_string()?;
            self.skip_ws();
            self.eat(b':')?;
            self.skip_ws();
            let val = self.parse_value()?;
            pairs.push((key, val));
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b'}') => { self.pos += 1; break; }
                _ => return Err(()),
            }
        }
        Ok(Json::Object(pairs))
    }

    fn parse_array(&mut self) -> Result<Json, ()> {
        self.eat(b'[')?;
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b']') { self.pos += 1; return Ok(Json::Array(items)); }
        loop {
            self.skip_ws();
            let val = self.parse_value()?;
            items.push(val);
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b']') => { self.pos += 1; break; }
                _ => return Err(()),
            }
        }
        Ok(Json::Array(items))
    }

    fn parse_string(&mut self) -> Result<String, ()> {
        self.eat(b'"')?;
        let mut out = Vec::new();
        loop {
            if self.pos >= self.s.len() { return Err(()); }
            let c = self.s[self.pos];
            match c {
                b'"' => { self.pos += 1; break; }
                b'\\' => {
                    self.pos += 1;
                    if self.pos >= self.s.len() { return Err(()); }
                    match self.s[self.pos] {
                        b'"' => { out.push(b'"'); self.pos += 1; }
                        b'\\' => { out.push(b'\\'); self.pos += 1; }
                        b'/' => { out.push(b'/'); self.pos += 1; }
                        b'b' => { out.push(0x08); self.pos += 1; }
                        b'f' => { out.push(0x0C); self.pos += 1; }
                        b'n' => { out.push(b'\n'); self.pos += 1; }
                        b'r' => { out.push(b'\r'); self.pos += 1; }
                        b't' => { out.push(b'\t'); self.pos += 1; }
                        b'u' => {
                            self.pos += 1;
                            let cp = self.parse_hex4()?;
                            if (0xD800..=0xDBFF).contains(&cp) {
                                self.eat(b'\\')?;
                                self.eat(b'u')?;
                                let lo = self.parse_hex4()?;
                                if !(0xDC00..=0xDFFF).contains(&lo) { return Err(()); }
                                let full = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                                let ch = char::from_u32(full).ok_or(())?;
                                let mut buf = [0u8; 4];
                                out.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                            } else if (0xDC00..=0xDFFF).contains(&cp) {
                                return Err(());
                            } else {
                                let ch = char::from_u32(cp).ok_or(())?;
                                let mut buf = [0u8; 4];
                                out.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                            }
                        }
                        _ => return Err(()),
                    }
                }
                0x00..=0x1F => return Err(()),
                _ => { out.push(c); self.pos += 1; }
            }
        }
        String::from_utf8(out).map_err(|_| ())
    }

    fn parse_hex4(&mut self) -> Result<u32, ()> {
        if self.pos + 4 > self.s.len() { return Err(()); }
        let mut val: u32 = 0;
        for i in 0..4 {
            let c = self.s[self.pos + i];
            let d = match c {
                b'0'..=b'9' => (c - b'0') as u32,
                b'a'..=b'f' => (c - b'a' + 10) as u32,
                b'A'..=b'F' => (c - b'A' + 10) as u32,
                _ => return Err(()),
            };
            val = val * 16 + d;
        }
        self.pos += 4;
        Ok(val)
    }

    fn parse_number(&mut self) -> Result<Json, ()> {
        let start = self.pos;
        let mut is_float = false;
        if self.peek() == Some(b'-') { self.pos += 1; }
        // int part
        match self.peek() {
            Some(b'0') => { self.pos += 1; }
            Some(c) if c >= b'1' && c <= b'9' => { while self.peek().map_or(false, |c| c >= b'0' && c <= b'9') { self.pos += 1; } }
            _ => return Err(()),
        }
        // frac
        if self.peek() == Some(b'.') {
            is_float = true;
            self.pos += 1;
            if !self.peek().map_or(false, |c| c >= b'0' && c <= b'9') { return Err(()); }
            while self.peek().map_or(false, |c| c >= b'0' && c <= b'9') { self.pos += 1; }
        }
        // exp
        if self.peek().map_or(false, |c| c == b'e' || c == b'E') {
            is_float = true;
            self.pos += 1;
            if self.peek().map_or(false, |c| c == b'+' || c == b'-') { self.pos += 1; }
            if !self.peek().map_or(false, |c| c >= b'0' && c <= b'9') { return Err(()); }
            while self.peek().map_or(false, |c| c >= b'0' && c <= b'9') { self.pos += 1; }
        }
        let num_str = &self.s[start..self.pos];
        let num_str = std::str::from_utf8(num_str).map_err(|_| ())?;
        if is_float {
            let v: f64 = num_str.parse().map_err(|_| ())?;
            Ok(Json::Float(v))
        } else {
            let v: i64 = num_str.parse().map_err(|_| ())?;
            Ok(Json::Int(v))
        }
    }
}

// --- Serializer ---
fn ser(j: &Json) -> String {
    let mut s = String::new();
    ser_into(j, &mut s);
    s
}

fn ser_into(j: &Json, out: &mut String) {
    match j {
        Json::Null => out.push_str("null"),
        Json::Bool(true) => out.push_str("true"),
        Json::Bool(false) => out.push_str("false"),
        Json::Int(i) => { out.push_str(&i.to_string()); }
        Json::Float(f) => {
            if f.fract() == 0.0 && f.is_finite() {
                out.push_str(&(*f as i64).to_string());
            } else {
                out.push_str(&f.to_string());
            }
        }
        Json::Str(s) => {
            out.push('"');
            for c in s.chars() {
                match c {
                    '"' => out.push_str("\\\""),
                    '\\' => out.push_str("\\\\"),
                    '\n' => out.push_str("\\n"),
                    '\r' => out.push_str("\\r"),
                    '\t' => out.push_str("\\t"),
                    '\u{08}' => out.push_str("\\b"),
                    '\u{0C}' => out.push_str("\\f"),
                    c if (c as u32) < 0x20 => { out.push_str(&format!("\\u{:04x}", c as u32)); }
                    c => out.push(c),
                }
            }
            out.push('"');
        }
        Json::Array(items) => {
            out.push('[');
            for (i, item) in items.iter().enumerate() {
                if i > 0 { out.push(','); }
                ser_into(item, out);
            }
            out.push(']');
        }
        Json::Object(pairs) => {
            out.push('{');
            for (i, (k, v)) in pairs.iter().enumerate() {
                if i > 0 { out.push(','); }
                ser_into(&Json::Str(k.clone()), out);
                out.push(':');
                ser_into(v, out);
            }
            out.push('}');
        }
    }
}

fn obj(pairs: Vec<(&str, Json)>) -> Json {
    Json::Object(pairs.into_iter().map(|(k, v)| (k.to_string(), v)).collect())
}
fn arr(items: Vec<Json>) -> Json { Json::Array(items) }
fn js(s: &str) -> Json { Json::Str(s.to_string()) }
fn ji(i: i64) -> Json { Json::Int(i) }
fn jb(b: bool) -> Json { Json::Bool(b) }

