}
static bool is_int_val(jval *v){
    return v && v->t==JV_INT;
}

/* Build failure result */
static void build_fail(sb_t *out, const char *msg){
    sb_puts(out,"{\"content\":[");
    sb_puts(out,"{\"type\":\"text\",\"text\":");
    ser_string(out,msg);
    sb_puts(out,"}],\"isError\":true}");
}
/* Build success result (no outputSchema) */
static void build_ok_text(sb_t *out, const char *text){
    sb_puts(out,"{\"content\":[");
    sb_puts(out,"{\"type\":\"text\",\"text\":");
    ser_string(out,text);
    sb_puts(out,"}],\"isError\":false}");
}
/* Build success result (with outputSchema) */
static void build_ok_struct(sb_t *out, jval *structured){
    sb_puts(out,"{\"content\":[{\"type\":\"text\",\"text\":");
    sb_t inner; sb_init(&inner);
    ser_value(&inner,structured);
    sb_putc(&inner,0);
    ser_string(out,inner.b);
    free(inner.b);
    sb_puts(out,"}],\"structuredContent\":");
    ser_value(out,structured);
    sb_puts(out,",\"isError\":false}");
}

static void validate_and_run(sb_t *out, const char *tool_name, jval *args){
    /* args is the arguments object (or NULL meaning empty) */
    int np;
    const char **props = get_tool_props(tool_name, &np);

    /* Check unknown arguments */
    if(args && args->t==JV_OBJ){
        const char *smallest = NULL;
        for(size_t i=0;i<args->o.n;i++){
            bool known=false;
            for(int j=0;j<np;j++){
                if(strcmp(args->o.k[i],props[j])==0){ known=true; break; }
            }
            if(!known){
                if(!smallest || strcmp(args->o.k[i],smallest)<0) smallest=args->o.k[i];
            }
        }
        if(smallest){
            char msg[256]; snprintf(msg,sizeof(msg),"unknown argument: %s",smallest);
            build_fail(out,msg); return;
        }
    }

    /* Check each property in schema order */
    for(int j=0;j<np;j++){
        const char *pn=props[j];
        jval *pv = args ? obj_get(args,pn) : NULL;
        bool present = args && obj_has(args,pn);

        if(!present){
            if(is_required(tool_name,pn)){
                char msg[256]; snprintf(msg,sizeof(msg),"missing required argument: %s",pn);
                build_fail(out,msg); return;
            }
            continue;
        }

        /* Type check */
        if(is_array_int(tool_name,pn)){
            if(pv->t!=JV_ARR){
                char msg[256]; snprintf(msg,sizeof(msg),"argument %s must be an array of integers",pn);
                build_fail(out,msg); return;
            }
            for(size_t k=0;k<pv->a.n;k++){
                if(!is_int_val(pv->a.v[k])){
                    char msg[256]; snprintf(msg,sizeof(msg),"argument %s must be an array of integers",pn);
                    build_fail(out,msg); return;
                }
            }
            if(has_minItems(tool_name,pn) && pv->a.n==0){
                char msg[256]; snprintf(msg,sizeof(msg),"argument %s must not be empty",pn);
                build_fail(out,msg); return;
            }
        } else {
            /* string type */
            if(pv->t!=JV_STR){
                char msg[256]; snprintf(msg,sizeof(msg),"argument %s must be a string",pn);
                build_fail(out,msg); return;
            }
            if(has_minLength(tool_name,pn) && pv->s[0]=='\0'){
                char msg[256]; snprintf(msg,sizeof(msg),"argument %s must not be empty",pn);
                build_fail(out,msg); return;
            }
        }
    }

    /* Execute tool */
    if(!strcmp(tool_name,"kv_set")){
        jval *kv=obj_get(args,"key"), *vv=obj_get(args,"value");
        bool existed = false;
        for(size_t i=0;i<kv_count;i++) if(strcmp(kv_store[i].key,kv->s)==0){ existed=true; break; }
        kv_set(kv->s, vv->s);
        char msg[512]; snprintf(msg,sizeof(msg),"%s %s",existed?"updated":"created",kv->s);
        build_ok_text(out,msg);
    } else if(!strcmp(tool_name,"kv_get")){
        jval *kv=obj_get(args,"key");
        char *val=NULL;
        if(!kv_find(kv->s,&val)){
            char msg[512]; snprintf(msg,sizeof(msg),"key not found: %s",kv->s);
            build_fail(out,msg); return;
        }
        build_ok_text(out,val);
    } else if(!strcmp(tool_name,"kv_list")){
        const char *prefix = "";
        jval *pv = args ? obj_get(args,"prefix") : NULL;
        if(pv && pv->t==JV_STR) prefix=pv->s;
        size_t plen=strlen(prefix);
        /* Collect matching keys */
        const char **keys=NULL; size_t kn=0,kcap=0;
        for(size_t i=0;i<kv_count;i++){
            if(strncmp(kv_store[i].key,prefix,plen)==0){
                if(kn==kcap){ kcap=kcap?kcap*2:16; keys=realloc(keys,kcap*sizeof(char*)); }
                keys[kn++]=kv_store[i].key;
            }
        }
        /* Sort by strcmp (code point order for UTF-8) */
        for(size_t i=1;i<kn;i++){
            const char *tmp=keys[i];
            size_t j=i;
            while(j>0&&strcmp(keys[j-1],tmp)>0){ keys[j]=keys[j-1]; j--; }
            keys[j]=tmp;
        }
        jval *s=jv_obj();
        jval *ka=jv_arr();
        for(size_t i=0;i<kn;i++) jval_arr_push(ka,jv_str(keys[i]));
        jval_obj_put(s,"keys",ka);
        jval_obj_put(s,"count",jv_int((long long)kn));
        build_ok_struct(out,s);
        jval_free(s); free(keys);
    } else if(!strcmp(tool_name,"sum")){
        jval *na=obj_get(args,"numbers");
        long long total=0;
        for(size_t i=0;i<na->a.n;i++) total+=na->a.v[i]->i;
        jval *s=jv_obj();
        jval_obj_put(s,"sum",jv_int(total));
        jval_obj_put(s,"count",jv_int((long long)na->a.n));
        build_ok_struct(out,s);
        jval_free(s);
    } else if(!strcmp(tool_name,"text_stats")){
        jval *tv=obj_get(args,"text");
        const char *text=tv->s;
        size_t tlen=strlen(text);
        /* words */
        long long words=0;
        bool in_word=false;
        for(size_t i=0;i<tlen;i++){
            char c=text[i];
            if(c==' '||c=='\t'||c=='\n'||c=='\r'){
                in_word=false;
            } else {
                if(!in_word){ words++; in_word=true; }
            }
        }
        /* codepoints */
        long long cps=0;
        for(size_t i=0;i<tlen;){
            unsigned char c=(unsigned char)text[i];
            if(c<0x80) i+=1;
            else if(c<0xE0) i+=2;
            else if(c<0xF0) i+=3;
            else i+=4;
            cps++;
        }
        /* utf8_bytes */
        jval *s=jv_obj();
        jval_obj_put(s,"words",jv_int(words));
        jval_obj_put(s,"codepoints",jv_int(cps));
        jval_obj_put(s,"utf8_bytes",jv_int((long long)tlen));
        build_ok_struct(out,s);
        jval_free(s);
    }
}

/* ==================== MCP Server State ==================== */
static bool server_initialized=false;

/* ==================== Message Processing ==================== */
static void emit_error(sb_t *out, jval *id, int code, const char *msg){
    sb_puts(out,"{\"jsonrpc\":\"2.0\",\"id\":");
    ser_value(out,id);
    sb_puts(out,",\"error\":{\"code\":");
    sb_printf(out,"%d",code);
    sb_puts(out,",\"message\":");
    ser_string(out,msg);
    sb_puts(out,"}}");
}
static void emit_result(sb_t *out, jval *id, const char *result_json){
    sb_puts(out,"{\"jsonrpc\":\"2.0\",\"id\":");
    ser_value(out,id);
    sb_puts(out,",\"result\":");
    sb_puts(out,result_json);
    sb_puts(out,"}");
}
static void emit_result_jval(sb_t *out, jval *id, jval *result){
    sb_puts(out,"{\"jsonrpc\":\"2.0\",\"id\":");
    ser_value(out,id);
    sb_puts(out,",\"result\":");
    ser_value(out,result);
    sb_puts(out,"}");
}

static void process_line(const char *line, size_t len, sb_t *out){
    /* Parse JSON */
    jval *msg = parse_json(line, len);
    if(!msg){
        emit_error(out, NULL, -32700, "Parse error");
        sb_putc(out,'\n');
        return;
    }
    /* Must be object */
    if(msg->t!=JV_OBJ){
        emit_error(out, NULL, -32600, "Invalid Request");
        jval_free(msg); sb_putc(out,'\n'); return;
    }
    /* Client response: no method, has result or error */
    jval *method = obj_get(msg,"method");
    jval *result = obj_get(msg,"result");
    jval *error  = obj_get(msg,"error");
    if(!method && (result||error)){
        jval_free(msg); return;
    }
    /* Check invalid request */
    jval *jsonrpc = obj_get(msg,"jsonrpc");
    jval *id = obj_get(msg,"id");
    bool invalid = false;
    if(!jsonrpc || jsonrpc->t!=JV_STR || strcmp(jsonrpc->s,"2.0")!=0) invalid=true;
    if(!method || method->t!=JV_STR) invalid=true;
    if(obj_has(msg,"id") && !is_valid_id(id)) invalid=true;

    if(invalid){
        jval *echo_id = (obj_has(msg,"id") && is_valid_id(id)) ? id : NULL;
        emit_error(out, echo_id, -32600, "Invalid Request");
        sb_putc(out,'\n');
        jval_free(msg); return;
    }

    /* Notification: no id member */
    if(!obj_has(msg,"id")){
        jval_free(msg); return;
    }

    /* It's a request. Echo id. */
    const char *mname = method->s;

    /* Check method */
    if(strcmp(mname,"initialize")!=0 && strcmp(mname,"ping")!=0 &&
       strcmp(mname,"tools/list")!=0 && strcmp(mname,"tools/call")!=0){
        emit_error(out, id, -32601, "Method not found");
        sb_putc(out,'\n'); jval_free(msg); return;
    }

    /* Check params */
    jval *params = obj_get(msg,"params");
    if(params && params->t!=JV_OBJ){
        emit_error(out, id, -32602, "Invalid params");
        sb_putc(out,'\n'); jval_free(msg); return;
    }

    /* Check initialized */
    if(!server_initialized && strcmp(mname,"initialize")!=0 && strcmp(mname,"ping")!=0){
        emit_error(out, id, -32002, "Server not initialized");
        sb_putc(out,'\n'); jval_free(msg); return;
    }

    /* Dispatch */
    if(!strcmp(mname,"initialize")){
        if(server_initialized){
            emit_error(out, id, -32600, "Already initialized");
            sb_putc(out,'\n'); jval_free(msg); return;
        }
        if(!params){
            emit_error(out, id, -32602, "Invalid params");
            sb_putc(out,'\n'); jval_free(msg); return;
        }
        jval *pv = obj_get(params,"protocolVersion");
        if(!pv || pv->t!=JV_STR){
            emit_error(out, id, -32602, "Invalid params");
            sb_putc(out,'\n'); jval_free(msg); return;
        }
        server_initialized=true;
        const char *ver = pv->s;
        const char *resp_ver = "2025-06-18";
        if(strcmp(ver,"2025-06-18")==0||strcmp(ver,"2025-03-26")==0||strcmp(ver,"2024-11-05")==0)
            resp_ver=ver;
        jval *res=jv_obj();
        jval_obj_put(res,"protocolVersion",jv_str(resp_ver));
        jval *caps=jv_obj();
        jval *tools_cap=jv_obj();
        jval_obj_put(tools_cap,"listChanged",jv_bool(0));
        jval_obj_put(caps,"tools",tools_cap);
        jval_obj_put(res,"capabilities",caps);
        jval *si=jv_obj();
        jval_obj_put(si,"name",jv_str("cb2-kv"));
        jval_obj_put(si,"title",jv_str("CB2 key-value server"));
        jval_obj_put(si,"version",jv_str("1.4.2"));
        jval_obj_put(res,"serverInfo",si);
        emit_result_jval(out,id,res);
        sb_putc(out,'\n');
        jval_free(res); jval_free(msg); return;
    }
    if(!strcmp(mname,"ping")){
        jval *res=jv_obj();
        emit_result_jval(out,id,res);
        sb_putc(out,'\n');
        jval_free(res); jval_free(msg); return;
    }
    if(!strcmp(mname,"tools/list")){
        emit_result(out,id,TOOLS_LIST_JSON);
        sb_putc(out,'\n');
        jval_free(msg); return;
    }
    if(!strcmp(mname,"tools/call")){
        if(!params){
            emit_error(out, id, -32602, "Invalid params");
            sb_putc(out,'\n'); jval_free(msg); return;
        }
        jval *pname = obj_get(params,"name");
        if(!pname || pname->t!=JV_STR){
            emit_error(out, id, -32602, "Invalid params");
            sb_putc(out,'\n'); jval_free(msg); return;
        }
        const char *tn=pname->s;
        bool known=false;
        for(int i=0;i<5;i++) if(strcmp(tn,tool_names[i])==0){ known=true; break; }
        if(!known){
            char msg[256]; snprintf(msg,sizeof(msg),"Unknown tool: %s",tn);
            emit_error(out, id, -32602, msg);
            sb_putc(out,'\n'); jval_free(msg); return;
        }
        jval *arguments = obj_get(params,"arguments");
        /* Validate arguments */
        if(arguments && arguments->t!=JV_OBJ){
            build_fail(out,"arguments must be an object");
            sb_puts(out,"\n");
            /* Actually we need to wrap in result */
            /* Let me redo this */
            /* We need: {"jsonrpc":"2.0","id":<id>,"result":<tool_result>} */
            /* Let me restructure */
            jval_free(msg); return; /* placeholder - will fix */
        }
        /* Build the result */
        sb_t tool_res; sb_init(&tool_res);
        if(arguments && arguments->t!=JV_OBJ){
            build_fail(&tool_res,"arguments must be an object");
        } else {
            validate_and_run(&tool_res, tn, arguments);
        }
        sb_putc(&tool_res,0);
        emit_result(out, id, tool_res.b);
        sb_putc(out,'\n');
        free(tool_res.b);
        jval_free(msg); return;
    }

    jval_free(msg);
}

/* ==================== Main ==================== */
int main(void){
    char *line=NULL;
    size_t bufsz=0;
    ssize_t nread;
    while((nread=getline(&line,&bufsz,stdin))!=-1){
        /* Strip trailing \r and \n */
        while(nread>0 && (line[nread-1]=='\n'||line[nread-1]=='\r')) nread--;
        /* Check if empty or all whitespace */
        bool skip=true;
        for(ssize_t i=0;i<nread;i++){
            char c=line[i];
            if(c!=' '&&c!='\t'&&c!='\r'){ skip=false; break; }
        }
        if(skip) continue;

        sb_t out; sb_init(&out);
        process_line(line, (size_t)nread, &out);
        if(out.len>0){
            fwrite(out.b,1,out.len,stdout);
        }
        sb_free(&out);
    }
    free(line);
    fflush(stdout);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <stdarg.h>

/* ==================== String Buffer ==================== */
typedef struct { char *b; size_t len, cap; } sb_t;
static void sb_init(sb_t *s){ s->b=NULL; s->len=0; s->cap=0; }
static void sb_grow(sb_t *s, size_t need){
    if(s->len+need<=s->cap) return;
    size_t nc = s->cap?s->cap*2:64;
    while(nc < s->len+need) nc*=2;
    s->b = realloc(s->b, nc);
    s->cap = nc;
}
static void sb_putc(sb_t *s, char c){ sb_grow(s,1); s->b[s->len++]=c; }
static void sb_puts(sb_t *s, const char *str){ size_t l=strlen(str); sb_grow(s,l); memcpy(s->b+s->len,str,l); s->len+=l; }
static void sb_putn(sb_t *s, const char *str, size_t n){ sb_grow(s,n); memcpy(s->b+s->len,str,n); s->len+=n; }
static void sb_printf(sb_t *s, const char *fmt, ...){
    va_list ap; va_start(ap,fmt);
    int n = vsnprintf(NULL,0,fmt,ap); va_end(ap);
    sb_grow(s,n);
    va_start(ap,fmt); vsnprintf(s->b+s->len,n+1,fmt,ap); va_end(ap);
    s->len+=n;
}
static void sb_free(sb_t *s){ free(s->b); s->b=NULL; s->len=0; s->cap=0; }

/* ==================== JSON Value ==================== */
typedef enum { JV_NULL, JV_TRUE, JV_FALSE, JV_INT, JV_DBL, JV_STR, JV_ARR, JV_OBJ } jtype;
typedef struct jval {
    jtype t;
    union {
        long long i;
        double d;
        char *s;
        struct { struct jval **v; size_t n; } a;
        struct { char **k; struct jval **v; size_t n; } o;
    };
} jval;

static jval *jv_null(void){ jval *v=calloc(1,sizeof(jval)); v->t=JV_NULL; return v; }
static jval *jv_bool(int b){ jval *v=calloc(1,sizeof(jval)); v->t=b?JV_TRUE:JV_FALSE; return v; }
static jval *jv_int(long long i){ jval *v=calloc(1,sizeof(jval)); v->t=JV_INT; v->i=i; return v; }
static jval *jv_dbl(double d){ jval *v=calloc(1,sizeof(jval)); v->t=JV_DBL; v->d=d; return v; }
static jval *jv_str(const char *s){ jval *v=calloc(1,sizeof(jval)); v->t=JV_STR; v->s=strdup(s); return v; }
static jval *jv_arr(void){ jval *v=calloc(1,sizeof(jval)); v->t=JV_ARR; return v; }
static jval *jv_obj(void){ jval *v=calloc(1,sizeof(jval)); v->t=JV_OBJ; return v; }
static void jval_free(jval *v){
    if(!v) return;
    if(v->t==JV_STR) free(v->s);
    else if(v->t==JV_ARR){ for(size_t i=0;i<v->a.n;i++) jval_free(v->a.v[i]); free(v->a.v); }
    else if(v->t==JV_OBJ){ for(size_t i=0;i<v->o.n;i++){ free(v->o.k[i]); jval_free(v->o.v[i]); } free(v->o.k); free(v->o.v); }
    free(v);
}
static void jval_arr_push(jval *a, jval *item){
    a->a.v = realloc(a->a.v, (a->a.n+1)*sizeof(jval*));
    a->a.v[a->a.n++] = item;
}
static void jval_obj_put(jval *o, const char *key, jval *val){
    o->o.k = realloc(o->o.k, (o->o.n+1)*sizeof(char*));
    o->o.v = realloc(o->o.v, (o->o.n+1)*sizeof(jval*));
    o->o.k[o->o.n] = strdup(key);
    o->o.v[o->o.n] = val;
    o->o.n++;
}
static jval *obj_get(jval *o, const char *key){
    if(!o || o->t!=JV_OBJ) return NULL;
    for(size_t i=0;i<o->o.n;i++) if(strcmp(o->o.k[i],key)==0) return o->o.v[i];
    return NULL;
}
static bool obj_has(jval *o, const char *key){
    if(!o || o->t!=JV_OBJ) return false;
    for(size_t i=0;i<o->o.n;i++) if(strcmp(o->o.k[i],key)==0) return true;
    return false;
}

/* ==================== JSON Parser ==================== */
typedef struct { const char *s; size_t pos, len; int err; } parser_t;
static void p_err(parser_t *p){ p->err=1; }
static void p_ws(parser_t *p){
    while(p->pos<p->len){
        char c=p->s[p->pos];
        if(c==' '||c=='\t'||c=='\n'||c=='\r') p->pos++;
        else break;
    }
}
static jval *p_value(parser_t *p);
static int p_hex4(parser_t *p, unsigned *out){
    if(p->pos+4>p->len) return 0;
    unsigned v=0;
    for(int i=0;i<4;i++){
        char c=p->s[p->pos++];
        if(c>='0'&&c<='9') v=v*16+(c-'0');
        else if(c>='a'&&c<='f') v=v*16+(c-'a'+10);
        else if(c>='A'&&c<='F') v=v*16+(c-'A'+10);
        else { p->pos--; return 0; }
    }
    *out=v; return 1;
}
static void utf8_encode(sb_t *s, unsigned cp){
    if(cp<0x80){ sb_putc(s,(char)cp); }
    else if(cp<0x800){ sb_putc(s,(char)(0xC0|(cp>>6))); sb_putc(s,(char)(0x80|(cp&0x3F))); }
    else if(cp<0x10000){ sb_putc(s,(char)(0xE0|(cp>>12))); sb_putc(s,(char)(0x80|((cp>>6)&0x3F))); sb_putc(s,(char)(0x80|(cp&0x3F))); }
    else { sb_putc(s,(char)(0xF0|(cp>>18))); sb_putc(s,(char)(0x80|((cp>>12)&0x3F))); sb_putc(s,(char)(0x80|((cp>>6)&0x3F))); sb_putc(s,(char)(0x80|(cp&0x3F))); }
}
static char *p_string(parser_t *p){
    if(p->pos>=p->len||p->s[p->pos]!='"'){ p_err(p); return NULL; }
    p->pos++;
    sb_t sb; sb_init(&sb);
    while(p->pos<p->len){
        char c=p->s[p->pos];
        if(c=='"'){ p->pos++; sb_putc(&sb,0); return sb.b; }
        if(c=='\\'){
            p->pos++;
            if(p->pos>=p->len){ p_err(p); free(sb.b); return NULL; }
            char e=p->s[p->pos++];
            switch(e){
                case '"': sb_putc(&sb,'"'); break;
                case '\\': sb_putc(&sb,'\\'); break;
                case '/': sb_putc(&sb,'/'); break;
                case 'b': sb_putc(&sb,'\b'); break;
                case 'f': sb_putc(&sb,'\f'); break;
                case 'n': sb_putc(&sb,'\n'); break;
                case 'r': sb_putc(&sb,'\r'); break;
                case 't': sb_putc(&sb,'\t'); break;
                case 'u': {
                    unsigned cp;
                    if(!p_hex4(p,&cp)){ p_err(p); free(sb.b); return NULL; }
                    if(cp>=0xD800&&cp<=0xDBFF){
                        if(p->pos+1<p->len&&p->s[p->pos]=='\\'&&p->s[p->pos+1]=='u'){
                            p->pos+=2;
                            unsigned lo;
                            if(!p_hex4(p,&lo)){ p_err(p); free(sb.b); return NULL; }
                            if(lo>=0xDC00&&lo<=0xDFFF){
                                cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                            } else {
                                utf8_encode(&sb,cp);
                                utf8_encode(&sb,lo);
                                cp=0;
                            }
                        } else {
                            utf8_encode(&sb,cp); cp=0;
                        }
                        if(cp!=0) utf8_encode(&sb,cp);
                    } else {
                        utf8_encode(&sb,cp);
                    }
                    break;
                }
                default: p_err(p); free(sb.b); return NULL;
            }
        } else if((unsigned char)c<0x20){
            p_err(p); free(sb.b); return NULL;
        } else {
            sb_putc(&sb,c); p->pos++;
        }
    }
    p_err(p); free(sb.b); return NULL;
}
static jval *p_number(parser_t *p){
    size_t start=p->pos;
    bool is_int=true;
    if(p->pos<p->len&&p->s[p->pos]=='-') p->pos++;
    if(p->pos>=p->len){ p_err(p); return NULL; }
    if(p->s[p->pos]=='0'){ p->pos++; }
    else if(p->s[p->pos]>='1'&&p->s[p->pos]<='9'){ while(p->pos<p->len&&p->s[p->pos]>='0'&&p->s[p->pos]<='9') p->pos++; }
    else { p_err(p); return NULL; }
    if(p->pos<p->len&&p->s[p->pos]=='.'){
        is_int=false; p->pos++;
        if(p->pos>=p->len||p->s[p->pos]<'0'||p->s[p->pos]>'9'){ p_err(p); return NULL; }
        while(p->pos<p->len&&p->s[p->pos]>='0'&&p->s[p->pos]<='9') p->pos++;
    }
    if(p->pos<p->len&&(p->s[p->pos]=='e'||p->s[p->pos]=='E')){
        is_int=false; p->pos++;
        if(p->pos<p->len&&(p->s[p->pos]=='+'||p->s[p->pos]=='-')) p->pos++;
        if(p->pos>=p->len||p->s[p->pos]<'0'||p->s[p->pos]>'9'){ p_err(p); return NULL; }
        while(p->pos<p->len&&p->s[p->pos]>='0'&&p->s[p->pos]<='9') p->pos++;
    }
    size_t nlen=p->pos-start;
    char *tmp=malloc(nlen+1); memcpy(tmp,p->s+start,nlen); tmp[nlen]=0;
    if(is_int){
        long long v=strtoll(tmp,NULL,10);
        free(tmp);
        return jv_int(v);
    } else {
        double v=strtod(tmp,NULL);
        free(tmp);
        return jv_dbl(v);
    }
}
static jval *p_value(parser_t *p){
    if(p->err) return NULL;
    p_ws(p);
    if(p->pos>=p->len){ p_err(p); return NULL; }
    char c=p->s[p->pos];
    if(c=='"'){
        char *s=p_string(p);
        if(!s) return NULL;
        jval *v=calloc(1,sizeof(jval)); v->t=JV_STR; v->s=s; return v;
    }
    if(c=='{'){
        p->pos++;
        jval *o=jv_obj();
        p_ws(p);
        if(p->pos<p->len&&p->s[p->pos]=='}'){ p->pos++; return o; }
        while(1){
            p_ws(p);
            if(p->pos>=p->len||p->s[p->pos]!='"'){ p_err(p); jval_free(o); return NULL; }
            char *key=p_string(p);
            if(!key){ jval_free(o); return NULL; }
            p_ws(p);
            if(p->pos>=p->len||p->s[p->pos]!=':'){ p_err(p); free(key); jval_free(o); return NULL; }
            p->pos++;
            jval *val=p_value(p);
            if(!val){ free(key); jval_free(o); return NULL; }
            jval_obj_put(o,key,val); free(key);
            p_ws(p);
            if(p->pos>=p->len){ p_err(p); jval_free(o); return NULL; }
            if(p->s[p->pos]==','){ p->pos++; continue; }
            if(p->s[p->pos]=='}'){ p->pos++; return o; }
            p_err(p); jval_free(o); return NULL;
        }
    }
    if(c=='['){
        p->pos++;
        jval *a=jv_arr();
        p_ws(p);
        if(p->pos<p->len&&p->s[p->pos]==']'){ p->pos++; return a; }
        while(1){
            jval *item=p_value(p);
            if(!item){ jval_free(a); return NULL; }
            jval_arr_push(a,item);
            p_ws(p);
            if(p->pos>=p->len){ p_err(p); jval_free(a); return NULL; }
            if(p->s[p->pos]==','){ p->pos++; continue; }
            if(p->s[p->pos]==']'){ p->pos++; return a; }
            p_err(p); jval_free(a); return NULL;
        }
    }
    if(c=='t'){
        if(p->pos+4<=p->len&&memcmp(p->s+p->pos,"true",4)==0){ p->pos+=4; return jv_bool(1); }
        p_err(p); return NULL;
    }
    if(c=='f'){
        if(p->pos+5<=p->len&&memcmp(p->s+p->pos,"false",5)==0){ p->pos+=5; return jv_bool(0); }
        p_err(p); return NULL;
    }
    if(c=='n'){
        if(p->pos+4<=p->len&&memcmp(p->s+p->pos,"null",4)==0){ p->pos+=4; return jv_null(); }
        p_err(p); return NULL;
    }
    if(c=='-'||(c>='0'&&c<='9')) return p_number(p);
    p_err(p); return NULL;
}
static jval *parse_json(const char *s, size_t len){
    parser_t p={s,0,len,0};
    jval *v=p_value(&p);
    if(p.err||!v){ jval_free(v); return NULL; }
    p_ws(&p);
    if(p.pos!=p.len){ jval_free(v); return NULL; }
    return v;
}

/* ==================== JSON Serializer ==================== */
static void ser_string(sb_t *out, const char *s){
    sb_putc(out,'"');
    for(const char *p=s;*p;p++){
        unsigned char c=(unsigned char)*p;
        if(c=='"') sb_puts(out,"\\\"");
        else if(c=='\\') sb_puts(out,"\\\\");
        else if(c=='\n') sb_puts(out,"\\n");
        else if(c=='\r') sb_puts(out,"\\r");
        else if(c=='\t') sb_puts(out,"\\t");
        else if(c=='\b') sb_puts(out,"\\b");
        else if(c=='\f') sb_puts(out,"\\f");
        else if(c<0x20){ sb_printf(out,"\\u%04x",c); }
        else sb_putc(out,(char)c);
    }
    sb_putc(out,'"');
}
static void ser_value(sb_t *out, jval *v){
    if(!v){ sb_puts(out,"null"); return; }
    switch(v->t){
        case JV_NULL: sb_puts(out,"null"); break;
        case JV_TRUE: sb_puts(out,"true"); break;
        case JV_FALSE: sb_puts(out,"false"); break;
        case JV_INT: sb_printf(out,"%lld",v->i); break;
        case JV_DBL: {
            if(v->d==(double)(long long)v->d && fabs(v->d)<1e15){
                sb_printf(out,"%lld",(long long)v->d);
            } else {
                char buf[64]; snprintf(buf,sizeof(buf),"%.17g",v->d); sb_puts(out,buf);
            }
            break;
        }
        case JV_STR: ser_string(out,v->s); break;
        case JV_ARR:
            sb_putc(out,'[');
            for(size_t i=0;i<v->a.n;i++){ if(i) sb_putc(out,','); ser_value(out,v->a.v[i]); }
            sb_putc(out,']');
            break;
        case JV_OBJ:
            sb_putc(out,'{');
            for(size_t i=0;i<v->o.n;i++){ if(i) sb_putc(out,','); ser_string(out,v->o.k[i]); sb_putc(out,':'); ser_value(out,v->o.v[i]); }
            sb_putc(out,'}');
            break;
    }
}

/* ==================== Key-Value Store ==================== */
typedef struct { char *key; char *val; } kv_entry;
static kv_entry *kv_store=NULL;
static size_t kv_count=0, kv_cap=0;
static bool kv_find(const char *key, char **out_val){
    for(size_t i=0;i<kv_count;i++){
        if(strcmp(kv_store[i].key,key)==0){ *out_val=kv_store[i].val; return true; }
    }
    return false;
}
static bool kv_exists(const char *key){
    for(size_t i=0;i<kv_count;i++){
        if(strcmp(kv_store[i].key,key)==0) return true;
    }
    return false;
}
static void kv_set(const char *key, const char *val){
    for(size_t i=0;i<kv_count;i++){
        if(strcmp(kv_store[i].key,key)==0){
            free(kv_store[i].val); kv_store[i].val=strdup(val); return;
        }
    }
    if(kv_count==kv_cap){ kv_cap=kv_cap?kv_cap*2:16; kv_store=realloc(kv_store,kv_cap*sizeof(kv_entry)); }
    kv_store[kv_count].key=strdup(key);
    kv_store[kv_count].val=strdup(val);
    kv_count++;
}

