import java.io.*;
import java.nio.file.*;
import java.nio.charset.*;
import java.util.*;
import java.util.zip.CRC32;

public class Main {
    static byte[] lineEndBytes;
    static int leLen;

    public static void main(String[] args) throws Exception {
        Path dir = Paths.get(args[0]);
        List<Path> files = new ArrayList<>();
        try (DirectoryStream<Path> ds = Files.newDirectoryStream(dir)) {
            for (Path p : ds) {
                if (p.getFileName().toString().endsWith(".eml"))
                    files.add(p);
            }
        }
        files.sort((a, b) -> {
            byte[] an = a.getFileName().toString().getBytes(StandardCharsets.UTF_8);
            byte[] bn = b.getFileName().toString().getBytes(StandardCharsets.UTF_8);
            int len = Math.min(an.length, bn.length);
            for (int i = 0; i < len; i++) {
                int c = (an[i] & 0xFF) - (bn[i] & 0xFF);
                if (c != 0) return c;
            }
            return an.length - bn.length;
        });
        boolean first = true;
        for (Path f : files) {
            if (!first) System.out.println();
            first = false;
            processFile(f);
        }
    }

    static void processFile(Path f) throws Exception {
        byte[] data = Files.readAllBytes(f);
        detectLineEnding(data);
        Entity msg = parseEntity(data, 0, data.length, true);
        System.out.println("== " + f.getFileName());
        String from = msg.headers.get("from");
        String subject = msg.headers.get("subject");
        System.out.println("From: " + (from != null ? quotedString(decodeRfc2047(from)) : "-"));
        System.out.println("Subject: " + (subject != null ? quotedString(decodeRfc2047(subject)) : "-"));
        printEntity(msg, 0);
    }

    static void detectLineEnding(byte[] data) {
        for (int i = 0; i < data.length; i++) {
            if (data[i] == '\r' && i + 1 < data.length && data[i + 1] == '\n') {
                lineEndBytes = new byte[]{'\r', '\n'};
                leLen = 2;
                return;
            }
            if (data[i] == '\n') {
                lineEndBytes = new byte[]{'\n'};
                leLen = 1;
                return;
            }
        }
        lineEndBytes = new byte[]{'\n'};
        leLen = 1;
    }

    static int findLineEnd(byte[] data, int pos, int end) {
        if (leLen == 2) {
            for (int i = pos; i + 1 < end; i++) {
                if (data[i] == '\r' && data[i + 1] == '\n') return i;
            }
        } else {
            for (int i = pos; i < end; i++) {
                if (data[i] == '\n') return i;
            }
        }
        return end;
    }

    static class Entity {
        Map<String, String> headers = new LinkedHashMap<>();
        byte[] rawBody;
        boolean isMultipart;
        String ctType = "text", ctSubtype = "plain";
        Map<String, String> ctParams = new LinkedHashMap<>();
        String cdType;
        Map<String, String> cdParams = new LinkedHashMap<>();
        String cte = "7bit";
        List<Entity> parts;
        String boundary;
    }

    static Entity parseEntity(byte[] data, int start, int end, boolean topLevel) {
        Entity e = new Entity();
        int pos = start;
        List<String> rawHeaderLines = new ArrayList<>();
        boolean inHeaders = true;
        int bodyStart = start;
        while (pos < end) {
            int le = findLineEnd(data, pos, end);
            if (le == pos) {
                bodyStart = le + leLen;
                inHeaders = false;
                break;
            }
            rawHeaderLines.add(new String(data, pos, le - pos, StandardCharsets.ISO_8859_1));
            pos = le + leLen;
        }
        if (inHeaders) bodyStart = end;
        List<String> unfolded = new ArrayList<>();
        for (String line : rawHeaderLines) {
            if (!line.isEmpty() && (line.charAt(0) == ' ' || line.charAt(0) == '\t')) {
                if (!unfolded.isEmpty())
                    unfolded.set(unfolded.size() - 1, unfolded.get(unfolded.size() - 1) + line);
            } else {
                unfolded.add(line);
            }
        }
        for (String line : unfolded) {
            int colon = line.indexOf(':');
            if (colon < 0) continue;
            String name = line.substring(0, colon).trim().toLowerCase();
            String val = line.substring(colon + 1);
            int vs = 0;
            while (vs < val.length() && (val.charAt(vs) == ' ' || val.charAt(vs) == '\t')) vs++;
            int ve = val.length();
            while (ve > vs && (val.charAt(ve - 1) == ' ' || val.charAt(ve - 1) == '\t')) ve--;
            e.headers.put(name, val.substring(vs, ve));
        }
        String ct = e.headers.get("content-type");
        if (ct != null) {
            parseContentType(ct, e);
        }
        String cd = e.headers.get("content-disposition");
        if (cd != null) {
            parseContentDisposition(cd, e);
        }
        String cteHdr = e.headers.get("content-transfer-encoding");
        if (cteHdr != null) e.cte = cteHdr.trim().toLowerCase();

        if (e.ctType.equals("multipart")) {
            e.isMultipart = true;
            e.boundary = e.ctParams.get("boundary");
            if (e.boundary == null) e.boundary = "";
            byte[] body = Arrays.copyOfRange(data, bodyStart, end);
            e.parts = parseMultipart(body, e.boundary);
        } else {
            e.rawBody = Arrays.copyOfRange(data, bodyStart, end);
        }
        return e;
    }

    static void parseContentType(String value, Entity e) {
        int[] idx = {0};
        skipWS(value, idx);
        String type = readToken(value, idx);
        skipWS(value, idx);
        if (idx[0] < value.length() && value.charAt(idx[0]) == '/') {
            idx[0]++;
            skipWS(value, idx);
        }
        String subtype = readToken(value, idx);
        e.ctType = type.toLowerCase();
        e.ctSubtype = subtype.toLowerCase();
        parseParams(value, idx, e.ctParams);
    }

    static void parseContentDisposition(String value, Entity e) {
        int[] idx = {0};
        skipWS(value, idx);
        String disp = readToken(value, idx);
        e.cdType = disp.toLowerCase();
        parseParams(value, idx, e.cdParams);
    }

    static void skipWS(String s, int[] idx) {
        while (idx[0] < s.length() && (s.charAt(idx[0]) == ' ' || s.charAt(idx[0]) == '\t')) idx[0]++;
    }

    static String readToken(String s, int[] idx) {
        int start = idx[0];
        while (idx[0] < s.length() && s.charAt(idx[0]) != ';' && s.charAt(idx[0]) != '/' &&
               s.charAt(idx[0]) != ' ' && s.charAt(idx[0]) != '\t' && s.charAt(idx[0]) != '=')
            idx[0]++;
        return s.substring(start, idx[0]);
    }

    static void parseParams(String s, int[] idx, Map<String, String> params) {
        while (idx[0] < s.length()) {
            skipWS(s, idx);
            if (idx[0] >= s.length()) break;
            if (s.charAt(idx[0]) != ';') break;
            idx[0]++;
            skipWS(s, idx);
            String attr = readParamName(s, idx);
            skipWS(s, idx);
            if (idx[0] < s.length() && s.charAt(idx[0]) == '=') {
                idx[0]++;
                skipWS(s, idx);
                String val = readParamValue(s, idx);
                params.put(attr.toLowerCase(), val);
            }
        }
    }

    static String readParamName(String s, int[] idx) {
        int start = idx[0];
        while (idx[0] < s.length() && s.charAt(idx[0]) != '=' && s.charAt(idx[0]) != ';' &&
               s.charAt(idx[0]) != ' ' && s.charAt(idx[0]) != '\t')
            idx[0]++;
        return s.substring(start, idx[0]);
    }

    static String readParamValue(String s, int[] idx) {
        if (idx[0] < s.length() && s.charAt(idx[0]) == '"') {
            idx[0]++;
            StringBuilder sb = new StringBuilder();
            while (idx[0] < s.length() && s.charAt(idx[0]) != '"') {
                if (s.charAt(idx[0]) == '\\' && idx[0] + 1 < s.length()) {
                    idx[0]++;
                    sb.append(s.charAt(idx[0]));
                } else {
                    sb.append(s.charAt(idx[0]));
                }
                idx[0]++;
            }
            if (idx[0] < s.length()) idx[0]++;
            return sb.toString();
        } else {
            int start = idx[0];
            while (idx[0] < s.length() && s.charAt(idx[0]) != ';' && s.charAt(idx[0]) != ' ' && s.charAt(idx[0]) != '\t')
                idx[0]++;
            return s.substring(start, idx[0]);
        }
    }

    static List<Entity> parseMultipart(byte[] body, String boundary) {
        List<Entity> parts = new ArrayList<>();
        byte[] bBytes = boundary.getBytes(StandardCharsets.ISO_8859_1);
        List<int[]> delims = new ArrayList<>();
        int pos = 0;
        while (pos <= body.length) {
            int le = findLineEnd(body, pos, body.length);
            if (isDelimLine(body, pos, le, bBytes, false) || isDelimLine(body, pos, le, bBytes, true)) {
                boolean isClose = isDelimLine(body, pos, le, bBytes, true);
                delims.add(new int[]{pos, le, isClose ? 1 : 0});
                if (isClose) break;
            }
            if (le >= body.length) break;
            pos = le + leLen;
        }
        for (int i = 0; i + 1 < delims.size(); i++) {
            int partStart = delims[i][1] + leLen;
            int partEnd = delims[i + 1][0] - leLen;
            if (partEnd < partStart) partEnd = partStart;
            parts.add(parseEntity(body, partStart, partEnd, false));
        }
        return parts;
    }

    static boolean isDelimLine(byte[] data, int ls, int le, byte[] boundary, boolean close) {
        int prefixLen = 2 + boundary.length;
        if (close) prefixLen += 2;
        if (le - ls < prefixLen) return false;
        if (data[ls] != '-' || data[ls + 1] != '-') return false;
        for (int i = 0; i < boundary.length; i++) {
            if (data[ls + 2 + i] != boundary[i]) return false;
        }
        if (close) {
            if (data[ls + 2 + boundary.length] != '-' || data[ls + 3 + boundary.length] != '-') return false;
        }
        for (int i = ls + prefixLen; i < le; i++) {
            if (data[i] != ' ' && data[i] != '\t') return false;
        }
        return true;
    }

    static byte[] transferDecode(byte[] data, String cte) {
        switch (cte) {
            case "base64": return decodeBase64(data);
            case "quoted-printable": return decodeQP(data);
            default: return data;
        }
    }

    static byte[] decodeBase64(byte[] data) {
        List<Byte> out = new ArrayList<>();
        int[] buf = new int[4];
        int bi = 0;
        for (byte b : data) {
            int c = b & 0xFF;
            int val = -1;
            if (c >= 'A' && c <= 'Z') val = c - 'A';
            else if (c >= 'a' && c <= 'z') val = c - 'a' + 26;
            else if (c >= '0' && c <= '9') val = c - '0' + 52;
            else if (c == '+') val = 62;
            else if (c == '/') val = 63;
            else if (c == '=') break;
            else continue;
            buf[bi++] = val;
            if (bi == 4) {
                out.add((byte)((buf[0] << 2) | (buf[1] >> 4)));
                out.add((byte)((buf[1] << 4) | (buf[2] >> 2)));
                out.add((byte)((buf[2] << 6) | buf[3]));
                bi = 0;
            }
        }
        if (bi == 2) {
            out.add((byte)((buf[0] << 2) | (buf[1] >> 4)));
        } else if (bi == 3) {
            out.add((byte)((buf[0] << 2) | (buf[1] >> 4)));
            out.add((byte)((buf[1] << 4) | (buf[2] >> 2)));
        }
        byte[] res = new byte[out.size()];
        for (int i = 0; i < out.size(); i++) res[i] = out.get(i);
        return res;
    }

    static byte[] decodeQP(byte[] data) {
        List<Byte> out = new ArrayList<>();
        int pos = 0;
        while (pos < data.length) {
            int lineEnd = findLineEnd(data, pos, data.length);
            int lineContentEnd = lineEnd;
            while (lineContentEnd > pos && (data[lineContentEnd - 1] == ' ' || data[lineContentEnd - 1] == '\t'))
                lineContentEnd--;
            boolean softBreak = lineContentEnd > pos && data[lineContentEnd - 1] == '=';
            if (softBreak) {
                for (int i = pos; i < lineContentEnd - 1; i++) {
                    if (data[i] == '=' && i + 2 < lineContentEnd) {
                        int h1 = hexVal(data[i + 1]);
                        int h2 = hexVal(data[i + 2]);
                        if (h1 >= 0 && h2 >= 0) {
                            out.add((byte)((h1 << 4) | h2));
                            i += 2;
                            continue;
                        }
                    }
                    out.add(data[i]);
                }
                if (lineEnd < data.length) pos = lineEnd + leLen;
                else pos = data.length;
            } else {
                for (int i = pos; i < lineContentEnd; i++) {
                    if (data[i] == '=' && i + 2 < lineContentEnd) {
                        int h1 = hexVal(data[i + 1]);
                        int h2 = hexVal(data[i + 2]);
                        if (h1 >= 0 && h2 >= 0) {
                            out.add((byte)((h1 << 4) | h2));
                            i += 2;
                            continue;
                        }
                    }
                    out.add(data[i]);
                }
                if (lineEnd < data.length) {
                    for (int j = 0; j < leLen; j++) out.add(lineEndBytes[j]);
                    pos = lineEnd + leLen;
                } else {
                    pos = data.length;
                }
            }
        }
        byte[] res = new byte[out.size()];
        for (int i = 0; i < out.size(); i++) res[i] = out.get(i);
        return res;
    }

    static int hexVal(byte b) {
        if (b >= '0' && b <= '9') return b - '0';
        if (b >= 'a' && b <= 'f') return b - 'a' + 10;
        if (b >= 'A' && b <= 'F') return b - 'A' + 10;
        return -1;
    }

    static String decodeCharset(byte[] bytes, String charset) {
        String cs = charset.toLowerCase();
        if (cs.equals("us-ascii") || cs.equals("ascii")) {
            return new String(bytes, StandardCharsets.US_ASCII);
        } else if (cs.equals("utf-8")) {
            return new String(bytes, StandardCharsets.UTF_8);
        } else if (cs.equals("iso-8859-1") || cs.equals("latin1") || cs.equals("latin-1")) {
            return new String(bytes, StandardCharsets.ISO_8859_1);
        } else if (cs.equals("windows-1252")) {
            return decodeWindows1252(bytes);
        } else {
            return new String(bytes, StandardCharsets.ISO_8859_1);
        }
    }

    static String decodeWindows1252(byte[] bytes) {
        char[] map = new char[32];
        map[0x80 - 0x80] = '\u20AC';
        map[0x81 - 0x80] = '\u0081';
        map[0x82 - 0x80] = '\u201A';
        map[0x83 - 0x80] = '\u0192';
        map[0x84 - 0x80] = '\u201E';
        map[0x85 - 0x80] = '\u2026';
        map[0x86 - 0x80] = '\u2020';
        map[0x87 - 0x80] = '\u2021';
        map[0x88 - 0x80] = '\u02C6';
        map[0x89 - 0x80] = '\u2030';
        map[0x8A - 0x80] = '\u0160';
        map[0x8B - 0x80] = '\u2039';
        map[0x8C - 0x80] = '\u0152';
        map[0x8D - 0x80] = '\u008D';
        map[0x8E - 0x80] = '\u017D';
        map[0x8F - 0x80] = '\u008F';
        map[0x90 - 0x80] = '\u0090';
        map[0x91 - 0x80] = '\u2018';
        map[0x92 - 0x80] = '\u2019';
        map[0x93 - 0x80] = '\u201C';
        map[0x94 - 0x80] = '\u201D';
        map[0x95 - 0x80] = '\u2022';
        map[0x96 - 0x80] = '\u2013';
        map[0x97 - 0x80] = '\u2014';
        map[0x98 - 0x80] = '\u02DC';
        map[0x99 - 0x80] = '\u2122';
        map[0x9A - 0x80] = '\u0161';
        map[0x9B - 0x80] = '\u203A';
        map[0x9C - 0x80] = '\u0153';
        map[0x9D - 0x80] = '\u009D';
        map[0x9E - 0x80] = '\u017E';
        map[0x9F - 0x80] = '\u0178';
        char[] res = new char[bytes.length];
        for (int i = 0; i < bytes.length; i++) {
            int b = bytes[i] & 0xFF;
            if (b >= 0x80 && b <= 0x9F) res[i] = map[b - 0x80];
            else res[i] = (char) b;
        }
        return new String(res);
    }

    static String decodeRfc2047(String value) {
        List<int[]> matches = new ArrayList<>();
        List<String> charsets = new ArrayList<>();
        List<String> encodings = new ArrayList<>();
        List<String> encTexts = new ArrayList<>();
        int pos = 0;
        while (pos < value.length()) {
            int idx = value.indexOf("=?", pos);
            if (idx < 0) break;
            int[] result = tryMatchEncodedWord(value, idx);
            if (result != null) {
                int mStart = result[0];
                int mEnd = result[1];
                int csStart = result[2], csEnd = result[3];
                int encStart = result[4], encEnd = result[5];
                int etStart = result[6], etEnd = result[7];
                matches.add(new int[]{mStart, mEnd});
                charsets.add(value.substring(csStart, csEnd));
                encodings.add(value.substring(encStart, encEnd));
                encTexts.add(value.substring(etStart, etEnd));
                pos = mEnd;
            } else {
                pos = idx + 1;
            }
        }
        if (matches.isEmpty()) return value;
        List<List<Integer>> groups = new ArrayList<>();
        int i = 0;
        while (i < matches.size()) {
            List<Integer> group = new ArrayList<>();
            group.add(i);
            String baseCs = baseCharset(charsets.get(i));
            int j = i + 1;
            while (j < matches.size()) {
                int prevEnd = matches.get(j - 1)[1];
                int curStart = matches.get(j)[0];
                boolean adjacent = true;
                for (int k = prevEnd; k < curStart; k++) {
                    if (value.charAt(k) != ' ' && value.charAt(k) != '\t') {
                        adjacent = false;
                        break;
                    }
                }
                if (adjacent && baseCharset(charsets.get(j)).equalsIgnoreCase(baseCs)) {
                    group.add(j);
                    j++;
                } else break;
            }
            groups.add(group);
            i = j;
        }
        StringBuilder sb = new StringBuilder();
        int curPos = 0;
        for (List<Integer> group : groups) {
            int gStart = matches.get(group.get(0))[0];
            int gEnd = matches.get(group.get(group.size() - 1))[1];
            sb.append(value, curPos, gStart);
            List<Byte> allBytes = new ArrayList<>();
            for (int idx2 : group) {
                byte[] decoded = decodeEncodedWord(encodings.get(idx2), encTexts.get(idx2));
                for (byte b : decoded) allBytes.add(b);
            }
            byte[] bytes = new byte[allBytes.size()];
            for (int k = 0; k < allBytes.size(); k++) bytes[k] = allBytes.get(k);
            String cs = charsets.get(group.get(0));
            cs = baseCharset(cs);
            sb.append(decodeCharset(bytes, cs));
            curPos = gEnd;
        }
        sb.append(value, curPos, value.length());
        return sb.toString();
    }

    static String baseCharset(String cs) {
        int star = cs.indexOf('*');
        if (star >= 0) return cs.substring(0, star);
        return cs;
    }

    static int[] tryMatchEncodedWord(String s, int start) {
        if (start + 2 > s.length() || s.charAt(start) != '=' || s.charAt(start + 1) != '?') return null;
        int pos = start + 2;
        int csStart = pos;
        while (pos < s.length() && s.charAt(pos) != '?' && s.charAt(pos) != ' ' && s.charAt(pos) != '\t') pos++;
        if (pos >= s.length() || s.charAt(pos) != '?') return null;
        if (pos == csStart) return null;
        int csEnd = pos;
        pos++;
        int encStart = pos;
        while (pos < s.length() && s.charAt(pos) != '?' && s.charAt(pos) != ' ' && s.charAt(pos) != '\t') pos++;
        if (pos >= s.length() || s.charAt(pos) != '?') return null;
        int encEnd = pos;
        String enc = s.substring(encStart, encEnd);
        if (!enc.equals("B") && !enc.equals("b") && !enc.equals("Q") && !enc.equals("q")) return null;
        pos++;
        int etStart = pos;
        while (pos < s.length() && s.charAt(pos) != '?' && s.charAt(pos) != ' ' && s.charAt(pos) != '\t') pos++;
        if (pos >= s.length() || s.charAt(pos) != '?') return null;
        int etEnd = pos;
        pos++;
        if (pos >= s.length() || s.charAt(pos) != '=') return null;
        pos++;
        return new int[]{start, pos, csStart, csEnd, encStart, encEnd, etStart, etEnd};
    }

    static byte[] decodeEncodedWord(String encoding, String text) {
        if (encoding.equals("B") || encoding.equals("b")) {
            return decodeBase64(text.getBytes(StandardCharsets.ISO_8859_1));
        } else {
            List<Byte> out = new ArrayList<>();
            for (int i = 0; i < text.length(); i++) {
                char c = text.charAt(i);
                if (c == '_') {
                    out.add((byte) 0x20);
                } else if (c == '=' && i + 2 < text.length()) {
                    int h1 = hexVal((byte) text.charAt(i + 1));
                    int h2 = hexVal((byte) text.charAt(i + 2));
                    if (h1 >= 0 && h2 >= 0) {
                        out.add((byte)((h1 << 4) | h2));
                        i += 2;
                    } else {
                        out.add((byte) c);
                    }
                } else {
                    out.add((byte) c);
                }
            }
            byte[] res = new byte[out.size()];
            for (int i = 0; i < out.size(); i++) res[i] = out.get(i);
            return res;
        }
    }

    static String getFileName(Entity e) {
        String name = getRfc2231Param(e.cdParams, "filename");
        if (name != null) return name;
        if (e.cdParams.containsKey("filename")) {
            return decodeRfc2047(e.cdParams.get("filename"));
        }
        name = getRfc2231Param(e.ctParams, "name");
        if (name != null) return name;
        if (e.ctParams.containsKey("name")) {
            return decodeRfc2047(e.ctParams.get("name"));
        }
        return null;
    }

    static String getRfc2231Param(Map<String, String> params, String attr) {
        String lower = attr.toLowerCase();
        String single = params.get(lower + "*");
        if (single != null) {
            return decodeRfc2231Single(single);
        }
        List<Integer> indices = new ArrayList<>();
        for (String key : params.keySet()) {
            if (key.startsWith(lower + "*")) {
                String suffix = key.substring(lower.length() + 1);
                try {
                    indices.add(Integer.parseInt(suffix));
                } catch (NumberFormatException e) {}
            }
        }
        if (indices.isEmpty()) return null;
        Collections.sort(indices);
        List<Byte> allBytes = new ArrayList<>();
        String charset = null;
        for (int idx : indices) {
            String key1 = lower + "*" + idx;
            String key2 = lower + "*" + idx + "*";
            String val;
            boolean percentEncoded;
            if (params.containsKey(key2)) {
                val = params.get(key2);
                percentEncoded = true;
            } else if (params.containsKey(key1)) {
                val = params.get(key1);
                percentEncoded = false;
            } else {
                continue;
            }
            if (percentEncoded) {
                if (idx == indices.get(0) && charset == null) {
                    int q1 = val.indexOf('\'');
                    if (q1 >= 0) {
                        int q2 = val.indexOf('\'', q1 + 1);
                        if (q2 >= 0) {
                            charset = val.substring(0, q1);
                            val = val.substring(q2 + 1);
                        }
                    }
                }
                byte[] decoded = percentDecode(val);
                for (byte b : decoded) allBytes.add(b);
            } else {
                for (int i = 0; i < val.length(); i++) allBytes.add((byte) val.charAt(i));
            }
        }
        byte[] bytes = new byte[allBytes.size()];
        for (int i = 0; i < allBytes.size(); i++) bytes[i] = allBytes.get(i);
        if (charset == null || charset.isEmpty()) charset = "us-ascii";
        return decodeCharset(bytes, charset);
    }

    static String decodeRfc2231Single(String val) {
        int q1 = val.indexOf('\'');
        if (q1 < 0) return val;
        int q2 = val.indexOf('\'', q1 + 1);
        if (q2 < 0) return val;
        String charset = val.substring(0, q1);
        String encoded = val.substring(q2 + 1);
        byte[] bytes = percentDecode(encoded);
        if (charset.isEmpty()) charset = "us-ascii";
        return decodeCharset(bytes, charset);
    }

    static byte[] percentDecode(String s) {
        List<Byte> out = new ArrayList<>();
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '%' && i + 2 < s.length()) {
                int h1 = hexVal((byte) s.charAt(i + 1));
                int h2 = hexVal((byte) s.charAt(i + 2));
                if (h1 >= 0 && h2 >= 0) {
                    out.add((byte)((h1 << 4) | h2));
                    i += 2;
                } else {
                    out.add((byte) s.charAt(i));
                }
            } else {
                out.add((byte) s.charAt(i));
            }
        }
        byte[] res = new byte[out.size()];
        for (int i = 0; i < out.size(); i++) res[i] = out.get(i);
        return res;
    }

    static void printEntity(Entity e, int indent) {
        String pad = "  ".repeat(indent);
        if (e.isMultipart) {
            System.out.println(pad + "multipart/" + e.ctSubtype + " parts=" + e.parts.size());
            for (Entity p : e.parts) printEntity(p, indent + 1);
        } else if (e.ctType.equals("text") && !"attachment".equals(e.cdType)) {
            String charset = e.ctParams.getOrDefault("charset", "us-ascii").toLowerCase();
            byte[] decoded = transferDecode(e.rawBody, e.cte);
            String text = decodeCharset(decoded, charset);
            text = text.replace("\r\n", "\n").replace("\r", "\n");
            int chars = text.codePointCount(0, text.length());
            System.out.println(pad + "text/" + e.ctSubtype + " charset=" + charset + " cte=" + e.cte + " chars=" + chars);
            System.out.println(pad + "  " + quotedString(text));
        } else {
            byte[] decoded = transferDecode(e.rawBody, e.cte);
            CRC32 crc = new CRC32();
            crc.update(decoded);
            long crcVal = crc.getValue() & 0xFFFFFFFFL;
            String disp = e.cdType != null ? e.cdType : "-";
            String name = getFileName(e);
            String nameStr = name != null ? quotedString(name) : "-";
            System.out.println(pad + e.ctType + "/" + e.ctSubtype + " cte=" + e.cte + " disposition=" + disp + " name=" + nameStr + " size=" + decoded.length + " crc32=" + String.format("%08x", crcVal));
        }
    }

    static String quotedString(String s) {
        StringBuilder sb = new StringBuilder();
        sb.append('"');
        int i = 0;
        while (i < s.length()) {
            int cp = s.codePointAt(i);
            if (cp == '\\') sb.append("\\\\");
            else if (cp == '"') sb.append("\\\"");
            else if (cp == '\n') sb.append("\\n");
            else if (cp == '\t') sb.append("\\t");
            else if (cp < 0x20 || (cp >= 0x7F && cp <= 0x9F)) {
                sb.append(String.format("\\u%04x", cp));
            } else {
                sb.appendCodePoint(cp);
            }
            i += Character.charCount(cp);
        }
        sb.append('"');
        return sb.toString();
    }
}

