// CRC-32 table (zlib/PNG style)
const crcTable: number[] = [];
for (let i = 0; i < 256; i++) {
  let c = i;
  for (let j = 0; j < 8; j++) {
    c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
  }
  crcTable[i] = c;
}

function crc32(buf: Buffer): number {
  let crc = 0xFFFFFFFF;
  for (let i = 0; i < buf.length; i++) {
    crc = crcTable[(crc ^ buf[i]) & 0xFF] ^ (crc >>> 8);
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

// Base64 decode (strict, for RFC 2047)
function base64DecodeStrict(s: string): Buffer {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const lookup: number[] = new Array(256).fill(-1);
  for (let i = 0; i < alphabet.length; i++) lookup[alphabet.charCodeAt(i)] = i;
  const bytes: number[] = [];
  let bits = 0, count = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c === 61) break; // '='
    const v = lookup[c];
    if (v < 0) continue;
    bits = (bits << 6) | v;
    count++;
    if (count === 4) {
      bytes.push((bits >> 16) & 0xFF, (bits >> 8) & 0xFF, bits & 0xFF);
      bits = 0; count = 0;
    }
  }
  if (count > 1) {
    bits <<= (4 - count) * 6;
    if (count >= 2) bytes.push((bits >> 16) & 0xFF);
    if (count >= 3) bytes.push((bits >> 8) & 0xFF);
  }
  return Buffer.from(bytes);
}

// Base64 decode (lenient, for CTE)
function base64DecodeLenient(buf: Buffer): Buffer {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const lookup: number[] = new Array(256).fill(-1);
  for (let i = 0; i < alphabet.length; i++) lookup[alphabet.charCodeAt(i)] = i;
  const bytes: number[] = [];
  let bits = 0, count = 0;
  for (let i = 0; i < buf.length; i++) {
    const c = buf[i];
    if (c === 61) break; // '='
    const v = lookup[c];
    if (v < 0) continue;
    bits = (bits << 6) | v;
    count++;
    if (count === 4) {
      bytes.push((bits >> 16) & 0xFF, (bits >> 8) & 0xFF, bits & 0xFF);
      bits = 0; count = 0;
    }
  }
  if (count > 1) {
    bits <<= (4 - count) * 6;
    if (count >= 2) bytes.push((bits >> 16) & 0xFF);
    if (count >= 3) bytes.push((bits >> 8) & 0xFF);
  }
  return Buffer.from(bytes);
}

// Quoted-printable decode
function qpDecode(buf: Buffer, lineEnding: Buffer): Buffer {
  const leStr = lineEnding.toString('latin1');
  const leLen = lineEnding.length;

  // Split into lines
  const lines: number[][] = [];
  let start = 0;
  for (let i = 0; i <= buf.length - leLen; i++) {
    if (buf.subarray(i, i + leLen).equals(lineEnding)) {
      lines.push(Array.from(buf.subarray(start, i)));
      start = i + leLen;
      i += leLen - 1;
    }
  }
  if (start < buf.length) {
    lines.push(Array.from(buf.subarray(start)));
  } else if (start === buf.length && lines.length === 0) {
    lines.push([]);
  }

  // Remove trailing spaces/tabs from each line
  for (let i = 0; i < lines.length; i++) {
    while (lines[i].length > 0 && (lines[i][lines[i].length - 1] === 32 || lines[i][lines[i].length - 1] === 9)) {
      lines[i].pop();
    }
  }

  // Join soft line breaks (lines ending with '=')
  const joined: number[][] = [];
  let i = 0;
  while (i < lines.length) {
    let current = lines[i];
    while (current.length > 0 && current[current.length - 1] === 61 && i + 1 < lines.length) {
      current = current.slice(0, -1).concat(lines[i + 1]);
      i++;
    }
    joined.push(current);
    i++;
  }

  // Decode =XY sequences
  const result: number[] = [];
  for (const line of joined) {
    let j = 0;
    while (j < line.length) {
      if (line[j] === 61 && j + 2 < line.length) {
        const h1 = line[j + 1], h2 = line[j + 2];
        const v1 = hexVal(h1), v2 = hexVal(h2);
        if (v1 >= 0 && v2 >= 0) {
          result.push((v1 << 4) | v2);
          j += 3;
        } else {
          result.push(61);
          j++;
        }
      } else {
        result.push(line[j]);
        j++;
      }
    }
    // Add line break between lines (not after last)
    if (joined.length > 1) {
      // We'll add line endings between joined lines
    }
  }

  // Actually, let me redo this - add line breaks between joined lines
  const finalResult: number[] = [];
  for (let li = 0; li < joined.length; li++) {
    const line = joined[li];
    let j = 0;
    while (j < line.length) {
      if (line[j] === 61 && j + 2 < line.length) {
        const h1 = line[j + 1], h2 = line[j + 2];
        const v1 = hexVal(h1), v2 = hexVal(h2);
        if (v1 >= 0 && v2 >= 0) {
          finalResult.push((v1 << 4) | v2);
          j += 3;
        } else {
          finalResult.push(61);
          j++;
        }
      } else {
        finalResult.push(line[j]);
        j++;
      }
    }
    if (li < joined.length - 1) {
      for (let k = 0; k < leLen; k++) finalResult.push(lineEnding[k]);
    }
