        out.append(sec.path).append(": ").append(sec.kind).append("\n");

        Path filePath = Paths.get(dir, "tree", sec.path);
        List<byte[]> content;

        if (sec.kind.equals("create")) {
            if (Files.exists(filePath)) {
                out.append("  error: already exists\n");
                return;
            }
            content = new ArrayList<>();
        } else {
            if (!Files.exists(filePath)) {
                out.append("  error: not found\n");
                return;
            }
            try {
                byte[] fileBytes = Files.readAllBytes(filePath);
                content = splitFileLines(fileBytes);
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        int delta = 0;
        boolean allApplied = true;

        for (int h = 0; h < sec.hunks.size(); h++) {
            Hunk hunk = sec.hunks.get(h);
            int hunkNum = h + 1;

            if (hunk.malformed) {
                out.append("  hunk ").append(hunkNum).append(": malformed\n");
                allApplied = false;
                continue;
            }

            int P = hunk.a + delta;

            if (hunk.b == 0) {
                if (P >= 0 && P <= content.size()) {
                    content.addAll(P, new ArrayList<>(hunk.newLines));
                    out.append("  hunk ").append(hunkNum).append(": applied at ").append(P).append(" (offset 0)\n");
                    delta += hunk.d - hunk.b;
                    hunk.applied = true;
                } else {
                    out.append("  hunk ").append(hunkNum).append(": rejected\n");
                    allApplied = false;
                }
            } else {
                int lineCount = content.size();
                int found = -1;

                if (hunk.b <= lineCount) {
                    int maxP = lineCount - hunk.b + 1;
                    for (int dist = 0; ; dist++) {
                        int p1 = P - dist;
                        if (p1 >= 1 && p1 <= maxP) {
                            if (matchAt(content, p1 - 1, hunk.oldLines)) {
                                found = p1;
                                break;
                            }
                        }
                        if (dist > 0) {
                            int p2 = P + dist;
                            if (p2 >= 1 && p2 <= maxP) {
                                if (matchAt(content, p2 - 1, hunk.oldLines)) {
                                    found = p2;
                                    break;
                                }
                            }
                        }
                        if (P - dist < 1 && P + dist > maxP) break;
                    }
                }

                if (found >= 0) {
                    int startIdx = found - 1;
                    for (int j = 0; j < hunk.b; j++) {
                        content.remove(startIdx);
                    }
                    content.addAll(startIdx, new ArrayList<>(hunk.newLines));
                    int offset = found - P;
                    String offStr = offset > 0 ? "+" + offset : "" + offset;
                    out.append("  hunk ").append(hunkNum).append(": applied at ").append(found)
                            .append(" (offset ").append(offStr).append(")\n");
                    delta += hunk.d - hunk.b;
                    hunk.applied = true;
                } else {
                    out.append("  hunk ").append(hunkNum).append(": rejected\n");
                    allApplied = false;
                }
            }
        }

        if (sec.kind.equals("delete") && allApplied && content.isEmpty()) {
            out.append("  result: deleted\n");
        } else {
            byte[] finalBytes = concatLines(content);
            CRC32 crc = new CRC32();
            crc.update(finalBytes);
            long crcVal = crc.getValue();
            out.append("  result: ").append(content.size()).append(" lines, crc32 ")
                    .append(String.format("%08x", crcVal)).append("\n");
        }
    }

    static boolean matchAt(List<byte[]> content, int startIdx, List<byte[]> oldLines) {
        for (int i = 0; i < oldLines.size(); i++) {
            if (!Arrays.equals(content.get(startIdx + i), oldLines.get(i))) {
                return false;
            }
        }
        return true;
    }

    static byte[] concatLines(List<byte[]> lines) {
        int totalLen = 0;
        for (byte[] l : lines) totalLen += l.length;
        byte[] result = new byte[totalLen];
        int pos = 0;
        for (byte[] l : lines) {
            System.arraycopy(l, 0, result, pos, l.length);
            pos += l.length;
        }
        return result;
    }
}

import * as fs from 'fs';
import * as path from 'path';

function crc32(data: Buffer): number {
  let crc = 0xFFFFFFFF;
  for (let i = 0; i < data.length; i++) {
    crc ^= data[i];
    for (let j = 0; j < 8; j++) {
      if (crc & 1) {
        crc = (crc >>> 1) ^ 0xEDB88320;
      } else {
        crc = crc >>> 1;
      }
    }
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

interface FileLine {
  bytes: Buffer;
  hasNewline: boolean;
}

function splitLines(content: Buffer): FileLine[] {
  if (content.length === 0) return [];
  const lines: FileLine[] = [];
  let start = 0;
  for (let i = 0; i < content.length; i++) {
    if (content[i] === 0x0A) {
      lines.push({ bytes: content.subarray(start, i + 1), hasNewline: true });
      start = i + 1;
    }
  }
  if (start < content.length) {
    lines.push({ bytes: content.subarray(start), hasNewline: false });
  }
  return lines;
}

function linesToBuffer(lines: FileLine[]): Buffer {
  return Buffer.concat(lines.map(l => l.bytes));
}

function linesEqual(a: FileLine, b: FileLine): boolean {
  return a.hasNewline === b.hasNewline && a.bytes.equals(b.bytes);
}

interface HunkLine {
  type: ' ' | '-' | '+';
  bytes: Buffer;
  hasNewline: boolean;
}

interface Hunk {
  a: number;
  b: number;
  c: number;
  d: number;
  oldLines: FileLine[];
  newLines: FileLine[];
  malformed: boolean;
}

interface Section {
  path: string;
  kind: 'create' | 'delete' | 'modify';
  hunks: Hunk[];
}

function parseDiff(diffContent: Buffer): Section[] {
  const diffLines: string[] = [];
  let start = 0;
  for (let i = 0; i < diffContent.length; i++) {
    if (diffContent[i] === 0x0A) {
      diffLines.push(diffContent.subarray(start, i).toString('latin1'));
      start = i + 1;
    }
  }
  if (start < diffContent.length) {
    diffLines.push(diffContent.subarray(start).toString('latin1'));
  }
  if (diffLines.length > 0 && diffLines[diffLines.length - 1] === '') {
    diffLines.pop();
  }

  const sections: Section[] = [];
  let i = 0;

  while (i < diffLines.length) {
    const line = diffLines[i];
    if (line.startsWith('diff --git a/')) {
      const rest = line.substring('diff --git '.length);
      const spaceIdx = rest.indexOf(' ');
      const aPart = rest.substring(0, spaceIdx);
      const filePath = aPart.substring(2); // remove "a/"
      i++;

      let kind: 'create' | 'delete' | 'modify' = 'modify';

      while (i < diffLines.length) {
        const ml = diffLines[i];
        if (ml.startsWith('@@ ') || ml.startsWith('diff --git ') || ml.startsWith('--- ') || ml.startsWith('+++ ')) {
          break;
        }
        if (ml.startsWith('new file mode ')) {
          kind = 'create';
        } else if (ml.startsWith('deleted file mode ')) {
          kind = 'delete';
        }
        i++;
      }

      if (i < diffLines.length && diffLines[i].startsWith('--- ')) {
        i++;
        if (i < diffLines.length && diffLines[i].startsWith('+++ ')) {
          i++;
        }
      }

      const hunks: Hunk[] = [];
      while (i < diffLines.length && diffLines[i].startsWith('@@ ')) {
        const headerLine = diffLines[i];
        i++;

        const hunkMatch = headerLine.match(/^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/);
        if (!hunkMatch) {
          while (i < diffLines.length && !diffLines[i].startsWith('@@ ') && !diffLines[i].startsWith('diff --git ')) {
            i++;
          }
          continue;
        }

        const a = parseInt(hunkMatch[1], 10);
        const b = hunkMatch[2] !== undefined ? parseInt(hunkMatch[2], 10) : 1;
        const c = parseInt(hunkMatch[3], 10);
        const d = hunkMatch[4] !== undefined ? parseInt(hunkMatch[4], 10) : 1;

        const bodyLines: HunkLine[] = [];
        while (i < diffLines.length && !diffLines[i].startsWith('@@ ') && !diffLines[i].startsWith('diff --git ')) {
          const bl = diffLines[i];
          if (bl.length === 0) {
            break;
          }
          const marker = bl[0];
          if (marker === ' ' || marker === '-' || marker === '+') {
            bodyLines.push({
              type: marker as ' ' | '-' | '+',
              bytes: Buffer.from(bl.substring(1), 'latin1'),
              hasNewline: true
            });
          } else if (marker === '\\') {
            if (bodyLines.length > 0) {
              bodyLines[bodyLines.length - 1].hasNewline = false;
            }
          }
          i++;
        }

        const oldLines: FileLine[] = [];
        const newLines: FileLine[] = [];
        for (const hl of bodyLines) {
          if (hl.type === ' ' || hl.type === '-') {
            oldLines.push({ bytes: hl.bytes, hasNewline: hl.hasNewline });
          }
          if (hl.type === ' ' || hl.type === '+') {
            newLines.push({ bytes: hl.bytes, hasNewline: hl.hasNewline });
          }
        }

        const malformed = (oldLines.length !== b) || (newLines.length !== d);
        hunks.push({ a, b, c, d, oldLines, newLines, malformed });
      }

      sections.push({ path: filePath, kind, hunks });
    } else {
      i++;
    }
  }

  return sections;
}

interface HunkResult {
  status: 'applied' | 'rejected' | 'malformed';
  position?: number;
  offset?: number;
}

function applyHunks(content: FileLine[], hunks: Hunk[]): { results: HunkResult[]; content: FileLine[] } {
  const results: HunkResult[] = [];
  let currentContent = content.map(l => ({ bytes: Buffer.from(l.bytes), hasNewline: l.hasNewline }));
  let delta = 0;

  for (let hi = 0; hi < hunks.length; hi++) {
    const hunk = hunks[hi];

    if (hunk.malformed) {
      results.push({ status: 'malformed' });
      continue;
    }

    const P = hunk.a + delta;
    const lineCount = currentContent.length;

    if (hunk.b === 0) {
      if (P >= 0 && P <= lineCount) {
        const newLinesCopy = hunk.newLines.map(l => ({ bytes: Buffer.from(l.bytes), hasNewline: l.hasNewline }));
        currentContent.splice(P, 0, ...newLinesCopy);
        results.push({ status: 'applied', position: P, offset: 0 });
        delta += hunk.d - hunk.b;
      } else {
        results.push({ status: 'rejected' });
      }
    } else {
      const maxValid = lineCount - hunk.b + 1;
      let found = false;

      for (let k = 0; ; k++) {
        const candidates: number[] = [];
        if (k === 0) {
          candidates.push(P);
        } else {
          candidates.push(P - k);
          candidates.push(P + k);
        }

        let allInvalid = true;
        for (const p of candidates) {
          if (p >= 1 && p + hunk.b - 1 <= lineCount) {
            allInvalid = false;
            let matches = true;
            for (let j = 0; j < hunk.b; j++) {
              if (!linesEqual(currentContent[p - 1 + j], hunk.oldLines[j])) {
                matches = false;
                break;
              }
            }
            if (matches) {
              const newLinesCopy = hunk.newLines.map(l => ({ bytes: Buffer.from(l.bytes), hasNewline: l.hasNewline }));
              currentContent.splice(p - 1, hunk.b, ...newLinesCopy);
              results.push({ status: 'applied', position: p, offset: p - P });
              delta += hunk.d - hunk.b;
              found = true;
              break;
            }
          }
        }

        if (found) break;

        const leftExhausted = (P - k) < 1;
        const rightExhausted = (P + k) > maxValid;
        if (leftExhausted && rightExhausted) break;
      }

      if (!found) {
        results.push({ status: 'rejected' });
      }
    }
  }

  return { results, content: currentContent };
}

function formatHunkResult(n: number, result: HunkResult): string {
  if (result.status === 'malformed') {
    return `  hunk ${n}: malformed`;
  } else if (result.status === 'rejected') {
    return `  hunk ${n}: rejected`;
  } else {
    const offset = result.offset!;
    const offsetStr = offset > 0 ? `+${offset}` : offset < 0 ? `${offset}` : `0`;
    return `  hunk ${n}: applied at ${result.position} (offset ${offsetStr})`;
  }
}

function formatResult(content: FileLine[], deleted: boolean): string {
  if (deleted) {
    return `  result: deleted`;
  }
  const buf = linesToBuffer(content);
  const crc = crc32(buf);
  const crcHex = crc.toString(16).padStart(8, '0');
  return `  result: ${content.length} lines, crc32 ${crcHex}`;
}

function main() {
  const args = process.argv.slice(2);
  if (args.length < 1) {
    process.exit(1);
  }
  const dir = args[0];
  const diffPath = path.join(dir, 'changes.diff');
  const treeDir = path.join(dir, 'tree');

  const diffContent = fs.readFileSync(diffPath);
  const sections = parseDiff(diffContent);

  sections.sort((a, b) => {
    const bufA = Buffer.from(a.path, 'latin1');
    const bufB = Buffer.from(b.path, 'latin1');
    return bufA.compare(bufB);
  });

  const outputLines: string[] = [];

  for (const section of sections) {
    const filePath = path.join(treeDir, section.path);

    if (section.kind === 'create') {
      if (fs.existsSync(filePath)) {
        outputLines.push(`${section.path}: create`);
        outputLines.push(`  error: already exists`);
        continue;
      }
      const { results, content: finalContent } = applyHunks([], section.hunks);
      outputLines.push(`${section.path}: create`);
      for (let i = 0; i < results.length; i++) {
        outputLines.push(formatHunkResult(i + 1, results[i]));
      }
      outputLines.push(formatResult(finalContent, false));
    } else if (section.kind === 'delete') {
      if (!fs.existsSync(filePath)) {
        outputLines.push(`${section.path}: delete`);
        outputLines.push(`  error: not found`);
        continue;
      }
      const fileContent = fs.readFileSync(filePath);
      const initialLines = splitLines(fileContent);
      const { results, content: finalContent } = applyHunks(initialLines, section.hunks);

      const allApplied = results.every(r => r.status === 'applied');
      const isEmpty = finalContent.length === 0;

      outputLines.push(`${section.path}: delete`);
      for (let i = 0; i < results.length; i++) {
        outputLines.push(formatHunkResult(i + 1, results[i]));
      }
      if (allApplied && isEmpty) {
        outputLines.push(`  result: deleted`);
      } else {
        outputLines.push(formatResult(finalContent, false));
      }
    } else {
      if (!fs.existsSync(filePath)) {
        outputLines.push(`${section.path}: modify`);
        outputLines.push(`  error: not found`);
        continue;
      }
      const fileContent = fs.readFileSync(filePath);
      const initialLines = splitLines(fileContent);
      const { results, content: finalContent } = applyHunks(initialLines, section.hunks);

      outputLines.push(`${section.path}: modify`);
      for (let i = 0; i < results.length; i++) {
        outputLines.push(formatHunkResult(i + 1, results[i]));
      }
      outputLines.push(formatResult(finalContent, false));
    }
  }

  if (outputLines.length > 0) {
    process.stdout.write(outputLines.join('\n') + '\n');
  }
}

main();

