  } else {
    const offset = result.offset!;
    const offsetStr = offset > 0 ? `+${offset}` : offset < 0 ? `${offset}` : `0`;
    return `  hunk ${n}: applied at ${result.position} (offset ${offsetStr})`;
  }
}

function formatResult(content: FileLine[], deleted: boolean): string {
  if (deleted) {
    return `  result: deleted`;
  }
  const buf = linesToBuffer(content);
  const crc = crc32(buf);
  const crcHex = crc.toString(16).padStart(8, '0');
  return `  result: ${content.length} lines, crc32 ${crcHex}`;
}

function main() {
  const args = process.argv.slice(2);
  if (args.length < 1) {
    process.exit(1);
  }
  const dir = args[0];
  const diffPath = path.join(dir, 'changes.diff');
  const treeDir = path.join(dir, 'tree');

  const diffContent = fs.readFileSync(diffPath);
  const sections = parseDiff(diffContent);

  sections.sort((a, b) => {
    const bufA = Buffer.from(a.path, 'latin1');
    const bufB = Buffer.from(b.path, 'latin1');
    return bufA.compare(bufB);
  });

  const outputLines: string[] = [];

  for (const section of sections) {
    const filePath = path.join(treeDir, section.path);

    if (section.kind === 'create') {
      if (fs.existsSync(filePath)) {
        outputLines.push(`${section.path}: create`);
        outputLines.push(`  error: already exists`);
        continue;
      }
      const { results, content: finalContent } = applyHunks([], section.hunks);
      outputLines.push(`${section.path}: create`);
      for (let i = 0; i < results.length; i++) {
        outputLines.push(formatHunkResult(i + 1, results[i]));
      }
      outputLines.push(formatResult(finalContent, false));
    } else if (section.kind === 'delete') {
      if (!fs.existsSync(filePath)) {
        outputLines.push(`${section.path}: delete`);
        outputLines.push(`  error: not found`);
        continue;
      }
      const fileContent = fs.readFileSync(filePath);
      const initialLines = splitLines(fileContent);
      const { results, content: finalContent } = applyHunks(initialLines, section.hunks);

      const allApplied = results.every(r => r.status === 'applied');
      const isEmpty = finalContent.length === 0;

      outputLines.push(`${section.path}: delete`);
      for (let i = 0; i < results.length; i++) {
        outputLines.push(formatHunkResult(i + 1, results[i]));
      }
      if (allApplied && isEmpty) {
        outputLines.push(`  result: deleted`);
      } else {
        outputLines.push(formatResult(finalContent, false));
      }
    } else {
      if (!fs.existsSync(filePath)) {
        outputLines.push(`${section.path}: modify`);
        outputLines.push(`  error: not found`);
        continue;
      }
      const fileContent = fs.readFileSync(filePath);
      const initialLines = splitLines(fileContent);
      const { results, content: finalContent } = applyHunks(initialLines, section.hunks);

      outputLines.push(`${section.path}: modify`);
      for (let i = 0; i < results.length; i++) {
        outputLines.push(formatHunkResult(i + 1, results[i]));
      }
      outputLines.push(formatResult(finalContent, false));
    }
  }

  if (outputLines.length > 0) {
    process.stdout.write(outputLines.join('\n') + '\n');
  }
}

main();

#include <stdio.h>
