/* ============ Value ============ */
enum { V_INT, V_BOOL, V_STRING, V_LIST, V_FUNCTION, V_NIL };

typedef struct List List;
typedef struct Func Func;
typedef struct Scope Scope;
typedef struct ASTNode ASTNode;

typedef struct {
    int type;
    union {
        long long ival;
        int bval;
        struct { char *data; int len; } *str;
        List *list;
        Func *func;
    };
} Value;

struct List {
    Value *elems;
    int len, cap;
};

struct Func {
    char **params;
    int nparams;
    ASTNode **body;
    int nbody;
    Scope *captured;
    int is_builtin;
    int builtin_id;
};

struct Scope {
    Scope *parent;
    char **names;
    Value *values;
    int count, cap;
};

/* ============ Tokens ============ */
enum {
    TK_INT, TK_STR, TK_ID,
    TK_TRUE, TK_FALSE, TK_NIL,
    TK_LET, TK_FN, TK_IF, TK_ELSE, TK_WHILE, TK_FOR, TK_IN,
    TK_RETURN, TK_BREAK, TK_CONTINUE, TK_AND, TK_OR, TK_NOT,
    TK_EQ, TK_NE, TK_LE, TK_GE, TK_LT, TK_GT,
    TK_ASSIGN, TK_PLUS, TK_MINUS, TK_STAR, TK_SLASH, TK_PCT,
    TK_LP, TK_RP, TK_LB, TK_RB, TK_LC, TK_RC,
    TK_COMMA, TK_SEMI, TK_EOF
};

typedef struct {
    int type;
    long long ival;
    char *sval;
    int slen;
    int line;
} Token;

/* ============ AST ============ */
enum {
    E_INT, E_STR, E_BOOL, E_NIL, E_ID, E_LIST, E_FN,
    E_BIN, E_UN, E_CALL, E_IDX, E_AND, E_OR,
    S_LET, S_FN, S_IF, S_WHILE, S_FOR, S_RET, S_BREAK, S_CONT,
    S_ASSIGN, S_IDXASSIGN, S_EXPR
};

enum { OP_ADD, OP_SUB, OP_MUL, OP_DIV, OP_MOD, OP_EQ, OP_NE, OP_LT, OP_LE, OP_GT, OP_GE };
enum { UN_NEG, UN_NOT };

typedef struct {
    int type;
    int line;
    union {
        long long ival;
        struct { char *data; int len; } *str;
        struct { char *name; } id;
        struct { ASTNode **elems; int n; } list;
        struct { char **params; int np; ASTNode **body; int nb; } fn;
        struct { int op; ASTNode *l, *r; } bin;
        struct { int op; ASTNode *e; } un;
        struct { ASTNode *callee; ASTNode **args; int na; } call;
        struct { ASTNode *obj, *idx; } idx;
        struct { ASTNode *l, *r; } andor;
        struct { char *name; ASTNode *val; } let;
        struct { char *name; ASTNode **body; int nb; ASTNode *val; } fndecl;
        struct { ASTNode *cond; ASTNode **then_b; int tn; ASTNode **else_b; int en; int has_else; } ifst;
        struct { ASTNode *cond; ASTNode **body; int nb; } whilest;
        struct { char *var; ASTNode *iter; ASTNode **body; int nb; } forst;
        struct { ASTNode *val; } ret;
        struct { char *name; ASTNode *val; } assign;
        struct { ASTNode *obj, *idx, *val; } idxassign;
        struct { ASTNode *e; } exprst;
    };
} ASTNode;

/* ============ Globals ============ */
static Token *tokens;
static int ntok, tokpos;
static int err_flag, err_line;
static char err_msg[512];
static Value global_retval;
static List *display_stack[256];
static int display_sp;

static Value mk_int(long long v) { Value x; x.type=V_INT; x.ival=v; return x; }
static Value mk_bool(int b) { Value x; x.type=V_BOOL; x.bval=b; return x; }
static Value mk_nil(void) { Value x; x.type=V_NIL; return x; }
static Value mk_str(const char *s, int len) {
    Value x; x.type=V_STRING;
    x.str = malloc(sizeof(*x.str));
    x.str->data = malloc(len+1);
    memcpy(x.str->data, s, len);
    x.str->data[len]=0;
    x.str->len=len;
    return x;
}
static Value mk_list(void) {
    Value x; x.type=V_LIST;
    x.list = calloc(1, sizeof(List));
    return x;
}
static Value mk_func(Func *f) { Value x; x.type=V_FUNCTION; x.func=f; return x; }

static int truthy(Value v) {
    switch(v.type) {
        case V_INT: return v.ival != 0;
        case V_BOOL: return v.bval;
        case V_STRING: return v.str->len != 0;
        case V_LIST: return v.list->len != 0;
        case V_FUNCTION: return 1;
        case V_NIL: return 0;
    }
    return 0;
}

static const char *type_name(int t) {
    switch(t) {
        case V_INT: return "int";
        case V_BOOL: return "bool";
        case V_STRING: return "string";
        case V_LIST: return "list";
        case V_FUNCTION: return "function";
        case V_NIL: return "nil";
    }
    return "?";
}

/* ============ String buffer ============ */
typedef struct { char *buf; int len, cap; } SBuf;
static void sb_init(SBuf *s) { s->cap=128; s->buf=malloc(s->cap); s->len=0; }
static void sb_putc(SBuf *s, char c) {
    if(s->len+1>=s->cap){s->cap*=2;s->buf=realloc(s->buf,s->cap);}
    s->buf[s->len++]=c;
}
static void sb_puts(SBuf *s, const char *str) {
    int l=strlen(str);
    if(s->len+l>=s->cap){while(s->len+l>=s->cap)s->cap*=2;s->buf=realloc(s->buf,s->cap);}
    memcpy(s->buf+s->len,str,l);s->len+=l;
}
static void sb_putn(SBuf *s, const char *str, int n) {
    if(s->len+n>=s->cap){while(s->len+n>=s->cap)s->cap*=2;s->buf=realloc(s->buf,s->cap);}
    memcpy(s->buf+s->len,str,n);s->len+=n;
}

static void display_val(SBuf *s, Value v);

static void display_list(SBuf *s, List *l) {
    for(int i=0;i<display_sp;i++) if(display_stack[i]==l){sb_puts(s,"[...]");return;}
    if(display_sp<256) display_stack[display_sp++]=l;
    sb_putc(s,'[');
    for(int i=0;i<l->len;i++){
        if(i)sb_puts(s,", ");
        display_val(s,l->elems[i]);
    }
    sb_putc(s,']');
    if(display_sp>0)display_sp--;
}

static void display_val(SBuf *s, Value v) {
    switch(v.type){
        case V_INT: { char b[32]; snprintf(b,32,"%lld",v.ival); sb_puts(s,b); } break;
        case V_BOOL: sb_puts(s,v.bval?"true":"false"); break;
        case V_NIL: sb_puts(s,"nil"); break;
        case V_FUNCTION: sb_puts(s,"<fn>"); break;
        case V_STRING: sb_putn(s,v.str->data,v.str->len); break;
        case V_LIST: display_list(s,v.list); break;
    }
}

static void display_str_in_list(SBuf *s, Value v) {
    switch(v.type){
        case V_INT: { char b[32]; snprintf(b,32,"%lld",v.ival); sb_puts(s,b); } break;
        case V_BOOL: sb_puts(s,v.bval?"true":"false"); break;
        case V_NIL: sb_puts(s,"nil"); break;
        case V_FUNCTION: sb_puts(s,"<fn>"); break;
        case V_STRING: {
            sb_putc(s,'"');
            for(int i=0;i<v.str->len;i++){
                char c=v.str->data[i];
                if(c=='\\')sb_puts(s,"\\\\");
                else if(c=='"')sb_puts(s,"\\\"");
                else if(c=='\n')sb_puts(s,"\\n");
                else if(c=='\t')sb_puts(s,"\\t");
                else sb_putc(s,c);
            }
            sb_putc(s,'"');
        } break;
        case V_LIST: display_list(s,v.list); break;
    }
}

static void display_list_quoted(SBuf *s, List *l) {
    for(int i=0;i<display_sp;i++) if(display_stack[i]==l){sb_puts(s,"[...]");return;}
    if(display_sp<256) display_stack[display_sp++]=l;
    sb_putc(s,'[');
    for(int i=0;i<l->len;i++){
        if(i)sb_puts(s,", ");
        display_str_in_list(s,l->elems[i]);
    }
    sb_putc(s,']');
    if(display_sp>0)display_sp--;
}

static void display_val_quoted(SBuf *s, Value v) {
    switch(v.type){
        case V_INT: { char b[32]; snprintf(b,32,"%lld",v.ival); sb_puts(s,b); } break;
        case V_BOOL: sb_puts(s,v.bval?"true":"false"); break;
        case V_NIL: sb_puts(s,"nil"); break;
        case V_FUNCTION: sb_puts(s,"<fn>"); break;
        case V_STRING: {
            sb_putc(s,'"');
            for(int i=0;i<v.str->len;i++){
                char c=v.str->data[i];
                if(c=='\\')sb_puts(s,"\\\\");
                else if(c=='"')sb_puts(s,"\\\"");
                else if(c=='\n')sb_puts(s,"\\n");
                else if(c=='\t')sb_puts(s,"\\t");
                else sb_putc(s,c);
            }
            sb_putc(s,'"');
        } break;
        case V_LIST: display_list_quoted(s,v.list); break;
    }
}

static void display_top(SBuf *s, Value v) {
    display_sp=0;
    display_val(s,v);
}

static void display_top_quoted(SBuf *s, Value v) {
    display_sp=0;
    display_val_quoted(s,v);
}

/* ============ Equality ============ */
static int val_eq(Value a, Value b) {
    if(a.type!=b.type) return 0;
    switch(a.type){
        case V_INT: return a.ival==b.ival;
        case V_BOOL: return a.bval==b.bval;
        case V_NIL: return 1;
        case V_FUNCTION: return a.func==b.func;
        case V_STRING:
            if(a.str->len!=b.str->len) return 0;
            return memcmp(a.str->data,b.str->data,a.str->len)==0;
        case V_LIST: {
            if(a.list->len!=b.list->len) return 0;
            for(int i=0;i<a.list->len;i++)
                if(!val_eq(a.list->elems[i],b.list->elems[i])) return 0;
            return 1;
        }
    }
    return 0;
}

/* ============ Lexer ============ */
static void tokenize(const char *src) {
    int cap=4096, n=0, line=1;
    tokens=malloc(cap*sizeof(Token));
    int i=0, slen=strlen(src);
    while(i<slen){
        if(src[i]=='\n'){line++;i++;continue;}
        if(src[i]=='\r'||src[i]==' '||src[i]=='\t'){i++;continue;}
        if(src[i]=='#'){while(i<slen&&src[i]!='\n')i++;continue;}
        Token t; memset(&t,0,sizeof(t)); t.line=line;
        if(src[i]>='0'&&src[i]<='9'){
            long long v=0;
            while(i<slen&&src[i]>='0'&&src[i]<='9'){v=v*10+(src[i]-'0');i++;}
            t.type=TK_INT; t.ival=v;
        } else if(src[i]=='"'){
            i++;
            char *buf=malloc(256); int bl=0,bcap=256;
            while(i<slen&&src[i]!='"'){
                if(src[i]=='\\'&&i+1<slen){
                    i++;
                    if(src[i]=='n'){if(bl+1>=bcap){bcap*=2;buf=realloc(buf,bcap);}buf[bl++]='\n';}
                    else if(src[i]=='t'){if(bl+1>=bcap){bcap*=2;buf=realloc(buf,bcap);}buf[bl++]='\t';}
                    else if(src[i]=='"'){if(bl+1>=bcap){bcap*=2;buf=realloc(buf,bcap);}buf[bl++]='"';}
                    else if(src[i]=='\\'){if(bl+1>=bcap){bcap*=2;buf=realloc(buf,bcap);}buf[bl++]='\\';}
                    else {if(bl+1>=bcap){bcap*=2;buf=realloc(buf,bcap);}buf[bl++]=src[i];}
                    i++;
                } else {
                    if(bl+1>=bcap){bcap*=2;buf=realloc(buf,bcap);}
                    buf[bl++]=src[i++];
                }
            }
            if(i<slen)i++; // skip closing "
            t.type=TK_STR; t.sval=buf; t.slen=bl;
        } else if((src[i]>='A'&&src[i]<='Z')||(src[i]>='a'&&src[i]<='z')||src[i]=='_'){
            int st=i;
            while(i<slen&&((src[i]>='A'&&src[i]<='Z')||(src[i]>='a'&&src[i]<='z')||(src[i]>='0'&&src[i]<='9')||src[i]=='_'))i++;
            int ll=i-st;
            char *id=malloc(ll+1); memcpy(id,src+st,ll); id[ll]=0;
            if(!strcmp(id,"true"))t.type=TK_TRUE;
            else if(!strcmp(id,"false"))t.type=TK_FALSE;
            else if(!strcmp(id,"nil"))t.type=TK_NIL;
            else if(!strcmp(id,"let"))t.type=TK_LET;
            else if(!strcmp(id,"fn"))t.type=TK_FN;
            else if(!strcmp(id,"if"))t.type=TK_IF;
            else if(!strcmp(id,"else"))t.type=TK_ELSE;
            else if(!strcmp(id,"while"))t.type=TK_WHILE;
            else if(!strcmp(id,"for"))t.type=TK_FOR;
            else if(!strcmp(id,"in"))t.type=TK_IN;
            else if(!strcmp(id,"return"))t.type=TK_RETURN;
            else if(!strcmp(id,"break"))t.type=TK_BREAK;
            else if(!strcmp(id,"continue"))t.type=TK_CONTINUE;
            else if(!strcmp(id,"and"))t.type=TK_AND;
            else if(!strcmp(id,"or"))t.type=TK_OR;
            else if(!strcmp(id,"not"))t.type=TK_NOT;
            else {t.type=TK_ID; t.sval=id; t.slen=ll;}
        } else {
            switch(src[i]){
                case '(':t.type=TK_LP;i++;break;
                case ')':t.type=TK_RP;i++;break;
                case '[':t.type=TK_LB;i++;break;
                case ']':t.type=TK_RB;i++;break;
                case '{':t.type=TK_LC;i++;break;
                case '}':t.type=TK_RC;i++;break;
                case ',':t.type=TK_COMMA;i++;break;
                case ';':t.type=TK_SEMI;i++;break;
                case '+':t.type=TK_PLUS;i++;break;
                case '-':t.type=TK_MINUS;i++;break;
                case '*':t.type=TK_STAR;i++;break;
                case '/':t.type=TK_SLASH;i++;break;
                case '%':t.type=TK_PCT;i++;break;
                case '=':if(i+1<slen&&src[i+1]=='='){t.type=TK_EQ;i+=2;}else{t.type=TK_ASSIGN;i++;}break;
                case '!':if(i+1<slen&&src[i+1]=='='){t.type=TK_NE;i+=2;}else{i++;}break;
                case '<':if(i+1<slen&&src[i+1]=='='){t.type=TK_LE;i+=2;}else{t.type=TK_LT;i++;}break;
                case '>':if(i+1<slen&&src[i+1]=='='){t.type=TK_GE;i+=2;}else{t.type=TK_GT;i++;}break;
                default:i++;break;
            }
        }
        if(n>=cap){cap*=2;tokens=realloc(tokens,cap*sizeof(Token));}
        tokens[n++]=t;
    }
    Token eof; memset(&eof,0,sizeof(eof)); eof.type=TK_EOF; eof.line=line;
    if(n>=cap){cap*=2;tokens=realloc(tokens,cap*sizeof(Token));}
    tokens[n++]=eof;
    ntok=n;
}

/* ============ Parser ============ */
static Token *cur(){return &tokens[tokpos];}
static int at(int t){return tokens[tokpos].type==t;}
static void adv(){tokpos++;}
static void expect(int t){if(at(t))adv();}

static ASTNode *mk_node(int type, int line){
    ASTNode *n=calloc(1,sizeof(ASTNode));
    n->type=type; n->line=line;
    return n;
}

static ASTNode *parse_expr(void);
static ASTNode *parse_or(void);
static ASTNode **parse_block(int *cnt);

static ASTNode **parse_block(int *cnt){
    expect(TK_LC);
    int cap=16,n=0;
    ASTNode **body=malloc(cap*sizeof(ASTNode*));
    while(!at(TK_RC)&&!at(TK_EOF)){
        ASTNode *s=NULL;
        int ln=cur()->line;
        if(at(TK_LET)){
            adv();
            char *name=tokens[tokpos].sval; adv();
            expect(TK_ASSIGN);
            ASTNode *v=parse_expr();
            expect(TK_SEMI);
            s=mk_node(S_LET,ln); s->let.name=name; s->let.val=v;
        } else if(at(TK_FN)&&tokens[tokpos+1].type==TK_ID){
            adv();
            char *name=tokens[tokpos].sval; adv();
            expect(TK_LP);
            char **params=NULL; int np=0;
            if(!at(TK_RP)){
                int pc=8; params=malloc(pc*sizeof(char*));
                params[np++]=tokens[tokpos].sval; adv();
                while(at(TK_COMMA)){adv(); if(np>=pc){pc*=2;params=realloc(params,pc*sizeof(char*));} params[np++]=tokens[tokpos].sval; adv();}
            }
            expect(TK_RP);
            int nb; ASTNode **body2=parse_block(&nb);
            s=mk_node(S_FN,ln); s->fndecl.name=name; s->fndecl.body=body2; s->fndecl.nb=nb;
        } else if(at(TK_IF)){
            adv();
            ASTNode *cond=parse_expr();
            int tn; ASTNode **tb=parse_block(&tn);
            ASTNode **eb=NULL; int en=0; int he=0;
            if(at(TK_ELSE)){
                adv();
                if(at(TK_IF)){
                    // else if ... -> wrap in a block with one if statement
                    he=1;
                    // parse the if as a statement
                    int ln2=cur()->line; adv();
                    ASTNode *cond2=parse_expr();
                    int tn2; ASTNode **tb2=parse_block(&tn2);
                    ASTNode **eb2=NULL; int en2=0; int he2=0;
                    if(at(TK_ELSE)){adv(); if(at(TK_IF)){/* recursive else if */
                        he2=1;
                        // We'll handle nested else-if by making it a block with one if stmt
                        // For simplicity, parse as block
                        int eb_cap=4; eb2=malloc(eb_cap*sizeof(ASTNode*));
                        // Actually let's just parse a block here
                        // Hmm, let me restructure
                    } else {
                        he2=1; eb2=parse_block(&en2);
                    }}
                    ASTNode *ifn=mk_node(S_IF,ln2);
                    ifn->ifst.cond=cond2; ifn->ifst.then_b=tb2; ifn->ifst.tn=tn2;
                    ifn->ifst.else_b=eb2; ifn->ifst.en=en2; ifn->ifst.has_else=he2;
                    eb=malloc(sizeof(ASTNode*)); eb[0]=ifn; en=1; he=1;
                } else {
                    he=1; eb=parse_block(&en);
                }
            }
            s=mk_node(S_IF,ln); s->ifst.cond=cond; s->ifst.then_b=tb; s->ifst.tn=tn;
            s->ifst.else_b=eb; s->ifst.en=en; s->ifst.has_else=he;
        } else if(at(TK_WHILE)){
            adv();
            ASTNode *cond=parse_expr();
            int nb2; ASTNode **body2=parse_block(&nb2);
            s=mk_node(S_WHILE,ln); s->whilest.cond=cond; s->whilest.body=body2; s->whilest.nb=nb2;
        } else if(at(TK_FOR)){
            adv();
            char *var=tokens[tokpos].sval; adv();
            expect(TK_IN);
            ASTNode *iter=parse_expr();
            int nb2; ASTNode **body2=parse_block(&nb2);
            s=mk_node(S_FOR,ln); s->forst.var=var; s->forst.iter=iter; s->forst.body=body2; s->forst.nb=nb2;
        } else if(at(TK_RETURN)){
            adv();
            ASTNode *v=NULL;
            if(!at(TK_SEMI)) v=parse_expr();
            expect(TK_SEMI);
            s=mk_node(S_RET,ln); s->ret.val=v;
        } else if(at(TK_BREAK)){
            adv(); expect(TK_SEMI);
            s=mk_node(S_BREAK,ln);
        } else if(at(TK_CONTINUE)){
            adv(); expect(TK_SEMI);
            s=mk_node(S_CONT,ln);
        } else {
            // expression statement, assignment, or index assignment
            ASTNode *e=parse_expr();
            if(at(TK_ASSIGN)){
                adv();
                ASTNode *v=parse_expr();
                expect(TK_SEMI);
                if(e->type==E_ID){
                    s=mk_node(S_ASSIGN,ln); s->assign.name=e->id.name; s->assign.val=v;
                } else if(e->type==E_IDX){
                    s=mk_node(S_IDXASSIGN,ln); s->idxassign.obj=e->idx.obj; s->idxassign.idx=e->idx.idx; s->idxassign.val=v;
                } else {
                    s=mk_node(S_EXPR,ln); s->exprst.e=e;
                }
            } else {
                expect(TK_SEMI);
                s=mk_node(S_EXPR,ln); s->exprst.e=e;
            }
        }
        if(n>=cap){cap*=2;body=realloc(body,cap*sizeof(ASTNode*));}
        body[n++]=s;
    }
    expect(TK_RC);
    *cnt=n;
    return body;
}

static ASTNode *parse_primary(void){
    int ln=cur()->line;
    if(at(TK_INT)){long long v=tokens[tokpos].ival;adv();ASTNode *n=mk_node(E_INT,ln);n->ival=v;return n;}
    if(at(TK_STR)){char *d=tokens[tokpos].sval;int l=tokens[tokpos].slen;adv();ASTNode *n=mk_node(E_STR,ln);n->str=malloc(sizeof(*n->str));n->str->data=d;n->str->len=l;return n;}
    if(at(TK_TRUE)){adv();ASTNode *n=mk_node(E_BOOL,ln);n->ival=1;return n;}
    if(at(TK_FALSE)){adv();ASTNode *n=mk_node(E_BOOL,ln);n->ival=0;return n;}
    if(at(TK_NIL)){adv();ASTNode *n=mk_node(E_NIL,ln);return n;}
    if(at(TK_ID)){char *nm=tokens[tokpos].sval;adv();ASTNode *n=mk_node(E_ID,ln);n->id.name=nm;return n;}
    if(at(TK_LP)){adv();ASTNode *e=parse_expr();expect(TK_RP);return e;}
    if(at(TK_LB)){
        adv();
        ASTNode *n=mk_node(E_LIST,ln);
        if(!at(TK_RB)){
            int cap=8; n->list.elems=malloc(cap*sizeof(ASTNode*)); n->list.n=0;
            n->list.elems[n->list.n++]=parse_expr();
            while(at(TK_COMMA)){adv();if(n->list.n>=cap){cap*=2;n->list.elems=realloc(n->list.elems,cap*sizeof(ASTNode*));}n->list.elems[n->list.n++]=parse_expr();}
        } else {n->list.elems=NULL;n->list.n=0;}
        expect(TK_RB);
        return n;
    }
    if(at(TK_FN)){
        adv();
        expect(TK_LP);
        char **params=NULL; int np=0;
        if(!at(TK_RP)){
            int pc=8; params=malloc(pc*sizeof(char*));
            params[np++]=tokens[tokpos].sval; adv();
            while(at(TK_COMMA)){adv();if(np>=pc){pc*=2;params=realloc(params,pc*sizeof(char*));}params[np++]=tokens[tokpos].sval;adv();}
        }
        expect(TK_RP);
        int nb; ASTNode **body=parse_block(&nb);
        ASTNode *n=mk_node(E_FN,ln); n->fn.params=params; n->fn.np=np; n->fn.body=body; n->fn.nb=nb;
        return n;
    }
    // fallback
    adv();
    return mk_node(E_NIL,ln);
}

static ASTNode *parse_postfix(void){
    ASTNode *e=parse_primary();
    for(;;){
        if(at(TK_LP)){
            int ln=cur()->line; adv();
            ASTNode *n=mk_node(E_CALL,ln); n->call.callee=e;
            if(!at(TK_RP)){
                int cap=8; n->call.args=malloc(cap*sizeof(ASTNode*)); n->call.na=0;
                n->call.args[n->call.na++]=parse_expr();
                while(at(TK_COMMA)){adv();if(n->call.na>=cap){cap*=2;n->call.args=realloc(n->call.args,cap*sizeof(ASTNode*));}n->call.args[n->call.na++]=parse_expr();}
            } else {n->call.args=NULL;n->call.na=0;}
            expect(TK_RP);
            e=n;
        } else if(at(TK_LB)){
            int ln=cur()->line; adv();
            ASTNode *idx=parse_expr();
            expect(TK_RB);
            ASTNode *n=mk_node(E_IDX,ln); n->idx.obj=e; n->idx.idx=idx;
            e=n;
        } else break;
    }
    return e;
}

static ASTNode *parse_unary(void){
    int ln=cur()->line;
    if(at(TK_MINUS)){adv();ASTNode *n=mk_node(E_UN,ln);n->un.op=UN_NEG;n->un.e=parse_postfix();return n;}
    return parse_postfix();
}

static ASTNode *parse_mul(void){
    ASTNode *l=parse_unary();
    while(at(TK_STAR)||at(TK_SLASH)||at(TK_PCT)){
        int ln=cur()->line;
        int op=at(TK_STAR)?OP_MUL:(at(TK_SLASH)?OP_DIV:OP_MOD);
        adv();
        ASTNode *r=parse_unary();
        ASTNode *n=mk_node(E_BIN,ln);n->bin.op=op;n->bin.l=l;n->bin.r=r;
        l=n;
    }
    return l;
}

static ASTNode *parse_add(void){
    ASTNode *l=parse_mul();
    while(at(TK_PLUS)||at(TK_MINUS)){
        int ln=cur()->line;
        int op=at(TK_PLUS)?OP_ADD:OP_SUB;
        adv();
        ASTNode *r=parse_mul();
        ASTNode *n=mk_node(E_BIN,ln);n->bin.op=op;n->bin.l=l;n->bin.r=r;
        l=n;
    }
    return l;
}

static ASTNode *parse_cmp(void){
    ASTNode *l=parse_add();
    while(at(TK_EQ)||at(TK_NE)||at(TK_LT)||at(TK_LE)||at(TK_GT)||at(TK_GE)){
        int ln=cur()->line;
        int op;
        if(at(TK_EQ))op=OP_EQ;else if(at(TK_NE))op=OP_NE;else if(at(TK_LT))op=OP_LT;
        else if(at(TK_LE))op=OP_LE;else if(at(TK_GT))op=OP_GT;else op=OP_GE;
        adv();
        ASTNode *r=parse_add();
        ASTNode *n=mk_node(E_BIN,ln);n->bin.op=op;n->bin.l=l;n->bin.r=r;
        l=n;
    }
    return l;
}

static ASTNode *parse_not(void){
    int ln=cur()->line;
    if(at(TK_NOT)){adv();ASTNode *n=mk_node(E_UN,ln);n->un.op=UN_NOT;n->un.e=parse_not();return n;}
    return parse_cmp();
}

static ASTNode *parse_and(void){
    ASTNode *l=parse_not();
    while(at(TK_AND)){
        int ln=cur()->line; adv();
        ASTNode *r=parse_not();
        ASTNode *n=mk_node(E_AND,ln);n->andor.l=l;n->andor.r=r;
        l=n;
    }
    return l;
}

static ASTNode *parse_or(void){
    ASTNode *l=parse_and();
    while(at(TK_OR)){
        int ln=cur()->line; adv();
        ASTNode *r=parse_and();
        ASTNode *n=mk_node(E_OR,ln);n->andor.l=l;n->andor.r=r;
        l=n;
    }
    return l;
}

static ASTNode *parse_expr(void){return parse_or();}

/* ============ Scope ============ */
static Scope *scope_new(Scope *parent){
    Scope *s=calloc(1,sizeof(Scope));
    s->parent=parent;
    return s;
}
static void scope_declare(Scope *s, const char *name, Value v){
    if(s->count>=s->cap){s->cap=s->cap?s->cap*2:8;s->names=realloc(s->names,s->cap*sizeof(char*));s->values=realloc(s->values,s->cap*sizeof(Value));}
    s->names[s->count]=name;
    s->values[s->count]=v;
    s->count++;
}
static Value *scope_lookup(Scope *s, const char *name){
    while(s){
        for(int i=s->count-1;i>=0;i--)
            if(strcmp(s->names[i],name)==0) return &s->values[i];
        s=s->parent;
    }
    return NULL;
}

/* ============ Error ============ */
static void set_err(int line, const char *fmt, ...){
    if(err_flag) return;
    err_flag=1; err_line=line;
    va_list ap; va_start(ap,fmt); vsnprintf(err_msg,sizeof(err_msg),fmt,ap); va_end(ap);
}

/* ============ Integer overflow check ============ */
static int check_overflow(long long r, int line, int op_token_line){
    (void)r;
    return 0;
}

static Value int_binop(int op, long long a, long long b, int line, const char *opstr){
    long long r;
    switch(op){
        case OP_ADD:
            if(b>0 && a>0 && a>9223372036854775807LL-b){set_err(line,"integer overflow");return mk_nil();}
            if(b<0 && a<0 && a<(-9223372036854775807LL-1)-b){set_err(line,"integer overflow");return mk_nil();}
            r=a+b; break;
        case OP_SUB:
            if(b<0 && a>0 && a>9223372036854775807LL+b){set_err(line,"integer overflow");return mk_nil();}
            if(b>0 && a<0 && a<(-9223372036854775807LL-1)+b){set_err(line,"integer overflow");return mk_nil();}
            r=a-b; break;
        case OP_MUL:
            if(a==0||b==0){r=0;break;}
            if(a==-1&&b==(-9223372036854775807LL-1)){set_err(line,"integer overflow");return mk_nil();}
            if(b==-1&&a==(-9223372036854775807LL-1)){set_err(line,"integer overflow");return mk_nil();}
            if(a>0&&b>0&&a>9223372036854775807LL/b){set_err(line,"integer overflow");return mk_nil();}
            if(a<0&&b<0&&a<9223372036854775807LL/b){set_err(line,"integer overflow");return mk_nil();}
            if(a>0&&b<0&&b<(-9223372036854775807LL-1)/a){set_err(line,"integer overflow");return mk_nil();}
            if(a<0&&b>0&&a<(-9223372036854775807LL-1)/b){set_err(line,"integer overflow");return mk_nil();}
            r=a*b; break;
        case OP_DIV:
            if(b==0){set_err(line,"division by zero");return mk_nil();}
            if(a==(-9223372036854775807LL-1)&&b==-1){set_err(line,"integer overflow");return mk_nil();}
            r=a/b; break;
        case OP_MOD:
            if(b==0){set_err(line,"division by zero");return mk_nil();}
            if(b==-1){r=0;break;}
            r=a-(a/b)*b; break;
        default: r=0;
    }
    (void)opstr;
    return mk_int(r);
}

/* ============ Builtins ============ */
enum { BI_PRINT, BI_STR, BI_TYPE, BI_LEN, BI_PUSH, BI_POP, BI_RANGE, BI_SLICE };

static Value call_builtin(int id, Value *args, int na, int line){
    switch(id){
        case BI_PRINT:{
            for(int i=0;i<na;i++){
                if(i)fputc(' ',stdout);
                SBuf sb; sb_init(&sb);
                display_top(&sb,args[i]);
                fwrite(sb.buf,1,sb.len,stdout);
                free(sb.buf);
            }
            fputc('\n',stdout);
            return mk_nil();
        }
        case BI_STR:{
            if(na!=1){set_err(line,"expected 1 arguments, got %d",na);return mk_nil();}
            SBuf sb; sb_init(&sb);
            display_top(&sb,args[0]);
            Value r=mk_str(sb.buf,sb.len);
            free(sb.buf);
            return r;
        }
        case BI_TYPE:{
            if(na!=1){set_err(line,"expected 1 arguments, got %d",na);return mk_nil();}
            const char *tn=type_name(args[0].type);
            return mk_str(tn,strlen(tn));
        }
        case BI_LEN:{
            if(na!=1){set_err(line,"expected 1 arguments, got %d",na);return mk_nil();}
            if(args[0].type==V_STRING) return mk_int(args[0].str->len);
            if(args[0].type==V_LIST) return mk_int(args[0].list->len);
            set_err(line,"bad argument to len"); return mk_nil();
        }
        case BI_PUSH:{
            if(na!=2){set_err(line,"expected 2 arguments, got %d",na);return mk_nil();}
            if(args[0].type!=V_LIST){set_err(line,"bad argument to push");return mk_nil();}
            List *l=args[0].list;
            if(l->len>=l->cap){l->cap=l->cap?l->cap*2:8;l->elems=realloc(l->elems,l->cap*sizeof(Value));}
            l->elems[l->len++]=args[1];
            return mk_nil();
        }
        case BI_POP:{
            if(na!=1){set_err(line,"expected 1 arguments, got %d",na);return mk_nil();}
            if(args[0].type!=V_LIST||args[0].list->len==0){set_err(line,"bad argument to pop");return mk_nil();}
            return args[0].list->elems[--args[0].list->len];
        }
        case BI_RANGE:{
            if(na!=2){set_err(line,"expected 2 arguments, got %d",na);return mk_nil();}
            if(args[0].type!=V_INT||args[1].type!=V_INT){set_err(line,"bad argument to range");return mk_nil();}
            long long a=args[0].ival,b=args[1].ival;
            Value r=mk_list();
            if(b>a){
                long long n=b-a;
                if(n>100000000LL){set_err(line,"bad argument to range");return mk_nil();}
                r.list->cap=(int)n; r.list->elems=malloc(n*sizeof(Value));
                for(long long i=0;i<n;i++) r.list->elems[r.list->len++]=mk_int(a+i);
            }
            return r;
        }
        case BI_SLICE:{
            if(na!=3){set_err(line,"expected 3 arguments, got %d",na);return mk_nil();}
            if(args[1].type!=V_INT||args[2].type!=V_INT){set_err(line,"bad argument to slice");return mk_nil();}
            long long a=args[1].ival,b=args[2].ival;
            if(args[0].type==V_STRING){
                int l=args[0].str->len;
                if(a<0||b>l||a>b){set_err(line,"bad argument to slice");return mk_nil();}
                return mk_str(args[0].str->data+a,(int)(b-a));
            } else if(args[0].type==V_LIST){
                int l=args[0].list->len;
                if(a<0||b>l||a>b){set_err(line,"bad argument to slice");return mk_nil();}
                Value r=mk_list();
                r.list->cap=(int)(b-a); r.list->elems=malloc((b-a)*sizeof(Value));
                for(long long i=a;i<b;i++) r.list->elems[r.list->len++]=args[0].list->elems[i];
                return r;
            }
            set_err(line,"bad argument to slice"); return mk_nil();
        }
    }
    return mk_nil();
}

/* ============ Interpreter ============ */
static int exec_block(ASTNode **body, int nb, Scope *scope);
static Value eval_expr(ASTNode *e, Scope *scope);

static Value call_value(Value callee, Value *args, int na, int line){
    if(callee.type!=V_FUNCTION){set_err(line,"cannot call %s",type_name(callee.type));return mk_nil();}
    Func *f=callee.func;
    if(f->is_builtin){
        return call_builtin(f->builtin_id,args,na,line);
    }
    if(na!=f->nparams){set_err(line,"expected %d arguments, got %d",f->nparams,na);return mk_nil();}
    Scope *call_scope=scope_new(f->captured);
    for(int i=0;i<na;i++) scope_declare(call_scope,f->params[i],args[i]);
    exec_block(f->body,f->nbody,call_scope);
    return global_retval;
}

static Value eval_expr(ASTNode *e, Scope *scope){
    if(err_flag) return mk_nil();
    switch(e->type){
        case E_INT: return mk_int(e->ival);
        case E_STR: return mk_str(e->str->data,e->str->len);
        case E_BOOL: return mk_bool(e->ival);
        case E_NIL: return mk_nil();
        case E_ID:{
            Value *v=scope_lookup(scope,e->id.name);
            if(!v){set_err(e->line,"undefined variable %s",e->id.name);return mk_nil();}
            return *v;
        }
        case E_LIST:{
            Value r=mk_list();
            if(e->list.n>0){
                r.list->cap=e->list.n;
                r.list->elems=malloc(e->list.n*sizeof(Value));
                for(int i=0;i<e->list.n;i++){
                    r.list->elems[r.list->len++]=eval_expr(e->list.elems[i],scope);
                    if(err_flag) return mk_nil();
                }
            }
            return r;
        }
        case E_FN:{
            Func *f=calloc(1,sizeof(Func));
            f->params=e->fn.params; f->nparams=e->fn.np;
            f->body=e->fn.body; f->nbody=e->fn.nb;
            f->captured=scope;
            return mk_func(f);
        }
        case E_BIN:{
            Value l=eval_expr(e->bin.l,scope); if(err_flag)return mk_nil();
            Value r=eval_expr(e->bin.r,scope); if(err_flag)return mk_nil();
            int op=e->bin.op;
            if(op==OP_EQ) return mk_bool(val_eq(l,r));
            if(op==OP_NE) return mk_bool(!val_eq(l,r));
            if(op==OP_ADD){
                if(l.type==V_INT&&r.type==V_INT) return int_binop(OP_ADD,l.ival,r.ival,e->line,"+");
                if(l.type==V_STRING&&r.type==V_STRING){
                    int nl=l.str->len+r.str->len;
                    char *d=malloc(nl+1);
                    memcpy(d,l.str->data,l.str->len);
                    memcpy(d+l.str->len,r.str->data,r.str->len);
                    d[nl]=0;
                    Value res;res.type=V_STRING;res.str=malloc(sizeof(*res.str));res.str->data=d;res.str->len=nl;
                    return res;
                }
                if(l.type==V_LIST&&r.type==V_LIST){
                    Value res=mk_list();
                    int nl=l.list->len+r.list->len;
                    res.list->cap=nl;res.list->elems=malloc(nl*sizeof(Value));
                    for(int i=0;i<l.list->len;i++)res.list->elems[res.list->len++]=l.list->elems[i];
                    for(int i=0;i<r.list->len;i++)res.list->elems[res.list->len++]=r.list->elems[i];
                    return res;
                }
                set_err(e->line,"cannot apply + to %s and %s",type_name(l.type),type_name(r.type));return mk_nil();
            }
            if(op==OP_SUB){
                if(l.type==V_INT&&r.type==V_INT) return int_binop(OP_SUB,l.ival,r.ival,e->line,"-");
                set_err(e->line,"cannot apply - to %s and %s",type_name(l.type),type_name(r.type));return mk_nil();
            }
            if(op==OP_MUL){
                if(l.type==V_INT&&r.type==V_INT) return int_binop(OP_MUL,l.ival,r.ival,e->line,"*");
                set_err(e->line,"cannot apply * to %s and %s",type_name(l.type),type_name(r.type));return mk_nil();
            }
            if(op==OP_DIV){
                if(l.type==V_INT&&r.type==V_INT) return int_binop(OP_DIV,l.ival,r.ival,e->line,"/");
                set_err(e->line,"cannot apply / to %s and %s",type_name(l.type),type_name(r.type));return mk_nil();
            }
            if(op==OP_MOD){
                if(l.type==V_INT&&r.type==V_INT) return int_binop(OP_MOD,l.ival,r.ival,e->line,"%");
                set_err(e->line,"cannot apply %% to %s and %s",type_name(l.type),type_name(r.type));return mk_nil();
            }
            // comparisons
            if(op==OP_LT||op==OP_LE||op==OP_GT||op==OP_GE){
                if(l.type==V_INT&&r.type==V_INT){
                    long long a=l.ival,b=r.ival;
                    return mk_bool(op==OP_LT?a<b:op==OP_LE?a<=b:op==OP_GT?a>b:a>=b);
                }
                if(l.type==V_STRING&&r.type==V_STRING){
                    int cmp;
                    int ml=l.str->len<r.str->len?l.str->len:r.str->len;
                    cmp=memcmp(l.str->data,r.str->data,ml);
                    if(cmp==0) cmp=(l.str->len<r.str->len)?-1:(l.str->len>r.str->len)?1:0;
                    return mk_bool(op==OP_LT?cmp<0:op==OP_LE?cmp<=0:op==OP_GT?cmp>0:cmp>=0);
                }
                const char *os=op==OP_LT?"<":op==OP_LE?"<=":op==OP_GT?">":">=";
                set_err(e->line,"cannot apply %s to %s and %s",os,type_name(l.type),type_name(r.type));return mk_nil();
            }
            return mk_nil();
        }
        case E_UN:{
            if(e->un.op==UN_NOT){
                Value v=eval_expr(e->un.e,scope);
                return mk_bool(!truthy(v));
            }
            // negation
            Value v=eval_expr(e->un.e,scope); if(err_flag)return mk_nil();
            if(v.type!=V_INT){set_err(e->line,"cannot apply - to %s",type_name(v.type));return mk_nil();}
            if(v.ival==(-9223372036854775807LL-1)){set_err(e->line,"integer overflow");return mk_nil();}
            return mk_int(-v.ival);
        }
        case E_AND:{
            Value l=eval_expr(e->andor.l,scope); if(err_flag)return mk_nil();
            if(!truthy(l)) return l;
            return eval_expr(e->andor.r,scope);
        }
        case E_OR:{
            Value l=eval_expr(e->andor.l,scope); if(err_flag)return mk_nil();
            if(truthy(l)) return l;
            return eval_expr(e->andor.r,scope);
        }
        case E_CALL:{
            Value callee=eval_expr(e->call.callee,scope); if(err_flag)return mk_nil();
            Value *args=NULL; int na=e->call.na;
            if(na>0){
                args=malloc(na*sizeof(Value));
                for(int i=0;i<na;i++){
                    args[i]=eval_expr(e->call.args[i],scope);
                    if(err_flag){free(args);return mk_nil();}
                }
            }
            Value r=call_value(callee,args,na,e->call.line);
            free(args);
            return r;
        }
        case E_IDX:{
            Value obj=eval_expr(e->idx.obj,scope); if(err_flag)return mk_nil();
            Value idx=eval_expr(e->idx.idx,scope); if(err_flag)return mk_nil();
            if(obj.type==V_LIST){
                if(idx.type!=V_INT){set_err(e->line,"cannot index list with %s",type_name(idx.type));return mk_nil();}
                long long i=idx.ival;
                if(i<0||i>=obj.list->len){set_err(e->line,"index %lld out of range for length %d",i,obj.list->len);return mk_nil();}
                return obj.list->elems[i];
            }
            if(obj.type==V_STRING){
                if(idx.type!=V_INT){set_err(e->line,"cannot index string with %s",type_name(idx.type));return mk_nil();}
                long long i=idx.ival;
                if(i<0||i>=obj.str->len){set_err(e->line,"index %lld out of range for length %d",i,obj.str->len);return mk_nil();}
                return mk_str(obj.str->data+(int)i,1);
            }
            set_err(e->line,"cannot index %s with %s",type_name(obj.type),type_name(idx.type));return mk_nil();
        }
    }
    return mk_nil();
}

static int exec_block(ASTNode **body, int nb, Scope *scope){
    for(int i=0;i<nb;i++){
        int cf=exec_stmt(body[i],scope);
        if(cf!=0) return cf;
        if(err_flag) return 0;
    }
    return 0;
}

