            }
            expect(TK_RP);
            int nb; ASTNode **body=parse_block(&nb);
            // Create as: let name = fn(params) { body }
            // We'll create an S_LET with an E_FN value
            ASTNode *fnnode=mk_node(E_FN,ln);
            fnnode->fn.params=params; fnnode->fn.np=np;
            fnnode->fn.body=body; fnnode->fn.nb=nb;
            s=mk_node(S_LET,ln); s->let.name=name; s->let.val=fnnode;
        } else if(at(TK_IF)){
            adv();
            ASTNode *cond=parse_expr();
            int tn; ASTNode **tb=parse_block(&tn);
            ASTNode **eb=NULL; int en=0; int he=0;
            if(at(TK_ELSE)){
                adv();
                if(at(TK_IF)){
                    // else if: wrap in block
                    he=1;
                    // We need to parse the rest as a single if statement in a block
                    // Create a mini block with one if statement
                    // Recursively parse the if
                    // Actually let's just parse it as a block containing one if stmt
                    // We'll create a temporary statement list
                    int ln2=cur()->line; adv(); // consume 'if'
                    ASTNode *cond2=parse_expr();
                    int tn2; ASTNode **tb2=parse_block(&tn2);
                    ASTNode **eb2=NULL; int en2=0; int he2=0;
                    if(at(TK_ELSE)){
                        adv();
                        if(at(TK_IF)){
                            // nested else-if: make it a block with one if
                            // We need to handle this recursively...
                            // For simplicity, parse as a block
                            he2=1;
                            // Create a statement for the else-if
                            // Actually let me just parse a block here
                            // The else-if is parsed as a block containing an if statement
                            // But we need to handle the chain...
                            // Let me use a different approach: parse else-if as a block
                            // containing a single if statement (recursively)
                            // I'll create the if statement manually
                            int cap2=4; eb2=malloc(cap2*sizeof(ASTNode*)); en2=0;
                            // Parse the if statement
                            int ln3=cur()->line; adv(); // consume 'if'
                            ASTNode *cond3=parse_expr();
                            int tn3; ASTNode **tb3=parse_block(&tn3);
                            ASTNode **eb3=NULL; int en3=0; int he3=0;
                            if(at(TK_ELSE)){adv(); if(at(TK_IF)){/* deeper */
                                // For deep nesting, just parse as block
                                he3=1; eb3=parse_block(&en3);
                            } else {he3=1; eb3=parse_block(&en3);}}
                            ASTNode *if3=mk_node(S_IF,ln3);
                            if3->ifst.cond=cond3;if3->ifst.then_b=tb3;if3->ifst.tn=tn3;
                            if3->ifst.else_b=eb3;if3->ifst.en=en3;if3->ifst.has_else=he3;
                            eb2[en2++]=if3;
                        } else {
                            he2=1; eb2=parse_block(&en2);
                        }
                    }
                    ASTNode *if2=mk_node(S_IF,ln2);
                    if2->ifst.cond=cond2;if2->ifst.then_b=tb2;if2->ifst.tn=tn2;
                    if2->ifst.else_b=eb2;if2->ifst.en=en2;if2->ifst.has_else=he2;
