            s=mk_node(S_FOR,ln); s->forst.var=var; s->forst.iter=iter; s->forst.body=body; s->forst.nb=nb;
        } else if(at(TK_RETURN)){
            adv();
            ASTNode *v=NULL;
            if(!at(TK_SEMI)) v=parse_expr();
            expect(TK_SEMI);
            s=mk_node(S_RET,ln); s->ret.val=v;
        } else if(at(TK_BREAK)){
            adv(); expect(TK_SEMI);
            s=mk_node(S_BREAK,ln);
        } else if(at(TK_CONTINUE)){
            adv(); expect(TK_SEMI);
            s=mk_node(S_CONT,ln);
        } else {
            ASTNode *e=parse_expr();
            if(at(TK_ASSIGN)){
                adv();
                ASTNode *v=parse_expr();
                expect(TK_SEMI);
                if(e->type==E_ID){
                    s=mk_node(S_ASSIGN,ln); s->assign.name=e->id.name; s->assign.val=v;
                } else if(e->type==E_IDX){
                    s=mk_node(S_IDXASSIGN,ln); s->idxassign.obj=e->idx.obj; s->idxassign.idx=e->idx.idx; s->idxassign.val=v;
                } else {
                    s=mk_node(S_EXPR,ln); s->exprst.e=e;
                }
            } else {
                expect(TK_SEMI);
                s=mk_node(S_EXPR,ln); s->exprst.e=e;
            }
        }
        if(pn>=cap){cap*=2;prog=realloc(prog,cap*sizeof(ASTNode*));}
        prog[pn++]=s;
    }

    // Set up global scope with builtins
    Scope *global=scope_new(NULL);
    // Builtin: print
    {Func *f=calloc(1,sizeof(Func));f->is_builtin=1;f->builtin_id=BI_PRINT;f->nparams=-1;scope_declare(global,"print",mk_func(f));}
    {Func *f=calloc(1,sizeof(Func));f->is_builtin=1;f->builtin_id=BI_STR;f->nparams=1;scope_declare(global,"str",mk_func(f));}
    {Func *f=calloc(1,sizeof(Func));f->is_builtin=1;f->builtin_id=BI_TYPE;f->nparams=1;scope_declare(global,"type",mk_func(f));}
    {Func *f=calloc(1,sizeof(Func));f->is_builtin=1;f->builtin_id=BI_LEN;f->nparams=1;scope_declare(global,"len",mk_func(f));}
    {Func *f=calloc(1,sizeof(Func));f->is_builtin=1;f->builtin_id=BI_PUSH;f->nparams=2;scope_declare(global,"push",mk_func(f));}
    {Func *f=calloc(1,sizeof(Func));f->is_builtin=1;f->builtin_id=BI_POP;f->nparams=1;scope_declare(global,"pop",mk_func(f));}
    {Func *f=calloc(1,sizeof(Func));f->is_builtin=1;f->builtin_id=BI_RANGE;f->nparams=2;scope_declare(global,"range",mk_func(f));}
    {Func *f=calloc(1,sizeof(Func));f->is_builtin=1;f->builtin_id=BI_SLICE;f->nparams=3;scope_declare(global,"slice",mk_func(f));}

    // Run
    global_retval=mk_nil();
    exec_block(prog,pn,global);

    if(err_flag){
        printf("error at line %d: %s\n",err_line,err_msg);
    }
    return 0;
}

