// Build PNG
func crc32(_ data: [UInt8]) -> UInt32 {
    var crc: UInt32 = 0xFFFFFFFF
    for byte in data {
        crc ^= UInt32(byte)
        for _ in 0..<8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320
            } else {
                crc >>= 1
            }
        }
    }
    return crc ^ 0xFFFFFFFF
}

func adler32(_ data: [UInt8]) -> UInt32 {
    var a: UInt32 = 1
    var b: UInt32 = 0
    for byte in data {
        a = (a + UInt32(byte)) % 65521
        b = (b + a) % 65521
    }
    return (b << 16) | a
}

func makeChunk(_ type: String, _ data: [UInt8]) -> [UInt8] {
    var chunk = [UInt8]()
    let len = UInt32(data.count)
    chunk.append(UInt8((len >> 24) & 0xFF))
    chunk.append(UInt8((len >> 16) & 0xFF))
    chunk.append(UInt8((len >> 8) & 0xFF))
    chunk.append(UInt8(len & 0xFF))
    let typeBytes = Array(type.utf8)
    chunk.append(contentsOf: typeBytes)
    chunk.append(contentsOf: data)
    var crcInput = typeBytes
    crcInput.append(contentsOf: data)
    let crc = crc32(crcInput)
    chunk.append(UInt8((crc >> 24) & 0xFF))
    chunk.append(UInt8((crc >> 16) & 0xFF))
    chunk.append(UInt8((crc >> 8) & 0xFF))
    chunk.append(UInt8(crc & 0xFF))
    return chunk
}

func writeBE32(_ val: UInt32) -> [UInt8] {
    return [UInt8((val >> 24) & 0xFF), UInt8((val >> 16) & 0xFF), UInt8((val >> 8) & 0xFF), UInt8(val & 0xFF)]
}

func writeLE16(_ val: UInt16) -> [UInt8] {
    return [UInt8(val & 0xFF), UInt8((val >> 8) & 0xFF)]
}

// Build raw image data (filter byte 0 + RGB per row)
var rawData = [UInt8]()
rawData.reserveCapacity(height * (1 + width * 3))
for y in 0..<height {
    rawData.append(0) // filter: None
    let rowBase = y * width
    for x in 0..<width {
        let idx = (rowBase + x) * 3
        rawData.append(UInt8(canvas[idx]))
        rawData.append(UInt8(canvas[idx + 1]))
        rawData.append(UInt8(canvas[idx + 2]))
    }
}

// Build zlib stream with stored DEFLATE blocks
var zlibData = [UInt8]()
// zlib header: CMF=0x78, FLG=0x01 (so that (CMF*256+FLG)%31==0)
zlibData.append(0x78)
zlibData.append(0x01)

// DEFLATE stored blocks
let maxBlock = 65535
var offset = 0
let totalLen = rawData.count
while offset < totalLen {
    let blockLen = min(maxBlock, totalLen - offset)
    let isLast = (offset + blockLen >= totalLen)
    let bfinal: UInt8 = isLast ? 1 : 0
    zlibData.append(bfinal) // BFINAL in bit 0, BTYPE=00 in bits 1-2
    let len16 = UInt16(blockLen)
    let nlen16 = ~len16
    zlibData.append(contentsOf: writeLE16(len16))
    zlibData.append(contentsOf: writeLE16(nlen16))
    zlibData.append(contentsOf: rawData[offset..<(offset + blockLen)])
    offset += blockLen
}

// Handle empty data case
if totalLen == 0 {
    zlibData.append(0x01) // BFINAL=1, BTYPE=00
    zlibData.append(contentsOf: writeLE16(0))
    zlibData.append(contentsOf: writeLE16(0xFFFF))
}

// Adler-32
let adler = adler32(rawData)
zlibData.append(contentsOf: writeBE32(adler))

// Build PNG file
var png = [UInt8]()
// Signature
png.append(contentsOf: [137, 80, 78, 71, 13, 10, 26, 10])

// IHDR
var ihdrData = [UInt8]()
ihdrData.append(contentsOf: writeBE32(UInt32(width)))
ihdrData.append(contentsOf: writeBE32(UInt32(height)))
ihdrData.append(8)  // bit depth
ihdrData.append(2)  // color type: RGB
ihdrData.append(0)  // compression
ihdrData.append(0)  // filter
ihdrData.append(0)  // interlace
png.append(contentsOf: makeChunk("IHDR", ihdrData))

// IDAT
png.append(contentsOf: makeChunk("IDAT", zlibData))

// IEND
png.append(contentsOf: makeChunk("IEND", []))

// Write file
let outPath = "out.png"
let outData = Data(png)
try! outData.write(to: URL(fileURLWithPath: outPath))

import Foundation

// Safe JSON value extraction
func jsonInt(_ obj: [String: Any], _ key: String) -> Int {
    let v = obj[key]!
    if let i = v as? Int { return i }
    if let n = v as? NSNumber { return n.intValue }
    if let d = v as? Double { return Int(d) }
    fatalError("not an int: \(key)")
}

func jsonIntArray(_ obj: [String: Any], _ key: String) -> [Int] {
    let arr = obj[key]! as! [Any]
    return arr.map { v in
        if let i = v as? Int { return i }
        if let n = v as? NSNumber { return n.intValue }
        if let d = v as? Double { return Int(d) }
        fatalError("not an int in array")
    }
}

func jsonInt2D(_ obj: [String: Any], _ key: String) -> [[Int]] {
    let arr = obj[key]! as! [Any]
    return arr.map { row in
        let inner = row as! [Any]
        return inner.map { v in
            if let i = v as? Int { return i }
            if let n = v as? NSNumber { return n.intValue }
            if let d = v as? Double { return Int(d) }
            fatalError("not an int in 2D array")
        }
    }
}

let args = CommandLine.arguments
guard args.count >= 2 else { fatalError("need argument") }
let dir = args[1]
let jsonPath = URL(fileURLWithPath: dir).appendingPathComponent("scene.json").path
let fileData = try! Data(contentsOf: URL(fileURLWithPath: jsonPath))
let json = try! JSONSerialization.jsonObject(with: fileData) as! [String: Any]

let width = jsonInt(json, "width")
let height = jsonInt(json, "height")
let bg = jsonIntArray(json, "background")
let shapesJson = json["shapes"] as! [[String: Any]]

// Canvas: flat array [y * width * 3 + x * 3 + channel]
var canvas = [Int](repeating: 0, count: width * height * 3)
for i in 0..<(width * height) {
    canvas[i * 3] = bg[0]
    canvas[i * 3 + 1] = bg[1]
    canvas[i * 3 + 2] = bg[2]
}

var counts: [Int] = []

for shapeJson in shapesJson {
    let type = shapeJson["type"] as! String
    let color = jsonIntArray(shapeJson, "color")
    let sR = color[0], sG = color[1], sB = color[2], A = color[3]

    var count = 0

    switch type {
    case "rect":
        let rx = Int64(jsonInt(shapeJson, "x"))
        let ry = Int64(jsonInt(shapeJson, "y"))
        let w = Int64(jsonInt(shapeJson, "w"))
        let h = Int64(jsonInt(shapeJson, "h"))
        let rxEnd = rx + w
        let ryEnd = ry + h
        let yStart = max(0, Int(ry))
        let yEnd = min(height, Int(ryEnd))
        let xStart = max(0, Int(rx))
        let xEnd = min(width, Int(rxEnd))
        if yStart < yEnd && xStart < xEnd {
            for y in yStart..<yEnd {
                let rowBase = y * width
                for x in xStart..<xEnd {
                    let idx = (rowBase + x) * 3
                    count += 1
                    if A > 0 {
                        canvas[idx] = (sR * A + canvas[idx] * (255 - A) + 127) / 255
                        canvas[idx + 1] = (sG * A + canvas[idx + 1] * (255 - A) + 127) / 255
                        canvas[idx + 2] = (sB * A + canvas[idx + 2] * (255 - A) + 127) / 255
                    }
                }
            }
        }
    case "circle":
        let cx = Int64(jsonInt(shapeJson, "cx"))
        let cy = Int64(jsonInt(shapeJson, "cy"))
        let r = Int64(jsonInt(shapeJson, "r"))
        let r2 = r * r
        let yStart = max(0, Int(cy - r))
        let yEnd = min(height, Int(cy + r) + 1)
        let xStart = max(0, Int(cx - r))
        let xEnd = min(width, Int(cx + r) + 1)
        if yStart < yEnd && xStart < xEnd {
            for y in yStart..<yEnd {
                let dy = Int64(y) - cy
                let dy2 = dy * dy
                let rowBase = y * width
                for x in xStart..<xEnd {
                    let dx = Int64(x) - cx
                    if dx * dx + dy2 <= r2 {
                        let idx = (rowBase + x) * 3
                        count += 1
                        if A > 0 {
                            canvas[idx] = (sR * A + canvas[idx] * (255 - A) + 127) / 255
                            canvas[idx + 1] = (sG * A + canvas[idx + 1] * (255 - A) + 127) / 255
                            canvas[idx + 2] = (sB * A + canvas[idx + 2] * (255 - A) + 127) / 255
                        }
                    }
                }
            }
        }
    case "triangle":
        let points = jsonInt2D(shapeJson, "points")
        let px: [Int64] = points.map { Int64($0[0]) }
        let py: [Int64] = points.map { Int64($0[1]) }
        let minX64 = max(Int64(0), min(px[0], min(px[1], px[2])))
        let maxX64 = min(Int64(width - 1), max(px[0], max(px[1], px[2])))
        let minY64 = max(Int64(0), min(py[0], min(py[1], py[2])))
        let maxY64 = min(Int64(height - 1), max(py[0], max(py[1], py[2])))
        if minX64 <= maxX64 && minY64 <= maxY64 {
            let minX = Int(minX64)
            let maxX = Int(maxX64)
            let minY = Int(minY64)
            let maxY = Int(maxY64)
            for y in minY...maxY {
                let rowBase = y * width
                let yi = Int64(y)
                for x in minX...maxX {
                    let xi = Int64(x)
                    var allPos = true
                    var allNeg = true
                    for i in 0..<3 {
                        let j = (i + 1) % 3
                        let ei = (px[j] - px[i]) * (yi - py[i]) - (py[j] - py[i]) * (xi - px[i])
                        if ei < 0 { allPos = false }
                        if ei > 0 { allNeg = false }
                    }
                    if allPos || allNeg {
                        let idx = (rowBase + x) * 3
                        count += 1
                        if A > 0 {
                            canvas[idx] = (sR * A + canvas[idx] * (255 - A) + 127) / 255
                            canvas[idx + 1] = (sG * A + canvas[idx + 1] * (255 - A) + 127) / 255
                            canvas[idx + 2] = (sB * A + canvas[idx + 2] * (255 - A) + 127) / 255
                        }
                    }
                }
            }
        }
    case "line":
        let x1 = Int64(jsonInt(shapeJson, "x1"))
        let y1 = Int64(jsonInt(shapeJson, "y1"))
        let x2 = Int64(jsonInt(shapeJson, "x2"))
        let y2 = Int64(jsonInt(shapeJson, "y2"))
        let r = Int64(jsonInt(shapeJson, "r"))
        let dx = x2 - x1
        let dy = y2 - y1
        let L = dx * dx + dy * dy
        let r2 = r * r
        let bxMin = min(x1, x2) - r
        let bxMax = max(x1, x2) + r
        let byMin = min(y1, y2) - r
        let byMax = max(y1, y2) + r
        let yStart = max(0, Int(byMin))
        let yEnd = min(height, Int(byMax) + 1)
        let xStart = max(0, Int(bxMin))
        let xEnd = min(width, Int(bxMax) + 1)
        if yStart < yEnd && xStart < xEnd {
            for y in yStart..<yEnd {
                let rowBase = y * width
                let yi = Int64(y)
                for x in xStart..<xEnd {
                    let xi = Int64(x)
                    var covered = false
                    let t = (xi - x1) * dx + (yi - y1) * dy
                    if t <= 0 {
                        let ddx = xi - x1
                        let ddy = yi - y1
                        covered = (ddx * ddx + ddy * ddy <= r2)
                    } else if t >= L {
                        let ddx = xi - x2
                        let ddy = yi - y2
                        covered = (ddx * ddx + ddy * ddy <= r2)
                    } else {
                        let c = (xi - x1) * dy - (yi - y1) * dx
                        covered = (c * c <= r2 * L)
                    }
                    if covered {
                        let idx = (rowBase + x) * 3
                        count += 1
                        if A > 0 {
                            canvas[idx] = (sR * A + canvas[idx] * (255 - A) + 127) / 255
                            canvas[idx + 1] = (sG * A + canvas[idx + 1] * (255 - A) + 127) / 255
                            canvas[idx + 2] = (sB * A + canvas[idx + 2] * (255 - A) + 127) / 255
                        }
                    }
                }
            }
        }
    default:
        break
    }

    counts.append(count)
}

// Print summary
for i in 0..<counts.count {
