struct Tokenizer {
    let input: [UInt8]
    var pos: Int = 0

    init(_ s: String) { input = Array(s.utf8) }

    mutating func skipWS() {
        while pos < input.count {
            let c = input[pos]
            if c == 0x20 || c == 0x09 || c == 0x0A || c == 0x0D { pos += 1 }
            else if c == 0x2F && pos + 1 < input.count {
