// MARK: - Parser

final class ProtoParser {
    var tok: Tokenizer
    var cur: Tok = .eof
    var schema = Schema()
    var topMessageOrder: [String] = []

    init(_ source: String) {
        tok = Tokenizer(source)
        advance()
    }

    func advance() { cur = tok.next() }
    func expect(_ t: Tok) {
        if cur != t { fatalError("Expected \(t) got \(cur)") }
        advance()
    }
    func expectIdent(_ s: String) {
        if case .ident(let n) = cur, n == s { advance() } else { fatalError("Expected \(s) got \(cur)") }
    }
    func isIdent(_ s: String) -> Bool { if case .ident(let n) = cur { return n == s }; return false }
    func isSym(_ c: Character) -> Bool { if case .sym(let s) = cur { return s == c }; return false }

    func parse() {
        // skip syntax
        if isIdent("syntax") { advance(); expect(.sym("=")); advance(); expect(.sym(";")) }
        // skip package
        if isIdent("package") { advance(); while !isSym(";") { advance() }; expect(.sym(";")) }
        // skip top-level options
        while isIdent("option") { skipOption() }
        // parse top-level declarations
        while cur != .eof {
            if isIdent("message") {
                parseMessage(topLevel: true)
            } else if isIdent("enum") {
                parseEnum()
            } else if isIdent("option") {
                skipOption()
            } else {
                advance() // skip unknown top-level
            }
        }
        if let first = topMessageOrder.first { schema.rootTypeName = first }
    }

    func skipOption() {
        advance() // 'option'
        while !isSym(";") && cur != .eof { advance() }
        if isSym(";") { advance() }
    }

    func skipToSemicolon() {
        while !isSym(";") && cur != .eof { advance() }
        if isSym(";") { advance() }
    }

    func parseMessage(topLevel: Bool) {
        expect(.ident("message"))
        guard case .ident(let name) = cur else { fatalError("Expected message name") }
        advance()
        expect(.sym("{"))
        if topLevel { topMessageOrder.append(name) }
        var msgDef = MessageDef(name: name)
        while !isSym("}") && cur != .eof {
            if isIdent("message") {
                parseMessage(topLevel: false)
            } else if isIdent("enum") {
                parseEnum()
            } else if isIdent("oneof") {
                parseOneof(into: &msgDef)
            } else if isIdent("reserved") {
                advance(); skipToSemicolon()
            } else if isIdent("option") {
                skipOption()
            } else {
                parseField(into: &msgDef, oneofName: nil)
            }
        }
        expect(.sym("}"))
        msgDef.fields.sort { $0.number < $1.number }
        schema.messages[name] = msgDef
    }

    func parseOneof(into msgDef: inout MessageDef) {
        expect(.ident("oneof"))
        guard case .ident(let oneofName) = cur else { fatalError("Expected oneof name") }
        advance()
        msgDef.oneofNames.append(oneofName)
        expect(.sym("{"))
        while !isSym("}") && cur != .eof {
            if isIdent("option") { skipOption() }
            else { parseField(into: &msgDef, oneofName: oneofName) }
        }
        expect(.sym("}"))
    }

    func parseField(into msgDef: inout MessageDef, oneofName: String?) {
        var label: FieldLabel = .singular
        if isIdent("repeated") { label = .repeated; advance() }
        else if isIdent("optional") { label = .optional; advance() }

        var isMap = false
        var mapKeyType = ""
        var mapValueType = ""
        var typeName = ""

        if isIdent("map") {
            advance()
            expect(.sym("<"))
            guard case .ident(let kt) = cur else { fatalError("Expected map key type") }
            mapKeyType = kt; advance()
            expect(.sym(","))
            guard case .ident(let vt) = cur else { fatalError("Expected map value type") }
            mapValueType = vt; advance()
            expect(.sym(">"))
            isMap = true
            typeName = "map"
        } else {
            guard case .ident(let tn) = cur else { fatalError("Expected type name, got \(cur)") }
            typeName = tn; advance()
        }

        guard case .ident(let fname) = cur else { fatalError("Expected field name") }
        advance()
        expect(.sym("="))
        guard case .num(let fnum) = cur else { fatalError("Expected field number") }
        advance()

        // optional [options]
        if isSym("[") {
            advance()
            while !isSym("]") && cur != .eof { advance() }
            if isSym("]") { advance() }
        }
        if isSym(";") { advance() }

        let fd = FieldDef(number: fnum, name: fname, typeName: typeName, label: label,
                          oneofName: oneofName, isMap: isMap, mapKeyType: mapKeyType, mapValueType: mapValueType)
        msgDef.fields.append(fd)
    }

    func parseEnum() {
        expect(.ident("enum"))
        guard case .ident(let name) = cur else { fatalError("Expected enum name") }
        advance()
        expect(.sym("{"))
        var ed = EnumDef(name: name)
        while !isSym("}") && cur != .eof {
            if isIdent("option") { skipOption() }
            else if isIdent("reserved") { advance(); skipToSemicolon() }
            else {
                guard case .ident(let vname) = cur else { advance(); continue }
                advance()
                expect(.sym("="))
                guard case .num(let vnum) = cur else { fatalError("Expected enum value number") }
                advance()
                if isSym("[") { advance(); while !isSym("]") && cur != .eof { advance() }; if isSym("]") { advance() } }
                if isSym(";") { advance() }
                ed.values.append((name: vname, number: vnum))
            }
        }
        expect(.sym("}"))
        schema.enums[name] = ed
    }
}

// MARK: - Decoded Types

class DecodedMsg {
    var scalarFields: [Int: ScalarVal] = [:]
    var messageFields: [Int: DecodedMsg] = [:]
    var repeatedScalars: [Int: [ScalarVal]] = [:]
