    case int(Int32)
}

enum MapVal {
    case scalar(ScalarVal)
    case message(DecodedMsg)
}

// MARK: - Decoder

final class Decoder {
    let schema: Schema

    init(_ schema: Schema) { self.schema = schema }

    func readVarint(_ data: [UInt8], _ pos: inout Int) -> UInt64 {
        var result: UInt64 = 0
        var shift: UInt64 = 0
        for _ in 0..<10 {
            if pos >= data.count { break }
            let byte = data[pos]; pos += 1
            result |= UInt64(byte & 0x7F) << shift
            if byte & 0x80 == 0 { break }
            shift += 7
        }
        return result
    }

    func readFixed32(_ data: [UInt8], _ pos: inout Int) -> UInt32 {
        var v: UInt32 = 0
        for i in 0..<4 {
            if pos + i < data.count { v |= UInt32(data[pos+i]) << (8*i) }
        }
        pos += 4
        return v
    }

    func readFixed64(_ data: [UInt8], _ pos: inout Int) -> UInt64 {
        var v: UInt64 = 0
        for i in 0..<8 {
            if pos + i < data.count { v |= UInt64(data[pos+i]) << (8*i) }
        }
        pos += 8
        return v
    }

    func readLengthDelimited(_ data: [UInt8], _ pos: inout Int) -> [UInt8] {
        let len = Int(readVarint(data, &pos))
        let start = pos
        let end = min(pos + len, data.count)
        pos = end
        return Array(data[start..<end])
