        } else {
            if let sv = decodeScalarFromWire(data, &pos, typeName: valType, wireType: ewt) {
                return .scalar(sv)
            }
            return .scalar(defaultScalar(valType))
        }
    }

    func defaultMapValue(_ valType: String) -> MapVal {
        if isMessageType(valType) { return .message(DecodedMsg()) }
        return .scalar(defaultScalar(valType))
    }

    func defaultScalar(_ typeName: String) -> ScalarVal {
        switch typeName {
        case "bool": return .bool(false)
        case "string": return .string("")
        case "bytes": return .bytes([])
        default:
            if isEnumType(typeName) { return .enumVal(0) }
            return .int(0)
        }
    }

    func skipField(_ data: [UInt8], _ pos: inout Int, wireType: Int, fieldNum: Int) {
        if wireType == 3 {
            // group: skip until matching end group
            skipGroup(data, &pos, groupFieldNum: fieldNum)
        } else {
            skipValue(data, &pos, wireType: wireType)
        }
    }

    func skipGroup(_ data: [UInt8], _ pos: inout Int, groupFieldNum: Int) {
        while pos < data.count {
            let key = readVarint(data, &pos)
            let fn = Int(key >> 3)
            let wt = Int(key & 7)
            if wt == 4 && fn == groupFieldNum { return }
            if wt == 3 {
                skipGroup(data, &pos, groupFieldNum: fn)
            } else {
                skipValue(data, &pos, wireType: wt)
            }
        }
    }

    func skipValue(_ data: [UInt8], _ pos: inout Int, wireType: Int) {
        switch wireType {
        case 0: _ = readVarint(data, &pos)
        case 1: pos += 8
        case 2: let len = Int(readVarint(data, &pos)); pos += len
        case 5: pos += 4
        case 3: break // group handled elsewhere
        case 4: break // end group handled elsewhere
        default: break
        }
    }

    func isMessageType(_ name: String) -> Bool { schema.messages[name] != nil }
    func isEnumType(_ name: String) -> Bool { schema.enums[name] != nil }
    func isNumericType(_ name: String) -> Bool {
        return ["int32","int64","uint32","uint64","sint32","sint64","bool","fixed32","fixed64","sfixed32","sfixed64"].contains(name)
    }
}

// MARK: - JSON Printer

func toLowerCamelCase(_ name: String) -> String {
    var result = ""
    let chars = Array(name)
    var i = 0
    while i < chars.count {
        if chars[i] == "_" {
            if i + 1 < chars.count && chars[i+1] >= "a" && chars[i+1] <= "z" {
                result.append(Character(chars[i+1].uppercased()))
                i += 2
            } else {
                i += 1
            }
        } else {
            result.append(chars[i])
            i += 1
        }
    }
    return result
}

func escapeJSON(_ s: String) -> String {
    var r = "\""
    for scalar in s.unicodeScalars {
        let v = scalar.value
        switch v {
        case 0x22: r += "\\\""
        case 0x5C: r += "\\\\"
        case 0x08: r += "\\b"
        case 0x09: r += "\\t"
        case 0x0A: r += "\\n"
        case 0x0C: r += "\\f"
        case 0x0D: r += "\\r"
        default:
            if v < 0x20 {
                r += String(format: "\\u%04x", v)
            } else {
                r.append(Character(scalar))
            }
        }
    }
    r += "\""
    return r
}

func base64Encode(_ bytes: [UInt8]) -> String {
    return Data(bytes).base64EncodedString()
}

func isInt64Type(_ typeName: String) -> Bool {
    return ["int64","uint64","sint64","fixed64","sfixed64"].contains(typeName)
}

func isInt32Type(_ typeName: String) -> Bool {
    return ["int32","uint32","sint32","fixed32","sfixed32"].contains(typeName)
}

func formatScalar(_ sv: ScalarVal, typeName: String, schema: Schema) -> String {
    switch sv {
    case .int(let v):
        if isInt64Type(typeName) { return "\"\(v)\"" }
        return "\(v)"
    case .uint(let v):
        if isInt64Type(typeName) { return "\"\(v)\"" }
        return "\(v)"
    case .bool(let v): return v ? "true" : "false"
    case .string(let s): return escapeJSON(s)
    case .bytes(let b): return "\"\(base64Encode(b))\""
    case .enumVal(let v):
        if let ed = schema.enums[typeName] {
            if let match = ed.values.first(where: { $0.number == v }) {
                return "\"\(match.name)\""
            }
        }
        return "\(v)"
    }
}

func isScalarDefault(_ sv: ScalarVal, typeName: String) -> Bool {
    switch sv {
    case .int(let v): return v == 0
    case .uint(let v): return v == 0
    case .bool(let v): return !v
    case .string(let s): return s.isEmpty
    case .bytes(let b): return b.isEmpty
    case .enumVal(let v): return v == 0
    }
}

func printMessage(_ msg: DecodedMsg, def: MessageDef, schema: Schema) -> String {
    var parts: [String] = []
    let sortedFields = def.fields.sorted { $0.number < $1.number }

    for fd in sortedFields {
        let jsonName = toLowerCamelCase(fd.name)
        let fn = fd.number

        if fd.isMap {
            guard let entries = msg.mapEntries[fn], !entries.isEmpty else { continue }
            let sorted: [(MapKey, MapVal)]
            if fd.mapKeyType == "int32" {
                sorted = entries.sorted { (a, b) in
                    let ai: Int32; let bi: Int32
                    if case .int(let x) = a.0 { ai = x } else { ai = 0 }
                    if case .int(let x) = b.0 { bi = x } else { bi = 0 }
                    return ai < bi
                }
            } else {
                sorted = entries.sorted { (a, b) in
                    let as_: String; let bs: String
                    if case .str(let x) = a.0 { as_ = x } else { as_ = "" }
                    if case .str(let x) = b.0 { bs = x } else { bs = "" }
                    return as_.utf8.lexicographicallyPrecedes(bs.utf8)
                }
            }
            var mapParts: [String] = []
            for (k, v) in sorted {
                let keyStr: String
                switch k {
                case .str(let s): keyStr = escapeJSON(s)
                case .int(let i): keyStr = "\"\(i)\""
                }
                let valStr: String
                switch v {
                case .scalar(let sv): valStr = formatScalar(sv, typeName: fd.mapValueType, schema: schema)
                case .message(let m): valStr = printMessage(m, def: schema.messages[fd.mapValueType] ?? MessageDef(), schema: schema)
                }
                mapParts.append("\(keyStr):\(valStr)")
            }
            parts.append("\"\(jsonName)\":{\(mapParts.joined(separator: ","))}")
        } else if fd.label == .repeated {
            if isMessageType(fd.typeName) {
                guard let msgs = msg.repeatedMessages[fn], !msgs.isEmpty else { continue }
                let subDef = schema.messages[fd.typeName] ?? MessageDef()
                let elems = msgs.map { printMessage($0, def: subDef, schema: schema) }
                parts.append("\"\(jsonName)\":[\(elems.joined(separator: ","))]")
            } else {
                guard let elems = msg.repeatedScalars[fn], !elems.isEmpty else { continue }
                let strs = elems.map { formatScalar($0, typeName: fd.typeName, schema: schema) }
                parts.append("\"\(jsonName)\":[\(strs.joined(separator: ","))]")
            }
        } else {
            // singular or optional
            let isOneofMember = fd.oneofName != nil
            let isSetOneof: Bool
            if let on = fd.oneofName {
                isSetOneof = (msg.oneofSet[on] == fn)
            } else {
                isSetOneof = false
            }

            if isMessageType(fd.typeName) {
                guard msg.presentFields.contains(fn), let m = msg.messageFields[fn] else { continue }
                let subDef = schema.messages[fd.typeName] ?? MessageDef()
                parts.append("\"\(jsonName)\":\(printMessage(m, def: subDef, schema: schema))")
            } else if isEnumType(fd.typeName) {
                guard let sv = msg.scalarFields[fn] else { continue }
                let shouldPrint: Bool
                if fd.label == .optional || isSetOneof {
                    shouldPrint = msg.presentFields.contains(fn)
                } else if isOneofMember {
                    shouldPrint = isSetOneof
                } else {
                    shouldPrint = !isScalarDefault(sv, typeName: fd.typeName)
                }
                if shouldPrint {
                    parts.append("\"\(jsonName)\":\(formatScalar(sv, typeName: fd.typeName, schema: schema))")
                }
            } else {
                guard let sv = msg.scalarFields[fn] else { continue }
                let shouldPrint: Bool
                if fd.label == .optional || isSetOneof {
                    shouldPrint = msg.presentFields.contains(fn)
                } else if isOneofMember {
                    shouldPrint = isSetOneof
                } else {
                    shouldPrint = !isScalarDefault(sv, typeName: fd.typeName)
                }
                if shouldPrint {
                    parts.append("\"\(jsonName)\":\(formatScalar(sv, typeName: fd.typeName, schema: schema))")
                }
            }
        }
    }
    return "{\(parts.joined(separator: ","))}"
}

// MARK: - Main

func main() {
    let args = CommandLine.arguments
    guard args.count >= 2 else { exit(1) }
    let dir = args[1]

    let schemaPath = dir + "/schema.proto"
    let binPath = dir + "/messages.bin"

    guard let schemaContent = try? String(contentsOfFile: schemaPath, encoding: .utf8) else { exit(1) }
    guard let binData = try? Data(contentsOf: URL(fileURLWithPath: binPath)) else { exit(1) }

    let parser = ProtoParser(schemaContent)
    parser.parse()
    let schema = parser.schema

    let decoder = Decoder(schema)
    let bytes = [UInt8](binData)
    var pos = 0
    var output: [String] = []

    while pos < bytes.count {
        let len = Int(decoder.readVarint(bytes, &pos))
        let recordStart = pos
        let recordEnd = min(pos + len, bytes.count)
        let recordBytes = Array(bytes[recordStart..<recordEnd])
        pos = recordEnd

        let msg = decoder.decodeMessage(recordBytes, msgName: schema.rootTypeName)
        let def = schema.messages[schema.rootTypeName] ?? MessageDef()
        output.append(printMessage(msg, def: def, schema: schema))
    }

    for line in output {
        print(line)
    }
}

main()

import Foundation

// MARK: - Schema Types

enum FieldLabel { case singular, optional, repeated }

struct FieldDef {
    var number: Int = 0
    var name: String = ""
    var typeName: String = ""
    var label: FieldLabel = .singular
    var oneofName: String? = nil
    var isMap: Bool = false
    var mapKeyType: String = ""
    var mapValueType: String = ""
}

struct MessageDef {
    var name: String = ""
    var fields: [FieldDef] = []
    var oneofNames: [String] = []
}

struct EnumDef {
    var name: String = ""
    var values: [(name: String, number: Int)] = []
}

struct Schema {
    var messages: [String: MessageDef] = [:]
    var enums: [String: EnumDef] = [:]
    var rootTypeName: String = ""
}

// MARK: - Tokenizer

enum Tok: Equatable {
    case ident(String)
    case num(Int)
    case str(String)
    case sym(Character)
    case eof
}

struct Tokenizer {
    let input: [UInt8]
    var pos: Int = 0

    init(_ s: String) { input = Array(s.utf8) }

    mutating func skipWS() {
        while pos < input.count {
            let c = input[pos]
            if c == 0x20 || c == 0x09 || c == 0x0A || c == 0x0D { pos += 1 }
            else if c == 0x2F && pos + 1 < input.count {
                if input[pos+1] == 0x2F {
                    pos += 2
                    while pos < input.count && input[pos] != 0x0A { pos += 1 }
                    if pos < input.count { pos += 1 }
                } else if input[pos+1] == 0x2A {
                    pos += 2
                    while pos + 1 < input.count {
                        if input[pos] == 0x2A && input[pos+1] == 0x2F { pos += 2; break }
                        pos += 1
                    }
                } else { break }
            } else { break }
        }
    }

    mutating func next() -> Tok {
        skipWS()
        if pos >= input.count { return .eof }
        let c = input[pos]
        if c == 0x22 { // string literal
            pos += 1
            var s = ""
            while pos < input.count && input[pos] != 0x22 {
                s.append(Character(UnicodeScalar(input[pos])))
                pos += 1
            }
            if pos < input.count { pos += 1 }
            return .str(s)
        }
        if c == 0x2D || (c >= 0x30 && c <= 0x39) {
            var s = ""
            if c == 0x2D { s = "-"; pos += 1 }
            while pos < input.count && input[pos] >= 0x30 && input[pos] <= 0x39 {
                s.append(Character(UnicodeScalar(input[pos]))); pos += 1
            }
            return .num(Int(s) ?? 0)
        }
        if (c >= 0x41 && c <= 0x5A) || (c >= 0x61 && c <= 0x7A) || c == 0x5F {
            var s = ""
            while pos < input.count {
                let ch = input[pos]
                if (ch >= 0x41 && ch <= 0x5A) || (ch >= 0x61 && ch <= 0x7A) || (ch >= 0x30 && ch <= 0x39) || ch == 0x5F {
                    s.append(Character(UnicodeScalar(ch))); pos += 1
                } else { break }
            }
            return .ident(s)
        }
        pos += 1
        return .sym(Character(UnicodeScalar(c)))
    }
}

// MARK: - Parser

final class ProtoParser {
    var tok: Tokenizer
    var cur: Tok = .eof
    var schema = Schema()
    var topMessageOrder: [String] = []

    init(_ source: String) {
        tok = Tokenizer(source)
        advance()
    }

    func advance() { cur = tok.next() }
    func expect(_ t: Tok) {
        if cur != t { fatalError("Expected \(t) got \(cur)") }
        advance()
    }
    func expectIdent(_ s: String) {
        if case .ident(let n) = cur, n == s { advance() } else { fatalError("Expected \(s) got \(cur)") }
    }
    func isIdent(_ s: String) -> Bool { if case .ident(let n) = cur { return n == s }; return false }
    func isSym(_ c: Character) -> Bool { if case .sym(let s) = cur { return s == c }; return false }

    func parse() {
        if isIdent("syntax") { advance(); expect(.sym("=")); advance(); expect(.sym(";")) }
        if isIdent("package") { advance(); while !isSym(";") && cur != .eof { advance() }; if isSym(";") { advance() } }
        while isIdent("option") { skipOption() }
        while cur != .eof {
            if isIdent("message") {
                parseMessage(topLevel: true)
            } else if isIdent("enum") {
                parseEnum()
            } else if isIdent("option") {
                skipOption()
            } else {
                advance()
            }
        }
        if let first = topMessageOrder.first { schema.rootTypeName = first }
    }

    func skipOption() {
        advance() // 'option'
        while !isSym(";") && cur != .eof { advance() }
        if isSym(";") { advance() }
    }

    func skipToSemicolon() {
        while !isSym(";") && cur != .eof { advance() }
        if isSym(";") { advance() }
    }

    func parseMessage(topLevel: Bool) {
        expect(.ident("message"))
        guard case .ident(let name) = cur else { fatalError("Expected message name") }
        advance()
        expect(.sym("{"))
        if topLevel { topMessageOrder.append(name) }
        var msgDef = MessageDef(name: name)
        while !isSym("}") && cur != .eof {
            if isIdent("message") {
                parseMessage(topLevel: false)
            } else if isIdent("enum") {
                parseEnum()
            } else if isIdent("oneof") {
                parseOneof(into: &msgDef)
            } else if isIdent("reserved") {
                advance(); skipToSemicolon()
            } else if isIdent("option") {
                skipOption()
            } else {
                parseField(into: &msgDef, oneofName: nil)
            }
        }
        expect(.sym("}"))
        msgDef.fields.sort { $0.number < $1.number }
        schema.messages[name] = msgDef
    }

    func parseOneof(into msgDef: inout MessageDef) {
        expect(.ident("oneof"))
        guard case .ident(let oneofName) = cur else { fatalError("Expected oneof name") }
        advance()
        msgDef.oneofNames.append(oneofName)
        expect(.sym("{"))
        while !isSym("}") && cur != .eof {
            if isIdent("option") { skipOption() }
            else { parseField(into: &msgDef, oneofName: oneofName) }
        }
        expect(.sym("}"))
    }

    func parseField(into msgDef: inout MessageDef, oneofName: String?) {
        var label: FieldLabel = .singular
        if isIdent("repeated") { label = .repeated; advance() }
        else if isIdent("optional") { label = .optional; advance() }

        var isMap = false
        var mapKeyType = ""
        var mapValueType = ""
        var typeName = ""

        if isIdent("map") {
            advance()
            expect(.sym("<"))
            guard case .ident(let kt) = cur else { fatalError("Expected map key type") }
            mapKeyType = kt; advance()
            expect(.sym(","))
            guard case .ident(let vt) = cur else { fatalError("Expected map value type") }
            mapValueType = vt; advance()
            expect(.sym(">"))
            isMap = true
            typeName = "map"
        } else {
            guard case .ident(let tn) = cur else { fatalError("Expected type name, got \(cur)") }
            typeName = tn; advance()
        }

        guard case .ident(let fname) = cur else { fatalError("Expected field name") }
        advance()
        expect(.sym("="))
        guard case .num(let fnum) = cur else { fatalError("Expected field number") }
        advance()

        if isSym("[") {
            advance()
            while !isSym("]") && cur != .eof { advance() }
            if isSym("]") { advance() }
        }
        if isSym(";") { advance() }

        let fd = FieldDef(number: fnum, name: fname, typeName: typeName, label: label,
                          oneofName: oneofName, isMap: isMap, mapKeyType: mapKeyType, mapValueType: mapValueType)
        msgDef.fields.append(fd)
    }

    func parseEnum() {
        expect(.ident("enum"))
        guard case .ident(let name) = cur else { fatalError("Expected enum name") }
        advance()
        expect(.sym("{"))
        var ed = EnumDef(name: name)
        while !isSym("}") && cur != .eof {
            if isIdent("option") { skipOption() }
            else if isIdent("reserved") { advance(); skipToSemicolon() }
            else {
                guard case .ident(let vname) = cur else { advance(); continue }
                advance()
                expect(.sym("="))
                guard case .num(let vnum) = cur else { fatalError("Expected enum value number") }
                advance()
                if isSym("[") { advance(); while !isSym("]") && cur != .eof { advance() }; if isSym("]") { advance() } }
                if isSym(";") { advance() }
                ed.values.append((name: vname, number: vnum))
            }
        }
        expect(.sym("}"))
        schema.enums[name] = ed
    }
}

// MARK: - Decoded Types

class DecodedMsg {
    var scalarFields: [Int: ScalarVal] = [:]
    var messageFields: [Int: DecodedMsg] = [:]
    var repeatedScalars: [Int: [ScalarVal]] = [:]
    var repeatedMessages: [Int: [DecodedMsg]] = [:]
    var mapEntries: [Int: [(MapKey, MapVal)]] = [:]
    var presentFields: Set<Int> = []
    var oneofSet: [String: Int] = [:]
}

enum ScalarVal {
    case int(Int64)
    case uint(UInt64)
    case bool(Bool)
    case string(String)
    case bytes([UInt8])
    case enumVal(Int)
}

enum MapKey: Equatable {
    case str(String)
    case int(Int32)
}

enum MapVal {
    case scalar(ScalarVal)
    case message(DecodedMsg)
}

// MARK: - Helper functions

func isMessageType(_ name: String, _ schema: Schema) -> Bool { schema.messages[name] != nil }
func isEnumType(_ name: String, _ schema: Schema) -> Bool { schema.enums[name] != nil }
func isNumericType(_ name: String) -> Bool {
    return ["int32","int64","uint32","uint64","sint32","sint64","bool","fixed32","fixed64","sfixed32","sfixed64"].contains(name)
}

// MARK: - Decoder

final class Decoder {
    let schema: Schema

    init(_ schema: Schema) { self.schema = schema }

    func readVarint(_ data: [UInt8], _ pos: inout Int) -> UInt64 {
        var result: UInt64 = 0
        var shift: UInt64 = 0
        for _ in 0..<10 {
            if pos >= data.count { break }
            let byte = data[pos]; pos += 1
            result |= UInt64(byte & 0x7F) << shift
            if byte & 0x80 == 0 { break }
            shift += 7
        }
        return result
    }

    func readFixed32(_ data: [UInt8], _ pos: inout Int) -> UInt32 {
        var v: UInt32 = 0
        for i in 0..<4 {
            if pos + i < data.count { v |= UInt32(data[pos+i]) << (8*i) }
        }
        pos += 4
        return v
    }

    func readFixed64(_ data: [UInt8], _ pos: inout Int) -> UInt64 {
        var v: UInt64 = 0
        for i in 0..<8 {
            if pos + i < data.count { v |= UInt64(data[pos+i]) << (8*i) }
        }
        pos += 8
        return v
    }

    func readLengthDelimited(_ data: [UInt8], _ pos: inout Int) -> [UInt8] {
        let len = Int(readVarint(data, &pos))
        let start = pos
        let end = min(pos + len, data.count)
        pos = end
        return Array(data[start..<end])
    }

    func decodeMessage(_ data: [UInt8], msgName: String) -> DecodedMsg {
        let msg = DecodedMsg()
        guard let def = schema.messages[msgName] else { return msg }
        decodeInto(data, def: def, msg: msg)
        return msg
    }

    func decodeInto(_ data: [UInt8], def: MessageDef, msg: DecodedMsg) {
        var pos = 0
        while pos < data.count {
            let key = readVarint(data, &pos)
            let fieldNum = Int(key >> 3)
            let wireType = Int(key & 7)

            guard let fd = def.fields.first(where: { $0.number == fieldNum }) else {
                skipField(data, &pos, wireType: wireType, fieldNum: fieldNum)
                continue
            }

            // Handle oneof clearing
            if let oneofName = fd.oneofName {
                if let prev = msg.oneofSet[oneofName], prev != fieldNum {
                    msg.scalarFields.removeValue(forKey: prev)
                    msg.messageFields.removeValue(forKey: prev)
                    msg.repeatedScalars.removeValue(forKey: prev)
                    msg.repeatedMessages.removeValue(forKey: prev)
                    msg.mapEntries.removeValue(forKey: prev)
                    msg.presentFields.remove(prev)
                }
                msg.oneofSet[oneofName] = fieldNum
            }

            msg.presentFields.insert(fieldNum)

            if fd.isMap {
                decodeMapField(data, &pos, fd: fd, msg: msg, wireType: wireType)
            } else if fd.label == .repeated {
                decodeRepeatedField(data, &pos, fd: fd, wireType: wireType, msg: msg)
            } else {
                decodeSingularField(data, &pos, fd: fd, wireType: wireType, msg: msg)
            }
        }
    }

    func decodeSingularField(_ data: [UInt8], _ pos: inout Int, fd: FieldDef, wireType: Int, msg: DecodedMsg) {
        if isMessageType(fd.typeName, schema) {
            if wireType != 2 { skipValue(data, &pos, wireType: wireType); return }
            let subData = readLengthDelimited(data, &pos)
            if let existing = msg.messageFields[fd.number] {
                guard let subDef = schema.messages[fd.typeName] else { return }
                decodeInto(subData, def: subDef, msg: existing)
            } else {
                msg.messageFields[fd.number] = decodeMessage(subData, msgName: fd.typeName)
            }
        } else if isEnumType(fd.typeName, schema) {
            if wireType != 0 { skipValue(data, &pos, wireType: wireType); return }
            let v = readVarint(data, &pos)
            let sv = ScalarVal.enumVal(Int(Int32(truncatingIfNeeded: v)))
            msg.scalarFields[fd.number] = sv
        } else {
            decodeScalarField(data, &pos, fd: fd, wireType: wireType, msg: msg)
        }
    }

    func decodeScalarField(_ data: [UInt8], _ pos: inout Int, fd: FieldDef, wireType: Int, msg: DecodedMsg) {
        let sv: ScalarVal?
        switch fd.typeName {
        case "int32":
            if wireType != 0 { skipValue(data, &pos, wireType: wireType); return }
            let v = readVarint(data, &pos)
            sv = .int(Int64(Int32(truncatingIfNeeded: v)))
        case "int64":
            if wireType != 0 { skipValue(data, &pos, wireType: wireType); return }
            sv = .int(Int64(bitPattern: readVarint(data, &pos)))
        case "uint32":
            if wireType != 0 { skipValue(data, &pos, wireType: wireType); return }
            sv = .uint(readVarint(data, &pos) & 0xFFFFFFFF)
        case "uint64":
            if wireType != 0 { skipValue(data, &pos, wireType: wireType); return }
            sv = .uint(readVarint(data, &pos))
        case "sint32":
            if wireType != 0 { skipValue(data, &pos, wireType: wireType); return }
            let v = readVarint(data, &pos)
            let d = (v >> 1) ^ (v & 1 == 1 ? 0xFFFFFFFFFFFFFFFF : 0)
            sv = .int(Int64(Int32(truncatingIfNeeded: d)))
        case "sint64":
            if wireType != 0 { skipValue(data, &pos, wireType: wireType); return }
            let v = readVarint(data, &pos)
            let d = (v >> 1) ^ (v & 1 == 1 ? 0xFFFFFFFFFFFFFFFF : 0)
            sv = .int(Int64(bitPattern: d))
        case "bool":
            if wireType != 0 { skipValue(data, &pos, wireType: wireType); return }
            sv = .bool(readVarint(data, &pos) != 0)
        case "string":
            if wireType != 2 { skipValue(data, &pos, wireType: wireType); return }
            let bytes = readLengthDelimited(data, &pos)
            sv = .string(String(decoding: bytes, as: UTF8.self))
        case "bytes":
            if wireType != 2 { skipValue(data, &pos, wireType: wireType); return }
            sv = .bytes(readLengthDelimited(data, &pos))
        case "fixed32":
            if wireType != 5 { skipValue(data, &pos, wireType: wireType); return }
            sv = .uint(UInt64(readFixed32(data, &pos)))
        case "sfixed32":
            if wireType != 5 { skipValue(data, &pos, wireType: wireType); return }
            sv = .int(Int64(Int32(bitPattern: readFixed32(data, &pos))))
        case "fixed64":
            if wireType != 1 { skipValue(data, &pos, wireType: wireType); return }
            sv = .uint(readFixed64(data, &pos))
        case "sfixed64":
            if wireType != 1 { skipValue(data, &pos, wireType: wireType); return }
            sv = .int(Int64(bitPattern: readFixed64(data, &pos)))
        default:
            skipValue(data, &pos, wireType: wireType); return
        }
        if let sv = sv { msg.scalarFields[fd.number] = sv }
    }

    func decodeRepeatedField(_ data: [UInt8], _ pos: inout Int, fd: FieldDef, wireType: Int, msg: DecodedMsg) {
        if isMessageType(fd.typeName, schema) {
            if wireType != 2 { skipValue(data, &pos, wireType: wireType); return }
            let subData = readLengthDelimited(data, &pos)
            msg.repeatedMessages[fd.number, default: []].append(decodeMessage(subData, msgName: fd.typeName))
        } else if isEnumType(fd.typeName, schema) {
            if wireType == 2 {
                let payload = readLengthDelimited(data, &pos)
                var ppos = 0
                while ppos < payload.count {
                    let v = readVarint(payload, &ppos)
                    msg.repeatedScalars[fd.number, default: []].append(.enumVal(Int(Int32(truncatingIfNeeded: v))))
                }
            } else if wireType == 0 {
                let v = readVarint(data, &pos)
                msg.repeatedScalars[fd.number, default: []].append(.enumVal(Int(Int32(truncatingIfNeeded: v))))
            } else { skipValue(data, &pos, wireType: wireType) }
        } else if isNumericType(fd.typeName) {
            if wireType == 2 {
                // packed
                let payload = readLengthDelimited(data, &pos)
                var ppos = 0
                while ppos < payload.count {
                    if let sv = decodeScalarFromPayload(payload, &ppos, typeName: fd.typeName) {
                        msg.repeatedScalars[fd.number, default: []].append(sv)
                    }
                }
            } else {
                if let sv = decodeScalarFromWire(data, &pos, typeName: fd.typeName, wireType: wireType) {
                    msg.repeatedScalars[fd.number, default: []].append(sv)
                }
            }
        } else if fd.typeName == "string" {
            if wireType != 2 { skipValue(data, &pos, wireType: wireType); return }
            let bytes = readLengthDelimited(data, &pos)
            msg.repeatedScalars[fd.number, default: []].append(.string(String(decoding: bytes, as: UTF8.self)))
        } else if fd.typeName == "bytes" {
            if wireType != 2 { skipValue(data, &pos, wireType: wireType); return }
            msg.repeatedScalars[fd.number, default: []].append(.bytes(readLengthDelimited(data, &pos)))
        } else {
            skipValue(data, &pos, wireType: wireType)
        }
    }

    func decodeScalarFromPayload(_ payload: [UInt8], _ pos: inout Int, typeName: String) -> ScalarVal? {
        switch typeName {
        case "int32": let v = readVarint(payload, &pos); return .int(Int64(Int32(truncatingIfNeeded: v)))
        case "int64": let v = readVarint(payload, &pos); return .int(Int64(bitPattern: v))
        case "uint32": let v = readVarint(payload, &pos); return .uint(v & 0xFFFFFFFF)
        case "uint64": return .uint(readVarint(payload, &pos))
        case "sint32":
            let v = readVarint(payload, &pos)
            let d = (v >> 1) ^ (v & 1 == 1 ? 0xFFFFFFFFFFFFFFFF : 0)
            return .int(Int64(Int32(truncatingIfNeeded: d)))
        case "sint64":
            let v = readVarint(payload, &pos)
            let d = (v >> 1) ^ (v & 1 == 1 ? 0xFFFFFFFFFFFFFFFF : 0)
            return .int(Int64(bitPattern: d))
        case "bool": return .bool(readVarint(payload, &pos) != 0)
        case "fixed32": return .uint(UInt64(readFixed32(payload, &pos)))
        case "sfixed32": return .int(Int64(Int32(bitPattern: readFixed32(payload, &pos))))
        case "fixed64": return .uint(readFixed64(payload, &pos))
        case "sfixed64": return .int(Int64(bitPattern: readFixed64(payload, &pos)))
        default: return nil
        }
    }

    func decodeScalarFromWire(_ data: [UInt8], _ pos: inout Int, typeName: String, wireType: Int) -> ScalarVal? {
        switch typeName {
        case "int32","int64","uint32","uint64","sint32","sint64","bool":
            if wireType != 0 { skipValue(data, &pos, wireType: wireType); return nil }
            return decodeScalarFromPayload(data, &pos, typeName: typeName)
        case "fixed32","sfixed32":
            if wireType != 5 { skipValue(data, &pos, wireType: wireType); return nil }
            return decodeScalarFromPayload(data, &pos, typeName: typeName)
        case "fixed64","sfixed64":
            if wireType != 1 { skipValue(data, &pos, wireType: wireType); return nil }
            return decodeScalarFromPayload(data, &pos, typeName: typeName)
        default:
            skipValue(data, &pos, wireType: wireType); return nil
        }
    }

    func decodeMapField(_ data: [UInt8], _ pos: inout Int, fd: FieldDef, msg: DecodedMsg, wireType: Int) {
        if wireType != 2 { skipValue(data, &pos, wireType: wireType); return }
        let entryData = readLengthDelimited(data, &pos)
        var key: MapKey = fd.mapKeyType == "int32" ? .int(0) : .str("")
        var val: MapVal = defaultMapValue(fd.mapValueType)
        var epos = 0
        while epos < entryData.count {
            let ekey = readVarint(entryData, &epos)
            let efn = Int(ekey >> 3)
            let ewt = Int(ekey & 7)
            if efn == 1 {
                key = decodeMapKey(entryData, &epos, ewt: ewt, keyType: fd.mapKeyType)
            } else if efn == 2 {
                val = decodeMapValue(entryData, &epos, ewt: ewt, valType: fd.mapValueType)
            } else {
                skipValue(entryData, &epos, wireType: ewt)
            }
        }
        var entries = msg.mapEntries[fd.number] ?? []
        if let idx = entries.firstIndex(where: { $0.0 == key }) {
            entries[idx].1 = val
        } else {
            entries.append((key, val))
        }
        msg.mapEntries[fd.number] = entries
    }

    func decodeMapKey(_ data: [UInt8], _ pos: inout Int, ewt: Int, keyType: String) -> MapKey {
        if keyType == "string" {
            if ewt != 2 { skipValue(data, &pos, wireType: ewt); return .str("") }
            let bytes = readLengthDelimited(data, &pos)
            return .str(String(decoding: bytes, as: UTF8.self))
        } else {
            if ewt != 0 { skipValue(data, &pos, wireType: ewt); return .int(0) }
            let v = readVarint(data, &pos)
            return .int(Int32(truncatingIfNeeded: v))
        }
    }

    func decodeMapValue(_ data: [UInt8], _ pos: inout Int, ewt: Int, valType: String) -> MapVal {
        if isMessageType(valType, schema) {
            if ewt != 2 { skipValue(data, &pos, wireType: ewt); return .message(DecodedMsg()) }
            let subData = readLengthDelimited(data, &pos)
            return .message(decodeMessage(subData, msgName: valType))
        } else if isEnumType(valType, schema) {
            if ewt != 0 { skipValue(data, &pos, wireType: ewt); return .scalar(.enumVal(0)) }
            let v = readVarint(data, &pos)
            return .scalar(.enumVal(Int(Int32(truncatingIfNeeded: v))))
        } else if valType == "string" {
            if ewt != 2 { skipValue(data, &pos, wireType: ewt); return .scalar(.string("")) }
            let bytes = readLengthDelimited(data, &pos)
            return .scalar(.string(String(decoding: bytes, as: UTF8.self)))
        } else if valType == "bytes" {
            if ewt != 2 { skipValue(data, &pos, wireType: ewt); return .scalar(.bytes([])) }
            return .scalar(.bytes(readLengthDelimited(data, &pos)))
        } else {
            if let sv = decodeScalarFromWire(data, &pos, typeName: valType, wireType: ewt) {
                return .scalar(sv)
            }
            return .scalar(defaultScalar(valType))
        }
    }

    func defaultMapValue(_ valType: String) -> MapVal {
        if isMessageType(valType, schema) { return .message(DecodedMsg()) }
        return .scalar(defaultScalar(valType))
    }

    func defaultScalar(_ typeName: String) -> ScalarVal {
        switch typeName {
        case "bool": return .bool(false)
        case "string": return .string("")
        case "bytes": return .bytes([])
        default:
            if isEnumType(typeName, schema) { return .enumVal(0) }
            return .int(0)
        }
    }

    func skipField(_ data: [UInt8], _ pos: inout Int, wireType: Int, fieldNum: Int) {
        if wireType == 3 {
            skipGroup(data, &pos, groupFieldNum: fieldNum)
        } else {
            skipValue(data, &pos, wireType: wireType)
        }
    }

    func skipGroup(_ data: [UInt8], _ pos: inout Int, groupFieldNum: Int) {
        while pos < data.count {
            let key = readVarint(data, &pos)
            let fn = Int(key >> 3)
            let wt = Int(key & 7)
            if wt == 4 && fn == groupFieldNum { return }
            if wt == 3 {
                skipGroup(data, &pos, groupFieldNum: fn)
            } else {
                skipValue(data, &pos, wireType: wt)
            }
        }
    }

    func skipValue(_ data: [UInt8], _ pos: inout Int, wireType: Int) {
        switch wireType {
        case 0: _ = readVarint(data, &pos)
        case 1: pos += 8
        case 2: let len = Int(readVarint(data, &pos)); pos += len
        case 5: pos += 4
        case 3: break
        case 4: break
        default: break
        }
    }
}

// MARK: - JSON Printer

func toLowerCamelCase(_ name: String) -> String {
    var result = ""
    let chars = Array(name)
    var i = 0
    while i < chars.count {
        if chars[i] == "_" {
            if i + 1 < chars.count && chars[i+1] >= "a" && chars[i+1] <= "z" {
                result.append(Character(chars[i+1].uppercased()))
                i += 2
            } else {
                i += 1
            }
        } else {
            result.append(chars[i])
            i += 1
        }
    }
    return result
}

func escapeJSON(_ s: String) -> String {
    var r = "\""
    for scalar in s.unicodeScalars {
        let v = scalar.value
        switch v {
        case 0x22: r += "\\\""
        case 0x5C: r += "\\\\"
        case 0x08: r += "\\b"
        case 0x09: r += "\\t"
        case 0x0A: r += "\\n"
        case 0x0C: r += "\\f"
        case 0x0D: r += "\\r"
        default:
            if v < 0x20 {
                r += String(format: "\\u%04x", v)
            } else {
                r.append(Character(scalar))
            }
        }
    }
    r += "\""
    return r
}

func base64Encode(_ bytes: [UInt8]) -> String {
    return Data(bytes).base64EncodedString()
}

func isInt64Type(_ typeName: String) -> Bool {
    return ["int64","uint64","sint64","fixed64","sfixed64"].contains(typeName)
}

func formatScalar(_ sv: ScalarVal, typeName: String, schema: Schema) -> String {
    switch sv {
    case .int(let v):
        if isInt64Type(typeName) { return "\"\(v)\"" }
        return "\(v)"
    case .uint(let v):
        if isInt64Type(typeName) { return "\"\(v)\"" }
        return "\(v)"
    case .bool(let v): return v ? "true" : "false"
    case .string(let s): return escapeJSON(s)
    case .bytes(let b): return "\"\(base64Encode(b))\""
    case .enumVal(let v):
        if let ed = schema.enums[typeName] {
            if let match = ed.values.first(where: { $0.number == v }) {
                return "\"\(match.name)\""
            }
        }
        return "\(v)"
    }
}

func isScalarDefault(_ sv: ScalarVal, typeName: String) -> Bool {
    switch sv {
    case .int(let v): return v == 0
    case .uint(let v): return v == 0
    case .bool(let v): return !v
    case .string(let s): return s.isEmpty
    case .bytes(let b): return b.isEmpty
    case .enumVal(let v): return v == 0
    }
}

func printMessage(_ msg: DecodedMsg, def: MessageDef, schema: Schema) -> String {
    var parts: [String] = []
    let sortedFields = def.fields.sorted { $0.number < $1.number }

    for fd in sortedFields {
        let jsonName = toLowerCamelCase(fd.name)
        let fn = fd.number

        if fd.isMap {
            guard let entries = msg.mapEntries[fn], !entries.isEmpty else { continue }
            let sorted: [(MapKey, MapVal)]
            if fd.mapKeyType == "int32" {
                sorted = entries.sorted { (a, b) in
                    let ai: Int32; let bi: Int32
                    if case .int(let x) = a.0 { ai = x } else { ai = 0 }
                    if case .int(let x) = b.0 { bi = x } else { bi = 0 }
                    return ai < bi
                }
            } else {
                sorted = entries.sorted { (a, b) in
                    let as_: String; let bs: String
                    if case .str(let x) = a.0 { as_ = x } else { as_ = "" }
                    if case .str(let x) = b.0 { bs = x } else { bs = "" }
                    return as_.utf8.lexicographicallyPrecedes(bs.utf8)
                }
            }
            var mapParts: [String] = []
            for (k, v) in sorted {
                let keyStr: String
                switch k {
                case .str(let s): keyStr = escapeJSON(s)
                case .int(let i): keyStr = "\"\(i)\""
                }
                let valStr: String
                switch v {
                case .scalar(let sv): valStr = formatScalar(sv, typeName: fd.mapValueType, schema: schema)
                case .message(let m): valStr = printMessage(m, def: schema.messages[fd.mapValueType] ?? MessageDef(), schema: schema)
                }
                mapParts.append("\(keyStr):\(valStr)")
            }
            parts.append("\"\(jsonName)\":{\(mapParts.joined(separator: ","))}")
        } else if fd.label == .repeated {
            if isMessageType(fd.typeName, schema) {
                guard let msgs = msg.repeatedMessages[fn], !msgs.isEmpty else { continue }
                let subDef = schema.messages[fd.typeName] ?? MessageDef()
                let elems = msgs.map { printMessage($0, def: subDef, schema: schema) }
                parts.append("\"\(jsonName)\":[\(elems.joined(separator: ","))]")
            } else {
                guard let elems = msg.repeatedScalars[fn], !elems.isEmpty else { continue }
                let strs = elems.map { formatScalar($0, typeName: fd.typeName, schema: schema) }
                parts.append("\"\(jsonName)\":[\(strs.joined(separator: ","))]")
            }
        } else {
            let isOneofMember = fd.oneofName != nil
            let isSetOneof: Bool
            if let on = fd.oneofName {
                isSetOneof = (msg.oneofSet[on] == fn)
            } else {
                isSetOneof = false
            }

            if isMessageType(fd.typeName, schema) {
                guard msg.presentFields.contains(fn), let m = msg.messageFields[fn] else { continue }
                let subDef = schema.messages[fd.typeName] ?? MessageDef()
                parts.append("\"\(jsonName)\":\(printMessage(m, def: subDef, schema: schema))")
            } else if isEnumType(fd.typeName, schema) {
                guard let sv = msg.scalarFields[fn] else { continue }
                let shouldPrint: Bool
                if fd.label == .optional || isSetOneof {
                    shouldPrint = msg.presentFields.contains(fn)
                } else if isOneofMember {
                    shouldPrint = isSetOneof
                } else {
                    shouldPrint = !isScalarDefault(sv, typeName: fd.typeName)
                }
                if shouldPrint {
                    parts.append("\"\(jsonName)\":\(formatScalar(sv, typeName: fd.typeName, schema: schema))")
                }
            } else {
                guard let sv = msg.scalarFields[fn] else { continue }
                let shouldPrint: Bool
                if fd.label == .optional || isSetOneof {
                    shouldPrint = msg.presentFields.contains(fn)
                } else if isOneofMember {
                    shouldPrint = isSetOneof
                } else {
                    shouldPrint = !isScalarDefault(sv, typeName: fd.typeName)
                }
                if shouldPrint {
                    parts.append("\"\(jsonName)\":\(formatScalar(sv, typeName: fd.typeName, schema: schema))")
                }
            }
        }
    }
    return "{\(parts.joined(separator: ","))}"
}

// MARK: - Main

func main() {
    let args = CommandLine.arguments
    guard args.count >= 2 else { exit(1) }
    let dir = args[1]

    let schemaPath = dir + "/schema.proto"
    let binPath = dir + "/messages.bin"

    guard let schemaContent = try? String(contentsOfFile: schemaPath, encoding: .utf8) else { exit(1) }
    guard let binData = try? Data(contentsOf: URL(fileURLWithPath: binPath)) else { exit(1) }

    let parser = ProtoParser(schemaContent)
    parser.parse()
    let schema = parser.schema

    let decoder = Decoder(schema)
    let bytes = [UInt8](binData)
    var pos = 0
    var output: [String] = []

    while pos < bytes.count {
        let len = Int(decoder.readVarint(bytes, &pos))
        let recordStart = pos
        let recordEnd = min(pos + len, bytes.count)
        let recordBytes = Array(bytes[recordStart..<recordEnd])
        pos = recordEnd

        let msg = decoder.decodeMessage(recordBytes, msgName: schema.rootTypeName)
        let def = schema.messages[schema.rootTypeName] ?? MessageDef()
        output.append(printMessage(msg, def: def, schema: schema))
    }

    for line in output {
        print(line)
    }
}

main()

import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {

    static Map<String, MessageDef> messages = new HashMap<>();
    static Map<String, EnumDef> enums = new HashMap<>();
    static String rootTypeName;

    static class FieldDef {
        String name, type;
        int number;
        boolean repeated, optional, isMap;
        String oneofName;
        String mapKeyType, mapValueType;
    }

    static class MessageDef {
        String name;
        List<FieldDef> fields = new ArrayList<>();
        Map<Integer, FieldDef> fieldsByNumber = new HashMap<>();
        Set<String> oneofNames = new HashSet<>();
    }

    static class EnumDef {
        String name;
        Map<Integer, String> valuesByNumber = new HashMap<>();
    }

    static class Token {
        String type, value;
        Token(String t, String v) { type = t; value = v; }
    }

    static List<Token> tokenize(String input) {
        List<Token> tokens = new ArrayList<>();
        int i = 0, n = input.length();
        while (i < n) {
            char c = input.charAt(i);
            if (Character.isWhitespace(c)) { i++; continue; }
            if (c == '/' && i + 1 < n && input.charAt(i + 1) == '/') {
                while (i < n && input.charAt(i) != '\n') i++;
                continue;
            }
            if (c == '/' && i + 1 < n && input.charAt(i + 1) == '*') {
                i += 2;
                while (i + 1 < n && !(input.charAt(i) == '*' && input.charAt(i + 1) == '/')) i++;
                i += 2;
                continue;
            }
            if (c == '"') {
                i++;
                StringBuilder sb = new StringBuilder();
                while (i < n && input.charAt(i) != '"') { sb.append(input.charAt(i)); i++; }
                i++;
                tokens.add(new Token("STRING", sb.toString()));
                continue;
            }
            if (Character.isLetter(c) || c == '_') {
                int s = i;
                while (i < n && (Character.isLetterOrDigit(input.charAt(i)) || input.charAt(i) == '_')) i++;
                tokens.add(new Token("IDENT", input.substring(s, i)));
                continue;
            }
            if (Character.isDigit(c) || (c == '-' && i + 1 < n && Character.isDigit(input.charAt(i + 1)))) {
                int s = i;
                if (c == '-') i++;
                while (i < n && Character.isDigit(input.charAt(i))) i++;
                tokens.add(new Token("NUMBER", input.substring(s, i)));
                continue;
            }
            tokens.add(new Token("PUNCT", String.valueOf(c)));
            i++;
        }
        return tokens;
    }

    static class Parser {
        List<Token> tokens;
        int pos;
        Parser(List<Token> t) { tokens = t; }
        Token peek() { return pos < tokens.size() ? tokens.get(pos) : null; }
        Token next() { return tokens.get(pos++); }
        boolean matchPunct(String v) {
            if (peek() != null && peek().type.equals("PUNCT") && peek().value.equals(v)) { pos++; return true; }
            return false;
        }
        void expectPunct(String v) {
            if (!matchPunct(v)) throw new RuntimeException("Expected " + v + " got " + (peek() != null ? peek().type + ":" + peek().value : "EOF"));
        }

        void parseFile() {
            while (peek() != null) {
                Token t = peek();
                if (t.type.equals("IDENT")) {
                    switch (t.value) {
                        case "syntax": skipToSemicolon(); break;
                        case "package": skipToSemicolon(); break;
                        case "option": skipToSemicolon(); break;
                        case "message": parseMessage(); break;
                        case "enum": parseEnum(); break;
                        default: next(); break;
                    }
                } else next();
            }
        }

        void skipToSemicolon() {
            while (peek() != null && !(peek().type.equals("PUNCT") && peek().value.equals(";"))) next();
            if (peek() != null) next();
        }

        void parseMessage() {
            next(); // message
            String name = next().value;
            if (rootTypeName == null) rootTypeName = name;
            MessageDef msg = new MessageDef();
            msg.name = name;
            messages.put(name, msg);
            expectPunct("{");
            parseMessageBody(msg);
            expectPunct("}");
        }

        void parseMessageBody(MessageDef msg) {
            while (peek() != null && !(peek().type.equals("PUNCT") && peek().value.equals("}"))) {
                Token t = peek();
                if (t.type.equals("IDENT")) {
                    switch (t.value) {
                        case "message": parseMessage(); break;
                        case "enum": parseEnum(); break;
                        case "oneof": parseOneof(msg); break;
                        case "reserved": skipToSemicolon(); break;
                        case "option": skipToSemicolon(); break;
                        case "map": parseMapField(msg); break;
                        case "repeated": parseField(msg, true, false); break;
                        case "optional": parseField(msg, false, true); break;
                        default: parseField(msg, false, false); break;
                    }
                } else next();
            }
        }

        void parseField(MessageDef msg, boolean repeated, boolean optional) {
            if (repeated || optional) next();
            String type = next().value;
            String name = next().value;
            expectPunct("=");
            int number = Integer.parseInt(next().value);
            if (peek() != null && peek().type.equals("PUNCT") && peek().value.equals("[")) {
                next();
                while (peek() != null && !(peek().type.equals("PUNCT") && peek().value.equals("]"))) next();
                next();
            }
            expectPunct(";");
            FieldDef fd = new FieldDef();
            fd.name = name; fd.number = number; fd.type = type;
            fd.repeated = repeated; fd.optional = optional;
            msg.fields.add(fd);
            msg.fieldsByNumber.put(number, fd);
        }

        void parseMapField(MessageDef msg) {
            next(); // map
            expectPunct("<");
            String keyType = next().value;
            expectPunct(",");
            String valueType = next().value;
            expectPunct(">");
            expectPunct(">");
            String name = next().value;
            expectPunct("=");
            int number = Integer.parseInt(next().value);
            if (peek() != null && peek().type.equals("PUNCT") && peek().value.equals("[")) {
                next();
                while (peek() != null && !(peek().type.equals("PUNCT") && peek().value.equals("]"))) next();
                next();
            }
            expectPunct(";");
            FieldDef fd = new FieldDef();
            fd.name = name; fd.number = number; fd.isMap = true;
            fd.mapKeyType = keyType; fd.mapValueType = valueType;
            msg.fields.add(fd);
            msg.fieldsByNumber.put(number, fd);
        }

        void parseOneof(MessageDef msg) {
            next(); // oneof
            String oneofName = next().value;
            msg.oneofNames.add(oneofName);
            expectPunct("{");
            while (peek() != null && !(peek().type.equals("PUNCT") && peek().value.equals("}"))) {
                Token t = peek();
                if (t.type.equals("IDENT") && t.value.equals("option")) { skipToSemicolon(); }
                else if (t.type.equals("IDENT") && t.value.equals("reserved")) { skipToSemicolon(); }
                else {
                    String type = next().value;
                    String name = next().value;
                    expectPunct("=");
                    int number = Integer.parseInt(next().value);
                    if (peek() != null && peek().type.equals("PUNCT") && peek().value.equals("[")) {
                        next();
                        while (peek() != null && !(peek().type.equals("PUNCT") && peek().value.equals("]"))) next();
                        next();
                    }
                    expectPunct(";");
                    FieldDef fd = new FieldDef();
                    fd.name = name; fd.number = number; fd.type = type;
                    fd.oneofName = oneofName;
                    msg.fields.add(fd);
                    msg.fieldsByNumber.put(number, fd);
                }
            }
            expectPunct("}");
        }

        void parseEnum() {
            next(); // enum
            String name = next().value;
            EnumDef ed = new EnumDef();
            ed.name = name;
            enums.put(name, ed);
            expectPunct("{");
            while (peek() != null && !(peek().type.equals("PUNCT") && peek().value.equals("}"))) {
                Token t = peek();
                if (t.type.equals("IDENT") && t.value.equals("option")) { skipToSemicolon(); }
                else if (t.type.equals("IDENT") && t.value.equals("reserved")) { skipToSemicolon(); }
                else if (t.type.equals("IDENT")) {
                    String valName = next().value;
                    expectPunct("=");
                    int valNum = Integer.parseInt(next().value);
                    ed.valuesByNumber.put(valNum, valName);
                    if (peek() != null && peek().type.equals("PUNCT") && peek().value.equals("[")) {
                        next();
                        while (peek() != null && !(peek().type.equals("PUNCT") && peek().value.equals("]"))) next();
                        next();
                    }
                    expectPunct(";");
                } else next();
            }
            expectPunct("}");
        }
    }

    static class BinaryReader {
        byte[] data;
        int pos, end;
        BinaryReader(byte[] d, int off, int len) { data = d; pos = off; end = off + len; }
        boolean hasMore() { return pos < end; }
        long readVarint() {
            long r = 0;
            int shift = 0;
            for (int i = 0; i < 10; i++) {
                int b = data[pos++] & 0xFF;
                r |= ((long)(b & 0x7F)) << shift;
                if ((b & 0x80) == 0) break;
                shift += 7;
            }
            return r;
        }
        int readFixed32() {
            int v = (data[pos] & 0xFF) | ((data[pos+1] & 0xFF) << 8) | ((data[pos+2] & 0xFF) << 16) | ((data[pos+3] & 0xFF) << 24);
            pos += 4;
            return v;
        }
        long readFixed64() {
            long v = 0;
            for (int i = 0; i < 8; i++) v |= ((long)(data[pos+i] & 0xFF)) << (i * 8);
            pos += 8;
            return v;
        }
        byte[] readLengthDelimited() {
            int len = (int) readVarint();
            byte[] r = Arrays.copyOfRange(data, pos, pos + len);
            pos += len;
            return r;
        }
    }

    static class DecodedMessage {
        Map<Integer, Object> values = new LinkedHashMap<>();
        Set<Integer> present = new HashSet<>();
        Map<String, Integer> oneofSet = new HashMap<>();
    }

    static Object decodeValue(BinaryReader reader, String type) {
        if (messages.containsKey(type)) {
            byte[] b = reader.readLengthDelimited();
            return decodeMessage(b, type);
        }
        if (enums.containsKey(type)) {
            return (int) reader.readVarint();
        }
        switch (type) {
            case "int32": return (int) reader.readVarint();
            case "int64": return reader.readVarint();
            case "uint32": return reader.readVarint() & 0xFFFFFFFFL;
            case "uint64": return reader.readVarint();
            case "sint32": { long r = reader.readVarint(); int n = (int) r; return (n >>> 1) ^ -(n & 1); }
            case "sint64": { long r = reader.readVarint(); return (r >>> 1) ^ -(r & 1); }
            case "bool": return reader.readVarint() != 0;
            case "fixed32": return (long)(reader.readFixed32() & 0xFFFFFFFFL);
            case "fixed64": return reader.readFixed64();
            case "sfixed32": return reader.readFixed32();
            case "sfixed64": return reader.readFixed64();
            case "string": return new String(reader.readLengthDelimited(), java.nio.charset.StandardCharsets.UTF_8);
            case "bytes": return reader.readLengthDelimited();
            default: return null;
        }
    }

    static boolean isPackable(String type) {
        switch (type) {
            case "int32": case "int64": case "uint32": case "uint64":
            case "sint32": case "sint64": case "bool": case "fixed32":
            case "fixed64": case "sfixed32": case "sfixed64": return true;
            default: return enums.containsKey(type);
        }
    }

    static DecodedMessage decodeMessage(byte[] data, String typeName) {
        MessageDef msgDef = messages.get(typeName);
        DecodedMessage msg = new DecodedMessage();
        if (msgDef == null) return msg;
        BinaryReader reader = new BinaryReader(data, 0, data.length);
        while (reader.hasMore()) {
            long key = reader.readVarint();
            int fieldNumber = (int)(key >>> 3);
            int wireType = (int)(key & 7);
            FieldDef fd = msgDef.fieldsByNumber.get(fieldNumber);
            if (fd == null) {
                skipField(reader, wireType, fieldNumber);
                continue;
            }
            if (fd.oneofName != null) {
                Integer cur = msg.oneofSet.get(fd.oneofName);
                if (cur != null && cur != fieldNumber) {
                    msg.values.remove(cur);
                    msg.present.remove(cur);
                }
                msg.oneofSet.put(fd.oneofName, fieldNumber);
            }
            if (fd.isMap) {
                byte[] entryBytes = reader.readLengthDelimited();
                decodeMapEntry(msg, fd, entryBytes);
            } else if (fd.repeated) {
                @SuppressWarnings("unchecked")
                List<Object> list = (List<Object>) msg.values.computeIfAbsent(fieldNumber, k -> new ArrayList<>());
                if (wireType == 2 && isPackable(fd.type)) {
                    byte[] packed = reader.readLengthDelimited();
                    BinaryReader pr = new BinaryReader(packed, 0, packed.length);
                    while (pr.hasMore()) {
                        list.add(decodeValue(pr, fd.type));
                    }
                } else {
                    list.add(decodeValue(reader, fd.type));
                }
                msg.present.add(fieldNumber);
            } else {
                if (messages.containsKey(fd.type)) {
                    byte[] bytes = reader.readLengthDelimited();
                    DecodedMessage existing = (DecodedMessage) msg.values.get(fieldNumber);
                    if (existing == null) {
                        msg.values.put(fieldNumber, decodeMessage(bytes, fd.type));
                    } else {
                        mergeMessage(existing, decodeMessage(bytes, fd.type), fd.type);
                    }
                } else {
                    msg.values.put(fieldNumber, decodeValue(reader, fd.type));
                }
                msg.present.add(fieldNumber);
            }
        }
        return msg;
    }

    static void decodeMapEntry(DecodedMessage msg, FieldDef fd, byte[] entryBytes) {
        BinaryReader reader = new BinaryReader(entryBytes, 0, entryBytes.length);
        Object key = getDefaultKey(fd.mapKeyType);
        Object value = getDefaultVal(fd.mapValueType);
        while (reader.hasMore()) {
            long k = reader.readVarint();
            int fn = (int)(k >>> 3);
            int wt = (int)(k & 7);
            if (fn == 1) {
                key = decodeValue(reader, fd.mapKeyType);
            } else if (fn == 2) {
                if (messages.containsKey(fd.mapValueType)) {
                    byte[] b = reader.readLengthDelimited();
                    value = decodeMessage(b, fd.mapValueType);
                } else {
                    value = decodeValue(reader, fd.mapValueType);
                }
            } else {
                skipField(reader, wt, fn);
            }
        }
        @SuppressWarnings("unchecked")
        Map<Object, Object> map = (Map<Object, Object>) msg.values.computeIfAbsent(fd.number, k -> new LinkedHashMap<>());
        map.put(key, value);
        msg.present.add(fd.number);
    }

    static Object getDefaultKey(String type) {
        if (type.equals("string")) return "";
        return (int) 0;
    }

    static Object getDefaultVal(String type) {
        if (type.equals("string")) return "";
        if (type.equals("bytes")) return new byte[0];
        if (type.equals("bool")) return false;
        if (messages.containsKey(type)) return new DecodedMessage();
        return (long) 0;
    }

    static void skipField(BinaryReader reader, int wireType, int fieldNumber) {
        switch (wireType) {
            case 0: reader.readVarint(); break;
            case 1: reader.readFixed64(); break;
            case 2: reader.readLengthDelimited(); break;
            case 5: reader.readFixed32(); break;
            case 3:
                while (reader.hasMore()) {
                    long k = reader.readVarint();
                    int fn = (int)(k >>> 3);
                    int wt = (int)(k & 7);
                    if (wt == 4 && fn == fieldNumber) break;
                    skipField(reader, wt, fn);
                }
                break;
            case 4: break;
        }
    }

    static void mergeMessage(DecodedMessage target, DecodedMessage source, String typeName) {
        MessageDef msgDef = messages.get(typeName);
        if (msgDef == null) return;
        for (Map.Entry<Integer, Object> e : source.values.entrySet()) {
            int fn = e.getKey();
            FieldDef fd = msgDef.fieldsByNumber.get(fn);
            if (fd == null) continue;
            if (fd.repeated) {
                @SuppressWarnings("unchecked")
                List<Object> tl = (List<Object>) target.values.computeIfAbsent(fn, k -> new ArrayList<>());
                @SuppressWarnings("unchecked")
                List<Object> sl = (List<Object>) e.getValue();
                tl.addAll(sl);
            } else if (fd.isMap) {
                @SuppressWarnings("unchecked")
                Map<Object, Object> tm = (Map<Object, Object>) target.values.computeIfAbsent(fn, k -> new LinkedHashMap<>());
                @SuppressWarnings("unchecked")
                Map<Object, Object> sm = (Map<Object, Object>) e.getValue();
                tm.putAll(sm);
            } else if (messages.containsKey(fd.type)) {
                DecodedMessage ts = (DecodedMessage) target.values.get(fn);
                DecodedMessage ss = (DecodedMessage) e.getValue();
                if (ts == null) target.values.put(fn, ss);
                else mergeMessage(ts, ss, fd.type);
            } else {
                target.values.put(fn, e.getValue());
            }
            target.present.add(fn);
        }
        target.oneofSet.putAll(source.oneofSet);
    }

    static String toJson(DecodedMessage msg, String typeName) {
        MessageDef msgDef = messages.get(typeName);
        if (msgDef == null) return "{}";
        List<FieldDef> sorted = new ArrayList<>(msgDef.fields);
        sorted.sort((a, b) -> Integer.compare(a.number, b.number));
        StringBuilder sb = new StringBuilder();
        sb.append('{');
        boolean first = true;
        for (FieldDef fd : sorted) {
            if (!msg.present.contains(fd.number)) continue;
            if (!fd.repeated && !fd.isMap && !messages.containsKey(fd.type)) {
                if (fd.oneofName == null && !fd.optional) {
                    Object v = msg.values.get(fd.number);
                    if (isDefault(v, fd.type)) continue;
                }
            }
            if (fd.repeated) {
                @SuppressWarnings("unchecked")
                List<Object> list = (List<Object>) msg.values.get(fd.number);
                if (list == null || list.isEmpty()) continue;
            }
            if (fd.isMap) {
                @SuppressWarnings("unchecked")
                Map<Object, Object> map = (Map<Object, Object>) msg.values.get(fd.number);
                if (map == null || map.isEmpty()) continue;
            }
            if (!first) sb.append(',');
            first = false;
            sb.append('"').append(escapeJson(toJsonName(fd.name))).append("\":");
            sb.append(encodeVal(msg.values.get(fd.number), fd));
        }
        sb.append('}');
        return sb.toString();
    }

    static boolean isDefault(Object v, String type) {
        if (v == null) return true;
        if (type.equals("string")) return v.equals("");
        if (type.equals("bytes")) return ((byte[])v).length == 0;
        if (type.equals("bool")) return Boolean.FALSE.equals(v);
        if (enums.containsKey(type)) return ((Number)v).intValue() == 0;
        if (v instanceof Number) return ((Number)v).longValue() == 0;
        return false;
    }

    static String toJsonName(String name) {
        StringBuilder sb = new StringBuilder();
        boolean up = false;
        for (int i = 0; i < name.length(); i++) {
            char c = name.charAt(i);
            if (c == '_') { up = true; }
            else {
                if (up && c >= 'a' && c <= 'z') sb.append((char)(c - 32));
                else sb.append(c);
                up = false;
            }
        }
        return sb.toString();
    }

    static String encodeVal(Object val, FieldDef fd) {
        if (fd.isMap) return encodeMap((Map<Object, Object>) val, fd);
        if (fd.repeated) return encodeArray((List<Object>) val, fd);
        return encodeSingle(val, fd.type);
    }

    static String encodeSingle(Object val, String type) {
        if (val == null) val = getDefaultVal(type);
        if (messages.containsKey(type)) return toJson((DecodedMessage) val, type);
        if (enums.containsKey(type)) {
            int num = ((Number) val).intValue();
            String nm = enums.get(type).valuesByNumber.get(num);
            if (nm != null) return "\"" + nm + "\"";
            return String.valueOf(num);
        }
        if (type.equals("string")) return "\"" + escapeJson((String) val) + "\"";
        if (type.equals("bytes")) return "\"" + Base64.getEncoder().encodeToString((byte[]) val) + "\"";
        if (type.equals("bool")) return ((Boolean) val) ? "true" : "false";
        switch (type) {
            case "int32": case "sint32": case "sfixed32":
                return String.valueOf(((Number) val).intValue());
            case "uint32": case "fixed32":
                return String.valueOf(((Number) val).longValue() & 0xFFFFFFFFL);
            case "int64": case "sint64": case "sfixed64":
                return "\"" + ((Number) val).longValue() + "\"";
            case "uint64": case "fixed64":
                return "\"" + Long.toUnsignedString(((Number) val).longValue()) + "\"";
            default: return String.valueOf(val);
        }
    }

    static String encodeArray(List<Object> list, FieldDef fd) {
        StringBuilder sb = new StringBuilder();
        sb.append('[');
        for (int i = 0; i < list.size(); i++) {
            if (i > 0) sb.append(',');
            sb.append(encodeSingle(list.get(i), fd.type));
        }
        sb.append(']');
        return sb.toString();
    }

    static String encodeMap(Map<Object, Object> map, FieldDef fd) {
        if (map == null || map.isEmpty()) return "{}";
        List<Object> keys = new ArrayList<>(map.keySet());
        if (fd.mapKeyType.equals("string")) {
            keys.sort((a, b) -> {
                byte[] ba = ((String)a).getBytes(java.nio.charset.StandardCharsets.UTF_8);
                byte[] bb = ((String)b).getBytes(java.nio.charset.StandardCharsets.UTF_8);
                return cmpBytes(ba, bb);
            });
        } else {
            keys.sort((a, b) -> Integer.compare((Integer)a, (Integer)b));
        }
        StringBuilder sb = new StringBuilder();
        sb.append('{');
        boolean first = true;
        for (Object key : keys) {
            if (!first) sb.append(',');
            first = false;
            if (fd.mapKeyType.equals("string")) {
                sb.append('"').append(escapeJson((String) key)).append('"');
            } else {
                sb.append('"').append(key).append('"');
            }
            sb.append(':');
            sb.append(encodeSingle(map.get(key), fd.mapValueType));
        }
        sb.append('}');
        return sb.toString();
    }

    static int cmpBytes(byte[] a, byte[] b) {
        int min = Math.min(a.length, b.length);
        for (int i = 0; i < min; i++) {
            int d = (a[i] & 0xFF) - (b[i] & 0xFF);
            if (d != 0) return d;
        }
        return a.length - b.length;
    }

    static String escapeJson(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\b': sb.append("\\b"); break;
                case '\t': sb.append("\\t"); break;
                case '\n': sb.append("\\n"); break;
                case '\f': sb.append("\\f"); break;
                case '\r': sb.append("\\r"); break;
                default:
                    if (c < 0x20) sb.append(String.format("\\u%04x", (int)c));
                    else sb.append(c);
            }
        }
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        String schema = new String(Files.readAllBytes(Paths.get(dir, "schema.proto")), java.nio.charset.StandardCharsets.UTF_8);
        byte[] msgData = Files.readAllBytes(Paths.get(dir, "messages.bin"));

        List<Token> tokens = tokenize(schema);
        new Parser(tokens).parseFile();

        BinaryReader reader = new BinaryReader(msgData, 0, msgData.length);
        StringBuilder out = new StringBuilder();
        while (reader.hasMore()) {
            int len = (int) reader.readVarint();
            byte[] rec = Arrays.copyOfRange(msgData, reader.pos, reader.pos + len);
            reader.pos += len;
            DecodedMessage dm = decodeMessage(rec, rootTypeName);
            out.append(toJson(dm, rootTypeName)).append('\n');
        }
        System.out.print(out.toString());
    }
}

import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {

    static Map<String, MessageDef> messages = new HashMap<>();
    static Map<String, EnumDef> enums = new HashMap<>();
    static String rootTypeName;

    static class FieldDef {
        String name, type;
        int number;
        boolean repeated, optional, isMap;
        String oneofName;
        String mapKeyType, mapValueType;
    }

    static class MessageDef {
        String name;
        List<FieldDef> fields = new ArrayList<>();
        Map<Integer, FieldDef> fieldsByNumber = new HashMap<>();
        Set<String> oneofNames = new HashSet<>();
    }

    static class EnumDef {
        String name;
        Map<Integer, String> valuesByNumber = new HashMap<>();
    }

    static class Token {
        String type, value;
        Token(String t, String v) { type = t; value = v; }
    }

    static List<Token> tokenize(String input) {
        List<Token> tokens = new ArrayList<>();
        int i = 0, n = input.length();
        while (i < n) {
            char c = input.charAt(i);
            if (Character.isWhitespace(c)) { i++; continue; }
            if (c == '/' && i + 1 < n && input.charAt(i + 1) == '/') {
                while (i < n && input.charAt(i) != '\n') i++;
                continue;
            }
            if (c == '/' && i + 1 < n && input.charAt(i + 1) == '*') {
                i += 2;
                while (i + 1 < n && !(input.charAt(i) == '*' && input.charAt(i + 1) == '/')) i++;
                i += 2;
                continue;
            }
            if (c == '"') {
                i++;
                StringBuilder sb = new StringBuilder();
                while (i < n && input.charAt(i) != '"') { sb.append(input.charAt(i)); i++; }
                i++;
                tokens.add(new Token("STRING", sb.toString()));
                continue;
            }
            if (Character.isLetter(c) || c == '_') {
                int s = i;
                while (i < n && (Character.isLetterOrDigit(input.charAt(i)) || input.charAt(i) == '_')) i++;
                tokens.add(new Token("IDENT", input.substring(s, i)));
                continue;
            }
            if (Character.isDigit(c) || (c == '-' && i + 1 < n && Character.isDigit(input.charAt(i + 1)))) {
                int s = i;
                if (c == '-') i++;
                while (i < n && Character.isDigit(input.charAt(i))) i++;
                tokens.add(new Token("NUMBER", input.substring(s, i)));
                continue;
            }
            tokens.add(new Token("PUNCT", String.valueOf(c)));
            i++;
        }
        return tokens;
    }

    static class Parser {
        List<Token> tokens;
        int pos;
        Parser(List<Token> t) { tokens = t; }
        Token peek() { return pos < tokens.size() ? tokens.get(pos) : null; }
        Token next() { return tokens.get(pos++); }
        boolean matchPunct(String v) {
            if (peek() != null && peek().type.equals("PUNCT") && peek().value.equals(v)) { pos++; return true; }
            return false;
        }
        void expectPunct(String v) {
            if (!matchPunct(v)) throw new RuntimeException("Expected " + v + " got " + (peek() != null ? peek().type + ":" + peek().value : "EOF"));
        }

        void parseFile() {
            while (peek() != null) {
                Token t = peek();
                if (t.type.equals("IDENT")) {
                    switch (t.value) {
                        case "syntax": skipToSemicolon(); break;
                        case "package": skipToSemicolon(); break;
                        case "option": skipToSemicolon(); break;
                        case "message": parseMessage(); break;
                        case "enum": parseEnum(); break;
                        default: next(); break;
                    }
                } else next();
            }
        }

        void skipToSemicolon() {
            while (peek() != null && !(peek().type.equals("PUNCT") && peek().value.equals(";"))) next();
            if (peek() != null) next();
        }

        void parseMessage() {
            next(); // message
            String name = next().value;
            if (rootTypeName == null) rootTypeName = name;
            MessageDef msg = new MessageDef();
            msg.name = name;
            messages.put(name, msg);
            expectPunct("{");
            parseMessageBody(msg);
            expectPunct("}");
        }

        void parseMessageBody(MessageDef msg) {
            while (peek() != null && !(peek().type.equals("PUNCT") && peek().value.equals("}"))) {
                Token t = peek();
                if (t.type.equals("IDENT")) {
                    switch (t.value) {
                        case "message": parseMessage(); break;
                        case "enum": parseEnum(); break;
                        case "oneof": parseOneof(msg); break;
                        case "reserved": skipToSemicolon(); break;
                        case "option": skipToSemicolon(); break;
                        case "map": parseMapField(msg); break;
                        case "repeated": parseField(msg, true, false); break;
                        case "optional": parseField(msg, false, true); break;
                        default: parseField(msg, false, false); break;
                    }
                } else next();
            }
        }

        void parseField(MessageDef msg, boolean repeated, boolean optional) {
            if (repeated || optional) next();
            String type = next().value;
            String name = next().value;
            expectPunct("=");
            int number = Integer.parseInt(next().value);
            if (peek() != null && peek().type.equals("PUNCT") && peek().value.equals("[")) {
                next();
                while (peek() != null && !(peek().type.equals("PUNCT") && peek().value.equals("]"))) next();
                next();
            }
            expectPunct(";");
            FieldDef fd = new FieldDef();
            fd.name = name; fd.number = number; fd.type = type;
            fd.repeated = repeated; fd.optional = optional;
            msg.fields.add(fd);
            msg.fieldsByNumber.put(number, fd);
        }

        void parseMapField(MessageDef msg) {
            next(); // map
            expectPunct("<");
            String keyType = next().value;
            expectPunct(",");
            String valueType = next().value;
            expectPunct(">");
            String name = next().value;
            expectPunct("=");
            int number = Integer.parseInt(next().value);
            if (peek() != null && peek().type.equals("PUNCT") && peek().value.equals("[")) {
                next();
                while (peek() != null && !(peek().type.equals("PUNCT") && peek().value.equals("]"))) next();
                next();
            }
            expectPunct(";");
            FieldDef fd = new FieldDef();
            fd.name = name; fd.number = number; fd.isMap = true;
            fd.mapKeyType = keyType; fd.mapValueType = valueType;
            msg.fields.add(fd);
            msg.fieldsByNumber.put(number, fd);
        }

        void parseOneof(MessageDef msg) {
            next(); // oneof
            String oneofName = next().value;
            msg.oneofNames.add(oneofName);
            expectPunct("{");
            while (peek() != null && !(peek().type.equals("PUNCT") && peek().value.equals("}"))) {
                Token t = peek();
                if (t.type.equals("IDENT") && t.value.equals("option")) { skipToSemicolon(); }
                else if (t.type.equals("IDENT") && t.value.equals("reserved")) { skipToSemicolon(); }
                else {
                    String type = next().value;
                    String name = next().value;
                    expectPunct("=");
                    int number = Integer.parseInt(next().value);
                    if (peek() != null && peek().type.equals("PUNCT") && peek().value.equals("[")) {
                        next();
                        while (peek() != null && !(peek().type.equals("PUNCT") && peek().value.equals("]"))) next();
                        next();
                    }
                    expectPunct(";");
                    FieldDef fd = new FieldDef();
                    fd.name = name; fd.number = number; fd.type = type;
                    fd.oneofName = oneofName;
                    msg.fields.add(fd);
                    msg.fieldsByNumber.put(number, fd);
                }
            }
            expectPunct("}");
        }

        void parseEnum() {
            next(); // enum
            String name = next().value;
            EnumDef ed = new EnumDef();
            ed.name = name;
            enums.put(name, ed);
            expectPunct("{");
            while (peek() != null && !(peek().type.equals("PUNCT") && peek().value.equals("}"))) {
                Token t = peek();
                if (t.type.equals("IDENT") && t.value.equals("option")) { skipToSemicolon(); }
                else if (t.type.equals("IDENT") && t.value.equals("reserved")) { skipToSemicolon(); }
                else if (t.type.equals("IDENT")) {
                    String valName = next().value;
                    expectPunct("=");
                    int valNum = Integer.parseInt(next().value);
                    ed.valuesByNumber.put(valNum, valName);
                    if (peek() != null && peek().type.equals("PUNCT") && peek().value.equals("[")) {
                        next();
                        while (peek() != null && !(peek().type.equals("PUNCT") && peek().value.equals("]"))) next();
                        next();
                    }
                    expectPunct(";");
                } else next();
            }
            expectPunct("}");
        }
    }

    static class BinaryReader {
        byte[] data;
        int pos, end;
        BinaryReader(byte[] d, int off, int len) { data = d; pos = off; end = off + len; }
        boolean hasMore() { return pos < end; }
        long readVarint() {
            long r = 0;
            int shift = 0;
            for (int i = 0; i < 10; i++) {
                int b = data[pos++] & 0xFF;
                r |= ((long)(b & 0x7F)) << shift;
                if ((b & 0x80) == 0) break;
                shift += 7;
            }
            return r;
        }
        int readFixed32() {
            int v = (data[pos] & 0xFF) | ((data[pos+1] & 0xFF) << 8) | ((data[pos+2] & 0xFF) << 16) | ((data[pos+3] & 0xFF) << 24);
            pos += 4;
            return v;
        }
        long readFixed64() {
            long v = 0;
            for (int i = 0; i < 8; i++) v |= ((long)(data[pos+i] & 0xFF)) << (i * 8);
            pos += 8;
            return v;
        }
        byte[] readLengthDelimited() {
            int len = (int) readVarint();
            byte[] r = Arrays.copyOfRange(data, pos, pos + len);
            pos += len;
            return r;
        }
    }

    static class DecodedMessage {
        Map<Integer, Object> values = new LinkedHashMap<>();
        Set<Integer> present = new HashSet<>();
        Map<String, Integer> oneofSet = new HashMap<>();
    }

    static Object decodeValue(BinaryReader reader, String type) {
        if (messages.containsKey(type)) {
            byte[] b = reader.readLengthDelimited();
            return decodeMessage(b, type);
        }
        if (enums.containsKey(type)) {
            return (int) reader.readVarint();
        }
        switch (type) {
            case "int32": return (int) reader.readVarint();
            case "int64": return reader.readVarint();
            case "uint32": return reader.readVarint() & 0xFFFFFFFFL;
            case "uint64": return reader.readVarint();
            case "sint32": { long r = reader.readVarint(); int n = (int) r; return (n >>> 1) ^ -(n & 1); }
            case "sint64": { long r = reader.readVarint(); return (r >>> 1) ^ -(r & 1); }
            case "bool": return reader.readVarint() != 0;
            case "fixed32": return (long)(reader.readFixed32() & 0xFFFFFFFFL);
            case "fixed64": return reader.readFixed64();
            case "sfixed32": return reader.readFixed32();
            case "sfixed64": return reader.readFixed64();
            case "string": return new String(reader.readLengthDelimited(), java.nio.charset.StandardCharsets.UTF_8);
            case "bytes": return reader.readLengthDelimited();
            default: return null;
        }
    }

    static boolean isPackable(String type) {
        switch (type) {
            case "int32": case "int64": case "uint32": case "uint64":
            case "sint32": case "sint64": case "bool": case "fixed32":
            case "fixed64": case "sfixed32": case "sfixed64": return true;
            default: return enums.containsKey(type);
        }
    }

    static DecodedMessage decodeMessage(byte[] data, String typeName) {
        MessageDef msgDef = messages.get(typeName);
        DecodedMessage msg = new DecodedMessage();
        if (msgDef == null) return msg;
        BinaryReader reader = new BinaryReader(data, 0, data.length);
        while (reader.hasMore()) {
            long key = reader.readVarint();
            int fieldNumber = (int)(key >>> 3);
            int wireType = (int)(key & 7);
            FieldDef fd = msgDef.fieldsByNumber.get(fieldNumber);
            if (fd == null) {
                skipField(reader, wireType, fieldNumber);
                continue;
            }
            if (fd.oneofName != null) {
                Integer cur = msg.oneofSet.get(fd.oneofName);
                if (cur != null && cur != fieldNumber) {
                    msg.values.remove(cur);
                    msg.present.remove(cur);
                }
                msg.oneofSet.put(fd.oneofName, fieldNumber);
            }
            if (fd.isMap) {
                byte[] entryBytes = reader.readLengthDelimited();
                decodeMapEntry(msg, fd, entryBytes);
            } else if (fd.repeated) {
                @SuppressWarnings("unchecked")
                List<Object> list = (List<Object>) msg.values.computeIfAbsent(fieldNumber, k -> new ArrayList<>());
                if (wireType == 2 && isPackable(fd.type)) {
                    byte[] packed = reader.readLengthDelimited();
                    BinaryReader pr = new BinaryReader(packed, 0, packed.length);
                    while (pr.hasMore()) {
                        list.add(decodeValue(pr, fd.type));
                    }
                } else {
                    list.add(decodeValue(reader, fd.type));
                }
                msg.present.add(fieldNumber);
            } else {
                if (messages.containsKey(fd.type)) {
                    byte[] bytes = reader.readLengthDelimited();
                    DecodedMessage existing = (DecodedMessage) msg.values.get(fieldNumber);
                    if (existing == null) {
                        msg.values.put(fieldNumber, decodeMessage(bytes, fd.type));
                    } else {
                        mergeMessage(existing, decodeMessage(bytes, fd.type), fd.type);
                    }
                } else {
                    msg.values.put(fieldNumber, decodeValue(reader, fd.type));
                }
                msg.present.add(fieldNumber);
            }
        }
        return msg;
    }

    static void decodeMapEntry(DecodedMessage msg, FieldDef fd, byte[] entryBytes) {
        BinaryReader reader = new BinaryReader(entryBytes, 0, entryBytes.length);
        Object key = getDefaultKey(fd.mapKeyType);
        Object value = getDefaultVal(fd.mapValueType);
        while (reader.hasMore()) {
            long k = reader.readVarint();
            int fn = (int)(k >>> 3);
            int wt = (int)(k & 7);
            if (fn == 1) {
                key = decodeValue(reader, fd.mapKeyType);
            } else if (fn == 2) {
                if (messages.containsKey(fd.mapValueType)) {
                    byte[] b = reader.readLengthDelimited();
                    value = decodeMessage(b, fd.mapValueType);
                } else {
                    value = decodeValue(reader, fd.mapValueType);
                }
            } else {
                skipField(reader, wt, fn);
            }
        }
        @SuppressWarnings("unchecked")
        Map<Object, Object> map = (Map<Object, Object>) msg.values.computeIfAbsent(fd.number, k -> new LinkedHashMap<>());
        map.put(key, value);
        msg.present.add(fd.number);
    }

    static Object getDefaultKey(String type) {
        if (type.equals("string")) return "";
        return (int) 0;
    }

    static Object getDefaultVal(String type) {
        if (type.equals("string")) return "";
        if (type.equals("bytes")) return new byte[0];
        if (type.equals("bool")) return false;
        if (messages.containsKey(type)) return new DecodedMessage();
        return (long) 0;
    }

    static void skipField(BinaryReader reader, int wireType, int fieldNumber) {
        switch (wireType) {
            case 0: reader.readVarint(); break;
            case 1: reader.readFixed64(); break;
            case 2: reader.readLengthDelimited(); break;
            case 5: reader.readFixed32(); break;
            case 3:
                while (reader.hasMore()) {
                    long k = reader.readVarint();
                    int fn = (int)(k >>> 3);
                    int wt = (int)(k & 7);
                    if (wt == 4 && fn == fieldNumber) break;
                    skipField(reader, wt, fn);
                }
                break;
            case 4: break;
        }
    }

    static void mergeMessage(DecodedMessage target, DecodedMessage source, String typeName) {
        MessageDef msgDef = messages.get(typeName);
        if (msgDef == null) return;
        // Handle oneof: if source sets a oneof member different from target's, clear target's
        for (Map.Entry<String, Integer> e : source.oneofSet.entrySet()) {
            String oneofName = e.getKey();
            int srcField = e.getValue();
            Integer tgtField = target.oneofSet.get(oneofName);
            if (tgtField != null && tgtField != srcField) {
                target.values.remove(tgtField);
                target.present.remove(tgtField);
            }
        }
        for (Map.Entry<Integer, Object> e : source.values.entrySet()) {
            int fn = e.getKey();
            FieldDef fd = msgDef.fieldsByNumber.get(fn);
            if (fd == null) continue;
            if (fd.repeated) {
                @SuppressWarnings("unchecked")
                List<Object> tl = (List<Object>) target.values.computeIfAbsent(fn, k -> new ArrayList<>());
                @SuppressWarnings("unchecked")
                List<Object> sl = (List<Object>) e.getValue();
                tl.addAll(sl);
            } else if (fd.isMap) {
                @SuppressWarnings("unchecked")
                Map<Object, Object> tm = (Map<Object, Object>) target.values.computeIfAbsent(fn, k -> new LinkedHashMap<>());
                @SuppressWarnings("unchecked")
                Map<Object, Object> sm = (Map<Object, Object>) e.getValue();
                tm.putAll(sm);
            } else if (messages.containsKey(fd.type)) {
                DecodedMessage ts = (DecodedMessage) target.values.get(fn);
                DecodedMessage ss = (DecodedMessage) e.getValue();
                if (ts == null) target.values.put(fn, ss);
                else mergeMessage(ts, ss, fd.type);
            } else {
                target.values.put(fn, e.getValue());
            }
            target.present.add(fn);
        }
        target.oneofSet.putAll(source.oneofSet);
    }

    static String toJson(DecodedMessage msg, String typeName) {
        MessageDef msgDef = messages.get(typeName);
        if (msgDef == null) return "{}";
        List<FieldDef> sorted = new ArrayList<>(msgDef.fields);
        sorted.sort((a, b) -> Integer.compare(a.number, b.number));
        StringBuilder sb = new StringBuilder();
        sb.append('{');
        boolean first = true;
        for (FieldDef fd : sorted) {
            if (!msg.present.contains(fd.number)) continue;
            if (!fd.repeated && !fd.isMap && !messages.containsKey(fd.type)) {
                if (fd.oneofName == null && !fd.optional) {
                    Object v = msg.values.get(fd.number);
                    if (isDefault(v, fd.type)) continue;
                }
            }
            if (fd.repeated) {
                @SuppressWarnings("unchecked")
                List<Object> list = (List<Object>) msg.values.get(fd.number);
                if (list == null || list.isEmpty()) continue;
            }
            if (fd.isMap) {
                @SuppressWarnings("unchecked")
                Map<Object, Object> map = (Map<Object, Object>) msg.values.get(fd.number);
                if (map == null || map.isEmpty()) continue;
            }
            if (!first) sb.append(',');
            first = false;
            sb.append('"').append(escapeJson(toJsonName(fd.name))).append("\":");
            sb.append(encodeVal(msg.values.get(fd.number), fd));
        }
        sb.append('}');
        return sb.toString();
    }

    static boolean isDefault(Object v, String type) {
        if (v == null) return true;
        if (type.equals("string")) return v.equals("");
        if (type.equals("bytes")) return ((byte[])v).length == 0;
        if (type.equals("bool")) return Boolean.FALSE.equals(v);
        if (enums.containsKey(type)) return ((Number)v).intValue() == 0;
        if (v instanceof Number) return ((Number)v).longValue() == 0;
        return false;
    }

    static String toJsonName(String name) {
        StringBuilder sb = new StringBuilder();
        boolean up = false;
        for (int i = 0; i < name.length(); i++) {
            char c = name.charAt(i);
            if (c == '_') { up = true; }
            else {
                if (up && c >= 'a' && c <= 'z') sb.append((char)(c - 32));
                else sb.append(c);
                up = false;
            }
        }
        return sb.toString();
    }

    static String encodeVal(Object val, FieldDef fd) {
        if (fd.isMap) return encodeMap((Map<Object, Object>) val, fd);
        if (fd.repeated) return encodeArray((List<Object>) val, fd);
        return encodeSingle(val, fd.type);
    }

    static String encodeSingle(Object val, String type) {
        if (val == null) val = getDefaultVal(type);
        if (messages.containsKey(type)) return toJson((DecodedMessage) val, type);
        if (enums.containsKey(type)) {
            int num = ((Number) val).intValue();
            String nm = enums.get(type).valuesByNumber.get(num);
            if (nm != null) return "\"" + nm + "\"";
            return String.valueOf(num);
        }
        if (type.equals("string")) return "\"" + escapeJson((String) val) + "\"";
        if (type.equals("bytes")) return "\"" + Base64.getEncoder().encodeToString((byte[]) val) + "\"";
        if (type.equals("bool")) return ((Boolean) val) ? "true" : "false";
        switch (type) {
            case "int32": case "sint32": case "sfixed32":
                return String.valueOf(((Number) val).intValue());
            case "uint32": case "fixed32":
                return String.valueOf(((Number) val).longValue() & 0xFFFFFFFFL);
            case "int64": case "sint64": case "sfixed64":
                return "\"" + ((Number) val).longValue() + "\"";
            case "uint64": case "fixed64":
                return "\"" + Long.toUnsignedString(((Number) val).longValue()) + "\"";
            default: return String.valueOf(val);
        }
    }

    static String encodeArray(List<Object> list, FieldDef fd) {
        StringBuilder sb = new StringBuilder();
        sb.append('[');
        for (int i = 0; i < list.size(); i++) {
            if (i > 0) sb.append(',');
            sb.append(encodeSingle(list.get(i), fd.type));
        }
        sb.append(']');
        return sb.toString();
    }

    static String encodeMap(Map<Object, Object> map, FieldDef fd) {
        if (map == null || map.isEmpty()) return "{}";
        List<Object> keys = new ArrayList<>(map.keySet());
        if (fd.mapKeyType.equals("string")) {
            keys.sort((a, b) -> {
                byte[] ba = ((String)a).getBytes(java.nio.charset.StandardCharsets.UTF_8);
                byte[] bb = ((String)b).getBytes(java.nio.charset.StandardCharsets.UTF_8);
                return cmpBytes(ba, bb);
            });
        } else {
            keys.sort((a, b) -> Integer.compare((Integer)a, (Integer)b));
        }
        StringBuilder sb = new StringBuilder();
        sb.append('{');
        boolean first = true;
        for (Object key : keys) {
            if (!first) sb.append(',');
            first = false;
            if (fd.mapKeyType.equals("string")) {
                sb.append('"').append(escapeJson((String) key)).append('"');
            } else {
                sb.append('"').append(key).append('"');
            }
            sb.append(':');
            sb.append(encodeSingle(map.get(key), fd.mapValueType));
        }
        sb.append('}');
        return sb.toString();
    }

    static int cmpBytes(byte[] a, byte[] b) {
        int min = Math.min(a.length, b.length);
        for (int i = 0; i < min; i++) {
            int d = (a[i] & 0xFF) - (b[i] & 0xFF);
            if (d != 0) return d;
        }
        return a.length - b.length;
    }

    static String escapeJson(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\b': sb.append("\\b"); break;
                case '\t': sb.append("\\t"); break;
                case '\n': sb.append("\\n"); break;
                case '\f': sb.append("\\f"); break;
                case '\r': sb.append("\\r"); break;
                default:
                    if (c < 0x20) sb.append(String.format("\\u%04x", (int)c));
                    else sb.append(c);
            }
        }
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        String schema = new String(Files.readAllBytes(Paths.get(dir, "schema.proto")), java.nio.charset.StandardCharsets.UTF_8);
        byte[] msgData = Files.readAllBytes(Paths.get(dir, "messages.bin"));

        List<Token> tokens = tokenize(schema);
        new Parser(tokens).parseFile();

        BinaryReader reader = new BinaryReader(msgData, 0, msgData.length);
        StringBuilder out = new StringBuilder();
        while (reader.hasMore()) {
            int len = (int) reader.readVarint();
            byte[] rec = Arrays.copyOfRange(msgData, reader.pos, reader.pos + len);
            reader.pos += len;
            DecodedMessage dm = decodeMessage(rec, rootTypeName);
            out.append(toJson(dm, rootTypeName)).append('\n');
        }
        System.out.print(out.toString());
    }
}

#!/usr/bin/env python3
import sys
import os
import struct
import base64

# ─── Tokenizer ───────────────────────────────────────────────────────────────

def remove_comments(text):
    out = []
    i = 0
    n = len(text)
    while i < n:
        if text[i] == '/' and i + 1 < n and text[i+1] == '/':
            while i < n and text[i] != '\n':
                i += 1
        elif text[i] == '/' and i + 1 < n and text[i+1] == '*':
            i += 2
            while i + 1 < n and not (text[i] == '*' and text[i+1] == '/'):
                i += 1
            i += 2
        else:
            out.append(text[i])
            i += 1
    return ''.join(out)

def tokenize(text):
    text = remove_comments(text)
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c in ' \t\r\n':
            i += 1
        elif c == '"':
            j = i + 1
            while j < n and text[j] != '"':
                j += 1
            tokens.append(('STR', text[i+1:j]))
            i = j + 1
        elif c.isalpha() or c == '_':
            j = i
            while j < n and (text[j].isalnum() or text[j] == '_'):
                j += 1
            tokens.append(('ID', text[i:j]))
            i = j
        elif c == '-' and i + 1 < n and text[i+1].isdigit():
            j = i + 1
            while j < n and text[j].isdigit():
                j += 1
            tokens.append(('NUM', int(text[i:j])))
            i = j
        elif c.isdigit():
            j = i
            while j < n and text[j].isdigit():
                j += 1
            tokens.append(('NUM', int(text[i:j])))
            i = j
        elif c in '{}=;<>,[].':
            tokens.append(('P', c))
            i += 1
        else:
            i += 1
    return tokens

# ─── Schema data structures ──────────────────────────────────────────────────

class FieldDef:
    __slots__ = ('name','number','type_name','label','is_map','map_key_type','map_value_type','oneof_name')
    def __init__(self, name, number, type_name, label='singular', is_map=False,
                 map_key_type=None, map_value_type=None, oneof_name=None):
        self.name = name
        self.number = number
        self.type_name = type_name
        self.label = label
        self.is_map = is_map
        self.map_key_type = map_key_type
        self.map_value_type = map_value_type
        self.oneof_name = oneof_name

class MessageDef:
    __slots__ = ('name','fields','fields_by_number','oneof_fields')
    def __init__(self, name):
        self.name = name
        self.fields = []
        self.fields_by_number = {}
        self.oneof_fields = {}  # oneof_name -> [field_numbers]

class EnumDef:
    __slots__ = ('name','values','values_by_number')
    def __init__(self, name):
        self.name = name
        self.values = []
        self.values_by_number = {}

class Schema:
    __slots__ = ('messages','enums','root')
    def __init__(self):
        self.messages = {}
        self.enums = {}
        self.root = None

# ─── Parser ──────────────────────────────────────────────────────────────────

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0
    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return (None, None)
    def advance(self):
        t = self.tokens[self.pos]
        self.pos += 1
        return t
    def expect_id(self, val):
        t = self.advance()
        assert t[0] == 'ID' and t[1] == val, f"Expected {val}, got {t}"
    def expect_p(self, val):
        t = self.advance()
        assert t[0] == 'P' and t[1] == val, f"Expected {val}, got {t}"

SCALAR_TYPES = {'int32','int64','uint32','uint64','sint32','sint64','bool','string','bytes',
                'fixed32','fixed64','sfixed32','sfixed64'}

def parse_schema(text):
    tokens = tokenize(text)
    p = Parser(tokens)
    schema = Schema()
    _parse_top_level(p, schema)
    return schema

def _parse_top_level(p, schema):
    while p.pos < len(p.tokens):
        t = p.peek()
        if t[0] == 'ID' and t[1] == 'syntax':
            _skip_to_semicolon(p)
        elif t[0] == 'ID' and t[1] == 'package':
            _skip_to_semicolon(p)
        elif t[0] == 'ID' and t[1] == 'option':
            _skip_to_semicolon(p)
        elif t[0] == 'ID' and t[1] == 'message':
            _parse_message(p, schema)
        elif t[0] == 'ID' and t[1] == 'enum':
            _parse_enum(p, schema)
        else:
            p.advance()

def _skip_to_semicolon(p):
    while p.pos < len(p.tokens):
        t = p.advance()
        if t[0] == 'P' and t[1] == ';':
            return

def _skip_brackets(p):
    """Skip [...] block"""
    depth = 0
    while p.pos < len(p.tokens):
        t = p.advance()
        if t[0] == 'P' and t[1] == '[':
            depth += 1
        elif t[0] == 'P' and t[1] == ']':
            depth -= 1
            if depth == 0:
                return

def _parse_message(p, schema):
    p.expect_id('message')
    name = p.advance()[1]
    msg = MessageDef(name)
    p.expect_p('{')
    _parse_message_body(p, msg, schema)
    p.expect_p('}')
    schema.messages[name] = msg
    if schema.root is None:
        schema.root = name

def _parse_message_body(p, msg, schema):
    while p.pos < len(p.tokens):
        t = p.peek()
        if t[0] == 'P' and t[1] == '}':
            return
        if t[0] == 'ID':
            if t[1] == 'message':
                _parse_message(p, schema)
            elif t[1] == 'enum':
                _parse_enum(p, schema)
            elif t[1] == 'option':
                _skip_to_semicolon(p)
            elif t[1] == 'reserved':
                _skip_to_semicolon(p)
            elif t[1] == 'oneof':
                _parse_oneof(p, msg, schema)
            elif t[1] == 'map':
                _parse_map_field(p, msg, schema)
            elif t[1] in ('repeated', 'optional'):
                _parse_field(p, msg, schema, label=t[1])
            else:
                _parse_field(p, msg, schema, label='singular')
        else:
            p.advance()

def _parse_field(p, msg, schema, label):
    if label in ('repeated', 'optional'):
        p.advance()
    type_name = p.advance()[1]
    name = p.advance()[1]
    p.expect_p('=')
    number = p.advance()[1]
    if p.peek()[0] == 'P' and p.peek()[1] == '[':
        _skip_brackets(p)
    p.expect_p(';')
    fd = FieldDef(name, number, type_name, label=label)
    msg.fields.append(fd)
    msg.fields_by_number[number] = fd

def _parse_map_field(p, msg, schema):
    p.expect_id('map')
    p.expect_p('<')
    key_type = p.advance()[1]
    p.expect_p(',')
    val_type = p.advance()[1]
    p.expect_p('>')
    name = p.advance()[1]
    p.expect_p('=')
    number = p.advance()[1]
    if p.peek()[0] == 'P' and p.peek()[1] == '[':
        _skip_brackets(p)
    p.expect_p(';')
    fd = FieldDef(name, number, 'map', label='repeated', is_map=True,
                  map_key_type=key_type, map_value_type=val_type)
    msg.fields.append(fd)
    msg.fields_by_number[number] = fd

def _parse_oneof(p, msg, schema):
    p.expect_id('oneof')
    oneof_name = p.advance()[1]
    msg.oneof_fields[oneof_name] = []
    p.expect_p('{')
    while p.pos < len(p.tokens):
        t = p.peek()
        if t[0] == 'P' and t[1] == '}':
            p.advance()
            return
        if t[0] == 'ID' and t[1] == 'option':
            _skip_to_semicolon(p)
        elif t[0] == 'ID' and t[1] == 'map':
            _parse_map_field_oneof(p, msg, schema, oneof_name)
        elif t[0] == 'ID':
            _parse_field_oneof(p, msg, schema, oneof_name)
        else:
            p.advance()

def _parse_field_oneof(p, msg, schema, oneof_name):
    type_name = p.advance()[1]
    name = p.advance()[1]
    p.expect_p('=')
    number = p.advance()[1]
    if p.peek()[0] == 'P' and p.peek()[1] == '[':
        _skip_brackets(p)
    p.expect_p(';')
    fd = FieldDef(name, number, type_name, label='singular', oneof_name=oneof_name)
    msg.fields.append(fd)
    msg.fields_by_number[number] = fd
    msg.oneof_fields[oneof_name].append(number)

def _parse_map_field_oneof(p, msg, schema, oneof_name):
    p.expect_id('map')
    p.expect_p('<')
    key_type = p.advance()[1]
    p.expect_p(',')
    val_type = p.advance()[1]
    p.expect_p('>')
    name = p.advance()[1]
    p.expect_p('=')
    number = p.advance()[1]
    if p.peek()[0] == 'P' and p.peek()[1] == '[':
        _skip_brackets(p)
    p.expect_p(';')
    fd = FieldDef(name, number, 'map', label='singular', is_map=True,
                  map_key_type=key_type, map_value_type=val_type, oneof_name=oneof_name)
    msg.fields.append(fd)
    msg.fields_by_number[number] = fd
    msg.oneof_fields[oneof_name].append(number)

def _parse_enum(p, schema):
    p.expect_id('enum')
    name = p.advance()[1]
    ed = EnumDef(name)
    p.expect_p('{')
    while p.pos < len(p.tokens):
        t = p.peek()
        if t[0] == 'P' and t[1] == '}':
            p.advance()
            break
        if t[0] == 'ID' and t[1] == 'option':
            _skip_to_semicolon(p)
        elif t[0] == 'ID' and t[1] == 'reserved':
            _skip_to_semicolon(p)
        elif t[0] == 'ID':
            vname = p.advance()[1]
            p.expect_p('=')
            vnum = p.advance()[1]
            if p.peek()[0] == 'P' and p.peek()[1] == '[':
                _skip_brackets(p)
            p.expect_p(';')
            ed.values.append((vname, vnum))
            ed.values_by_number[vnum] = vname
        else:
            p.advance()
    schema.enums[name] = ed

# ─── Varint / wire helpers ───────────────────────────────────────────────────

def read_varint(data, offset):
    result = 0
    shift = 0
    while True:
        b = data[offset]
        offset += 1
        result |= (b & 0x7F) << shift
        if (b & 0x80) == 0:
            break
        shift += 7
    return result, offset

def read_varint_bytes(data, offset):
    return read_varint(data, offset)

def skip_value(data, offset, wire_type):
    if wire_type == 0:
        _, offset = read_varint(data, offset)
    elif wire_type == 1:
        offset += 8
    elif wire_type == 2:
        length, offset = read_varint(data, offset)
        offset += length
    elif wire_type == 5:
        offset += 4
    elif wire_type == 3:
        # group start - find matching group end
        offset = skip_group(data, offset)
    elif wire_type == 4:
        pass  # shouldn't be called for end group at top level
    return offset

def skip_group(data, offset):
    while True:
        key, offset = read_varint(data, offset)
        wt = key & 7
        if wt == 4:
            return offset
        offset = skip_value(data, offset, wt)

# ─── Decoding ────────────────────────────────────────────────────────────────

def decode_message(data, msg_def, schema):
    state = {'fields': {}, 'oneof_current': {}}
    offset = 0
    ndata = len(data)
    while offset < ndata:
        key, offset = read_varint(data, offset)
        fnum = key >> 3
        wtype = key & 7
        fdef = msg_def.fields_by_number.get(fnum)
        if fdef is None:
            offset = skip_value(data, offset, wtype)
            continue
        offset = _process_field(data, offset, wtype, fdef, msg_def, state, schema)
    return state

def _process_field(data, offset, wtype, fdef, msg_def, state, schema):
    if fdef.is_map:
        return _decode_map_entry(data, offset, wtype, fdef, state, schema)
    if fdef.label == 'repeated':
        return _decode_repeated(data, offset, wtype, fdef, state, schema)
    if fdef.oneof_name is not None:
        return _decode_oneof_field(data, offset, wtype, fdef, state, schema)
    # singular
    return _decode_singular(data, offset, wtype, fdef, state, schema)

def _decode_repeated(data, offset, wtype, fdef, state, schema):
    fnum = fdef.number
    if fnum not in state['fields']:
        state['fields'][fnum] = {'value': [], 'seen': True}
    entry = state['fields'][fnum]
    if _is_packed_type(fdef) and wtype == 2:
        # packed
        length, offset = read_varint(data, offset)
        end = offset + length
        while offset < end:
            val, offset = _read_scalar(data, offset, fdef, schema)
            entry['value'].append(val)
    else:
        val, offset = _read_single_value(data, offset, wtype, fdef, schema)
        entry['value'].append(val)
    return offset

def _decode_singular(data, offset, wtype, fdef, state, schema):
    fnum = fdef.number
    if fdef.type_name in schema.messages:
        length, offset = read_varint(data, offset)
        sub_data = data[offset:offset+length]
        offset += length
        sub_msg_def = schema.messages[fdef.type_name]
        sub_state = decode_message(sub_data, sub_msg_def, schema)
        if fnum in state['fields']:
            merge_state(state['fields'][fnum]['value'], sub_state, sub_msg_def, schema)
            state['fields'][fnum]['seen'] = True
        else:
            state['fields'][fnum] = {'value': sub_state, 'seen': True}
    else:
        val, offset = _read_single_value(data, offset, wtype, fdef, schema)
        state['fields'][fnum] = {'value': val, 'seen': True}
    return offset

def _decode_oneof_field(data, offset, wtype, fdef, state, schema):
    fnum = fdef.number
    oneof = fdef.oneof_name
    cur = state['oneof_current'].get(oneof)
    if cur != fnum:
        # clear previous
        if cur is not None and cur in state['fields']:
            del state['fields'][cur]
        state['oneof_current'][oneof] = fnum
        # set new
        if fdef.type_name in schema.messages:
            length, offset = read_varint(data, offset)
            sub_data = data[offset:offset+length]
            offset += length
            sub_msg_def = schema.messages[fdef.type_name]
            sub_state = decode_message(sub_data, sub_msg_def, schema)
            state['fields'][fnum] = {'value': sub_state, 'seen': True}
        else:
            val, offset = _read_single_value(data, offset, wtype, fdef, schema)
            state['fields'][fnum] = {'value': val, 'seen': True}
    else:
        # same member
        if fdef.type_name in schema.messages:
            length, offset = read_varint(data, offset)
            sub_data = data[offset:offset+length]
            offset += length
            sub_msg_def = schema.messages[fdef.type_name]
            sub_state = decode_message(sub_data, sub_msg_def, schema)
            merge_state(state['fields'][fnum]['value'], sub_state, sub_msg_def, schema)
        else:
            val, offset = _read_single_value(data, offset, wtype, fdef, schema)
            state['fields'][fnum] = {'value': val, 'seen': True}
    return offset

def _decode_map_entry(data, offset, wtype, fdef, state, schema):
    fnum = fdef.number
    if fnum not in state['fields']:
        state['fields'][fnum] = {'value': {}, 'seen': True}
    # wtype should be 2
    length, offset = read_varint(data, offset)
    end = offset + length
    key = _default_map_key(fdef.map_key_type)
    val = _default_map_value(fdef, schema)
    while offset < end:
        ek, offset = read_varint(data, offset)
        efnum = ek >> 3
        ewt = ek & 7
        if efnum == 1:
            key, offset = _read_map_key(data, offset, ewt, fdef.map_key_type)
        elif efnum == 2:
            val, offset = _read_map_val(data, offset, ewt, fdef.map_value_type, schema)
        else:
            offset = skip_value(data, offset, ewt)
    state['fields'][fnum]['value'][key] = val
    return offset

def _default_map_key(kt):
    return "" if kt == 'string' else 0

def _default_map_value(fdef, schema):
    vt = fdef.map_value_type
    if vt in schema.messages:
        return decode_message(b'', schema.messages[vt], schema)
    if vt == 'string':
        return ""
    if vt == 'bytes':
        return b''
    if vt == 'bool':
        return False
    return 0

def _read_map_key(data, offset, wtype, kt):
    if kt == 'string':
        length, offset = read_varint(data, offset)
        s = data[offset:offset+length].decode('utf-8')
        offset += length
        return s, offset
    else:  # int32
        val, offset = read_varint(data, offset)
        return _to_signed32(val), offset

def _read_map_val(data, offset, wtype, vt, schema):
    if vt in schema.messages:
        length, offset = read_varint(data, offset)
        sub_data = data[offset:offset+length]
        offset += length
        return decode_message(sub_data, schema.messages[vt], schema), offset
    if vt == 'string':
        length, offset = read_varint(data, offset)
        s = data[offset:offset+length].decode('utf-8')
        offset += length
        return s, offset
    if vt == 'bytes':
        length, offset = read_varint(data, offset)
        b = data[offset:offset+length]
        offset += length
        return b, offset
    if vt == 'bool':
        val, offset = read_varint(data, offset)
        return val != 0, offset
    if vt in ('int32','uint32','sint32','fixed32','sfixed32'):
        return _read_scalar_by_type(data, offset, wtype, vt)
    if vt in ('int64','uint64','sint64','fixed64','sfixed64'):
        return _read_scalar_by_type(data, offset, wtype, vt)
    if vt in schema.enums:
        val, offset = read_varint(data, offset)
        return _to_signed32(val), offset
    return 0, offset

def _read_single_value(data, offset, wtype, fdef, schema):
    tn = fdef.type_name
    if tn in schema.messages:
        length, offset = read_varint(data, offset)
        sub_data = data[offset:offset+length]
        offset += length
        return decode_message(sub_data, schema.messages[tn], schema), offset
    if tn == 'string':
        length, offset = read_varint(data, offset)
        s = data[offset:offset+length].decode('utf-8')
        offset += length
        return s, offset
    if tn == 'bytes':
        length, offset = read_varint(data, offset)
        b = data[offset:offset+length]
        offset += length
        return b, offset
    return _read_scalar_by_type(data, offset, wtype, tn)

def _read_scalar(data, offset, fdef, schema):
    tn = fdef.type_name
    if tn == 'bool':
        val, offset = read_varint(data, offset)
        return val != 0, offset
    if tn in schema.enums:
        val, offset = read_varint(data, offset)
        return _to_signed32(val), offset
    return _read_scalar_by_type(data, offset, 0, tn)

def _read_scalar_by_type(data, offset, wtype, tn):
    if tn in ('int32','int64','uint32','uint64','bool'):
        val, offset = read_varint(data, offset)
        if tn in ('int32','uint32'):
            return _to_signed32(val) if tn == 'int32' else val & 0xFFFFFFFF, offset
        if tn in ('int64','uint64'):
            return _to_signed64(val) if tn == 'int64' else val & 0xFFFFFFFFFFFFFFFF, offset
        return val, offset  # bool handled elsewhere
    if tn == 'sint32':
        val, offset = read_varint(data, offset)
        return _zigzag32(val), offset
    if tn == 'sint64':
        val, offset = read_varint(data, offset)
        return _zigzag64(val), offset
    if tn in ('fixed32',):
        val = struct.unpack_from('<I', data, offset)[0]
        return val, offset + 4
    if tn in ('sfixed32',):
        val = struct.unpack_from('<i', data, offset)[0]
        return val, offset + 4
    if tn in ('fixed64',):
        val = struct.unpack_from('<Q', data, offset)[0]
        return val, offset + 8
    if tn in ('sfixed64',):
        val = struct.unpack_from('<q', data, offset)[0]
        return val, offset + 8
    if tn in ('int32',):
        val, offset = read_varint(data, offset)
        return _to_signed32(val), offset
    if tn == 'bool':
        val, offset = read_varint(data, offset)
        return val != 0, offset
    # enum
    val, offset = read_varint(data, offset)
    return _to_signed32(val), offset

def _is_packed_type(fdef):
    tn = fdef.type_name
    if tn in ('int32','int64','uint32','uint64','sint32','sint64','bool',
              'fixed32','fixed64','sfixed32','sfixed64'):
        return True
    if tn in ('int32','int64','uint32','uint64','sint32','sint64'):
        return True
    return False

def _to_signed32(n):
    n = n & 0xFFFFFFFF
    if n >= 0x80000000:
        n -= 0x100000000
    return n

def _to_signed64(n):
    n = n & 0xFFFFFFFFFFFFFFFF
    if n >= 0x8000000000000000:
        n -= 0x10000000000000000
    return n

def _zigzag32(n):
    return (n >> 1) ^ -(n & 1)

def _zigzag64(n):
    return (n >> 1) ^ -(n & 1)

# ─── Merge ───────────────────────────────────────────────────────────────────

def merge_state(target, source, msg_def, schema):
    for fdef in msg_def.fields:
        fnum = fdef.number
        if fnum not in source['fields']:
            continue
        src_entry = source['fields'][fnum]
        if fdef.is_map:
            if fnum in target['fields']:
                target['fields'][fnum]['value'].update(src_entry['value'])
                target['fields'][fnum]['seen'] = True
            else:
                target['fields'][fnum] = {'value': dict(src_entry['value']), 'seen': True}
        elif fdef.label == 'repeated':
            if fnum in target['fields']:
                target['fields'][fnum]['value'].extend(src_entry['value'])
                target['fields'][fnum]['seen'] = True
            else:
                target['fields'][fnum] = {'value': list(src_entry['value']), 'seen': True}
        elif fdef.oneof_name is not None:
            oneof = fdef.oneof_name
            if source['oneof_current'].get(oneof) == fnum:
                # clear target's current member
                cur = target['oneof_current'].get(oneof)
                if cur is not None and cur in target['fields']:
                    del target['fields'][cur]
                target['oneof_current'][oneof] = fnum
                if fdef.type_name in schema.messages:
                    if fnum in target['fields']:
                        sub_md = schema.messages[fdef.type_name]
                        merge_state(target['fields'][fnum]['value'], src_entry['value'], sub_md, schema)
                    else:
                        target['fields'][fnum] = {'value': src_entry['value'], 'seen': True}
                else:
                    target['fields'][fnum] = {'value': src_entry['value'], 'seen': True}
        elif fdef.type_name in schema.messages:
            if fnum in target['fields']:
                sub_md = schema.messages[fdef.type_name]
                merge_state(target['fields'][fnum]['value'], src_entry['value'], sub_md, schema)
                target['fields'][fnum]['seen'] = True
            else:
                target['fields'][fnum] = {'value': src_entry['value'], 'seen': True}
        else:
            target['fields'][fnum] = {'value': src_entry['value'], 'seen': True}

# ─── JSON Output ─────────────────────────────────────────────────────────────

def to_lower_camel(name):
    parts = name.split('_')
    result = parts[0]
    for part in parts[1:]:
        if part and part[0].islower() and part[0].isascii():
            result += part[0].upper() + part[1:]
        else:
            result += part
    return result

def json_str(s):
    out = ['"']
    for ch in s:
        if ch == '"':
            out.append('\\"')
        elif ch == '\\':
            out.append('\\\\')
        elif ch == '\b':
            out.append('\\b')
        elif ch == '\t':
            out.append('\\t')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\f':
            out.append('\\f')
        elif ch == '\r':
            out.append('\\r')
        elif ord(ch) < 0x20:
            out.append('\\u%04x' % ord(ch))
        else:
            out.append(ch)
    out.append('"')
    return ''.join(out)

def encode_json(state, msg_def, schema):
    parts = []
    sorted_fields = sorted(msg_def.fields, key=lambda f: f.number)
    for fdef in sorted_fields:
        fnum = fdef.number
        if fdef.oneof_name is not None:
            if state['oneof_current'].get(fdef.oneof_name) != fnum:
                continue
            if fnum not in state['fields']:
                continue
            entry = state['fields'][fnum]
            jname = to_lower_camel(fdef.name)
            parts.append(json_str(jname) + ':' + _encode_val(entry['value'], fdef, schema))
        elif fdef.label == 'repeated' or fdef.is_map:
            if fnum not in state['fields']:
                continue
            entry = state['fields'][fnum]
            if fdef.is_map:
                if not entry['value']:
                    continue
            else:
                if not entry['value']:
                    continue
            jname = to_lower_camel(fdef.name)
            parts.append(json_str(jname) + ':' + _encode_val(entry['value'], fdef, schema))
        else:
            # singular
            if fnum not in state['fields']:
                continue
            entry = state['fields'][fnum]
            if not entry['seen']:
                continue
            # presence check
            if fdef.type_name in schema.messages:
                pass  # always print if seen
            elif fdef.label == 'optional':
                pass  # always print if seen
            else:
                if _is_default(entry['value'], fdef, schema):
                    continue
            jname = to_lower_camel(fdef.name)
            parts.append(json_str(jname) + ':' + _encode_val(entry['value'], fdef, schema))
    return '{' + ','.join(parts) + '}'

def _is_default(value, fdef, schema):
    tn = fdef.type_name
    if tn in ('int32','int64','uint32','uint64','sint32','sint64','fixed32','fixed64','sfixed32','sfixed64'):
        return value == 0
    if tn == 'bool':
        return value == False
    if tn == 'string':
        return value == ""
    if tn == 'bytes':
        return value == b''
    if tn in schema.enums:
        return value == 0
    return False

def _encode_val(value, fdef, schema):
    if fdef.is_map:
        return _encode_map(value, fdef, schema)
    if fdef.label == 'repeated':
        return '[' + ','.join(_encode_one(e, fdef, schema) for e in value) + ']'
    return _encode_one(value, fdef, schema)

def _encode_one(value, fdef, schema):
    tn = fdef.type_name
    if tn in schema.messages:
        return encode_json(value, schema.messages[tn], schema)
    if tn == 'string':
        return json_str(value)
    if tn == 'bytes':
        return '"' + base64.b64encode(value).decode('ascii') + '"'
    if tn == 'bool':
        return 'true' if value else 'false'
    if tn in ('int32','uint32','sint32','fixed32','sfixed32'):
        return str(value)
    if tn in ('int64','uint64','sint64','fixed64','sfixed64'):
        return '"' + str(value) + '"'
    if tn in schema.enums:
        ed = schema.enums[tn]
        if value in ed.values_by_number:
            return '"' + ed.values_by_number[value] + '"'
        return str(value)
    return str(value)

def _encode_map(m, fdef, schema):
    if not m:
        return '{}'
    kt = fdef.map_key_type
    items = list(m.items())
    if kt == 'int32':
        items.sort(key=lambda x: x[0])
    else:
        items.sort(key=lambda x: x[0].encode('utf-8'))
    val_fdef = FieldDef('v', 0, fdef.map_value_type)
    parts = []
    for k, v in items:
        if kt == 'int32':
            kstr = json_str(str(k))
        else:
            kstr = json_str(k)
        parts.append(kstr + ':' + _encode_one(v, val_fdef, schema))
    return '{' + ','.join(parts) + '}'

# ─── Main ────────────────────────────────────────────────────────────────────

def main():
    dir_path = sys.argv[1]
    schema_path = os.path.join(dir_path, 'schema.proto')
    messages_path = os.path.join(dir_path, 'messages.bin')

    with open(schema_path, 'r', encoding='utf-8') as f:
        schema_text = f.read()

    with open(messages_path, 'rb') as f:
        messages_data = f.read()

    schema = parse_schema(schema_text)

    offset = 0
    while offset < len(messages_data):
        length, offset = read_varint_bytes(messages_data, offset)
        record = messages_data[offset:offset+length]
        offset += length
        root_def = schema.messages[schema.root]
        state = decode_message(record, root_def, schema)
        print(encode_json(state, root_def, schema))

if __name__ == '__main__':
    main()

