// ==================== UTILITIES ====================
static void *xmalloc(size_t n){ void*p=malloc(n); if(!p){perror("malloc");exit(1);} return p; }
static void *xcalloc(size_t n,size_t s){ void*p=calloc(n,s); if(!p){perror("calloc");exit(1);} return p; }
static void *xrealloc(void*p,size_t n){ void*q=realloc(p,n); if(!q){perror("realloc");exit(1);} return q; }

static char *read_file(const char *path, size_t *out_len){
    FILE *f=fopen(path,"rb");
    if(!f){perror(path);exit(1);}
    fseek(f,0,SEEK_END); long sz=ftell(f); fseek(f,0,SEEK_SET);
    char *buf=xmalloc(sz+1);
    fread(buf,1,sz,f); buf[sz]=0; fclose(f);
    *out_len=sz; return buf;
}

// ==================== TOKENIZER ====================
typedef enum { TK_EOF, TK_IDENT, TK_STRING, TK_NUMBER, TK_PUNCT } TokType;
typedef struct { TokType type; char text[1024]; } Token;

static Token *g_toks; static int g_ntoks, g_tpos;

static bool is_ident_char(char c){ return isalnum((unsigned char)c)||c=='_'; }

static void tokenize(const char *src, size_t len){
    int cap=1024, n=0;
    g_toks=xmalloc(cap*sizeof(Token));
    size_t i=0;
    while(i<len){
        // skip whitespace
        if(isspace((unsigned char)src[i])){i++;continue;}
        // comments
        if(i+1<len && src[i]=='/' && src[i+1]=='/'){
            while(i<len && src[i]!='\n') i++;
            continue;
        }
        if(i+1<len && src[i]=='/' && src[i+1]=='*'){
            i+=2;
            while(i+1<len && !(src[i]=='*'&&src[i+1]=='/')) i++;
            if(i+1<len) i+=2;
            continue;
        }
        // string literal
        if(src[i]=='"'){
            if(n>=cap){cap*=2;g_toks=xrealloc(g_toks,cap*sizeof(Token));}
            g_toks[n].type=TK_STRING;
            i++; // skip opening quote
            int j=0;
            while(i<len && src[i]!='"'){
                g_toks[n].text[j++]=src[i++];
            }
            if(i<len) i++; // skip closing quote
            g_toks[n].text[j]=0;
            n++;
            continue;
        }
        // identifier/keyword
        if(isalpha((unsigned char)src[i])||src[i]=='_'){
            if(n>=cap){cap*=2;g_toks=xrealloc(g_toks,cap*sizeof(Token));}
            g_toks[n].type=TK_IDENT;
            int j=0;
            while(i<len && is_ident_char(src[i])){
                g_toks[n].text[j++]=src[i++];
            }
            g_toks[n].text[j]=0;
            n++;
            continue;
        }
        // number (possibly negative handled by parser)
        if(isdigit((unsigned char)src[i])){
            if(n>=cap){cap*=2;g_toks=xrealloc(g_toks,cap*sizeof(Token));}
            g_toks[n].type=TK_NUMBER;
            int j=0;
            while(i<len && (isdigit((unsigned char)src[i])||src[i]=='.'||src[i]=='x'||src[i]=='X'||
                   (src[i]>='a'&&src[i]<='f')||(src[i]>='A'&&src[i]<='F'))){
                g_toks[n].text[j++]=src[i++];
            }
            g_toks[n].text[j]=0;
            n++;
            continue;
        }
        // punctuation
        if(n>=cap){cap*=2;g_toks=xrealloc(g_toks,cap*sizeof(Token));}
        g_toks[n].type=TK_PUNCT;
        g_toks[n].text[0]=src[i]; g_toks[n].text[1]=0;
        i++; n++;
    }
    if(n>=cap){cap++;g_toks=xrealloc(g_toks,cap*sizeof(Token));}
    g_toks[n].type=TK_EOF; g_toks[n].text[0]=0;
    g_ntoks=n; g_tpos=0;
}

static Token *peek(void){ return &g_toks[g_tpos]; }
static Token *advance(void){ return &g_toks[g_tpos++]; }
static bool match_punct(const char *p){
    if(g_toks[g_tpos].type==TK_PUNCT && strcmp(g_toks[g_tpos].text,p)==0){g_tpos++;return true;}
    return false;
}
static void expect_punct(const char *p){
    if(!match_punct(p)){fprintf(stderr,"Expected '%s' got '%s' at token %d\n",p,g_toks[g_tpos].text,g_tpos);exit(1);}
}
static char *expect_ident(void){
    if(g_toks[g_tpos].type==TK_IDENT) return advance()->text;
    fprintf(stderr,"Expected ident got '%s' at token %d\n",g_toks[g_tpos].text,g_tpos);exit(1);
}
static bool is_punct(const char *p){
    return g_toks[g_tpos].type==TK_PUNCT && strcmp(g_toks[g_tpos].text,p)==0;
}
static bool is_ident(const char *s){
    return g_toks[g_tpos].type==TK_IDENT && strcmp(g_toks[g_tpos].text,s)==0;
}

// ==================== SCHEMA ====================
typedef enum {
    FT_INT32,FT_INT64,FT_UINT32,FT_UINT64,FT_SINT32,FT_SINT64,
    FT_BOOL,FT_STRING,FT_BYTES,FT_FIXED32,FT_FIXED64,FT_SFIXED32,FT_SFIXED64,
    FT_MESSAGE,FT_ENUM,FT_MAP
} FieldType;

typedef struct {
    char name[256];
    int number;
    FieldType type;
    int label; // 0=singular,1=repeated,2=optional
    int oneof_idx;
    char type_name[256];
    FieldType map_key_type;
    FieldType map_val_type;
    char map_val_type_name[256];
} SchemaField;

typedef struct { char name[256]; int value; } EnumVal;
typedef struct { char name[256]; EnumVal *vals; int nvals; int cap; } SchemaEnum;
typedef struct {
    char name[256];
    SchemaField *fields; int nfields, cap_fields;
    int noneofs; int cap_oneofs;
    char (*oneof_names)[256];
} SchemaMsg;

static SchemaMsg *g_msgs; static int g_nmsgs, g_cap_msgs;
static SchemaEnum *g_enums; static int g_nenums, g_cap_enums;

static SchemaMsg *find_msg(const char *name){
    for(int i=0;i<g_nmsgs;i++) if(strcmp(g_msgs[i].name,name)==0) return &g_msgs[i];
    return NULL;
}
static SchemaEnum *find_enum(const char *name){
    for(int i=0;i<g_nenums;i++) if(strcmp(g_enums[i].name,name)==0) return &g_enums[i];
    return NULL;
}

static FieldType parse_scalar_type(const char *s){
    if(!strcmp(s,"int32"))return FT_INT32;
    if(!strcmp(s,"int64"))return FT_INT64;
    if(!strcmp(s,"uint32"))return FT_UINT32;
    if(!strcmp(s,"uint64"))return FT_UINT64;
    if(!strcmp(s,"sint32"))return FT_SINT32;
    if(!strcmp(s,"sint64"))return FT_SINT64;
    if(!strcmp(s,"bool"))return FT_BOOL;
    if(!strcmp(s,"string"))return FT_STRING;
    if(!strcmp(s,"bytes"))return FT_BYTES;
    if(!strcmp(s,"fixed32"))return FT_FIXED32;
    if(!strcmp(s,"fixed64"))return FT_FIXED64;
    if(!strcmp(s,"sfixed32"))return FT_SFIXED32;
    if(!strcmp(s,"sfixed64"))return FT_SFIXED64;
    return FT_MESSAGE; // caller resolves
}

static void skip_option(void){
    // 'option' already consumed; skip until ';'
    while(g_toks[g_tpos].type!=TK_EOF){
        if(g_toks[g_tpos].type==TK_PUNCT && g_toks[g_tpos].text[0]==';'){g_tpos++;return;}
        g_tpos++;
    }
}

static void skip_bracket_options(void){
    // skip [ ... ]
    if(!match_punct("[")) return;
    int depth=1;
    while(g_toks[g_tpos].type!=TK_EOF && depth>0){
        if(g_toks[g_tpos].type==TK_PUNCT && g_toks[g_tpos].text[0]=='[') depth++;
        if(g_toks[g_tpos].type==TK_PUNCT && g_toks[g_tpos].text[0]==']') depth--;
        g_tpos++;
    }
}

static void parse_enum(void){
    // 'enum' already consumed
    SchemaEnum *e;
    g_nenums++;
    if(g_nenums>g_cap_enums){g_cap_enums=g_cap_enums?g_cap_enums*2:16;g_enums=xrealloc(g_enums,g_cap_enums*sizeof(SchemaEnum));}
    e=&g_enums[g_nenums-1];
    memset(e,0,sizeof(*e));
    strcpy(e->name,expect_ident());
    expect_punct("{");
    while(!is_punct("}") && g_toks[g_tpos].type!=TK_EOF){
        if(is_ident("option")){g_tpos++;skip_option();continue;}
        if(is_ident("reserved")){g_tpos++;while(!is_punct(";")&&g_toks[g_tpos].type!=TK_EOF)g_tpos++;if(is_punct(";"))g_tpos++;continue;}
        // VALUE = number [options];
        char vname[256]; strcpy(vname,expect_ident());
        expect_punct("=");
        int val=0;
        if(is_punct("-")){g_tpos++;val=-atoi(advance()->text);}
        else val=atoi(advance()->text);
        skip_bracket_options();
        match_punct(";");
        if(e->nvals>=e->cap){e->cap=e->cap?e->cap*2:8;e->vals=xrealloc(e->vals,e->cap*sizeof(EnumVal));}
        strcpy(e->vals[e->nvals].name,vname);
        e->vals[e->nvals].value=val;
        e->nvals++;
    }
    match_punct("}");
}

static void add_field(SchemaMsg *m, SchemaField *f){
    if(m->nfields>=m->cap_fields){m->cap_fields=m->cap_fields?m->cap_fields*2:16;m->fields=xrealloc(m->fields,m->cap_fields*sizeof(SchemaField));}
    m->fields[m->nfields++]=*f;
}

static void parse_message_body(SchemaMsg *m);

static void parse_message(void){
    // 'message' already consumed
    SchemaMsg *m;
    g_nmsgs++;
    if(g_nmsgs>g_cap_msgs){g_cap_msgs=g_cap_msgs?g_cap_msgs*2:16;g_msgs=xrealloc(g_msgs,g_cap_msgs*sizeof(SchemaMsg));}
    m=&g_msgs[g_nmsgs-1];
    memset(m,0,sizeof(*m));
    strcpy(m->name,expect_ident());
    expect_punct("{");
    parse_message_body(m);
    match_punct("}");
}

static void parse_message_body(SchemaMsg *m){
    while(!is_punct("}") && g_toks[g_tpos].type!=TK_EOF){
        if(is_ident("option")){g_tpos++;skip_option();continue;}
        if(is_ident("reserved")){g_tpos++;while(!is_punct(";")&&g_toks[g_tpos].type!=TK_EOF)g_tpos++;if(is_punct(";"))g_tpos++;continue;}
        if(is_ident("message")){g_tpos++;parse_message();continue;}
        if(is_ident("enum")){g_tpos++;parse_enum();continue;}
        if(is_ident("oneof")){
            g_tpos++;
            int oi=m->noneofs;
            if(m->noneofs>=m->cap_oneofs){m->cap_oneofs=m->cap_oneofs?m->cap_oneofs*2:8;m->oneof_names=xrealloc(m->oneof_names,m->cap_oneofs*sizeof(*m->oneof_names));}
            strcpy(m->oneof_names[m->noneofs],expect_ident());
            m->noneofs++;
            expect_punct("{");
            while(!is_punct("}") && g_toks[g_tpos].type!=TK_EOF){
                if(is_ident("option")){g_tpos++;skip_option();continue;}
                if(is_ident("reserved")){g_tpos++;while(!is_punct(";")&&g_toks[g_tpos].type!=TK_EOF)g_tpos++;if(is_punct(";"))g_tpos++;continue;}
                // field in oneof: type name = number [options];
                SchemaField f; memset(&f,0,sizeof(f));
                f.oneof_idx=oi; f.label=0;
                // type
                if(is_ident("map")){
                    g_tpos++;
                    expect_punct("<");
                    char kt[256]; strcpy(kt,expect_ident());
                    expect_punct(",");
                    char vt[256]; strcpy(vt,expect_ident());
                    expect_punct(">");
                    f.type=FT_MAP;
                    f.map_key_type=parse_scalar_type(kt);
                    if(f.map_key_type==FT_MESSAGE){if(find_enum(kt))f.map_key_type=FT_ENUM;else f.map_key_type=FT_MESSAGE;}
                    f.map_val_type=parse_scalar_type(vt);
                    if(f.map_val_type==FT_MESSAGE){
                        if(find_enum(vt))f.map_val_type=FT_ENUM;
                        else{strcpy(f.map_val_type_name,vt);}
                    }
                } else {
                    strcpy(f.type_name,expect_ident());
                    f.type=parse_scalar_type(f.type_name);
                    if(f.type==FT_MESSAGE){
                        if(find_enum(f.type_name))f.type=FT_ENUM;
                    }
                }
                strcpy(f.name,expect_ident());
                expect_punct("=");
                if(is_punct("-")){g_tpos++;f.number=-atoi(advance()->text);}
                else f.number=atoi(advance()->text);
                skip_bracket_options();
                match_punct(";");
                add_field(m,&f);
            }
            match_punct("}");
            continue;
        }
        // regular field
        SchemaField f; memset(&f,0,sizeof(f));
        f.oneof_idx=-1; f.label=0;
        if(is_ident("repeated")){g_tpos++;f.label=1;}
        else if(is_ident("optional")){g_tpos++;f.label=2;}
        // type
        if(is_ident("map")){
            g_tpos++;
            expect_punct("<");
            char kt[256]; strcpy(kt,expect_ident());
            expect_punct(",");
            char vt[256]; strcpy(vt,expect_ident());
            expect_punct(">");
            f.type=FT_MAP;
            f.map_key_type=parse_scalar_type(kt);
            if(f.map_key_type==FT_MESSAGE){if(find_enum(kt))f.map_key_type=FT_ENUM;else f.map_key_type=FT_MESSAGE;}
            f.map_val_type=parse_scalar_type(vt);
            if(f.map_val_type==FT_MESSAGE){
                if(find_enum(vt))f.map_val_type=FT_ENUM;
                else strcpy(f.map_val_type_name,vt);
            }
        } else {
            strcpy(f.type_name,expect_ident());
            f.type=parse_scalar_type(f.type_name);
            if(f.type==FT_MESSAGE){
                if(find_enum(f.type_name))f.type=FT_ENUM;
            }
        }
        strcpy(f.name,expect_ident());
        expect_punct("=");
        if(is_punct("-")){g_tpos++;f.number=-atoi(advance()->text);}
        else f.number=atoi(advance()->text);
        skip_bracket_options();
        match_punct(";");
        add_field(m,&f);
    }
}

static void parse_proto(const char *src, size_t len){
    tokenize(src,len);
    g_tpos=0;
    while(g_toks[g_tpos].type!=TK_EOF){
        if(is_ident("syntax")){g_tpos++;skip_option();continue;}
        if(is_ident("package")){g_tpos++;while(!is_punct(";")&&g_toks[g_tpos].type!=TK_EOF)g_tpos++;if(is_punct(";"))g_tpos++;continue;}
        if(is_ident("option")){g_tpos++;skip_option();continue;}
        if(is_ident("message")){g_tpos++;parse_message();continue;}
        if(is_ident("enum")){g_tpos++;parse_enum();continue;}
        // skip unknown top-level
        g_tpos++;
    }
}

// ==================== BINARY READER ====================
typedef struct { uint8_t *data; size_t len; size_t pos; } Reader;

static uint64_t read_varint(Reader *r){
    uint64_t val=0; int shift=0;
    for(int i=0;i<10;i++){
        if(r->pos>=r->len) return val;
        uint8_t b=r->data[r->pos++];
        val|=(uint64_t)(b&0x7f)<<shift;
        if(!(b&0x80)) break;
        shift+=7;
    }
    return val;
}

static void skip_value(Reader *r, int wt){
    if(wt==0){read_varint(r);}
    else if(wt==1){r->pos+=8;}
    else if(wt==5){r->pos+=4;}
    else if(wt==2){uint64_t l=read_varint(r);r->pos+=l;}
    else if(wt==3){/* group start - handled by caller */}
    else if(wt==4){/* group end - handled by caller */}
}

static void skip_group(Reader *r, int my_field_num){
    while(r->pos<r->len){
        uint64_t key=read_varint(r);
        int fn=(int)(key>>3);
        int wt=(int)(key&7);
        if(wt==4&&fn==my_field_num) return;
        if(wt==3){skip_group(r,fn);}
        else skip_value(r,wt);
    }
}

static uint64_t read_fixed64(Reader *r){
    uint64_t v=0;
    for(int i=0;i<8&&r->pos<r->len;i++) v|=(uint64_t)r->data[r->pos++]<<(i*8);
    return v;
}
static uint32_t read_fixed32(Reader *r){
    uint32_t v=0;
    for(int i=0;i<4&&r->pos<r->len;i++) v|=(uint32_t)r->data[r->pos++]<<(i*8);
    return v;
}

// ==================== DECODED MESSAGE ====================
typedef struct DecMsg DecMsg;

typedef struct {
    FieldType type;
    union {
        int64_t i64;
        uint64_t u64;
        bool b;
        struct { char *data; size_t len; } str;
        DecMsg *msg;
    };
} Val;

typedef struct { Val key; Val val; } MapEntry;

typedef struct {
    bool present;
    Val val;
    Val *arr; int narr, carr;
    MapEntry *entries; int nmap, cmap;
} FieldData;

struct DecMsg {
    SchemaMsg *schema;
    FieldData *fields;
    int *oneof_active;
};

static Val make_val_int(int64_t v){ Val x; memset(&x,0,sizeof(x)); x.type=FT_INT32; x.i64=v; return x; }
static Val make_val_uint(uint64_t v){ Val x; memset(&x,0,sizeof(x)); x.type=FT_UINT32; x.u64=v; return x; }
static Val make_val_bool(bool v){ Val x; memset(&x,0,sizeof(x)); x.type=FT_BOOL; x.b=v; return x; }
static Val make_val_str(const char *d, size_t l){ Val x; memset(&x,0,sizeof(x)); x.type=FT_STRING; x.str.data=(char*)malloc(l); memcpy(x.str.data,d,l); x.str.len=l; return x; }
static Val make_val_bytes(const char *d, size_t l){ Val x; memset(&x,0,sizeof(x)); x.type=FT_BYTES; x.str.data=(char*)malloc(l); memcpy(x.str.data,d,l); x.str.len=l; return x; }
static Val make_val_msg(DecMsg *m){ Val x; memset(&x,0,sizeof(x)); x.type=FT_MESSAGE; x.msg=m; return x; }

static DecMsg *new_decmsg(SchemaMsg *sm){
    DecMsg *dm=xmalloc(sizeof(DecMsg));
    dm->schema=sm;
    dm->fields=xcalloc(sm->nfields,sizeof(FieldData));
    dm->oneof_active=xcalloc(sm->noneofs>0?sm->noneofs:1,sizeof(int));
    for(int i=0;i<sm->noneofs;i++) dm->oneof_active[i]=-1;
    return dm;
}

static void free_val(Val *v){
    if((v->type==FT_STRING||v->type==FT_BYTES)&&v->str.data){free(v->str.data);v->str.data=NULL;}
}

static void free_decmsg(DecMsg *dm){
    if(!dm) return;
    SchemaMsg *sm=dm->schema;
    for(int i=0;i<sm->nfields;i++){
        FieldData *fd=&dm->fields[i];
        if(fd->arr){for(int j=0;j<fd->narr;j++) free_val(&fd->arr[j]); free(fd->arr);}
        if(fd->entries){for(int j=0;j<fd->nmap;j++){free_val(&fd->entries[j].key);free_val(&fd->entries[j].val);} free(fd->entries);}
        if(fd->present) free_val(&fd->val);
    }
    free(dm->fields); free(dm->oneof_active); free(dm);
}

// ==================== DECODER ====================
static SchemaField *find_field(SchemaMsg *sm, int fnum){
    for(int i=0;i<sm->nfields;i++) if(sm->fields[i].number==fnum) return &sm->fields[i];
    return NULL;
}
static int find_field_idx(SchemaMsg *sm, int fnum){
    for(int i=0;i<sm->nfields;i++) if(sm->fields[i].number==fnum) return i;
    return -1;
}

static int64_t zigzag32(uint32_t n){ return (int64_t)((n>>1)^(-(n&1))); }
static int64_t zigzag64(uint64_t n){ return (int64_t)((n>>1)^(-(n&1))); }

static Val decode_scalar(Reader *r, FieldType ft, int wt){
    Val x; memset(&x,0,sizeof(x));
    if(ft==FT_INT32||ft==FT_ENUM){
        uint64_t v=read_varint(r);
        x.type=ft; x.i64=(int64_t)(int32_t)(uint32_t)v;
    } else if(ft==FT_INT64){
        uint64_t v=read_varint(r); x.type=ft; x.i64=(int64_t)v;
    } else if(ft==FT_UINT32){
        uint64_t v=read_varint(r); x.type=ft; x.u64=(uint32_t)v;
    } else if(ft==FT_UINT64){
        uint64_t v=read_varint(r); x.type=ft; x.u64=v;
    } else if(ft==FT_SINT32){
        uint64_t v=read_varint(r); x.type=ft; x.i64=zigzag32((uint32_t)v);
    } else if(ft==FT_SINT64){
        uint64_t v=read_varint(r); x.type=ft; x.i64=zigzag64(v);
    } else if(ft==FT_BOOL){
        uint64_t v=read_varint(r); x.type=ft; x.b=(v!=0);
    } else if(ft==FT_FIXED32){
        uint32_t v=read_fixed32(r); x.type=ft; x.u64=v;
    } else if(ft==FT_SFIXED32){
        uint32_t v=read_fixed32(r); x.type=ft; x.i64=(int64_t)(int32_t)v;
    } else if(ft==FT_FIXED64){
        uint64_t v=read_fixed64(r); x.type=ft; x.u64=v;
    } else if(ft==FT_SFIXED64){
        uint64_t v=read_fixed64(r); x.type=ft; x.i64=(int64_t)v;
    } else if(ft==FT_STRING){
        uint64_t l=read_varint(r);
        x.type=ft; x.str.data=xmalloc(l+1); memcpy(x.str.data,r->data+r->pos,l); x.str.data[l]=0; x.str.len=l; r->pos+=l;
    } else if(ft==FT_BYTES){
        uint64_t l=read_varint(r);
        x.type=ft; x.str.data=xmalloc(l); memcpy(x.str.data,r->data+r->pos,l); x.str.len=l; r->pos+=l;
    }
    return x;
}

static Val decode_packed_elem(Reader *r, FieldType ft){
    // For packed repeated: read one element from the packed buffer
    Val x; memset(&x,0,sizeof(x));
    if(ft==FT_INT32||ft==FT_ENUM){
        uint64_t v=read_varint(r); x.type=ft; x.i64=(int64_t)(int32_t)(uint32_t)v;
    } else if(ft==FT_INT64){
        uint64_t v=read_varint(r); x.type=ft; x.i64=(int64_t)v;
    } else if(ft==FT_UINT32){
        uint64_t v=read_varint(r); x.type=ft; x.u64=(uint32_t)v;
    } else if(ft==FT_UINT64){
        uint64_t v=read_varint(r); x.type=ft; x.u64=v;
    } else if(ft==FT_SINT32){
        uint64_t v=read_varint(r); x.type=ft; x.i64=zigzag32((uint32_t)v);
    } else if(ft==FT_SINT64){
        uint64_t v=read_varint(r); x.type=ft; x.i64=zigzag64(v);
    } else if(ft==FT_BOOL){
        uint64_t v=read_varint(r); x.type=ft; x.b=(v!=0);
    } else if(ft==FT_FIXED32){
        uint32_t v=read_fixed32(r); x.type=ft; x.u64=v;
    } else if(ft==FT_SFIXED32){
        uint32_t v=read_fixed32(r); x.type=ft; x.i64=(int64_t)(int32_t)v;
    } else if(ft==FT_FIXED64){
        uint64_t v=read_fixed64(r); x.type=ft; x.u64=v;
    } else if(ft==FT_SFIXED64){
        uint64_t v=read_fixed64(r); x.type=ft; x.i64=(int64_t)v;
    }
    return x;
}

static bool is_packed_type(FieldType ft){
    switch(ft){
        case FT_INT32:case FT_INT64:case FT_UINT32:case FT_UINT64:
        case FT_SINT32:case FT_SINT64:case FT_BOOL:case FT_FIXED32:
        case FT_FIXED64:case FT_SFIXED32:case FT_SFIXED64:case FT_ENUM:
            return true;
        default: return false;
    }
}

static void merge_decmsg(DecMsg *dst, DecMsg *src);

static DecMsg *decode_message(Reader *r, SchemaMsg *sm);

static void decode_field(Reader *r, DecMsg *dm, SchemaMsg *sm, int fnum, int wt){
    int fi=find_field_idx(sm,fnum);
    if(fi<0){
        // unknown field
        if(wt==3){skip_group(r,fnum);}
        else if(wt==4){/* shouldn't happen at top level */}
        else skip_value(r,wt);
        return;
    }
    SchemaField *sf=&sm->fields[fi];
    FieldData *fd=&dm->fields[fi];

    // Handle oneof
    if(sf->oneof_idx>=0){
        int oi=sf->oneof_idx;
        if(dm->oneof_active[oi]!=fi){
            // clear old member
            if(dm->oneof_active[oi]>=0){
                FieldData *old=&dm->fields[dm->oneof_active[oi]];
                if(old->present){free_val(&old->val);old->present=false;}
                if(old->arr){for(int j=0;j<old->narr;j++)free_val(&old->arr[j]);free(old->arr);old->arr=NULL;old->narr=0;old->carr=0;}
                if(old->entries){for(int j=0;j<old->nmap;j++){free_val(&old->entries[j].key);free_val(&old->entries[j].val);}free(old->entries);old->entries=NULL;old->nmap=0;old->cmap=0;}
            }
            dm->oneof_active[oi]=fi;
            // start fresh
            if(fd->present){free_val(&fd->val);fd->present=false;}
            if(fd->arr){for(int j=0;j<fd->narr;j++)free_val(&fd->arr[j]);free(fd->arr);fd->arr=NULL;fd->narr=0;fd->carr=0;}
            if(fd->entries){for(int j=0;j<fd->nmap;j++){free_val(&fd->entries[j].key);free_val(&fd->entries[j].val);}free(fd->entries);fd->entries=NULL;fd->nmap=0;fd->cmap=0;}
        }
    }

    if(sf->type==FT_MAP){
        // wire type 2, entry is embedded message
        if(wt!=2) return; // shouldn't happen
        uint64_t elen=read_varint(r);
        Reader er={r->data+r->pos,(size_t)elen,0};
        r->pos+=elen;
        // decode entry: field 1 = key, field 2 = value
        Val key; memset(&key,0,sizeof(key));
        Val val; memset(&val,0,sizeof(val));
        bool have_key=false, have_val=false;
        if(sf->map_key_type==FT_STRING){key.type=FT_STRING;key.str.data=(char*)xmalloc(1);key.str.data[0]=0;key.str.len=0;}
        else{key.type=FT_INT32;key.i64=0;}
        if(sf->map_val_type==FT_STRING){val.type=FT_STRING;val.str.data=(char*)xmalloc(1);val.str.data[0]=0;val.str.len=0;}
        else if(sf->map_val_type==FT_BYTES){val.type=FT_BYTES;val.str.data=(char*)xmalloc(1);val.str.data[0]=0;val.str.len=0;}
        else if(sf->map_val_type==FT_MESSAGE){val.type=FT_MESSAGE;val.msg=NULL;}
        else if(sf->map_val_type==FT_ENUM){val.type=FT_ENUM;val.i64=0;}
        else{val.type=sf->map_val_type;val.i64=0;val.u64=0;}

        while(er.pos<er.len){
            uint64_t k=read_varint(&er);
            int efn=(int)(k>>3);
            int ewt=(int)(k&7);
            if(ewt==3){skip_group(&er,efn);continue;}
            if(ewt==4) continue;
            if(efn==1){
                if(sf->map_key_type==FT_STRING){
                    free_val(&key);
                    key=decode_scalar(&er,FT_STRING,ewt);
                } else {
                    key=decode_scalar(&er,FT_INT32,ewt);
                }
                have_key=true;
            } else if(efn==2){
                if(sf->map_val_type==FT_MESSAGE){
                    if(ewt==2){
                        uint64_t ml=read_varint(&er);
                        Reader mr={er.data+er.pos,(size_t)ml,0};
                        er.pos+=ml;
                        SchemaMsg *sm2=find_msg(sf->map_val_type_name);
                        val.msg=sm2?decode_message(&mr,sm2):NULL;
                        val.type=FT_MESSAGE;
                    }
                } else if(sf->map_val_type==FT_STRING){
                    free_val(&val);
                    val=decode_scalar(&er,FT_STRING,ewt);
                } else if(sf->map_val_type==FT_BYTES){
                    free_val(&val);
                    val=decode_scalar(&er,FT_BYTES,ewt);
                } else {
                    val=decode_scalar(&er,sf->map_val_type,ewt);
                }
                have_val=true;
            } else {
                skip_value(&er,ewt);
            }
        }
        (void)have_key;(void)have_val;
        // insert/update in map
        // find existing entry with same key
        for(int i=0;i<fd->nmap;i++){
            bool match=false;
            if(sf->map_key_type==FT_STRING){
                if(fd->entries[i].key.str.len==key.str.len && memcmp(fd->entries[i].key.str.data,key.str.data,key.str.len)==0) match=true;
            } else {
                if(fd->entries[i].key.i64==key.i64) match=true;
            }
            if(match){
                free_val(&fd->entries[i].val);
                fd->entries[i].val=val;
                free_val(&key);
                goto map_done;
            }
        }
        // new entry
        if(fd->nmap>=fd->cmap){fd->cmap=fd->cmap?fd->cmap*2:8;fd->entries=xrealloc(fd->entries,fd->cmap*sizeof(MapEntry));}
        fd->entries[fd->nmap].key=key;
        fd->entries[fd->nmap].val=val;
        fd->nmap++;
        map_done:;
        return;
    }

    if(sf->label==1){ // repeated
        if(is_packed_type(sf->type) && wt==2){
            // packed
            uint64_t plen=read_varint(r);
            Reader pr={r->data+r->pos,(size_t)plen,0};
            r->pos+=plen;
            while(pr.pos<pr.len){
                Val v=decode_packed_elem(&pr,sf->type);
                if(fd->narr>=fd->carr){fd->carr=fd->carr?fd->carr*2:8;fd->arr=xrealloc(fd->arr,fd->carr*sizeof(Val));}
                fd->arr[fd->narr++]=v;
            }
        } else {
            // unpacked single element
            Val v;
            if(sf->type==FT_MESSAGE){
                if(wt!=2) return;
                uint64_t ml=read_varint(r);
                Reader mr={r->data+r->pos,(size_t)ml,0};
                r->pos+=ml;
                SchemaMsg *sm2=find_msg(sf->type_name);
                v=make_val_msg(sm2?decode_message(&mr,sm2):NULL);
            } else {
                v=decode_scalar(r,sf->type,wt);
            }
            if(fd->narr>=fd->carr){fd->carr=fd->carr?fd->carr*2:8;fd->arr=xrealloc(fd->arr,fd->carr*sizeof(Val));}
            fd->arr[fd->narr++]=v;
        }
        return;
    }

    // singular
    if(sf->type==FT_MESSAGE){
        if(wt!=2) return;
        uint64_t ml=read_varint(r);
        Reader mr={r->data+r->pos,(size_t)ml,0};
        r->pos+=ml;
        SchemaMsg *sm2=find_msg(sf->type_name);
        DecMsg *sub=sm2?decode_message(&mr,sm2):NULL;
        if(fd->present && fd->val.msg && sub){
            merge_decmsg(fd->val.msg,sub);
            free_decmsg(sub);
        } else {
            if(fd->present) free_val(&fd->val);
            fd->val=make_val_msg(sub);
            fd->present=true;
        }
    } else {
        Val v=decode_scalar(r,sf->type,wt);
        if(fd->present) free_val(&fd->val);
        fd->val=v;
        fd->present=true;
    }
}

static void merge_decmsg(DecMsg *dst, DecMsg *src){
    SchemaMsg *sm=dst->schema;
    for(int i=0;i<sm->nfields;i++){
        FieldData *sf=&src->fields[i];
        if(!sf->present && sf->narr==0 && sf->nmap==0) continue;
        FieldData *df=&dst->fields[i];
        SchemaField *schema=&sm->fields[i];
        if(schema->type==FT_MAP){
            for(int j=0;j<sf->nmap;j++){
                bool found=false;
                for(int k=0;k<df->nmap;k++){
                    bool match=false;
                    if(schema->map_key_type==FT_STRING){
                        if(df->entries[k].key.str.len==sf->entries[j].key.str.len &&
                           memcmp(df->entries[k].key.str.data,sf->entries[j].key.str.data,sf->entries[j].key.str.len)==0) match=true;
                    } else {
                        if(df->entries[k].key.i64==sf->entries[j].key.i64) match=true;
                    }
                    if(match){
                        free_val(&df->entries[k].val);
                        df->entries[k].val=sf->entries[j].val;
                        found=true;
                        break;
                    }
                }
                if(!found){
                    if(df->nmap>=df->cmap){df->cmap=df->cmap?df->cmap*2:8;df->entries=xrealloc(df->entries,df->cmap*sizeof(MapEntry));}
                    df->entries[df->nmap].key=sf->entries[j].key;
                    df->entries[df->nmap].val=sf->entries[j].val;
                    df->nmap++;
                }
            }
            // don't free src entries since we transferred them
            sf->nmap=0; sf->entries=NULL; sf->cmap=0;
        } else if(schema->label==1){ // repeated
            for(int j=0;j<sf->narr;j++){
                if(df->narr>=df->carr){df->carr=df->carr?df->carr*2:8;df->arr=xrealloc(df->arr,df->carr*sizeof(Val));}
                df->arr[df->narr++]=sf->arr[j];
            }
            free(sf->arr); sf->arr=NULL; sf->narr=0; sf->carr=0;
        } else if(schema->type==FT_MESSAGE){
            if(sf->present && sf->val.msg){
                if(df->present && df->val.msg){
                    merge_decmsg(df->val.msg,sf->val.msg);
                    free_decmsg(sf->val.msg);
                } else {
                    if(df->present) free_val(&df->val);
                    df->val=sf->val;
                    df->present=true;
                }
                sf->present=false;
            }
        } else {
            if(sf->present){
                if(df->present) free_val(&df->val);
                df->val=sf->val;
                df->present=true;
                sf->present=false;
            }
        }
    }
}

static DecMsg *decode_message(Reader *r, SchemaMsg *sm){
    DecMsg *dm=new_decmsg(sm);
    while(r->pos<r->len){
        uint64_t key=read_varint(r);
        int fnum=(int)(key>>3);
        int wt=(int)(key&7);
        if(wt==4) continue; // stray end group, skip
        decode_field(r,dm,sm,fnum,wt);
    }
    return dm;
}

// ==================== JSON OUTPUT ====================
static void print_json_string(const char *s, size_t len){
    putchar('"');
    for(size_t i=0;i<len;i++){
        unsigned char c=(unsigned char)s[i];
        if(c=='"') printf("\\\"");
        else if(c=='\\') printf("\\\\");
        else if(c=='\b') printf("\\b");
        else if(c=='\t') printf("\\t");
        else if(c=='\n') printf("\\n");
        else if(c=='\f') printf("\\f");
        else if(c=='\r') printf("\\r");
        else if(c<0x20) printf("\\u%04x",(int)c);
        else putchar(c);
    }
    putchar('"');
}

static const char b64[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
static void print_base64(const char *data, size_t len){
    putchar('"');
    size_t i=0;
    while(i+2<len){
        uint32_t v=((uint8_t)data[i]<<16)|((uint8_t)data[i+1]<<8)|(uint8_t)data[i+2];
        putchar(b64[(v>>18)&63]);putchar(b64[(v>>12)&63]);putchar(b64[(v>>6)&63]);putchar(b64[v&63]);
        i+=3;
    }
    if(i+1==len){
        uint32_t v=(uint8_t)data[i]<<16;
        putchar(b64[(v>>18)&63]);putchar(b64[(v>>12)&63]);putchar('=');putchar('=');
    } else if(i+2==len){
        uint32_t v=((uint8_t)data[i]<<16)|((uint8_t)data[i+1]<<8);
        putchar(b64[(v>>18)&63]);putchar(b64[(v>>12)&63]);putchar(b64[(v>>6)&63]);putchar('=');
    }
    putchar('"');
}

static void to_camel(const char *src, char *dst){
    int j=0;
    for(int i=0;src[i];i++){
        if(src[i]=='_'){
            if(src[i+1]&&islower((unsigned char)src[i+1])){
                dst[j++]=toupper(src[i+1]);
                i++;
            }
        } else {
            dst[j++]=src[i];
        }
    }
    dst[j]=0;
}

static bool is_default_scalar(FieldType ft, Val *v){
    switch(ft){
        case FT_INT32:case FT_INT64:case FT_SINT32:case FT_SINT64:
        case FT_SFIXED32:case FT_SFIXED64:case FT_ENUM:
            return v->i64==0;
        case FT_UINT32:case FT_UINT64:case FT_FIXED32:case FT_FIXED64:
            return v->u64==0;
        case FT_BOOL: return !v->b;
        case FT_STRING:case FT_BYTES: return v->str.len==0;
        default: return false;
    }
}

static void print_val(FieldType ft, Val *v, const char *type_name);
static void print_msg(DecMsg *dm);

static void print_val(FieldType ft, Val *v, const char *type_name){
    switch(ft){
        case FT_INT32:case FT_SINT32:case FT_SFIXED32:
            printf("%lld",(long long)v->i64);break;
        case FT_INT64:case FT_SINT64:case FT_SFIXED64:
            printf("\"%lld\"",(long long)v->i64);break;
        case FT_UINT32:case FT_FIXED32:
            printf("%llu",(unsigned long long)v->u64);break;
        case FT_UINT64:case FT_FIXED64:
            printf("\"%llu\"",(unsigned long long)v->u64);break;
        case FT_BOOL:
            printf("%s",v->b?"true":"false");break;
        case FT_STRING:
            print_json_string(v->str.data,v->str.len);break;
        case FT_BYTES:
            print_base64(v->str.data,v->str.len);break;
        case FT_ENUM:{
            SchemaEnum *e=find_enum(type_name);
            bool found=false;
            if(e){
                for(int i=0;i<e->nvals;i++){
                    if(e->vals[i].value==(int)v->i64){
                        printf("\"%s\"",e->vals[i].name);
                        found=true;break;
                    }
                }
            }
            if(!found) printf("%lld",(long long)v->i64);
            break;
        }
        case FT_MESSAGE:
            if(v->msg) print_msg(v->msg);
            else printf("{}");
            break;
        default: break;
    }
}

static int cmp_str_keys(const void *a, const void *b){
    const MapEntry *ea=(const MapEntry*)a, *eb=(const MapEntry*)b;
    size_t la=ea->key.str.len, lb=eb->key.str.len;
    size_t ml=la<lb?la:lb;
    int r=memcmp(ea->key.str.data,eb->key.str.data,ml);
    if(r) return r;
    return (int)la-(int)lb;
}
static int cmp_int_keys(const void *a, const void *b){
    const MapEntry *ea=(const MapEntry*)a, *eb=(const MapEntry*)b;
    if(ea->key.i64<eb->key.i64) return -1;
    if(ea->key.i64>eb->key.i64) return 1;
    return 0;
}

static void print_msg(DecMsg *dm){
    SchemaMsg *sm=dm->schema;
    // collect fields to print, sorted by field number
    int *order=xmalloc(sm->nfields*sizeof(int));
    for(int i=0;i<sm->nfields;i++) order[i]=i;
    // sort by field number
    for(int i=0;i<sm->nfields-1;i++)
        for(int j=i+1;j<sm->nfields;j++)
            if(sm->fields[order[j]].number<sm->fields[order[i]].number){int t=order[i];order[i]=order[j];order[j]=t;}

    printf("{");
    bool first=true;
    for(int oi=0;oi<sm->nfields;oi++){
        int fi=order[oi];
        SchemaField *sf=&sm->fields[fi];
        FieldData *fd=&dm->fields[fi];

        bool print_field=false;
        if(sf->type==FT_MAP){
            if(fd->nmap>0) print_field=true;
        } else if(sf->label==1){ // repeated
            if(fd->narr>0) print_field=true;
        } else if(sf->type==FT_MESSAGE){
            if(fd->present) print_field=true;
        } else {
            // singular scalar
            bool in_oneof=(sf->oneof_idx>=0);
            bool is_active_oneof=in_oneof && dm->oneof_active[sf->oneof_idx]==fi;
            if(sf->label==2){ // optional
                if(fd->present) print_field=true;
            } else if(is_active_oneof){
                if(fd->present) print_field=true;
            } else {
                if(fd->present && !is_default_scalar(sf->type,&fd->val)) print_field=true;
            }
        }
        if(!print_field) continue;
        if(!first) putchar(',');
        first=false;
        char cname[256]; to_camel(sf->name,cname);
        print_json_string(cname,strlen(cname));
        putchar(':');

        if(sf->type==FT_MAP){
            printf("{");
            // sort entries
            if(sf->map_key_type==FT_STRING) qsort(fd->entries,fd->nmap,sizeof(MapEntry),cmp_str_keys);
            else qsort(fd->entries,fd->nmap,sizeof(MapEntry),cmp_int_keys);
            for(int i=0;i<fd->nmap;i++){
                if(i) putchar(',');
                // key
                if(sf->map_key_type==FT_STRING){
                    print_json_string(fd->entries[i].key.str.data,fd->entries[i].key.str.len);
                } else {
                    char kb[32]; snprintf(kb,sizeof(kb),"%lld",(long long)fd->entries[i].key.i64);
                    print_json_string(kb,strlen(kb));
                }
                putchar(':');
                // value
                print_val(sf->map_val_type,&fd->entries[i].val,sf->map_val_type_name);
            }
            printf("}");
        } else if(sf->label==1){ // repeated
            printf("[");
            for(int i=0;i<fd->narr;i++){
                if(i) putchar(',');
                print_val(sf->type,&fd->arr[i],sf->type_name);
            }
            printf("]");
        } else {
            print_val(sf->type,&fd->val,sf->type_name);
        }
    }
    printf("}\n");
    free(order);
}

// ==================== MAIN ====================
int main(int argc, char **argv){
    if(argc<2){fprintf(stderr,"Usage: %s <dir>\n",argv[0]);return 1;}
    char spath[4096], bpath[4096];
    snprintf(spath,sizeof(spath),"%s/schema.proto",argv[1]);
    snprintf(bpath,sizeof(bpath),"%s/messages.bin",argv[1]);

    size_t slen, blen;
    char *src=read_file(spath,&slen);
    char *bin=read_file(bpath,&blen);

    parse_proto(src,slen);

    if(g_nmsgs==0){return 0;}
    SchemaMsg *root=&g_msgs[0];

    Reader br={bin,blen,0};
    while(br.pos<br.len){
        uint64_t rlen=read_varint(&br);
        if(br.pos+rlen>br.len) break;
        Reader mr={br.data+br.pos,(size_t)rlen,0};
        br.pos+=rlen;
        DecMsg *dm=decode_message(&mr,root);
        print_msg(dm);
        free_decmsg(dm);
    }
    return 0;
}

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Main {
    static PrintStream out;
    static String json;
    static int pos;

    public static void main(String[] args) throws Exception {
        out = new PrintStream(new FileOutputStream(FileDescriptor.out), true, "UTF-8");
        String dataDir = args[0];
        String baseUrl = args[1];

        byte[] clientBytes = Files.readAllBytes(Paths.get(dataDir, "client.json"));
        String clientJson = new String(clientBytes, StandardCharsets.UTF_8);
        @SuppressWarnings("unchecked")
        Map<String, Object> client = (Map<String, Object>) parseJson(clientJson);
        String clientId = (String) client.get("client_id");
        String clientSecret = (String) client.get("client_secret");
        String scope = (String) client.get("scope");
        int pageSize = ((Number) client.get("page_size")).intValue();

        URI uri = new URI(baseUrl);
        String host = uri.getHost();
        int port = uri.getPort();
        if (port == -1) port = 80;
        String basePath = uri.getPath();

        String token = getToken(host, port, basePath, clientId, clientSecret, scope);
        int reauthCount = 0;
        int pageCount = 0;
        int retryCount = 0;
        int totalOrders = 0;

        Map<String, Map<String, Long>> totals = new HashMap<>();
        Map<String, Integer> statusCounts = new TreeMap<>();

        String cursor = null;
        boolean hasCursor = false;
        boolean freshToken = true;

        while (true) {
            String reqPath;
            if (!hasCursor) {
                reqPath = basePath + "/orders?limit=" + pageSize;
            } else {
                reqPath = basePath + "/orders?limit=" + pageSize + "&cursor=" + percentEncode(cursor);
            }

            Map<String, String> headers = new HashMap<>();
            headers.put("Authorization", "Bearer " + token);

            HttpResponse resp = sendRequest(host, port, "GET", reqPath, headers, null);

            if (resp.status == 429) {
                retryCount++;
                String ra = resp.headers.get("retry-after");
                int wait = (ra != null) ? Integer.parseInt(ra.trim()) : 1;
                Thread.sleep(wait * 1000L);
                continue;
            }
            if (resp.status == 503) {
                retryCount++;
                Thread.sleep(500);
                continue;
            }
            if (resp.status == 401) {
                if (freshToken) {
                    out.println("ERROR " + resp.status + " " + resp.body);
                    out.flush();
                    System.exit(0);
                }
                token = getToken(host, port, basePath, clientId, clientSecret, scope);
                reauthCount++;
                freshToken = true;
                continue;
            }
            if (resp.status != 200) {
                out.println("ERROR " + resp.status + " " + resp.body);
                out.flush();
                System.exit(0);
            }

            pageCount++;
            freshToken = false;

            @SuppressWarnings("unchecked")
            Map<String, Object> page = (Map<String, Object>) parseJson(resp.body);
            @SuppressWarnings("unchecked")
            List<Object> data = (List<Object>) page.get("data");
            if (data != null) {
                for (Object obj : data) {
                    @SuppressWarnings("unchecked")
                    Map<String, Object> order = (Map<String, Object>) obj;
                    totalOrders++;
                    String status = (String) order.get("status");
                    statusCounts.merge(status, 1, Integer::sum);
                    if (!"cancelled".equals(status)) {
                        @SuppressWarnings("unchecked")
                        Map<String, Object> customer = (Map<String, Object>) order.get("customer");
                        String name = (String) customer.get("name");
                        String currency = (String) order.get("currency");
                        String amountStr = (String) order.get("amount");
                        long cents = parseAmount(amountStr);
                        totals.computeIfAbsent(name, k -> new HashMap<>()).merge(currency, cents, Long::sum);
                    }
                }
            }
            Object nextCursor = page.get("next_cursor");
            if (nextCursor == null) break;
            cursor = (String) nextCursor;
            hasCursor = true;
        }

        List<String[]> totalLines = new ArrayList<>();
        for (Map.Entry<String, Map<String, Long>> e : totals.entrySet()) {
            String name = e.getKey();
            for (Map.Entry<String, Long> ce : e.getValue().entrySet()) {
                totalLines.add(new String[]{name, ce.getKey(), formatAmount(ce.getValue())});
            }
        }
        totalLines.sort((a, b) -> {
            int c = compareCodePoints(a[0], b[0]);
            if (c != 0) return c;
            return a[1].compareTo(b[1]);
        });
        for (String[] line : totalLines) {
            out.println("total " + line[1] + " " + line[2] + " " + line[0]);
        }
        for (Map.Entry<String, Integer> e : statusCounts.entrySet()) {
            out.println("status " + e.getKey() + " " + e.getValue());
        }
        out.println("orders " + totalOrders + " pages " + pageCount + " retries " + retryCount + " reauth " + reauthCount);
        out.flush();
    }

    static String getToken(String host, int port, String basePath, String clientId, String clientSecret, String scope) throws Exception {
        String tokenPath = basePath + "/oauth/token";
        String credentials = formEncode(clientId) + ":" + formEncode(clientSecret);
        String b64 = Base64.getEncoder().encodeToString(credentials.getBytes(StandardCharsets.UTF_8));
        String body = "grant_type=client_credentials&scope=" + formEncode(scope);
        byte[] bodyBytes = body.getBytes(StandardCharsets.UTF_8);

        Map<String, String> headers = new LinkedHashMap<>();
        headers.put("Content-Type", "application/x-www-form-urlencoded");
        headers.put("Authorization", "Basic " + b64);
        headers.put("Content-Length", String.valueOf(bodyBytes.length));

        HttpResponse resp = sendRequest(host, port, "POST", tokenPath, headers, body);
        if (resp.status != 200) {
            out.println("ERROR " + resp.status + " " + resp.body);
            out.flush();
            System.exit(0);
        }
        @SuppressWarnings("unchecked")
        Map<String, Object> tokenResp = (Map<String, Object>) parseJson(resp.body);
        return (String) tokenResp.get("access_token");
    }

    static HttpResponse sendRequest(String host, int port, String method, String path,
                                    Map<String, String> headers, String body) throws Exception {
        Socket socket = new Socket();
        socket.connect(new InetSocketAddress(host, port), 30000);
        socket.setSoTimeout(30000);
        try {
            OutputStream os = socket.getOutputStream();
            StringBuilder req = new StringBuilder();
            req.append(method).append(" ").append(path).append(" HTTP/1.1\r\n");
            req.append("Host: ").append(host);
            if (port != 80) req.append(":").append(port);
            req.append("\r\n");
            for (Map.Entry<String, String> h : headers.entrySet()) {
                req.append(h.getKey()).append(": ").append(h.getValue()).append("\r\n");
            }
            req.append("\r\n");
            os.write(req.toString().getBytes(StandardCharsets.UTF_8));
            if (body != null) {
                os.write(body.getBytes(StandardCharsets.UTF_8));
            }
            os.flush();

            InputStream is = new BufferedInputStream(socket.getInputStream());
            String statusLine = readLine(is);
            String[] parts = statusLine.split(" ", 3);
            int status = Integer.parseInt(parts[1]);

            Map<String, String> respHeaders = new HashMap<>();
            String line;
            while ((line = readLine(is)) != null && !line.isEmpty()) {
                int idx = line.indexOf(':');
                if (idx >= 0) {
                    respHeaders.put(line.substring(0, idx).trim().toLowerCase(), line.substring(idx + 1).trim());
                }
            }

            byte[] bodyBytes;
            String te = respHeaders.get("transfer-encoding");
            String cl = respHeaders.get("content-length");
            if (te != null && te.toLowerCase().contains("chunked")) {
                bodyBytes = readChunked(is);
            } else if (cl != null) {
                int len = Integer.parseInt(cl.trim());
                bodyBytes = readBytes(is, len);
            } else {
                bodyBytes = readAllBytes(is);
            }
            String respBody = new String(bodyBytes, StandardCharsets.UTF_8);
            return new HttpResponse(status, respHeaders, respBody);
        } finally {
            socket.close();
        }
    }

    static String readLine(InputStream is) throws IOException {
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        int b;
        while ((b = is.read()) != -1) {
            if (b == '\r') {
                int next = is.read();
                if (next == '\n') break;
                buf.write('\r');
                if (next != -1) buf.write(next);
            } else if (b == '\n') {
                break;
            } else {
                buf.write(b);
            }
        }
        if (buf.size() == 0 && b == -1) return null;
        return buf.toString("ISO-8859-1");
    }

    static byte[] readBytes(InputStream is, int n) throws IOException {
        byte[] buf = new byte[n];
        int off = 0;
        while (off < n) {
            int r = is.read(buf, off, n - off);
            if (r == -1) break;
            off += r;
        }
        return Arrays.copyOf(buf, off);
    }

    static byte[] readAllBytes(InputStream is) throws IOException {
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        byte[] tmp = new byte[4096];
        int r;
        while ((r = is.read(tmp)) != -1) {
            buf.write(tmp, 0, r);
        }
        return buf.toByteArray();
    }

    static byte[] readChunked(InputStream is) throws IOException {
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        while (true) {
            String sizeLine = readLine(is);
            if (sizeLine == null) break;
            int semi = sizeLine.indexOf(';');
            if (semi >= 0) sizeLine = sizeLine.substring(0, semi);
            int chunkSize = Integer.parseInt(sizeLine.trim(), 16);
            if (chunkSize == 0) {
                readLine(is);
                break;
            }
            byte[] chunk = readBytes(is, chunkSize);
            buf.write(chunk);
            readLine(is);
        }
        return buf.toByteArray();
    }

    static Object parseJson(String s) {
        json = s;
        pos = 0;
        return parseValue();
    }

    static Object parseValue() {
        skipWs();
        char c = json.charAt(pos);
        if (c == '{') return parseObject();
        if (c == '[') return parseArray();
        if (c == '"') return parseString();
        if (c == 't' || c == 'f') return parseBool();
        if (c == 'n') return parseNull();
        return parseNumber();
    }

    static void skipWs() {
        while (pos < json.length()) {
            char c = json.charAt(pos);
            if (c == ' ' || c == '\t' || c == '\r' || c == '\n') pos++;
            else break;
        }
    }

    static Map<String, Object> parseObject() {
        Map<String, Object> map = new LinkedHashMap<>();
        pos++;
        skipWs();
        if (json.charAt(pos) == '}') { pos++; return map; }
        while (true) {
            skipWs();
            String key = parseString();
            skipWs();
            pos++; // ':'
            skipWs();
            Object val = parseValue();
            map.put(key, val);
            skipWs();
            char c = json.charAt(pos);
            if (c == ',') { pos++; continue; }
            if (c == '}') { pos++; break; }
        }
        return map;
    }

    static List<Object> parseArray() {
        List<Object> list = new ArrayList<>();
        pos++;
        skipWs();
        if (json.charAt(pos) == ']') { pos++; return list; }
        while (true) {
            skipWs();
            list.add(parseValue());
            skipWs();
            char c = json.charAt(pos);
            if (c == ',') { pos++; continue; }
            if (c == ']') { pos++; break; }
        }
        return list;
    }

    static String parseString() {
        pos++; // skip "
        StringBuilder sb = new StringBuilder();
        while (true) {
            char c = json.charAt(pos);
            if (c == '"') { pos++; break; }
            if (c == '\\') {
                pos++;
                char esc = json.charAt(pos);
                pos++;
                switch (esc) {
                    case '"': sb.append('"'); break;
                    case '\\': sb.append('\\'); break;
                    case '/': sb.append('/'); break;
                    case 'b': sb.append('\b'); break;
                    case 'f': sb.append('\f'); break;
                    case 'n': sb.append('\n'); break;
                    case 'r': sb.append('\r'); break;
                    case 't': sb.append('\t'); break;
                    case 'u':
                        int cp = parseHex4();
                        if (Character.isHighSurrogate((char) cp)) {
                            if (pos + 1 < json.length() && json.charAt(pos) == '\\' && json.charAt(pos + 1) == 'u') {
                                pos += 2;
                                int cp2 = parseHex4();
                                if (Character.isLowSurrogate((char) cp2)) {
                                    sb.appendCodePoint(Character.toCodePoint((char) cp, (char) cp2));
                                } else {
                                    sb.append((char) cp);
                                    sb.append((char) cp2);
                                }
                            } else {
                                sb.append((char) cp);
                            }
                        } else {
                            sb.append((char) cp);
                        }
                        break;
                    default: sb.append(esc);
                }
            } else {
                sb.append(c);
                pos++;
            }
        }
        return sb.toString();
    }

    static int parseHex4() {
        int val = 0;
        for (int i = 0; i < 4; i++) {
            char c = json.charAt(pos++);
            if (c >= '0' && c <= '9') val = val * 16 + (c - '0');
            else if (c >= 'a' && c <= 'f') val = val * 16 + (c - 'a' + 10);
            else if (c >= 'A' && c <= 'F') val = val * 16 + (c - 'A' + 10);
        }
        return val;
    }

    static Object parseBool() {
        if (json.startsWith("true", pos)) { pos += 4; return Boolean.TRUE; }
        pos += 5; return Boolean.FALSE;
    }

    static Object parseNull() {
        pos += 4;
        return null;
    }

    static Object parseNumber() {
        int start = pos;
        if (json.charAt(pos) == '-') pos++;
        while (pos < json.length() && json.charAt(pos) >= '0' && json.charAt(pos) <= '9') pos++;
        boolean isFloat = false;
        if (pos < json.length() && json.charAt(pos) == '.') {
            isFloat = true; pos++;
            while (pos < json.length() && json.charAt(pos) >= '0' && json.charAt(pos) <= '9') pos++;
        }
        if (pos < json.length() && (json.charAt(pos) == 'e' || json.charAt(pos) == 'E')) {
            isFloat = true; pos++;
            if (pos < json.length() && (json.charAt(pos) == '+' || json.charAt(pos) == '-')) pos++;
            while (pos < json.length() && json.charAt(pos) >= '0' && json.charAt(pos) <= '9') pos++;
        }
        String numStr = json.substring(start, pos);
        if (isFloat) return Double.parseDouble(numStr);
        return Long.parseLong(numStr);
    }

    static String formEncode(String s) {
        byte[] bytes = s.getBytes(StandardCharsets.UTF_8);
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            int c = b & 0xFF;
            if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')
                    || c == '-' || c == '.' || c == '_' || c == '*') {
                sb.append((char) c);
            } else if (c == ' ') {
                sb.append('+');
            } else {
                sb.append('%');
                sb.append(String.format("%02X", c));
            }
        }
        return sb.toString();
    }

    static String percentEncode(String s) {
        byte[] bytes = s.getBytes(StandardCharsets.UTF_8);
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            int c = b & 0xFF;
            if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')
                    || c == '-' || c == '.' || c == '_' || c == '~') {
                sb.append((char) c);
            } else {
                sb.append('%');
                sb.append(String.format("%02X", c));
            }
        }
        return sb.toString();
    }

    static long parseAmount(String s) {
        int i = 0;
        boolean neg = false;
        if (s.charAt(i) == '-') { neg = true; i++; }
        long intPart = 0;
        while (i < s.length() && s.charAt(i) >= '0' && s.charAt(i) <= '9') {
            intPart = intPart * 10 + (s.charAt(i) - '0');
            i++;
        }
        long fracPart = 0;
        int fracDigits = 0;
        if (i < s.length() && s.charAt(i) == '.') {
            i++;
            while (i < s.length() && s.charAt(i) >= '0' && s.charAt(i) <= '9') {
                fracPart = fracPart * 10 + (s.charAt(i) - '0');
                fracDigits++;
                i++;
            }
        }
        if (fracDigits == 1) fracPart *= 10;
        long cents = intPart * 100 + fracPart;
        return neg ? -cents : cents;
    }

    static String formatAmount(long cents) {
        if (cents == 0) return "0.00";
        String sign = "";
        long abs = cents;
        if (cents < 0) { sign = "-"; abs = -cents; }
        long intPart = abs / 100;
        long fracPart = abs % 100;
        return sign + intPart + "." + (fracPart < 10 ? "0" : "") + fracPart;
    }

    static int compareCodePoints(String a, String b) {
        int i = 0, j = 0;
        while (i < a.length() && j < b.length()) {
            int cpA = a.codePointAt(i);
            int cpB = b.codePointAt(j);
            if (cpA != cpB) return Integer.compare(cpA, cpB);
            i += Character.charCount(cpA);
            j += Character.charCount(cpB);
        }
        if (i < a.length()) return 1;
        if (j < b.length()) return -1;
        return 0;
    }

    static class HttpResponse {
        int status;
        Map<String, String> headers;
        String body;
        HttpResponse(int status, Map<String, String> headers, String body) {
            this.status = status;
            this.headers = headers;
            this.body = body;
        }
    }
}

import Foundation

// MARK: - Form URL Encoding (RFC 6749 §2.3.1)
func formURLEncode(_ s: String) -> String {
    var result = ""
    for byte in s.utf8 {
        if (byte >= 65 && byte <= 90) ||
           (byte >= 97 && byte <= 122) ||
           (byte >= 48 && byte <= 57) ||
           byte == 45 || byte == 46 || byte == 95 || byte == 42 {
            result.append(Character(UnicodeScalar(byte)))
        } else if byte == 32 {
            result.append("+")
        } else {
            result.append(String(format: "%%%02X", byte))
        }
    }
    return result
}

// MARK: - Percent Encoding for query params
func percentEncode(_ s: String) -> String {
    var result = ""
    for byte in s.utf8 {
        if (byte >= 65 && byte <= 90) ||
           (byte >= 97 && byte <= 122) ||
           (byte >= 48 && byte <= 57) ||
           byte == 45 || byte == 46 || byte == 95 || byte == 126 {
            result.append(Character(UnicodeScalar(byte)))
        } else {
            result.append(String(format: "%%%02X", byte))
        }
    }
    return result
}

// MARK: - HTTP Response
struct HTTPResponse {
    let status: Int
    let headers: [String: String]
    let body: String
}

// MARK: - Chunked Decoding
func decodeChunked(_ raw: String) -> String {
    let bytes = Array(raw.utf8)
    var result = ""
    var pos = 0
    while pos < bytes.count {
        var sizeStr = ""
        while pos < bytes.count && bytes[pos] != 0x0D {
            sizeStr.append(Character(UnicodeScalar(bytes[pos])))
            pos += 1
        }
        if pos < bytes.count && bytes[pos] == 0x0D { pos += 1 }
        if pos < bytes.count && bytes[pos] == 0x0A { pos += 1 }
        guard let chunkSize = Int(sizeStr, radix: 16) else { break }
        if chunkSize == 0 { break }
        let end = pos + chunkSize
        if end <= bytes.count {
            result += String(data: Data(bytes[pos..<end]), encoding: .utf8) ?? ""
        }
        pos = end
        if pos < bytes.count && bytes[pos] == 0x0D { pos += 1 }
        if pos < bytes.count && bytes[pos] == 0x0A { pos += 1 }
    }
    return result
}

// MARK: - HTTP Exchange
func httpExchange(host: String, port: UInt16, method: String, path: String,
                  headers: [(String, String)], body: String?) -> HTTPResponse {
    let sock = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP)
    precondition(sock >= 0, "socket() failed")
    var tv = timeval(tv_sec: 60, tv_usec: 0)
    setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, &tv, socklen_t(MemoryLayout<timeval>.size))
    setsockopt(sock, SOL_SOCKET, SO_SNDTIMEO, &tv, socklen_t(MemoryLayout<timeval>.size))

    var addr = sockaddr_in()
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = in_port_t(port).bigEndian
    inet_pton(AF_INET, host, &addr.sin_addr)

    let cr = withUnsafePointer(to: &addr) {
        $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
            connect(sock, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
    precondition(cr == 0, "connect() failed to \(host):\(port)")

    var req = "\(method) \(path) HTTP/1.1\r\n"
    req += "Host: \(host):\(port)\r\n"
    for (k, v) in headers { req += "\(k): \(v)\r\n" }
    if let b = body {
        req += "Content-Length: \(Data(b.utf8).count)\r\n"
    }
    req += "\r\n"
    if let b = body { req += b }

    let reqData = Data(req.utf8)
    reqData.withUnsafeBytes { ptr in
        var sent = 0
        while sent < reqData.count {
            let n = send(sock, ptr.baseAddress!.advanced(by: sent), reqData.count - sent, 0)
            if n <= 0 { break }
            sent += n
        }
    }

    var buf = Data()
    var tmp = [UInt8](repeating: 0, count: 65536)
    while true {
        let n = recv(sock, &tmp, tmp.count, 0)
        if n <= 0 { break }
        buf.append(contentsOf: tmp[0..<n])
    }
    close(sock)

    guard let respStr = String(data: buf, encoding: .utf8) else {
        return HTTPResponse(status: 0, headers: [:], body: "")
    }
    guard let hdrEnd = respStr.range(of: "\r\n\r\n") else {
        return HTTPResponse(status: 0, headers: [:], body: "")
    }
    let hdrSection = String(respStr[respStr.startIndex..<hdrEnd.lowerBound])
    var bodySection = String(respStr[hdrEnd.upperBound...])

    let lines = hdrSection.components(separatedBy: "\r\n")
    var status = 0
    if let sl = lines.first {
        let parts = sl.components(separatedBy: " ")
        if parts.count >= 2 { status = Int(parts[1]) ?? 0 }
    }
    var hdrs: [String: String] = [:]
    for i in 1..<lines.count {
        if let ci = lines[i].firstIndex(of: ":") {
            let k = String(lines[i][lines[i].startIndex..<ci]).lowercased()
            let v = String(lines[i][lines[i].index(after: ci)...]).trimmingCharacters(in: .whitespaces)
            hdrs[k] = v
        }
    }
    if let te = hdrs["transfer-encoding"], te.lowercased().contains("chunked") {
        bodySection = decodeChunked(bodySection)
    }
    return HTTPResponse(status: status, headers: hdrs, body: bodySection)
}

// MARK: - Amount Parsing (exact cents)
func parseAmount(_ s: String) -> Int64 {
    var idx = s.startIndex
    var negative = false
    if s[idx] == "-" { negative = true; idx = s.index(after: idx) }
    var intPart = ""
    while idx < s.endIndex && s[idx] != "." {
        intPart.append(s[idx])
        idx = s.index(after: idx)
    }
    var fracPart = ""
    if idx < s.endIndex && s[idx] == "." {
        idx = s.index(after: idx)
        while idx < s.endIndex {
            fracPart.append(s[idx])
            idx = s.index(after: idx)
        }
    }
    while fracPart.count < 2 { fracPart.append("0") }
    if fracPart.count > 2 { fracPart = String(fracPart.prefix(2)) }
    let cents = (Int64(intPart) ?? 0) * 100 + (Int64(fracPart) ?? 0)
    return negative ? -cents : cents
}

func formatCents(_ cents: Int64) -> String {
    let neg = cents < 0
    let absC = neg ? -cents : cents
    let whole = absC / 100
    let frac = absC % 100
    let sign = neg ? "-" : ""
    return "\(sign)\(whole).\(String(format: "%02lld", frac))"
}

// MARK: - UTF-8 byte comparison
func utf8Less(_ a: String, _ b: String) -> Bool {
    let ab = Array(a.utf8)
    let bb = Array(b.utf8)
    let n = min(ab.count, bb.count)
    for i in 0..<n {
        if ab[i] != bb[i] { return ab[i] < bb[i] }
    }
    return ab.count < bb.count
}

// MARK: - Fatal error
func fatal(_ status: Int, _ body: String) -> Never {
    print("ERROR \(status) \(body)")
    exit(0)
}

// MARK: - Main
let args = CommandLine.arguments
guard args.count >= 3 else { fatalError("usage: main <data_dir> <base_url>") }
let dataDir = args[1]
let baseUrl = args[2]

// Read client.json
let clientPath = dataDir + "/client.json"
let clientData = try! Data(contentsOf: URL(fileURLWithPath: clientPath))
let clientJson = try! JSONSerialization.jsonObject(with: clientData) as! [String: Any]
let clientId = clientJson["client_id"] as! String
let clientSecret = clientJson["client_secret"] as! String
let scope = clientJson["scope"] as! String
let pageSize = (clientJson["page_size"] as! NSNumber).intValue

// Parse base URL: http://host:port/path
var remaining = baseUrl
if remaining.hasPrefix("http://") { remaining = String(remaining.dropFirst(7)) }
guard let slashPos = remaining.firstIndex(of: "/") else { fatalError("bad url") }
let hostPort = String(remaining[remaining.startIndex..<slashPos])
let pathPrefix = String(remaining[slashPos...])
guard let colonPos = hostPort.lastIndex(of: ":") else { fatalError("bad host:port") }
let host = String(hostPort[hostPort.startIndex..<colonPos])
let port = UInt16(hostPort[hostPort.index(after: colonPos)...])!

// MARK: Get Token
func getToken() -> String {
    let encId = formURLEncode(clientId)
    let encSecret = formURLEncode(clientSecret)
    let credentials = encId + ":" + encSecret
    let b64 = Data(credentials.utf8).base64EncodedString()
    let tokenBody = "grant_type=client_credentials&scope=" + formURLEncode(scope)
    let resp = httpExchange(host: host, port: port, method: "POST",
                            path: pathPrefix + "/oauth/token",
                            headers: [("Content-Type", "application/x-www-form-urlencoded"),
                                      ("Authorization", "Basic " + b64)],
                            body: tokenBody)
    if resp.status != 200 { fatal(resp.status, resp.body) }
    let json = try! JSONSerialization.jsonObject(with: Data(resp.body.utf8)) as! [String: Any]
    return json["access_token"] as! String
}

// MARK: Fetch Pages
var accessToken = getToken()
var firstReqWithToken = true
var totalPages = 0
var totalRetries = 0
var totalReauths = 0
var allOrders: [[String: Any]] = []

var cursor: String? = nil

while true {
    var query = "?limit=\(pageSize)"
    if let c = cursor {
        query += "&cursor=" + percentEncode(c)
    }
    let path = pathPrefix + "/orders" + query

    while true {
        let resp = httpExchange(host: host, port: port, method: "GET", path: path,
                                headers: [("Authorization", "Bearer " + accessToken)],
                                body: nil)
        if resp.status == 429 {
            totalRetries += 1
            let ra = Int(resp.headers["retry-after"] ?? "1") ?? 1
            Thread.sleep(forTimeInterval: Double(ra))
            continue
        }
        if resp.status == 503 {
            totalRetries += 1
            Thread.sleep(forTimeInterval: 0.5)
            continue
        }
        if resp.status == 401 {
            if firstReqWithToken {
                fatal(resp.status, resp.body)
            }
            totalReauths += 1
            accessToken = getToken()
            firstReqWithToken = true
            continue
        }
        if resp.status != 200 {
            fatal(resp.status, resp.body)
        }
        // 200
        firstReqWithToken = false
        totalPages += 1
        let json = try! JSONSerialization.jsonObject(with: Data(resp.body.utf8)) as! [String: Any]
        if let dataArr = json["data"] as? [Any] {
            for item in dataArr {
                if let order = item as? [String: Any] {
                    allOrders.append(order)
                }
            }
        }
        if let nc = json["next_cursor"], !(nc is NSNull) {
            cursor = nc as? String
        } else {
            cursor = nil
        }
        break
    }
    if cursor == nil { break }
}

// MARK: Aggregate
var totals: [(name: String, currency: String, cents: Int64)] = []
var statusCounts: [String: Int] = [:]

for order in allOrders {
    let status = (order["status"] as? String) ?? ""
    statusCounts[status, default: 0] += 1

    if status != "cancelled" {
        let customer = order["customer"] as? [String: Any]
        let name = (customer?["name"] as? String) ?? ""
        let currency = (order["currency"] as? String) ?? ""
        let amountStr = (order["amount"] as? String) ?? "0"
        let cents = parseAmount(amountStr)

        var found = false
        for i in 0..<totals.count {
            if totals[i].name == name && totals[i].currency == currency {
                totals[i].cents += cents
                found = true
                break
            }
        }
        if !found {
            totals.append((name: name, currency: currency, cents: cents))
        }
    }
}

// Sort totals by name (UTF-8 bytes), then currency
totals.sort { a, b in
    if utf8Less(a.name, b.name) { return true }
    if utf8Less(b.name, a.name) { return false }
    return utf8Less(a.currency, b.currency)
}

// Print totals
for t in totals {
    print("total \(t.currency) \(formatCents(t.cents)) \(t.name)")
}

// Print statuses sorted
let sortedStatuses = statusCounts.keys.sorted()
for s in sortedStatuses {
    print("status \(s) \(statusCounts[s]!)")
}

// Print summary
print("orders \(allOrders.count) pages \(totalPages) retries \(totalRetries) reauth \(totalReauths)")

exit(0)

import * as http from 'http';
import * as fs from 'fs';
import * as path from 'path';

interface ClientConfig {
  client_id: string;
  client_secret: string;
  scope: string;
  page_size: number;
}

interface HttpResponse {
  status: number;
  headers: http.IncomingHttpHeaders;
  body: string;
}

function formUrlEncode(s: string): string {
  const bytes = Buffer.from(s, 'utf-8');
  let result = '';
  for (const b of bytes) {
    if ((b >= 65 && b <= 90) || (b >= 97 && b <= 122) || (b >= 48 && b <= 57) ||
        b === 45 || b === 46 || b === 95 || b === 42) {
      result += String.fromCharCode(b);
    } else if (b === 32) {
      result += '+';
    } else {
      result += '%' + b.toString(16).toUpperCase().padStart(2, '0');
    }
  }
  return result;
}

function percentEncode(s: string): string {
  const bytes = Buffer.from(s, 'utf-8');
  let result = '';
  for (const b of bytes) {
    if ((b >= 65 && b <= 90) || (b >= 97 && b <= 122) || (b >= 48 && b <= 57) ||
        b === 45 || b === 46 || b === 95 || b === 126) {
      result += String.fromCharCode(b);
    } else {
      result += '%' + b.toString(16).toUpperCase().padStart(2, '0');
    }
  }
  return result;
}

function sleep(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function makeRequest(
  method: string,
  hostname: string,
  port: number,
  reqPath: string,
  headers: Record<string, string>,
  body?: string
): Promise<HttpResponse> {
  return new Promise((resolve, reject) => {
    const allHeaders: Record<string, string> = { ...headers, 'Host': `${hostname}:${port}` };
    if (body !== undefined) {
      allHeaders['Content-Length'] = Buffer.byteLength(body, 'utf-8').toString();
    }
    const req = http.request({
      method,
      hostname,
      port,
      path: reqPath,
      headers: allHeaders,
      httpVersion: '1.1',
    }, (res) => {
      const chunks: Buffer[] = [];
      res.on('data', (chunk: Buffer) => chunks.push(chunk));
      res.on('end', () => {
        resolve({
          status: res.statusCode!,
          headers: res.headers,
          body: Buffer.concat(chunks).toString('utf-8'),
        });
      });
      res.on('error', reject);
    });
    req.on('error', reject);
    if (body !== undefined) req.write(body);
    req.end();
  });
}

function parseCents(s: string): bigint {
  let negative = false;
  if (s[0] === '-') {
    negative = true;
    s = s.slice(1);
  }
  const dotIdx = s.indexOf('.');
  let intPart: string, fracPart: string;
  if (dotIdx === -1) {
    intPart = s;
    fracPart = '00';
  } else {
    intPart = s.slice(0, dotIdx);
    fracPart = s.slice(dotIdx + 1);
    if (fracPart.length === 1) fracPart += '0';
  }
  const cents = BigInt(intPart) * 100n + BigInt(fracPart);
  return negative ? -cents : cents;
}

function formatCents(cents: bigint): string {
  const negative = cents < 0n;
  const abs = negative ? -cents : cents;
  const intPart = abs / 100n;
  const fracPart = abs % 100n;
  const fracStr = fracPart.toString().padStart(2, '0');
  return (negative ? '-' : '') + intPart.toString() + '.' + fracStr;
}

async function main() {
  const args = process.argv.slice(2);
  const dataDir = args[0];
  const baseUrl = args[1];

  const clientConfig: ClientConfig = JSON.parse(
    fs.readFileSync(path.join(dataDir, 'client.json'), 'utf-8')
  );

  const url = new URL(baseUrl);
  const hostname = url.hostname;
  const port = url.port ? parseInt(url.port) : 80;
  const basePath = url.pathname;

  let totalPages = 0;
  let totalRetries = 0;
  let totalReauth = 0;
  let totalOrders = 0;

  function buildAuthHeader(): string {
    const encodedId = formUrlEncode(clientConfig.client_id);
    const encodedSecret = formUrlEncode(clientConfig.client_secret);
    const combined = encodedId + ':' + encodedSecret;
    return 'Basic ' + Buffer.from(combined, 'ascii').toString('base64');
  }

  async function getToken(): Promise<string> {
    const tokenPath = basePath + '/oauth/token';
    const body = 'grant_type=client_credentials&scope=' + formUrlEncode(clientConfig.scope);
    const res = await makeRequest('POST', hostname, port, tokenPath, {
      'Content-Type': 'application/x-www-form-urlencoded',
      'Authorization': buildAuthHeader(),
    }, body);
    if (res.status !== 200) {
      process.stdout.write(`ERROR ${res.status} ${res.body}\n`);
      process.exit(0);
    }
    const data = JSON.parse(res.body);
    return data.access_token;
  }

  let accessToken = await getToken();
  let tokenUsed = false;

  const totals = new Map<string, bigint>();
  const statusCounts = new Map<string, number>();
  let cursor: string | null = null;
  let firstPage = true;

  while (true) {
    let reqPath = basePath + '/orders?limit=' + clientConfig.page_size;
    if (!firstPage && cursor !== null) {
      reqPath += '&cursor=' + percentEncode(cursor);
    }

    const res = await makeRequest('GET', hostname, port, reqPath, {
      'Authorization': 'Bearer ' + accessToken,
    });

    if (res.status === 429) {
      totalRetries++;
      const retryAfter = parseInt((res.headers['retry-after'] as string) || '1', 10);
      await sleep(retryAfter * 1000);
      continue;
    }

    if (res.status === 503) {
      totalRetries++;
      await sleep(100);
      continue;
    }

    if (res.status === 401) {
      if (!tokenUsed) {
        process.stdout.write(`ERROR ${res.status} ${res.body}\n`);
        process.exit(0);
      }
      totalReauth++;
      accessToken = await getToken();
      tokenUsed = false;
      continue;
    }

    if (res.status !== 200) {
      process.stdout.write(`ERROR ${res.status} ${res.body}\n`);
      process.exit(0);
    }

    tokenUsed = true;
    totalPages++;
    const pageData = JSON.parse(res.body);
    const orders: any[] = pageData.data || [];
    totalOrders += orders.length;

    for (const order of orders) {
      const status: string = order.status;
      statusCounts.set(status, (statusCounts.get(status) || 0) + 1);
      if (status !== 'cancelled') {
        const name: string = order.customer.name;
        const currency: string = order.currency;
        const key = name + '\x00' + currency;
        const cents = parseCents(order.amount);
        totals.set(key, (totals.get(key) || 0n) + cents);
      }
    }

    cursor = pageData.next_cursor;
    firstPage = false;
    if (cursor === null) {
      break;
    }
  }

  // Build output lines for totals
  const totalEntries: { name: string; currency: string; cents: bigint }[] = [];
  for (const [key, cents] of totals) {
    const sepIdx = key.indexOf('\x00');
    const name = key.slice(0, sepIdx);
    const currency = key.slice(sepIdx + 1);
    totalEntries.push({ name, currency, cents });
  }
  totalEntries.sort((a, b) => {
    const cmp = Buffer.compare(Buffer.from(a.name, 'utf-8'), Buffer.from(b.name, 'utf-8'));
    if (cmp !== 0) return cmp;
    return Buffer.compare(Buffer.from(a.currency, 'utf-8'), Buffer.from(b.currency, 'utf-8'));
  });

  for (const entry of totalEntries) {
    process.stdout.write(`total ${entry.currency} ${formatCents(entry.cents)} ${entry.name}\n`);
  }

  const sortedStatuses = [...statusCounts.entries()].sort((a, b) =>
    a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
  );
  for (const [status, count] of sortedStatuses) {
    process.stdout.write(`status ${status} ${count}\n`);
  }

  process.stdout.write(
    `orders ${totalOrders} pages ${totalPages} retries ${totalRetries} reauth ${totalReauth}\n`
  );
}

main().catch((err) => {
  process.stderr.write(String(err) + '\n');
  process.exit(1);
});

use std::collections::BTreeMap;
use std::env;
use std::fs;
use std::io::Read;
use std::net::TcpStream;
use std::process;
use std::thread;
use std::time::Duration;

// ============ JSON ============

#[derive(Debug, Clone)]
enum Json {
    Object(Vec<(String, Json)>),
    Array(Vec<Json>),
    Str(String),
    Num(f64),
    Bool(bool),
    Null,
}

impl Json {
    fn get(&self, key: &str) -> Option<&Json> {
        if let Json::Object(ref pairs) = self {
            for (k, v) in pairs {
                if k == key { return Some(v); }
            }
        }
        None
    }
    fn as_str(&self) -> Option<&str> {
        if let Json::Str(ref s) = self { Some(s) } else { None }
    }
    fn as_array(&self) -> Option<&[Json]> {
        if let Json::Array(ref a) = self { Some(a) } else { None }
    }
    fn is_null(&self) -> bool { matches!(self, Json::Null) }
}

struct JP<'a> { s: &'a [u8], p: usize }

impl<'a> JP<'a> {
    fn new(s: &'a str) -> Self { JP { s: s.as_bytes(), p: 0 } }
    fn ws(&mut self) { while self.p < self.s.len() && matches!(self.s[self.p], b' '|b'\t'|b'\n'|b'\r') { self.p += 1; } }
    fn peek(&self) -> Option<u8> { if self.p < self.s.len() { Some(self.s[self.p]) } else { None } }
    fn eat(&mut self, c: u8) { assert!(self.p < self.s.len() && self.s[self.p] == c); self.p += 1; }
    fn parse(&mut self) -> Json {
        self.ws();
        match self.peek() {
            Some(b'{') => self.obj(),
            Some(b'[') => self.arr(),
            Some(b'"') => Json::Str(self.string()),
            Some(b't') => { assert!(&self.s[self.p..self.p+4]==b"true"); self.p+=4; Json::Bool(true) }
            Some(b'f') => { assert!(&self.s[self.p..self.p+5]==b"false"); self.p+=5; Json::Bool(false) }
            Some(b'n') => { assert!(&self.s[self.p..self.p+4]==b"null"); self.p+=4; Json::Null }
            _ => self.num(),
        }
    }
    fn obj(&mut self) -> Json {
        self.eat(b'{');
        let mut pairs = Vec::new();
        self.ws();
        if self.peek()==Some(b'}') { self.p+=1; return Json::Object(pairs); }
        loop {
            self.ws();
            let k = self.string();
            self.ws(); self.eat(b':'); self.ws();
            let v = self.parse();
            pairs.push((k,v));
            self.ws();
            if self.peek()==Some(b',') { self.p+=1; } else { break; }
        }
        self.eat(b'}');
        Json::Object(pairs)
    }
    fn arr(&mut self) -> Json {
        self.eat(b'[');
        let mut items = Vec::new();
        self.ws();
        if self.peek()==Some(b']') { self.p+=1; return Json::Array(items); }
        loop {
            self.ws();
            items.push(self.parse());
            self.ws();
            if self.peek()==Some(b',') { self.p+=1; } else { break; }
        }
        self.eat(b']');
        Json::Array(items)
    }
    fn string(&mut self) -> String {
        self.eat(b'"');
        let mut r = Vec::new();
        loop {
            let c = self.s[self.p]; self.p += 1;
            if c == b'"' { break; }
            if c == b'\\' {
                let c2 = self.s[self.p]; self.p += 1;
                match c2 {
                    b'"' => r.push(b'"'),
                    b'\\' => r.push(b'\\'),
                    b'/' => r.push(b'/'),
                    b'b' => r.push(8),
                    b'f' => r.push(12),
                    b'n' => r.push(b'\n'),
                    b'r' => r.push(b'\r'),
                    b't' => r.push(b'\t'),
                    b'u' => {
                        let cp = self.hex4();
                        if cp >= 0xD800 && cp <= 0xDBFF {
                            assert!(self.s[self.p]==b'\\' && self.s[self.p+1]==b'u');
                            self.p += 2;
                            let lo = self.hex4();
                            let code = 0x10000u32 + ((cp-0xD800)<<10) + (lo-0xDC00);
                            let ch = char::from_u32(code).unwrap();
                            let mut buf = [0u8;4];
                            r.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                        } else {
                            let ch = char::from_u32(cp).unwrap();
                            let mut buf = [0u8;4];
                            r.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                        }
                    }
                    _ => panic!("bad esc"),
                }
            } else {
                r.push(c);
            }
        }
        String::from_utf8(r).unwrap()
    }
    fn hex4(&mut self) -> u32 {
        let h = &self.s[self.p..self.p+4]; self.p += 4;
        let mut v = 0u32;
        for &b in h { v <<= 4; v |= match b {
            b'0'..=b'9' => (b-b'0') as u32,
            b'a'..=b'f' => (b-b'a'+10) as u32,
            b'A'..=b'F' => (b-b'A'+10) as u32,
            _ => panic!("hex"),
        }; }
        v
    }
    fn num(&mut self) -> Json {
        let st = self.p;
        if self.peek()==Some(b'-') { self.p+=1; }
        while self.p<self.s.len() && self.s[self.p].is_ascii_digit() { self.p+=1; }
        if self.p<self.s.len() && self.s[self.p]==b'.' { self.p+=1; while self.p<self.s.len() && self.s[self.p].is_ascii_digit() { self.p+=1; } }
        if self.p<self.s.len() && (self.s[self.p]==b'e'||self.s[self.p]==b'E') { self.p+=1; if self.p<self.s.len() && (self.s[self.p]==b'+'||self.s[self.p]==b'-') { self.p+=1; } while self.p<self.s.len() && self.s[self.p].is_ascii_digit() { self.p+=1; } }
        Json::Num(std::str::from_utf8(&self.s[st..self.p]).unwrap().parse().unwrap())
    }
}

fn parse_json(s: &str) -> Json { JP::new(s).parse() }

// ============ Base64 ============

fn b64_encode(data: &[u8]) -> String {
    const T: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut r = String::new();
    let mut i = 0;
    while i + 2 < data.len() {
        let n = ((data[i] as u32) << 16) | ((data[i+1] as u32) << 8) | (data[i+2] as u32);
        r.push(T[((n>>18)&63) as usize] as char);
        r.push(T[((n>>12)&63) as usize] as char);
        r.push(T[((n>>6)&63) as usize] as char);
        r.push(T[(n&63) as usize] as char);
        i += 3;
    }
    if i < data.len() {
        let n = ((data[i] as u32) << 16) | if i+1<data.len() { (data[i+1] as u32)<<8 } else { 0 };
        r.push(T[((n>>18)&63) as usize] as char);
        r.push(T[((n>>12)&63) as usize] as char);
        if i+1 < data.len() {
            r.push(T[((n>>6)&63) as usize] as char);
            r.push('=');
        } else {
            r.push('=');
            r.push('=');
        }
    }
    r
}

// ============ Encoding ============

fn form_encode(s: &str) -> String {
    let mut r = String::new();
    for &b in s.as_bytes() {
        if b.is_ascii_alphanumeric() || b==b'-' || b==b'.' || b==b'_' || b==b'*' {
            r.push(b as char);
        } else if b == b' ' {
            r.push('+');
        } else {
            r.push_str(&format!("%{:02X}", b));
        }
    }
    r
}

fn query_encode(s: &str) -> String {
    let mut r = String::new();
    for &b in s.as_bytes() {
        if b.is_ascii_alphanumeric() || b==b'-' || b==b'_' || b==b'.' || b==b'~' {
            r.push(b as char);
        } else {
            r.push_str(&format!("%{:02X}", b));
        }
    }
    r
}

// ============ HTTP ============

struct Resp { status: u16, headers: Vec<(String,String)>, body: String }

fn parse_headers(raw: &[u8]) -> (u16, Vec<(String,String)>, usize) {
    let text = std::str::from_utf8(raw).unwrap();
    let mut lines = text.split("\r\n");
    let status_line = lines.next().unwrap();
    let parts: Vec<&str> = status_line.splitn(3, ' ').collect();
    let status: u16 = parts[1].parse().unwrap();
    let mut headers = Vec::new();
    let mut body_start = status_line.len() + 2;
    for line in lines {
        if line.is_empty() { body_start += 2; break; }
        if let Some(idx) = line.find(':') {
            let k = line[..idx].trim().to_lowercase();
            let v = line[idx+1..].trim().to_string();
            headers.push((k, v));
        }
        body_start += line.len() + 2;
    }
    (status, headers, body_start)
}

fn decode_chunked(data: &[u8]) -> Vec<u8> {
    let mut result = Vec::new();
    let mut pos = 0;
    loop {
        let nl = find_crlf(data, pos);
        let size_str = std::str::from_utf8(&data[pos..nl]).unwrap().trim();
        // handle possible extensions after ;
        let size_str = if let Some(semi) = size_str.find(';') { &size_str[..semi] } else { size_str };
        let size = usize::from_str_radix(size_str, 16).unwrap();
        pos = nl + 2;
        if size == 0 { break; }
        result.extend_from_slice(&data[pos..pos+size]);
        pos += size + 2; // skip trailing \r\n
    }
    result
}

fn find_crlf(data: &[u8], from: usize) -> usize {
    let mut i = from;
    while i + 1 < data.len() {
        if data[i]==b'\r' && data[i+1]==b'\n' { return i; }
        i += 1;
    }
    data.len()
}

fn http_request(method: &str, host: &str, port: u16, path: &str, extra_headers: &[(&str,&str)], body: Option<&str>) -> Resp {
    let addr = format!("{}:{}", host, port);
    let mut stream = TcpStream::connect(&addr).unwrap();
    stream.set_read_timeout(Some(Duration::from_secs(30))).unwrap();

    let host_hdr = if port == 80 { format!("{}", host) } else { format!("{}:{}", host, port) };
    let mut req = format!("{} {} HTTP/1.1\r\nHost: {}\r\n", method, path, host_hdr);
    for (k,v) in extra_headers {
        req.push_str(&format!("{}: {}\r\n", k, v));
    }
    if let Some(b) = body {
        req.push_str(&format!("Content-Length: {}\r\n", b.len()));
    }
    req.push_str("\r\n");
    if let Some(b) = body { req.push_str(b); }

    stream.write_all(req.as_bytes()).unwrap();
    stream.flush().unwrap();

    let mut raw = Vec::new();
    stream.read_to_end(&mut raw).unwrap();

    let (status, headers, body_start) = parse_headers(&raw);
    let body_bytes = &raw[body_start..];

    let body_vec = if headers.iter().any(|(k,v)| k=="transfer-encoding" && v.contains("chunked")) {
        decode_chunked(body_bytes)
    } else {
        body_bytes.to_vec()
    };

    Resp { status, headers, body: String::from_utf8(body_vec).unwrap() }
}

// ============ URL parsing ============

fn parse_url(url: &str) -> (String, u16, String) {
    let rest = if url.starts_with("http://") { &url[7..] } else { panic!("bad url") };
    let slash = rest.find('/').unwrap_or(rest.len());
    let authority = &rest[..slash];
    let path = if slash < rest.len() { &rest[slash..] } else { "" };
    let (host, port) = if let Some(colon) = authority.rfind(':') {
        // Check it's not an IPv6 bracket
        if authority[colon..].contains(']') {
            (authority.to_string(), 80u16)
        } else {
            (authority[..colon].to_string(), authority[colon+1..].parse().unwrap())
        }
    } else {
        (authority.to_string(), 80u16)
    };
    (host, port, path.to_string())
}

// ============ Amount ============

fn parse_cents(s: &str) -> i64 {
    let (neg, s2) = if s.starts_with('-') { (true, &s[1..]) } else { (false, s) };
    let (int_part, frac_part) = if let Some(dot) = s2.find('.') {
        (&s2[..dot], &s2[dot+1..])
    } else {
        (s2, "")
    };
    let mut cents: i64 = int_part.parse::<i64>().unwrap() * 100;
    if !frac_part.is_empty() {
        let f = if frac_part.len() == 1 {
            (frac_part.as_bytes()[0] - b'0') as i64 * 10
        } else {
            frac_part.parse::<i64>().unwrap()
        };
        cents += f;
    }
    if neg { -cents } else { cents }
}

fn fmt_cents(cents: i64) -> String {
    let neg = cents < 0;
    let abs = if neg { (cents as i128).wrapping_neg() as i64 } else { cents };
    let int_part = abs / 100;
    let frac_part = abs % 100;
    if neg {
        format!("-{}.{}", int_part, format!("{:02}", frac_part))
    } else {
        format!("{}.{}", int_part, format!("{:02}", frac_part))
    }
}

// ============ Main ============

fn main() {
    let args: Vec<String> = env::args().collect();
    let data_dir = &args[1];
    let base_url = &args[2];

    let client_json_str = fs::read_to_string(format!("{}/client.json", data_dir)).unwrap();
    let client = parse_json(&client_json_str);
    let client_id = client.get("client_id").unwrap().as_str().unwrap().to_string();
    let client_secret = client.get("client_secret").unwrap().as_str().unwrap().to_string();
    let scope = client.get("scope").unwrap().as_str().unwrap().to_string();
    let page_size = client.get("page_size").unwrap();
    let page_size = if let Json::Num(n) = page_size { n as usize } else { panic!("page_size") };

    let (host, port, path_prefix) = parse_url(base_url);

    // Step 1: get token
    let token_body = format!("grant_type=client_credentials&scope={}", form_encode(&scope));
    let b64_creds = b64_encode(format!("{}:{}", form_encode(&client_id), form_encode(&client_secret)).as_bytes());
    let auth_hdr = format!("Basic {}", b64_creds);

    let get_token = || -> String {
        let r = http_request("POST", &host, port, &format!("{}/oauth/token", path_prefix),
            &[("Content-Type","application/x-www-form-urlencoded"), ("Authorization", auth_hdr.as_str())],
            Some(&token_body));
        if r.status != 200 {
            println!("ERROR {} {}", r.status, r.body);
            process::exit(0);
        }
        let j = parse_json(&r.body);
        j.get("access_token").unwrap().as_str().unwrap().to_string()
    };

    let mut access_token = get_token();
    let mut reauth_count: usize = 0;
    let mut got_200_with_token = false;

    let mut total_orders: usize = 0;
    let mut total_pages: usize = 0;
    let total_retries: usize = 0;
    let mut retries: usize = 0;

    // Aggregation
    let mut totals: BTreeMap<(String, String), i64> = BTreeMap::new();
    let mut status_counts: BTreeMap<String, usize> = BTreeMap::new();

    let mut cursor: Option<String> = None;

    loop {
        let path = if let Some(ref c) = cursor {
            format!("{}/orders?limit={}&cursor={}", path_prefix, page_size, query_encode(c))
        } else {
            format!("{}/orders?limit={}", path_prefix, page_size)
        };

        let r = loop {
            let resp = http_request("GET", &host, port, &path,
                &[("Authorization", &format!("Bearer {}", access_token))], None);
            match resp.status {
                429 => {
                    retries += 1;
                    let ra = resp.headers.iter().find(|(k,_)| k=="retry-after")
                        .map(|(_,v)| v.trim().parse::<u64>().unwrap_or(1)).unwrap_or(1);
                    thread::sleep(Duration::from_secs(ra));
                    continue;
                }
                503 => {
                    retries += 1;
                    thread::sleep(Duration::from_millis(500));
                    continue;
                }
                401 => {
                    if !got_200_with_token {
                        println!("ERROR {} {}", resp.status, resp.body);
                        process::exit(0);
                    }
                    access_token = get_token();
                    reauth_count += 1;
                    got_200_with_token = false;
                    continue;
                }
                200 => { break resp; }
                _ => {
                    println!("ERROR {} {}", resp.status, resp.body);
                    process::exit(0);
                }
            }
        };

        got_200_with_token = true;
        total_pages += 1;

        let page = parse_json(&r.body);
        let data = page.get("data").unwrap().as_array().unwrap();
        total_orders += data.len();

        for order in data {
            let status = order.get("status").unwrap().as_str().unwrap().to_string();
            *status_counts.entry(status.clone()).or_insert(0) += 1;

            if status != "cancelled" {
                let customer = order.get("customer").unwrap();
                let name = customer.get("name").unwrap().as_str().unwrap().to_string();
                let currency = order.get("currency").unwrap().as_str().unwrap().to_string();
                let amount_str = order.get("amount").unwrap().as_str().unwrap();
                let cents = parse_cents(amount_str);
                *totals.entry((name, currency)).or_insert(0) += cents;
            }
        }

        let nc = page.get("next_cursor").unwrap();
        if nc.is_null() {
            break;
        }
        cursor = Some(nc.as_str().unwrap().to_string());
    }

    // Output
    let mut lines: Vec<(String, String, i64, String)> = Vec::new();
    for ((name, currency), cents) in &totals {
        lines.push((name.clone(), currency.clone(), *cents, format!("total {} {} {}", currency, fmt_cents(*cents), name)));
    }
    lines.sort_by(|a, b| {
        a.0.as_bytes().cmp(b.0.as_bytes())
            .then_with(|| a.1.as_bytes().cmp(b.1.as_bytes()))
    });
    for (_,_,_, line) in &lines {
        println!("{}", line);
    }

    for (status, count) in &status_counts {
        println!("status {} {}", status, count);
    }

    println!("orders {} pages {} retries {} reauth {}", total_orders, total_pages, retries, reauth_count);
}

use std::collections::BTreeMap;
use std::env;
use std::fs;
use std::io::{Read, Write};
use std::net::TcpStream;
use std::process;
use std::thread;
use std::time::Duration;

// ============ JSON ============

#[derive(Debug, Clone)]
enum Json {
    Object(Vec<(String, Json)>),
    Array(Vec<Json>),
    Str(String),
    Num(f64),
    Bool(bool),
    Null,
}

impl Json {
    fn get(&self, key: &str) -> Option<&Json> {
        if let Json::Object(ref pairs) = self {
            for (k, v) in pairs {
                if k == key { return Some(v); }
            }
        }
        None
    }
    fn as_str(&self) -> Option<&str> {
        if let Json::Str(ref s) = self { Some(s) } else { None }
    }
    fn as_array(&self) -> Option<&[Json]> {
        if let Json::Array(ref a) = self { Some(a) } else { None }
    }
    fn is_null(&self) -> bool { matches!(self, Json::Null) }
}

struct JP<'a> { s: &'a [u8], p: usize }

impl<'a> JP<'a> {
    fn new(s: &'a str) -> Self { JP { s: s.as_bytes(), p: 0 } }
    fn ws(&mut self) { while self.p < self.s.len() && matches!(self.s[self.p], b' '|b'\t'|b'\n'|b'\r') { self.p += 1; } }
    fn peek(&self) -> Option<u8> { if self.p < self.s.len() { Some(self.s[self.p]) } else { None } }
    fn eat(&mut self, c: u8) { assert!(self.p < self.s.len() && self.s[self.p] == c); self.p += 1; }
    fn parse(&mut self) -> Json {
        self.ws();
        match self.peek() {
            Some(b'{') => self.obj(),
            Some(b'[') => self.arr(),
            Some(b'"') => Json::Str(self.string()),
            Some(b't') => { assert!(&self.s[self.p..self.p+4]==b"true"); self.p+=4; Json::Bool(true) }
            Some(b'f') => { assert!(&self.s[self.p..self.p+5]==b"false"); self.p+=5; Json::Bool(false) }
            Some(b'n') => { assert!(&self.s[self.p..self.p+4]==b"null"); self.p+=4; Json::Null }
            _ => self.num(),
        }
    }
    fn obj(&mut self) -> Json {
        self.eat(b'{');
        let mut pairs = Vec::new();
        self.ws();
        if self.peek()==Some(b'}') { self.p+=1; return Json::Object(pairs); }
        loop {
            self.ws();
            let k = self.string();
            self.ws(); self.eat(b':'); self.ws();
            let v = self.parse();
            pairs.push((k,v));
            self.ws();
            if self.peek()==Some(b',') { self.p+=1; } else { break; }
        }
        self.eat(b'}');
        Json::Object(pairs)
    }
    fn arr(&mut self) -> Json {
        self.eat(b'[');
        let mut items = Vec::new();
        self.ws();
        if self.peek()==Some(b']') { self.p+=1; return Json::Array(items); }
        loop {
            self.ws();
            items.push(self.parse());
            self.ws();
            if self.peek()==Some(b',') { self.p+=1; } else { break; }
        }
        self.eat(b']');
        Json::Array(items)
    }
    fn string(&mut self) -> String {
        self.eat(b'"');
        let mut r = Vec::new();
        loop {
            let c = self.s[self.p]; self.p += 1;
            if c == b'"' { break; }
            if c == b'\\' {
                let c2 = self.s[self.p]; self.p += 1;
                match c2 {
                    b'"' => r.push(b'"'),
                    b'\\' => r.push(b'\\'),
                    b'/' => r.push(b'/'),
                    b'b' => r.push(8),
                    b'f' => r.push(12),
                    b'n' => r.push(b'\n'),
                    b'r' => r.push(b'\r'),
                    b't' => r.push(b'\t'),
                    b'u' => {
                        let cp = self.hex4();
                        if cp >= 0xD800 && cp <= 0xDBFF {
                            assert!(self.s[self.p]==b'\\' && self.s[self.p+1]==b'u');
                            self.p += 2;
                            let lo = self.hex4();
                            let code = 0x10000u32 + ((cp-0xD800)<<10) + (lo-0xDC00);
                            let ch = char::from_u32(code).unwrap();
                            let mut buf = [0u8;4];
                            r.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                        } else {
                            let ch = char::from_u32(cp).unwrap();
                            let mut buf = [0u8;4];
                            r.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                        }
                    }
                    _ => panic!("bad esc"),
                }
            } else {
                r.push(c);
            }
        }
        String::from_utf8(r).unwrap()
    }
    fn hex4(&mut self) -> u32 {
        let h = &self.s[self.p..self.p+4]; self.p += 4;
        let mut v = 0u32;
        for &b in h { v <<= 4; v |= match b {
            b'0'..=b'9' => (b-b'0') as u32,
            b'a'..=b'f' => (b-b'a'+10) as u32,
            b'A'..=b'F' => (b-b'A'+10) as u32,
            _ => panic!("hex"),
        }; }
        v
    }
    fn num(&mut self) -> Json {
        let st = self.p;
        if self.peek()==Some(b'-') { self.p+=1; }
        while self.p<self.s.len() && self.s[self.p].is_ascii_digit() { self.p+=1; }
        if self.p<self.s.len() && self.s[self.p]==b'.' { self.p+=1; while self.p<self.s.len() && self.s[self.p].is_ascii_digit() { self.p+=1; } }
        if self.p<self.s.len() && (self.s[self.p]==b'e'||self.s[self.p]==b'E') { self.p+=1; if self.p<self.s.len() && (self.s[self.p]==b'+'||self.s[self.p]==b'-') { self.p+=1; } while self.p<self.s.len() && self.s[self.p].is_ascii_digit() { self.p+=1; } }
        Json::Num(std::str::from_utf8(&self.s[st..self.p]).unwrap().parse().unwrap())
    }
}

fn parse_json(s: &str) -> Json { JP::new(s).parse() }

// ============ Base64 ============

fn b64_encode(data: &[u8]) -> String {
    const T: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut r = String::new();
    let mut i = 0;
    while i + 2 < data.len() {
        let n = ((data[i] as u32) << 16) | ((data[i+1] as u32) << 8) | (data[i+2] as u32);
        r.push(T[((n>>18)&63) as usize] as char);
        r.push(T[((n>>12)&63) as usize] as char);
        r.push(T[((n>>6)&63) as usize] as char);
        r.push(T[(n&63) as usize] as char);
        i += 3;
    }
    if i < data.len() {
        let n = ((data[i] as u32) << 16) | if i+1<data.len() { (data[i+1] as u32)<<8 } else { 0 };
        r.push(T[((n>>18)&63) as usize] as char);
        r.push(T[((n>>12)&63) as usize] as char);
        if i+1 < data.len() {
            r.push(T[((n>>6)&63) as usize] as char);
            r.push('=');
        } else {
            r.push('=');
            r.push('=');
        }
    }
    r
}

// ============ Encoding ============

fn form_encode(s: &str) -> String {
    let mut r = String::new();
    for &b in s.as_bytes() {
        if b.is_ascii_alphanumeric() || b==b'-' || b==b'.' || b==b'_' || b==b'*' {
            r.push(b as char);
        } else if b == b' ' {
            r.push('+');
        } else {
            r.push_str(&format!("%{:02X}", b));
        }
    }
    r
}

fn query_encode(s: &str) -> String {
    let mut r = String::new();
    for &b in s.as_bytes() {
        if b.is_ascii_alphanumeric() || b==b'-' || b==b'_' || b==b'.' || b==b'~' {
            r.push(b as char);
        } else {
            r.push_str(&format!("%{:02X}", b));
        }
    }
    r
}

// ============ HTTP ============

struct Resp { status: u16, headers: Vec<(String,String)>, body: String }

fn parse_headers(raw: &[u8]) -> (u16, Vec<(String,String)>, usize) {
    let text = std::str::from_utf8(raw).unwrap();
    let mut lines = text.split("\r\n");
    let status_line = lines.next().unwrap();
    let parts: Vec<&str> = status_line.splitn(3, ' ').collect();
    let status: u16 = parts[1].parse().unwrap();
    let mut headers = Vec::new();
    let mut body_start = status_line.len() + 2;
    for line in lines {
        if line.is_empty() { body_start += 2; break; }
        if let Some(idx) = line.find(':') {
            let k = line[..idx].trim().to_lowercase();
            let v = line[idx+1..].trim().to_string();
            headers.push((k, v));
        }
        body_start += line.len() + 2;
    }
    (status, headers, body_start)
}

fn decode_chunked(data: &[u8]) -> Vec<u8> {
    let mut result = Vec::new();
    let mut pos = 0;
    loop {
        let nl = find_crlf(data, pos);
        let size_str = std::str::from_utf8(&data[pos..nl]).unwrap().trim();
        let size_str = if let Some(semi) = size_str.find(';') { &size_str[..semi] } else { size_str };
        let size = usize::from_str_radix(size_str.trim(), 16).unwrap();
        pos = nl + 2;
        if size == 0 { break; }
        result.extend_from_slice(&data[pos..pos+size]);
        pos += size + 2;
    }
    result
}

fn find_crlf(data: &[u8], from: usize) -> usize {
    let mut i = from;
    while i + 1 < data.len() {
        if data[i]==b'\r' && data[i+1]==b'\n' { return i; }
        i += 1;
    }
    data.len()
}

fn http_request(method: &str, host: &str, port: u16, path: &str, extra_headers: &[(&str,&str)], body: Option<&str>) -> Resp {
    let addr = format!("{}:{}", host, port);
    let mut stream = TcpStream::connect(&addr).unwrap();
    stream.set_read_timeout(Some(Duration::from_secs(30))).unwrap();

    let host_hdr = if port == 80 { format!("{}", host) } else { format!("{}:{}", host, port) };
    let mut req = format!("{} {} HTTP/1.1\r\nHost: {}\r\n", method, path, host_hdr);
    for (k,v) in extra_headers {
        req.push_str(&format!("{}: {}\r\n", k, v));
    }
    if let Some(b) = body {
        req.push_str(&format!("Content-Length: {}\r\n", b.len()));
    }
    req.push_str("\r\n");
    if let Some(b) = body { req.push_str(b); }

    stream.write_all(req.as_bytes()).unwrap();
    stream.flush().unwrap();

    let mut raw = Vec::new();
    stream.read_to_end(&mut raw).unwrap();

    let (status, headers, body_start) = parse_headers(&raw);
    let body_bytes = &raw[body_start..];

    let body_vec = if headers.iter().any(|(k,v)| k=="transfer-encoding" && v.contains("chunked")) {
        decode_chunked(body_bytes)
    } else {
        body_bytes.to_vec()
    };

    Resp { status, headers, body: String::from_utf8(body_vec).unwrap() }
}

// ============ URL parsing ============

fn parse_url(url: &str) -> (String, u16, String) {
    let rest = if url.starts_with("http://") { &url[7..] } else { panic!("bad url") };
    let slash = rest.find('/').unwrap_or(rest.len());
    let authority = &rest[..slash];
    let path = if slash < rest.len() { &rest[slash..] } else { "" };
    let (host, port) = if let Some(colon) = authority.rfind(':') {
        if authority[colon..].contains(']') {
            (authority.to_string(), 80u16)
        } else {
            (authority[..colon].to_string(), authority[colon+1..].parse().unwrap())
        }
    } else {
        (authority.to_string(), 80u16)
    };
    (host, port, path.to_string())
}

// ============ Amount ============

fn parse_cents(s: &str) -> i64 {
    let (neg, s2) = if s.starts_with('-') { (true, &s[1..]) } else { (false, s) };
    let (int_part, frac_part) = if let Some(dot) = s2.find('.') {
        (&s2[..dot], &s2[dot+1..])
    } else {
        (s2, "")
    };
    let mut cents: i64 = int_part.parse::<i64>().unwrap() * 100;
    if !frac_part.is_empty() {
        let f = if frac_part.len() == 1 {
            (frac_part.as_bytes()[0] - b'0') as i64 * 10
        } else {
            frac_part.parse::<i64>().unwrap()
        };
        cents += f;
    }
    if neg { -cents } else { cents }
}

fn fmt_cents(cents: i64) -> String {
    let neg = cents < 0;
    let abs: i64 = if neg { (cents as i128).wrapping_neg() as i64 } else { cents };
    let int_part = abs / 100;
    let frac_part = abs % 100;
    if neg {
        format!("-{}.{}", int_part, format!("{:02}", frac_part))
    } else {
        format!("{}.{}", int_part, format!("{:02}", frac_part))
    }
}

