            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            baos.write(local, 0, local.length);
            int remaining = P - localSize;
            while (overflowPage != 0 && remaining > 0) {
                int opOff = (int) ((overflowPage - 1) * pageSize);
                long nextOp = (long) readUint32(opOff) & 0xFFFFFFFFL;
                int chunk = Math.min(remaining, usableSize - 4);
                baos.write(fileData, opOff + 4, chunk);
                remaining -= chunk;
                overflowPage = nextOp;
            }
            fullPayload = baos.toByteArray();
        } else {
            fullPayload = local;
        }

        return new CellData(rowid, fullPayload);
    }

    static Value[] decodeRecord(byte[] payload) {
        if (payload.length == 0) return new Value[0];
        int[] p = {0};
        long headerSize = readVarint(payload, p);
        long numCols = readVarint(payload, p);
        int nc = (int) numCols;
        long[] stypes = new long[nc];
        for (int i = 0; i < nc; i++) {
            stypes[i] = readVarint(payload, p);
        }
        Value[] vals = new Value[nc];
        for (int i = 0; i < nc; i++) {
            vals[i] = decodeValue(payload, p, stypes[i]);
        }
        return vals;
    }

    static Value decodeValue(byte[] data, int[] p, long stype) {
        Value v = new Value();
        if (stype == 0) {
            v.type = 0;
        } else if (stype == 1) {
            v.type = 1;
            v.intVal = (byte) data[p[0]];
            p[0] += 1;
        } else if (stype == 2) {
            v.type = 1;
            v.intVal = readSignedInt(data, p[0], 2);
            p[0] += 2;
        } else if (stype == 3) {
            v.type = 1;
            v.intVal = readSignedInt(data, p[0], 3);
            p[0] += 3;
        } else if (stype == 4) {
            v.type = 1;
            v.intVal = readSignedInt(data, p[0], 4);
            p[0] += 4;
        } else if (stype == 5) {
            v.type = 1;
            v.intVal = readSignedInt(data, p[0], 6);
            p[0] += 6;
        } else if (stype == 6) {
            v.type = 1;
            v.intVal = readSignedInt(data, p[0], 8);
            p[0] += 8;
        } else if (stype == 7) {
            v.type = 2;
            long bits = readSignedInt(data, p[0], 8);
            v.realVal = Double.longBitsToDouble(bits);
            p[0] += 8;
        } else if (stype == 8) {
            v.type = 1;
            v.intVal = 0;
        } else if (stype == 9) {
            v.type = 1;
            v.intVal = 1;
        } else if (stype >= 12 && (stype & 1) == 0) {
            v.type = 4;
            int len = (int) ((stype - 12) / 2);
            v.bytesVal = Arrays.copyOfRange(data, p[0], p[0] + len);
            p[0] += len;
        } else if (stype >= 13 && (stype & 1) == 1) {
            v.type = 3;
            int len = (int) ((stype - 13) / 2);
            v.bytesVal = Arrays.copyOfRange(data, p[0], p[0] + len);
            p[0] += len;
        } else {
            v.type = 0;
        }
        return v;
    }

    static long readSignedInt(byte[] data, int off, int n) {
        long val;
        if (n == 0) return 0;
        if ((data[off] & 0x80) != 0) val = -1;
        else val = 0;
        for (int i = 0; i < n; i++) {
            val = (val << 8) | (data[off + i] & 0xFF);
        }
        return val;
    }

    static long readVarint(int[] p) {
        long val = 0;
        int i = 0;
        while (i < 9) {
            int b = fileData[p[0] + i] & 0xFF;
            if (i == 8) {
                val = (val << 8) | b;
                p[0] += 9;
                return val;
            }
            val = (val << 7) | (b & 0x7F);
            i++;
            if ((b & 0x80) == 0) {
                p[0] += i;
                return val;
            }
        }
        p[0] += 9;
        return val;
    }

    static long readVarint(byte[] data, int[] p) {
        long val = 0;
        int i = 0;
        while (i < 9) {
            int b = data[p[0] + i] & 0xFF;
            if (i == 8) {
                val = (val << 8) | b;
                p[0] += 9;
                return val;
            }
            val = (val << 7) | (b & 0x7F);
            i++;
            if ((b & 0x80) == 0) {
                p[0] += i;
                return val;
            }
        }
        p[0] += 9;
        return val;
    }

    static int readUint16(int off) {
        return ((fileData[off] & 0xFF) << 8) | (fileData[off + 1] & 0xFF);
    }

    static int readUint32(int off) {
        return ((fileData[off] & 0xFF) << 24) | ((fileData[off + 1] & 0xFF) << 16) |
               ((fileData[off + 2] & 0xFF) << 8) | (fileData[off + 3] & 0xFF);
    }

    static String formatValue(Value v) {
        switch (v.type) {
            case 0: return "NULL";
            case 1: return Long.toString(v.intVal);
            case 2: return formatReal(v.realVal);
            case 3: return formatText(v.bytesVal);
            case 4: return formatBlob(v.bytesVal);
            default: return "NULL";
        }
    }

    static String formatReal(double d) {
        BigDecimal bd = new BigDecimal(d);
        bd = bd.stripTrailingZeros();
        String s = bd.toPlainString();
        if (!s.contains(".")) s += ".0";
        return s;
    }

    static String formatText(byte[] data) {
        if (data.length > 100) {
            CRC32 crc = new CRC32();
            crc.update(data);
            return "<TEXT len=" + data.length + " crc32=" + String.format("%08x", crc.getValue()) + ">";
        }
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        baos.write('"');
        for (byte b : data) {
            int v = b & 0xFF;
            if (v == '\\') { baos.write('\\'); baos.write('\\'); }
            else if (v == '"') { baos.write('\\'); baos.write('"'); }
            else if (v == '\n') { baos.write('\\'); baos.write('n'); }
            else if (v == '\r') { baos.write('\\'); baos.write('r'); }
            else if (v == '\t') { baos.write('\\'); baos.write('t'); }
            else if (v < 0x20 || v == 0x7F) {
                baos.write('\\'); baos.write('x');
                String hex = String.format("%02X", v);
                baos.write(hex.charAt(0)); baos.write(hex.charAt(1));
            } else {
                baos.write(v);
            }
        }
        baos.write('"');
        return new String(baos.toByteArray(), StandardCharsets.UTF_8);
    }

    static String formatBlob(byte[] data) {
        if (data.length > 100) {
            CRC32 crc = new CRC32();
            crc.update(data);
            return "<BLOB len=" + data.length + " crc32=" + String.format("%08x", crc.getValue()) + ">";
        }
        StringBuilder sb = new StringBuilder("X'");
        for (byte b : data) {
            sb.append(String.format("%02X", b & 0xFF));
        }
        sb.append("'");
        return sb.toString();
    }

    static List<ColDef> parseColumns(String sql) {
        List<ColDef> cols = new ArrayList<>();
        String s = sql.trim();
        int idx = skipKeyword(s, 0, "CREATE");
        idx = skipWhitespace(s, idx);
        idx = skipKeyword(s, idx, "TABLE");
        idx = skipWhitespace(s, idx);
        idx = skipName(s, idx);
        idx = skipWhitespace(s, idx);
        if (idx < s.length() && s.charAt(idx) == '(') {
            idx++;
        }
        int depth = 1;
        int defsStart = idx;
        int defsEnd = idx;
        while (idx < s.length() && depth > 0) {
            if (s.charAt(idx) == '(') depth++;
            else if (s.charAt(idx) == ')') depth--;
            if (depth > 0) idx++;
        }
        defsEnd = idx;
        String defs = s.substring(defsStart, defsEnd);

        List<String> defsList = splitDefs(defs);
        for (String def : defsList) {
            String trimmed = def.trim();
            if (trimmed.isEmpty()) continue;
            String colName = extractColName(trimmed);
            boolean isAlias = isRowidAlias(trimmed);
            cols.add(new ColDef(colName, isAlias));
        }
        return cols;
    }

    static int skipKeyword(String s, int idx, String kw) {
        idx = skipWhitespace(s, idx);
        if (idx + kw.length() <= s.length() && s.substring(idx, idx + kw.length()).equalsIgnoreCase(kw)) {
            idx += kw.length();
        }
        return idx;
    }

    static int skipWhitespace(String s, int idx) {
        while (idx < s.length() && Character.isWhitespace(s.charAt(idx))) idx++;
        return idx;
    }

    static int skipName(String s, int idx) {
        if (idx < s.length() && s.charAt(idx) == '"') {
            idx++;
            while (idx < s.length() && s.charAt(idx) != '"') idx++;
            if (idx < s.length()) idx++;
        } else {
            while (idx < s.length() && !Character.isWhitespace(s.charAt(idx)) && s.charAt(idx) != '(' && s.charAt(idx) != ')') idx++;
        }
        return idx;
    }

    static List<String> splitDefs(String defs) {
        List<String> result = new ArrayList<>();
        int depth = 0;
        int start = 0;
        for (int i = 0; i < defs.length(); i++) {
            char c = defs.charAt(i);
            if (c == '(') depth++;
            else if (c == ')') depth--;
            else if (c == ',' && depth == 0) {
                result.add(defs.substring(start, i));
                start = i + 1;
            }
        }
        if (start < defs.length()) {
            result.add(defs.substring(start));
        }
        return result;
    }

    static String extractColName(String def) {
        def = def.trim();
        if (def.startsWith("\"")) {
            int end = def.indexOf('"', 1);
            if (end > 0) return def.substring(1, end);
            return def.substring(1);
        }
        int i = 0;
        while (i < def.length() && !Character.isWhitespace(def.charAt(i)) && def.charAt(i) != '(') {
            i++;
        }
        return def.substring(0, i);
    }

    static boolean isRowidAlias(String def) {
        def = def.trim();
        int i = 0;
        if (def.startsWith("\"")) {
            i = def.indexOf('"', 1) + 1;
        } else {
            while (i < def.length() && !Character.isWhitespace(def.charAt(i)) && def.charAt(i) != '(') i++;
        }
        while (i < def.length() && Character.isWhitespace(def.charAt(i))) i++;
        int typeStart = i;
        while (i < def.length() && (Character.isLetterOrDigit(def.charAt(i)) || def.charAt(i) == '_')) i++;
        String typeName = def.substring(typeStart, i);
        while (i < def.length() && Character.isWhitespace(def.charAt(i))) i++;
        if (i < def.length() && def.charAt(i) == '(') {
            int d = 1; i++;
            while (i < def.length() && d > 0) {
                if (def.charAt(i) == '(') d++;
                else if (def.charAt(i) == ')') d--;
                i++;
            }
        }
        if (!typeName.equalsIgnoreCase("INTEGER")) return false;
        String rest = def.substring(typeStart).replaceAll("\\s+", " ").toUpperCase();
        return rest.contains("PRIMARY KEY");
    }
}

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {

    // ==================== JSON Parser ====================
    static int jPos;
    static String jSrc;

    static Object parseJson(String s) {
        jPos = 0;
        jSrc = s;
        skipWs();
        return parseVal();
    }

    static void skipWs() {
        while (jPos < jSrc.length()) {
            char c = jSrc.charAt(jPos);
            if (c == ' ' || c == '\t' || c == '\n' || c == '\r') jPos++;
            else break;
        }
    }

    static Object parseVal() {
        skipWs();
        char c = jSrc.charAt(jPos);
        if (c == '{') return parseObj();
        if (c == '[') return parseArr();
        if (c == '"') return parseStr();
        if (c == 't') { jPos += 4; return Boolean.TRUE; }
        if (c == 'f') { jPos += 5; return Boolean.FALSE; }
        if (c == 'n') { jPos += 4; return null; }
        return parseNum();
    }

    static Map<String, Object> parseObj() {
        LinkedHashMap<String, Object> m = new LinkedHashMap<>();
        jPos++;
        skipWs();
        if (jSrc.charAt(jPos) == '}') { jPos++; return m; }
        while (true) {
            skipWs();
            String key = parseStr();
            skipWs();
            jPos++; // ':'
            skipWs();
            m.put(key, parseVal());
            skipWs();
            if (jSrc.charAt(jPos) == ',') { jPos++; continue; }
            jPos++; // '}'
            break;
        }
        return m;
    }

    static List<Object> parseArr() {
        ArrayList<Object> a = new ArrayList<>();
        jPos++;
        skipWs();
        if (jSrc.charAt(jPos) == ']') { jPos++; return a; }
        while (true) {
            skipWs();
            a.add(parseVal());
            skipWs();
            if (jSrc.charAt(jPos) == ',') { jPos++; continue; }
            jPos++; // ']'
            break;
        }
        return a;
    }

    static String parseStr() {
        jPos++; // opening "
        StringBuilder sb = new StringBuilder();
        while (jSrc.charAt(jPos) != '"') {
            char c = jSrc.charAt(jPos);
            if (c == '\\') {
                jPos++;
                char e = jSrc.charAt(jPos);
                if (e == '"') { sb.append('"'); }
                else if (e == '\\') { sb.append('\\'); }
                else if (e == '/') { sb.append('/'); }
                else if (e == 'b') { sb.append('\b'); }
                else if (e == 'f') { sb.append('\f'); }
                else if (e == 'n') { sb.append('\n'); }
                else if (e == 'r') { sb.append('\r'); }
                else if (e == 't') { sb.append('\t'); }
                else if (e == 'u') {
                    int hi = Integer.parseInt(jSrc.substring(jPos + 1, jPos + 5), 16);
                    jPos += 4;
                    if (Character.isHighSurrogate((char) hi)) {
                        jPos++; // backslash
                        jPos++; // 'u'
                        int lo = Integer.parseInt(jSrc.substring(jPos + 1, jPos + 5), 16);
                        jPos += 4;
                        sb.appendCodePoint(Character.toCodePoint((char) hi, (char) lo));
                    } else {
                        sb.append((char) hi);
                    }
                }
            } else {
                sb.append(c);
            }
            jPos++;
        }
        jPos++; // closing "
        return sb.toString();
    }

    static Object parseNum() {
        int start = jPos;
        if (jPos < jSrc.length() && jSrc.charAt(jPos) == '-') jPos++;
        while (jPos < jSrc.length() && Character.isDigit(jSrc.charAt(jPos))) jPos++;
        boolean isFloat = false;
        if (jPos < jSrc.length() && jSrc.charAt(jPos) == '.') { isFloat = true; jPos++; while (jPos < jSrc.length() && Character.isDigit(jSrc.charAt(jPos))) jPos++; }
        if (jPos < jSrc.length() && (jSrc.charAt(jPos) == 'e' || jSrc.charAt(jPos) == 'E')) { isFloat = true; jPos++; if (jPos < jSrc.length() && (jSrc.charAt(jPos) == '+' || jSrc.charAt(jPos) == '-')) jPos++; while (jPos < jSrc.length() && Character.isDigit(jSrc.charAt(jPos))) jPos++; }
        String s = jSrc.substring(start, jPos);
        if (isFloat) return Double.parseDouble(s);
        return Long.parseLong(s);
    }

    // ==================== JSON Serializer ====================
    @SuppressWarnings("unchecked")
    static String toJson(Object o) {
        if (o == null) return "null";
        if (o instanceof Boolean) return o.toString();
        if (o instanceof Long) return o.toString();
        if (o instanceof Integer) return o.toString();
        if (o instanceof Double) {
            double d = (Double) o;
            if (d == Math.floor(d) && !Double.isInfinite(d)) return String.valueOf((long) d);
            return o.toString();
        }
        if (o instanceof String) return jsonStr((String) o);
        if (o instanceof Map) {
            Map<String, Object> m = (Map<String, Object>) o;
            StringBuilder sb = new StringBuilder("{");
            boolean first = true;
            for (Map.Entry<String, Object> e : m.entrySet()) {
                if (!first) sb.append(',');
                first = false;
                sb.append(jsonStr(e.getKey())).append(':').append(toJson(e.getValue()));
            }
            sb.append('}');
            return sb.toString();
        }
        if (o instanceof List) {
            List<Object> l = (List<Object>) o;
            StringBuilder sb = new StringBuilder("[");
            boolean first = true;
            for (Object item : l) {
                if (!first) sb.append(',');
                first = false;
                sb.append(toJson(item));
            }
            sb.append(']');
            return sb.toString();
        }
        return o.toString();
    }

    static String jsonStr(String s) {
        StringBuilder sb = new StringBuilder("\"");
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                default:
                    if (c < 0x20) sb.append(String.format("\\u%04x", (int) c));
                    else sb.append(c);
            }
        }
        sb.append('"');
        return sb.toString();
    }

    // ==================== Output Escaping ====================
    static String esc(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '\\') sb.append("\\\\");
            else if (c == '\n') sb.append("\\n");
            else if (c == '\r') sb.append("\\r");
            else if (c == '\t') sb.append("\\t");
            else sb.append(c);
        }
        return sb.toString();
    }

    // ==================== HTTP ====================
    static class HttpResponse {
        int status;
        byte[] body;
    }

    static HttpResponse httpPost(String host, int port, String path, String apiKey, byte[] body) throws IOException {
        Socket sock = new Socket(host, port);
        sock.setSoTimeout(60000);
        OutputStream out = sock.getOutputStream();
        InputStream in = sock.getInputStream();

        String hdr = "POST " + path + " HTTP/1.1\r\n" +
                "Host: " + host + ":" + port + "\r\n" +
                "Content-Length: " + body.length + "\r\n" +
                "x-api-key: " + apiKey + "\r\n" +
                "anthropic-version: 2023-06-01\r\n" +
                "content-type: application/json\r\n" +
                "\r\n";
        out.write(hdr.getBytes(StandardCharsets.US_ASCII));
        out.write(body);
        out.flush();

        HttpResponse resp = new HttpResponse();
        String statusLine = readLine(in);
        resp.status = Integer.parseInt(statusLine.split("\\s+")[1]);

        Map<String, String> headers = new LinkedHashMap<>();
        String line;
        while ((line = readLine(in)) != null && !line.isEmpty()) {
            int ci = line.indexOf(':');
            if (ci >= 0) headers.put(line.substring(0, ci).trim().toLowerCase(), line.substring(ci + 1).trim());
        }

        String te = headers.get("transfer-encoding");
        String cl = headers.get("content-length");
        if (te != null && te.toLowerCase().contains("chunked")) {
            resp.body = readChunked(in);
        } else if (cl != null) {
            resp.body = readN(in, Integer.parseInt(cl));
        } else {
            resp.body = readAll(in);
        }
        sock.close();
        return resp;
    }

    static String readLine(InputStream in) throws IOException {
        StringBuilder sb = new StringBuilder();
        int c;
        while ((c = in.read()) != -1) {
            if (c == '\n') {
                if (sb.length() > 0 && sb.charAt(sb.length() - 1) == '\r') sb.setLength(sb.length() - 1);
                return sb.toString();
            }
            sb.append((char) c);
        }
        return sb.length() > 0 ? sb.toString() : null;
    }

    static byte[] readN(InputStream in, int n) throws IOException {
        byte[] buf = new byte[n];
        int off = 0;
        while (off < n) {
            int r = in.read(buf, off, n - off);
            if (r < 0) break;
            off += r;
        }
        return buf;
    }

    static byte[] readAll(InputStream in) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        byte[] buf = new byte[8192];
        int r;
        while ((r = in.read(buf)) != -1) baos.write(buf, 0, r);
        return baos.toByteArray();
    }

    static byte[] readChunked(InputStream in) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        while (true) {
            String szLine = readLine(in);
            if (szLine == null) break;
            int semi = szLine.indexOf(';');
            if (semi >= 0) szLine = szLine.substring(0, semi);
            szLine = szLine.trim();
            if (szLine.isEmpty()) continue;
            int sz = Integer.parseInt(szLine, 16);
            if (sz == 0) break;
            byte[] data = readN(in, sz);
            baos.write(data);
            // consume trailing CRLF
            int c;
            while ((c = in.read()) != -1 && c != '\n') {}
        }
        return baos.toByteArray();
    }

    // ==================== SSE Parsing ====================
    static class SseEvent {
        String event;
        String data;
    }

    static List<SseEvent> parseSse(String text) {
        List<SseEvent> events = new ArrayList<>();
        String curEvent = null;
        StringBuilder curData = new StringBuilder();
        boolean hasData = false;

        String[] lines = text.split("\n", -1);
        for (String raw : lines) {
            String ln = raw;
            if (ln.endsWith("\r")) ln = ln.substring(0, ln.length() - 1);

            if (ln.isEmpty()) {
                if (hasData || curEvent != null) {
                    SseEvent ev = new SseEvent();
                    ev.event = curEvent;
                    ev.data = hasData ? curData.toString() : "";
                    events.add(ev);
                }
                curEvent = null;
                curData = new StringBuilder();
                hasData = false;
                continue;
            }
            if (ln.charAt(0) == ':') continue; // comment

            int colon = ln.indexOf(':');
            String field, value;
            if (colon >= 0) {
                field = ln.substring(0, colon);
                value = ln.substring(colon + 1);
                if (value.startsWith(" ")) value = value.substring(1);
            } else {
                field = ln;
                value = "";
            }

            if (field.equals("event")) {
                curEvent = value;
            } else if (field.equals("data")) {
                if (hasData) curData.append('\n');
                curData.append(value);
                hasData = true;
            }
        }
        // handle trailing event without blank line
        if (hasData || curEvent != null) {
            SseEvent ev = new SseEvent();
            ev.event = curEvent;
            ev.data = hasData ? curData.toString() : "";
            events.add(ev);
        }
        return events;
    }

    // ==================== Content Blocks ====================
    static class CBlock {
        String type;
        StringBuilder thinking = new StringBuilder();
        StringBuilder signature = new StringBuilder();
        StringBuilder text = new StringBuilder();
        String id, name;
        StringBuilder inputJson = new StringBuilder();
    }

    // ==================== Tool Execution ====================
    static String runTool(String name, Map<String, Object> input) {
        if (name.equals("measure")) {
            String txt = (String) input.get("text");
            String unit = (String) input.get("unit");
            if (txt == null || unit == null) return "unsupported unit: " + unit;
            if (unit.equals("code_points")) {
                return String.valueOf(txt.codePointCount(0, txt.length()));
            } else if (unit.equals("utf8_bytes")) {
                return String.valueOf(txt.getBytes(StandardCharsets.UTF_8).length);
            } else if (unit.equals("utf16_units")) {
                return String.valueOf(txt.length());
            } else {
                return null; // error
            }
        } else if (name.equals("reverse")) {
            String txt = (String) input.get("text");
            if (txt == null) return "";
            int[] cps = txt.codePoints().toArray();
            StringBuilder sb = new StringBuilder();
            for (int i = cps.length - 1; i >= 0; i--) sb.appendCodePoint(cps[i]);
            return sb.toString();
        } else {
            return null; // unknown tool
        }
    }

    // ==================== Main ====================
    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        String dataDir = args[0];
        String baseUrl = args[1];

        // Read request.json
