import Foundation

func readBE16(_ d: [UInt8], _ off: Int) -> Int {
    return Int(d[off]) << 8 | Int(d[off + 1])
}

func readBE32(_ d: [UInt8], _ off: Int) -> Int {
    return Int(d[off]) << 24 | Int(d[off+1]) << 16 | Int(d[off+2]) << 8 | Int(d[off+3])
}

func readVarint(_ d: [UInt8], _ off: Int) -> (UInt64, Int) {
    var result: UInt64 = 0
    for i in 0..<8 {
        let b = d[off + i]
        result = (result << 7) | UInt64(b & 0x7F)
        if b & 0x80 == 0 {
            return (result, i + 1)
        }
    }
    result = (result << 8) | UInt64(d[off + 8])
    return (result, 9)
}

func crc32(_ data: [UInt8]) -> UInt32 {
    var crc: UInt32 = 0xFFFFFFFF
    for byte in data {
        crc ^= UInt32(byte)
        for _ in 0..<8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320
            } else {
                crc >>= 1
            }
        }
    }
    return crc ^ 0xFFFFFFFF
}

enum Value {
    case null
    case integer(Int64)
    case real(Double)
    case text([UInt8])
    case blob([UInt8])
}

func parseRecord(_ payload: [UInt8], numColumns: Int) -> [Value] {
    if payload.isEmpty { return [Value](repeating: .null, count: numColumns) }
    var pos = 0
    let (headerSize, n) = readVarint(payload, pos)
    pos += n
    var serialTypes: [UInt64] = []
    let headerEnd = Int(headerSize)
    while pos < headerEnd {
        let (st, nb) = readVarint(payload, pos)
        serialTypes.append(st)
        pos += nb
    }
    var values: [Value] = []
    var vpos = headerEnd
    for i in 0..<numColumns {
        if i >= serialTypes.count {
            values.append(.null)
            continue
        }
        let st = serialTypes[i]
        if st == 0 {
            values.append(.null)
        } else if st == 1 {
            let v = Int64(Int8(bitPattern: payload[vpos])); vpos += 1
            values.append(.integer(v))
        } else if st == 2 {
            let v = Int64(Int16(bitPattern: UInt16(payload[vpos]) << 8 | UInt16(payload[vpos+1]))); vpos += 2
            values.append(.integer(v))
        } else if st == 3 {
            let raw = Int(payload[vpos]) << 16 | Int(payload[vpos+1]) << 8 | Int(payload[vpos+2])
            let v: Int64
            if raw & 0x800000 != 0 { v = Int64(raw) - 0x1000000 } else { v = Int64(raw) }
            vpos += 3
            values.append(.integer(v))
        } else if st == 4 {
            let raw = UInt32(payload[vpos]) << 24 | UInt32(payload[vpos+1]) << 16 | UInt32(payload[vpos+2]) << 8 | UInt32(payload[vpos+3])
            let v = Int64(Int32(bitPattern: raw)); vpos += 4
            values.append(.integer(v))
        } else if st == 5 {
            var raw: UInt64 = 0
            for j in 0..<6 { raw = (raw << 8) | UInt64(payload[vpos+j]) }
            let v: Int64
            if raw & 0x800000000000 != 0 { v = Int64(bitPattern: raw | (0xFF << 48)) } else { v = Int64(bitPattern: raw) }
            vpos += 6
            values.append(.integer(v))
        } else if st == 6 {
            var raw: UInt64 = 0
            for j in 0..<8 { raw = (raw << 8) | UInt64(payload[vpos+j]) }
            let v = Int64(bitPattern: raw); vpos += 8
            values.append(.integer(v))
        } else if st == 7 {
            var raw: UInt64 = 0
            for j in 0..<8 { raw = (raw << 8) | UInt64(payload[vpos+j]) }
            let v = Double(bitPattern: raw); vpos += 8
            values.append(.real(v))
        } else if st == 8 {
            values.append(.integer(0))
        } else if st == 9 {
            values.append(.integer(1))
        } else if st >= 12 && st % 2 == 0 {
            let len = Int((st - 12) / 2)
            let bytes = Array(payload[vpos..<(vpos+len)]); vpos += len
            values.append(.blob(bytes))
        } else if st >= 13 {
            let len = Int((st - 13) / 2)
            let bytes = Array(payload[vpos..<(vpos+len)]); vpos += len
            values.append(.text(bytes))
        } else {
            values.append(.null)
        }
    }
    return values
}

func readOverflow(_ data: [UInt8], startPage: Int, pageSize: Int, reserved: Int, needed: Int) -> [UInt8] {
    var result: [UInt8] = []
    var page = startPage
    while page != 0 && result.count < needed {
        let off = (page - 1) * pageSize
        let next = readBE32(data, off)
        let avail = pageSize - reserved - 4
        let toRead = min(avail, needed - result.count)
        result.append(contentsOf: data[(off+4)..<(off+4+toRead)])
        page = next
    }
    return result
}

func walkBTree(_ data: [UInt8], pageNum: Int, pageSize: Int, reserved: Int, isPage1: Bool) -> [(Int64, [UInt8])] {
    var results: [(Int64, [UInt8])] = []
    let pageOff = (pageNum - 1) * pageSize
    let hdrOff = isPage1 ? 100 : 0
    let pageType = data[pageOff + hdrOff]

    if pageType == 0x02 { // interior table b-tree
        let numCells = readBE16(data, pageOff + hdrOff + 3)
        let rightmost = readBE32(data, pageOff + hdrOff + 8)
        let cellPtrStart = pageOff + hdrOff + 12
        for i in 0..<numCells {
            let cellOff = pageOff + readBE16(data, cellPtrStart + i * 2)
            let childPage = readBE32(data, cellOff)
            results.append(contentsOf: walkBTree(data, pageNum: childPage, pageSize: pageSize, reserved: reserved, isPage1: childPage == 1))
        }
        results.append(contentsOf: walkBTree(data, pageNum: rightmost, pageSize: pageSize, reserved: reserved, isPage1: rightmost == 1))
    } else if pageType == 0x08 { // leaf table b-tree
        let numCells = readBE16(data, pageOff + hdrOff + 3)
        let cellPtrStart = pageOff + hdrOff + 8
        let usableSize = pageSize - reserved
        let X = usableSize - 35
        for i in 0..<numCells {
            let cellOff = pageOff + readBE16(data, cellPtrStart + i * 2)
            var pos = cellOff
            let (payloadSize, n1) = readVarint(data, pos); pos += n1
            let (rowidU, n2) = readVarint(data, pos); pos += n2
            let rowid = Int64(bitPattern: rowidU)
            let P = Int(payloadSize)
            let localSize: Int
            if P <= X {
                localSize = P
            } else {
                let K = X + ((P - X) % (usableSize - 4))
                localSize = K <= X ? K : X
            }
            var payload = Array(data[pos..<(pos + localSize)])
            pos += localSize
            if P > localSize {
                let overflowPage = readBE32(data, pos)
                let remaining = P - localSize
                payload.append(contentsOf: readOverflow(data, startPage: overflowPage, pageSize: pageSize, reserved: reserved, needed: remaining))
            }
            results.append((rowid, payload))
        }
    }
    return results
}

func getString(_ v: Value) -> String {
    if case .text(let bytes) = v { return String(bytes: bytes, encoding: .utf8) ?? "" }
    if case .blob(let bytes) = v { return String(bytes: bytes, encoding: .utf8) ?? "" }
    return ""
}

func getInt(_ v: Value) -> Int {
    if case .integer(let x) = v { return Int(x) }
    return 0
}

func formatReal(_ d: Double) -> String {
    var s = String(format: "%.8f", d)
    if let dotIdx = s.firstIndex(of: ".") {
        var end = s.endIndex
        while end > s.index(after: dotIdx) && s[s.index(before: end)] == "0" {
            end = s.index(before: end)
        }
        if end == s.index(after: dotIdx) {
            // keep at least one digit after dot - it's already "0"
        }
        s = String(s[s.startIndex..<end])
    }
    return s
}

func formatValue(_ v: Value) -> String {
    switch v {
    case .null: return "NULL"
    case .integer(let x): return String(x)
    case .real(let d): return formatReal(d)
    case .text(let bytes):
        if bytes.count <= 100 {
            return escapeText(bytes)
        } else {
            let crc = crc32(bytes)
            return "<TEXT len=\(bytes.count) crc32=\(String(format: "%08x", crc))>"
        }
    case .blob(let bytes):
        if bytes.count <= 100 {
            let hex = bytes.map { String(format: "%02X", $0) }.joined()
            return "X'\(hex)'"
        } else {
            let crc = crc32(bytes)
            return "<BLOB len=\(bytes.count) crc32=\(String(format: "%08x", crc))>"
        }
    }
}

func escapeText(_ bytes: [UInt8]) -> String {
    var result = "\""
    for b in bytes {
        switch b {
        case 0x5C: result += "\\\\"
        case 0x22: result += "\\\""
        case 0x0A: result += "\\n"
        case 0x0D: result += "\\r"
        case 0x09: result += "\\t"
        case 0x00...0x08, 0x0B, 0x0C, 0x0E...0x1F, 0x7F:
            result += String(format: "\\x%02X", b)
        default:
            result.append(Character(UnicodeScalar(b)))
        }
    }
    result += "\""
    return result
}

func parseCreateTable(_ sql: String) -> [(name: String, isRowidAlias: Bool)] {
    // Find the opening paren after CREATE TABLE <name>
    let upper = sql.uppercased()
    guard let createIdx = upper.range(of: "CREATE") else { return [] }
    var pos = createIdx.upperBound
    // skip whitespace
    pos = skipWS(sql, pos)
    // skip TABLE
    guard let tableIdx = upper.range(of: "TABLE", range: pos..<sql.endIndex) else { return [] }
    pos = tableIdx.upperBound
    pos = skipWS(sql, pos)
    // skip table name (bare or quoted)
    pos = skipIdentifier(sql, pos)
    pos = skipWS(sql, pos)
    // expect '('
    guard pos < sql.endIndex && sql[pos] == "(" else { return [] }
    pos = sql.index(after: pos)
    // find matching ')'
    var depth = 1
    let defsStart = pos
    while pos < sql.endIndex && depth > 0 {
        if sql[pos] == "(" { depth += 1 }
        else if sql[pos] == ")" { depth -= 1 }
        if depth > 0 { pos = sql.index(after: pos) }
    }
    let defsEnd = pos
    let defsStr = String(sql[defsStart..<defsEnd])

    // split by commas not inside parens
    let colDefs = splitDefs(defsStr)

    var columns: [(name: String, isRowidAlias: Bool)] = []
    for def in colDefs {
        let trimmed = def.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmed.isEmpty { continue }
        let (colName, rest) = parseColName(trimmed)
        let isAlias = isIntegerPrimaryKey(rest)
        columns.append((colName, isAlias))
    }
    return columns
}

func skipWS(_ s: String, _ i: String.Index) -> String.Index {
    var p = i
    while p < s.endIndex && (s[p] == " " || s[p] == "\t" || s[p] == "\n" || s[p] == "\r") {
        p = s.index(after: p)
    }
    return p
}

func skipIdentifier(_ s: String, _ i: String.Index) -> String.Index {
    var p = i
    if p < s.endIndex && s[p] == "\"" {
        p = s.index(after: p)
        while p < s.endIndex && s[p] != "\"" { p = s.index(after: p) }
        if p < s.endIndex { p = s.index(after: p) }
    } else {
        while p < s.endIndex && (s[p].isLetter || s[p].isNumber || s[p] == "_") {
            p = s.index(after: p)
        }
    }
    return p
}

func parseColName(_ s: String) -> (String, String) {
    var p = s.startIndex
    p = skipWS(s, p)
    var name = ""
    if p < s.endIndex && s[p] == "\"" {
        p = s.index(after: p)
        while p < s.endIndex && s[p] != "\"" {
            name.append(s[p])
            p = s.index(after: p)
        }
        if p < s.endIndex { p = s.index(after: p) }
    } else {
        while p < s.endIndex && (s[p].isLetter || s[p].isNumber || s[p] == "_") {
            name.append(s[p])
            p = s.index(after: p)
        }
    }
    let rest = String(s[p...])
    return (name, rest)
}

func isIntegerPrimaryKey(_ rest: String) -> Bool {
    let trimmed = rest.trimmingCharacters(in: .whitespacesAndNewlines)
    if trimmed.isEmpty { return false }
    // Read the first word (the type)
    var p = trimmed.startIndex
    var typeWord = ""
    while p < trimmed.endIndex && (trimmed[p].isLetter || trimmed[p].isNumber || trimmed[p] == "_") {
        typeWord.append(trimmed[p])
        p = trimmed.index(after: p)
    }
    // Check if type is exactly "INTEGER" (case-insensitive) with no following (
    let afterType = trimmed[p...].trimmingCharacters(in: .whitespacesAndNewlines)
    let hasParens = afterType.hasPrefix("(")
    if typeWord.uppercased() != "INTEGER" || hasParens { return false }
    // Check for PRIMARY KEY in the rest
    return containsPrimaryKey(rest)
}

func containsPrimaryKey(_ s: String) -> Bool {
    let words = s.split(whereSeparator: { $0 == " " || $0 == "\t" || $0 == "\n" || $0 == "\r" }).map { $0.uppercased() }
    for i in 0..<words.count {
        if words[i] == "PRIMARY" && i + 1 < words.count && words[i+1] == "KEY" {
            return true
        }
    }
    return false
}

func splitDefs(_ s: String) -> [String] {
    var result: [String] = []
    var depth = 0
    var current = ""
    for ch in s {
        if ch == "(" { depth += 1; current.append(ch) }
        else if ch == ")" { depth -= 1; current.append(ch) }
        else if ch == "," && depth == 0 {
            result.append(current)
            current = ""
        }
        else { current.append(ch) }
    }
    if !current.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
        result.append(current)
    }
    return result
}

func main() {
    let args = CommandLine.arguments
    let dir = args[1]
    let path = dir + "/db.sqlite"
    let fileData = try! Data(contentsOf: URL(fileURLWithPath: path))
    let bytes = [UInt8](fileData)

    let pageSizeRaw = Int(bytes[16]) << 8 | Int(bytes[17])
    let pageSize = pageSizeRaw == 1 ? 65536 : pageSizeRaw
    let reservedBytes = Int(bytes[20])

    // Walk sqlite_schema (rooted at page 1)
    let schemaRows = walkBTree(bytes, pageNum: 1, pageSize: pageSize, reserved: reservedBytes, isPage1: true)

    struct TableInfo {
        let name: String
        let rootPage: Int
        let sql: String
    }

    var tables: [TableInfo] = []
    for (_, payload) in schemaRows {
        let record = parseRecord(payload, numColumns: 5)
        let typeStr = getString(record[0])
        let name = getString(record[1])
        let rootPage = getInt(record[3])
        let sql = getString(record[4])
        if typeStr == "table" && !name.hasPrefix("sqlite_") {
            tables.append(TableInfo(name: name, rootPage: rootPage, sql: sql))
        }
    }

    tables.sort { $0.name < $1.name }

    for (idx, table) in tables.enumerated() {
        if idx > 0 { print("") }

        let columns = parseCreateTable(table.sql)
        let numCols = columns.count

        let rows = walkBTree(bytes, pageNum: table.rootPage, pageSize: pageSize, reserved: reservedBytes, isPage1: table.rootPage == 1)

        print("TABLE \(table.name) rows=\(rows.count)")
        let colNames = columns.map { $0.name }
        print("COLUMNS \(colNames.joined(separator: ", "))")

        for (rowid, payload) in rows {
            var record = parseRecord(payload, numColumns: numCols)

            // Handle INTEGER PRIMARY KEY aliases
            var values: [String] = []
            for ci in 0..<numCols {
                if columns[ci].isRowidAlias {
                    values.append(String(rowid))
                } else {
                    if ci < record.count {
                        values.append(formatValue(record[ci]))
                    } else {
                        values.append("NULL")
                    }
                }
            }
            print("\(rowid): \(values.joined(separator: ", "))")
        }
    }
}

main()

import Foundation

func readBE16(_ d: [UInt8], _ off: Int) -> Int {
    return Int(d[off]) << 8 | Int(d[off + 1])
}

func readBE32(_ d: [UInt8], _ off: Int) -> Int {
    return Int(d[off]) << 24 | Int(d[off+1]) << 16 | Int(d[off+2]) << 8 | Int(d[off+3])
}

func readVarint(_ d: [UInt8], _ off: Int) -> (UInt64, Int) {
    var result: UInt64 = 0
    for i in 0..<8 {
        let b = d[off + i]
        result = (result << 7) | UInt64(b & 0x7F)
        if b & 0x80 == 0 {
            return (result, i + 1)
        }
    }
    result = (result << 8) | UInt64(d[off + 8])
    return (result, 9)
}

func crc32(_ data: [UInt8]) -> UInt32 {
    var crc: UInt32 = 0xFFFFFFFF
    for byte in data {
        crc ^= UInt32(byte)
        for _ in 0..<8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320
            } else {
                crc >>= 1
            }
        }
    }
    return crc ^ 0xFFFFFFFF
}

enum Value {
    case null
    case integer(Int64)
    case real(Double)
    case text([UInt8])
    case blob([UInt8])
}

func parseRecord(_ payload: [UInt8], numColumns: Int) -> [Value] {
    if payload.isEmpty { return [Value](repeating: .null, count: numColumns) }
    var pos = 0
    let (headerSize, n) = readVarint(payload, pos)
    pos += n
    var serialTypes: [UInt64] = []
    let headerEnd = Int(headerSize)
    while pos < headerEnd {
        let (st, nb) = readVarint(payload, pos)
        serialTypes.append(st)
        pos += nb
    }
    var values: [Value] = []
    var vpos = headerEnd
    for i in 0..<numColumns {
        if i >= serialTypes.count {
            values.append(.null)
            continue
        }
        let st = serialTypes[i]
        if st == 0 {
            values.append(.null)
        } else if st == 1 {
            let v = Int64(Int8(bitPattern: payload[vpos])); vpos += 1
            values.append(.integer(v))
        } else if st == 2 {
            let v = Int64(Int16(bitPattern: UInt16(payload[vpos]) << 8 | UInt16(payload[vpos+1]))); vpos += 2
            values.append(.integer(v))
        } else if st == 3 {
            let raw = Int(payload[vpos]) << 16 | Int(payload[vpos+1]) << 8 | Int(payload[vpos+2])
            let v: Int64
            if raw & 0x800000 != 0 { v = Int64(raw) - 0x1000000 } else { v = Int64(raw) }
            vpos += 3
            values.append(.integer(v))
        } else if st == 4 {
            let raw = UInt32(payload[vpos]) << 24 | UInt32(payload[vpos+1]) << 16 | UInt32(payload[vpos+2]) << 8 | UInt32(payload[vpos+3])
            let v = Int64(Int32(bitPattern: raw)); vpos += 4
            values.append(.integer(v))
        } else if st == 5 {
            var raw: UInt64 = 0
            for j in 0..<6 { raw = (raw << 8) | UInt64(payload[vpos+j]) }
            let v: Int64
            if raw & 0x800000000000 != 0 { v = Int64(bitPattern: raw | (0xFF << 48)) } else { v = Int64(bitPattern: raw) }
            vpos += 6
            values.append(.integer(v))
        } else if st == 6 {
            var raw: UInt64 = 0
            for j in 0..<8 { raw = (raw << 8) | UInt64(payload[vpos+j]) }
            let v = Int64(bitPattern: raw); vpos += 8
            values.append(.integer(v))
        } else if st == 7 {
            var raw: UInt64 = 0
            for j in 0..<8 { raw = (raw << 8) | UInt64(payload[vpos+j]) }
            let v = Double(bitPattern: raw); vpos += 8
            values.append(.real(v))
        } else if st == 8 {
            values.append(.integer(0))
        } else if st == 9 {
            values.append(.integer(1))
        } else if st >= 12 && st % 2 == 0 {
            let len = Int((st - 12) / 2)
            let bytes = Array(payload[vpos..<(vpos+len)]); vpos += len
            values.append(.blob(bytes))
        } else if st >= 13 {
            let len = Int((st - 13) / 2)
            let bytes = Array(payload[vpos..<(vpos+len)]); vpos += len
            values.append(.text(bytes))
        } else {
            values.append(.null)
        }
    }
    return values
}

func readOverflow(_ data: [UInt8], startPage: Int, pageSize: Int, reserved: Int, needed: Int) -> [UInt8] {
    var result: [UInt8] = []
    var page = startPage
    while page != 0 && result.count < needed {
        let off = (page - 1) * pageSize
        let next = readBE32(data, off)
        let avail = pageSize - reserved - 4
        let toRead = min(avail, needed - result.count)
        result.append(contentsOf: data[(off+4)..<(off+4+toRead)])
        page = next
    }
    return result
}

func walkBTree(_ data: [UInt8], pageNum: Int, pageSize: Int, reserved: Int, isPage1: Bool) -> [(Int64, [UInt8])] {
    var results: [(Int64, [UInt8])] = []
    let pageOff = (pageNum - 1) * pageSize
    let hdrOff = isPage1 ? 100 : 0
    let pageType = data[pageOff + hdrOff]

    if pageType == 0x02 { // interior table b-tree
        let numCells = readBE16(data, pageOff + hdrOff + 3)
        let rightmost = readBE32(data, pageOff + hdrOff + 8)
        let cellPtrStart = pageOff + hdrOff + 12
        for i in 0..<numCells {
            let cellOff = pageOff + readBE16(data, cellPtrStart + i * 2)
            let childPage = readBE32(data, cellOff)
            results.append(contentsOf: walkBTree(data, pageNum: childPage, pageSize: pageSize, reserved: reserved, isPage1: childPage == 1))
        }
        results.append(contentsOf: walkBTree(data, pageNum: rightmost, pageSize: pageSize, reserved: reserved, isPage1: rightmost == 1))
    } else if pageType == 0x08 { // leaf table b-tree
        let numCells = readBE16(data, pageOff + hdrOff + 3)
        let cellPtrStart = pageOff + hdrOff + 8
        let usableSize = pageSize - reserved
        let X = usableSize - 35
        for i in 0..<numCells {
            let cellOff = pageOff + readBE16(data, cellPtrStart + i * 2)
            var pos = cellOff
            let (payloadSize, n1) = readVarint(data, pos); pos += n1
            let (rowidU, n2) = readVarint(data, pos); pos += n2
            let rowid = Int64(bitPattern: rowidU)
            let P = Int(payloadSize)
            let localSize: Int
            if P <= X {
                localSize = P
            } else {
                let K = X + ((P - X) % (usableSize - 4))
                localSize = K <= X ? K : X
            }
            var payload = Array(data[pos..<(pos + localSize)])
            pos += localSize
            if P > localSize {
                let overflowPage = readBE32(data, pos)
                let remaining = P - localSize
                payload.append(contentsOf: readOverflow(data, startPage: overflowPage, pageSize: pageSize, reserved: reserved, needed: remaining))
            }
            results.append((rowid, payload))
        }
    }
    return results
}

func getString(_ v: Value) -> String {
    if case .text(let bytes) = v { return String(bytes: bytes, encoding: .utf8) ?? "" }
    if case .blob(let bytes) = v { return String(bytes: bytes, encoding: .utf8) ?? "" }
    return ""
}

func getInt(_ v: Value) -> Int {
    if case .integer(let x) = v { return Int(x) }
    return 0
}

func formatReal(_ d: Double) -> String {
    var s = String(format: "%.8f", d)
    if let dotIdx = s.firstIndex(of: ".") {
        var end = s.endIndex
        while end > s.index(after: dotIdx) && s[s.index(before: end)] == "0" {
            end = s.index(before: end)
        }
        // ensure at least one digit after dot
        if end == s.index(after: dotIdx) {
            // already has at least the '0' we stopped at
        }
        s = String(s[s.startIndex..<end])
    }
    return s
}

func escapeText(_ bytes: [UInt8]) -> String {
    var result = "\""
    var i = 0
    while i < bytes.count {
        let b = bytes[i]
        if b == 0x5C { result += "\\\\"; i += 1 }
        else if b == 0x22 { result += "\\\""; i += 1 }
        else if b == 0x0A { result += "\\n"; i += 1 }
        else if b == 0x0D { result += "\\r"; i += 1 }
        else if b == 0x09 { result += "\\t"; i += 1 }
        else if (b >= 0x00 && b <= 0x08) || b == 0x0B || b == 0x0C || (b >= 0x0E && b <= 0x1F) || b == 0x7F {
            result += String(format: "\\x%02X", b)
            i += 1
        } else if b < 0x80 {
            result.append(Character(UnicodeScalar(b)))
            i += 1
        } else {
            // multi-byte UTF-8
            let charLen: Int
            if b & 0xE0 == 0xC0 { charLen = 2 }
            else if b & 0xF0 == 0xE0 { charLen = 3 }
            else if b & 0xF8 == 0xF0 { charLen = 4 }
            else { charLen = 1 }
            if i + charLen <= bytes.count {
                let charBytes = Array(bytes[i..<(i+charLen)])
                if let str = String(bytes: charBytes, encoding: .utf8) {
                    result += str
                } else {
                    for j in 0..<charLen {
                        result += String(format: "\\x%02X", bytes[i+j])
                    }
                }
                i += charLen
            } else {
                result += String(format: "\\x%02X", b)
                i += 1
            }
        }
    }
    result += "\""
    return result
}

func formatValue(_ v: Value) -> String {
    switch v {
    case .null: return "NULL"
    case .integer(let x): return String(x)
    case .real(let d): return formatReal(d)
    case .text(let bytes):
        if bytes.count <= 100 {
            return escapeText(bytes)
        } else {
            let crc = crc32(bytes)
            return "<TEXT len=\(bytes.count) crc32=\(String(format: "%08x", crc))>"
        }
    case .blob(let bytes):
        if bytes.count <= 100 {
            let hex = bytes.map { String(format: "%02X", $0) }.joined()
            return "X'\(hex)'"
        } else {
            let crc = crc32(bytes)
            return "<BLOB len=\(bytes.count) crc32=\(String(format: "%08x", crc))>"
        }
    }
}

// --- SQL parsing helpers working on [Character] to avoid String.Index issues ---

func isWS(_ c: Character) -> Bool {
    return c == " " || c == "\t" || c == "\n" || c == "\r"
}

func isIdentChar(_ c: Character) -> Bool {
    return c.isLetter || c.isNumber || c == "_"
}

func skipWSChars(_ chars: [Character], _ pos: Int) -> Int {
    var p = pos
    while p < chars.count && isWS(chars[p]) { p += 1 }
    return p
}

func skipWordCI(_ chars: [Character], _ pos: Int, _ word: String) -> Int {
    let wChars = Array(word)
    var p = pos
    for i in 0..<wChars.count {
        if p >= chars.count { return pos }
        if Character(chars[p].uppercased()) != wChars[i] { return pos }
        p += 1
    }
    // ensure it's a whole word (next char is not an identifier char)
    if p < chars.count && isIdentChar(chars[p]) { return pos }
    return p
}

func skipIdentChars(_ chars: [Character], _ pos: Int) -> Int {
    var p = pos
    if p < chars.count && chars[p] == "\"" {
        p += 1
        while p < chars.count && chars[p] != "\"" { p += 1 }
        if p < chars.count { p += 1 }
    } else {
        while p < chars.count && isIdentChar(chars[p]) { p += 1 }
    }
    return p
}

func parseColNameChars(_ chars: [Character], _ start: Int) -> (String, Int) {
    var p = skipWSChars(chars, start)
    var name = ""
    if p < chars.count && chars[p] == "\"" {
        p += 1
        while p < chars.count && chars[p] != "\"" {
            name.append(chars[p])
            p += 1
        }
        if p < chars.count { p += 1 }
    } else {
        while p < chars.count && isIdentChar(chars[p]) {
            name.append(chars[p])
            p += 1
        }
    }
    return (name, p)
}

func isIntegerPrimaryKeyChars(_ chars: [Character], _ start: Int) -> Bool {
    var p = skipWSChars(chars, start)
    // read first word (type name)
    var typeWord = ""
    while p < chars.count && isIdentChar(chars[p]) {
        typeWord.append(chars[p])
        p += 1
    }
    if typeWord.uppercased() != "INTEGER" { return false }
    // check no '(' immediately after (allowing whitespace)
    var q = p
    while q < chars.count && isWS(chars[q]) { q += 1 }
    if q < chars.count && chars[q] == "(" { return false }
    // check for PRIMARY KEY in the rest
    return containsPrimaryKeyChars(chars, p)
}

func containsPrimaryKeyChars(_ chars: [Character], _ start: Int) -> Bool {
    var p = start
    while p < chars.count {
        // skip non-identifier chars
        while p < chars.count && !isIdentChar(chars[p]) { p += 1 }
        if p >= chars.count { break }
        // read a word
        var word = ""
        while p < chars.count && isIdentChar(chars[p]) {
            word.append(chars[p])
            p += 1
        }
        if word.uppercased() == "PRIMARY" {
            // skip whitespace
            var q = p
            while q < chars.count && isWS(chars[q]) { q += 1 }
            // read next word
            var word2 = ""
            let q2 = q
            while q < chars.count && isIdentChar(chars[q]) {
                word2.append(chars[q])
                q += 1
            }
            if word2.uppercased() == "KEY" {
                return true
            }
            _ = q2
        }
    }
    return false
}

func splitDefsChars(_ chars: [Character]) -> [[Character]] {
    var result: [[Character]] = []
    var depth = 0
    var current: [Character] = []
    for ch in chars {
        if ch == "(" { depth += 1; current.append(ch) }
        else if ch == ")" { depth -= 1; current.append(ch) }
        else if ch == "," && depth == 0 {
            result.append(current)
            current = []
        }
        else { current.append(ch) }
    }
    // check if current has non-whitespace
    if current.contains(where: { !isWS($0) }) {
        result.append(current)
    }
    return result
}

func parseCreateTable(_ sql: String) -> [(name: String, isRowidAlias: Bool)] {
    let chars = Array(sql)
    var pos = 0

    pos = skipWSChars(chars, pos)
    pos = skipWordCI(chars, pos, "CREATE")
    pos = skipWSChars(chars, pos)
    pos = skipWordCI(chars, pos, "TABLE")
    pos = skipWSChars(chars, pos)
    // skip IF NOT EXISTS if present
    let afterTable = skipWordCI(chars, pos, "IF")
    if afterTable > pos {
        pos = skipWSChars(chars, afterTable)
        pos = skipWordCI(chars, pos, "NOT")
        pos = skipWSChars(chars, pos)
        pos = skipWordCI(chars, pos, "EXISTS")
        pos = skipWSChars(chars, pos)
    }
    // skip table name
    pos = skipIdentChars(chars, pos)
    pos = skipWSChars(chars, pos)
    // expect '('
    guard pos < chars.count && chars[pos] == "(" else { return [] }
    pos += 1

    // find matching ')'
    var depth = 1
    let defsStart = pos
    while pos < chars.count && depth > 0 {
        if chars[pos] == "(" { depth += 1 }
        else if chars[pos] == ")" { depth -= 1 }
        if depth > 0 { pos += 1 }
    }
    let defsEnd = pos

    let defsChars = Array(chars[defsStart..<defsEnd])
    let colDefs = splitDefsChars(defsChars)

    var columns: [(name: String, isRowidAlias: Bool)] = []
    for def in colDefs {
        // skip leading whitespace
        var dp = 0
        while dp < def.count && isWS(def[dp]) { dp += 1 }
        if dp >= def.count { continue }
        let (colName, afterName) = parseColNameChars(def, dp)
        if colName.isEmpty { continue }
        let isAlias = isIntegerPrimaryKeyChars(def, afterName)
        columns.append((colName, isAlias))
    }
    return columns
}

