// ─── JSON Value ───────────────────────────────────────────────────────────────

#[derive(Clone, Debug)]
enum Jv {
    Null,
    Bool(bool),
    Num(String),
    Str(String),
    Arr(Vec<Jv>),
    Obj(Vec<(String, Jv)>),
}

impl Jv {
    fn get(&self, key: &str) -> Option<&Jv> {
        if let Jv::Obj(pairs) = self {
            for (k, v) in pairs {
                if k == key { return Some(v); }
            }
        }
        None
    }
    fn as_str(&self) -> &str {
        if let Jv::Str(s) = self { s } else { "" }
    }
    fn as_num_str(&self) -> &str {
        if let Jv::Num(s) = self { s } else { "0" }
    }
}

// ─── JSON Parser ──────────────────────────────────────────────────────────────

struct Jp<'a> { s: &'a [u8], pos: usize }

impl<'a> Jp<'a> {
    fn new(s: &'a str) -> Self { Jp { s: s.as_bytes(), pos: 0 } }
    fn skip_ws(&mut self) {
        while self.pos < self.s.len() && (self.s[self.pos] == b' ' || self.s[self.pos] == b'\t' || self.s[self.pos] == b'\n' || self.s[self.pos] == b'\r') {
            self.pos += 1;
        }
    }
    fn peek(&self) -> Option<u8> { if self.pos < self.s.len() { Some(self.s[self.pos]) } else { None } }
    fn eat(&mut self, c: u8) -> bool {
        if self.peek() == Some(c) { self.pos += 1; true } else { false }
    }
    fn parse(&mut self) -> Jv {
        self.skip_ws();
        match self.peek() {
            Some(b'{') => self.parse_obj(),
            Some(b'[') => self.parse_arr(),
            Some(b'"') => Jv::Str(self.parse_str()),
            Some(b't') => { self.pos += 4; Jv::Bool(true) }
            Some(b'f') => { self.pos += 5; Jv::Bool(false) }
            Some(b'n') => { self.pos += 4; Jv::Null }
            _ => self.parse_num(),
        }
    }
    fn parse_obj(&mut self) -> Jv {
        self.pos += 1; // {
        let mut pairs = Vec::new();
        self.skip_ws();
        if self.eat(b'}') { return Jv::Obj(pairs); }
        loop {
            self.skip_ws();
            let key = self.parse_str();
            self.skip_ws();
            self.eat(b':');
            let val = self.parse();
            pairs.push((key, val));
            self.skip_ws();
            if self.eat(b',') { continue; }
            self.eat(b'}');
            break;
        }
        Jv::Obj(pairs)
    }
    fn parse_arr(&mut self) -> Jv {
        self.pos += 1; // [
        let mut items = Vec::new();
        self.skip_ws();
        if self.eat(b']') { return Jv::Arr(items); }
        loop {
            let val = self.parse();
            items.push(val);
            self.skip_ws();
            if self.eat(b',') { continue; }
            self.eat(b']');
            break;
        }
        Jv::Arr(items)
    }
    fn parse_str(&mut self) -> String {
        self.pos += 1; // "
        let mut out = Vec::new();
        loop {
            if self.pos >= self.s.len() { break; }
            let c = self.s[self.pos];
            self.pos += 1;
            if c == b'"' { break; }
            if c == b'\\' {
                if self.pos >= self.s.len() { break; }
                let e = self.s[self.pos]; self.pos += 1;
                match e {
                    b'"' => out.push(b'"'),
                    b'\\' => out.push(b'\\'),
                    b'/' => out.push(b'/'),
                    b'b' => out.push(8),
                    b'f' => out.push(12),
                    b'n' => out.push(b'\n'),
                    b'r' => out.push(b'\r'),
                    b't' => out.push(b'\t'),
                    b'u' => {
                        let cp = self.read_hex4();
                        if cp >= 0xD800 && cp <= 0xDBFF {
                            // high surrogate
                            if self.pos + 1 < self.s.len() && self.s[self.pos] == b'\\' && self.s[self.pos+1] == b'u' {
                                self.pos += 2;
                                let lo = self.read_hex4();
                                if lo >= 0xDC00 && lo <= 0xDFFF {
                                    let full = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                                    self.push_utf8(&mut out, full);
                                } else {
                                    self.push_utf8(&mut out, cp);
                                    self.push_utf8(&mut out, lo);
                                }
                            } else {
                                self.push_utf8(&mut out, cp);
                            }
                        } else {
                            self.push_utf8(&mut out, cp);
                        }
                    }
                    _ => { out.push(b'\\'); out.push(e); }
                }
            } else {
                out.push(c);
            }
        }
        String::from_utf8_lossy(&out).into_owned()
    }
    fn read_hex4(&mut self) -> u32 {
        let mut v: u32 = 0;
        for _ in 0..4 {
            let c = self.s[self.pos] as char;
            self.pos += 1;
            v = v * 16 + c.to_digit(16).unwrap_or(0);
        }
        v
    }
    fn push_utf8(&self, out: &mut Vec<u8>, cp: u32) {
        let ch = char::from_u32(cp).unwrap_or('\u{FFFD}');
        let mut buf = [0u8; 4];
        let s = ch.encode_utf8(&mut buf);
        out.extend_from_slice(s.as_bytes());
    }
    fn parse_num(&mut self) -> Jv {
        let start = self.pos;
        if self.peek() == Some(b'-') { self.pos += 1; }
        while self.pos < self.s.len() && (self.s[self.pos].is_ascii_digit() || self.s[self.pos] == b'.' || self.s[self.pos] == b'e' || self.s[self.pos] == b'E' || self.s[self.pos] == b'+' || self.s[self.pos] == b'-') {
            self.pos += 1;
        }
        Jv::Num(String::from_utf8_lossy(&self.s[start..self.pos]).into_owned())
    }
}

// ─── JSON Serializer ──────────────────────────────────────────────────────────

fn json_escape_str(s: &str, out: &mut String) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0C}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => { out.push_str(&format!("\\u{:04x}", c as u32)); }
            c => out.push(c),
        }
    }
    out.push('"');
}

fn ser_json(v: &Jv, out: &mut String) {
    match v {
        Jv::Null => out.push_str("null"),
        Jv::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        Jv::Num(s) => out.push_str(s),
        Jv::Str(s) => json_escape_str(s, out),
        Jv::Arr(items) => {
            out.push('[');
            for (i, item) in items.iter().enumerate() {
                if i > 0 { out.push(','); }
                ser_json(item, out);
            }
            out.push(']');
        }
        Jv::Obj(pairs) => {
            out.push('{');
            for (i, (k, v)) in pairs.iter().enumerate() {
                if i > 0 { out.push(','); }
                json_escape_str(k, out);
                out.push(':');
                ser_json(v, out);
            }
            out.push('}');
        }
    }
}

// ─── Output Escaping ──────────────────────────────────────────────────────────

fn esc(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c => out.push(c),
        }
    }
    out
}

// ─── HTTP Client ──────────────────────────────────────────────────────────────

struct HttpResp {
    status: u16,
    headers: Vec<(String, String)>,
    body: Vec<u8>,
}

fn http_post(host: &str, port: u16, path: &str, api_key: &str, body: &str) -> HttpResp {
    let addr = format!("{}:{}", host, port);
    let mut sock = TcpStream::connect(&addr).expect("connect failed");

    let req = format!(
        "POST {} HTTP/1.1\r\nHost: {}\r\nContent-Length: {}\r\nx-api-key: {}\r\nanthropic-version: 2023-06-01\r\ncontent-type: application/json\r\n\r\n{}",
        path, host, body.len(), api_key, body
    );
    sock.write_all(req.as_bytes()).expect("write failed");
    sock.flush().expect("flush failed");

    // Read all bytes until EOF
    let mut raw = Vec::new();
    sock.read_to_end(&mut raw).expect("read failed");

    // Parse HTTP response
    let header_end = find_subsequence(&raw, b"\r\n\r\n").expect("no header end");
    let header_bytes = &raw[..header_end];
    let body_start = header_end + 4;

    let header_str = String::from_utf8_lossy(header_bytes).into_owned();
    let mut lines = header_str.split("\r\n");
    let status_line = lines.next().unwrap_or("");
    let parts: Vec<&str> = status_line.splitn(3, ' ').collect();
    let status: u16 = parts.get(1).and_then(|s| s.parse().ok()).unwrap_or(0);

    let mut headers = Vec::new();
    for line in lines {
        if let Some(idx) = line.find(':') {
            let name = line[..idx].trim().to_lowercase();
            let val = line[idx+1..].trim().to_string();
            headers.push((name, val));
        }
    }

    let body_data = &raw[body_start..];
    let is_chunked = headers.iter().any(|(k, v)| k == "transfer-encoding" && v.to_lowercase().contains("chunked"));

    let body = if is_chunked {
        decode_chunked(body_data)
    } else {
        body_data.to_vec()
    };

    HttpResp { status, headers, body }
}

fn find_subsequence(haystack: &[u8], needle: &[u8]) -> Option<usize> {
    haystack.windows(needle.len()).position(|w| w == needle)
}

fn decode_chunked(data: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    let mut pos = 0;
    loop {
        // Read chunk size line
        let line_end = find_subsequence(&data[pos..], b"\r\n");
        let line_end = match line_end {
            Some(e) => pos + e,
            None => break,
        };
        let size_str = String::from_utf8_lossy(&data[pos..line_end]).into_owned();
        let size_str = size_str.trim();
        // Handle chunk extensions (ignore after ';')
        let size_str = size_str.split(';').next().unwrap_or("0").trim();
        let chunk_size = usize::from_str_radix(size_str, 16).unwrap_or(0);
        pos = line_end + 2; // skip \r\n

        if chunk_size == 0 { break; }

        // Read chunk data
        if pos + chunk_size <= data.len() {
            out.extend_from_slice(&data[pos..pos+chunk_size]);
            pos += chunk_size;
        } else {
            out.extend_from_slice(&data[pos..]);
            break;
        }

        // Skip trailing \r\n after chunk data
        if pos + 2 <= data.len() && data[pos] == b'\r' && data[pos+1] == b'\n' {
            pos += 2;
        }
    }
    out
}

// ─── SSE Parser ───────────────────────────────────────────────────────────────

struct SseEvent {
    event: String,
    data: String,
}

fn parse_sse(data: &[u8]) -> Vec<SseEvent> {
    let text = String::from_utf8_lossy(data).into_owned();
    let mut events = Vec::new();
    let mut event_name = String::new();
    let mut data_lines: Vec<String> = Vec::new();
    let mut has_data = false;

    let lines = split_sse_lines(&text);

    for line in lines {
        if line.is_empty() {
            // Blank line: dispatch event
            if has_data {
                events.push(SseEvent {
                    event: event_name.clone(),
                    data: data_lines.join("\n"),
                });
            }
            event_name.clear();
            data_lines.clear();
            has_data = false;
        } else if line.starts_with(':') {
            // Comment, ignore
        } else if line.starts_with("event:") {
            let val = &line[6..];
            event_name = if val.starts_with(' ') { val[1..].to_string() } else { val.to_string() };
        } else if line.starts_with("data:") {
            let val = &line[5..];
            let v = if val.starts_with(' ') { val[1..].to_string() } else { val.to_string() };
            data_lines.push(v);
            has_data = true;
        }
        // Ignore other fields (id:, retry:, etc.)
    }

    events
}

fn split_sse_lines(text: &str) -> Vec<String> {
    let mut lines = Vec::new();
    let bytes = text.as_bytes();
    let mut start = 0;
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'\n' {
            let mut end = i;
            if end > start && bytes[end - 1] == b'\r' { end -= 1; }
            lines.push(String::from_utf8_lossy(&bytes[start..end]).into_owned());
            start = i + 1;
        }
        i += 1;
    }
    if start < bytes.len() {
        lines.push(String::from_utf8_lossy(&bytes[start..]).into_owned());
    }
    lines
}

// ─── Content Block Accumulation ───────────────────────────────────────────────

#[derive(Clone)]
enum Block {
    Thinking { thinking: String, signature: String },
    Text { text: String },
    ToolUse { id: String, name: String, raw_input: String, parsed_input: Jv },
}

struct Reply {
    blocks: Vec<Block>,
    stop_reason: String,
    input_tokens: i64,
    output_tokens: i64,
    cache_read_tokens: i64,
}

fn process_sse_events(events: &[SseEvent]) -> Reply {
    let mut blocks: Vec<Block> = Vec::new();
    let mut stop_reason = String::new();
    let mut input_tokens: i64 = 0;
    let mut output_tokens: i64 = 0;
    let mut cache_read_tokens: i64 = 0;

    // Track per-index data
    let mut block_types: Vec<String> = Vec::new();
    let mut thinking_texts: Vec<String> = Vec::new();
    let mut signatures: Vec<String> = Vec::new();
    let mut texts: Vec<String> = Vec::new();
    let mut tool_ids: Vec<String> = Vec::new();
    let mut tool_names: Vec<String> = Vec::new();
    let mut tool_raw_inputs: Vec<String> = Vec::new();

    for ev in events {
        let data = match Jp::new(&ev.data).parse() {
            Jv::Obj(_) => Jp::new(&ev.data).parse(),
            _ => Jv::Null,
        };
        // Re-parse (the match above consumed it)
        let data = Jp::new(&ev.data).parse();

