                    if let Some(usage) = msg.get("usage") {
                        if let Some(v) = usage.get("input_tokens") { input_tokens = v.as_num_str().parse().unwrap_or(0); }
                        if let Some(v) = usage.get("cache_read_input_tokens") { cache_read_tokens = v.as_num_str().parse().unwrap_or(0); }
                    }
                }
            }
            "content_block_start" => {
                let idx = data.get("index").and_then(|v| v.as_num_str().parse::<usize>().ok()).unwrap_or(0);
                let cb = data.get("content_block").unwrap_or(&Jv::Null);
                let btype = cb.get("type").map(|v| v.as_str().to_string()).unwrap_or_default();

                while block_types.len() <= idx {
                    block_types.push(String::new());
                    thinking_texts.push(String::new());
                    signatures.push(String::new());
                    texts.push(String::new());
                    tool_ids.push(String::new());
                    tool_names.push(String::new());
                    tool_raw_inputs.push(String::new());
                }

                block_types[idx] = btype.clone();
                if btype == "tool_use" {
                    tool_ids[idx] = cb.get("id").map(|v| v.as_str().to_string()).unwrap_or_default();
                    tool_names[idx] = cb.get("name").map(|v| v.as_str().to_string()).unwrap_or_default();
                }
