            "content_block_delta" => {
                let idx = data.get("index").and_then(|v| v.as_num_str().parse::<usize>().ok()).unwrap_or(0);
                let delta = data.get("delta").unwrap_or(&Jv::Null);
                let dtype = delta.get("type").map(|v| v.as_str()).unwrap_or("");

                while thinking_texts.len() <= idx {
                    thinking_texts.push(String::new());
                    signatures.push(String::new());
                    texts.push(String::new());
                    tool_raw_inputs.push(String::new());
                }

                match dtype {
                    "thinking_delta" => {
                        if let Some(t) = delta.get("thinking") { thinking_texts[idx].push_str(t.as_str()); }
                    }
                    "signature_delta" => {
                        if let Some(s) = delta.get("signature") { signatures[idx].push_str(s.as_str()); }
                    }
                    "text_delta" => {
                        if let Some(t) = delta.get("text") { texts[idx].push_str(t.as_str()); }
                    }
                    "input_json_delta" => {
                        if let Some(t) = delta.get("partial_json") { tool_raw_inputs[idx].push_str(t.as_str()); }
                    }
                    _ => {}
                }
            }
            "content_block_stop" => {
                // finalize block
                let idx = data.get("index").and_then(|v| v.as_num_str().parse::<usize>().ok()).unwrap_or(0);
                if idx < block_types.len() {
                    match block_types[idx].as_str() {
                        "thinking" => blocks.push(Block::Thinking {
                            thinking: thinking_texts[idx].clone(),
                            signature: signatures[idx].clone(),
                        }),
                        "text" => blocks.push(Block::Text {
                            text: texts[idx].clone(),
                        }),
                        "tool_use" => {
                            let raw = tool_raw_inputs[idx].clone();
                            let parsed = if raw.is_empty() {
                                Jv::Obj(vec![])
                            } else {
                                Jp::new(&raw).parse()
                            };
                            blocks.push(Block::ToolUse {
                                id: tool_ids[idx].clone(),
                                name: tool_names[idx].clone(),
                                raw_input: raw,
                                parsed_input: parsed,
                            });
                        }
                        _ => {}
                    }
                }
            }
            "message_delta" => {
                if let Some(d) = data.get("delta") {
                    if let Some(sr) = d.get("stop_reason") {
                        stop_reason = sr.as_str().to_string();
                    }
                }
                if let Some(usage) = data.get("usage") {
                    if let Some(v) = usage.get("output_tokens") { output_tokens = v.as_num_str().parse().unwrap_or(0); }
                }
            }
            _ => {} // ping, message_stop, etc.
        }
    }

    Reply { blocks, stop_reason, input_tokens, output_tokens, cache_read_tokens }
}

// ─── Tool Execution ───────────────────────────────────────────────────────────

fn execute_tool(name: &str, input: &Jv) -> (String, bool) {
    match name {
        "measure" => {
            let text = input.get("text").map(|v| v.as_str().to_string()).unwrap_or_default();
            let unit = input.get("unit").map(|v| v.as_str().to_string()).unwrap_or_default();
            match unit.as_str() {
                "code_points" => {
                    let count = text.chars().count();
                    (count.to_string(), false)
                }
                "utf8_bytes" => {
                    let count = text.len();
                    (count.to_string(), false)
                }
                "utf16_units" => {
                    let count: usize = text.chars().map(|c| if (c as u32) > 0xFFFF { 2 } else { 1 }).sum();
                    (count.to_string(), false)
                }
                _ => (format!("unsupported unit: {}", unit), true),
            }
        }
        "reverse" => {
            let text = input.get("text").map(|v| v.as_str().to_string()).unwrap_or_default();
            let reversed: String = text.chars().rev().collect();
            (reversed, false)
        }
        _ => (format!("unknown tool: {}", name), true),
    }
}

// ─── Main ─────────────────────────────────────────────────────────────────────

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 {
        eprintln!("Usage: main <data_dir> <base_url>");
        std::process::exit(1);
    }
    let data_dir = &args[1];
    let base_url = &args[2];

    // Read request.json
    let req_path = format!("{}/request.json", data_dir);
    let req_content = fs::read_to_string(&req_path).expect("cannot read request.json");
    let req_json = Jp::new(&req_content).parse();

    let api_key = req_json.get("api_key").map(|v| v.as_str().to_string()).unwrap_or_default();
    let model = req_json.get("model").map(|v| v.as_str().to_string()).unwrap_or_default();
    let max_tokens_str = req_json.get("max_tokens").map(|v| v.as_num_str().to_string()).unwrap_or_else(|| "8000".to_string());
    let thinking_budget_str = req_json.get("thinking_budget").map(|v| v.as_num_str().to_string()).unwrap_or_else(|| "2048".to_string());
    let system = req_json.get("system").map(|v| v.as_str().to_string()).unwrap_or_default();
    let prompt = req_json.get("prompt").map(|v| v.as_str().to_string()).unwrap_or_default();
    let tools = req_json.get("tools").cloned().unwrap_or(Jv::Arr(vec![]));

    // Parse URL
    let url = base_url.strip_prefix("http://").unwrap_or(base_url);
    let (host_port, path) = match url.find('/') {
        Some(idx) => (&url[..idx], &url[idx..]),
        None => (url, ""),
    };
    let (host, port) = match host_port.rfind(':') {
        Some(idx) => (&host_port[..idx], host_port[idx+1..].parse::<u16>().unwrap_or(80)),
        None => (host_port, 80u16),
    };
    let endpoint = format!("{}/v1/messages", path);

    // Build request 1 body
    let body1 = build_request_body(&model, &max_tokens_str, &thinking_budget_str, &system, &tools, 1, &prompt, &[], &[]);

    // Send request 1
    println!("request 1");
    let resp1 = http_post(host, port, &endpoint, &api_key, &body1);

    if resp1.status != 200 {
        let body_str = String::from_utf8_lossy(&resp1.body).into_owned();
        let err_json = Jp::new(&body_str).parse();
        let etype = err_json.get("error").and_then(|e| e.get("type")).map(|v| v.as_str().to_string()).unwrap_or_default();
        let emsg = err_json.get("error").and_then(|e| e.get("message")).map(|v| v.as_str().to_string()).unwrap_or_default();
        println!("ERROR {} {}: {}", resp1.status, etype, emsg);
        return;
    }

    let events1 = parse_sse(&resp1.body);
    let reply1 = process_sse_events(&events1);

    // Print reply 1
    print_reply(&reply1);

    // Execute tools
    let tool_uses: Vec<&Block> = reply1.blocks.iter().filter(|b| matches!(b, Block::ToolUse{..})).collect();
    let mut tool_results: Vec<(String, String, bool)> = Vec::new();

    for block in &tool_uses {
        if let Block::ToolUse { id, name, parsed_input, .. } = block {
            let (result, is_error) = execute_tool(name, parsed_input);
            tool_results.push((id.clone(), result.clone(), is_error));
            if is_error {
                println!("error {} {}", id, esc(&result));
            } else {
                println!("result {} {}", id, esc(&result));
            }
        }
    }

    // Build request 2 body
    let body2 = build_request_body(&model, &max_tokens_str, &thinking_budget_str, &system, &tools, 2, &prompt, &reply1.blocks, &tool_results);

    // Send request 2
    println!("request 2");
    let resp2 = http_post(host, port, &endpoint, &api_key, &body2);

    if resp2.status != 200 {
        let body_str = String::from_utf8_lossy(&resp2.body).into_owned();
        let err_json = Jp::new(&body_str).parse();
        let etype = err_json.get("error").and_then(|e| e.get("type")).map(|v| v.as_str().to_string()).unwrap_or_default();
        let emsg = err_json.get("error").and_then(|e| e.get("message")).map(|v| v.as_str().to_string()).unwrap_or_default();
        println!("ERROR {} {}: {}", resp2.status, etype, emsg);
        return;
    }

    let events2 = parse_sse(&resp2.body);
    let reply2 = process_sse_events(&events2);

    // Print reply 2
    print_reply(&reply2);

    // Print usage
    let total_input = reply1.input_tokens + reply2.input_tokens;
    let total_output = reply1.output_tokens + reply2.output_tokens;
    let total_cache = reply1.cache_read_tokens + reply2.cache_read_tokens;
    println!("usage input={} output={} cache_read={}", total_input, total_output, total_cache);
}

fn print_reply(reply: &Reply) {
    for block in &reply.blocks {
        match block {
            Block::Thinking { thinking, signature } => {
                println!("thinking {}", esc(thinking));
                println!("signature {}", esc(signature));
            }
            Block::Text { text } => {
                println!("text {}", esc(text));
            }
            Block::ToolUse { id, name, raw_input, .. } => {
                println!("tool_use {} {} {}", esc(id), esc(name), esc(raw_input));
            }
        }
    }
    println!("stop_reason {}", reply.stop_reason);
}

fn build_request_body(
    model: &str, max_tokens: &str, thinking_budget: &str,
    system: &str, tools: &Jv, which: i32,
    prompt: &str, blocks: &[Block], tool_results: &[(String, String, bool)],
) -> String {
    let mut out = String::from('{');

    out.push_str("\"model\":");
    json_escape_str(model, &mut out);

    out.push_str(",\"max_tokens\":");
    out.push_str(max_tokens);

    out.push_str(",\"stream\":true");

    out.push_str(",\"thinking\":{\"type\":\"enabled\",\"budget_tokens\":");
    out.push_str(thinking_budget);
    out.push('}');

    out.push_str(",\"system\":");
    json_escape_str(system, &mut out);

    out.push_str(",\"tools\":");
    ser_json(tools, &mut out);

    out.push_str(",\"messages\":[");

    // User message
    out.push_str("{\"role\":\"user\",\"content\":");
    json_escape_str(prompt, &mut out);
    out.push('}');

    if which == 2 {
        // Assistant message
        out.push_str(",{\"role\":\"assistant\",\"content\":[");
        for (i, block) in blocks.iter().enumerate() {
            if i > 0 { out.push(','); }
            match block {
                Block::Thinking { thinking, signature } => {
                    out.push_str("{\"type\":\"thinking\",\"thinking\":");
                    json_escape_str(thinking, &mut out);
                    out.push_str(",\"signature\":");
                    json_escape_str(signature, &mut out);
                    out.push('}');
                }
                Block::Text { text } => {
                    out.push_str("{\"type\":\"text\",\"text\":");
                    json_escape_str(text, &mut out);
                    out.push('}');
                }
                Block::ToolUse { id, name, parsed_input, .. } => {
                    out.push_str("{\"type\":\"tool_use\",\"id\":");
                    json_escape_str(id, &mut out);
                    out.push_str(",\"name\":");
                    json_escape_str(name, &mut out);
                    out.push_str(",\"input\":");
                    ser_json(parsed_input, &mut out);
                    out.push('}');
                }
            }
        }
        out.push_str("]}");

        // Tool results user message
        out.push_str(",{\"role\":\"user\",\"content\":[");
        for (i, (id, result, is_error)) in tool_results.iter().enumerate() {
            if i > 0 { out.push(','); }
            out.push_str("{\"type\":\"tool_result\",\"tool_use_id\":");
            json_escape_str(id, &mut out);
            out.push_str(",\"content\":");
            json_escape_str(result, &mut out);
            if *is_error {
                out.push_str(",\"is_error\":true");
            }
            out.push('}');
        }
        out.push_str("]}");
    }

    out.push_str("]}");
    out
}

