/* ============ Dynamic Buffer ============ */
typedef struct { char *d; size_t len, cap; } Buf;
static void buf_init(Buf *b){b->d=NULL;b->len=0;b->cap=0;}
static void buf_ensure(Buf *b,size_t n){
    if(b->len+n>b->cap){b->cap=(b->len+n)*2+64;b->d=realloc(b->d,b->cap);}
}
static void buf_putc(Buf *b,char c){buf_ensure(b,1);b->d[b->len++]=c;}
static void buf_puts(Buf *b,const char *s){size_t l=strlen(s);buf_ensure(b,l);memcpy(b->d+b->len,s,l);b->len+=l;}
static void buf_putn(Buf *b,const char *s,size_t n){buf_ensure(b,n);memcpy(b->d+b->len,s,n);b->len+=l;}
static char *buf_str(Buf *b){buf_ensure(b,1);b->d[b->len]='\0';return b->d;}

/* ============ Case-insensitive substring ============ */
static char *case_strstr(const char *hay, const char *needle) {
    size_t nl = strlen(needle);
    if (nl == 0) return (char*)hay;
    for (const char *p = hay; *p; p++) {
        if (strncasecmp(p, needle, nl) == 0) return (char*)p;
    }
    return NULL;
}

/* ============ JSON Parser ============ */
typedef enum{JV_NULL,JV_TRUE,JV_FALSE,JV_NUM,JV_STR,JV_ARR,JV_OBJ}JVType;
typedef struct JV{JVType type;double num;char*str;struct JV**arr;int alen;char**keys;struct JV**vals;int olen;}JV;

static JV *jv_new(JVType t){JV*v=calloc(1,sizeof(JV));v->type=t;return v;}
static void jv_free(JV*v){if(!v)return;if(v->str)free(v->str);for(int i=0;i<v->alen;i++)jv_free(v->arr[i]);free(v->arr);for(int i=0;i<v->olen;i++){free(v->keys[i]);jv_free(v->vals[i]);}free(v->keys);free(v->vals);free(v);}

static void skip_ws(const char**p){while(**p==' '||**p=='\t'||**p=='\n'||**p=='\r')(*p)++;}

static char *parse_str_raw(const char**p){
    if(**p!='"')return NULL;(*p)++;
    Buf b;buf_init(&b);
    while(**p&&**p!='"'){
        if(**p=='\\'){
            (*p)++;
            switch(**p){
                case '"':buf_putc(&b,'"');(*p)++;break;
                case '\\':buf_putc(&b,'\\');(*p)++;break;
                case '/':buf_putc(&b,'/');(*p)++;break;
                case 'b':buf_putc(&b,'\b');(*p)++;break;
                case 'f':buf_putc(&b,'\f');(*p)++;break;
                case 'n':buf_putc(&b,'\n');(*p)++;break;
                case 'r':buf_putc(&b,'\r');(*p)++;break;
                case 't':buf_putc(&b,'\t');(*p)++;break;
                case 'u':{
                    (*p)++;
                    unsigned int cp=0;
                    for(int i=0;i<4;i++){
                        char c=**p;unsigned int d;
                        if(c>='0'&&c<='9')d=c-'0';
                        else if(c>='a'&&c<='f')d=c-'a'+10;
                        else if(c>='A'&&c<='F')d=c-'A'+10;
                        else d=0;
                        cp=cp*16+d;(*p)++;
                    }
                    if(cp>=0xD800&&cp<=0xDBFF){
                        if(**p=='\\'&&(*p)[1]=='u'){
                            (*p)+=2;
                            unsigned int lo=0;
                            for(int i=0;i<4;i++){
                                char c=**p;unsigned int d;
                                if(c>='0'&&c<='9')d=c-'0';
                                else if(c>='a'&&c<='f')d=c-'a'+10;
                                else if(c>='A'&&c<='F')d=c-'A'+10;
                                else d=0;
                                lo=lo*16+d;(*p)++;
                            }
                            if(lo>=0xDC00&&lo<=0xDFFF)
                                cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                            else cp=0xFFFD;
                        } else cp=0xFFFD;
                    }
                    if(cp<0x80){buf_putc(&b,(char)cp);}
                    else if(cp<0x800){buf_putc(&b,(char)(0xC0|(cp>>6)));buf_putc(&b,(char)(0x80|(cp&0x3F)));}
                    else if(cp<0x10000){buf_putc(&b,(char)(0xE0|(cp>>12)));buf_putc(&b,(char)(0x80|((cp>>6)&0x3F)));buf_putc(&b,(char)(0x80|(cp&0x3F)));}
                    else{buf_putc(&b,(char)(0xF0|(cp>>18)));buf_putc(&b,(char)(0x80|((cp>>12)&0x3F)));buf_putc(&b,(char)(0x80|((cp>>6)&0x3F)));buf_putc(&b,(char)(0x80|(cp&0x3F)));}
                    break;
                }
                default:buf_putc(&b,**p);(*p)++;break;
            }
        } else {buf_putc(&b,**p);(*p)++;}
    }
    if(**p=='"')(*p)++;
    buf_putc(&b,'\0');
    return b.d;
}

static JV *parse_val(const char**p){
    skip_ws(p);
    if(!**p)return jv_new(JV_NULL);
    if(**p=='"'){JV*v=jv_new(JV_STR);v->str=parse_str_raw(p);return v;}
    if(**p=='{'){
        (*p)++;JV*v=jv_new(JV_OBJ);int cap=8;
        v->keys=malloc(cap*sizeof(char*));v->vals=malloc(cap*sizeof(JV*));
        skip_ws(p);
        if(**p=='}')(*p)++;
        else{
            for(;;){
                skip_ws(p);
                char *k=parse_str_raw(p);
                skip_ws(p);if(**p==':')(*p)++;
                JV *val=parse_val(p);
                if(v->olen>=cap){cap*=2;v->keys=realloc(v->keys,cap*sizeof(char*));v->vals=realloc(v->vals,cap*sizeof(JV*));}
                v->keys[v->olen]=k;v->vals[v->olen]=val;v->olen++;
                skip_ws(p);
                if(**p==',')(*p)++;else break;
            }
            if(**p=='}')(*p)++;
        }
        return v;
    }
    if(**p=='['){
        (*p)++;JV*v=jv_new(JV_ARR);int cap=8;
        v->arr=malloc(cap*sizeof(JV*));
        skip_ws(p);
        if(**p==']')(*p)++;
        else{
            for(;;){
                JV *item=parse_val(p);
                if(v->alen>=cap){cap*=2;v->arr=realloc(v->arr,cap*sizeof(JV*));}
                v->arr[v->alen++]=item;
                skip_ws(p);
                if(**p==',')(*p)++;else break;
            }
            if(**p==']')(*p)++;
        }
        return v;
    }
    if(strncmp(*p,"true",4)==0){*p+=4;return jv_new(JV_TRUE);}
    if(strncmp(*p,"false",5)==0){*p+=5;return jv_new(JV_FALSE);}
    if(strncmp(*p,"null",4)==0){*p+=4;return jv_new(JV_NULL);}
    char *end;double d=strtod(*p,&end);*p=end;
    JV*v=jv_new(JV_NUM);v->num=d;return v;
}

static JV *json_parse(const char *s){const char*p=s;return parse_val(&p);}

/* ============ JSON Serializer ============ */
static void ser_str(Buf *b,const char *s){
    buf_putc(b,'"');
    if(!s){buf_putc(b,'"');return;}
    for(const char*c=s;*c;c++){
        unsigned char ch=(unsigned char)*c;
        if(ch=='"')buf_puts(b,"\\\"");
        else if(ch=='\\')buf_puts(b,"\\\\");
        else if(ch=='\n')buf_puts(b,"\\n");
        else if(ch=='\r')buf_puts(b,"\\r");
        else if(ch=='\t')buf_puts(b,"\\t");
        else if(ch=='\b')buf_puts(b,"\\b");
        else if(ch=='\f')buf_puts(b,"\\f");
        else if(ch<0x20){char tmp[8];sprintf(tmp,"\\u%04x",ch);buf_puts(b,tmp);}
        else buf_putc(b,*c);
    }
    buf_putc(b,'"');
}

static void ser_val(Buf *b,JV *v){
    if(!v){buf_puts(b,"null");return;}
    switch(v->type){
        case JV_NULL:buf_puts(b,"null");break;
        case JV_TRUE:buf_puts(b,"true");break;
        case JV_FALSE:buf_puts(b,"false");break;
        case JV_NUM:{
            if(v->num==(long long)v->num&&fabs(v->num)<1e15){char t[32];sprintf(t,"%lld",(long long)v->num);buf_puts(b,t);}
            else{char t[64];sprintf(t,"%.17g",v->num);buf_puts(b,t);}
            break;
        }
        case JV_STR:ser_str(b,v->str?v->str:"");break;
        case JV_ARR:
            buf_putc(b,'[');
            for(int i=0;i<v->alen;i++){if(i)buf_putc(b,',');ser_val(b,v->arr[i]);}
            buf_putc(b,']');break;
        case JV_OBJ:
            buf_putc(b,'{');
            for(int i=0;i<v->olen;i++){if(i)buf_putc(b,',');ser_str(b,v->keys[i]);buf_putc(b,':');ser_val(b,v->vals[i]);}
            buf_putc(b,'}');break;
    }
}

static JV *jv_get(JV *obj,const char *key){
    if(!obj||obj->type!=JV_OBJ)return NULL;
    for(int i=0;i<obj->olen;i++)if(strcmp(obj->keys[i],key)==0)return obj->vals[i];
    return NULL;
}
static const char *jv_str(JV *obj,const char *key){
    JV*v=jv_get(obj,key);return(v&&v->type==JV_STR)?v->str:NULL;
}
static int jv_int(JV *obj,const char *key){
    JV*v=jv_get(obj,key);return(v&&v->type==JV_NUM)?(int)v->num:0;
}

/* ============ UTF-8 Utilities ============ */
static int utf8_decode(const char*s,unsigned int*cp){
    unsigned char c=(unsigned char)s[0];
    if(c<0x80){*cp=c;return 1;}
    if((c&0xE0)==0xC0){*cp=((c&0x1F)<<6)|((unsigned char)s[1]&0x3F);return 2;}
    if((c&0xF0)==0xE0){*cp=((c&0x0F)<<12)|(((unsigned char)s[1]&0x3F)<<6)|((unsigned char)s[2]&0x3F);return 3;}
    if((c&0xF8)==0xF0){*cp=((c&0x07)<<18)|(((unsigned char)s[1]&0x3F)<<12)|(((unsigned char)s[2]&0x3F)<<6)|((unsigned char)s[3]&0x3F);return 4;}
    *cp=0xFFFD;return 1;
}
static int utf8_encode(unsigned int cp,char*buf){
    if(cp<0x80){buf[0]=(char)cp;return 1;}
    if(cp<0x800){buf[0]=(char)(0xC0|(cp>>6));buf[1]=(char)(0x80|(cp&0x3F));return 2;}
    if(cp<0x10000){buf[0]=(char)(0xE0|(cp>>12));buf[1]=(char)(0x80|((cp>>6)&0x3F));buf[2]=(char)(0x80|(cp&0x3F));return 3;}
    buf[0]=(char)(0xF0|(cp>>18));buf[1]=(char)(0x80|((cp>>12)&0x3F));buf[2]=(char)(0x80|((cp>>6)&0x3F));buf[3]=(char)(0x80|(cp&0x3F));return 4;
}
static int count_codepoints(const char*s){int n=0;while(*s){unsigned int cp;int l=utf8_decode(s,&cp);s+=l;n++;}return n;}
static int count_utf16(const char*s){int n=0;while(*s){unsigned int cp;int l=utf8_decode(s,&cp);n+=(cp>0xFFFF)?2:1;s+=l;}return n;}
static char *reverse_utf8(const char*s){
    int n=0;
    const char*tmp=s;
    while(*tmp){unsigned int cp;int l=utf8_decode(tmp,&cp);tmp+=l;n++;}
    unsigned int *cps=malloc((n+1)*sizeof(unsigned int));
    int idx=0;tmp=s;
    while(*tmp){unsigned int cp;int l=utf8_decode(tmp,&cp);cps[idx++]=cp;tmp+=l;}
    Buf b;buf_init(&b);
    for(int i=n-1;i>=0;i--){char enc[4];int l=utf8_encode(cps[i],enc);buf_putn(&b,enc,l);}
    buf_putc(&b,'\0');
    free(cps);
    return b.d;
}

/* ============ Output escaping ============ */
static void esc_print(Buf *out,const char *s){
    if(!s)return;
    for(const char*c=s;*c;c++){
        unsigned char ch=(unsigned char)*c;
        if(ch=='\\')buf_puts(out,"\\\\");
        else if(ch=='\n')buf_puts(out,"\\n");
        else if(ch=='\r')buf_puts(out,"\\r");
        else if(ch=='\t')buf_puts(out,"\\t");
        else buf_putc(out,*c);
    }
}

/* ============ HTTP Client ============ */
typedef struct {char host[256];int port;char path[512];}URL;
static void parse_url(const char*url,URL*u){
    memset(u,0,sizeof(*u));
    const char*p=url;
    if(strncmp(p,"http://",7)==0)p+=7;
    const char*slash=strchr(p,'/');
    const char*colon=NULL;
    if(slash){
        const char*pp=p;while(pp<slash&&*pp){if(*pp==':')colon=pp;pp++;}
        if(colon){int hl=colon-p;if(hl>255)hl=255;memcpy(u->host,p,hl);u->host[hl]=0;u->port=atoi(colon+1);}
        else{int hl=slash-p;if(hl>255)hl=255;memcpy(u->host,p,hl);u->host[hl]=0;u->port=80;}
        strncpy(u->path,slash,511);
    } else {
        colon=strchr(p,':');
        if(colon){int hl=colon-p;if(hl>255)hl=255;memcpy(u->host,p,hl);u->host[hl]=0;u->port=atoi(colon+1);}
        else{strncpy(u->host,p,255);u->port=80;}
        strcpy(u->path,"");
    }
}

static char *read_file(const char*path){
    FILE*f=fopen(path,"rb");if(!f)return NULL;
    fseek(f,0,SEEK_END);long sz=ftell(f);fseek(f,0,SEEK_SET);
    char*buf=malloc(sz+1);size_t rd=fread(buf,1,sz,f);buf[rd]=0;fclose(f);return buf;
}

static int http_connect(URL*u){
    struct addrinfo hints={0},*res;
    hints.ai_family=AF_INET;hints.ai_socktype=SOCK_STREAM;
    char portstr[16];sprintf(portstr,"%d",u->port);
    if(getaddrinfo(u->host,portstr,&hints,&res)!=0)return -1;
    int fd=socket(res->ai_family,res->ai_socktype,res->ai_protocol);
    if(fd<0){freeaddrinfo(res);return -1;}
    if(connect(fd,res->ai_addr,res->ai_addrlen)<0){close(fd);freeaddrinfo(res);return -1;}
    freeaddrinfo(res);return fd;
}

static void send_all(int fd,const char*buf,size_t len){
    while(len>0){ssize_t w=write(fd,buf,len);if(w<=0)break;buf+=w;len-=w;}
}

static char *read_until_eof(int fd,size_t*out_len){
    size_t cap=65536,len=0;char*buf=malloc(cap);
    for(;;){
        if(len>=cap){cap*=2;buf=realloc(buf,cap);}
        ssize_t r=read(fd,buf+len,cap-len);
        if(r<=0)break;
        len+=r;
    }
    *out_len=len;return buf;
}

/* ============ Chunked Transfer Decoder ============ */
static char *decode_chunked(const char*raw,size_t raw_len,size_t*out_len){
    Buf out;buf_init(&out);
    size_t pos=0;
    while(pos<raw_len){
        /* read hex size */
        size_t sz=0;
        while(pos<raw_len&&raw[pos]!='\r'&&raw[pos]!='\n'){
            char c=raw[pos];
            if(c>='0'&&c<='9')sz=sz*16+(c-'0');
            else if(c>='a'&&c<='f')sz=sz*16+(c-'a'+10);
            else if(c>='A'&&c<='F')sz=sz*16+(c-'A'+10);
            else if(c==';') { /* chunk extension, skip to EOL */
                while(pos<raw_len&&raw[pos]!='\r'&&raw[pos]!='\n')pos++;
                break;
            }
            pos++;
        }
        /* skip CRLF or LF */
        if(pos<raw_len&&raw[pos]=='\r')pos++;
        if(pos<raw_len&&raw[pos]=='\n')pos++;
        if(sz==0)break;
        if(pos+sz>raw_len)sz=raw_len-pos;
        buf_putn(&out,raw+pos,sz);
        pos+=sz;
        /* skip trailing CRLF */
        if(pos<raw_len&&raw[pos]=='\r')pos++;
        if(pos<raw_len&&raw[pos]=='\n')pos++;
    }
    buf_putc(&out,'\0');
    *out_len=out.len;
    return out.d;
}

/* ============ SSE Parser & Event Processing ============ */
typedef struct {
    char *type;
    char *thinking;
    char *signature;
    char *text;
    char *id;
    char *name;
    char *partial_json;
    char *result;
    int is_error;
} Block;

typedef struct {
    Block *blocks;int nblocks,cap;
    char *stop_reason;
    int input_tokens,output_tokens,cache_read;
} Reply;

static void reply_init(Reply*r){memset(r,0,sizeof(*r));}
static Block *get_block(Reply*r,int idx){
    while(r->nblocks<=idx){
        if(r->nblocks>=r->cap){r->cap=r->cap?r->cap*2:8;r->blocks=realloc(r->blocks,r->cap*sizeof(Block));memset(&r->blocks[r->nblocks],0,(r->cap-r->nblocks)*sizeof(Block));}
        r->nblocks++;
    }
    return &r->blocks[idx];
}
static void append_str(char **dst,const char *src,size_t slen){
    size_t old=(*dst)?strlen(*dst):0;
    char *nd=realloc(*dst,old+slen+1);
    if(!*dst)nd[0]=0;
    memcpy(nd+old,src,slen);nd[old+slen]=0;
    *dst=nd;
}

static void process_sse(const char*stream,size_t slen,Reply*rep){
    Buf line;buf_init(&line);
    char *ev_name=NULL;
    Buf data;buf_init(&data);
    int has_data=0;

    for(size_t i=0;i<=slen;i++){
        char c=(i<slen)?stream[i]:'\n';
        if(c=='\n'){
            if(line.len==0){
                /* blank line: dispatch event */
                if(has_data){
                    buf_putc(&data,'\0');
                    JV *ev=json_parse(data.d);
                    if(ev){
                        const char*etype=jv_str(ev,"type");
                        if(!etype)etype=ev_name;
                        if(etype){
                            if(strcmp(etype,"message_start")==0){
                                JV*msg=jv_get(ev,"message");
                                if(msg){JV*usage=jv_get(msg,"usage");if(usage){
                                    rep->input_tokens+=jv_int(usage,"input_tokens");
                                    rep->cache_read+=jv_int(usage,"cache_read_input_tokens");
                                }}
                            } else if(strcmp(etype,"content_block_start")==0){
                                int idx=jv_int(ev,"index");
                                JV*cb=jv_get(ev,"content_block");
                                Block*bl=get_block(rep,idx);
                                if(cb){
                                    const char*bt=jv_str(cb,"type");
                                    if(bt)bl->type=strdup(bt);
                                    if(bt&&strcmp(bt,"tool_use")==0){
                                        const char*id=jv_str(cb,"id");if(id)bl->id=strdup(id);
                                        const char*nm=jv_str(cb,"name");if(nm)bl->name=strdup(nm);
                                        bl->partial_json=strdup("");
                                    }
                                    if(bt&&strcmp(bt,"thinking")==0){bl->thinking=strdup("");bl->signature=strdup("");}
                                    if(bt&&strcmp(bt,"text")==0){bl->text=strdup("");}
                                }
                            } else if(strcmp(etype,"content_block_delta")==0){
                                int idx=jv_int(ev,"index");
                                JV*delta=jv_get(ev,"delta");
                                if(delta){
                                    const char*dt=jv_str(delta,"type");
                                    Block*bl=get_block(rep,idx);
                                    if(dt&&strcmp(dt,"thinking_delta")==0){
                                        const char*t=jv_str(delta,"thinking");
                                        if(t){if(!bl->thinking)bl->thinking=strdup("");append_str(&bl->thinking,t,strlen(t));}
                                    } else if(dt&&strcmp(dt,"signature_delta")==0){
                                        const char*t=jv_str(delta,"signature");
                                        if(t){if(!bl->signature)bl->signature=strdup("");append_str(&bl->signature,t,strlen(t));}
                                    } else if(dt&&strcmp(dt,"text_delta")==0){
                                        const char*t=jv_str(delta,"text");
                                        if(t){if(!bl->text)bl->text=strdup("");append_str(&bl->text,t,strlen(t));}
                                    } else if(dt&&strcmp(dt,"input_json_delta")==0){
                                        const char*t=jv_str(delta,"partial_json");
                                        if(t){if(!bl->partial_json)bl->partial_json=strdup("");append_str(&bl->partial_json,t,strlen(t));}
                                    }
                                }
                            } else if(strcmp(etype,"message_delta")==0){
                                JV*delta=jv_get(ev,"delta");
                                if(delta){const char*sr=jv_str(delta,"stop_reason");if(sr)rep->stop_reason=strdup(sr);}
                                JV*usage=jv_get(ev,"usage");
                                if(usage)rep->output_tokens+=jv_int(usage,"output_tokens");
                            }
                        }
                        jv_free(ev);
                    }
                }
                free(ev_name);ev_name=NULL;
                free(data.d);buf_init(&data);has_data=0;
            } else {
                if(line.len>0&&line.d[line.len-1]=='\r')line.len--;
                buf_putc(&line,'\0');
                char*ln=line.d;
                if(ln[0]==':'){/* comment */}
                else if(strncmp(ln,"event:",6)==0){
                    free(ev_name);
                    const char*v=ln+6;if(*v==' ')v++;
                    ev_name=strdup(v);
                } else if(strncmp(ln,"data:",5)==0){
                    const char*v=ln+5;if(*v==' ')v++;
                    if(has_data)buf_putc(&data,'\n');
                    buf_puts(&data,v);has_data=1;
                }
            }
            line.len=0;
        } else {
            buf_putc(&line,c);
        }
    }
    free(line.d);free(ev_name);free(data.d);
}

/* ============ Tool Execution ============ */
static char *exec_tool(const char*name,const char*input_json,int*is_error){
    JV*inp=json_parse(input_json);
    if(!inp||inp->type!=JV_OBJ){*is_error=1;return strdup("unknown tool: invalid input");}
    if(strcmp(name,"measure")==0){
        const char*text=jv_str(inp,"text");
        const char*unit=jv_str(inp,"unit");
        if(!text)text="";if(!unit)unit="";
        if(strcmp(unit,"code_points")==0){
            char tmp[32];sprintf(tmp,"%d",count_codepoints(text));*is_error=0;
            jv_free(inp);return strdup(tmp);
        } else if(strcmp(unit,"utf8_bytes")==0){
            char tmp[32];sprintf(tmp,"%zu",strlen(text));*is_error=0;
            jv_free(inp);return strdup(tmp);
        } else if(strcmp(unit,"utf16_units")==0){
            char tmp[32];sprintf(tmp,"%d",count_utf16(text));*is_error=0;
            jv_free(inp);return strdup(tmp);
        } else {
            char tmp[256];sprintf(tmp,"unsupported unit: %s",unit);*is_error=1;
            jv_free(inp);return strdup(tmp);
        }
    } else if(strcmp(name,"reverse")==0){
        const char*text=jv_str(inp,"text");
        if(!text)text="";
        char*r=reverse_utf8(text);*is_error=0;
        jv_free(inp);return r;
    } else {
        char tmp[256];sprintf(tmp,"unknown tool: %s",name);*is_error=1;
        jv_free(inp);return strdup(tmp);
    }
}

/* ============ Build Request JSON ============ */
static char *build_request1(const char*model,int max_tokens,int thinking_budget,const char*system,JV*tools,const char*prompt){
    Buf b;buf_init(&b);
    buf_putc(&b,'{');
    buf_puts(&b,"\"model\":");ser_str(&b,model);
    buf_puts(&b,",\"max_tokens\":");{char t[16];sprintf(t,"%d",max_tokens);buf_puts(&b,t);}
    buf_puts(&b,",\"stream\":true");
    buf_puts(&b,",\"thinking\":{\"type\":\"enabled\",\"budget_tokens\":");{char t[16];sprintf(t,"%d",thinking_budget);buf_puts(&b,t);}
    buf_putc(&b,'}');
    buf_puts(&b,",\"system\":");ser_str(&b,system);
    buf_puts(&b,",\"tools\":");ser_val(&b,tools);
    buf_puts(&b,",\"messages\":[{\"role\":\"user\",\"content\":");ser_str(&b,prompt);
    buf_puts(&b,"}]}");
    buf_putc(&b,'\0');
    return b.d;
}

static char *build_request2(const char*model,int max_tokens,int thinking_budget,const char*system,JV*tools,const char*prompt,Reply*rep){
    Buf b;buf_init(&b);
    buf_putc(&b,'{');
    buf_puts(&b,"\"model\":");ser_str(&b,model);
    buf_puts(&b,",\"max_tokens\":");{char t[16];sprintf(t,"%d",max_tokens);buf_puts(&b,t);}
    buf_puts(&b,",\"stream\":true");
    buf_puts(&b,",\"thinking\":{\"type\":\"enabled\",\"budget_tokens\":");{char t[16];sprintf(t,"%d",thinking_budget);buf_puts(&b,t);}
    buf_putc(&b,'}');
    buf_puts(&b,",\"system\":");ser_str(&b,system);
    buf_puts(&b,",\"tools\":");ser_val(&b,tools);
    buf_puts(&b,",\"messages\":[");
    /* user message */
    buf_puts(&b,"{\"role\":\"user\",\"content\":");ser_str(&b,prompt);buf_putc(&b,'}');
    /* assistant message */
    buf_puts(&b,",{\"role\":\"assistant\",\"content\":[");
    for(int i=0;i<rep->nblocks;i++){
        if(i)buf_putc(&b,',');
        Block*bl=&rep->blocks[i];
        if(!bl->type)continue;
        if(strcmp(bl->type,"thinking")==0){
            buf_puts(&b,"{\"type\":\"thinking\",\"thinking\":");ser_str(&b,bl->thinking?bl->thinking:"");
            buf_puts(&b,",\"signature\":");ser_str(&b,bl->signature?bl->signature:"");
            buf_putc(&b,'}');
        } else if(strcmp(bl->type,"text")==0){
            buf_puts(&b,"{\"type\":\"text\",\"text\":");ser_str(&b,bl->text?bl->text:"");
            buf_putc(&b,'}');
        } else if(strcmp(bl->type,"tool_use")==0){
            buf_puts(&b,"{\"type\":\"tool_use\",\"id\":");ser_str(&b,bl->id?bl->id:"");
            buf_puts(&b,",\"name\":");ser_str(&b,bl->name?bl->name:"");
            buf_puts(&b,",\"input\":");
            JV*inp=json_parse(bl->partial_json?bl->partial_json:"{}");
            ser_val(&b,inp);
            jv_free(inp);
            buf_putc(&b,'}');
        }
    }
    buf_puts(&b,"]}");
    /* tool results user message */
    buf_puts(&b,",{\"role\":\"user\",\"content\":[");
    int first=1;
    for(int i=0;i<rep->nblocks;i++){
        Block*bl=&rep->blocks[i];
        if(!bl->type||strcmp(bl->type,"tool_use")!=0)continue;
        if(!first)buf_putc(&b,',');first=0;
        buf_puts(&b,"{\"type\":\"tool_result\",\"tool_use_id\":");ser_str(&b,bl->id?bl->id:"");
        buf_puts(&b,",\"content\":");ser_str(&b,bl->result?bl->result:"");
        if(bl->is_error)buf_puts(&b,",\"is_error\":true");
        buf_putc(&b,'}');
    }
    buf_puts(&b,"]}]}");
    buf_putc(&b,'\0');
    return b.d;
}

/* ============ Send HTTP Request & Read Response ============ */
static int send_and_read(URL*u,const char*api_key,const char*body,size_t body_len,char**out_body,size_t*out_body_len,int*out_status){
    int fd=http_connect(u);
    if(fd<0)return -1;
    char endpoint[600];
    snprintf(endpoint,sizeof(endpoint),"%s/v1/messages",u->path);
    Buf req;buf_init(&req);
    buf_puts(&req,"POST ");buf_puts(&req,endpoint);buf_puts(&req," HTTP/1.1\r\n");
    buf_puts(&req,"Host: ");buf_puts(&req,u->host);{char t[16];sprintf(t,":%d",u->port);buf_puts(&req,t);}
    buf_puts(&req,"\r\n");
    buf_puts(&req,"Content-Length: ");{char t[32];sprintf(t,"%zu",body_len);buf_puts(&req,t);}
    buf_puts(&req,"\r\n");
    buf_puts(&req,"x-api-key: ");buf_puts(&req,api_key);buf_puts(&req,"\r\n");
    buf_puts(&req,"anthropic-version: 2023-06-01\r\n");
    buf_puts(&req,"content-type: application/json\r\n");
    buf_puts(&req,"\r\n");
    buf_putn(&req,body,body_len);
    send_all(fd,req.d,req.len);
    free(req.d);

    /* read headers */
    size_t hcap=8192,hlen=0;char*hbuf=malloc(hcap);
    int found=0;
    while(!found){
        if(hlen>=hcap-1){hcap*=2;hbuf=realloc(hbuf,hcap);}
        ssize_t r=read(fd,hbuf+hlen,hcap-hlen-1);
        if(r<=0)break;
        hlen+=r;hbuf[hlen]=0;
        if(strstr(hbuf,"\r\n\r\n"))found=1;
    }
    /* parse status */
    int status=0;
    if(strncmp(hbuf,"HTTP/",5)==0){
        const char*sp=hbuf+9;
        status=atoi(sp);
    }
    *out_status=status;

    /* find Content-Length */
    size_t clen=0;
    {
        char*cl=case_strstr(hbuf,"content-length:");
        if(cl){cl+=15;while(*cl==' ')cl++;clen=atoi(cl);}
    }

    /* find where body starts (after \r\n\r\n) */
    char*hdr_end=strstr(hbuf,"\r\n\r\n");
    size_t hdr_size=hdr_end?(size_t)(hdr_end-hbuf+4):hlen;

    if(status==200){
        /* chunked - read rest until EOF */
        size_t rl;char*rest=read_until_eof(fd,&rl);
        /* prepend any body bytes already in hbuf */
        size_t pre=hlen-hdr_size;
        size_t total=pre+rl;
        char*raw=malloc(total+1);
        memcpy(raw,hbuf+hdr_size,pre);
        memcpy(raw+pre,rest,rl);
        raw[total]=0;
        free(rest);
        size_t dl;char*dec=decode_chunked(raw,total,&dl);
        free(raw);
        *out_body=dec;*out_body_len=dl;
    } else {
        /* read Content-Length bytes */
        size_t pre=hlen-hdr_size;
        char*body_buf=malloc(clen+1);
        if(pre>0){size_t cp=pre<clen?pre:clen;memcpy(body_buf,hbuf+hdr_size,cp);pre=cp;}
        while(pre<clen){
            ssize_t r=read(fd,body_buf+pre,clen-pre);
            if(r<=0)break;pre+=r;
        }
        body_buf[pre]=0;
        *out_body=body_buf;*out_body_len=pre;
    }
    free(hbuf);
    close(fd);
    return 0;
}

/* ============ Print block lines ============ */
static void print_blocks(Buf*out,Reply*rep){
    for(int i=0;i<rep->nblocks;i++){
        Block*bl=&rep->blocks[i];
        if(!bl->type)continue;
        if(strcmp(bl->type,"thinking")==0){
            buf_puts(out,"thinking ");esc_print(out,bl->thinking?bl->thinking:"");buf_putc(out,'\n');
            buf_puts(out,"signature ");esc_print(out,bl->signature?bl->signature:"");buf_putc(out,'\n');
        } else if(strcmp(bl->type,"text")==0){
            buf_puts(out,"text ");esc_print(out,bl->text?bl->text:"");buf_putc(out,'\n');
        } else if(strcmp(bl->type,"tool_use")==0){
            buf_puts(out,"tool_use ");esc_print(out,bl->id?bl->id:"");buf_putc(out,' ');
            esc_print(out,bl->name?bl->name:"");buf_putc(out,' ');
            esc_print(out,bl->partial_json?bl->partial_json:"");buf_putc(out,'\n');
        }
    }
}

/* ============ Main ============ */
int main(int argc,char**argv){
    if(argc<3){fprintf(stderr,"usage: %s <data_dir> <base_url>\n",argv[0]);return 1;}
    const char*data_dir=argv[1];
    const char*base_url=argv[2];

    /* read request.json */
    char rpath[1024];snprintf(rpath,sizeof(rpath),"%s/request.json",data_dir);
    char*rj=read_file(rpath);
    if(!rj){fprintf(stderr,"cannot read %s\n",rpath);return 1;}
    JV*req=json_parse(rj);
    const char*api_key=jv_str(req,"api_key");
    const char*model=jv_str(req,"model");
    int max_tokens=jv_int(req,"max_tokens");
    int thinking_budget=jv_int(req,"thinking_budget");
    const char*system=jv_str(req,"system");if(!system)system="";
    const char*prompt=jv_str(req,"prompt");if(!prompt)prompt="";
    JV*tools=jv_get(req,"tools");

    URL url;parse_url(base_url,&url);

    Buf out;buf_init(&out);

    /* ===== Request 1 ===== */
    buf_puts(&out,"request 1\n");
    char*body1=build_request1(model,max_tokens,thinking_budget,system,tools,prompt);
    char*resp_body=NULL;size_t resp_len=0;int status=0;
    if(send_and_read(&url,api_key,body1,strlen(body1),&resp_body,&resp_len,&status)<0){
        buf_puts(&out,"ERROR 0: connection failed\n");
        fwrite(out.d,1,out.len,stdout);return 0;
    }
    free(body1);
    if(status!=200){
        JV*err=json_parse(resp_body);
        const char*etype="unknown";const char*emsg="";
        if(err){JV*e=jv_get(err,"error");if(e){const char*t=jv_str(e,"type");if(t)etype=t;const char*m=jv_str(e,"message");if(m)emsg=m;}}
        buf_puts(&out,"ERROR ");{char t[16];sprintf(t,"%d",status);buf_puts(&out,t);}
        buf_putc(&out,' ');buf_puts(&out,etype);buf_puts(&out,": ");buf_puts(&out,emsg);buf_putc(&out,'\n');
        fwrite(out.d,1,out.len,stdout);return 0;
    }
    Reply rep1;reply_init(&rep1);
    process_sse(resp_body,resp_len,&rep1);
    free(resp_body);

    print_blocks(&out,&rep1);
    buf_puts(&out,"stop_reason ");buf_puts(&out,rep1.stop_reason?rep1.stop_reason:"");buf_putc(&out,'\n');

    /* Execute tools */
    for(int i=0;i<rep1.nblocks;i++){
        Block*bl=&rep1.blocks[i];
        if(!bl->type||strcmp(bl->type,"tool_use")!=0)continue;
        int is_err=0;
        char*result=exec_tool(bl->name?bl->name:"",bl->partial_json?bl->partial_json:"{}",&is_err);
        bl->result=result;bl->is_error=is_err;
        if(is_err)buf_puts(&out,"error ");else buf_puts(&out,"result ");
        esc_print(&out,bl->id?bl->id:"");buf_putc(&out,' ');
        esc_print(&out,result);buf_putc(&out,'\n');
    }

    /* ===== Request 2 ===== */
    buf_puts(&out,"request 2\n");
    char*body2=build_request2(model,max_tokens,thinking_budget,system,tools,prompt,&rep1);
    if(send_and_read(&url,api_key,body2,strlen(body2),&resp_body,&resp_len,&status)<0){
        buf_puts(&out,"ERROR 0: connection failed\n");
        fwrite(out.d,1,out.len,stdout);return 0;
    }
    free(body2);
    if(status!=200){
        JV*err=json_parse(resp_body);
        const char*etype="unknown";const char*emsg="";
        if(err){JV*e=jv_get(err,"error");if(e){const char*t=jv_str(e,"type");if(t)etype=t;const char*m=jv_str(e,"message");if(m)emsg=m;}}
        buf_puts(&out,"ERROR ");{char t[16];sprintf(t,"%d",status);buf_puts(&out,t);}
        buf_putc(&out,' ');buf_puts(&out,etype);buf_puts(&out,": ");buf_puts(&out,emsg);buf_putc(&out,'\n');
        fwrite(out.d,1,out.len,stdout);return 0;
    }
    Reply rep2;reply_init(&rep2);
    process_sse(resp_body,resp_len,&rep2);
    free(resp_body);

    print_blocks(&out,&rep2);
    buf_puts(&out,"stop_reason ");buf_puts(&out,rep2.stop_reason?rep2.stop_reason:"");buf_putc(&out,'\n');

    /* Usage */
    int total_in=rep1.input_tokens+rep2.input_tokens;
    int total_out=rep1.output_tokens+rep2.output_tokens;
    int total_cache=rep1.cache_read+rep2.cache_read;
    buf_puts(&out,"usage input=");{char t[32];sprintf(t,"%d",total_in);buf_puts(&out,t);}
    buf_puts(&out," output=");{char t[32];sprintf(t,"%d",total_out);buf_puts(&out,t);}
    buf_puts(&out," cache_read=");{char t[32];sprintf(t,"%d",total_cache);buf_puts(&out,t);}
    buf_putc(&out,'\n');

    fwrite(out.d,1,out.len,stdout);
    return 0;
}

use std::env;
use std::fs;

#[derive(Clone)]
enum Val {
    Null,
    Int(i64),
    Real(f64),
    Text(Vec<u8>),
    Blob(Vec<u8>),
}

fn read_varint(data: &[u8], pos: &mut usize) -> i64 {
    let mut val: u64 = 0;
    for i in 0..9 {
        let b = data[*pos];
        *pos += 1;
        if i < 8 {
            val = (val << 7) | (b & 0x7f) as u64;
            if b & 0x80 == 0 { break; }
        } else {
            val = (val << 8) | b as u64;
            break;
        }
    }
    val as i64
}

fn serial_size(st: i64) -> usize {
    match st {
        0..=9 | 10 | 11 => match st {
            1 => 1, 2 => 2, 3 => 3, 4 => 4, 5 => 6, 6 => 8, 7 => 8,
            _ => 0,
        },
        n if n >= 12 && n % 2 == 0 => ((n - 12) / 2) as usize,
        n if n >= 13 => ((n - 13) / 2) as usize,
        _ => 0,
    }
}

fn parse_record(payload: &[u8]) -> Vec<Val> {
    if payload.is_empty() { return vec![]; }
    let mut pos = 0;
    let header_size = read_varint(payload, &mut pos) as usize;
    let mut serials = Vec::new();
    while pos < header_size {
        serials.push(read_varint(payload, &mut pos));
    }
    let mut values = Vec::new();
    for &st in &serials {
        let size = serial_size(st);
        match st {
            0 => values.push(Val::Null),
            1 => { values.push(Val::Int(payload[pos] as i8 as i64)); pos += 1; }
            2 => { values.push(Val::Int(i16::from_be_bytes([payload[pos], payload[pos+1]]) as i64)); pos += 2; }
            3 => {
                let mut buf = [0u8; 4];
                if payload[pos] & 0x80 != 0 { buf[0] = 0xFF; }
                buf[1..4].copy_from_slice(&payload[pos..pos+3]);
                values.push(Val::Int(i32::from_be_bytes(buf) as i64)); pos += 3;
            }
            4 => { values.push(Val::Int(i32::from_be_bytes([payload[pos], payload[pos+1], payload[pos+2], payload[pos+3]]) as i64)); pos += 4; }
            5 => {
                let mut buf = [0u8; 8];
                if payload[pos] & 0x80 != 0 { buf[0] = 0xFF; buf[1] = 0xFF; }
                buf[2..8].copy_from_slice(&payload[pos..pos+6]);
                values.push(Val::Int(i64::from_be_bytes(buf))); pos += 6;
            }
            6 => {
                let mut buf = [0u8; 8];
                buf.copy_from_slice(&payload[pos..pos+8]);
                values.push(Val::Int(i64::from_be_bytes(buf))); pos += 8;
            }
            7 => {
                let mut buf = [0u8; 8];
                buf.copy_from_slice(&payload[pos..pos+8]);
                values.push(Val::Real(f64::from_be_bytes(buf))); pos += 8;
            }
            8 => values.push(Val::Int(0)),
            9 => values.push(Val::Int(1)),
            10 | 11 => values.push(Val::Null),
            n if n >= 12 && n % 2 == 0 => { values.push(Val::Text(payload[pos..pos+size].to_vec())); pos += size; }
            n if n >= 13 => { values.push(Val::Blob(payload[pos..pos+size].to_vec())); pos += size; }
            _ => values.push(Val::Null),
        }
    }
    values
}

fn calc_local_size(payload_size: usize, usable: usize) -> usize {
    let max_local = usable.saturating_sub(35);
    if payload_size <= max_local {
        payload_size
    } else {
        let k = 40 + ((payload_size.saturating_sub(40)) * (usable.saturating_sub(12))) / (usable + 31);
        std::cmp::min(k, max_local)
    }
}

fn walk_btree(data: &[u8], page_size: usize, usable: usize, pgno: usize, rows: &mut Vec<(i64, Vec<u8>)>) {
    let hoff = if pgno == 1 { 100 } else { 0 };
    let start = (pgno - 1) * page_size;
    let page = &data[start..start + usable];
    let page_type = page[hoff];
    let num_cells = u16::from_be_bytes([page[hoff + 3], page[hoff + 4]]) as usize;

    if page_type == 13 {
        let cell_ptr_start = hoff + 8;
        for i in 0..num_cells {
            let cell_off = u16::from_be_bytes([page[cell_ptr_start + i * 2], page[cell_ptr_start + i * 2 + 1]]) as usize;
            let mut pos = cell_off;
            let overflow_page = u32::from_be_bytes([page[pos], page[pos+1], page[pos+2], page[pos+3]]) as usize;
            pos += 4;
            let payload_size = read_varint(page, &mut pos) as usize;
            let local_size = calc_local_size(payload_size, usable);
            let mut payload = Vec::with_capacity(payload_size);
            payload.extend_from_slice(&page[pos..pos + local_size]);
            pos += local_size;
            let rowid = read_varint(page, &mut pos);
            if overflow_page != 0 {
                let mut remaining = payload_size - local_size;
                let mut opg = overflow_page;
                while remaining > 0 {
                    let ostart = (opg - 1) * page_size;
                    let next_opg = u32::from_be_bytes([data[ostart], data[ostart+1], data[ostart+2], data[ostart+3]]) as usize;
                    let avail = usable - 4;
                    let to_read = std::cmp::min(avail, remaining);
                    payload.extend_from_slice(&data[ostart + 4..ostart + 4 + to_read]);
                    remaining -= to_read;
                    opg = next_opg;
                    if opg == 0 { break; }
                }
            }
            rows.push((rowid, payload));
        }
    } else if page_type == 2 {
        let cell_ptr_start = hoff + 12;
        for i in 0..num_cells {
            let cell_off = u16::from_be_bytes([page[cell_ptr_start + i * 2], page[cell_ptr_start + i * 2 + 1]]) as usize;
            let child = u32::from_be_bytes([page[cell_off], page[cell_off+1], page[cell_off+2], page[cell_off+3]]) as usize;
            if child > 0 {
                walk_btree(data, page_size, usable, child, rows);
            }
        }
        let right_most = u32::from_be_bytes([page[hoff+8], page[hoff+9], page[hoff+10], page[hoff+11]]) as usize;
        if right_most > 0 {
            walk_btree(data, page_size, usable, right_most, rows);
        }
    }
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc: u32 = 0xFFFFFFFF;
    for &b in data {
        crc ^= b as u32;
        for _ in 0..8 {
            if crc & 1 != 0 { crc = (crc >> 1) ^ 0xEDB88320; }
            else { crc >>= 1; }
        }
    }
    crc ^ 0xFFFFFFFF
}

fn format_real(v: f64) -> String {
    let s = format!("{:.8}", v);
    let dot = s.find('.').unwrap();
    let mut end = s.len();
    while end > dot + 2 && s.as_bytes()[end - 1] == b'0' {
        end -= 1;
    }
    s[..end].to_string()
}

fn format_text(data: &[u8]) -> String {
    let mut result = String::from("\"");
    let mut raw: Vec<u8> = Vec::new();
    for &b in data {
        match b {
            b'\\' => { result.push_str(&String::from_utf8_lossy(&raw)); raw.clear(); result.push_str("\\\\"); }
            b'"' => { result.push_str(&String::from_utf8_lossy(&raw)); raw.clear(); result.push_str("\\\""); }
            b'\n' => { result.push_str(&String::from_utf8_lossy(&raw)); raw.clear(); result.push_str("\\n"); }
            b'\r' => { result.push_str(&String::from_utf8_lossy(&raw)); raw.clear(); result.push_str("\\r"); }
            b'\t' => { result.push_str(&String::from_utf8_lossy(&raw)); raw.clear(); result.push_str("\\t"); }
            b if b < 0x20 || b == 0x7f => {
                result.push_str(&String::from_utf8_lossy(&raw)); raw.clear();
                result.push_str(&format!("\\x{:02X}", b));
            }
            _ => { raw.push(b); }
        }
    }
    result.push_str(&String::from_utf8_lossy(&raw));
    result.push('"');
    result
}

fn format_value(v: &Val) -> String {
    match v {
        Val::Null => "NULL".to_string(),
        Val::Int(i) => format!("{}", i),
        Val::Real(r) => format_real(*r),
        Val::Text(t) => {
            if t.len() <= 100 {
                format_text(t)
            } else {
                format!("<TEXT len={} crc32={:08x}>", t.len(), crc32(t))
            }
        }
        Val::Blob(b) => {
            if b.len() <= 100 {
                let hex: String = b.iter().map(|x| format!("{:02X}", x)).collect();
                format!("X'{}'", hex)
            } else {
                format!("<BLOB len={} crc32={:08x}>", b.len(), crc32(b))
            }
        }
    }
}

fn parse_create_table(sql: &str) -> Vec<(String, bool)> {
    let sql_lower = sql.to_lowercase();
    let idx = sql_lower.find("create table").unwrap() + 12;
    let mut pos = idx;
    let bytes = sql.as_bytes();

    // skip whitespace
    while pos < bytes.len() && (bytes[pos] as char).is_whitespace() { pos += 1; }

    // skip table name
    if pos < bytes.len() && bytes[pos] == b'"' {
        pos += 1;
        while pos < bytes.len() && bytes[pos] != b'"' { pos += 1; }
        pos += 1;
    } else {
        while pos < bytes.len() && !(bytes[pos] as char).is_whitespace() && bytes[pos] != b'(' { pos += 1; }
    }

    // skip whitespace
    while pos < bytes.len() && (bytes[pos] as char).is_whitespace() { pos += 1; }

    // expect '('
    assert_eq!(bytes[pos], b'(');
    pos += 1;

    // find matching ')'
    let content_start = pos;
    let mut depth = 1usize;
    while depth > 0 {
        if bytes[pos] == b'(' { depth += 1; }
        else if bytes[pos] == b')' { depth -= 1; }
        pos += 1;
    }
    let content_end = pos - 1;
    let content = &sql[content_start..content_end];

    // split by top-level commas
    let mut defs: Vec<&str> = Vec::new();
    let mut start = 0;
    let mut depth = 0i32;
    for (i, ch) in content.char_indices() {
        match ch {
            '(' => depth += 1,
            ')' => depth -= 1,
            ',' if depth == 0 => { defs.push(&content[start..i]); start = i + 1; }
            _ => {}
        }
    }
    if start < content.len() { defs.push(&content[start..]); }

    let mut columns = Vec::new();
    for def in defs {
        let def = def.trim();
        if def.is_empty() { continue; }
        let def_lower = def.to_lowercase();
        let b = def.as_bytes();
        let mut p = 0;
        // skip whitespace
        while p < b.len() && (b[p] as char).is_whitespace() { p += 1; }
        // read column name
        let col_name;
        if p < b.len() && b[p] == b'"' {
            p += 1;
            let s = p;
            while p < b.len() && b[p] != b'"' { p += 1; }
            col_name = def[s..p].to_string();
            p += 1;
        } else {
            let s = p;
            while p < b.len() && !(b[p] as char).is_whitespace() && b[p] != b'(' { p += 1; }
            col_name = def[s..p].to_string();
        }

        // check INTEGER PRIMARY KEY
        let rest = def[p..].trim_start();
        let type_end = rest.find(|c: char| !(c.is_alphanumeric() || c == '_')).unwrap_or(rest.len());
        let type_word = &rest[..type_end];
        let after_type = &rest[type_end..];
        let has_paren = after_type.trim_start().starts_with('(');
        let is_alias = type_word.eq_ignore_ascii_case("INTEGER") && !has_paren && def_lower.contains("primary key");

        columns.push((col_name, is_alias));
    }
    columns
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let path = format!("{}/db.sqlite", dir);
    let data = fs::read(&path).unwrap();

    let mut page_size = u16::from_be_bytes([data[16], data[17]]) as usize;
    if page_size == 1 { page_size = 65536; }
    let reserved = data[20] as usize;
    let usable = page_size - reserved;

    // Read schema (page 1)
    let mut schema_rows: Vec<(i64, Vec<u8>)> = Vec::new();
    walk_btree(&data, page_size, usable, 1, &mut schema_rows);

    // Filter tables
    let mut tables: Vec<(String, usize, String)> = Vec::new();
    for (_rowid, payload) in &schema_rows {
        let values = parse_record(payload);
        if values.len() >= 5 {
            let type_str = match &values[0] {
                Val::Text(t) => String::from_utf8_lossy(t).to_string(),
                _ => continue,
            };
            let name = match &values[1] {
                Val::Text(t) => String::from_utf8_lossy(t).to_string(),
                _ => continue,
            };
            let rootpage = match &values[3] {
                Val::Int(i) => *i as usize,
                _ => continue,
            };
            let sql = match &values[4] {
                Val::Text(t) => String::from_utf8_lossy(t).to_string(),
                _ => continue,
            };
            if type_str == "table" && !name.starts_with("sqlite_") && rootpage > 0 {
                tables.push((name, rootpage, sql));
            }
        }
    }
    tables.sort_by(|a, b| a.0.as_bytes().cmp(b.0.as_bytes()));

    let mut first = true;
    for (name, rootpage, sql) in &tables {
        if !first { println!(); }
        first = false;

        let columns = parse_create_table(sql);

        let mut rows: Vec<(i64, Vec<u8>)> = Vec::new();
        walk_btree(&data, page_size, usable, *rootpage, &mut rows);
        rows.sort_by_key(|r| r.0);

        println!("TABLE {} rows={}", name, rows.len());
        let col_names: Vec<String> = columns.iter().map(|(n, _)| n.clone()).collect();
        println!("COLUMNS {}", col_names.join(", "));

        for (rowid, payload) in &rows {
            let values = parse_record(payload);
            let mut parts: Vec<String> = Vec::new();
            for (i, (_, is_alias)) in columns.iter().enumerate() {
                if *is_alias {
                    parts.push(format!("{}", rowid));
                } else if i < values.len() {
                    parts.push(format_value(&values[i]));
                } else {
                    parts.push("NULL".to_string());
                }
            }
            println!("{}: {}", rowid, parts.join(", "));
        }
    }
}

import * as fs from 'fs';
import * as path from 'path';

function readVarint(buf: Buffer, offset: number): { value: bigint; size: number } {
  let value = 0n;
  let i = 0;
  for (; i < 8; i++) {
    const b = buf[offset + i];
    value = (value << 7n) | BigInt(b & 0x7F);
    if ((b & 0x80) === 0) {
      return { value, size: i + 1 };
    }
  }
  const b = buf[offset + 8];
  value = (value << 8n) | BigInt(b);
  return { value, size: 9 };
}

function readSigned(buf: Buffer, offset: number, size: number): bigint {
  let val = 0n;
  for (let i = 0; i < size; i++) {
    val = (val << 8n) | BigInt(buf[offset + i]);
  }
  if (buf[offset] & 0x80) {
    val -= (1n << BigInt(size * 8));
  }
  return val;
}

function powBigInt(base: bigint, exp: bigint): bigint {
  if (exp === 0n) return 1n;
  let result = 1n;
  let b = base;
  let e = exp;
  while (e > 0n) {
    if (e & 1n) result *= b;
    b *= b;
    e >>= 1n;
  }
  return result;
}

function formatReal(d: number): string {
  if (d === 0) return "0.0";
  if (Number.isInteger(d) && isFinite(d)) {
    return d.toString() + ".0";
  }
  const buf = Buffer.alloc(8);
  buf.writeDoubleBE(d, 0);
  const bits = buf.readBigUInt64BE(0);
  const negative = (bits >> 63n) !== 0n;
  const expBits = Number((bits >> 52n) & 0x7FFn);
  const fracBits = bits & 0xFFFFFFFFFFFFFn;
  let m: bigint, e: bigint;
  if (expBits === 0) {
    m = fracBits;
    e = -1074n;
  } else {
    m = (1n << 52n) | fracBits;
    e = BigInt(expBits) - 1075n;
  }
  if (m === 0n) return "0.0";
  const sign = negative ? "-" : "";
  if (e >= 0n) {
    const intVal = m * (1n << e);
    return sign + intVal.toString() + ".0";
  } else {
    const negE = -e;
    const numerator = m * powBigInt(5n, negE);
    const denom = powBigInt(10n, negE);
    const intPart = numerator / denom;
    const rem = numerator % denom;
    let fracStr = rem.toString().padStart(Number(negE), '0');
    fracStr = fracStr.replace(/0+$/, '');
    if (fracStr === '') fracStr = '0';
    return sign + intPart.toString() + "." + fracStr;
  }
}

function crc32(buf: Buffer): number {
  let crc = 0xFFFFFFFF;
  for (let i = 0; i < buf.length; i++) {
    crc ^= buf[i];
    for (let j = 0; j < 8; j++) {
      if (crc & 1) crc = (crc >>> 1) ^ 0xEDB88320;
      else crc = crc >>> 1;
    }
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

function escapeText(buf: Buffer): string {
  let result = '';
  let asIsStart = 0;
  let i = 0;
  while (i < buf.length) {
    const b = buf[i];
    if (b === 0x5C || b === 0x22 || b === 0x0A || b === 0x0D || b === 0x09 || b < 0x20 || b === 0x7F) {
      if (i > asIsStart) {
        result += buf.slice(asIsStart, i).toString('utf8');
      }
      if (b === 0x5C) result += '\\\\';
      else if (b === 0x22) result += '\\"';
      else if (b === 0x0A) result += '\\n';
      else if (b === 0x0D) result += '\\r';
      else if (b === 0x09) result += '\\t';
      else result += '\\x' + b.toString(16).toUpperCase().padStart(2, '0');
      i++;
      asIsStart = i;
    } else {
      i++;
    }
  }
  if (i > asIsStart) {
    result += buf.slice(asIsStart, i).toString('utf8');
  }
  return result;
}

interface Value {
  type: 'NULL' | 'INTEGER' | 'REAL' | 'TEXT' | 'BLOB';
  value?: bigint;
  dvalue?: number;
  data?: Buffer;
}

function formatValue(v: Value): string {
  switch (v.type) {
    case 'NULL': return 'NULL';
    case 'INTEGER': return (v.value ?? 0n).toString();
    case 'REAL': return formatReal(v.dvalue ?? 0);
    case 'TEXT': {
      const d = v.data!;
      if (d.length <= 100) return '"' + escapeText(d) + '"';
      const c = crc32(d);
      return `<TEXT len=${d.length} crc32=${c.toString(16).padStart(8, '0')}>`;
    }
    case 'BLOB': {
      const d = v.data!;
      if (d.length <= 100) {
        let hex = '';
        for (let i = 0; i < d.length; i++) hex += d[i].toString(16).toUpperCase().padStart(2, '0');
        return `X'${hex}'`;
      }
      const c = crc32(d);
      return `<BLOB len=${d.length} crc32=${c.toString(16).padStart(8, '0')}>`;
    }
  }
}

function parseRecord(payload: Buffer, numCols: number): Value[] {
  if (payload.length === 0) {
    return Array(numCols).fill(null).map(() => ({ type: 'NULL' as const }));
  }
  let pos = 0;
  const headerLen = readVarint(payload, pos);
  pos += headerLen.size;
  const headerSize = Number(headerLen.value);
  const headerEnd = Math.min(headerSize, payload.length);

  const serialTypes: number[] = [];
  while (pos < headerEnd) {
    const st = readVarint(payload, pos);
    pos += st.size;
    serialTypes.push(Number(st.value));
  }
  while (serialTypes.length < numCols) serialTypes.push(0);

  const values: Value[] = [];
  let dataPos = headerEnd;
  for (let i = 0; i < numCols; i++) {
    const st = serialTypes[i];
    if (st === 0) {
      values.push({ type: 'NULL' });
    } else if (st >= 1 && st <= 6) {
      const sz = st === 1 ? 1 : st === 2 ? 2 : st === 3 ? 3 : st === 4 ? 4 : st === 5 ? 6 : 8;
      const val = readSigned(payload, dataPos, sz);
      values.push({ type: 'INTEGER', value: val });
      dataPos += sz;
    } else if (st === 7) {
      const d = payload.readDoubleBE(dataPos);
      values.push({ type: 'REAL', dvalue: d });
      dataPos += 8;
    } else if (st === 8) {
      values.push({ type: 'INTEGER', value: 0n });
    } else if (st === 9) {
      values.push({ type: 'INTEGER', value: 1n });
    } else if (st >= 12 && st % 2 === 0) {
      const len = (st - 12) / 2;
      values.push({ type: 'BLOB', data: payload.slice(dataPos, dataPos + len) });
      dataPos += len;
    } else if (st >= 13 && st % 2 === 1) {
      const len = (st - 13) / 2;
      values.push({ type: 'TEXT', data: payload.slice(dataPos, dataPos + len) });
      dataPos += len;
    } else {
      values.push({ type: 'NULL' });
    }
  }
  return values;
}

function walkTableBTree(buf: Buffer, pageNum: number, pageSize: number, reservedBytes: number): Array<{ rowid: bigint; payload: Buffer }> {
  const results: Array<{ rowid: bigint; payload: Buffer }> = [];
  const headerOffset = pageNum === 1 ? 100 : 0;
  const pageType = buf[headerOffset];

  if (pageType === 13) {
    const numCells = buf.readUInt16BE(headerOffset + 3);
    const cellPtrOffset = headerOffset + 8;
    const usableSize = pageSize - reservedBytes;
    const maxLocal = Math.floor(((usableSize - 12) * 64) / 255) - 23;
    const minLocal = Math.floor(((usableSize - 35) * 32) / 255) - 23;

    for (let i = 0; i < numCells; i++) {
      const cellOffset = buf.readUInt16BE(cellPtrOffset + i * 2);
      let pos = cellOffset;
      const overflowInfo = readVarint(buf, pos); pos += overflowInfo.size;
      const payloadLenInfo = readVarint(buf, pos); pos += payloadLenInfo.size;
      const rowidInfo = readVarint(buf, pos); pos += rowidInfo.size;

      const payloadLen = Number(payloadLenInfo.value);
      let localBytes: number;
      if (payloadLen <= maxLocal) {
        localBytes = payloadLen;
      } else {
        localBytes = minLocal + (payloadLen - minLocal) % (usableSize - 4);
        if (localBytes > maxLocal) localBytes = minLocal;
      }

      const payload = Buffer.alloc(payloadLen);
      if (localBytes > 0) {
        buf.copy(payload, 0, pos, pos + localBytes);
      }

      let remaining = payloadLen - localBytes;
      let curPage = Number(overflowInfo.value);
      let pPos = localBytes;
      while (remaining > 0 && curPage !== 0) {
        const pageOff = (curPage - 1) * pageSize;
        const nextPage = buf.readUInt32BE(pageOff);
        const available = usableSize - 4;
        const toRead = Math.min(remaining, available);
        buf.copy(payload, pPos, pageOff + 4, pageOff + 4 + toRead);
        pPos += toRead;
        remaining -= toRead;
        curPage = nextPage;
      }

      let rowid = rowidInfo.value;
      if (rowid >= (1n << 63n)) rowid -= (1n << 64n);
      results.push({ rowid, payload });
    }
  } else if (pageType === 5) {
    const numCells = buf.readUInt16BE(headerOffset + 3);
    const cellPtrOffset = headerOffset + 8;
    for (let i = 0; i < numCells; i++) {
      const cellOffset = buf.readUInt16BE(cellPtrOffset + i * 2);
      const childPage = buf.readUInt32BE(cellOffset);
      const childResults = walkTableBTree(buf, childPage, pageSize, reservedBytes);
      results.push(...childResults);
    }
    const rightPage = buf.readUInt32BE(headerOffset + 8);
    if (rightPage !== 0) {
      const childResults = walkTableBTree(buf, rightPage, pageSize, reservedBytes);
      results.push(...childResults);
    }
  }
  return results;
}

function parseCreateTable(sql: string): { columns: string[]; rowidAliases: boolean[] } {
  const columns: string[] = [];
  const rowidAliases: boolean[] = [];

  let s = sql.trim();
  // Remove CREATE TABLE
  const createMatch = s.match(/^CREATE\s+TABLE\s+/i);
  if (!createMatch) return { columns, rowidAliases };
  s = s.substring(createMatch[0].length);

  // Optional IF NOT EXISTS
  const ifneMatch = s.match(/^IF\s+NOT\s+EXISTS\s+/i);
  if (ifneMatch) s = s.substring(ifneMatch[0].length);

  // Read table name (possibly double-quoted)
  if (s[0] === '"') {
    const end = s.indexOf('"', 1);
    s = s.substring(end + 1);
  } else {
    const m = s.match(/^[^\s(]+/);
    if (m) s = s.substring(m[0].length);
  }

  // Skip whitespace to (
  s = s.trimStart();
  if (s[0] !== '(') return { columns, rowidAliases };
  s = s.substring(1);

  // Find matching )
  let depth = 1;
  let defsEnd = 0;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '(') depth++;
    else if (s[i] === ')') { depth--; if (depth === 0) { defsEnd = i; break; } }
  }
  const defsStr = s.substring(0, defsEnd);

  // Split by commas not inside parentheses
  const defs: string[] = [];
  let d = 0;
  let cur = '';
  for (let i = 0; i < defsStr.length; i++) {
    if (defsStr[i] === '(') d++;
    else if (defsStr[i] === ')') d--;
    else if (defsStr[i] === ',' && d === 0) {
      defs.push(cur.trim());
      cur = '';
      continue;
    }
    cur += defsStr[i];
  }
  if (cur.trim()) defs.push(cur.trim());

  for (const def of defs) {
    let colName: string;
    let afterName: string;
    if (def[0] === '"') {
      const end = def.indexOf('"', 1);
      colName = def.substring(1, end);
      afterName = def.substring(end + 1);
    } else {
      const m = def.match(/^([^\s(]+)/);
      if (!m) continue;
      colName = m[1];
      afterName = def.substring(m[0].length);
    }
    columns.push(colName);

    // Check rowid alias: type is single word INTEGER and contains PRIMARY KEY
    const isAlias = isRowidAlias(afterName);
    rowidAliases.push(isAlias);
  }

  return { columns, rowidAliases };
}

function isRowidAlias(afterName: string): boolean {
  const trimmed = afterName.trimStart();
  const upper = trimmed.toUpperCase();
  if (!upper.includes('PRIMARY KEY')) return false;

  // Check type is single word INTEGER
  if (!upper.startsWith('INTEGER')) return false;
  const afterInt = trimmed.substring(7);
  if (afterInt.length > 0) {
    const nextChar = afterInt[0];
    if (/[A-Za-z0-9_(]/.test(nextChar)) return false;
  }
  return true;
}

function main() {
  const dir = process.argv[2];
  const filePath = path.join(dir, 'db.sqlite');
  const data = fs.readFileSync(filePath);

  let pageSize = data.readUInt16BE(16);
  if (pageSize === 1) pageSize = 65536;
  const reservedBytes = data[20];

  // Walk schema b-tree (rooted at page 1)
  const schemaRows = walkTableBTree(data, 1, pageSize, reservedBytes);

  interface SchemaEntry { name: string; rootpage: number; sql: string; }
  const tables: SchemaEntry[] = [];

  for (const row of schemaRows) {
    const vals = parseRecord(row.payload, 5);
    if (vals[0].type === 'TEXT' && vals[0].data!.toString('utf8') === 'table' &&
        vals[1].type === 'TEXT' && !vals[1].data!.toString('utf8').startsWith('sqlite_')) {
      const rootpage = vals[3].type === 'INTEGER' ? Number(vals[3].value) : 0;
      const sql = vals[4].type === 'TEXT' ? vals[4].data!.toString('utf8') : '';
      tables.push({
        name: vals[1].data!.toString('utf8'),
        rootpage,
        sql,
      });
    }
  }

  // Sort by name byte-wise
  tables.sort((a, b) => {
    return Buffer.compare(Buffer.from(a.name, 'utf8'), Buffer.from(b.name, 'utf8'));
  });

  const outputParts: string[] = [];
  for (const table of tables) {
    const { columns, rowidAliases } = parseCreateTable(table.sql);
    const numCols = columns.length;

    let rows: Array<{ rowid: bigint; payload: Buffer }> = [];
    if (table.rootpage > 0) {
      rows = walkTableBTree(data, table.rootpage, pageSize, reservedBytes);
    }

    rows.sort((a, b) => {
      if (a.rowid < b.rowid) return -1;
      if (a.rowid > b.rowid) return 1;
      return 0;
    });

    const lines: string[] = [];
    lines.push(`TABLE ${table.name} rows=${rows.length}`);
    lines.push(`COLUMNS ${columns.join(', ')}`);

    for (const row of rows) {
      const vals = parseRecord(row.payload, numCols);
      const formatted: string[] = [];
      for (let i = 0; i < numCols; i++) {
        if (rowidAliases[i]) {
          formatted.push(row.rowid.toString());
        } else {
          formatted.push(formatValue(vals[i]));
        }
      }
      lines.push(`${row.rowid}: ${formatted.join(', ')}`);
    }

    outputParts.push(lines.join('\n'));
  }

  process.stdout.write(outputParts.join('\n\n') + '\n');
}

main();

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <math.h>

static uint8_t *g_db;
static long g_dbsize;
static int g_pagesize, g_reserved, g_usable;

static uint32_t crc_table[256];
static void crc_init(void){
    for(uint32_t i=0;i<256;i++){uint32_t c=i;for(int j=0;j<8;j++)c=(c&1)?0xEDB88320^(c>>1):c>>1;crc_table[i]=c;}
}
static uint32_t crc32(const uint8_t*d,int len){
    uint32_t c=0xFFFFFFFF;
    for(int i=0;i<len;i++)c=crc_table[(c^d[i])&0xFF]^(c>>8);
    return c^0xFFFFFFFF;
}

static uint16_t be16(const uint8_t*p){return(p[0]<<8)|p[1];}
static uint32_t be32(const uint8_t*p){return((uint32_t)p[0]<<24)|(p[1]<<16)|(p[2]<<8)|p[3];}
static int64_t be64(const uint8_t*p){return((int64_t)be32(p)<<32)|be32(p+4);}

static int read_varint(const uint8_t*d,int len,int pos,uint64_t*v){
    *v=0;
    for(int i=0;i<9;i++){
        if(pos>=len)break;
        uint8_t b=d[pos++];
        if(i<8){*v=(*v<<7)|(b&0x7F);if(!(b&0x80))return pos;}
        else{*v=(*v<<8)|b;return pos;}
    }
    return pos;
}

static const uint8_t*getpage(int pgno){return g_db+(long)(pgno-1)*g_pagesize;}

typedef struct{int64_t rowid;uint8_t*payload;int plen;}Row;

static void walk_btree(int pgno,Row**rows,int*n,int*cap){
    const uint8_t*p=getpage(pgno);
    int ho=(pgno==1)?100:0;
    uint8_t pt=p[ho];
    int nc=be16(p+ho+3);
    if(pt==0x0D){
        int cp=ho+8;
        int maxLocal=g_usable-35;
        int minLocal=((g_usable-12)*32)/255-23;
        for(int i=0;i<nc;i++){
            int co=be16(p+cp+i*2);
            int pos=co;
            uint64_t psz,rid;
            pos=read_varint(p,g_pagesize,pos,&psz);
            pos=read_varint(p,g_pagesize,pos,&rid);
            int psz_i=(int)psz;
            int local_sz;uint32_t ovf=0;
            if(psz_i<=maxLocal){local_sz=psz_i;}
            else{
                int K=minLocal+(psz_i-minLocal)%(g_usable-4);
                if(K>maxLocal)K=maxLocal;
                local_sz=K;
                ovf=be32(p+pos+K);
            }
            uint8_t*pl=malloc(psz_i>0?psz_i:1);
            memcpy(pl,p+pos,local_sz);
            if(ovf){
                int rem=psz_i-local_sz;int wp=local_sz;
                while(ovf&&rem>0){
                    const uint8_t*op=getpage(ovf);
                    uint32_t nxt=be32(op);
                    int chunk=g_usable-4;
                    if(chunk>rem)chunk=rem;
                    memcpy(pl+wp,op+4,chunk);
                    wp+=chunk;rem-=chunk;ovf=nxt;
                }
            }
            if(*n>=*cap){*cap=*cap?*cap*2:64;*rows=realloc(*rows,*cap*sizeof(Row));}
            (*rows)[*n].rowid=(int64_t)rid;
            (*rows)[*n].payload=pl;
            (*rows)[*n].plen=psz_i;
            (*n)++;
        }
    }else if(pt==0x05){
        int left=(int)be32(p+ho+8);
        walk_btree(left,rows,n,cap);
        int cp=ho+12;
        for(int i=0;i<nc;i++){
            int co=be16(p+cp+i*2);
            int child=(int)be32(p+co);
            walk_btree(child,rows,n,cap);
        }
    }
}

typedef struct{int stype;int64_t ival;double dval;const uint8_t*data;int dlen;}Val;

static int parse_record(const uint8_t*pl,int plen,Val*vals,int maxv){
    if(plen==0)return 0;
    int pos=0;uint64_t hs;
    pos=read_varint(pl,plen,pos,&hs);
    int hs_i=(int)hs;
    uint64_t sts[2048];int nv=0;
    int tp=pos;
    while(tp<hs_i&&nv<maxv){
        uint64_t s;tp=read_varint(pl,plen,tp,&s);sts[nv++]=s;
    }
    int dp=hs_i;
    for(int i=0;i<nv;i++){
        vals[i].stype=(int)sts[i];vals[i].ival=0;vals[i].dval=0;vals[i].data=NULL;vals[i].dlen=0;
        switch(vals[i].stype){
            case 0:break;
            case 1:vals[i].ival=(int8_t)pl[dp];dp+=1;break;
            case 2:vals[i].ival=(int16_t)((pl[dp]<<8)|pl[dp+1]);dp+=2;break;
            case 3:{int32_t v=(pl[dp]<<16)|(pl[dp+1]<<8)|pl[dp+2];if(v&0x800000)v|=(int32_t)0xFF000000;vals[i].ival=v;dp+=3;}break;
            case 4:vals[i].ival=(int32_t)be32(pl+dp);dp+=4;break;
            case 5:{int64_t v=0;for(int j=0;j<6;j++)v=(v<<8)|pl[dp+j];if(v&(1LL<<47))v-=(1LL<<48);vals[i].ival=v;dp+=6;}break;
            case 6:vals[i].ival=be64(pl+dp);dp+=8;break;
            case 7:{uint64_t bits=be64(pl+dp);memcpy(&vals[i].dval,&bits,8);dp+=8;}break;
            case 8:vals[i].ival=0;break;
            case 9:vals[i].ival=1;break;
            default:
                if(vals[i].stype>=12&&!(vals[i].stype&1)){vals[i].dlen=(vals[i].stype-12)/2;vals[i].data=pl+dp;dp+=vals[i].dlen;}
                else if(vals[i].stype>=13&&(vals[i].stype&1)){vals[i].dlen=(vals[i].stype-13)/2;vals[i].data=pl+dp;dp+=vals[i].dlen;}
                break;
        }
    }
    return nv;
}

static void fmt_real(double d,char*buf,int sz){
    if(d==0.0){snprintf(buf,sz,"0.0");return;}
    snprintf(buf,sz,"%.8f",d);
    char*dot=strchr(buf,'.');
    if(dot){char*e=buf+strlen(buf)-1;while(e>dot+1&&*e=='0')*e--='\0';}
    if(strcmp(buf,"-0.0")==0)strcpy(buf,"0.0");
}

static void fmt_text(const uint8_t*d,int len,char*buf,int sz){
    int p=0;buf[p++]='"';
    for(int i=0;i<len;i++){
        uint8_t c=d[i];
        if(c=='\\'){buf[p++]='\\';buf[p++]='\\';}
        else if(c=='"'){buf[p++]='\\';buf[p++]='"';}
        else if(c=='\n'){buf[p++]='\\';buf[p++]='n';}
        else if(c=='\r'){buf[p++]='\\';buf[p++]='r';}
        else if(c=='\t'){buf[p++]='\\';buf[p++]='t';}
        else if(c<0x20||c==0x7F){p+=sprintf(buf+p,"\\x%02X",c);}
        else buf[p++]=c;
    }
    buf[p++]='"';buf[p]='\0';
}

static void fmt_blob(const uint8_t*d,int len,char*buf,int sz){
    int p=0;buf[p++]='X';buf[p++]='\'';
    for(int i=0;i<len;i++)p+=sprintf(buf+p,"%02X",d[i]);
    buf[p++]='\'';buf[p]='\0';
}

static void fmt_value(const Val*v,char*buf,int sz){
    switch(v->stype){
        case 0:case 8:case 9:
            if(v->stype==0)strcpy(buf,"NULL");
            else sprintf(buf,"%lld",(long long)v->ival);
            break;
        case 1:case 2:case 3:case 4:case 5:case 6:
            sprintf(buf,"%lld",(long long)v->ival);break;
        case 7:fmt_real(v->dval,buf,sz);break;
        default:
            if(v->stype>=12&&!(v->stype&1)){
                if(v->dlen<=100)fmt_blob(v->data,v->dlen,buf,sz);
                else sprintf(buf,"<BLOB len=%d crc32=%08x>",v->dlen,crc32(v->data,v->dlen));
            }else if(v->stype>=13&&(v->stype&1)){
                if(v->dlen<=100)fmt_text(v->data,v->dlen,buf,sz);
                else sprintf(buf,"<TEXT len=%d crc32=%08x>",v->dlen,crc32(v->data,v->dlen));
            }else strcpy(buf,"NULL");
            break;
    }
}

static int is_ws(char c){return c==' '||c=='\t'||c=='\n'||c=='\r'||c=='\f';}
static int ci_ncmp(const char*a,const char*b,int n){
    for(int i=0;i<n;i++){int ca=tolower((unsigned char)a[i]),cb=tolower((unsigned char)b[i]);if(ca!=cb)return ca-cb;}return 0;
}

static int contains_primary_key(const char*s,const char*e){
    const char*p=s;
    while(p<e){
        while(p<e){
            if(p+7<=e&&ci_ncmp(p,"PRIMARY",7)==0&&(p+7>=e||!isalnum((unsigned char)p[7])&&p[7]!='_'))break;
            p++;
        }
        if(p>=e)return 0;
        p+=7;
        while(p<e&&is_ws(*p))p++;
        if(p+3<=e&&ci_ncmp(p,"KEY",3)==0&&(p+3>=e||!isalnum((unsigned char)p[3])&&p[3]!='_'))return 1;
        p++;
    }
    return 0;
}

static int parse_columns(const char*sql,char names[][256],int*ipk,int maxc){
    const char*s=sql;
    while(*s&&is_ws(*s))s++;
    int n=7;if(ci_ncmp(s,"CREATE",6)!=0)return -1;s+=6;
    while(*s&&is_ws(*s))s++;
    if(ci_ncmp(s,"TABLE",5)!=0)return -1;s+=5;
    while(*s&&is_ws(*s))s++;
    if(ci_ncmp(s,"IF",2)==0){
        s+=2;while(*s&&is_ws(*s))s++;
        if(ci_ncmp(s,"NOT",3)==0){s+=3;while(*s&&is_ws(*s))s++;}
        if(ci_ncmp(s,"EXISTS",6)==0){s+=6;while(*s&&is_ws(*s))s++;}
    }
    if(*s=='"'){s++;while(*s&&*s!='"')s++;if(*s=='"')s++;}
    else{while(*s&&*s!='('&&!is_ws(*s))s++;}
    while(*s&&is_ws(*s))s++;
    if(*s!='(')return -1;
    s++;
    const char*start=s;int depth=1;
    while(*s&&depth>0){if(*s=='(')depth++;else if(*s==')')depth--;if(depth>0)s++;}
    const char*end=s;
    int nc=0;
    const char*seg=start;
    depth=0;
    for(const char*p=start;p<=end;p++){
        if(p==end||(*p==','&&depth==0)){
            if(nc>=maxc)break;
            const char*ps=seg;
            while(ps<p&&is_ws(*ps))ps++;
            if(ps<p){
                if(*ps=='"'){
                    ps++;int nl=0;
                    while(ps<p&&*ps!='"')names[nc][nl++]=*ps++;
                    names[nc][nl]='\0';
                    if(ps<p&&*ps=='"')ps++;
                }else{
                    int nl=0;
                    while(ps<p&&*ps!='('&&!is_ws(*ps))names[nc][nl++]=*ps++;
                    names[nc][nl]='\0';
                }
                /* check INTEGER PRIMARY KEY */
                ipk[nc]=0;
                const char*tp=ps;
                while(tp<p&&is_ws(*tp))tp++;
                if(p-tp>=7&&ci_ncmp(tp,"INTEGER",7)==0){
                    const char*after=tp+7;
                    if(after>=p||(!isalnum((unsigned char)*after)&&*after!='_')){
                        if(contains_primary_key(seg,p))ipk[nc]=1;
                    }
                }
                nc++;
            }
            seg=p+1;
        }else if(*p=='(')depth++;
        else if(*p==')')depth--;
    }
    return nc;
}

typedef struct{char name[256];int rootpage;char*sql;}TblEntry;

int main(int argc,char*argv[]){
    crc_init();
    char path[4096];
    snprintf(path,sizeof(path),"%s/db.sqlite",argv[1]);
    FILE*f=fopen(path,"rb");
    if(!f){perror(path);return 1;}
    fseek(f,0,SEEK_END);g_dbsize=ftell(f);fseek(f,0,SEEK_SET);
    g_db=malloc(g_dbsize);fread(g_db,1,g_dbsize,f);fclose(f);

    g_pagesize=be16(g_db+16);
    if(g_pagesize==1)g_pagesize=65536;
    g_reserved=g_db[20];
    g_usable=g_pagesize-g_reserved;

    /* Walk schema b-tree (rooted at page 1) to find tables */
    TblEntry*tbls=NULL;int ntbl=0,cap_tbl=0;

    /* We need to walk page 1's b-tree for the schema table */
    /* Collect schema rows */
    Row*schema_rows=NULL;int n_schema=0,cap_schema=0;
    walk_btree(1,&schema_rows,&n_schema,&cap_schema);

    for(int i=0;i<n_schema;i++){
        Val vals[10];int nv=parse_record(schema_rows[i].payload,schema_rows[i].plen,vals,10);
        if(nv<5)continue;
        /* type=col0, name=col1, tbl_name=col2, rootpage=col3, sql=col4 */
        if(vals[0].stype<13||!(vals[0].stype&1))continue;
        if(vals[0].dlen!=5||memcmp(vals[0].data,"table",5)!=0)continue;
        if(vals[1].stype<13||!(vals[1].stype&1))continue;
        if(vals[1].dlen>=7&&memcmp(vals[1].data,"sqlite_",7)==0)continue;
        if(nv<4)continue;
        int rp=0;
        if(vals[3].stype>=1&&vals[3].stype<=6)rp=(int)vals[3].ival;
        else if(vals[3].stype==8)rp=0;
        else if(vals[3].stype==9)rp=1;
        char*sqltxt=NULL;
        if(nv>=5&&vals[4].stype>=13&&(vals[4].stype&1)){
            sqltxt=malloc(vals[4].dlen+1);
            memcpy(sqltxt,vals[4].data,vals[4].dlen);
            sqltxt[vals[4].dlen]='\0';
        }
        if(!sqltxt)continue;
        if(ntbl>=cap_tbl){cap_tbl=cap_tbl?cap_tbl*2:16;tbls=realloc(tbls,cap_tbl*sizeof(TblEntry));}
        int nlen=vals[1].dlen;if(nlen>255)nlen=255;
        memcpy(tbls[ntbl].name,vals[1].data,nlen);
        tbls[ntbl].name[nlen]='\0';
        tbls[ntbl].rootpage=rp;
        tbls[ntbl].sql=sqltxt;
        ntbl++;
    }

    /* Sort tables by name (byte-wise) */
    for(int i=0;i<ntbl;i++)for(int j=i+1;j<ntbl;j++){
        if(strcmp(tbls[i].name,tbls[j].name)>0){
            TblEntry tmp=tbls[i];tbls[i]=tbls[j];tbls[j]=tmp;
        }
    }

    int first_tbl=1;
    for(int t=0;t<ntbl;t++){
        if(!first_tbl)printf("\n");
        first_tbl=0;
        /* Parse columns */
        char colnames[256][256];int ipk[256];
        int ncols=parse_columns(tbls[t].sql,colnames,ipk,256);
        if(ncols<0)ncols=0;

        /* Walk table b-tree */
        Row*rows=NULL;int nrows=0,cap_rows=0;
        if(tbls[t].rootpage>0)
            walk_btree(tbls[t].rootpage,&rows,&nrows,&cap_rows);

        /* Sort rows by rowid */
        for(int i=0;i<nrows;i++)for(int j=i+1;j<nrows;j++){
            if(rows[i].rowid>rows[j].rowid){Row tmp=rows[i];rows[i]=rows[j];rows[j]=tmp;}
        }

        printf("TABLE %s rows=%d\n",tbls[t].name,nrows);
        printf("COLUMNS");
        for(int c=0;c<ncols;c++){
            if(c)printf(",");
            printf(" %s",colnames[c]);
        }
        printf("\n");

        for(int r=0;r<nrows;r++){
            Val vals[256];int nv=parse_record(rows[r].payload,rows[r].plen,vals,256);
            printf("%lld:",(long long)rows[r].rowid);
            for(int c=0;c<ncols;c++){
                char vbuf[4096];
                if(ipk[c]){
                    sprintf(vbuf,"%lld",(long long)rows[r].rowid);
                }else if(c<nv){
                    fmt_value(&vals[c],vbuf,sizeof(vbuf));
                }else{
                    strcpy(vbuf,"NULL");
                }
                printf(" %s",vbuf);
                if(c<ncols-1)printf(",");
            }
            printf("\n");
        }
        for(int i=0;i<nrows;i++)free(rows[i].payload);
        free(rows);
    }
    return 0;
}

import * as fs from 'fs';
import * as path from 'path';
import * as http from 'http';

function jsonEscape(s: string): string {
  let result = '"';
  for (let i = 0; i < s.length; ) {
    const cp = s.codePointAt(i)!;
    if (cp === 0x22) { result += '\\"'; i++; }
    else if (cp === 0x5C) { result += '\\\\'; i++; }
    else if (cp === 0x08) { result += '\\b'; i++; }
    else if (cp === 0x0C) { result += '\\f'; i++; }
    else if (cp === 0x0A) { result += '\\n'; i++; }
    else if (cp === 0x0D) { result += '\\r'; i++; }
    else if (cp === 0x09) { result += '\\t'; i++; }
    else if (cp < 0x20) { result += '\\u' + cp.toString(16).padStart(4, '0'); i++; }
    else {
      result += String.fromCodePoint(cp);
      i += cp > 0xFFFF ? 2 : 1;
    }
  }
  result += '"';
  return result;
}

function parseCSV(text: string): string[][] {
  if (text.charCodeAt(0) === 0xFEFF) text = text.slice(1);
  const records: string[][] = [];
  let i = 0;
  const len = text.length;
  while (i < len) {
    const record: string[] = [];
    while (true) {
      let field = '';
      if (i < len && text[i] === '"') {
        i++;
        while (i < len) {
          if (text[i] === '"') {
            if (i + 1 < len && text[i + 1] === '"') {
              field += '"';
              i += 2;
            } else {
              i++;
              break;
            }
          } else {
            field += text[i];
            i++;
          }
        }
      } else {
        while (i < len && text[i] !== ',' && text[i] !== '\r' && text[i] !== '\n') {
          field += text[i];
          i++;
        }
      }
      record.push(field);
      if (i < len && text[i] === ',') {
        i++;
      } else {
        if (i < len && text[i] === '\r') { i++; if (i < len && text[i] === '\n') i++; }
        else if (i < len && text[i] === '\n') { i++; }
        break;
      }
    }
    if (record.length > 1 || (record.length === 1 && record[0] !== '') || i < len) {
      records.push(record);
    }
  }
  return records;
}

interface InventoryItem {
  sku: string;
  name: string;
  price_cents: number;
  currency: string;
  stock: number;
}

function parseInventory(text: string): Map<string, InventoryItem> {
  const records = parseCSV(text);
  const map = new Map<string, InventoryItem>();
  for (let i = 1; i < records.length; i++) {
    const rec = records[i];
    if (rec.length < 5) continue;
    map.set(rec[0], {
      sku: rec[0],
      name: rec[1],
      price_cents: parseInt(rec[2], 10),
      currency: rec[3],
      stock: parseInt(rec[4], 10),
    });
  }
  return map;
}

function executeTool(name: string, argsStr: string, inventory: Map<string, InventoryItem>, rates: Record<string, number>): string {
  if (name === 'inventory_lookup') {
    const args = JSON.parse(argsStr);
    const sku: string = args.sku;
    const item = inventory.get(sku);
    if (item) {
      return '{"sku":' + jsonEscape(item.sku) + ',"name":' + jsonEscape(item.name) + ',"price_cents":' + item.price_cents + ',"currency":' + jsonEscape(item.currency) + ',"stock":' + item.stock + '}';
    } else {
      return '{"error":' + jsonEscape('unknown sku: ' + sku) + '}';
    }
  } else if (name === 'convert_currency') {
    const args = JSON.parse(argsStr);
    const amountCents: number = args.amount_cents;
    const from: string = args.from;
    const to: string = args.to;
    const rateFrom = BigInt(rates[from]);
    const rateTo = BigInt(rates[to]);
    const amount = BigInt(amountCents);
    const numerator = 2n * amount * rateTo + rateFrom;
    const denominator = 2n * rateFrom;
    const converted = numerator / denominator;
    return '{"amount_cents":' + converted.toString() + ',"currency":' + jsonEscape(to) + '}';
  } else {
    return '{"error":' + jsonEscape('unknown tool: ' + name) + '}';
  }
}

function doRequest(url: URL, apiKey: string, body: string): Promise<{ status: number; body: string }> {
  return new Promise((resolve, reject) => {
    const port = url.port ? parseInt(url.port, 10) : 80;
    const req = http.request({
      hostname: url.hostname,
      port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Host': url.port ? `${url.hostname}:${url.port}` : url.hostname,
        'Authorization': `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(body, 'utf-8'),
      },
    }, (res) => {
      const chunks: Buffer[] = [];
      res.on('data', (chunk: Buffer) => { chunks.push(chunk); });
      res.on('end', () => {
        let text = Buffer.concat(chunks).toString('utf-8');
        if (text.charCodeAt(0) === 0xFEFF) text = text.slice(1);
        resolve({ status: res.statusCode || 0, body: text });
      });
    });
    req.on('error', reject);
    req.write(body, 'utf-8');
    req.end();
  });
}

async function main() {
  const dataDir = process.argv[2];
  const baseUrl = process.argv[3];

  const taskRaw = fs.readFileSync(path.join(dataDir, 'task.json'), 'utf-8');
  const task = JSON.parse(taskRaw.charCodeAt(0) === 0xFEFF ? taskRaw.slice(1) : taskRaw);
  const csvText = fs.readFileSync(path.join(dataDir, 'inventory.csv'), 'utf-8');
  const ratesRaw = fs.readFileSync(path.join(dataDir, 'rates.json'), 'utf-8');
  const ratesData = JSON.parse(ratesRaw.charCodeAt(0) === 0xFEFF ? ratesRaw.slice(1) : ratesRaw);

  const inventory = parseInventory(csvText);
  const rates: Record<string, number> = ratesData.rates;

  const conversation: any[] = [
    { role: 'system', content: task.system },
    { role: 'user', content: task.user },
  ];

  const url = new URL(baseUrl + '/chat/completions');

  let totalPrompt = 0;
  let totalCompletion = 0;
  let totalTotal = 0;
  let requests = 0;
  const outputLines: string[] = [];

  while (true) {
    const reqBody = JSON.stringify({
      model: task.model,
      messages: conversation,
      tools: task.tools,
      tool_choice: 'auto',
    });

    const resp = await doRequest(url, task.api_key, reqBody);
    requests++;

    if (resp.status !== 200) {
      for (const line of outputLines) console.log(line);
      let errMsg = '';
      try {
        const errJson = JSON.parse(resp.body);
        errMsg = errJson.error?.message || '';
      } catch { /* ignore */ }
      console.log(`ERROR ${resp.status} ${errMsg}`);
      process.exit(0);
    }

    const respObj = JSON.parse(resp.body);

    if (respObj.usage) {
      totalPrompt += respObj.usage.prompt_tokens || 0;
      totalCompletion += respObj.usage.completion_tokens || 0;
      totalTotal += respObj.usage.total_tokens || 0;
    }

    const choice = respObj.choices[0];
    const message = choice.message;
    const finishReason: string = choice.finish_reason;

    if (finishReason === 'tool_calls') {
      if (typeof message.content === 'string') {
        outputLines.push(`SAY ${message.content}`);
      }

      const toolCalls = message.tool_calls || [];

      for (const tc of toolCalls) {
        outputLines.push(`CALL ${tc.id} ${tc.function.name}`);
      }

      const toolMessages: any[] = [];
      for (const tc of toolCalls) {
        const result = executeTool(tc.function.name, tc.function.arguments, inventory, rates);
        outputLines.push(`RESULT ${tc.id} ${result}`);
        toolMessages.push({ role: 'tool', tool_call_id: tc.id, content: result });
      }

      const assistantMsg: any = {
        role: 'assistant',
        content: message.content !== undefined ? message.content : null,
        tool_calls: toolCalls.map((tc: any) => ({
          id: tc.id,
          type: tc.type,
          function: {
            name: tc.function.name,
            arguments: tc.function.arguments,
          },
        })),
      };
      conversation.push(assistantMsg);
      for (const tm of toolMessages) {
        conversation.push(tm);
      }
    } else {
      outputLines.push(`FINAL ${message.content}`);
      break;
    }
  }

  for (const line of outputLines) console.log(line);
  console.log(`USAGE prompt=${totalPrompt} completion=${totalCompletion} total=${totalTotal} requests=${requests}`);
  process.exit(0);
}

main().catch((e) => {
  console.error(e);
  process.exit(0);
});

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
