/* ============ Dynamic string buffer ============ */
typedef struct { char *d; size_t len, cap; } sbuf;
static void sb_init(sbuf *s){s->d=malloc(256);s->d[0]=0;s->len=0;s->cap=256;}
static void sb_ensure(sbuf *s,size_t n){if(s->len+n>s->cap){s->cap=(s->len+n)*2;s->d=realloc(s->d,s->cap);}}
static void sb_append(sbuf *s,const char *t,size_t n){sb_ensure(s,n);memcpy(s->d+s->len,t,n);s->len+=n;s->d[s->len]=0;}
static void sb_puts(sbuf *s,const char *t){sb_append(s,t,strlen(t));}
static void sb_putc(sbuf *s,char c){sb_ensure(s,1);s->d[s->len++]=c;s->d[s->len]=0;}

/* ============ JSON value ============ */
typedef enum{JV_NULL,JV_BOOL,JV_NUM,JV_STR,JV_ARR,JV_OBJ}jt;
typedef struct jv{
    jt type;
    union{
        int b;
        char *str;
        struct{struct jv **items;size_t n;}arr;
        struct{char **keys;struct jv **vals;size_t n;}obj;
    };
}jv;

static jv*jv_new(jt t){jv*v=calloc(1,sizeof(jv));v->type=t;return v;}
static jv*jv_str(const char*s){jv*v=jv_new(JV_STR);v->str=strdup(s);return v;}

/* ============ JSON parser ============ */
typedef struct{const char*s;size_t p,len;}jp;
static void jp_ws(jp*j){while(j->p<j->len&&(j->s[j->p]==' '||j->s[j->p]=='\t'||j->s[j->p]=='\n'||j->s[j->p]=='\r'))j->p++;}
static jv*jp_val(jp*j);

static char*jp_str_raw(jp*j,size_t*out_len){
    /* assumes j->s[j->p]=='"' */
    j->p++;/* skip opening " */
    sbuf sb;sb_init(&sb);
    while(j->p<j->len&&j->s[j->p]!='"'){
        if(j->s[j->p]=='\\'){
            j->p++;
            if(j->p>=j->len)break;
            char c=j->s[j->p];j->p++;
            switch(c){
                case '"':sb_putc(&sb,'"');break;
                case '\\':sb_putc(&sb,'\\');break;
                case '/':sb_putc(&sb,'/');break;
                case 'b':sb_putc(&sb,'\b');break;
                case 'f':sb_putc(&sb,'\f');break;
                case 'n':sb_putc(&sb,'\n');break;
                case 'r':sb_putc(&sb,'\r');break;
                case 't':sb_putc(&sb,'\t');break;
                case 'u':{
                    if(j->p+4>j->len)break;
                    unsigned cp=0;
                    for(int i=0;i<4;i++){char h=j->s[j->p+i];cp=cp*16+(isdigit(h)?h-'0':(tolower(h)-'a'+10));}
                    j->p+=4;
                    if(cp>=0xD800&&cp<=0xDBFF){
                        if(j->p+6<=j->len&&j->s[j->p]=='\\'&&j->s[j->p+1]=='u'){
                            unsigned lo=0;j->p+=2;
                            for(int i=0;i<4;i++){char h=j->s[j->p+i];lo=lo*16+(isdigit(h)?h-'0':(tolower(h)-'a'+10));}
                            j->p+=4;
                            cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                        }
                    }
                    if(cp<0x80){sb_putc(&sb,(char)cp);}
                    else if(cp<0x800){sb_putc(&sb,(char)(0xC0|(cp>>6)));sb_putc(&sb,(char)(0x80|(cp&0x3F)));}
                    else if(cp<0x10000){sb_putc(&sb,(char)(0xE0|(cp>>12)));sb_putc(&sb,(char)(0x80|((cp>>6)&0x3F)));sb_putc(&sb,(char)(0x80|(cp&0x3F)));}
                    else{sb_putc(&sb,(char)(0xF0|(cp>>18)));sb_putc(&sb,(char)(0x80|((cp>>12)&0x3F)));sb_putc(&sb,(char)(0x80|((cp>>6)&0x3F)));sb_putc(&sb,(char)(0x80|(cp&0x3F)));}
                    break;
                }
                default:sb_putc(&sb,c);break;
            }
        }else{
            sb_putc(&sb,j->s[j->p]);j->p++;
        }
    }
    if(j->p<j->len)j->p++;/* skip closing " */
    if(out_len)*out_len=sb.len;
    return sb.d;
}

static jv*jp_val(jp*j){
    jp_ws(j);
    if(j->p>=j->len)return jv_new(JV_NULL);
    char c=j->s[j->p];
    if(c=='"'){jv*v=jv_new(JV_STR);v->str=jp_str_raw(j,NULL);return v;}
    if(c=='{'){
        j->p++;jv*v=jv_new(JV_OBJ);v->obj.keys=NULL;v->obj.vals=NULL;v->obj.n=0;
        jp_ws(j);
        if(j->p<j->len&&j->s[j->p]=='}'){j->p++;return v;}
        while(1){
            jp_ws(j);
            char*k=jp_str_raw(j,NULL);
            jp_ws(j);j->p++;/* : */
            jv*val=jp_val(j);
            v->obj.keys=realloc(v->obj.keys,(v->obj.n+1)*sizeof(char*));
            v->obj.vals=realloc(v->obj.vals,(v->obj.n+1)*sizeof(jv*));
            v->obj.keys[v->obj.n]=k;v->obj.vals[v->obj.n]=val;v->obj.n++;
            jp_ws(j);
            if(j->p<j->len&&j->s[j->p]==','){j->p++;continue;}
            if(j->p<j->len&&j->s[j->p]=='}'){j->p++;break;}
            break;
        }
        return v;
    }
    if(c=='['){
        j->p++;jv*v=jv_new(JV_ARR);v->arr.items=NULL;v->arr.n=0;
        jp_ws(j);
        if(j->p<j->len&&j->s[j->p]==']'){j->p++;return v;}
        while(1){
            jv*item=jp_val(j);
            v->arr.items=realloc(v->arr.items,(v->arr.n+1)*sizeof(jv*));
            v->arr.items[v->arr.n++]=item;
            jp_ws(j);
            if(j->p<j->len&&j->s[j->p]==','){j->p++;continue;}
            if(j->p<j->len&&j->s[j->p]==']'){j->p++;break;}
            break;
        }
        return v;
    }
    if(c=='t'){j->p+=4;jv*v=jv_new(JV_BOOL);v->b=1;return v;}
    if(c=='f'){j->p+=5;jv*v=jv_new(JV_BOOL);v->b=0;return v;}
    if(c=='n'){j->p+=4;jv*v=jv_new(JV_NULL);return v;}
    /* number */
    size_t start=j->p;
    if(j->p<j->len&&(j->s[j->p]=='-'||j->s[j->p]=='+'))j->p++;
    while(j->p<j->len&&(isdigit(j->s[j->p])||j->s[j->p]=='.'||j->s[j->p]=='e'||j->s[j->p]=='E'||j->s[j->p]=='+'||j->s[j->p]=='-'))j->p++;
    jv*v=jv_new(JV_NUM);
    size_t n=j->p-start;
    v->str=malloc(n+1);memcpy(v->str,j->s+start,n);v->str[n]=0;
    return v;
}

static jv*jv_get(jv*obj,const char*key){
    if(!obj||obj->type!=JV_OBJ)return NULL;
    for(size_t i=0;i<obj->obj.n;i++)if(strcmp(obj->obj.keys[i],key)==0)return obj->obj.vals[i];
    return NULL;
}

/* ============ JSON string encoding (for tool results & serialization) ============ */
static void enc_json_str(sbuf*sb,const char*s){
    sb_putc(sb,'"');
    for(const unsigned char*p=(const unsigned char*)s;*p;p++){
        unsigned char c=*p;
        if(c=='"'){sb_puts(sb,"\\\"");}
        else if(c=='\\'){sb_puts(sb,"\\\\");}
        else if(c=='\b'){sb_puts(sb,"\\b");}
        else if(c=='\f'){sb_puts(sb,"\\f");}
        else if(c=='\n'){sb_puts(sb,"\\n");}
        else if(c=='\r'){sb_puts(sb,"\\r");}
        else if(c=='\t'){sb_puts(sb,"\\t");}
        else if(c<0x20){char buf[8];sprintf(buf,"\\u%04x",c);sb_puts(sb,buf);}
        else{sb_putc(sb,(char)c);}
    }
    sb_putc(sb,'"');
}

/* ============ File reading ============ */
static char*read_file(const char*path,size_t*out_len){
    FILE*f=fopen(path,"rb");if(!f)return NULL;
    fseek(f,0,SEEK_END);long sz=ftell(f);fseek(f,0,SEEK_SET);
    char*buf=malloc(sz+1);size_t rd=fread(buf,1,sz,f);buf[rd]=0;fclose(f);
    if(out_len)*out_len=rd;return buf;
}

/* ============ HTTP client ============ */
static char*http_post(const char*base_url,const char*api_key,const char*body,size_t body_len,int*status){
    /* parse URL: http://host:port/path */
    const char*p=base_url;
    if(strncmp(p,"http://",7)==0)p+=7;
    else if(strncmp(p,"https://",8)==0)p+=8;
    char host[256]="",port[16]="80",path[512]="";
    const char*colon=strchr(p,':');
    const char*slash=strchr(p,'/');
    if(colon&&(!slash||colon<slash)){
        size_t hl=colon-p;memcpy(host,p,hl);host[hl]=0;
        size_t pl=slash?(size_t)(slash-colon-1):strlen(colon+1);
        memcpy(port,colon+1,pl);port[pl]=0;
        if(slash)strcpy(path,slash);
    }else if(slash){
        size_t hl=slash-p;memcpy(host,p,hl);host[hl]=0;
        strcpy(path,slash);
    }else{strcpy(host,p);}
    strcat(path,"/chat/completions");

    struct addrinfo hints={},*res=NULL;
    hints.ai_family=AF_INET;hints.ai_socktype=SOCK_STREAM;
    if(getaddrinfo(host,port,&hints,&res)!=0||!res){*status=-1;return NULL;}
    int fd=socket(res->ai_family,res->ai_socktype,res->ai_protocol);
    if(fd<0){freeaddrinfo(res);*status=-1;return NULL;}
    if(connect(fd,res->ai_addr,res->ai_addrlen)<0){close(fd);freeaddrinfo(res);*status=-1;return NULL;}
    freeaddrinfo(res);

    sbuf req;sb_init(&req);
    sb_puts(&req,"POST ");sb_puts(&req,path);sb_puts(&req," HTTP/1.1\r\n");
    sb_puts(&req,"Host: ");sb_puts(&req,host);sb_putc(&req,':');sb_puts(&req,port);sb_puts(&req,"\r\n");
    sb_puts(&req,"Authorization: Bearer ");sb_puts(&req,api_key);sb_puts(&req,"\r\n");
    sb_puts(&req,"Content-Type: application/json\r\n");
    char cl[32];sprintf(cl,"Content-Length: %zu\r\n",body_len);sb_puts(&req,cl);
    sb_puts(&req,"Connection: close\r\n\r\n");
    sb_append(&req,body,body_len);

    size_t sent=0;
    while(sent<req.len){
        ssize_t w=write(fd,req.d+sent,req.len-sent);
        if(w<=0){close(fd);*status=-1;return NULL;}
        sent+=w;
    }

    sbuf resp;sb_init(&resp);
    char tmp[65536];
    while(1){
        ssize_t r=read(fd,tmp,sizeof(tmp));
        if(r<=0)break;
        sb_append(&resp,tmp,r);
    }
    close(fd);

    /* parse status */
    *status=0;
    if(resp.len>12&&strncmp(resp.d,"HTTP/1.1 ",9)==0){
        *status=atoi(resp.d+9);
    }else if(resp.len>12&&strncmp(resp.d,"HTTP/1.0 ",9)==0){
        *status=atoi(resp.d+9);
    }
    /* find body */
    char*sep=strstr(resp.d,"\r\n\r\n");
    if(!sep){*status=-1;return NULL;}
    size_t hdr_len=(sep-resp.d)+4;
    char*body_out=malloc(resp.len-hdr_len+1);
    memcpy(body_out,resp.d+hdr_len,resp.len-hdr_len);
    body_out[resp.len-hdr_len]=0;
    return body_out;
}

/* ============ CSV parser ============ */
typedef struct{char*sku;char*name;long long price_cents;char*currency;long long stock;}inv_item;
static inv_item*inv=NULL;static int inv_n=0,inv_cap=0;

static char*csv_parse_field(const char*data,size_t len,size_t*pos){
    sbuf sb;sb_init(&sb);
    if(*pos<len&&data[*pos]=='"'){
        (*pos)++;
        while(*pos<len){
            if(data[*pos]=='"'){
                if(*pos+1<len&&data[*pos+1]=='"'){sb_putc(&sb,'"');*pos+=2;}
                else{(*pos)++;break;}
            }else{sb_putc(&sb,data[*pos]);(*pos)++;}
        }
    }else{
        while(*pos<len&&data[*pos]!=','&&data[*pos]!='\r'&&data[*pos]!='\n'){sb_putc(&sb,data[*pos]);(*pos)++;}
    }
    return sb.d;
}

static void parse_csv(const char*data,size_t len){
    size_t pos=0;
    /* skip BOM */
    if(len>=3&&(unsigned char)data[0]==0xEF&&(unsigned char)data[1]==0xBB&&(unsigned char)data[2]==0xBF)pos=3;
    /* skip header line */
    while(pos<len&&!(data[pos]=='\r'&&pos+1<len&&data[pos+1]=='\n'))pos++;
    if(pos<len)pos+=2;/* skip \r\n */
    while(pos<len){
        /* parse one record */
        char*fields[5]={NULL,NULL,NULL,NULL,NULL};
        int fi=0;
        while(fi<5&&pos<len){
            fields[fi]=csv_parse_field(data,len,&pos);
            fi++;
            if(pos<len&&data[pos]==','){pos++;}
            else break;
        }
        /* skip line ending */
        if(pos<len&&data[pos]=='\r')pos++;
        if(pos<len&&data[pos]=='\n')pos++;
        if(fi<5)continue;
        /* add to inventory */
        if(inv_n>=inv_cap){inv_cap=inv_cap?inv_cap*2:64;inv=realloc(inv,inv_cap*sizeof(inv_item));}
        inv_item*it=&inv[inv_n++];
        it->sku=fields[0];it->name=fields[1];
        it->price_cents=strtoll(fields[2],NULL,10);
        it->currency=fields[3];
        it->stock=strtoll(fields[4],NULL,10);
    }
}

/* ============ Rates ============ */
typedef struct{char*cur;long long rate;}rate_ent;
static rate_ent*rates=NULL;static int rates_n=0;
static long long get_rate(const char*cur){
    for(int i=0;i<rates_n;i++)if(strcmp(rates[i].cur,cur)==0)return rates[i].rate;
    return 1000000;
}

/* ============ Message structures ============ */
typedef struct{char*id;char*type;char*name;char*arguments;}tcall;
typedef struct{char*role;char*content;int content_null;tcall*tcs;int n_tcs;char*tool_call_id;}msg;
static msg*msgs=NULL;static int n_msgs=0,msgs_cap=0;

static void add_msg(msg m){
    if(n_msgs>=msgs_cap){msgs_cap=msgs_cap?msgs_cap*2:16;msgs=realloc(msgs,msgs_cap*sizeof(msg));}
    msgs[n_msgs++]=m;
}

/* ============ Serialize conversation to JSON ============ */
static void serialize_msgs(sbuf*sb){
    sb_putc(sb,'[');
    for(int i=0;i<n_msgs;i++){
        if(i)sb_putc(sb,',');
        sb_putc(sb,'{');
        sb_puts(sb,"\"role\":");enc_json_str(sb,msgs[i].role);
        sb_putc(sb,',');
        if(msgs[i].content_null){sb_puts(sb,"\"content\":null");}
        else{sb_puts(sb,"\"content\":");enc_json_str(sb,msgs[i].content);}
        if(msgs[i].tool_call_id){
            sb_putc(sb,',');sb_puts(sb,"\"tool_call_id\":");enc_json_str(sb,msgs[i].tool_call_id);
        }
        if(msgs[i].n_tcs>0){
            sb_putc(sb,',');sb_puts(sb,"\"tool_calls\":[");
            for(int j=0;j<msgs[i].n_tcs;j++){
                if(j)sb_putc(sb,',');
                sb_puts(sb,"{\"id\":");enc_json_str(sb,msgs[i].tcs[j].id);
                sb_puts(sb,",\"type\":");enc_json_str(sb,msgs[i].tcs[j].type);
                sb_puts(sb,",\"function\":{\"name\":");enc_json_str(sb,msgs[i].tcs[j].name);
                sb_puts(sb,",\"arguments\":");enc_json_str(sb,msgs[i].tcs[j].arguments);
                sb_puts(sb,"}}");
            }
            sb_putc(sb,']');
        }
        sb_putc(sb,'}');
    }
    sb_putc(sb,']');
}

/* ============ Tool execution ============ */
static char*exec_tool(const char*name,const char*args_json){
    if(strcmp(name,"inventory_lookup")==0){
        jp j={args_json,strlen(args_json),0};
        jv*obj=jp_val(&j);
        jv*skuv=jv_get(obj,"sku");
        if(!skuv||skuv->type!=JV_STR)return strdup("{\"error\":\"unknown sku: \"}");
        const char*sku=skuv->str;
        for(int i=0;i<inv_n;i++){
            if(strcmp(inv[i].sku,sku)==0){
                sbuf sb;sb_init(&sb);
                sb_puts(&sb,"{\"sku\":");enc_json_str(&sb,inv[i].sku);
                sb_puts(&sb,",\"name\":");enc_json_str(&sb,inv[i].name);
                char buf[64];
                sprintf(buf,",\"price_cents\":%lld",inv[i].price_cents);sb_puts(&sb,buf);
                sb_puts(&sb,",\"currency\":");enc_json_str(&sb,inv[i].currency);
                sprintf(buf,",\"stock\":%lld",inv[i].stock);sb_puts(&sb,buf);
                sb_putc(&sb,'}');
                return sb.d;
            }
        }
        sbuf sb;sb_init(&sb);
        sb_puts(&sb,"{\"error\":\"unknown sku: ");
        /* escape sku in error message */
        enc_json_str(&sb,sku);
        /* remove the quotes that enc_json_str added */
        /* Actually we need: {"error":"unknown sku: <sku>"} where <sku> is JSON-escaped */
        /* Let me redo this */
        sb.len=0;sb.d[0]=0;
        sb_puts(&sb,"{\"error\":\"unknown sku: ");
        for(const unsigned char*p=(const unsigned char*)sku;*p;p++){
            unsigned char c=*p;
            if(c=='"'){sb_puts(&sb,"\\\"");}
            else if(c=='\\'){sb_puts(&sb,"\\\\");}
            else if(c=='\b'){sb_puts(&sb,"\\b");}
            else if(c=='\f'){sb_puts(&sb,"\\f");}
            else if(c=='\n'){sb_puts(&sb,"\\n");}
            else if(c=='\r'){sb_puts(&sb,"\\r");}
            else if(c=='\t'){sb_puts(&sb,"\\t");}
            else if(c<0x20){char buf[8];sprintf(buf,"\\u%04x",c);sb_puts(&sb,buf);}
            else{sb_putc(&sb,(char)c);}
        }
        sb_puts(&sb,"\"}");
        return sb.d;
    }
    if(strcmp(name,"convert_currency")==0){
        jp j={args_json,strlen(args_json),0};
        jv*obj=jp_val(&j);
        jv*amt_v=jv_get(obj,"amount_cents");
        jv*from_v=jv_get(obj,"from");
        jv*to_v=jv_get(obj,"to");
        long long amount=0;
        if(amt_v&&amt_v->type==JV_NUM)amount=strtoll(amt_v->str,NULL,10);
        const char*from=from_v&&from_v->type==JV_STR?from_v->str:"USD";
        const char*to=to_v&&to_v->type==JV_STR?to_v->str:"USD";
        long long rf=get_rate(from),rt=get_rate(to);
        /* (2*amount*rt + rf) / (2*rf) */
        long long num=2*amount*rt+rf;
        long long den=2*rf;
        long long result=num/den;
        sbuf sb;sb_init(&sb);
        char buf[64];
        sprintf(buf,"{\"amount_cents\":%lld,\"currency\":",result);sb_puts(&sb,buf);
        enc_json_str(&sb,to);
        sb_putc(&sb,'}');
        return sb.d;
    }
    /* unknown tool */
    sbuf sb;sb_init(&sb);
    sb_puts(&sb,"{\"error\":\"unknown tool: ");
    for(const unsigned char*p=(const unsigned char*)name;*p;p++){
        unsigned char c=*p;
        if(c=='"'){sb_puts(&sb,"\\\"");}
        else if(c=='\\'){sb_puts(&sb,"\\\\");}
        else if(c=='\b'){sb_puts(&sb,"\\b");}
        else if(c=='\f'){sb_puts(&sb,"\\f");}
        else if(c=='\n'){sb_puts(&sb,"\\n");}
        else if(c=='\r'){sb_puts(&sb,"\\r");}
        else if(c=='\t'){sb_puts(&sb,"\\t");}
        else if(c<0x20){char buf[8];sprintf(buf,"\\u%04x",c);sb_puts(&sb,buf);}
        else{sb_putc(&sb,(char)c);}
    }
    sb_puts(&sb,"\"}");
    return sb.d;
}

/* ============ Main ============ */
int main(int argc,char**argv){
    if(argc<3){fprintf(stderr,"Usage: %s <data_dir> <base_url>\n",argv[0]);return 1;}
    const char*data_dir=argv[1];
    const char*base_url=argv[2];

    /* Read task.json */
    char tpath[4096];
    sprintf(tpath,"%s/task.json",data_dir);
    size_t tlen;char*tdata=read_file(tpath,&tlen);
    if(!tdata){fprintf(stderr,"Cannot read task.json\n");return 1;}
    jp tj={tdata,tlen,0};
    jv*tjv=jp_val(&tj);
    const char*api_key=jv_get(tjv,"api_key")->str;
    const char*model=jv_get(tjv,"model")->str;
    const char*system_msg=jv_get(tjv,"system")->str;
    const char*user_msg=jv_get(tjv,"user")->str;
    /* tools: store raw JSON */
    jv*tools_jv=jv_get(tjv,"tools");
    /* We need to serialize tools back. Let's find the raw substring. */
    /* Actually let's re-serialize from parsed value */
