    while(sent<req.len){
        ssize_t w=write(fd,req.d+sent,req.len-sent);
        if(w<=0){close(fd);freeaddrinfo(res);*status=-1;free(req.d);return NULL;}
        sent+=w;
    }

    sbuf resp;sb_init(&resp);
    char tmp[65536];
    while(1){
        ssize_t r=read(fd,tmp,sizeof(tmp));
        if(r<0){if(errno==EINTR)continue;break;}
        if(r==0)break;
        sb_append(&resp,tmp,(size_t)r);
    }
    close(fd);

    *status=0;
    if(resp.len>12&&(strncmp(resp.d,"HTTP/1.1 ",9)==0||strncmp(resp.d,"HTTP/1.0 ",9)==0)){
        *status=atoi(resp.d+9);
    }
    char*sep=strstr(resp.d,"\r\n\r\n");
    if(!sep){*status=-1;free(resp.d);return NULL;}
    size_t hdr_len=(size_t)(sep-resp.d)+4;
    size_t blen=resp.len-hdr_len;
    char*body_out=malloc(blen+1);
    memcpy(body_out,resp.d+hdr_len,blen);
    body_out[blen]=0;
    free(resp.d);
    return body_out;
}

/* ============ CSV parser ============ */
typedef struct{char*sku;char*name;long long price_cents;char*currency;long long stock;}inv_item;
static inv_item*inv=NULL;static int inv_n=0,inv_cap=0;

static char*csv_parse_field(const char*data,size_t len,size_t*pos){
    sbuf sb;sb_init(&sb);
    if(*pos<len&&data[*pos]=='"'){
        (*pos)++;
        while(*pos<len){
            if(data[*pos]=='"'){
                if(*pos+1<len&&data[*pos+1]=='"'){sb_putc(&sb,'"');*pos+=2;}
                else{(*pos)++;break;}
            }else{sb_putc(&sb,data[*pos]);(*pos)++;}
        }
    }else{
        while(*pos<len&&data[*pos]!=','&&data[*pos]!='\r'&&data[*pos]!='\n'){sb_putc(&sb,data[*pos]);(*pos)++;}
    }
    return sb.d;
}

static void parse_csv(const char*data,size_t len){
    size_t pos=0;
    if(len>=3&&(unsigned char)data[0]==0xEF&&(unsigned char)data[1]==0xBB&&(unsigned char)data[2]==0xBF)pos=3;
    /* skip header line: find end of first record */
    while(pos<len){
        if(data[pos]=='\r'&&pos+1<len&&data[pos+1]=='\n'){pos+=2;break;}
        if(data[pos]=='\n'){pos++;break;}
        pos++;
    }
    while(pos<len){
        char*fields[5]={NULL,NULL,NULL,NULL,NULL};
        int fi=0;
        while(fi<5&&pos<len){
            fields[fi]=csv_parse_field(data,len,&pos);
            fi++;
            if(pos<len&&data[pos]==','){pos++;}
            else break;
        }
        /* skip line ending */
        if(pos<len&&data[pos]=='\r')pos++;
        if(pos<len&&data[pos]=='\n')pos++;
        if(fi<5){for(int i=0;i<fi;i++)free(fields[i]);continue;}
        if(inv_n>=inv_cap){inv_cap=inv_cap?inv_cap*2:64;inv=realloc(inv,inv_cap*sizeof(inv_item));}
        inv_item*it=&inv[inv_n++];
        it->sku=fields[0];it->name=fields[1];
        it->price_cents=strtoll(fields[2],NULL,10);
        it->currency=fields[3];
        it->stock=strtoll(fields[4],NULL,10);
    }
}

/* ============ Rates ============ */
typedef struct{char*cur;long long rate;}rate_ent;
static rate_ent*rates=NULL;static int rates_n=0;
static long long get_rate(const char*cur){
    for(int i=0;i<rates_n;i++)if(strcmp(rates[i].cur,cur)==0)return rates[i].rate;
    return 1000000;
}

/* ============ Message structures ============ */
typedef struct{char*id;char*type;char*name;char*arguments;}tcall;
typedef struct{char*role;char*content;int content_null;tcall*tcs;int n_tcs;char*tool_call_id;}msg;
static msg*msgs=NULL;static int n_msgs=0,msgs_cap=0;

static void add_msg(msg m){
    if(n_msgs>=msgs_cap){msgs_cap=msgs_cap?msgs_cap*2:16;msgs=realloc(msgs,msgs_cap*sizeof(msg));}
    msgs[n_msgs++]=m;
}

/* ============ Serialize conversation to JSON ============ */
static void serialize_msgs(sbuf*sb){
    sb_putc(sb,'[');
    for(int i=0;i<n_msgs;i++){
        if(i)sb_putc(sb,',');
        sb_putc(sb,'{');
        sb_puts(sb,"\"role\":");enc_json_str(sb,msgs[i].role);
        sb_putc(sb,',');
        if(msgs[i].content_null){sb_puts(sb,"\"content\":null");}
        else{sb_puts(sb,"\"content\":");enc_json_str(sb,msgs[i].content);}
        if(msgs[i].tool_call_id){
            sb_putc(sb,',');sb_puts(sb,"\"tool_call_id\":");enc_json_str(sb,msgs[i].tool_call_id);
        }
        if(msgs[i].n_tcs>0){
            sb_putc(sb,',');sb_puts(sb,"\"tool_calls\":[");
            for(int j=0;j<msgs[i].n_tcs;j++){
                if(j)sb_putc(sb,',');
                sb_puts(sb,"{\"id\":");enc_json_str(sb,msgs[i].tcs[j].id);
                sb_puts(sb,",\"type\":");enc_json_str(sb,msgs[i].tcs[j].type);
                sb_puts(sb,",\"function\":{\"name\":");enc_json_str(sb,msgs[i].tcs[j].name);
                sb_puts(sb,",\"arguments\":");enc_json_str(sb,msgs[i].tcs[j].arguments);
                sb_puts(sb,"}}");
            }
            sb_putc(sb,']');
        }
        sb_putc(sb,'}');
    }
    sb_putc(sb,']');
}

/* ============ Tool execution ============ */
static void enc_json_str_inner(sbuf*sb,const char*s){
    if(!s)return;
    for(const unsigned char*p=(const unsigned char*)s;*p;p++){
        unsigned char c=*p;
        if(c=='"'){sb_puts(sb,"\\\"");}
        else if(c=='\\'){sb_puts(sb,"\\\\");}
        else if(c=='\b'){sb_puts(sb,"\\b");}
        else if(c=='\f'){sb_puts(sb,"\\f");}
        else if(c=='\n'){sb_puts(sb,"\\n");}
        else if(c=='\r'){sb_puts(sb,"\\r");}
        else if(c=='\t'){sb_puts(sb,"\\t");}
        else if(c<0x20){char buf[8];sprintf(buf,"\\u%04x",c);sb_puts(sb,buf);}
        else{sb_putc(sb,(char)c);}
    }
}

static char*exec_tool(const char*name,const char*args_json){
    if(!args_json)args_json="{}";
    if(strcmp(name,"inventory_lookup")==0){
        jp j={args_json,strlen(args_json),0,0};
        jv*obj=jp_val(&j);
        jv*skuv=jv_get(obj,"sku");
        if(!skuv||skuv->type!=JV_STR){
            sbuf sb;sb_init(&sb);
            sb_puts(&sb,"{\"error\":\"unknown sku: \"}");
            return sb.d;
        }
        const char*sku=skuv->str;
        for(int i=0;i<inv_n;i++){
            if(strcmp(inv[i].sku,sku)==0){
                sbuf sb;sb_init(&sb);
                char buf[64];
                sb_puts(&sb,"{\"sku\":");enc_json_str(&sb,inv[i].sku);
                sb_puts(&sb,",\"name\":");enc_json_str(&sb,inv[i].name);
                sprintf(buf,",\"price_cents\":%lld",inv[i].price_cents);sb_puts(&sb,buf);
                sb_puts(&sb,",\"currency\":");enc_json_str(&sb,inv[i].currency);
                sprintf(buf,",\"stock\":%lld",inv[i].stock);sb_puts(&sb,buf);
                sb_putc(&sb,'}');
                return sb.d;
            }
        }
        sbuf sb;sb_init(&sb);
        sb_puts(&sb,"{\"error\":\"unknown sku: ");
        enc_json_str_inner(&sb,sku);
        sb_puts(&sb,"\"}");
        return sb.d;
    }
    if(strcmp(name,"convert_currency")==0){
        jp j={args_json,strlen(args_json),0,0};
        jv*obj=jp_val(&j);
        jv*amt_v=jv_get(obj,"amount_cents");
        jv*from_v=jv_get(obj,"from");
        jv*to_v=jv_get(obj,"to");
        long long amount=0;
        if(amt_v&&amt_v->type==JV_NUM)amount=strtoll(amt_v->str,NULL,10);
        const char*from=(from_v&&from_v->type==JV_STR)?from_v->str:"USD";
        const char*to=(to_v&&to_v->type==JV_STR)?to_v->str:"USD";
        long long rf=get_rate(from),rt=get_rate(to);
        long long num=2*amount*rt+rf;
        long long den=2*rf;
        long long result=num/den;
        sbuf sb;sb_init(&sb);
        char buf[64];
        sprintf(buf,"{\"amount_cents\":%lld,\"currency\":",result);sb_puts(&sb,buf);
        enc_json_str(&sb,to);
        sb_putc(&sb,'}');
        return sb.d;
    }
    /* unknown tool */
    sbuf sb;sb_init(&sb);
    sb_puts(&sb,"{\"error\":\"unknown tool: ");
    enc_json_str_inner(&sb,name);
    sb_puts(&sb,"\"}");
    return sb.d;
}

/* ============ Extract raw JSON substring for a key at top level ============ */
static char*extract_raw_value(const char*json,size_t jlen,const char*key){
    /* Simple scanner: find "key" at depth 1 (inside top-level object), then extract value */
    size_t i=0;
    /* skip to first { */
    while(i<jlen&&json[i]!='{')i++;
    if(i>=jlen)return NULL;
    i++; /* skip { */
    int depth=1;
    while(i<jlen&&depth>0){
        /* skip whitespace */
        while(i<jlen&&(json[i]==' '||json[i]=='\t'||json[i]=='\n'||json[i]=='\r'))i++;
        if(i>=jlen)break;
        if(json[i]=='}'){depth--;i++;continue;}
        if(json[i]==']'){depth--;i++;continue;}
        if(json[i]==','){i++;continue;}
        if(json[i]==':'){i++;continue;}
        if(json[i]=='"'){
            /* this is a key (at depth 1) or a value */
            size_t start=i+1;
            i++;
            while(i<jlen&&json[i]!='"'){if(json[i]=='\\')i++;i++;}
            if(i<jlen)i++; /* skip closing " */
            size_t klen=i-start;
            /* check if this is the key we want and we're at depth 1 expecting a key */
            /* At depth 1, after { or , we expect a key */
            /* Simple heuristic: if next non-ws char is ':', this was a key */
            size_t save=i;
            while(i<jlen&&(json[i]==' '||json[i]=='\t'||json[i]=='\n'||json[i]=='\r'))i++;
            if(i<jlen&&json[i]==':'&&klen==strlen(key)&&memcmp(json+start,key,klen)==0){
                i++; /* skip : */
                while(i<jlen&&(json[i]==' '||json[i]=='\t'||json[i]=='\n'||json[i]=='\r'))i++;
                size_t vstart=i;
                /* now parse the value to find its end */
                int vdepth=0;
                while(i<jlen){
                    char c=json[i];
                    if(c=='{'||c=='['){vdepth++;i++;}
                    else if(c=='}'||c==']'){vdepth--;i++;if(vdepth==0)break;}
                    else if(c=='"'){i++;while(i<jlen&&json[i]!='"'){if(json[i]=='\\')i++;i++;}if(i<jlen)i++;}
                    else{i++;}
                }
                size_t vlen=i-vstart;
                char*res=malloc(vlen+1);
                memcpy(res,json+vstart,vlen);
                res[vlen]=0;
                return res;
            }
            i=save; /* restore if not the key */
        }else{
            /* value: number, true, false, null */
            while(i<jlen&&json[i]!=','&&json[i]!='}'&&json[i]!=']'&&json[i]!=' '&&json[i]!='\t'&&json[i]!='\n'&&json[i]!='\r')i++;
        }
    }
    return NULL;
}

/* ============ Main ============ */
int main(int argc,char**argv){
    if(argc<3){fprintf(stderr,"Usage: %s <data_dir> <base_url>\n",argv[0]);return 1;}
    const char*data_dir=argv[1];
    const char*base_url=argv[2];

    char tpath[4096];
    /* Read task.json */
    sprintf(tpath,"%s/task.json",data_dir);
    size_t tlen;char*tdata=read_file(tpath,&tlen);
    if(!tdata){fprintf(stderr,"Cannot read task.json\n");return 1;}
    jp tj={tdata,tlen,0,0};
    jv*tjv=jp_val(&tj);
    jv*api_key_v=jv_get(tjv,"api_key");
    jv*model_v=jv_get(tjv,"model");
    jv*system_v=jv_get(tjv,"system");
    jv*user_v=jv_get(tjv,"user");
    const char*api_key=api_key_v&&api_key_v->type==JV_STR?api_key_v->str:"";
    const char*model=model_v&&model_v->type==JV_STR?model_v->str:"";
    const char*system_msg=system_v&&system_v->type==JV_STR?system_v->str:"";
    const char*user_msg=user_v&&user_v->type==JV_STR?user_v->str:"";

    /* Extract raw tools array */
    char*tools_raw=extract_raw_value(tdata,tlen,"tools");
    if(!tools_raw)tools_raw=strdup("[]");

    /* Read inventory.csv */
    sprintf(tpath,"%s/inventory.csv",data_dir);
    size_t clen=0;char*cdata=read_file(tpath,&clen);
    if(cdata&&clen>0)parse_csv(cdata,clen);

    /* Read rates.json */
    sprintf(tpath,"%s/rates.json",data_dir);
    size_t rlen2=0;char*rdata=read_file(tpath,&rlen2);
    if(rdata&&rlen2>0){
        jp rj={rdata,rlen2,0,0};
        jv*rjv=jp_val(&rj);
        jv*rrates=jv_get(rjv,"rates");
        if(rrates&&rrates->type==JV_OBJ){
            rates=malloc(rrates->obj.n*sizeof(rate_ent));
            for(size_t i=0;i<rrates->obj.n;i++){
                rates[rates_n].cur=strdup(rrates->obj.keys[i]);
                rates[rates_n].rate=strtoll(rrates->obj.vals[i]->str,NULL,10);
                rates_n++;
            }
        }
    }

    /* Initialize conversation */
    msg sysm={strdup("system"),strdup(system_msg),0,NULL,0,NULL};
    add_msg(sysm);
    msg usr={strdup("user"),strdup(user_msg),0,NULL,0,NULL};
    add_msg(usr);

    /* Main loop */
    long long total_prompt=0,total_completion=0,total_tokens=0;
    int n_requests=0;

    while(1){
        sbuf body;sb_init(&body);
        sb_putc(&body,'{');
        sb_puts(&body,"\"model\":");enc_json_str(&body,model);
        sb_puts(&body,",\"messages\":");
        serialize_msgs(&body);
        sb_puts(&body,",\"tools\":");
        sb_puts(&body,tools_raw);
        sb_puts(&body,",\"tool_choice\":\"auto\"");
        sb_putc(&body,'}');

        n_requests++;
        int status=0;
        char*resp_body=http_post(base_url,api_key,body.d,body.len,&status);
        free(body.d);

        if(status!=200||!resp_body){
            const char*err_msg="";
            if(resp_body){
                jp ej={resp_body,strlen(resp_body),0,0};
                jv*ejv=jp_val(&ej);
                jv*err=jv_get(ejv,"error");
                if(err){jv*em=jv_get(err,"message");if(em&&em->type==JV_STR)err_msg=em->str;}
            }
            printf("ERROR %d %s\n",status,err_msg);
            fflush(stdout);
            free(resp_body);
            return 0;
        }

        /* Parse response */
        jp rj={resp_body,strlen(resp_body),0,0};
        jv*resp=jp_val(&rj);

        /* usage */
        jv*usage=jv_get(resp,"usage");
        if(usage&&usage->type==JV_OBJ){
            jv*pt=jv_get(usage,"prompt_tokens");
            jv*ct=jv_get(usage,"completion_tokens");
            jv*tt=jv_get(usage,"total_tokens");
            if(pt&&pt->type==JV_NUM)total_prompt+=strtoll(pt->str,NULL,10);
            if(ct&&ct->type==JV_NUM)total_completion+=strtoll(ct->str,NULL,10);
            if(tt&&tt->type==JV_NUM)total_tokens+=strtoll(tt->str,NULL,10);
        }

        /* choices[0] */
        jv*choices=jv_get(resp,"choices");
        if(!choices||choices->type!=JV_ARR||choices->arr.n==0){
            printf("ERROR 200 no choices\n");fflush(stdout);free(resp_body);return 0;
        }
        jv*choice=choices->arr.items[0];
        jv*fr=jv_get(choice,"finish_reason");
        jv*message=jv_get(choice,"message");
        const char*finish=fr&&fr->type==JV_STR?fr->str:"";

        if(strcmp(finish,"stop")==0){
            jv*cont=jv_get(message,"content");
            const char*final_content=(cont&&cont->type==JV_STR)?cont->str:"";
            printf("FINAL %s\n",final_content);
            free(resp_body);
            break;
        }

        if(strcmp(finish,"tool_calls")==0){
            jv*cont=jv_get(message,"content");
            if(cont&&cont->type==JV_STR){
                printf("SAY %s\n",cont->str);
            }

            jv*tcs=jv_get(message,"tool_calls");
            int n_tc=(tcs&&tcs->type==JV_ARR)?(int)tcs->arr.n:0;
            tcall*calls=malloc((n_tc>0?n_tc:1)*sizeof(tcall));
            for(int i=0;i<n_tc;i++){
                jv*tc=tcs->arr.items[i];
                jv*id=jv_get(tc,"id");
                jv*tp2=jv_get(tc,"type");
                jv*fn=jv_get(tc,"function");
                jv*fn_name=jv_get(fn,"name");
                jv*fn_args=jv_get(fn,"arguments");
                calls[i].id=strdup(id&&id->type==JV_STR?id->str:"");
                calls[i].type=strdup(tp2&&tp2->type==JV_STR?tp2->str:"function");
                calls[i].name=strdup(fn_name&&fn_name->type==JV_STR?fn_name->str:"");
                calls[i].arguments=strdup(fn_args&&fn_args->type==JV_STR?fn_args->str:"{}");
                printf("CALL %s %s\n",calls[i].id,calls[i].name);
            }

            char**results=malloc((n_tc>0?n_tc:1)*sizeof(char*));
            for(int i=0;i<n_tc;i++){
                results[i]=exec_tool(calls[i].name,calls[i].arguments);
                printf("RESULT %s %s\n",calls[i].id,results[i]);
            }

            /* Append assistant message */
            msg am;
            am.role=strdup("assistant");
            if(cont&&cont->type==JV_STR){am.content=strdup(cont->str);am.content_null=0;}
            else{am.content=NULL;am.content_null=1;}
            am.tcs=calls;am.n_tcs=n_tc;am.tool_call_id=NULL;
            add_msg(am);

            /* Append tool messages */
            for(int i=0;i<n_tc;i++){
                msg tm;
                tm.role=strdup("tool");
                tm.content=results[i];tm.content_null=0;
                tm.tcs=NULL;tm.n_tcs=0;
                tm.tool_call_id=strdup(calls[i].id);
                add_msg(tm);
            }
        }else{
            /* unexpected finish_reason, treat as stop */
            jv*cont=jv_get(message,"content");
            const char*final_content=(cont&&cont->type==JV_STR)?cont->str:"";
            printf("FINAL %s\n",final_content);
            free(resp_body);
            break;
        }

        fflush(stdout);
        free(resp_body);
    }

    printf("USAGE prompt=%lld completion=%lld total=%lld requests=%d\n",
        total_prompt,total_completion,total_tokens,n_requests);
    fflush(stdout);
    return 0;
}

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.math.BigInteger;

public class Main {

    static class JNode {
        int type; // 0=null,1=bool,2=number,3=string,4=array,5=object
        Object value;
        int start, end;
        JNode(int t, Object v, int s, int e) { type=t; value=v; start=s; end=e; }
        @SuppressWarnings("unchecked")
        Map<String,JNode> obj() { return (Map<String,JNode>)value; }
        @SuppressWarnings("unchecked")
        List<JNode> arr() { return (List<JNode>)value; }
        String str() { return (String)value; }
        long lng() { return Long.parseLong((String)value); }
        BigInteger big() { return new BigInteger((String)value); }
    }

    static class JP {
        String s; int pos;
        JP(String s) { this.s=s; this.pos=0; }
        void ws() { while(pos<s.length()){char c=s.charAt(pos);if(c==' '||c=='\t'||c=='\n'||c=='\r')pos++;else break;} }
        JNode parse() { ws(); return pv(); }
        JNode pv() {
            char c=s.charAt(pos);
            if(c=='{')return po(); if(c=='[')return pa(); if(c=='"')return ps();
            if(c=='t')return pl("true",0,null); if(c=='f')return pl("false",1,Boolean.FALSE); if(c=='n')return pl("null",0,null);
            return pn();
        }
        JNode po() {
            int st=pos; pos++; Map<String,JNode> m=new LinkedHashMap<>(); ws();
            if(s.charAt(pos)=='}'){pos++;return new JNode(5,m,st,pos);}
            while(true){ws();JNode k=ps();ws();ec(':');JNode v=pv();m.put(k.str(),v);ws();
                if(s.charAt(pos)==','){pos++;continue;} if(s.charAt(pos)=='}'){pos++;break;} throw new RuntimeException("obj");}
            return new JNode(5,m,st,pos);
        }
        JNode pa() {
            int st=pos; pos++; List<JNode> l=new ArrayList<>(); ws();
            if(s.charAt(pos)==']'){pos++;return new JNode(4,l,st,pos);}
            while(true){l.add(pv());ws();
                if(s.charAt(pos)==','){pos++;continue;} if(s.charAt(pos)==']'){pos++;break;} throw new RuntimeException("arr");}
            return new JNode(4,l,st,pos);
        }
        JNode ps() {
            int st=pos; pos++; StringBuilder sb=new StringBuilder();
            while(pos<s.length()){char c=s.charAt(pos);
                if(c=='"'){pos++;break;}
                if(c=='\\'){pos++;char e=s.charAt(pos);pos++;
                    switch(e){case '"':sb.append('"');break;case '\\':sb.append('\\');break;case '/':sb.append('/');break;
                    case 'b':sb.append('\b');break;case 'f':sb.append('\f');break;case 'n':sb.append('\n');break;
                    case 'r':sb.append('\r');break;case 't':sb.append('\t');break;
                    case 'u':int cp=Integer.parseInt(s.substring(pos,pos+4),16);pos+=4;
                        if(cp>=0xD800&&cp<=0xDBFF&&pos+1<s.length()&&s.charAt(pos)=='\\'&&s.charAt(pos+1)=='u'){
                            pos+=2;int lo=Integer.parseInt(s.substring(pos,pos+4),16);pos+=4;
                            cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);}
                        sb.appendCodePoint(cp);break;
                    default:throw new RuntimeException("esc");}}
