    public static void main(String[] args) throws Exception {
        String dataDir=args[0];
        String baseUrl=args[1];

        String taskRaw=new String(Files.readAllBytes(Paths.get(dataDir,"task.json")),StandardCharsets.UTF_8);
        String csvRaw=new String(Files.readAllBytes(Paths.get(dataDir,"inventory.csv")),StandardCharsets.UTF_8);
        String ratesRaw=new String(Files.readAllBytes(Paths.get(dataDir,"rates.json")),StandardCharsets.UTF_8);

        JP tp=new JP(taskRaw);
        JNode task=tp.parse();
        String apiKey=task.obj().get("api_key").str();
        String model=task.obj().get("model").str();
        String system=task.obj().get("system").str();
        String user=task.obj().get("user").str();
        String toolsRaw=taskRaw.substring(task.obj().get("tools").start,task.obj().get("tools").end);

        // Parse inventory
        Map<String,String[]> inv=new LinkedHashMap<>();
        List<String[]> csv=parseCsv(csvRaw);
        for(int r=1;r<csv.size();r++){
            String[] row=csv.get(r);
            if(row.length<5)continue;
            inv.put(row[0],row);
        }

        // Parse rates
        JP rp=new JP(ratesRaw);
        JNode ratesNode=rp.parse();
        Map<String,BigInteger> rates=new HashMap<>();
        for(Map.Entry<String,JNode> e:ratesNode.obj().get("rates").obj().entrySet()){
            rates.put(e.getKey(),e.getValue().big());
        }

        // Conversation: list of raw JSON message strings
        List<String> conversation=new ArrayList<>();
        conversation.add("{\"role\":\"system\",\"content\":"+jsonStr(system)+"}");
        conversation.add("{\"role\":\"user\",\"content\":"+jsonStr(user)+"}");

        long totPrompt=0,totCompletion=0,totTotal=0;
        int numRequests=0;

        String endpoint=baseUrl+"/chat/completions";

        while(true){
            StringBuilder body=new StringBuilder();
            body.append("{\"model\":").append(jsonStr(model));
            body.append(",\"messages\":[");
            for(int i=0;i<conversation.size();i++){
                if(i>0)body.append(',');
                body.append(conversation.get(i));
            }
            body.append("],\"tools\":").append(toolsRaw);
            body.append(",\"tool_choice\":\"auto\"}");

            String[] resp=httpPost(endpoint,apiKey,body.toString());
            numRequests++;
            int status=Integer.parseInt(resp[0]);
            String respBody=resp[1];

            if(status!=200){
                // print lines produced so far (already printed), then error
                try{
                    JP ep=new JP(respBody);
                    JNode err=ep.parse();
                    String msg=err.obj().get("error").obj().get("message").str();
                    System.out.println("ERROR "+status+" "+msg);
                }catch(Exception e){
                    System.out.println("ERROR "+status+" "+respBody);
                }
                System.out.flush();
                return;
            }

            JP jp=new JP(respBody);
            JNode respNode=jp.parse();
            JNode choice=respNode.obj().get("choices").arr().get(0);
            JNode msg=choice.obj().get("message");
            String finish=choice.obj().get("finish_reason").str();

            // usage
            if(respNode.obj().containsKey("usage")){
                JNode usage=respNode.obj().get("usage");
                if(usage.obj().containsKey("prompt_tokens"))totPrompt+=usage.obj().get("prompt_tokens").lng();
                if(usage.obj().containsKey("completion_tokens"))totCompletion+=usage.obj().get("completion_tokens").lng();
                if(usage.obj().containsKey("total_tokens"))totTotal+=usage.obj().get("total_tokens").lng();
            }

            if(finish.equals("stop")){
                String content=msg.obj().containsKey("content")&&msg.obj().get("content").type==3?msg.obj().get("content").str():"";
                System.out.println("FINAL "+content);
                System.out.println("USAGE prompt="+totPrompt+" completion="+totCompletion+" total="+totTotal+" requests="+numRequests);
                System.out.flush();
                return;
            }

            // tool_calls
            if(msg.obj().containsKey("content")&&msg.obj().get("content").type==3){
                System.out.println("SAY "+msg.obj().get("content").str());
            }

            // Extract raw assistant message (keep role, content, tool_calls; may keep refusal/annotations)
            String rawMsg=respBody.substring(msg.start,msg.end);
            conversation.add(rawMsg);

            List<JNode> toolCalls=msg.obj().get("tool_calls").arr();
            for(JNode tc:toolCalls){
                String id=tc.obj().get("id").str();
                String name=tc.obj().get("function").obj().get("name").str();
                System.out.println("CALL "+id+" "+name);
            }

            for(JNode tc:toolCalls){
                String id=tc.obj().get("id").str();
                String name=tc.obj().get("function").obj().get("name").str();
                String argsStr=tc.obj().get("function").obj().get("arguments").str();
                String result=executeTool(name,argsStr,inv,rates);
                System.out.println("RESULT "+id+" "+result);
                conversation.add("{\"role\":\"tool\",\"tool_call_id\":"+jsonStr(id)+",\"content\":"+jsonStr(result)+"}");
            }
        }
    }

    static String executeTool(String name,String argsStr,Map<String,String[]> inv,Map<String,BigInteger> rates){
        if(name.equals("inventory_lookup")){
            JP ap=new JP(argsStr);
            JNode args=ap.parse();
            String sku=args.obj().get("sku").str();
            String[] row=inv.get(sku);
            if(row==null)return "{\"error\":\"unknown sku: "+escJson(sku)+"\"}";
            return "{\"sku\":"+jsonStr(row[0])+",\"name\":"+jsonStr(row[1])+",\"price_cents\":"+row[2]+",\"currency\":"+jsonStr(row[3])+",\"stock\":"+row[4]+"}";
        } else if(name.equals("convert_currency")){
            JP ap=new JP(argsStr);
            JNode args=ap.parse();
            BigInteger amount=new BigInteger((String)args.obj().get("amount_cents").value);
            String from=args.obj().get("from").str();
            String to=args.obj().get("to").str();
            BigInteger rFrom=rates.get(from);
            BigInteger rTo=rates.get(to);
            // (2*amount*rTo + rFrom) / (2*rFrom)
            BigInteger num=BigInteger.valueOf(2).multiply(amount).multiply(rTo).add(rFrom);
            BigInteger den=BigInteger.valueOf(2).multiply(rFrom);
            BigInteger converted=num.divide(den);
            return "{\"amount_cents\":"+converted+",\"currency\":"+jsonStr(to)+"}";
        } else {
            return "{\"error\":\"unknown tool: "+escJson(name)+"\"}";
        }
    }
}

