import Foundation

// MARK: - JSON string encoding (for output)
func jsonEncodeString(_ s: String) -> String {
    var result = "\""
    for scalar in s.unicodeScalars {
        switch scalar {
        case "\"": result += "\\\""
        case "\\": result += "\\\\"
        case "\u{08}": result += "\\b"
        case "\u{0C}": result += "\\f"
        case "\n": result += "\\n"
        case "\r": result += "\\r"
        case "\t": result += "\\t"
        default:
            if scalar.value < 0x20 {
                result += String(format: "\\u%04x", scalar.value)
            } else {
                result.unicodeScalars.append(scalar)
            }
        }
    }
    result += "\""
    return result
}

// MARK: - CSV Parser (RFC 4180)
func parseCSV(_ data: Data) -> [[String]] {
    var text = String(data: data, encoding: .utf8)!
    if text.hasPrefix("\u{FEFF}") {
        text = String(text.dropFirst())
    }

    var records: [[String]] = []
    var fields: [String] = []
    var currentField = ""
    var inQuotes = false
    let chars = Array(text)
    let n = chars.count
    var i = 0

    while i < n {
        let ch = chars[i]
        if inQuotes {
            if ch == "\"" {
                if i + 1 < n && chars[i + 1] == "\"" {
                    currentField.append("\"")
                    i += 2
                } else {
                    inQuotes = false
                    i += 1
                }
            } else {
                currentField.append(ch)
                i += 1
            }
        } else {
            if ch == "\"" {
                inQuotes = true
                i += 1
            } else if ch == "," {
                fields.append(currentField)
                currentField = ""
                i += 1
            } else if ch == "\r" {
                if i + 1 < n && chars[i + 1] == "\n" {
                    fields.append(currentField)
                    currentField = ""
                    records.append(fields)
                    fields = []
                    i += 2
                } else {
                    currentField.append(ch)
                    i += 1
                }
            } else if ch == "\n" {
                fields.append(currentField)
                currentField = ""
                records.append(fields)
                fields = []
                i += 1
            } else {
                currentField.append(ch)
                i += 1
            }
        }
    }

    if !currentField.isEmpty || !fields.isEmpty {
        fields.append(currentField)
        records.append(fields)
    }

    return records
}

// MARK: - Data structures
struct ToolCallData {
    let id: String
    let type: String
    let name: String
    let arguments: String
}

struct MessageData {
    let role: String
    let content: String?
    let toolCalls: [ToolCallData]?
}

// MARK: - Serialize message to JSON string
func serializeMessage(_ msg: MessageData) -> String {
    var parts: [String] = []
    parts.append("\"role\":\(jsonEncodeString(msg.role))")
    if let c = msg.content {
        parts.append("\"content\":\(jsonEncodeString(c))")
    } else {
        parts.append("\"content\":null")
    }
    if let tcs = msg.toolCalls {
        var tcStrs: [String] = []
        for tc in tcs {
            let tcStr = "{\"id\":\(jsonEncodeString(tc.id)),\"type\":\(jsonEncodeString(tc.type)),\"function\":{\"name\":\(jsonEncodeString(tc.name)),\"arguments\":\(jsonEncodeString(tc.arguments))}}"
            tcStrs.append(tcStr)
        }
        parts.append("\"tool_calls\":[\(tcStrs.joined(separator: ","))]")
    }
    return "{\(parts.joined(separator: ","))}"
}

// MARK: - Serialize conversation to JSON body
func serializeRequestBody(model: String, messages: [MessageData], toolsRaw: String) -> String {
    let msgStrs = messages.map { serializeMessage($0) }
    let body = "{\"model\":\(jsonEncodeString(model)),\"messages\":[\(msgStrs.joined(separator: ","))],\"tools\":\(toolsRaw),\"tool_choice\":\"auto\"}"
    return body
}

// MARK: - HTTP request
func sendRequest(url: String, apiKey: String, body: String) -> (Int, Data) {
    let urlObj = URL(string: url)!
    var request = URLRequest(url: urlObj)
    request.httpMethod = "POST"
    request.setValue("Bearer \(apiKey)", forHTTPHeaderField: "Authorization")
    request.setValue("application/json", forHTTPHeaderField: "Content-Type")
    request.httpBody = body.data(using: .utf8)
    request.setValue("1.1", forHTTPHeaderField: "X-HTTP-Version")

    let semaphore = DispatchSemaphore(value: 0)
    var statusCode = 0
    var responseData = Data()

    let config = URLSessionConfiguration.default
    config.httpAdditionalHeaders = ["Accept": "application/json"]
    let session = URLSession(configuration: config)

    let task = session.dataTask(with: request) { data, response, error in
        if let httpResponse = response as? HTTPURLResponse {
            statusCode = httpResponse.statusCode
        }
        if let d = data {
            responseData = d
        }
        semaphore.signal()
    }
    task.resume()
    semaphore.wait()

    return (statusCode, responseData)
}

