import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    static class Type {
        int gmtoff;
        boolean isdst;
        String abbr;
        Type(int gmtoff, boolean isdst, String abbr) {
            this.gmtoff = gmtoff; this.isdst = isdst; this.abbr = abbr;
        }
    }

    static class TzifData {
        long[] transTimes;
        int[] transTypeIdx;
        Type[] types;
        String stdName, dstName;
        int stdGmtoff, dstGmtoff;
        boolean hasDst, hasRule;
        int sm, sw, sd, sh, smi, ss;
        int em, ew, ed, eh, emi, es;
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        List<String> lines = Files.readAllLines(Paths.get(dir, "queries.txt"));
        Map<String, TzifData> cache = new HashMap<>();
        StringBuilder out = new StringBuilder();

        for (String line : lines) {
            if (line.trim().isEmpty()) continue;
            String[] parts = line.split(" ");
            String qType = parts[0];
            String fileName = parts[1];
            TzifData d = cache.get(fileName);
            if (d == null) {
                d = parseTzif(dir + "/" + fileName);
                cache.put(fileName, d);
            }

            if (qType.equals("UTC")) {
                long t = Long.parseLong(parts[2]);
                out.append(line).append(" -> ").append(utcQuery(d, t)).append("\n");
            } else {
                String wall = parts[2];
                out.append(line).append(" -> ").append(localQuery(d, wall)).append("\n");
            }
        }
        System.out.print(out.toString());
    }

    static TzifData parseTzif(String path) throws Exception {
        byte[] b = Files.readAllBytes(Paths.get(path));
        int pos = 0;
        // First header: 44 bytes
        pos += 4; // TZif
        pos += 1; // version
        pos += 15; // unused
        int isutcnt1 = readInt32(b, pos); pos += 4;
        int isstdcnt1 = readInt32(b, pos); pos += 4;
        int leapcnt1 = readInt32(b, pos); pos += 4;
        int timecnt1 = readInt32(b, pos); pos += 4;
        int typecnt1 = readInt32(b, pos); pos += 4;
        int charcnt1 = readInt32(b, pos); pos += 4;
        // Skip first data block
        pos += timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1;
        // Second header: 44 bytes
        pos += 4; pos += 1; pos += 15;
        int isutcnt = readInt32(b, pos); pos += 4;
        int isstdcnt = readInt32(b, pos); pos += 4;
        int leapcnt = readInt32(b, pos); pos += 4;
        int timecnt = readInt32(b, pos); pos += 4;
        int typecnt = readInt32(b, pos); pos += 4;
        int charcnt = readInt32(b, pos); pos += 4;

        TzifData d = new TzifData();
        d.transTimes = new long[timecnt];
        d.transTypeIdx = new int[timecnt];
        d.types = new Type[typecnt];

        for (int i = 0; i < timecnt; i++) {
            d.transTimes[i] = readInt64(b, pos); pos += 8;
        }
        for (int i = 0; i < timecnt; i++) {
            d.transTypeIdx[i] = b[pos] & 0xFF; pos++;
        }
        for (int i = 0; i < typecnt; i++) {
            int gmtoff = readInt32(b, pos); pos += 4;
            boolean isdst = b[pos] != 0; pos++;
            int abbrIdx = b[pos] & 0xFF; pos++;
            d.types[i] = new Type(gmtoff, isdst, null); // abbr filled later
        }
        byte[] abbrs = Arrays.copyOfRange(b, pos, pos + charcnt); pos += charcnt;
        for (int i = 0; i < typecnt; i++) {
            int idx = 0;
            for (int j = 0; j < i; j++) {
                idx = d.types[j].abbr.length();
                while (idx < abbrs.length && abbrs[idx] != 0) idx++;
                idx++; // skip NUL
            }
            // Actually let's recompute: find the abbreviation for type i
            // We need to find the start of the i-th abbreviation
            // Let me redo this properly
        }
        // Redo abbreviation parsing
        for (int i = 0; i < typecnt; i++) {
            int abbrIdx = getAbbrIdx(b, pos - charcnt - typecnt * 6 + i * 6 + 5);
            // Actually the abbr index was stored in the type record. Let me re-read.
            // I'll store it temporarily.
        }
        // Let me redo the type parsing to store abbr index
        // Actually let me restructure: read abbr indices first, then resolve
        // I'll re-parse types
        int typeStart = pos - charcnt - typecnt * 6;
        for (int i = 0; i < typecnt; i++) {
            int abbrIdx = b[typeStart + i * 6 + 5] & 0xFF;
            d.types[i] = new Type(readInt32(b, typeStart + i * 6), b[typeStart + i * 6 + 4] != 0, null);
            d.types[i].abbr = readNullTerminated(abbrs, abbrIdx);
        }
        // Skip leap seconds, isstd, isut
        pos += leapcnt * 12 + isstdcnt + isutcnt;
        // Footer: \n POSIX \n
        pos++; // skip newline
        int footStart = pos;
        while (pos < b.length && b[pos] != '\n') pos++;
        String posixStr = new String(b, footStart, pos - footStart, "ISO-8859-1");
        parsePosix(d, posixStr);
        return d;
    }

    static int getAbbrIdx(byte[] b, int off) { return b[off] & 0xFF; }

    static String readNullTerminated(byte[] arr, int start) {
        int end = start;
        while (end < arr.length && arr[end] != 0) end++;
        return new String(arr, start, end - start, java.nio.charset.StandardCharsets.ISO_8859_1);
    }

    static void parsePosix(TzifData d, String s) {
        if (s == null || s.isEmpty()) {
            d.hasDst = false; d.hasRule = false;
            d.stdName = ""; d.stdGmtoff = 0;
            return;
        }
        int pos = 0;
        // Parse std name
        int[] r = parseName(s, pos);
        d.stdName = s.substring(pos, r[0]); pos = r[0];
        // Parse std offset
        r = parseOffset(s, pos);
        d.stdGmtoff = -r[0]; pos = r[1]; // gmtoff = -posix_offset
        d.hasDst = false; d.hasRule = false;
        d.dstGmtoff = d.stdGmtoff + 3600;
        if (pos >= s.length()) return;
        // Parse dst name
        r = parseName(s, pos);
        d.dstName = s.substring(pos, r[0]); pos = r[0];
        d.hasDst = true;
        // Parse dst offset (optional, not if next char is ',')
        if (pos < s.length() && s.charAt(pos) != ',') {
            r = parseOffset(s, pos);
            d.dstGmtoff = -r[0]; pos = r[1];
        } else {
            d.dstGmtoff = d.stdGmtoff + 3600;
        }
        // Parse rules
        if (pos < s.length() && s.charAt(pos) == ',') {
            pos++; // skip comma
            d.hasRule = true;
            r = parseRule(s, pos);
            d.sm = r[0]; d.sw = r[1]; d.sd = r[2]; d.sh = r[3]; d.smi = r[4]; d.ss = r[5];
            pos = r[6];
            if (pos < s.length() && s.charAt(pos) == ',') pos++;
            r = parseRule(s, pos);
            d.em = r[0]; d.ew = r[1]; d.ed = r[2]; d.eh = r[3]; d.emi = r[4]; d.es = r[5];
        }
    }

    static int[] parseName(String s, int pos) {
        if (s.charAt(pos) == '<') {
            int end = s.indexOf('>', pos);
            return new int[]{end + 1};
        } else {
            int end = pos;
            while (end < s.length() && Character.isLetter(s.charAt(end))) end++;
            return new int[]{end};
        }
    }

    static int[] parseOffset(String s, int pos) {
        int sign = 1;
        if (s.charAt(pos) == '+') { pos++; }
        else if (s.charAt(pos) == '-') { sign = -1; pos++; }
        int h = 0, m = 0, sec = 0;
        int start = pos;
        while (pos < s.length() && Character.isDigit(s.charAt(pos))) { h = h * 10 + (s.charAt(pos++) - '0'); }
        if (pos < s.length() && s.charAt(pos) == ':') {
            pos++;
            while (pos < s.length() && Character.isDigit(s.charAt(pos))) { m = m * 10 + (s.charAt(pos++) - '0'); }
            if (pos < s.length() && s.charAt(pos) == ':') {
                pos++;
                while (pos < s.length() && Character.isDigit(s.charAt(pos))) { sec = sec * 10 + (s.charAt(pos++) - '0'); }
            }
        }
        return new int[]{sign * (h * 3600 + m * 60 + sec), pos};
    }

    static int[] parseRule(String s, int pos) {
        // Mm.w.d[/time]
        // s.charAt(pos) should be 'M'
        pos++; // skip M
        int m = 0; while (Character.isDigit(s.charAt(pos))) m = m * 10 + (s.charAt(pos++) - '0');
        pos++; // skip .
        int w = 0; while (Character.isDigit(s.charAt(pos))) w = w * 10 + (s.charAt(pos++) - '0');
        pos++; // skip .
        int d = 0; while (Character.isDigit(s.charAt(pos))) d = d * 10 + (s.charAt(pos++) - '0');
        int h = 2, mi = 0, sec = 0;
        if (pos < s.length() && s.charAt(pos) == '/') {
            pos++;
            int sign = 1;
            if (s.charAt(pos) == '+') pos++;
            else if (s.charAt(pos) == '-') { sign = -1; pos++; }
            h = 0; while (pos < s.length() && Character.isDigit(s.charAt(pos))) h = h * 10 + (s.charAt(pos++) - '0');
            if (pos < s.length() && s.charAt(pos) == ':') {
                pos++;
                while (pos < s.length() && Character.isDigit(s.charAt(pos))) mi = mi * 10 + (s.charAt(pos++) - '0');
                if (pos < s.length() && s.charAt(pos) == ':') {
                    pos++;
                    while (pos < s.length() && Character.isDigit(s.charAt(pos))) sec = sec * 10 + (s.charAt(pos++) - '0');
                }
            }
            h *= sign;
        }
        return new int[]{m, w, d, h, mi, sec, pos};
    }

    static Type getTypeAt(TzifData d, long t) {
        if (d.transTimes.length == 0) {
            return posixType(d, t);
        }
        if (t < d.transTimes[0]) return d.types[0];
        if (t > d.transTimes[d.transTimes.length - 1]) return posixType(d, t);
        // Binary search: latest transition <= t
        int lo = 0, hi = d.transTimes.length - 1, idx = 0;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            if (d.transTimes[mid] <= t) { idx = mid; lo = mid + 1; }
            else hi = mid - 1;
        }
        return d.types[d.transTypeIdx[idx]];
    }

    static Type posixType(TzifData d, long t) {
        if (!d.hasDst || !d.hasRule) return new Type(d.stdGmtoff, false, d.stdName);
        int year = epochToYear(t);
        long startUtc = posixTransitionUtc(d, year, true);
        long endUtc = posixTransitionUtc(d, year, false);
        boolean inDst;
        if (startUtc <= endUtc) {
            inDst = t >= startUtc && t < endUtc;
        } else {
            inDst = t >= startUtc || t < endUtc;
        }
        if (inDst) return new Type(d.dstGmtoff, true, d.dstName);
        else return new Type(d.stdGmtoff, false, d.stdName);
    }

    static long posixTransitionUtc(TzifData d, int year, boolean isStart) {
        int m, w, dow, h, mi, sec, gmtoff;
        if (isStart) {
            m = d.sm; w = d.sw; dow = d.sd; h = d.sh; mi = d.smi; sec = d.ss;
            gmtoff = d.stdGmtoff;
        } else {
            m = d.em; w = d.ew; dow = d.ed; h = d.eh; mi = d.emi; sec = d.es;
            gmtoff = d.dstGmtoff;
        }
        int day = computeMDay(year, m, w, dow);
        long localSec = dateTimeToEpoch(year, m, day, h, mi, sec);
        return localSec - gmtoff; // UTC = local - gmtoff
    }

    static String utcQuery(TzifData d, long t) {
        Type type = getTypeAt(d, t);
        long localSec = t + type.gmtoff;
        String dt = epochToDateTimeStr(localSec);
        String off = formatOffset(type.gmtoff);
        return dt + off + " " + type.abbr;
    }

    static String localQuery(TzifData d, String wall) {
        // Parse wall clock
        int y = Integer.parseInt(wall.substring(0, 4));
        int mo = Integer.parseInt(wall.substring(5, 7));
        int da = Integer.parseInt(wall.substring(8, 10));
        int h = Integer.parseInt(wall.substring(11, 13));
        int mi = Integer.parseInt(wall.substring(14, 16));
        int se = Integer.parseInt(wall.substring(17, 19));
        long localEpoch = dateTimeToEpoch(y, mo, da, h, mi, se);

        // Collect all candidate (gmtoff, abbr) pairs
        Set<String> seen = new HashSet<>();
        List<int[]> candidates = new ArrayList<>(); // [gmtoff, abbrIndex]
        List<String> abbrs = new ArrayList<>();

        // From types
        for (Type tp : d.types) {
            String key = tp.gmtoff + "|" + tp.abbr;
            if (seen.add(key)) {
                candidates.add(new int[]{tp.gmtoff, -1});
                abbrs.add(tp.abbr);
            }
        }
        // From POSIX
        if (d.stdName != null && !d.stdName.isEmpty()) {
            String key = d.stdGmtoff + "|" + d.stdName;
            if (seen.add(key)) {
                candidates.add(new int[]{d.stdGmtoff, -1});
                abbrs.add(d.stdName);
            }
        }
        if (d.hasDst && d.dstName != null && !d.dstName.isEmpty()) {
            String key = d.dstGmtoff + "|" + d.dstName;
            if (seen.add(key)) {
                candidates.add(new int[]{d.dstGmtoff, -1});
                abbrs.add(d.dstName);
            }
        }

        // Enumerate and verify
        List<long[]> results = new ArrayList<>(); // [t, gmtoff, abbrIdx]
        for (int i = 0; i < candidates.size(); i++) {
            int gmtoff = candidates.get(i)[0];
            String abbr = abbrs.get(i);
            long tCand = localEpoch - gmtoff;
            Type actual = getTypeAt(d, tCand);
            if (actual.gmtoff == gmtoff && actual.abbr.equals(abbr)) {
                results.add(new long[]{tCand, gmtoff, i});
            }
        }
        results.sort((a, b) -> Long.compare(a[0], b[0]));

        if (results.size() == 1) {
            long t = results.get(0)[0];
            int gmtoff = (int)results.get(0)[1];
            String abbr = abbrs.get((int)results.get(0)[2]);
            return t + " " + formatOffset(gmtoff) + " " + abbr;
        } else if (results.size() == 2) {
            long t1 = results.get(0)[0]; int g1 = (int)results.get(0)[1]; String a1 = abbrs.get((int)results.get(0)[2]);
            long t2 = results.get(1)[0]; int g2 = (int)results.get(1)[1]; String a2 = abbrs.get((int)results.get(1)[2]);
            return t1 + " " + formatOffset(g1) + " " + a1 + " | " + t2 + " " + formatOffset(g2) + " " + a2;
        } else {
            // Gap: find the transition that skipped this wall-clock time
            // t = localEpoch - gmtoff_before
            long tGap = findGapT(d, localEpoch);
            Type typeAtGap = getTypeAt(d, tGap);
            String dt = epochToDateTimeStr(tGap + typeAtGap.gmtoff);
            String off = formatOffset(typeAtGap.gmtoff);
            return "GAP " + tGap + " " + dt + off + " " + typeAtGap.abbr;
        }
    }

    static long findGapT(TzifData d, long localEpoch) {
        // Check TZif transitions
        for (int i = 0; i < d.transTimes.length; i++) {
            long T = d.transTimes[i];
            Type before;
            if (i == 0) before = d.types[0];
            else before = d.types[d.transTypeIdx[i - 1]];
            Type after = d.types[d.transTypeIdx[i]];
            if (after.gmtoff > before.gmtoff) {
                long gapStart = T + before.gmtoff;
                long gapEnd = T + after.gmtoff;
                if (localEpoch >= gapStart && localEpoch < gapEnd) {
                    return localEpoch - before.gmtoff;
                }
            }
        }
        // Check POSIX transitions for nearby years
        int year = epochToYear(localEpoch); // approximate
        for (int yr = year - 1; yr <= year + 1; yr++) {
            if (!d.hasDst || !d.hasRule) continue;
            long startUtc = posixTransitionUtc(d, yr, true);
            long endUtc = posixTransitionUtc(d, yr, false);
            // Spring forward: STD -> DST at startUtc
            if (d.dstGmtoff > d.stdGmtoff) {
                long gapStart = startUtc + d.stdGmtoff;
                long gapEnd = startUtc + d.dstGmtoff;
                if (localEpoch >= gapStart && localEpoch < gapEnd) {
                    return localEpoch - d.stdGmtoff;
                }
            }
            // Check if end is also a spring forward (unusual)
            if (d.stdGmtoff > d.dstGmtoff) {
                long gapStart = endUtc + d.dstGmtoff;
                long gapEnd = endUtc + d.stdGmtoff;
                if (localEpoch >= gapStart && localEpoch < gapEnd) {
                    return localEpoch - d.dstGmtoff;
                }
            }
        }
        // Fallback (shouldn't happen)
        return localEpoch;
    }

    // --- Date/Time utilities ---

    static long dateTimeToEpoch(int y, int m, int d, int h, int mi, int s) {
        long days = daysFromCivil(y, m, d);
        return days * 86400L + h * 3600L + mi * 60L + s;
    }

    static String epochToDateTimeStr(long epochSec) {
        long days = Math.floorDiv(epochSec, 86400);
        long rem = Math.floorMod(epochSec, 86400);
        int[] ymd = civilFromDays(days);
        int h = (int)(rem / 3600); rem %= 3600;
        int mi = (int)(rem / 60);
        int se = (int)(rem % 60);
        return String.format("%04d-%02d-%02dT%02d:%02d:%02d", ymd[0], ymd[1], ymd[2], h, mi, se);
    }

    static int epochToYear(long epochSec) {
        long days = Math.floorDiv(epochSec, 86400);
        return civilFromDays(days)[0];
    }

    // Howard Hinnant's algorithms
    static long daysFromCivil(long y, long m, long d) {
        y -= m <= 2 ? 1 : 0;
        long era = (y >= 0 ? y : y - 399) / 400;
        long yoe = y - era * 400;
        long mp = m + (m > 2 ? -3 : 9);
        long doy = (153 * mp + 2) / 5 + d - 1;
        long doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
        return era * 146097 + doe - 719468;
    }

    static int[] civilFromDays(long z) {
        z += 719468;
        long era = (z >= 0 ? z : z - 146096) / 146097;
        long doe = z - era * 146097;
        long yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
        long y = yoe + era * 400;
        long doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
        long mp = (5 * doy + 2) / 153;
        long d = doy - (153 * mp + 2) / 5 + 1;
        long m = mp < 10 ? mp + 3 : mp - 9;
        y += (m <= 2) ? 1 : 0;
        return new int[]{(int)y, (int)m, (int)d};
    }

    static int dayOfWeek(int y, int m, int d) {
        long days = daysFromCivil(y, m, d);
        return (int)((days + 4) % 7 + 7) % 7; // 0=Sun
    }

    static int daysInMonth(int y, int m) {
        int[] dm = {0,31,28,31,30,31,30,31,31,30,31,30,31};
        if (m == 2 && isLeap(y)) return 29;
        return dm[m];
    }

    static boolean isLeap(int y) {
        return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
    }

    static int computeMDay(int year, int month, int week, int dow) {
        int dowFirst = dayOfWeek(year, month, 1);
        int first = 1 + ((dow - dowFirst + 7) % 7);
        if (week == 5) {
            int lastDay = daysInMonth(year, month);
            int dowLast = dayOfWeek(year, month, lastDay);
            return lastDay - ((dowLast - dow + 7) % 7);
        } else {
            return first + (week - 1) * 7;
        }
    }

    static String formatOffset(int gmtoff) {
        int sign = gmtoff >= 0 ? 1 : -1;
        int abs = Math.abs(gmtoff);
        int h = abs / 3600; abs %= 3600;
        int m = abs / 60;
        int s = abs % 60;
        String signStr = sign >= 0 ? "+" : "-";
        if (s != 0) {
            return String.format("%s%02d:%02d:%02d", signStr, h, m, s);
        } else {
            return String.format("%s%02d:%02d", signStr, h, m);
        }
    }

    // --- Binary reading ---
    static int readInt32(byte[] b, int off) {
        return ((b[off] & 0xFF) << 24) | ((b[off+1] & 0xFF) << 16) |
               ((b[off+2] & 0xFF) << 8) | (b[off+3] & 0xFF);
    }

    static long readInt64(byte[] b, int off) {
        return ((long)readInt32(b, off) << 32) | (readInt32(b, off + 4) & 0xFFFFFFFFL);
    }
}

import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    static class Type {
        int gmtoff;
        boolean isdst;
        String abbr;
        Type(int gmtoff, boolean isdst, String abbr) {
            this.gmtoff = gmtoff; this.isdst = isdst; this.abbr = abbr;
        }
    }

    static class TzifData {
        long[] transTimes;
        int[] transTypeIdx;
        Type[] types;
        String stdName, dstName;
        int stdGmtoff, dstGmtoff;
        boolean hasDst, hasRule;
        int sm, sw, sd, sh, smi, ss;
        int em, ew, ed, eh, emi, es;
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        List<String> lines = Files.readAllLines(Paths.get(dir, "queries.txt"));
        Map<String, TzifData> cache = new HashMap<>();
        StringBuilder out = new StringBuilder();

        for (String line : lines) {
            if (line.trim().isEmpty()) continue;
            String[] parts = line.split(" ");
            String qType = parts[0];
            String fileName = parts[1];
            TzifData d = cache.get(fileName);
            if (d == null) {
                d = parseTzif(dir + "/" + fileName);
                cache.put(fileName, d);
            }

            if (qType.equals("UTC")) {
                long t = Long.parseLong(parts[2]);
                out.append(line).append(" -> ").append(utcQuery(d, t)).append("\n");
            } else {
                String wall = parts[2];
                out.append(line).append(" -> ").append(localQuery(d, wall)).append("\n");
            }
        }
        System.out.print(out.toString());
    }

    static TzifData parseTzif(String path) throws Exception {
        byte[] b = Files.readAllBytes(Paths.get(path));
        int pos = 0;
        // First header: 44 bytes
        pos += 4; // TZif
        pos += 1; // version
        pos += 15; // unused
        int isutcnt1 = readInt32(b, pos); pos += 4;
        int isstdcnt1 = readInt32(b, pos); pos += 4;
        int leapcnt1 = readInt32(b, pos); pos += 4;
        int timecnt1 = readInt32(b, pos); pos += 4;
        int typecnt1 = readInt32(b, pos); pos += 4;
        int charcnt1 = readInt32(b, pos); pos += 4;
        // Skip first data block
        pos += timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1;
        // Second header: 44 bytes
        pos += 4; pos += 1; pos += 15;
        int isutcnt = readInt32(b, pos); pos += 4;
        int isstdcnt = readInt32(b, pos); pos += 4;
        int leapcnt = readInt32(b, pos); pos += 4;
        int timecnt = readInt32(b, pos); pos += 4;
        int typecnt = readInt32(b, pos); pos += 4;
        int charcnt = readInt32(b, pos); pos += 4;

        TzifData d = new TzifData();
        d.transTimes = new long[timecnt];
        d.transTypeIdx = new int[timecnt];
        d.types = new Type[typecnt];

        for (int i = 0; i < timecnt; i++) {
            d.transTimes[i] = readInt64(b, pos); pos += 8;
        }
        for (int i = 0; i < timecnt; i++) {
            d.transTypeIdx[i] = b[pos] & 0xFF; pos++;
        }
        int[] abbrIdxs = new int[typecnt];
        for (int i = 0; i < typecnt; i++) {
            int gmtoff = readInt32(b, pos); pos += 4;
            boolean isdst = b[pos] != 0; pos++;
            abbrIdxs[i] = b[pos] & 0xFF; pos++;
            d.types[i] = new Type(gmtoff, isdst, null);
        }
        byte[] abbrs = Arrays.copyOfRange(b, pos, pos + charcnt); pos += charcnt;
        for (int i = 0; i < typecnt; i++) {
            d.types[i].abbr = readNullTerminated(abbrs, abbrIdxs[i]);
        }
        // Skip leap seconds, isstd, isut
        pos += leapcnt * 12 + isstdcnt + isutcnt;
        // Footer: \n POSIX \n
        pos++; // skip newline
        int footStart = pos;
        while (pos < b.length && b[pos] != '\n') pos++;
        String posixStr = new String(b, footStart, pos - footStart, "ISO-8859-1");
        parsePosix(d, posixStr);
        return d;
    }

    static String readNullTerminated(byte[] arr, int start) {
        int end = start;
        while (end < arr.length && arr[end] != 0) end++;
        return new String(arr, start, end - start, java.nio.charset.StandardCharsets.ISO_8859_1);
    }

    static void parsePosix(TzifData d, String s) {
        if (s == null || s.isEmpty()) {
            d.hasDst = false; d.hasRule = false;
            d.stdName = ""; d.stdGmtoff = 0;
            d.dstName = ""; d.dstGmtoff = 0;
            return;
        }
        int pos = 0;
        // Parse std name
        int[] r = parseName(s, pos);
        d.stdName = s.substring(pos, r[0]); pos = r[0];
        // Parse std offset
        r = parseOffset(s, pos);
        d.stdGmtoff = -r[0]; pos = r[1];
        d.hasDst = false; d.hasRule = false;
        d.dstName = ""; d.dstGmtoff = d.stdGmtoff + 3600;
        if (pos >= s.length()) return;
        // Parse dst name
        r = parseName(s, pos);
        d.dstName = s.substring(pos, r[0]); pos = r[0];
        d.hasDst = true;
        // Parse dst offset (optional, not if next char is ',')
        if (pos < s.length() && s.charAt(pos) != ',') {
            r = parseOffset(s, pos);
            d.dstGmtoff = -r[0]; pos = r[1];
        } else {
            d.dstGmtoff = d.stdGmtoff + 3600;
        }
        // Parse rules
        if (pos < s.length() && s.charAt(pos) == ',') {
            pos++; // skip comma
            d.hasRule = true;
            r = parseRule(s, pos);
            d.sm = r[0]; d.sw = r[1]; d.sd = r[2]; d.sh = r[3]; d.smi = r[4]; d.ss = r[5];
            pos = r[6];
            if (pos < s.length() && s.charAt(pos) == ',') pos++;
            r = parseRule(s, pos);
            d.em = r[0]; d.ew = r[1]; d.ed = r[2]; d.eh = r[3]; d.emi = r[4]; d.es = r[5];
        }
    }

    static int[] parseName(String s, int pos) {
        if (s.charAt(pos) == '<') {
            int end = s.indexOf('>', pos);
            return new int[]{end + 1};
        } else {
            int end = pos;
            while (end < s.length() && Character.isLetter(s.charAt(end))) end++;
            return new int[]{end};
        }
    }

    static int[] parseOffset(String s, int pos) {
        int sign = 1;
        if (s.charAt(pos) == '+') { pos++; }
        else if (s.charAt(pos) == '-') { sign = -1; pos++; }
        int h = 0, m = 0, sec = 0;
        while (pos < s.length() && Character.isDigit(s.charAt(pos))) { h = h * 10 + (s.charAt(pos++) - '0'); }
        if (pos < s.length() && s.charAt(pos) == ':') {
            pos++;
            while (pos < s.length() && Character.isDigit(s.charAt(pos))) { m = m * 10 + (s.charAt(pos++) - '0'); }
            if (pos < s.length() && s.charAt(pos) == ':') {
                pos++;
                while (pos < s.length() && Character.isDigit(s.charAt(pos))) { sec = sec * 10 + (s.charAt(pos++) - '0'); }
            }
        }
        return new int[]{sign * (h * 3600 + m * 60 + sec), pos};
    }

    static int[] parseRule(String s, int pos) {
        // Mm.w.d[/time]
        pos++; // skip M
        int m = 0; while (Character.isDigit(s.charAt(pos))) m = m * 10 + (s.charAt(pos++) - '0');
        pos++; // skip .
        int w = 0; while (Character.isDigit(s.charAt(pos))) w = w * 10 + (s.charAt(pos++) - '0');
        pos++; // skip .
        int d = 0; while (Character.isDigit(s.charAt(pos))) d = d * 10 + (s.charAt(pos++) - '0');
        int h = 2, mi = 0, sec = 0;
        if (pos < s.length() && s.charAt(pos) == '/') {
            pos++;
            int sign = 1;
            if (s.charAt(pos) == '+') pos++;
            else if (s.charAt(pos) == '-') { sign = -1; pos++; }
            h = 0; while (pos < s.length() && Character.isDigit(s.charAt(pos))) h = h * 10 + (s.charAt(pos++) - '0');
            if (pos < s.length() && s.charAt(pos) == ':') {
                pos++;
                while (pos < s.length() && Character.isDigit(s.charAt(pos))) mi = mi * 10 + (s.charAt(pos++) - '0');
                if (pos < s.length() && s.charAt(pos) == ':') {
                    pos++;
                    while (pos < s.length() && Character.isDigit(s.charAt(pos))) sec = sec * 10 + (s.charAt(pos++) - '0');
                }
            }
            h *= sign;
        }
        return new int[]{m, w, d, h, mi, sec, pos};
    }

    static Type getTypeAt(TzifData d, long t) {
        if (d.transTimes.length == 0) {
            return posixType(d, t);
        }
        if (t < d.transTimes[0]) return d.types[0];
        if (t > d.transTimes[d.transTimes.length - 1]) return posixType(d, t);
        // Binary search: latest transition <= t
        int lo = 0, hi = d.transTimes.length - 1, idx = 0;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            if (d.transTimes[mid] <= t) { idx = mid; lo = mid + 1; }
            else hi = mid - 1;
        }
        return d.types[d.transTypeIdx[idx]];
    }

    static Type posixType(TzifData d, long t) {
        if (!d.hasDst || !d.hasRule) return new Type(d.stdGmtoff, false, d.stdName);
        int year = epochToYear(t);
        // Check year-1, year, year+1 to handle edge cases near year boundaries
        long startUtc = posixTransitionUtc(d, year, true);
        long endUtc = posixTransitionUtc(d, year, false);
        boolean inDst;
        if (startUtc <= endUtc) {
            inDst = t >= startUtc && t < endUtc;
        } else {
            inDst = t >= startUtc || t < endUtc;
        }
        if (inDst) return new Type(d.dstGmtoff, true, d.dstName);
        else return new Type(d.stdGmtoff, false, d.stdName);
    }

    static long posixTransitionUtc(TzifData d, int year, boolean isStart) {
        int m, w, dow, h, mi, sec, gmtoff;
        if (isStart) {
            m = d.sm; w = d.sw; dow = d.sd; h = d.sh; mi = d.smi; sec = d.ss;
            gmtoff = d.stdGmtoff;
        } else {
            m = d.em; w = d.ew; dow = d.ed; h = d.eh; mi = d.emi; sec = d.es;
            gmtoff = d.dstGmtoff;
        }
        int day = computeMDay(year, m, w, dow);
        long localSec = dateTimeToEpoch(year, m, day, h, mi, sec);
        return localSec - gmtoff; // UTC = local - gmtoff
    }

    static String utcQuery(TzifData d, long t) {
        Type type = getTypeAt(d, t);
        long localSec = t + type.gmtoff;
        String dt = epochToDateTimeStr(localSec);
        String off = formatOffset(type.gmtoff);
        return dt + off + " " + type.abbr;
    }

    static String localQuery(TzifData d, String wall) {
        int y = Integer.parseInt(wall.substring(0, 4));
        int mo = Integer.parseInt(wall.substring(5, 7));
        int da = Integer.parseInt(wall.substring(8, 10));
        int h = Integer.parseInt(wall.substring(11, 13));
        int mi = Integer.parseInt(wall.substring(14, 16));
        int se = Integer.parseInt(wall.substring(17, 19));
        long localEpoch = dateTimeToEpoch(y, mo, da, h, mi, se);

        // Collect all candidate (gmtoff, abbr) pairs
        Set<String> seen = new HashSet<>();
        List<long[]> candidates = new ArrayList<>(); // [gmtoff]
        List<String> abbrs = new ArrayList<>();

        // From types in TZif
        for (Type tp : d.types) {
            String key = tp.gmtoff + "|" + tp.abbr;
            if (seen.add(key)) {
                candidates.add(new long[]{tp.gmtoff});
                abbrs.add(tp.abbr);
            }
        }
        // From POSIX std
        if (d.stdName != null && !d.stdName.isEmpty()) {
            String key = d.stdGmtoff + "|" + d.stdName;
            if (seen.add(key)) {
                candidates.add(new long[]{d.stdGmtoff});
                abbrs.add(d.stdName);
            }
        }
        // From POSIX dst
        if (d.hasDst && d.dstName != null && !d.dstName.isEmpty()) {
            String key = d.dstGmtoff + "|" + d.dstName;
            if (seen.add(key)) {
                candidates.add(new long[]{d.dstGmtoff});
                abbrs.add(d.dstName);
            }
        }

        // Enumerate and verify
        List<long[]> results = new ArrayList<>(); // [t, gmtoff, abbrIdx]
        for (int i = 0; i < candidates.size(); i++) {
            int gmtoff = (int)candidates.get(i)[0];
            String abbr = abbrs.get(i);
            long tCand = localEpoch - gmtoff;
            Type actual = getTypeAt(d, tCand);
            if (actual.gmtoff == gmtoff && actual.abbr.equals(abbr)) {
                results.add(new long[]{tCand, gmtoff, i});
            }
        }
        results.sort((a, b) -> Long.compare(a[0], b[0]));

        if (results.size() == 1) {
            long t = results.get(0)[0];
            int gmtoff = (int)results.get(0)[1];
            String abbr = abbrs.get((int)results.get(0)[2]);
            return t + " " + formatOffset(gmtoff) + " " + abbr;
        } else if (results.size() == 2) {
            long t1 = results.get(0)[0]; int g1 = (int)results.get(0)[1]; String a1 = abbrs.get((int)results.get(0)[2]);
            long t2 = results.get(1)[0]; int g2 = (int)results.get(1)[1]; String a2 = abbrs.get((int)results.get(1)[2]);
            return t1 + " " + formatOffset(g1) + " " + a1 + " | " + t2 + " " + formatOffset(g2) + " " + a2;
        } else {
            // Gap: find the transition that skipped this wall-clock time
            long tGap = findGapT(d, localEpoch);
            Type typeAtGap = getTypeAt(d, tGap);
            String dt = epochToDateTimeStr(tGap + typeAtGap.gmtoff);
            String off = formatOffset(typeAtGap.gmtoff);
            return "GAP " + tGap + " " + dt + off + " " + typeAtGap.abbr;
        }
    }

    static long findGapT(TzifData d, long localEpoch) {
        // Check TZif transitions
        for (int i = 0; i < d.transTimes.length; i++) {
            long T = d.transTimes[i];
            Type before;
            if (i == 0) before = d.types[0];
            else before = d.types[d.transTypeIdx[i - 1]];
            Type after = d.types[d.transTypeIdx[i]];
            if (after.gmtoff > before.gmtoff) {
                long gapStart = T + before.gmtoff;
                long gapEnd = T + after.gmtoff;
                if (localEpoch >= gapStart && localEpoch < gapEnd) {
                    return localEpoch - before.gmtoff;
                }
            }
        }
        // Check POSIX transitions for nearby years
        int year = epochToYear(localEpoch);
        for (int yr = year - 1; yr <= year + 1; yr++) {
            if (!d.hasDst || !d.hasRule) continue;
            long startUtc = posixTransitionUtc(d, yr, true);
            long endUtc = posixTransitionUtc(d, yr, false);
            // Spring forward: STD -> DST at startUtc (gap if dstGmtoff > stdGmtoff)
            if (d.dstGmtoff > d.stdGmtoff) {
                long gapStart = startUtc + d.stdGmtoff;
                long gapEnd = startUtc + d.dstGmtoff;
                if (localEpoch >= gapStart && localEpoch < gapEnd) {
                    return localEpoch - d.stdGmtoff;
                }
            }
            // End transition: DST -> STD (gap if stdGmtoff > dstGmtoff, unusual)
            if (d.stdGmtoff > d.dstGmtoff) {
                long gapStart = endUtc + d.dstGmtoff;
                long gapEnd = endUtc + d.stdGmtoff;
                if (localEpoch >= gapStart && localEpoch < gapEnd) {
                    return localEpoch - d.dstGmtoff;
                }
            }
        }
        // Fallback
        return localEpoch;
    }

    // --- Date/Time utilities ---

    static long dateTimeToEpoch(int y, int m, int d, int h, int mi, int s) {
        long days = daysFromCivil(y, m, d);
        return days * 86400L + h * 3600L + mi * 60L + s;
    }

    static String epochToDateTimeStr(long epochSec) {
        long days = Math.floorDiv(epochSec, 86400);
        long rem = Math.floorMod(epochSec, 86400);
        int[] ymd = civilFromDays(days);
        int h = (int)(rem / 3600); rem %= 3600;
        int mi = (int)(rem / 60);
        int se = (int)(rem % 60);
        return String.format("%04d-%02d-%02dT%02d:%02d:%02d", ymd[0], ymd[1], ymd[2], h, mi, se);
    }

    static int epochToYear(long epochSec) {
        long days = Math.floorDiv(epochSec, 86400);
        return civilFromDays(days)[0];
    }

    static long daysFromCivil(long y, long m, long d) {
        y -= m <= 2 ? 1 : 0;
        long era = (y >= 0 ? y : y - 399) / 400;
        long yoe = y - era * 400;
        long mp = m + (m > 2 ? -3 : 9);
        long doy = (153 * mp + 2) / 5 + d - 1;
        long doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
        return era * 146097 + doe - 719468;
    }

    static int[] civilFromDays(long z) {
        z += 719468;
        long era = (z >= 0 ? z : z - 146096) / 146097;
        long doe = z - era * 146097;
        long yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
        long y = yoe + era * 400;
        long doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
        long mp = (5 * doy + 2) / 153;
        long d = doy - (153 * mp + 2) / 5 + 1;
        long m = mp < 10 ? mp + 3 : mp - 9;
        y += (m <= 2) ? 1 : 0;
        return new int[]{(int)y, (int)m, (int)d};
    }

    static int dayOfWeek(int y, int m, int d) {
        long days = daysFromCivil(y, m, d);
        return (int)(((days % 7) + 7 + 4) % 7); // 0=Sun
    }

    static int daysInMonth(int y, int m) {
        int[] dm = {0,31,28,31,30,31,30,31,31,30,31,30,31};
        if (m == 2 && isLeap(y)) return 29;
        return dm[m];
    }

    static boolean isLeap(int y) {
        return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
    }

    static int computeMDay(int year, int month, int week, int dow) {
        int dowFirst = dayOfWeek(year, month, 1);
        int first = 1 + ((dow - dowFirst + 7) % 7);
        if (week == 5) {
            int lastDay = daysInMonth(year, month);
            int dowLast = dayOfWeek(year, month, lastDay);
            return lastDay - ((dowLast - dow + 7) % 7);
        } else {
            return first + (week - 1) * 7;
        }
    }

    static String formatOffset(int gmtoff) {
        int sign = gmtoff >= 0 ? 1 : -1;
        int abs = Math.abs(gmtoff);
        int h = abs / 3600; abs %= 3600;
        int m = abs / 60;
        int s = abs % 60;
        String signStr = sign >= 0 ? "+" : "-";
        if (s != 0) {
            return String.format("%s%02d:%02d:%02d", signStr, h, m, s);
        } else {
            return String.format("%s%02d:%02d", signStr, h, m);
        }
    }

    // --- Binary reading ---
    static int readInt32(byte[] b, int off) {
        return ((b[off] & 0xFF) << 24) | ((b[off+1] & 0xFF) << 16) |
               ((b[off+2] & 0xFF) << 8) | (b[off+3] & 0xFF);
    }

    static long readInt64(byte[] b, int off) {
        return ((long)readInt32(b, off) << 32) | (readInt32(b, off + 4) & 0xFFFFFFFFL);
    }
}

import Foundation

let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }
let dir = args[1]

let fm = FileManager.default
let allEntries = try! fm.contentsOfDirectory(atPath: dir)
let wavFiles = allEntries.filter { $0.hasSuffix(".wav") }
let sortedFiles = wavFiles.sorted { a, b in
    Array(a.utf8).lexicographicallyPrecedes(Array(b.utf8))
}

let lowFreqs: [Double] = [697, 770, 852, 941]
let highFreqs: [Double] = [1209, 1336, 1477, 1633]

let keypad: [[String]] = [
    ["1", "2", "3", "A"],
    ["4", "5", "6", "B"],
    ["7", "8", "9", "C"],
    ["*", "0", "#", "D"]
]

func readU16(_ d: [UInt8], _ off: Int) -> UInt16 {
    return UInt16(d[off]) | (UInt16(d[off + 1]) << 8)
}

func readU32(_ d: [UInt8], _ off: Int) -> UInt32 {
    return UInt32(d[off]) | (UInt32(d[off + 1]) << 8) | (UInt32(d[off + 2]) << 16) | (UInt32(d[off + 3]) << 24)
}

var firstOutput = true

for filename in sortedFiles {
    if !firstOutput { print("") }
    firstOutput = false

    let path = dir + "/" + filename
    guard let fileData = fm.contents(atPath: path) else { continue }
    let bytes = [UInt8](fileData)

    guard bytes.count >= 12 else { continue }
    guard bytes[0] == 0x52, bytes[1] == 0x49, bytes[2] == 0x46, bytes[3] == 0x46 else { continue }
    guard bytes[8] == 0x57, bytes[9] == 0x41, bytes[10] == 0x56, bytes[11] == 0x45 else { continue }

    var offset = 12
    var fmtBody: [UInt8]? = nil
    var dataBody: [UInt8]? = nil

    while offset + 8 <= bytes.count {
        let id = String(bytes: bytes[offset..<offset+4], encoding: .ascii) ?? ""
        let chunkSize = Int(readU32(bytes, offset + 4))
        let bodyStart = offset + 8
        let bodyEnd = bodyStart + chunkSize

        if id == "fmt " {
            fmtBody = Array(bytes[bodyStart..<min(bodyEnd, bytes.count)])
        } else if id == "data" {
            dataBody = Array(bytes[bodyStart..<min(bodyEnd, bytes.count)])
        }

        var next = bodyEnd
        if chunkSize & 1 == 1 { next += 1 }
        offset = next
    }

    guard let fmt = fmtBody, let dataChunk = dataBody else { continue }
    guard fmt.count >= 16 else { continue }

    var formatTag = Int(readU16(fmt, 0))
    let channels = Int(readU16(fmt, 2))
    let sampleRate = Int(readU32(fmt, 4))
    let bitsPerSample = Int(readU16(fmt, 14))

    if formatTag == 0xFFFE {
        guard fmt.count > 24 else { continue }
        formatTag = Int(readU16(fmt, 24))
    }

    if formatTag != 1 || bitsPerSample != 16 {
        print("\(filename): unsupported")
        continue
    }
    if (channels != 1 && channels != 2) || (sampleRate != 8000 && sampleRate != 16000) {
        print("\(filename): unsupported")
        continue
    }

    let framesCount = dataChunk.count / (2 * channels)
    var samples = [Double](repeating: 0, count: framesCount)
    for i in 0..<framesCount {
        let byteOff = i * 2 * channels
        samples[i] = Double(Int16(bitPattern: readU16(dataChunk, byteOff)))
    }

    let N = sampleRate / 50
    let numBlocks = framesCount / N

    // Step 3: detect digit per block
    var labels: [String?] = []
    labels.reserveCapacity(numBlocks)

    for b in 0..<numBlocks {
        let base = b * N
        var E: Double = 0
        for n in 0..<N { let x = samples[base + n]; E += x * x }

        if E < 1_000_000.0 * Double(N) {
            labels.append(nil)
            continue
        }

        var maxLowR: Double = -1
        var maxLowIdx: Int = 0
        for fi in 0..<4 {
            let c = 2.0 * cos(2.0 * Double.pi * lowFreqs[fi] / Double(sampleRate))
            var s1: Double = 0, s2: Double = 0
            for n in 0..<N {
                let s = samples[base + n] + c * s1 - s2
                s2 = s1; s1 = s
            }
            let P = s1 * s1 + s2 * s2 - c * s1 * s2
            let r = 2.0 * P / (Double(N) * E)
            if r > maxLowR { maxLowR = r; maxLowIdx = fi }
        }

        var maxHighR: Double = -1
        var maxHighIdx: Int = 0
        for fi in 0..<4 {
            let c = 2.0 * cos(2.0 * Double.pi * highFreqs[fi] / Double(sampleRate))
            var s1: Double = 0, s2: Double = 0
            for n in 0..<N {
                let s = samples[base + n] + c * s1 - s2
                s2 = s1; s1 = s
            }
            let P = s1 * s1 + s2 * s2 - c * s1 * s2
            let r = 2.0 * P / (Double(N) * E)
            if r > maxHighR { maxHighR = r; maxHighIdx = fi }
        }

        if maxLowR >= 0.1 && maxHighR >= 0.1 && (maxLowR + maxHighR) >= 0.6 {
            labels.append(keypad[maxLowIdx][maxHighIdx])
        } else {
            labels.append(nil)
        }
    }

    // Step 4: bridging (use original step-3 labels for decisions)
    var bridged = labels
    for i in 0..<numBlocks {
        if labels[i] == nil && i > 0 && i < numBlocks - 1 {
            if let d = labels[i - 1], d == labels[i + 1] {
                bridged[i] = d
            }
        }
    }

    // Step 5: events (runs >= 2)
    var events: [(digit: String, start: Int, end: Int)] = []
    var i = 0
    while i < numBlocks {
        if let digit = bridged[i] {
            var j = i + 1
            while j < numBlocks && bridged[j] == digit { j += 1 }
            if j - i >= 2 {
                events.append((digit: digit, start: 20 * i, end: 20 * j))
            }
            i = j
        } else {
            i += 1
        }
    }

    // Output
    print("\(filename): \(sampleRate) Hz, \(channels) ch, \(numBlocks) blocks")
    for ev in events {
        print("\(ev.digit) \(ev.start) \(ev.end)")
    }
    let allDigits = events.map { $0.digit }.joined()
    print("digits: \(allDigits)")
}

exit(0)

import * as fs from 'fs';
import * as path from 'path';

const LOW_FREQS = [697, 770, 852, 941];
const HIGH_FREQS = [1209, 1336, 1477, 1633];
const KEYPAD = [
  ['1', '2', '3', 'A'],
  ['4', '5', '6', 'B'],
  ['7', '8', '9', 'C'],
  ['*', '0', '#', 'D'],
];

function goertzel(x: number[], N: number, f: number, rate: number, E: number): number {
  const c = 2 * Math.cos(2 * Math.PI * f / rate);
  let s1 = 0, s2 = 0;
  for (let n = 0; n < N; n++) {
    const s = x[n] + c * s1 - s2;
    s2 = s1;
    s1 = s;
  }
  const P = s1 * s1 + s2 * s2 - c * s1 * s2;
  return 2 * P / (N * E);
}

function processFile(name: string, buf: Buffer): string {
  if (buf.length < 12) return `${name}: unsupported`;
  if (buf.toString('ascii', 0, 4) !== 'RIFF') return `${name}: unsupported`;
  if (buf.toString('ascii', 8, 12) !== 'WAVE') return `${name}: unsupported`;

  let fmtBody: Buffer | null = null;
  let dataBody: Buffer | null = null;
  let offset = 12;

  while (offset + 8 <= buf.length) {
    const chunkId = buf.toString('ascii', offset, offset + 4);
    const chunkSize = buf.readUInt32LE(offset + 4);
    const bodyStart = offset + 8;
    const bodyEnd = bodyStart + chunkSize;

    if (bodyEnd > buf.length) break;

    if (chunkId === 'fmt ') {
      fmtBody = buf.subarray(bodyStart, bodyEnd);
    } else if (chunkId === 'data') {
      dataBody = buf.subarray(bodyStart, bodyEnd);
    }

    offset = bodyEnd + (chunkSize % 2 === 1 ? 1 : 0);
  }

  if (!fmtBody || !dataBody) return `${name}: unsupported`;
  if (fmtBody.length < 16) return `${name}: unsupported`;

  let formatTag = fmtBody.readUInt16LE(0);
  const channels = fmtBody.readUInt16LE(2);
  const sampleRate = fmtBody.readUInt32LE(4);
  const bitsPerSample = fmtBody.readUInt16LE(14);

  if (formatTag === 0xFFFE) {
    if (fmtBody.length < 26) return `${name}: unsupported`;
    formatTag = fmtBody.readUInt16LE(24);
  }

  if (formatTag !== 1 || bitsPerSample !== 16) return `${name}: unsupported`;
  if (channels !== 1 && channels !== 2) return `${name}: unsupported`;
  if (sampleRate !== 8000 && sampleRate !== 16000) return `${name}: unsupported`;

  const bytesPerFrame = 2 * channels;
  const numFrames = Math.floor(dataBody.length / bytesPerFrame);
  const samples: number[] = new Array(numFrames);
  for (let i = 0; i < numFrames; i++) {
    samples[i] = dataBody.readInt16LE(i * bytesPerFrame);
  }

  const N = sampleRate / 50;
  const numBlocks = Math.floor(samples.length / N);

  const labels: (string | null)[] = new Array(numBlocks);

  for (let b = 0; b < numBlocks; b++) {
    const blockStart = b * N;
    const x: number[] = new Array(N);
    for (let n = 0; n < N; n++) {
      x[n] = samples[blockStart + n];
    }

    let E = 0;
    for (let n = 0; n < N; n++) {
      E += x[n] * x[n];
    }

    if (E < 1000000 * N) {
      labels[b] = null;
      continue;
    }

    const rLow: number[] = new Array(4);
    const rHigh: number[] = new Array(4);

    for (let i = 0; i < 4; i++) {
      rLow[i] = goertzel(x, N, LOW_FREQS[i], sampleRate, E);
    }
    for (let i = 0; i < 4; i++) {
      rHigh[i] = goertzel(x, N, HIGH_FREQS[i], sampleRate, E);
    }

    let maxLowIdx = 0, maxHighIdx = 0;
    for (let i = 1; i < 4; i++) {
      if (rLow[i] > rLow[maxLowIdx]) maxLowIdx = i;
      if (rHigh[i] > rHigh[maxHighIdx]) maxHighIdx = i;
    }

    const rFl = rLow[maxLowIdx];
    const rFh = rHigh[maxHighIdx];

    if (rFl >= 0.1 && rFh >= 0.1 && rFl + rFh >= 0.6) {
      labels[b] = KEYPAD[maxLowIdx][maxHighIdx];
    } else {
      labels[b] = null;
    }
  }

  // Bridging
  const bridged: (string | null)[] = labels.slice();
  for (let i = 1; i < numBlocks - 1; i++) {
    if (labels[i] === null && labels[i - 1] !== null && labels[i + 1] !== null && labels[i - 1] === labels[i + 1]) {
      bridged[i] = labels[i - 1];
    }
  }

  // Events
  const events: { digit: string; start: number; end: number }[] = [];
  let i = 0;
  while (i < numBlocks) {
    if (bridged[i] === null) {
      i++;
      continue;
    }
    const digit = bridged[i]!;
    const start = i;
    while (i < numBlocks && bridged[i] === digit) {
      i++;
    }
    const end = i - 1;
    if (end - start + 1 >= 2) {
      events.push({ digit, start: 20 * start, end: 20 * (end + 1) });
    }
  }

  const lines: string[] = [];
  lines.push(`${name}: ${sampleRate} Hz, ${channels} ch, ${numBlocks} blocks`);
  for (const ev of events) {
    lines.push(`${ev.digit} ${ev.start} ${ev.end}`);
  }
  lines.push(`digits: ${events.map(e => e.digit).join('')}`);

  return lines.join('\n');
}

function main() {
  const dir = process.argv[2];
  const files = fs.readdirSync(dir).filter(f => f.endsWith('.wav')).sort((a, b) => {
    return Buffer.compare(Buffer.from(a, 'utf-8'), Buffer.from(b, 'utf-8'));
  });

  const outputs: string[] = [];

  for (const file of files) {
    const filePath = path.join(dir, file);
    const buf = fs.readFileSync(filePath);
    outputs.push(processFile(file, buf));
  }

  process.stdout.write(outputs.join('\n\n') + '\n');
}

main();

use std::env;
use std::fs;
use std::path::Path;

fn read_u16_le(data: &[u8], offset: usize) -> u16 {
    u16::from_le_bytes([data[offset], data[offset + 1]])
}

fn read_u32_le(data: &[u8], offset: usize) -> u32 {
    u32::from_le_bytes([data[offset], data[offset + 1], data[offset + 2], data[offset + 3]])
}

fn goertzel(block: &[i16], freq: f64, rate: f64, n: usize, e: f64) -> f64 {
    let c = 2.0 * (2.0 * std::f64::consts::PI * freq / rate).cos();
    let mut s1 = 0.0f64;
    let mut s2 = 0.0f64;
    for &x in block {
        let s = (x as f64) + c * s1 - s2;
        s2 = s1;
        s1 = s;
    }
    let p = s1 * s1 + s2 * s2 - c * s1 * s2;
    2.0 * p / (n as f64 * e)
}

fn process_file(name: &str, data: &[u8]) {
    if data.len() < 12 || &data[0..4] != b"RIFF" || &data[8..12] != b"WAVE" {
        println!("{}: unsupported", name);
        return;
    }

    let mut pos = 12usize;
    let mut fmt_body: Option<Vec<u8>> = None;
    let mut data_body: Option<Vec<u8>> = None;

    while pos + 8 <= data.len() {
        let chunk_id = &data[pos..pos + 4];
        let chunk_size = read_u32_le(data, pos + 4) as usize;
        let body_start = pos + 8;
        let actual_size = std::cmp::min(chunk_size, data.len().saturating_sub(body_start));

        if chunk_id == b"fmt " {
            fmt_body = Some(data[body_start..body_start + actual_size].to_vec());
        } else if chunk_id == b"data" {
            data_body = Some(data[body_start..body_start + actual_size].to_vec());
        }

        pos = body_start + chunk_size;
        if chunk_size % 2 == 1 {
            pos += 1;
        }
    }

    let fmt = match fmt_body {
        Some(f) => f,
        None => { println!("{}: unsupported", name); return; }
    };
    let samples_data = match data_body {
        Some(d) => d,
        None => { println!("{}: unsupported", name); return; }
    };

    if fmt.len() < 16 {
        println!("{}: unsupported", name);
        return;
    }

    let mut format_tag = read_u16_le(&fmt, 0) as u32;
    let channels = read_u16_le(&fmt, 2) as usize;
    let rate = read_u32_le(&fmt, 4) as usize;
    let bits_per_sample = read_u16_le(&fmt, 14);

    if format_tag == 0xFFFE {
        if fmt.len() < 26 {
            println!("{}: unsupported", name);
            return;
        }
        format_tag = read_u16_le(&fmt, 24) as u32;
    }

    if format_tag != 1 || bits_per_sample != 16 {
        println!("{}: unsupported", name);
        return;
    }
    if channels != 1 && channels != 2 {
        println!("{}: unsupported", name);
        return;
    }
    if rate != 8000 && rate != 16000 {
        println!("{}: unsupported", name);
        return;
    }

    let frame_bytes = 2 * channels;
    let num_frames = samples_data.len() / frame_bytes;

    let mut left_samples: Vec<i16> = Vec::with_capacity(num_frames);
    for i in 0..num_frames {
        let off = i * frame_bytes;
        let sample = i16::from_le_bytes([samples_data[off], samples_data[off + 1]]);
        left_samples.push(sample);
    }

    let n = rate / 50;
    let num_blocks = if n > 0 { left_samples.len() / n } else { 0 };

    let low_freqs: [f64; 4] = [697.0, 770.0, 852.0, 941.0];
    let high_freqs: [f64; 4] = [1209.0, 1336.0, 1477.0, 1633.0];

    let keypad: [[char; 4]; 4] = [
        ['1', '2', '3', 'A'],
        ['4', '5', '6', 'B'],
        ['7', '8', '9', 'C'],
        ['*', '0', '#', 'D'],
    ];

    let mut labels: Vec<Option<char>> = vec![None; num_blocks];

    for block_idx in 0..num_blocks {
        let start = block_idx * n;
        let block = &left_samples[start..start + n];

        let e: f64 = block.iter().map(|&x| (x as f64) * (x as f64)).sum();

        if e < 1000000.0 * n as f64 {
            continue;
        }

        let mut r_low: [f64; 4] = [0.0; 4];
        let mut r_high: [f64; 4] = [0.0; 4];

        for fi in 0..4 {
            r_low[fi] = goertzel(block, low_freqs[fi], rate as f64, n, e);
            r_high[fi] = goertzel(block, high_freqs[fi], rate as f64, n, e);
        }

        let mut max_low_idx = 0usize;
        let mut max_high_idx = 0usize;
        for i in 1..4 {
            if r_low[i] > r_low[max_low_idx] { max_low_idx = i; }
            if r_high[i] > r_high[max_high_idx] { max_high_idx = i; }
        }

        let r_fl = r_low[max_low_idx];
        let r_fh = r_high[max_high_idx];

        if r_fl >= 0.1 && r_fh >= 0.1 && r_fl + r_fh >= 0.6 {
            labels[block_idx] = Some(keypad[max_low_idx][max_high_idx]);
        }
    }

    // Bridging: use original step-3 labels for neighbor checks
    let original_labels = labels.clone();
    if num_blocks >= 3 {
        for i in 1..num_blocks - 1 {
            if labels[i].is_none() {
                if let Some(prev) = original_labels[i - 1] {
                    if let Some(next) = original_labels[i + 1] {
                        if prev == next {
                            labels[i] = Some(prev);
                        }
                    }
                }
            }
        }
    }

    // Events: maximal runs of same digit >= 2 blocks
    let mut events: Vec<(char, usize, usize)> = Vec::new();
    let mut i = 0usize;
    while i < num_blocks {
        if let Some(d) = labels[i] {
            let start_block = i;
            while i < num_blocks && labels[i] == Some(d) {
                i += 1;
            }
            let end_block = i - 1;
            let run_len = end_block - start_block + 1;
            if run_len >= 2 {
                let start_ms = 20 * start_block;
                let end_ms = 20 * (end_block + 1);
                events.push((d, start_ms, end_ms));
            }
        } else {
            i += 1;
        }
    }

    // Output
    println!("{}: {} Hz, {} ch, {} blocks", name, rate, channels, num_blocks);
    for (d, start_ms, end_ms) in &events {
        println!("{} {} {}", d, start_ms, end_ms);
    }
    let digits: String = events.iter().map(|(d, _, _)| *d).collect();
    println!("digits: {}", digits);
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let mut entries: Vec<String> = Vec::new();
    for entry in fs::read_dir(dir).unwrap() {
