        let name = entry.file_name().to_str().unwrap().to_string();
        if name.ends_with(".wav") {
            entries.push(name);
        }
    }
    entries.sort_by(|a, b| a.as_bytes().cmp(b.as_bytes()));

    let mut first = true;
    for name in &entries {
        if !first {
            println!();
        }
        first = false;

        let path = Path::new(dir).join(name);
        let file_data = fs::read(&path).unwrap();

        process_file(name, &file_data);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <dirent.h>
#include <stdint.h>

static uint16_t read_u16(const unsigned char *p) {
    return (uint16_t)(p[0] | (p[1] << 8));
}

static uint32_t read_u32(const unsigned char *p) {
    return (uint32_t)(p[0] | (p[1] << 8) | (p[2] << 16) | (p[3] << 24));
}

static int cmp_str(const void *a, const void *b) {
    return strcmp(*(const char *const *)a, *(const char *const *)b);
}

static const double low_freqs[4] = {697.0, 770.0, 852.0, 941.0};
static const double high_freqs[4] = {1209.0, 1336.0, 1477.0, 1633.0};
static const char digit_table[4][4] = {
    {'1', '2', '3', 'A'},
    {'4', '5', '6', 'B'},
    {'7', '8', '9', 'C'},
    {'*', '0', '#', 'D'}
};

int main(int argc, char *argv[]) {
    if (argc != 2) return 1;

    DIR *dir = opendir(argv[1]);
    if (!dir) return 1;

    char **files = NULL;
    int nfiles = 0;
    struct dirent *ent;
    while ((ent = readdir(dir)) != NULL) {
        const char *name = ent->d_name;
        size_t len = strlen(name);
        if (len >= 4 && strcmp(name + len - 4, ".wav") == 0) {
            files = realloc(files, (nfiles + 1) * sizeof(char *));
            files[nfiles++] = strdup(name);
        }
    }
    closedir(dir);

    qsort(files, nfiles, sizeof(char *), cmp_str);

    for (int fi = 0; fi < nfiles; fi++) {
        if (fi > 0) printf("\n");

        char path[8192];
        snprintf(path, sizeof(path), "%s/%s", argv[1], files[fi]);

        FILE *fp = fopen(path, "rb");
        if (!fp) {
            printf("%s: unsupported\n", files[fi]);
            continue;
        }

        fseek(fp, 0, SEEK_END);
        long fsize = ftell(fp);
        fseek(fp, 0, SEEK_SET);

        if (fsize < 12) {
            fclose(fp);
            printf("%s: unsupported\n", files[fi]);
            continue;
        }

        unsigned char *buf = malloc(fsize);
        if (!buf || (long)fread(buf, 1, fsize, fp) != fsize) {
            fclose(fp);
            free(buf);
            printf("%s: unsupported\n", files[fi]);
            continue;
        }
        fclose(fp);

        if (memcmp(buf, "RIFF", 4) != 0 || memcmp(buf + 8, "WAVE", 4) != 0) {
            printf("%s: unsupported\n", files[fi]);
            free(buf);
            continue;
        }

        unsigned char *fmt_body = NULL;
        uint32_t fmt_size = 0;
        unsigned char *data_body = NULL;
        uint32_t data_size = 0;

        long pos = 12;
        while (pos + 8 <= fsize) {
            uint32_t csize = read_u32(buf + pos + 4);
            long body_start = pos + 8;
            if (body_start + (long)csize > fsize) break;

            if (memcmp(buf + pos, "fmt ", 4) == 0) {
                fmt_body = buf + body_start;
                fmt_size = csize;
            } else if (memcmp(buf + pos, "data", 4) == 0) {
                data_body = buf + body_start;
                data_size = csize;
            }

            pos = body_start + csize;
            if (csize & 1) pos++;
        }

        if (!fmt_body || !data_body) {
            printf("%s: unsupported\n", files[fi]);
            free(buf);
            continue;
        }

        if (fmt_size < 16) {
            printf("%s: unsupported\n", files[fi]);
            free(buf);
            continue;
        }

        uint16_t fmt_tag = read_u16(fmt_body);
        uint16_t channels = read_u16(fmt_body + 2);
        uint32_t sample_rate = read_u32(fmt_body + 4);
        uint16_t bits = read_u16(fmt_body + 14);

        uint16_t effective = fmt_tag;
        if (fmt_tag == 0xFFFE) {
            if (fmt_size < 26) {
                printf("%s: unsupported\n", files[fi]);
                free(buf);
                continue;
            }
            effective = read_u16(fmt_body + 24);
        }

        if (effective != 1 || bits != 16 ||
            (channels != 1 && channels != 2) ||
            (sample_rate != 8000 && sample_rate != 16000)) {
            printf("%s: unsupported\n", files[fi]);
            free(buf);
            continue;
        }

        uint32_t frames = data_size / (2 * channels);
        int N = (int)(sample_rate / 50);
        int nblocks = (N > 0) ? (int)(frames / N) : 0;

        double *x = malloc(frames * sizeof(double));
        for (uint32_t i = 0; i < frames; i++) {
            int16_t val = (int16_t)read_u16(data_body + i * 2 * channels);
            x[i] = (double)val;
        }

        int *labels = malloc((nblocks > 0 ? nblocks : 1) * sizeof(int));

        for (int b = 0; b < nblocks; b++) {
            double *blk = x + (size_t)b * N;

            double E = 0.0;
            for (int n = 0; n < N; n++) {
                E += blk[n] * blk[n];
            }

            if (E < 1000000.0 * N) {
                labels[b] = -1;
                continue;
            }

            double r_low[4], r_high[4];

            for (int i = 0; i < 4; i++) {
                double c = 2.0 * cos(2.0 * M_PI * low_freqs[i] / sample_rate);
                double s1 = 0.0, s2 = 0.0;
                for (int n = 0; n < N; n++) {
                    double s = blk[n] + c * s1 - s2;
                    s2 = s1;
                    s1 = s;
                }
                double P = s1 * s1 + s2 * s2 - c * s1 * s2;
                r_low[i] = 2.0 * P / ((double)N * E);
            }

            for (int i = 0; i < 4; i++) {
                double c = 2.0 * cos(2.0 * M_PI * high_freqs[i] / sample_rate);
                double s1 = 0.0, s2 = 0.0;
                for (int n = 0; n < N; n++) {
                    double s = blk[n] + c * s1 - s2;
                    s2 = s1;
                    s1 = s;
                }
                double P = s1 * s1 + s2 * s2 - c * s1 * s2;
                r_high[i] = 2.0 * P / ((double)N * E);
            }

            int best_low = 0, best_high = 0;
            for (int i = 1; i < 4; i++) {
                if (r_low[i] > r_low[best_low]) best_low = i;
                if (r_high[i] > r_high[best_high]) best_high = i;
            }

            if (r_low[best_low] >= 0.1 && r_high[best_high] >= 0.1 &&
                r_low[best_low] + r_high[best_high] >= 0.6) {
                labels[b] = best_low * 4 + best_high;
            } else {
                labels[b] = -1;
            }
        }

        /* Bridging: use original labels for decisions */
        int *final_labels = malloc((nblocks > 0 ? nblocks : 1) * sizeof(int));
        memcpy(final_labels, labels, nblocks * sizeof(int));

        for (int b = 1; b < nblocks - 1; b++) {
            if (labels[b] == -1 && labels[b - 1] != -1 && labels[b - 1] == labels[b + 1]) {
                final_labels[b] = labels[b - 1];
            }
        }

        /* Events: maximal runs of same digit, length >= 2 */
        char *ev_digits = malloc((nblocks > 0 ? nblocks : 1) * sizeof(char));
        int *ev_start = malloc((nblocks > 0 ? nblocks : 1) * sizeof(int));
        int *ev_end = malloc((nblocks > 0 ? nblocks : 1) * sizeof(int));
        int nev = 0;

        int i = 0;
        while (i < nblocks) {
            if (final_labels[i] == -1) { i++; continue; }
            int j = i + 1;
            while (j < nblocks && final_labels[j] == final_labels[i]) j++;
            if (j - i >= 2) {
                int d = final_labels[i];
                ev_digits[nev] = digit_table[d / 4][d % 4];
                ev_start[nev] = 20 * i;
                ev_end[nev] = 20 * j;
                nev++;
            }
            i = j;
        }

        printf("%s: %u Hz, %u ch, %d blocks\n", files[fi], sample_rate, channels, nblocks);
        for (int e = 0; e < nev; e++) {
            printf("%c %d %d\n", ev_digits[e], ev_start[e], ev_end[e]);
        }
        printf("digits: ");
        for (int e = 0; e < nev; e++) {
            printf("%c", ev_digits[e]);
        }
        printf("\n");

        free(x);
        free(labels);
        free(final_labels);
        free(ev_digits);
        free(ev_start);
        free(ev_end);
        free(buf);
    }

    for (int i = 0; i < nfiles; i++) free(files[i]);
    free(files);

    return 0;
}

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.util.Base64;

public class Main {
    public static void main(String[] args) throws Exception {
        SecureRandom random = new SecureRandom();
        for (int i = 0; i < args.length; i++) {
            System.out.println("session " + (i + 1));
            handleSession(args[i], random);
        }
    }

    static void handleSession(String url, SecureRandom random) throws Exception {
        String rest = url.substring(5); // remove "ws://"
        int slashIdx = rest.indexOf('/');
        String hostPort, path;
        if (slashIdx >= 0) {
            hostPort = rest.substring(0, slashIdx);
            path = rest.substring(slashIdx);
        } else {
            hostPort = rest;
            path = "/";
        }
        int colonIdx = hostPort.lastIndexOf(':');
        String host;
        int port;
        if (colonIdx >= 0) {
            host = hostPort.substring(0, colonIdx);
            port = Integer.parseInt(hostPort.substring(colonIdx + 1));
        } else {
            host = hostPort;
            port = 80;
        }

        Socket socket = new Socket();
        socket.connect(new InetSocketAddress(host, port), 10000);
        socket.setSoTimeout(30000);
        InputStream in = new BufferedInputStream(socket.getInputStream(), 65536);
        OutputStream out = new BufferedOutputStream(socket.getOutputStream());

        byte[] keyBytes = new byte[16];
        random.nextBytes(keyBytes);
        String key = Base64.getEncoder().encodeToString(keyBytes);

        String handshake = "GET " + path + " HTTP/1.1\r\n"
                + "Host: " + host + ":" + port + "\r\n"
                + "Upgrade: websocket\r\n"
                + "Connection: Upgrade\r\n"
                + "Sec-WebSocket-Version: 13\r\n"
                + "Sec-WebSocket-Key: " + key + "\r\n"
                + "\r\n";
        out.write(handshake.getBytes(StandardCharsets.US_ASCII));
        out.flush();

        // Read HTTP response
        String statusLine = readHttpLine(in);
        if (statusLine == null) {
            socket.close();
            return;
        }
        int firstSpace = statusLine.indexOf(' ');
        int secondSpace = statusLine.indexOf(' ', firstSpace + 1);
        int statusCode;
        String reason;
        if (secondSpace == -1) {
            statusCode = Integer.parseInt(statusLine.substring(firstSpace + 1).trim());
            reason = "";
        } else {
            statusCode = Integer.parseInt(statusLine.substring(firstSpace + 1, secondSpace).trim());
            reason = statusLine.substring(secondSpace + 1);
        }

        if (statusCode != 101) {
            // consume remaining headers
            String hl;
            while ((hl = readHttpLine(in)) != null && !hl.isEmpty()) {}
            System.out.println("handshake failed: " + statusCode + " " + reason);
            socket.close();
            return;
        }

        String acceptValue = null;
        String hl;
        while ((hl = readHttpLine(in)) != null && !hl.isEmpty()) {
            int cp = hl.indexOf(':');
            if (cp >= 0) {
                String name = hl.substring(0, cp).trim();
                String value = hl.substring(cp + 1).trim();
                if (name.equalsIgnoreCase("Sec-WebSocket-Accept")) {
                    acceptValue = value;
                }
            }
        }

        String expectedAccept = computeAccept(key);
        if (acceptValue == null || !acceptValue.equals(expectedAccept)) {
            System.out.println("handshake failed: bad Sec-WebSocket-Accept");
            socket.close();
            return;
        }

        // WebSocket frame loop
        boolean inMessage = false;
        int messageType = -1;
        ByteArrayOutputStream msgBuf = null;
        boolean pendingSha1 = false;
        boolean closeSent = false;
        boolean byeReceived = false;

        while (true) {
            Frame f = readFrame(in);
            if (f == null) break;

            if (f.opcode == 9) { // ping
                sendFrame(out, 10, f.payload, random);
                out.flush();
                continue;
            }
            if (f.opcode == 10) { // pong
                continue;
            }
            if (f.opcode == 8) { // close
                int code = 1005;
                String closeReason = "";
                if (f.payload.length >= 2) {
                    code = ((f.payload[0] & 0xFF) << 8) | (f.payload[1] & 0xFF);
                }
                if (f.payload.length > 2) {
                    closeReason = new String(f.payload, 2, f.payload.length - 2, StandardCharsets.UTF_8);
                }
                if (closeReason.isEmpty()) {
                    System.out.println("closed " + code);
                } else {
                    System.out.println("closed " + code + " " + closeReason);
                }
                if (!closeSent) {
                    byte[] cp = new byte[]{(byte) (code >> 8), (byte) (code & 0xFF)};
                    sendFrame(out, 8, cp, random);
                    out.flush();
                    closeSent = true;
                }
                break;
            }

            if (byeReceived) continue;

            if (f.opcode == 1 || f.opcode == 2) {
                if (f.fin) {
                    handleData(f.opcode, f.payload, out, random, pendingSha1, new boolean[]{false});
                    if (f.opcode == 1) {
                        String text = new String(f.payload, StandardCharsets.UTF_8);
                        if (text.equals("SHA1")) {
                            pendingSha1 = true;
                        } else if (text.equals("BYE")) {
                            byeReceived = true;
                            byte[] cp = new byte[]{0x03, (byte) 0xE8};
                            sendFrame(out, 8, cp, random);
                            out.flush();
                            closeSent = true;
                        } else if (text.startsWith("ADD ")) {
                            String params = text.substring(4).trim();
                            String[] parts = params.split("\\s+");
                            long a = Long.parseLong(parts[0]);
                            long b = Long.parseLong(parts[1]);
                            long sum = a + b;
                            String reply = Long.toString(sum);
                            sendFrame(out, 1, reply.getBytes(StandardCharsets.UTF_8), random);
                            out.flush();
                            System.out.println(text + " -> " + reply);
                        } else if (text.startsWith("REV ")) {
                            String toReverse = text.substring(4);
                            String reversed = reverseByCodePoint(toReverse);
                            sendFrame(out, 1, reversed.getBytes(StandardCharsets.UTF_8), random);
                            out.flush();
                            System.out.println(text + " -> " + reversed);
                        }
                    } else if (f.opcode == 2 && pendingSha1) {
                        pendingSha1 = false;
                        MessageDigest md = MessageDigest.getInstance("SHA-1");
                        byte[] hash = md.digest(f.payload);
                        String hex = bytesToHex(hash);
                        sendFrame(out, 1, hex.getBytes(StandardCharsets.UTF_8), random);
                        out.flush();
                        System.out.println("SHA1 " + f.payload.length + " -> " + hex);
                    }
                } else {
                    inMessage = true;
                    messageType = f.opcode;
                    msgBuf = new ByteArrayOutputStream();
                    msgBuf.write(f.payload);
                }
            } else if (f.opcode == 0) { // continuation
                if (inMessage) {
                    msgBuf.write(f.payload);
                    if (f.fin) {
                        byte[] fullPayload = msgBuf.toByteArray();
                        inMessage = false;
                        if (messageType == 1) {
                            String text = new String(fullPayload, StandardCharsets.UTF_8);
                            if (text.equals("SHA1")) {
                                pendingSha1 = true;
                            } else if (text.equals("BYE")) {
                                byeReceived = true;
                                byte[] cp = new byte[]{0x03, (byte) 0xE8};
                                sendFrame(out, 8, cp, random);
                                out.flush();
                                closeSent = true;
                            } else if (text.startsWith("ADD ")) {
                                String params = text.substring(4).trim();
                                String[] parts = params.split("\\s+");
                                long a = Long.parseLong(parts[0]);
                                long b = Long.parseLong(parts[1]);
                                long sum = a + b;
                                String reply = Long.toString(sum);
                                sendFrame(out, 1, reply.getBytes(StandardCharsets.UTF_8), random);
                                out.flush();
                                System.out.println(text + " -> " + reply);
                            } else if (text.startsWith("REV ")) {
                                String toReverse = text.substring(4);
                                String reversed = reverseByCodePoint(toReverse);
                                sendFrame(out, 1, reversed.getBytes(StandardCharsets.UTF_8), random);
                                out.flush();
                                System.out.println(text + " -> " + reversed);
                            }
                        } else if (messageType == 2 && pendingSha1) {
                            pendingSha1 = false;
                            MessageDigest md = MessageDigest.getInstance("SHA-1");
                            byte[] hash = md.digest(fullPayload);
                            String hex = bytesToHex(hash);
                            sendFrame(out, 1, hex.getBytes(StandardCharsets.UTF_8), random);
                            out.flush();
                            System.out.println("SHA1 " + fullPayload.length + " -> " + hex);
                        }
                    }
                }
            }
        }
        socket.close();
    }

    static void handleData(int opcode, byte[] payload, OutputStream out, SecureRandom random, boolean pendingSha1, boolean[] dummy) {
        // placeholder - logic is inline in the loop
    }

    static String reverseByCodePoint(String s) {
        int[] cps = s.codePoints().toArray();
        StringBuilder sb = new StringBuilder();
        for (int i = cps.length - 1; i >= 0; i--) {
            sb.appendCodePoint(cps[i]);
        }
        return sb.toString();
    }

    static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder(bytes.length * 2);
        for (byte b : bytes) {
            sb.append(String.format("%02x", b & 0xFF));
        }
        return sb.toString();
    }

    static String computeAccept(String key) throws Exception {
        String magic = key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";
        MessageDigest md = MessageDigest.getInstance("SHA-1");
        byte[] hash = md.digest(magic.getBytes(StandardCharsets.US_ASCII));
        return Base64.getEncoder().encodeToString(hash);
    }

    static String readHttpLine(InputStream in) throws IOException {
        StringBuilder sb = new StringBuilder();
        int b;
        while ((b = in.read()) != -1) {
            if (b == '\n') {
                if (sb.length() > 0 && sb.charAt(sb.length() - 1) == '\r') {
                    sb.setLength(sb.length() - 1);
                }
                break;
            }
            sb.append((char) b);
        }
        if (b == -1 && sb.length() == 0) return null;
        return sb.toString();
    }

    static Frame readFrame(InputStream in) throws IOException {
        int b0 = in.read();
        if (b0 == -1) return null;
        boolean fin = (b0 & 0x80) != 0;
        int opcode = b0 & 0x0F;

        int b1 = in.read();
        if (b1 == -1) return null;
        boolean masked = (b1 & 0x80) != 0;
        long payloadLen = b1 & 0x7F;

        if (payloadLen == 126) {
            int hi = in.read();
            int lo = in.read();
            if (hi == -1 || lo == -1) return null;
            payloadLen = ((hi & 0xFF) << 8) | (lo & 0xFF);
        } else if (payloadLen == 127) {
            payloadLen = 0;
            for (int i = 0; i < 8; i++) {
                int bb = in.read();
                if (bb == -1) return null;
                payloadLen = (payloadLen << 8) | (bb & 0xFFL);
            }
        }

        byte[] maskKey = null;
        if (masked) {
            maskKey = new byte[4];
            readFully(in, maskKey);
        }

        byte[] payload = new byte[(int) payloadLen];
        if (payloadLen > 0) {
            readFully(in, payload);
        }

        if (masked && maskKey != null) {
            for (int i = 0; i < payload.length; i++) {
                payload[i] ^= maskKey[i % 4];
            }
        }

        return new Frame(fin, opcode, payload);
    }

    static void readFully(InputStream in, byte[] buf) throws IOException {
        int off = 0;
        while (off < buf.length) {
            int n = in.read(buf, off, buf.length - off);
            if (n == -1) throw new EOFException();
            off += n;
        }
    }

    static void sendFrame(OutputStream out, int opcode, byte[] payload, SecureRandom random) throws IOException {
        ByteArrayOutputStream frame = new ByteArrayOutputStream();
        frame.write(0x80 | opcode); // FIN + opcode, RSV clear

        int len = payload.length;
        if (len <= 125) {
            frame.write(0x80 | len);
        } else if (len <= 65535) {
            frame.write(0x80 | 126);
            frame.write((len >> 8) & 0xFF);
            frame.write(len & 0xFF);
        } else {
            frame.write(0x80 | 127);
            long flen = len;
            for (int i = 7; i >= 0; i--) {
                frame.write((int) ((flen >> (i * 8)) & 0xFF));
            }
        }

        byte[] maskKey = new byte[4];
        do {
            random.nextBytes(maskKey);
        } while (maskKey[0] == 0 && maskKey[1] == 0 && maskKey[2] == 0 && maskKey[3] == 0);
        frame.write(maskKey);

        for (int i = 0; i < payload.length; i++) {
            frame.write(payload[i] ^ maskKey[i % 4]);
        }

        out.write(frame.toByteArray());
    }

    static class Frame {
        final boolean fin;
        final int opcode;
        final byte[] payload;

        Frame(boolean fin, int opcode, byte[] payload) {
            this.fin = fin;
            this.opcode = opcode;
            this.payload = payload;
        }
    }
}

#!/usr/bin/env python3
import struct
import sys
import os
import bisect
from datetime import date, timedelta, datetime


def main():
    data_dir = sys.argv[1]

    with open(os.path.join(data_dir, 'queries.txt'), 'r') as f:
        lines = f.readlines()

    tzif_cache = {}

    def get_tzif(filename):
        if filename not in tzif_cache:
            tzif_cache[filename] = parse_tzif(os.path.join(data_dir, filename))
        return tzif_cache[filename]

    results = []
    for line in lines:
        line = line.rstrip('\n')
        if not line.strip():
            continue
        parts = line.split(' ')
        query_type = parts[0]
        filename = parts[1]

        if query_type == 'UTC':
            t = int(parts[2])
            tzif = get_tzif(filename)
            local_str, abbr = utc_to_local(t, tzif)
            results.append(f"{line} -> {local_str} {abbr}")
        elif query_type == 'LOCAL':
            wall_str = parts[2]
            tzif = get_tzif(filename)
            result = local_query(wall_str, tzif)
            results.append(f"{line} -> {result}")

    for r in results:
        print(r)


def parse_tzif(filepath):
    with open(filepath, 'rb') as f:
        data = f.read()

    pos = 0
    assert data[pos:pos + 4] == b'TZif'
    counts1 = struct.unpack('>6I', data[pos + 20:pos + 44])
    isutcnt1, isstdcnt1, leapcnt1, timecnt1, typecnt1, charcnt1 = counts1
    pos = 44

    block1_size = (timecnt1 * 4 + timecnt1 + typecnt1 * 6 +
                   charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1)
    pos += block1_size

    assert data[pos:pos + 4] == b'TZif'
    counts2 = struct.unpack('>6I', data[pos + 20:pos + 44])
    isutcnt, isstdcnt, leapcnt, timecnt, typecnt, charcnt = counts2
    pos += 44

    trans_times = []
    for i in range(timecnt):
        t = struct.unpack('>q', data[pos:pos + 8])[0]
        trans_times.append(t)
        pos += 8

    trans_types = list(data[pos:pos + timecnt])
    pos += timecnt

    type_records = []
    for i in range(typecnt):
        utoff = struct.unpack('>i', data[pos:pos + 4])[0]
        isdst = data[pos + 4]
        abbridx = data[pos + 5]
        type_records.append((utoff, isdst, abbridx))
        pos += 6

    abbrs_data = data[pos:pos + charcnt]
    pos += charcnt

    pos += leapcnt * 12
    pos += isstdcnt
    pos += isutcnt

    pos += 1  # leading newline
    end_nl = data.index(b'\n', pos)
    posix_str = data[pos:end_nl].decode('ascii')

    abbrs = []
    for i in range(typecnt):
        _, _, abbridx = type_records[i]
        end = abbrs_data.index(b'\x00', abbridx)
        abbrs.append(abbrs_data[abbridx:end].decode('ascii'))

    posix = parse_posix_tz(posix_str) if posix_str else None

    return {
        'trans_times': trans_times,
        'trans_types': trans_types,
        'type_records': type_records,
        'abbrs': abbrs,
        'posix': posix,
    }


def parse_posix_tz(s):
    pos = [0]

    def parse_name():
        if pos[0] < len(s) and s[pos[0]] == '<':
            end = s.index('>', pos[0])
            name = s[pos[0] + 1:end]
            pos[0] = end + 1
        else:
            start = pos[0]
            while pos[0] < len(s) and s[pos[0]].isalpha():
                pos[0] += 1
            name = s[start:pos[0]]
        return name

    def parse_offset_or_time():
        sign = 1
        if pos[0] < len(s) and s[pos[0]] == '-':
            sign = -1
            pos[0] += 1
        elif pos[0] < len(s) and s[pos[0]] == '+':
            pos[0] += 1

        h_start = pos[0]
        while pos[0] < len(s) and s[pos[0]].isdigit():
            pos[0] += 1
        hours = int(s[h_start:pos[0]])

        minutes = 0
        seconds = 0
        if pos[0] < len(s) and s[pos[0]] == ':':
            pos[0] += 1
            m_start = pos[0]
            while pos[0] < len(s) and s[pos[0]].isdigit():
                pos[0] += 1
            minutes = int(s[m_start:pos[0]])
            if pos[0] < len(s) and s[pos[0]] == ':':
                pos[0] += 1
                sec_start = pos[0]
                while pos[0] < len(s) and s[pos[0]].isdigit():
                    pos[0] += 1
                seconds = int(s[sec_start:pos[0]])

        return sign * (hours * 3600 + minutes * 60 + seconds)

    def parse_rule():
        assert s[pos[0]] == 'M'
        pos[0] += 1
        m_start = pos[0]
        while pos[0] < len(s) and s[pos[0]].isdigit():
            pos[0] += 1
        month = int(s[m_start:pos[0]])
        assert s[pos[0]] == '.'
        pos[0] += 1
        w_start = pos[0]
        while pos[0] < len(s) and s[pos[0]].isdigit():
            pos[0] += 1
        week = int(s[w_start:pos[0]])
        assert s[pos[0]] == '.'
        pos[0] += 1
        d_start = pos[0]
        while pos[0] < len(s) and s[pos[0]].isdigit():
            pos[0] += 1
        day = int(s[d_start:pos[0]])

        time_sec = 2 * 3600
        if pos[0] < len(s) and s[pos[0]] == '/':
            pos[0] += 1
            time_sec = parse_offset_or_time()

        return (month, week, day, time_sec)

    std_name = parse_name()
    std_posix_offset = parse_offset_or_time()
    std_utc_offset = -std_posix_offset

    dst_name = None
    dst_utc_offset = None

    if pos[0] < len(s) and s[pos[0]] != ',':
        dst_name = parse_name()
        if pos[0] < len(s) and (s[pos[0]] in '+-' or s[pos[0]].isdigit()):
            dst_posix_offset = parse_offset_or_time()
            dst_utc_offset = -dst_posix_offset
        else:
            dst_utc_offset = std_utc_offset + 3600

    start_rule = None
    end_rule = None

    if pos[0] < len(s) and s[pos[0]] == ',':
        pos[0] += 1
        start_rule = parse_rule()
        if pos[0] < len(s) and s[pos[0]] == ',':
            pos[0] += 1
            end_rule = parse_rule()

    return {
        'std_name': std_name,
        'std_utc_offset': std_utc_offset,
        'dst_name': dst_name,
        'dst_utc_offset': dst_utc_offset,
        'start_rule': start_rule,
        'end_rule': end_rule,
    }


def find_mdw_date(year, month, week, day):
    # day: 0=Sunday, 6=Saturday
    # Python weekday: Mon=0, ..., Sun=6
    target_python_wd = (day - 1) % 7

    first_of_month = date(year, month, 1)
    days_ahead = (target_python_wd - first_of_month.weekday()) % 7
    first_occurrence = first_of_month + timedelta(days=days_ahead)

    if week <= 4:
        result = first_occurrence + timedelta(days=(week - 1) * 7)
    else:
        if month == 12:
            last_of_month = date(year, 12, 31)
        else:
            last_of_month = date(year, month + 1, 1) - timedelta(days=1)
        days_back = (last_of_month.weekday() - target_python_wd) % 7
        result = last_of_month - timedelta(days=days_back)

    return result


def posix_transition_time(year, rule, utc_offset):
    d = find_mdw_date(year, rule[0], rule[1], rule[2])
    time_sec = rule[3]
    local_epoch = (d - date(1970, 1, 1)).days * 86400 + time_sec
    utc_time = local_epoch - utc_offset
    return utc_time


def get_type_at(t, tzif):
    trans_times = tzif['trans_times']
    trans_types = tzif['trans_types']
    type_records = tzif['type_records']
    abbrs = tzif['abbrs']
    posix = tzif['posix']

    if not trans_times:
        utoff, isdst, abbridx = type_records[0]
        return (utoff, isdst, abbrs[0])

    if t < trans_times[0]:
        utoff, isdst, abbridx = type_records[0]
        return (utoff, isdst, abbrs[0])

    if t > trans_times[-1]:
        if posix is None:
            ti = trans_types[-1]
            utoff, isdst, abbridx = type_records[ti]
            return (utoff, isdst, abbrs[ti])

        year = (datetime(1970, 1, 1) + timedelta(seconds=t)).year

        start_utc = posix_transition_time(year, posix['start_rule'], posix['std_utc_offset'])
        end_utc = posix_transition_time(year, posix['end_rule'], posix['dst_utc_offset'])

        if start_utc <= end_utc:
            in_dst = (start_utc <= t < end_utc)
        else:
            in_dst = (t >= start_utc or t < end_utc)

        if in_dst:
            return (posix['dst_utc_offset'], 1, posix['dst_name'])
        else:
            return (posix['std_utc_offset'], 0, posix['std_name'])

    idx = bisect.bisect_right(trans_times, t) - 1
    ti = trans_types[idx]
    utoff, isdst, abbridx = type_records[ti]
    return (utoff, isdst, abbrs[ti])


def utc_to_local(t, tzif):
    utoff, isdst, abbr = get_type_at(t, tzif)
    local_secs = t + utoff
    dt = datetime(1970, 1, 1) + timedelta(seconds=local_secs)
    local_str = f"{dt.year:04d}-{dt.month:02d}-{dt.day:02d}T{dt.hour:02d}:{dt.minute:02d}:{dt.second:02d}"
    offset_str = format_offset(utoff)
    return (local_str + offset_str, abbr)


def format_offset(secs):
    if secs < 0:
        sign = '-'
        secs = -secs
    else:
        sign = '+'
    h = secs // 3600
    m = (secs % 3600) // 60
    s = secs % 60
    if s:
        return f"{sign}{h:02d}:{m:02d}:{s:02d}"
    else:
        return f"{sign}{h:02d}:{m:02d}"


def wall_to_epoch(wall_str):
    y, mo, d, h, mi, s = map(int, wall_str.replace('T', '-').split('-'))
    dt = datetime(y, mo, d, h, mi, s)
    return int((dt - datetime(1970, 1, 1)).total_seconds())


def get_all_transitions(center, tzif):
    transitions = []
    trans_times = tzif['trans_times']
    trans_types = tzif['trans_types']
    type_records = tzif['type_records']

    for i in range(len(trans_times)):
        T = trans_times[i]
        ti = trans_types[i]
        off_after = type_records[ti][0]
        if i == 0:
            off_before = type_records[0][0]
        else:
            off_before = type_records[trans_types[i - 1]][0]
        transitions.append((T, off_before, off_after))

    posix = tzif['posix']
    if posix and posix['start_rule'] and posix['end_rule']:
        center_year = (datetime(1970, 1, 1) + timedelta(seconds=center)).year
        for year in range(center_year - 1, center_year + 2):
            start_utc = posix_transition_time(year, posix['start_rule'], posix['std_utc_offset'])
            end_utc = posix_transition_time(year, posix['end_rule'], posix['dst_utc_offset'])
            transitions.append((start_utc, posix['std_utc_offset'], posix['dst_utc_offset']))
            transitions.append((end_utc, posix['dst_utc_offset'], posix['std_utc_offset']))

    return transitions


def local_query(wall_str, tzif):
    w_epoch = wall_to_epoch(wall_str)

    offsets = set()
    for utoff, isdst, abbridx in tzif['type_records']:
        offsets.add(utoff)
    posix = tzif['posix']
    if posix:
        offsets.add(posix['std_utc_offset'])
        if posix['dst_utc_offset'] is not None:
            offsets.add(posix['dst_utc_offset'])

    valid_ts = []
    for off in offsets:
        t = w_epoch - off
        actual_off, _, _ = get_type_at(t, tzif)
        if actual_off == off:
            valid_ts.append(t)

    valid_ts.sort()

    if len(valid_ts) == 1:
        t = valid_ts[0]
        off, _, abbr = get_type_at(t, tzif)
        off_str = format_offset(off)
        return f"{t} {off_str} {abbr}"
    elif len(valid_ts) >= 2:
        parts = []
        for t in valid_ts[:2]:
            off, _, abbr = get_type_at(t, tzif)
            off_str = format_offset(off)
            parts.append(f"{t} {off_str} {abbr}")
        return " | ".join(parts)
    else:
        transitions = get_all_transitions(w_epoch, tzif)
        for T, off_before, off_after in transitions:
            if off_after > off_before:
                if T + off_before <= w_epoch < T + off_after:
                    t = w_epoch - off_before
                    local_str, abbr = utc_to_local(t, tzif)
                    return f"GAP {t} {local_str} {abbr}"

        # Fallback: try wider year range
        center_year = (datetime(1970, 1, 1) + timedelta(seconds=w_epoch)).year
        posix = tzif['posix']
        if posix and posix['start_rule'] and posix['end_rule']:
            for year in range(center_year - 2, center_year + 3):
                start_utc = posix_transition_time(year, posix['start_rule'], posix['std_utc_offset'])
                end_utc = posix_transition_time(year, posix['end_rule'], posix['dst_utc_offset'])
                # Start: STD -> DST
                if posix['dst_utc_offset'] > posix['std_utc_offset']:
                    if start_utc + posix['std_utc_offset'] <= w_epoch < start_utc + posix['dst_utc_offset']:
                        t = w_epoch - posix['std_utc_offset']
                        local_str, abbr = utc_to_local(t, tzif)
                        return f"GAP {t} {local_str} {abbr}"
                # End: DST -> STD (this is fall-back, not gap)

        # Should not reach here for valid input
        return "GAP 0 1970-01-01T00:00:00+00:00 UTC"


if __name__ == '__main__':
    main()

import Foundation
import CommonCrypto

// MARK: - SHA-1

func sha1Hash(_ data: Data) -> Data {
    var digest = [UInt8](repeating: 0, count: Int(CC_SHA1_DIGEST_LENGTH))
    data.withUnsafeBytes { ptr in
        _ = CC_SHA1(ptr.baseAddress, CC_LONG(data.count), &digest)
    }
    return Data(digest)
}

func sha1Hex(_ data: Data) -> String {
    let digest = sha1Hash(data)
    return digest.map { String(format: "%02x", $0) }.joined()
}

// MARK: - Random

func randomBytes(_ count: Int) -> Data {
    var bytes = [UInt8](repeating: 0, count: count)
    for i in 0..<count {
        bytes[i] = UInt8.random(in: 0...255)
    }
    return Data(bytes)
}

// MARK: - URL Parsing

struct WSURL {
    let host: String
    let port: UInt16
    let requestTarget: String
}

func parseWSURL(_ url: String) -> WSURL? {
    guard url.hasPrefix("ws://") else { return nil }
    let rest = String(url.dropFirst(5))
    guard let slashIdx = rest.firstIndex(of: "/") else { return nil }
    let hostPort = String(rest[..<slashIdx])
    let requestTarget = String(rest[slashIdx...])
    let parts = hostPort.split(separator: ":", maxSplits: 1, omittingEmptySubsequences: false)
    guard parts.count == 2 else { return nil }
    let host = String(parts[0])
    guard let port = UInt16(parts[1]) else { return nil }
    return WSURL(host: host, port: port, requestTarget: requestTarget)
}

// MARK: - Buffered TCP Connection

class Connection {
    let fd: Int32
    var buf: [UInt8] = []
    var pos: Int = 0

    init(fd: Int32) { self.fd = fd }

    func fill(min: Int) -> Bool {
        while buf.count - pos < min {
            if pos > 0 {
                buf.removeFirst(pos)
                pos = 0
            }
            var tmp = [UInt8](repeating: 0, count: 65536)
            let n = recv(fd, &tmp, tmp.count, 0)
            if n <= 0 { return false }
            buf.append(contentsOf: tmp[0..<n])
        }
        return true
    }

    func readExact(_ n: Int) -> Data? {
        if n == 0 { return Data() }
        guard fill(min: n) else { return nil }
        let d = Data(buf[pos..<pos+n])
        pos += n
        return d
    }

    func readHeaders() -> String? {
        let pat: [UInt8] = [13, 10, 13, 10]
        while true {
            if let idx = findPat(buf, from: pos, pat: pat) {
                let hdr = String(bytes: buf[pos..<idx], encoding: .ascii) ?? ""
                pos = idx + 4
                return hdr
            }
            var tmp = [UInt8](repeating: 0, count: 65536)
            let n = recv(fd, &tmp, tmp.count, 0)
            if n <= 0 { return nil }
            buf.append(contentsOf: tmp[0..<n])
        }
    }

    func writeData(_ data: Data) {
        var off = 0
        data.withUnsafeBytes { ptr in
            while off < data.count {
                let n = send(fd, ptr.baseAddress!.advanced(by: off), data.count - off, 0)
                if n <= 0 { return }
                off += n
            }
        }
    }

    func closeSocket() {
        Darwin.close(fd)
    }
}

func findPat(_ data: [UInt8], from start: Int, pat: [UInt8]) -> Int? {
    let end = data.count - pat.count
    var i = start
    while i <= end {
        var ok = true
        for j in 0..<pat.count {
            if data[i+j] != pat[j] { ok = false; break }
        }
        if ok { return i }
        i += 1
    }
    return nil
}

// MARK: - WebSocket Frames

struct WSFrame {
    let fin: Bool
    let opcode: UInt8
    let payload: Data
}

func readFrame(_ conn: Connection) -> WSFrame? {
    guard let hdr = conn.readExact(2) else { return nil }
    let b0 = hdr[hdr.startIndex]
    let b1 = hdr[hdr.startIndex + 1]
    let fin = (b0 & 0x80) != 0
    let opcode = b0 & 0x0F
    let masked = (b1 & 0x80) != 0
    var len = Int(b1 & 0x7F)

    if len == 126 {
        guard let ext = conn.readExact(2) else { return nil }
        len = (Int(ext[ext.startIndex]) << 8) | Int(ext[ext.startIndex + 1])
    } else if len == 127 {
        guard let ext = conn.readExact(8) else { return nil }
        len = 0
        for i in 0..<8 {
            len = (len << 8) | Int(ext[ext.startIndex + i])
        }
    }

    var maskKey: [UInt8] = []
    if masked {
        guard let mk = conn.readExact(4) else { return nil }
        maskKey = [UInt8](mk)
    }

    var payload = Data()
    if len > 0 {
        guard let p = conn.readExact(len) else { return nil }
        payload = p
        if masked {
            for i in 0..<payload.count {
                payload[payload.startIndex + i] ^= maskKey[i % 4]
            }
        }
    }

    return WSFrame(fin: fin, opcode: opcode, payload: payload)
}

func sendFrame(_ conn: Connection, opcode: UInt8, payload: Data) {
    var frame = Data()
    frame.append(0x80 | opcode)

    let len = payload.count
    if len <= 125 {
        frame.append(0x80 | UInt8(len))
    } else if len <= 65535 {
        frame.append(0x80 | 126)
        frame.append(UInt8(len >> 8))
        frame.append(UInt8(len & 0xFF))
    } else {
        frame.append(0x80 | 127)
        for i in (0..<8).reversed() {
            frame.append(UInt8((len >> (8 * i)) & 0xFF))
        }
    }

    var maskKey: [UInt8]
    repeat {
        maskKey = [UInt8](randomBytes(4))
    } while maskKey == [0, 0, 0, 0]

    frame.append(contentsOf: maskKey)

    for i in 0..<payload.count {
        frame.append(payload[payload.startIndex + i] ^ maskKey[i % 4])
    }

    conn.writeData(frame)
}

// MARK: - Close Handling

func handleServerClose(_ conn: Connection, frame: WSFrame, sentClose: inout Bool) {
    var code = 1005
    var reason = ""
    if frame.payload.count >= 2 {
        let p = frame.payload
        code = (Int(p[p.startIndex]) << 8) | Int(p[p.startIndex + 1])
        if frame.payload.count > 2 {
            reason = String(data: frame.payload[(frame.payload.startIndex + 2)...], encoding: .utf8) ?? ""
        }
    }

    if reason.isEmpty {
        print("closed \(code)")
    } else {
        print("closed \(code) \(reason)")
    }

    if !sentClose {
        let closePayload = Data([UInt8(code >> 8), UInt8(code & 0xFF)])
        sendFrame(conn, opcode: 8, payload: closePayload)
        sentClose = true
    }
}

// MARK: - Read next data message (handling pings/pongs between fragments)

func readDataMessage(_ conn: Connection, sentClose: inout Bool) -> (opcode: UInt8, payload: Data)? {
    while true {
        guard let frame = readFrame(conn) else { return nil }
        switch frame.opcode {
        case 9: // ping
            sendFrame(conn, opcode: 10, payload: frame.payload)
            continue
        case 10: // pong
            continue
        case 8: // close
            handleServerClose(conn, frame: frame, sentClose: &sentClose)
            return nil
        case 1, 2:
            var payload = frame.payload
            let msgOpcode = frame.opcode
            if !frame.fin {
                while true {
                    guard let cont = readFrame(conn) else { return nil }
                    switch cont.opcode {
                    case 9:
                        sendFrame(conn, opcode: 10, payload: cont.payload)
                        continue
                    case 10:
                        continue
                    case 8:
                        handleServerClose(conn, frame: cont, sentClose: &sentClose)
                        return nil
                    case 0:
                        payload.append(cont.payload)
                        if cont.fin { break }
                    default:
                        break
                    }
                    if cont.fin { break }
                }
            }
            return (msgOpcode, payload)
        default:
            continue
        }
    }
}

// MARK: - Session Handler

func handleSession(_ url: WSURL, sessionNum: Int) {
    print("session \(sessionNum)")

    let fd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP)
    if fd < 0 { return }

    var noSigPipe: Int32 = 1
    setsockopt(fd, SOL_SOCKET, SO_NOSIGPIPE, &noSigPipe, socklen_t(MemoryLayout<Int32>.size))

    var addr = sockaddr_in()
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = url.port.bigEndian
    inet_pton(AF_INET, url.host, &addr.sin_addr)

    let connResult = withUnsafePointer(to: &addr) { ptr in
        ptr.withMemoryRebound(to: sockaddr.self, capacity: 1) {
            Darwin.connect(fd, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
    if connResult != 0 {
        Darwin.close(fd)
        return
    }

    let conn = Connection(fd: fd)

    // Handshake
    let keyData = randomBytes(16)
    let key = keyData.base64EncodedString()

    let request = "GET \(url.requestTarget) HTTP/1.1\r\n" +
        "Host: \(url.host):\(url.port)\r\n" +
        "Upgrade: websocket\r\n" +
        "Connection: Upgrade\r\n" +
        "Sec-WebSocket-Version: 13\r\n" +
        "Sec-WebSocket-Key: \(key)\r\n" +
        "\r\n"

    conn.writeData(Data(request.utf8))

    guard let headerStr = conn.readHeaders() else {
        conn.closeSocket()
        return
    }

    let lines = headerStr.components(separatedBy: "\r\n")
    guard let statusLine = lines.first else {
        conn.closeSocket()
        return
    }

    let statusParts = statusLine.components(separatedBy: " ")
    guard statusParts.count >= 2, let statusCode = Int(statusParts[1]) else {
        conn.closeSocket()
        return
    }

    if statusCode != 101 {
        let reason = statusParts.count > 2 ? statusParts[2...].joined(separator: " ") : ""
        print("handshake failed: \(statusCode) \(reason)")
        conn.closeSocket()
        return
    }

    // Check Sec-WebSocket-Accept
    var acceptValue: String? = nil
    for line in lines.dropFirst() {
        if let colonIdx = line.firstIndex(of: ":") {
            let name = String(line[line.startIndex..<colonIdx]).lowercased()
            let value = String(line[line.index(after: colonIdx)...]).trimmingCharacters(in: .whitespaces)
            if name == "sec-websocket-accept" {
                acceptValue = value
            }
        }
    }

    let expectedAccept = sha1Hash(Data((key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11").utf8))
        .base64EncodedString()

    if acceptValue != expectedAccept {
        print("handshake failed: bad Sec-WebSocket-Accept")
        conn.closeSocket()
        return
    }

    // Process frames
    var sentClose = false

    while true {
        guard let msg = readDataMessage(conn, sentClose: &sentClose) else {
            break
        }

        if msg.opcode != 1 { continue } // only text messages are commands

        guard let text = String(data: msg.payload, encoding: .utf8) else { continue }

        if text == "BYE" {
            sendFrame(conn, opcode: 8, payload: Data([0x03, 0xE8]))
            sentClose = true
            // Read until server close
            while true {
                guard let f = readFrame(conn) else { break }
                switch f.opcode {
                case 9:
                    sendFrame(conn, opcode: 10, payload: f.payload)
                case 10:
                    break
                case 8:
                    handleServerClose(conn, frame: f, sentClose: &sentClose)
                    conn.closeSocket()
                    return
                default:
                    break
                }
            }
            conn.closeSocket()
            return
        } else if text.hasPrefix("ADD ") {
            let parts = text.split(separator: " ")
            if parts.count >= 3, let a = Int64(parts[1]), let b = Int64(parts[2]) {
                let sum = a + b
                let reply = String(sum)
                sendFrame(conn, opcode: 1, payload: Data(reply.utf8))
                print("\(text) -> \(reply)")
            }
        } else if text.hasPrefix("REV ") {
            let textToReverse = String(text.dropFirst(4))
            var reversed = ""
            for s in textToReverse.unicodeScalars.reversed() {
                reversed.unicodeScalars.append(s)
            }
            sendFrame(conn, opcode: 1, payload: Data(reversed.utf8))
            print("REV \(textToReverse) -> \(reversed)")
        } else if text == "SHA1" {
            guard let binMsg = readDataMessage(conn, sentClose: &sentClose) else {
                conn.closeSocket()
                return
            }
            let hex = sha1Hex(binMsg.payload)
            sendFrame(conn, opcode: 1, payload: Data(hex.utf8))
            print("SHA1 \(binMsg.payload.count) -> \(hex)")
        }
    }

    conn.closeSocket()
}

// MARK: - Main

let args = CommandLine.arguments
if args.count < 2 {
    exit(0)
}

for i in 1..<args.count {
    guard let url = parseWSURL(args[i]) else { continue }
    handleSession(url, sessionNum: i)
}

exit(0)

import Foundation

// MARK: - Big-endian readers
func readBE32(_ b: [UInt8], _ off: Int) -> Int32 {
    return Int32(bitPattern: UInt32(b[off]) << 24 | UInt32(b[off+1]) << 16 | UInt32(b[off+2]) << 8 | UInt32(b[off+3]))
}
func readBE64(_ b: [UInt8], _ off: Int) -> Int64 {
    return Int64(bitPattern: UInt64(b[off]) << 56 | UInt64(b[off+1]) << 48 | UInt64(b[off+2]) << 40 | UInt64(b[off+3]) << 32 |
                 UInt64(b[off+4]) << 24 | UInt64(b[off+5]) << 16 | UInt64(b[off+6]) << 8 | UInt64(b[off+7]))
}
func readU32(_ b: [UInt8], _ off: Int) -> UInt32 {
    return UInt32(b[off]) << 24 | UInt32(b[off+1]) << 16 | UInt32(b[off+2]) << 8 | UInt32(b[off+3])
}

// MARK: - Date utilities
func floorDiv(_ a: Int64, _ b: Int64) -> Int64 {
    var q = a / b
    if (a % b != 0) && ((a < 0) != (b < 0)) { q -= 1 }
    return q
}

func daysFromCivil(y: Int, m: Int, d: Int) -> Int {
    var yy = y
    if m <= 2 { yy -= 1 }
    let era = (yy >= 0 ? yy : yy - 399) / 400
    let yoe = yy - era * 400
    let mp = (m + 9) % 12
    let doy = (153 * mp + 2) / 5 + d - 1
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy
    return era * 146097 + doe - 719468
}

func civilFromDays(_ z: Int) -> (Int, Int, Int) {
    var z = z + 719468
    let era = (z >= 0 ? z : z - 146096) / 146097
    let doe = z - era * 146097
    let yoe = (doe - doe/1460 + doe/36524 - doe/146096) / 365
    let y = yoe + era * 400
    let doy = doe - (365*yoe + yoe/4 - yoe/100)
    let mp = (5*doy + 2)/153
    let d = doy - (153*mp+2)/5 + 1
    let m = mp < 10 ? mp + 3 : mp - 9
    return (y + (m <= 2 ? 1 : 0), m, d)
}

func daysInMonth(year: Int, month: Int) -> Int {
    switch month {
    case 1,3,5,7,8,10,12: return 31
    case 4,6,9,11: return 30
    case 2:
        if (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0) { return 29 }
        return 28
    default: return 30
    }
}

func dowFromDays(_ days: Int) -> Int {
    // 0=Sun, 1=Mon, ..., 6=Sat. 1970-01-01 is Thursday=4, daysFromCivil gives 0.
    return ((days + 4) % 7 + 7) % 7
}

func mdToDayOfMonth(year: Int, m: Int, w: Int, d: Int) -> Int {
    let firstDay = daysFromCivil(y: year, m: m, d: 1)
    let firstDow = dowFromDays(firstDay)
    var diff = d - firstDow
    if diff < 0 { diff += 7 }
    let firstOccurrence = 1 + diff
    if w <= 4 {
        return firstOccurrence + (w - 1) * 7
    } else {
        let dim = daysInMonth(year: year, month: m)
        return firstOccurrence + ((dim - firstOccurrence) / 7) * 7
    }
}

// MARK: - TZif structures
struct TTInfo {
    var gmtoff: Int32
    var isdst: UInt8
    var abbrind: UInt8
}

struct TZifFile {
    var transitions: [Int64]
    var transTypes: [UInt8]
    var ttis: [TTInfo]
    var abbrs: [UInt8]
    var posixTZ: String
}

struct PosixRule {
    var stdName: String = ""
    var stdOff: Int = 0  // seconds to ADD to local to get UTC
    var dstName: String = ""
    var dstOff: Int = 0
    var hasDst: Bool = false
    var startM: Int = 1; var startW: Int = 1; var startD: Int = 0; var startSec: Int = 7200
    var endM: Int = 1; var endW: Int = 1; var endD: Int = 0; var endSec: Int = 7200
    var hasRules: Bool = false
}

// MARK: - Parse POSIX TZ string
func parsePosixTZ(_ s: String) -> PosixRule {
    var rule = PosixRule()
    let chars = Array(s)
    var i = 0
    let n = chars.count

    func readName() -> String {
        if i < n && chars[i] == "<" {
            i += 1
            var name = ""
            while i < n && chars[i] != ">" { name.append(chars[i]); i += 1 }
            if i < n { i += 1 }
            return name
        } else {
            var name = ""
            while i < n && chars[i].isLetter { name.append(chars[i]); i += 1 }
            return name
        }
    }

    func readOffsetVal() -> Int {
        var sign = 1
        if i < n && (chars[i] == "+" || chars[i] == "-") {
            if chars[i] == "-" { sign = -1 }
            i += 1
        }
        var hh = 0, mm = 0, ss = 0
        while i < n && chars[i].isNumber { hh = hh*10 + Int(chars[i].wholeNumberValue!); i += 1 }
        if i < n && chars[i] == ":" {
            i += 1
            while i < n && chars[i].isNumber { mm = mm*10 + Int(chars[i].wholeNumberValue!); i += 1 }
        }
        if i < n && chars[i] == ":" {
            i += 1
            while i < n && chars[i].isNumber { ss = ss*10 + Int(chars[i].wholeNumberValue!); i += 1 }
        }
        return sign * (hh*3600 + mm*60 + ss)
    }

    func readTimeVal() -> Int {
        var sign = 1
        if i < n && (chars[i] == "+" || chars[i] == "-") {
            if chars[i] == "-" { sign = -1 }
            i += 1
        }
        var hh = 0, mm = 0, ss = 0
        while i < n && chars[i].isNumber { hh = hh*10 + Int(chars[i].wholeNumberValue!); i += 1 }
        if i < n && chars[i] == ":" {
            i += 1
            while i < n && chars[i].isNumber { mm = mm*10 + Int(chars[i].wholeNumberValue!); i += 1 }
        }
        if i < n && chars[i] == ":" {
            i += 1
            while i < n && chars[i].isNumber { ss = ss*10 + Int(chars[i].wholeNumberValue!); i += 1 }
        }
        return sign * (hh*3600 + mm*60 + ss)
    }

    func readMD() -> (Int, Int, Int) {
        i += 1 // skip 'M'
        var m = 0, w = 0, d = 0
        while i < n && chars[i].isNumber { m = m*10 + Int(chars[i].wholeNumberValue!); i += 1 }
        if i < n && chars[i] == "." { i += 1 }
        while i < n && chars[i].isNumber { w = w*10 + Int(chars[i].wholeNumberValue!); i += 1 }
        if i < n && chars[i] == "." { i += 1 }
        while i < n && chars[i].isNumber { d = d*10 + Int(chars[i].wholeNumberValue!); i += 1 }
        return (m, w, d)
    }

    rule.stdName = readName()
    rule.stdOff = readOffsetVal()

    if i < n && chars[i] != "," {
        rule.dstName = readName()
        rule.hasDst = true
        if i < n && (chars[i].isNumber || chars[i] == "+" || chars[i] == "-") {
            rule.dstOff = readOffsetVal()
        } else {
            rule.dstOff = rule.stdOff - 3600
        }
    }

    if i < n && chars[i] == "," {
        i += 1
        rule.hasRules = true
        (rule.startM, rule.startW, rule.startD) = readMD()
        if i < n && chars[i] == "/" { i += 1; rule.startSec = readTimeVal() }
        if i < n && chars[i] == "," { i += 1 }
        (rule.endM, rule.endW, rule.endD) = readMD()
        if i < n && chars[i] == "/" { i += 1; rule.endSec = readTimeVal() }
    }

    return rule
}

// MARK: - Parse TZif file
func parseTZif(_ path: String) -> TZifFile {
    let data = try! Data(contentsOf: URL(fileURLWithPath: path))
    let bytes = [UInt8](data)

    // First header (44 bytes)
    let isutcnt1 = Int(readU32(bytes, 20))
    let isstdcnt1 = Int(readU32(bytes, 24))
    let leapcnt1 = Int(readU32(bytes, 28))
    let timecnt1 = Int(readU32(bytes, 32))
    let typecnt1 = Int(readU32(bytes, 36))
    let charcnt1 = Int(readU32(bytes, 40))
    let block1Size = timecnt1*4 + timecnt1*1 + typecnt1*6 + charcnt1 + leapcnt1*8 + isstdcnt1 + isutcnt1
    let off2 = 44 + block1Size

    // Second header
    let isutcnt2 = Int(readU32(bytes, off2 + 20))
    let isstdcnt2 = Int(readU32(bytes, off2 + 24))
    let leapcnt2 = Int(readU32(bytes, off2 + 28))
    let timecnt2 = Int(readU32(bytes, off2 + 32))
    let typecnt2 = Int(readU32(bytes, off2 + 36))
    let charcnt2 = Int(readU32(bytes, off2 + 40))

    var pos = off2 + 44

    var transitions = [Int64]()
    for _ in 0..<timecnt2 { transitions.append(readBE64(bytes, pos)); pos += 8 }

    var transTypes = [UInt8]()
    for _ in 0..<timecnt2 { transTypes.append(bytes[pos]); pos += 1 }

    var ttis = [TTInfo]()
    for _ in 0..<typecnt2 {
        let gmtoff = readBE32(bytes, pos)
        let isdst = bytes[pos+4]
        let abbrind = bytes[pos+5]
        ttis.append(TTInfo(gmtoff: gmtoff, isdst: isdst, abbrind: abbrind))
        pos += 6
    }

    let abbrs = Array(bytes[pos..<pos+charcnt2])
    pos += charcnt2
    pos += leapcnt2 * 12 + isstdcnt2 + isutcnt2

    // Footer: \n + POSIX string + \n
    pos += 1 // skip first \n
    var footerBytes = [UInt8]()
    while pos < bytes.count && bytes[pos] != 10 { footerBytes.append(bytes[pos]); pos += 1 }
    let posixTZ = String(bytes: footerBytes, encoding: .ascii) ?? ""

    return TZifFile(transitions: transitions, transTypes: transTypes, ttis: ttis, abbrs: abbrs, posixTZ: posixTZ)
}

// MARK: - Abbreviation lookup
func getAbbr(_ tz: TZifFile, _ ti: TTInfo) -> String {
    var s = ""
    var idx = Int(ti.abbrind)
    while idx < tz.abbrs.count && tz.abbrs[idx] != 0 {
        s.append(Character(UnicodeScalar(tz.abbrs[idx])))
        idx += 1
    }
    return s
}

// MARK: - Type resolution
func resolveFooter(_ t: Int64, _ rule: PosixRule) -> (Int32, Bool, String) {
    let stdGmtoff = Int32(-rule.stdOff)
    let dstGmtoff = Int32(-rule.dstOff)
    if !rule.hasDst || !rule.hasRules {
        return (stdGmtoff, false, rule.stdName)
    }
    let approxDays = floorDiv(t + Int64(stdGmtoff), 86400)
    let (approxYear, _, _) = civilFromDays(Int(approxDays))
    for year in [approxYear - 1, approxYear, approxYear + 1] {
        let startDom = mdToDayOfMonth(year: year, m: rule.startM, w: rule.startW, d: rule.startD)
        let endDom = mdToDayOfMonth(year: year, m: rule.endM, w: rule.endW, d: rule.endD)
        let dstStartUTC = Int64(daysFromCivil(y: year, m: rule.startM, d: startDom)) * 86400 + Int64(rule.startSec) + Int64(rule.stdOff)
        let dstEndUTC = Int64(daysFromCivil(y: year, m: rule.endM, d: endDom)) * 86400 + Int64(rule.endSec) + Int64(rule.dstOff)
        if t >= dstStartUTC && t < dstEndUTC {
            return (dstGmtoff, true, rule.dstName)
        }
    }
    return (stdGmtoff, false, rule.stdName)
}

func resolveType(_ t: Int64, _ tz: TZifFile, _ rule: PosixRule) -> (Int32, Bool, String) {
    if tz.transitions.isEmpty {
        return resolveFooter(t, rule)
    }
    if t < tz.transitions[0] {
        let ti = tz.ttis[0]
        return (ti.gmtoff, ti.isdst != 0, getAbbr(tz, ti))
    }
    if t > tz.transitions[tz.transitions.count - 1] {
        return resolveFooter(t, rule)
    }
    // trans[0] <= t <= trans[last]
    var lo = 0, hi = tz.transitions.count - 1
    var idx = 0
    while lo <= hi {
        let mid = (lo + hi) / 2
        if tz.transitions[mid] <= t { idx = mid; lo = mid + 1 }
        else { hi = mid - 1 }
    }
    let ti = tz.ttis[Int(tz.transTypes[idx])]
    return (ti.gmtoff, ti.isdst != 0, getAbbr(tz, ti))
}

// MARK: - Formatting
func formatOffset(_ gmtoff: Int) -> String {
    if gmtoff == 0 { return "+00:00" }
    let sign = gmtoff >= 0 ? "+" : "-"
    let a = abs(gmtoff)
    let h = a / 3600
    let m = (a % 3600) / 60
    let s = a % 60
    if s != 0 {
        return String(format: "%@%02d:%02d:%02d", sign, h, m, s)
    } else {
        return String(format: "%@%02d:%02d", sign, h, m)
    }
}

func formatLocalTime(_ t: Int64, _ gmtoff: Int) -> String {
    let local = t + Int64(gmtoff)
    let day = floorDiv(local, 86400)
    let secOfDay = Int(local - day * 86400)
    let (y, m, d) = civilFromDays(Int(day))
    let h = secOfDay / 3600
    let mi = (secOfDay % 3600) / 60
    let s = secOfDay % 60
    let dateStr = String(format: "%04d-%02d-%02dT%02d:%02d:%02d", y, m, d, h, mi, s)
    return dateStr + formatOffset(gmtoff)
}

// MARK: - Main
let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }
let dir = args[1]

let queriesPath = dir + "/queries.txt"
let queriesContent = try! String(contentsOfFile: queriesPath, encoding: .utf8)
let queryLines = queriesContent.components(separatedBy: "\n")

// Cache parsed files
var fileCache: [String: (TZifFile, PosixRule)] = [:]

func getFile(_ name: String) -> (TZifFile, PosixRule) {
    if let cached = fileCache[name] { return cached }
    let path = dir + "/" + name
    let tz = parseTZif(path)
    let rule = parsePosixTZ(tz.posixTZ)
    fileCache[name] = (tz, rule)
    return (tz, rule)
}

var outputLines: [String] = []

for line in queryLines {
    let trimmed = line.trimmingCharacters(in: .whitespaces)
    if trimmed.isEmpty { continue }
    let parts = trimmed.components(separatedBy: " ")
    guard parts.count >= 3 else { continue }

    let queryType = parts[0]
    let fileName = parts[1]
    let (tz, rule) = getFile(fileName)

    if queryType == "UTC" {
        let t = Int64(parts[2])!
        let (gmtoff, _, abbr) = resolveType(t, tz, rule)
        let localStr = formatLocalTime(t, Int(gmtoff))
        outputLines.append("\(trimmed) -> \(localStr) \(abbr)")
    } else if queryType == "LOCAL" {
        let timeStr = parts[2]
        // Parse YYYY-MM-DDTHH:MM:SS
        let dateParts = timeStr.components(separatedBy: "T")
        let ymd = dateParts[0].components(separatedBy: "-")
        let hms = dateParts[1].components(separatedBy: ":")
        let yr = Int(ymd[0])!, mo = Int(ymd[1])!, dy = Int(ymd[2])!
        let hh = Int(hms[0])!, mi = Int(hms[1])!, ss = Int(hms[2])!
        let W_unix = Int64(daysFromCivil(y: yr, m: mo, d: dy)) * 86400 + Int64(hh)*3600 + Int64(mi)*60 + Int64(ss)

        // Collect all possible offsets
        var offsetSet = Set<Int>()
        for ti in tz.ttis { offsetSet.insert(Int(ti.gmtoff)) }
        offsetSet.insert(-rule.stdOff)
        if rule.hasDst { offsetSet.insert(-rule.dstOff) }

        var results: [(Int64, Int, String)] = []
        for o in offsetSet {
            let t = W_unix - Int64(o)
            let (go, _, ab) = resolveType(t, tz, rule)
            if Int(go) == o {
                results.append((t, o, ab))
            }
        }
        results.sort { $0.0 < $1.0 }

        if results.count == 1 {
            let (t, o, ab) = results[0]
            outputLines.append("\(trimmed) -> \(t) \(formatOffset(o)) \(ab)")
        } else if results.count >= 2 {
            // Take first two (should be exactly 2 for overlaps)
            let (t1, o1, ab1) = results[0]
            let (t2, o2, ab2) = results[1]
            outputLines.append("\(trimmed) -> \(t1) \(formatOffset(o1)) \(ab1) | \(t2) \(formatOffset(o2)) \(ab2)")
        } else {
            // Gap: find the transition that caused it
            var gapT: Int64 = 0
            var gapO: Int = 0
            var gapAbbr: String = ""
            var found = false

            // Check transition-based gaps
            for i in 0..<tz.transitions.count {
                let T = tz.transitions[i]
                let oBefore: Int
                if i == 0 {
                    oBefore = Int(tz.ttis[0].gmtoff)
                } else {
                    oBefore = Int(tz.ttis[Int(tz.transTypes[i-1])].gmtoff)
                }
                let oAfter = Int(tz.ttis[Int(tz.transTypes[i])].gmtoff)
                if oAfter > oBefore {
                    let gapStart = T + Int64(oBefore)
                    let gapEnd = T + Int64(oAfter)
                    if W_unix >= gapStart && W_unix < gapEnd {
                        gapT = W_unix - Int64(oBefore)
                        let (go, _, ab) = resolveType(gapT, tz, rule)
                        gapO = Int(go)
                        gapAbbr = ab
                        found = true
                        break
                    }
                }
            }

            // Check footer-based gaps (spring forward)
            if !found && rule.hasDst && rule.hasRules {
                let stdGmtoff = -rule.stdOff
                let dstGmtoff = -rule.dstOff
                let approxDays = floorDiv(W_unix, 86400)
                let (approxYear, _, _) = civilFromDays(Int(approxDays))
                for year in [approxYear - 1, approxYear, approxYear + 1] {
                    let startDom = mdToDayOfMonth(year: year, m: rule.startM, w: rule.startW, d: rule.startD)
                    let dstStartUTC = Int64(daysFromCivil(y: year, m: rule.startM, d: startDom)) * 86400 + Int64(rule.startSec) + Int64(rule.stdOff)
                    let gapStart = dstStartUTC + Int64(stdGmtoff)
                    let gapEnd = dstStartUTC + Int64(dstGmtoff)
                    if W_unix >= gapStart && W_unix < gapEnd {
                        gapT = W_unix - Int64(stdGmtoff)
                        let (go, _, ab) = resolveType(gapT, tz, rule)
                        gapO = Int(go)
                        gapAbbr = ab
                        found = true
                        break
                    }
                }
            }

            // Check boundary between last transition and footer
            if !found && !tz.transitions.isEmpty {
                let lastT = tz.transitions[tz.transitions.count - 1]
                let oBefore = Int(tz.ttis[Int(tz.transTypes[tz.transitions.count - 1])].gmtoff)
                let oAfter = -rule.stdOff // footer standard
                if oAfter > oBefore {
                    let gapStart = lastT + Int64(oBefore) + 1
                    let gapEnd = lastT + Int64(oAfter) + 1
                    if W_unix >= gapStart && W_unix < gapEnd {
                        gapT = W_unix - Int64(oBefore)
                        let (go, _, ab) = resolveType(gapT, tz, rule)
                        gapO = Int(go)
                        gapAbbr = ab
                        found = true
                    }
                }
            }

            if found {
                let localStr = formatLocalTime(gapT, gapO)
                outputLines.append("\(trimmed) -> GAP \(gapT) \(localStr) \(gapAbbr)")
            }
        }
    }
}

for line in outputLines {
    print(line)
}

import * as fs from 'fs';
import * as path from 'path';

interface LocalTimeType {
    gmtoff: number;
    isdst: number;
    abbrIndex: number;
    abbr: string;
}

interface TZifData {
    transitions: number[];
    transTypes: number[];
    types: LocalTimeType[];
    footer: string;
}

interface MWD {
    month: number;
    week: number;
    day: number;
    time: number;
}

interface PosixTZ {
    stdName: string;
    stdOffset: number;
    dstName: string | null;
    dstOffset: number | null;
    startRule: MWD | null;
    endRule: MWD | null;
}

function parseTZif(filePath: string): TZifData {
    const buf = fs.readFileSync(filePath);

    const isutcnt1 = buf.readUInt32BE(20);
    const isstdcnt1 = buf.readUInt32BE(24);
    const leapcnt1 = buf.readUInt32BE(28);
    const timecnt1 = buf.readUInt32BE(32);
    const typecnt1 = buf.readUInt32BE(36);
    const charcnt1 = buf.readUInt32BE(40);

    const firstBlockSize = timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1;
    const secondHeaderOffset = 44 + firstBlockSize;

    const isutcnt = buf.readUInt32BE(secondHeaderOffset + 20);
    const isstdcnt = buf.readUInt32BE(secondHeaderOffset + 24);
    const leapcnt = buf.readUInt32BE(secondHeaderOffset + 28);
    const timecnt = buf.readUInt32BE(secondHeaderOffset + 32);
    const typecnt = buf.readUInt32BE(secondHeaderOffset + 36);
    const charcnt = buf.readUInt32BE(secondHeaderOffset + 40);

    let pos = secondHeaderOffset + 44;

    const transitions: number[] = [];
    for (let i = 0; i < timecnt; i++) {
        const hi = buf.readInt32BE(pos);
        const lo = buf.readUInt32BE(pos + 4);
        transitions.push(hi * 0x100000000 + lo);
        pos += 8;
    }

    const transTypes: number[] = [];
    for (let i = 0; i < timecnt; i++) {
        transTypes.push(buf[pos]);
        pos += 1;
    }

    const types: LocalTimeType[] = [];
    for (let i = 0; i < typecnt; i++) {
        const gmtoff = buf.readInt32BE(pos);
        const isdst = buf[pos + 4];
        const abbrIndex = buf[pos + 5];
        types.push({ gmtoff, isdst, abbrIndex, abbr: '' });
        pos += 6;
    }

    const abbrStart = pos;
    for (let i = 0; i < typecnt; i++) {
        let end = abbrStart + types[i].abbrIndex;
        while (buf[end] !== 0) end++;
        types[i].abbr = buf.slice(abbrStart + types[i].abbrIndex, end).toString('ascii');
    }
    pos += charcnt;

    pos += leapcnt * 12;
    pos += isstdcnt;
    pos += isutcnt;

    pos++; // skip newline
    let footerEnd = pos;
    while (footerEnd < buf.length && buf[footerEnd] !== 10) footerEnd++;
    const footer = buf.slice(pos, footerEnd).toString('ascii');

    return { transitions, transTypes, types, footer };
}

function parsePosixTZ(s: string): PosixTZ | null {
    if (!s || s.length === 0) return null;

    let pos = 0;

    function parseName(): string {
        if (s[pos] === '<') {
            pos++;
            let name = '';
            while (pos < s.length && s[pos] !== '>') {
                name += s[pos];
                pos++;
            }
            pos++;
            return name;
        } else {
            let name = '';
            while (pos < s.length && /[a-zA-Z]/.test(s[pos])) {
                name += s[pos];
                pos++;
            }
            return name;
        }
    }

    function parseOffset(): number {
        let sign = 1;
        if (s[pos] === '+') { pos++; }
        else if (s[pos] === '-') { sign = -1; pos++; }

        let hours = 0;
        while (pos < s.length && /[0-9]/.test(s[pos])) {
            hours = hours * 10 + (s[pos].charCodeAt(0) - 48);
            pos++;
        }

        let minutes = 0;
        let seconds = 0;
        if (pos < s.length && s[pos] === ':') {
            pos++;
            while (pos < s.length && /[0-9]/.test(s[pos])) {
                minutes = minutes * 10 + (s[pos].charCodeAt(0) - 48);
                pos++;
            }
            if (pos < s.length && s[pos] === ':') {
                pos++;
                while (pos < s.length && /[0-9]/.test(s[pos])) {
                    seconds = seconds * 10 + (s[pos].charCodeAt(0) - 48);
                    pos++;
                }
            }
        }

        return sign * (hours * 3600 + minutes * 60 + seconds);
    }

    function parseMWD(): MWD | null {
        if (pos >= s.length || s[pos] !== 'M') return null;
        pos++;

        let month = 0;
        while (pos < s.length && /[0-9]/.test(s[pos])) {
            month = month * 10 + (s[pos].charCodeAt(0) - 48);
            pos++;
        }
        if (pos < s.length && s[pos] === '.') pos++;

        let week = 0;
        while (pos < s.length && /[0-9]/.test(s[pos])) {
            week = week * 10 + (s[pos].charCodeAt(0) - 48);
            pos++;
        }
        if (pos < s.length && s[pos] === '.') pos++;

        let day = 0;
        while (pos < s.length && /[0-9]/.test(s[pos])) {
            day = day * 10 + (s[pos].charCodeAt(0) - 48);
            pos++;
        }

        let time = 2 * 3600;
        if (pos < s.length && s[pos] === '/') {
            pos++;
            time = parseOffset();
        }

        return { month, week, day, time };
    }

    const stdName = parseName();
    const stdOffset = parseOffset();

    let dstName: string | null = null;
    let dstOffset: number | null = null;
    let startRule: MWD | null = null;
    let endRule: MWD | null = null;

    if (pos < s.length && (s[pos] === '<' || /[a-zA-Z]/.test(s[pos]))) {
        dstName = parseName();

        if (pos < s.length && (s[pos] === '+' || s[pos] === '-' || /[0-9]/.test(s[pos]))) {
            dstOffset = parseOffset();
        } else {
            dstOffset = stdOffset - 3600;
        }

        if (pos < s.length && s[pos] === ',') {
            pos++;
            startRule = parseMWD();
            if (pos < s.length && s[pos] === ',') {
                pos++;
                endRule = parseMWD();
            }
        }
    }

    return { stdName, stdOffset, dstName, dstOffset, startRule, endRule };
}

function mwdToUTC(year: number, rule: MWD, posixOffset: number): number {
    const { month, week, day, time } = rule;

    const firstOfMonth = new Date(Date.UTC(year, month - 1, 1));
    const firstDow = firstOfMonth.getUTCDay();

    let firstOcc = 1 + ((day - firstDow + 7) % 7);

    let dayOfMonth: number;
    if (week < 5) {
        dayOfMonth = firstOcc + (week - 1) * 7;
    } else {
        const lastDayOfMonth = new Date(Date.UTC(year, month, 0)).getUTCDate();
        const lastDow = new Date(Date.UTC(year, month - 1, lastDayOfMonth)).getUTCDay();
        dayOfMonth = lastDayOfMonth - ((lastDow - day + 7) % 7);
    }

    const dateMs = Date.UTC(year, month - 1, dayOfMonth);
    const dateSec = Math.round(dateMs / 1000);

    return dateSec + time + posixOffset;
}

function getFooterType(t: number, footer: PosixTZ): { gmtoff: number; abbr: string; isdst: boolean } {
    if (!footer.dstName || !footer.startRule || !footer.endRule) {
        return { gmtoff: -footer.stdOffset, abbr: footer.stdName, isdst: false };
    }

    const d = new Date(t * 1000);
    const year = d.getUTCFullYear();

    const startUTC = mwdToUTC(year, footer.startRule, footer.stdOffset);
    const endUTC = mwdToUTC(year, footer.endRule, footer.dstOffset!);

    let isDst: boolean;
    if (startUTC < endUTC) {
        isDst = t >= startUTC && t < endUTC;
    } else if (startUTC > endUTC) {
        isDst = t >= startUTC || t < endUTC;
    } else {
        isDst = false;
    }

    if (isDst) {
        return { gmtoff: -footer.dstOffset!, abbr: footer.dstName, isdst: true };
    } else {
        return { gmtoff: -footer.stdOffset, abbr: footer.stdName, isdst: false };
    }
}

function getTypeAtTime(t: number, data: TZifData, footer: PosixTZ | null): { gmtoff: number; abbr: string; isdst: boolean } {
    if (data.transitions.length === 0) {
        if (footer) return getFooterType(t, footer);
        return { gmtoff: data.types[0].gmtoff, abbr: data.types[0].abbr, isdst: data.types[0].isdst !== 0 };
    }

    if (t < data.transitions[0]) {
        return { gmtoff: data.types[0].gmtoff, abbr: data.types[0].abbr, isdst: data.types[0].isdst !== 0 };
    }

    if (t > data.transitions[data.transitions.length - 1]) {
        if (footer) return getFooterType(t, footer);
        const lastTypeIdx = data.transTypes[data.transitions.length - 1];
        return { gmtoff: data.types[lastTypeIdx].gmtoff, abbr: data.types[lastTypeIdx].abbr, isdst: data.types[lastTypeIdx].isdst !== 0 };
    }

    let lo = 0, hi = data.transitions.length - 1;
    while (lo < hi) {
        const mid = (lo + hi + 1) >> 1;
        if (data.transitions[mid] <= t) lo = mid;
        else hi = mid - 1;
    }

    const typeIdx = data.transTypes[lo];
    return { gmtoff: data.types[typeIdx].gmtoff, abbr: data.types[typeIdx].abbr, isdst: data.types[typeIdx].isdst !== 0 };
}

function formatOffset(gmtoff: number): string {
    const sign = gmtoff >= 0 ? '+' : '-';
    const abs = Math.abs(gmtoff);
    const hours = Math.floor(abs / 3600);
    const minutes = Math.floor((abs % 3600) / 60);
    const seconds = abs % 60;

    const hh = String(hours).padStart(2, '0');
    const mm = String(minutes).padStart(2, '0');

    if (seconds > 0) {
        const ss = String(seconds).padStart(2, '0');
        return `${sign}${hh}:${mm}:${ss}`;
    } else {
        return `${sign}${hh}:${mm}`;
    }
}

function formatLocalTime(t: number, gmtoff: number): string {
    const localT = t + gmtoff;
    const d = new Date(localT * 1000);
    const year = d.getUTCFullYear();
    const month = String(d.getUTCMonth() + 1).padStart(2, '0');
    const day = String(d.getUTCDate()).padStart(2, '0');
    const hours = String(d.getUTCHours()).padStart(2, '0');
    const minutes = String(d.getUTCMinutes()).padStart(2, '0');
    const seconds = String(d.getUTCSeconds()).padStart(2, '0');
    return `${year}-${month}-${day}T${hours}:${minutes}:${seconds}${formatOffset(gmtoff)}`;
}

function findGapTransition(W: number, data: TZifData, footer: PosixTZ | null): { offsetBefore: number } | null {
    for (let i = 0; i < data.transitions.length; i++) {
        const T = data.transitions[i];
        const newGmtoff = data.types[data.transTypes[i]].gmtoff;
        let oldGmtoff: number;
        if (i === 0) {
            oldGmtoff = data.types[0].gmtoff;
        } else {
            oldGmtoff = data.types[data.transTypes[i - 1]].gmtoff;
        }
        if (newGmtoff > oldGmtoff) {
            if (W >= T + oldGmtoff && W < T + newGmtoff) {
                return { offsetBefore: oldGmtoff };
            }
        }
    }

    if (footer && footer.dstName && footer.startRule && footer.endRule) {
        const d = new Date(W * 1000);
        const year = d.getUTCFullYear();

        for (let y = year - 1; y <= year + 1; y++) {
            const startUTC = mwdToUTC(y, footer.startRule, footer.stdOffset);
            const endUTC = mwdToUTC(y, footer.endRule, footer.dstOffset!);

            const stdGmtoff = -footer.stdOffset;
            const dstGmtoff = -footer.dstOffset!;

            if (dstGmtoff > stdGmtoff) {
                if (W >= startUTC + stdGmtoff && W < startUTC + dstGmtoff) {
                    return { offsetBefore: stdGmtoff };
                }
            }

            if (stdGmtoff > dstGmtoff) {
                if (W >= endUTC + dstGmtoff && W < endUTC + stdGmtoff) {
                    return { offsetBefore: dstGmtoff };
                }
            }
        }
    }

    return null;
}

function main() {
    const dir = process.argv[2];
    const queriesPath = path.join(dir, 'queries.txt');
    const queriesContent = fs.readFileSync(queriesPath, 'utf-8');
    const lines = queriesContent.split('\n');

    const tzifCache: Map<string, { data: TZifData; footer: PosixTZ | null }> = new Map();

    function getTZif(fileName: string) {
        if (!tzifCache.has(fileName)) {
            const filePath = path.join(dir, fileName);
            const data = parseTZif(filePath);
            const footer = parsePosixTZ(data.footer);
            tzifCache.set(fileName, { data, footer });
        }
        return tzifCache.get(fileName)!;
    }

    const output: string[] = [];

    for (const line of lines) {
        if (line.trim() === '') continue;

        const parts = line.split(' ');
        const queryType = parts[0];
        const fileName = parts[1];

        if (queryType === 'UTC') {
            const t = parseInt(parts[2], 10);
            const { data, footer } = getTZif(fileName);
            const type = getTypeAtTime(t, data, footer);
            const local = formatLocalTime(t, type.gmtoff);
            output.push(`${line} -> ${local} ${type.abbr}`);
        } else if (queryType === 'LOCAL') {
            const wallClockStr = parts[2];
            const { data, footer } = getTZif(fileName);

            const [datePart, timePart] = wallClockStr.split('T');
            const [y, m, d] = datePart.split('-').map(Number);
            const [h, mi, s] = timePart.split(':').map(Number);
            const W = Math.round(Date.UTC(y, m - 1, d, h, mi, s) / 1000);

            const solutions: { t: number; gmtoff: number; abbr: string }[] = [];

            const offsets = new Set<number>();
            for (const type of data.types) {
                offsets.add(type.gmtoff);
            }
            if (footer) {
                offsets.add(-footer.stdOffset);
                if (footer.dstOffset !== null) {
                    offsets.add(-footer.dstOffset);
                }
            }

            for (const g of offsets) {
                const t = W - g;
                const type = getTypeAtTime(t, data, footer);
                if (type.gmtoff === g) {
                    solutions.push({ t, gmtoff: g, abbr: type.abbr });
                }
            }

            solutions.sort((a, b) => a.t - b.t);

            if (solutions.length === 1) {
                const sol = solutions[0];
                output.push(`${line} -> ${sol.t} ${formatOffset(sol.gmtoff)} ${sol.abbr}`);
            } else if (solutions.length >= 2) {
                const s1 = solutions[0];
                const s2 = solutions[1];
                output.push(`${line} -> ${s1.t} ${formatOffset(s1.gmtoff)} ${s1.abbr} | ${s2.t} ${formatOffset(s2.gmtoff)} ${s2.abbr}`);
            } else {
                const gapInfo = findGapTransition(W, data, footer);
                if (gapInfo) {
                    const t = W - gapInfo.offsetBefore;
                    const type = getTypeAtTime(t, data, footer);
                    const local = formatLocalTime(t, type.gmtoff);
                    output.push(`${line} -> GAP ${t} ${local} ${type.abbr}`);
                }
            }
        }
    }

    console.log(output.join('\n'));
}

main();

import * as net from 'net';
import * as crypto from 'crypto';

class SocketReader {
  private buffer: Buffer = Buffer.alloc(0);
  private dataResolve: (() => void) | null = null;
  private closed = false;

  constructor(private socket: net.Socket) {
    socket.on('data', (chunk: Buffer) => {
      this.buffer = Buffer.concat([this.buffer, chunk]);
      this.wake();
    });
    socket.on('end', () => { this.closed = true; this.wake(); });
    socket.on('close', () => { this.closed = true; this.wake(); });
    socket.on('error', () => { this.closed = true; this.wake(); });
  }

  private wake(): void {
    if (this.dataResolve) {
      const r = this.dataResolve;
      this.dataResolve = null;
      r();
    }
  }

  async readExact(n: number): Promise<Buffer> {
    while (this.buffer.length < n) {
      if (this.closed) throw new Error('Connection closed');
      await new Promise<void>(resolve => { this.dataResolve = resolve; });
    }
    const result = this.buffer.subarray(0, n);
    this.buffer = this.buffer.subarray(n);
    return result;
  }

  async readUntil(delim: Buffer): Promise<Buffer> {
    while (true) {
      const idx = this.buffer.indexOf(delim);
      if (idx !== -1) {
        const result = this.buffer.subarray(0, idx + delim.length);
        this.buffer = this.buffer.subarray(idx + delim.length);
        return result;
      }
      if (this.closed) throw new Error('Connection closed');
      await new Promise<void>(resolve => { this.dataResolve = resolve; });
    }
  }
}

function sendFrame(socket: net.Socket, opcode: number, payload: Buffer): void {
  let maskKey: Buffer;
  do {
    maskKey = crypto.randomBytes(4);
  } while (maskKey[0] === 0 && maskKey[1] === 0 && maskKey[2] === 0 && maskKey[3] === 0);

  const parts: Buffer[] = [];
  const header = Buffer.alloc(2);
  header[0] = 0x80 | (opcode & 0x0F);
  header[1] = 0x80;

  if (payload.length <= 125) {
    header[1] |= payload.length;
    parts.push(header);
  } else if (payload.length <= 65535) {
    header[1] |= 126;
    parts.push(header);
    const ext = Buffer.alloc(2);
    ext.writeUInt16BE(payload.length);
    parts.push(ext);
  } else {
    header[1] |= 127;
    parts.push(header);
    const ext = Buffer.alloc(8);
    ext.writeBigUInt64BE(BigInt(payload.length));
    parts.push(ext);
  }

  parts.push(maskKey);

  const masked = Buffer.alloc(payload.length);
  for (let i = 0; i < payload.length; i++) {
    masked[i] = payload[i] ^ maskKey[i & 3];
  }
  parts.push(masked);

  socket.write(Buffer.concat(parts));
}

async function readFrame(reader: SocketReader): Promise<{ fin: boolean; opcode: number; payload: Buffer }> {
  const h = await reader.readExact(2);
  const fin = (h[0] & 0x80) !== 0;
  const opcode = h[0] & 0x0F;
  const masked = (h[1] & 0x80) !== 0;
  let len = h[1] & 0x7F;

  if (len === 126) {
    const lb = await reader.readExact(2);
    len = lb.readUInt16BE(0);
  } else if (len === 127) {
    const lb = await reader.readExact(8);
    len = Number(lb.readBigUInt64BE(0));
  }

  let payload: Buffer;
  if (masked) {
    const mk = await reader.readExact(4);
    const raw = await reader.readExact(len);
    payload = Buffer.alloc(len);
    for (let i = 0; i < len; i++) payload[i] = raw[i] ^ mk[i & 3];
  } else {
    payload = await reader.readExact(len);
  }

  return { fin, opcode, payload };
}

type MsgResult = { type: 'data'; opcode: number; payload: Buffer } | { type: 'close'; code: number; reason: string };

async function readMessage(reader: SocketReader, socket: net.Socket): Promise<MsgResult> {
  while (true) {
    const frame = await readFrame(reader);

    if (frame.opcode === 9) {
      sendFrame(socket, 10, frame.payload);
      continue;
    }
    if (frame.opcode === 10) {
      continue;
    }
    if (frame.opcode === 8) {
      let code = 1005;
      let reason = '';
      if (frame.payload.length >= 2) {
        code = frame.payload.readUInt16BE(0);
        reason = frame.payload.subarray(2).toString('utf8');
      }
      return { type: 'close', code, reason };
    }

    if (frame.opcode === 1 || frame.opcode === 2) {
      const fragments: Buffer[] = [frame.payload];
      let fin = frame.fin;
      while (!fin) {
        const nf = await readFrame(reader);
        if (nf.opcode === 9) { sendFrame(socket, 10, nf.payload); continue; }
        if (nf.opcode === 10) continue;
        if (nf.opcode === 8) {
          let code = 1005;
          let reason = '';
          if (nf.payload.length >= 2) {
            code = nf.payload.readUInt16BE(0);
            reason = nf.payload.subarray(2).toString('utf8');
          }
          return { type: 'close', code, reason };
        }
        fragments.push(nf.payload);
        fin = nf.fin;
      }
      return { type: 'data', opcode: frame.opcode, payload: Buffer.concat(fragments) };
    }

    // unexpected opcode, skip
  }
}

function handleCommand(command: string, socket: net.Socket): void {
  if (command.startsWith('ADD ')) {
    const rest = command.substring(4);
    const spaceIdx = rest.indexOf(' ');
    const a = BigInt(rest.substring(0, spaceIdx));
    const b = BigInt(rest.substring(spaceIdx + 1));
    const sum = (a + b).toString();
    console.log(`${command} -> ${sum}`);
    sendFrame(socket, 1, Buffer.from(sum, 'utf8'));
  } else if (command.startsWith('REV ')) {
    const text = command.substring(4);
    const reversed = [...text].reverse().join('');
    console.log(`${command} -> ${reversed}`);
    sendFrame(socket, 1, Buffer.from(reversed, 'utf8'));
  }
}

function parseWsUrl(url: string): { port: number; requestTarget: string } {
  const m = url.match(/^ws:\/\/127\.0\.0\.1:(\d+)(\/.*)?$/);
  if (!m) throw new Error(`Bad URL: ${url}`);
  return { port: parseInt(m[1], 10), requestTarget: m[2] || '/' };
}

async function handleSession(url: string, n: number): Promise<void> {
  console.log(`session ${n}`);

  const { port, requestTarget } = parseWsUrl(url);
  const socket = new net.Socket();

  try {
    await new Promise<void>((resolve, reject) => {
      socket.connect(port, '127.0.0.1', resolve);
      socket.on('error', reject);
    });
  } catch {
    return;
  }

  const reader = new SocketReader(socket);

  // Handshake
  const key = crypto.randomBytes(16).toString('base64');
  const req =
    `GET ${requestTarget} HTTP/1.1\r\n` +
    `Host: 127.0.0.1:${port}\r\n` +
    `Upgrade: websocket\r\n` +
    `Connection: Upgrade\r\n` +
    `Sec-WebSocket-Version: 13\r\n` +
    `Sec-WebSocket-Key: ${key}\r\n` +
    `\r\n`;
  socket.write(req);

  let headerBlock: Buffer;
  try {
    headerBlock = await reader.readUntil(Buffer.from('\r\n\r\n'));
  } catch {
    socket.destroy();
    return;
  }

  const headerStr = headerBlock.toString('ascii');
  const lines = headerStr.split('\r\n');
  const statusLine = lines[0];
  const sm = statusLine.match(/^HTTP\/\d\.\d (\d{3})(?: (.*))?$/);
  if (!sm) {
    socket.destroy();
    return;
  }
  const statusCode = parseInt(sm[1], 10);
  const reasonPhrase = sm[2] || '';

  if (statusCode !== 101) {
    console.log(`handshake failed: ${statusCode} ${reasonPhrase}`);
    socket.destroy();
    return;
  }

  const expectedAccept = crypto.createHash('sha1')
    .update(key + '258EAFA5-E914-47DA-95CA-C5AB0DC85B11')
    .digest('base64');

  let acceptVal: string | undefined;
  for (let i = 1; i < lines.length; i++) {
    const ci = lines[i].indexOf(':');
    if (ci === -1) continue;
    const name = lines[i].substring(0, ci).trim().toLowerCase();
    if (name === 'sec-websocket-accept') {
      acceptVal = lines[i].substring(ci + 1).trim();
      break;
    }
  }

  if (acceptVal !== expectedAccept) {
    console.log('handshake failed: bad Sec-WebSocket-Accept');
    socket.destroy();
    return;
  }

  // Frame processing loop
  let sentClose = false;

  while (true) {
    let msg: MsgResult;
    try {
      msg = await readMessage(reader, socket);
    } catch {
      socket.destroy();
      return;
    }

    if (msg.type === 'close') {
      if (msg.reason) {
        console.log(`closed ${msg.code} ${msg.reason}`);
      } else {
        console.log(`closed ${msg.code}`);
      }
      if (!sentClose) {
        const cp = Buffer.alloc(2);
        cp.writeUInt16BE(msg.code);
        sendFrame(socket, 8, cp);
      }
      socket.destroy();
      return;
    }

    // Data message
    if (msg.opcode === 1) {
      const command = msg.payload.toString('utf8');

      if (command === 'SHA1') {
        let nextMsg: MsgResult;
        try {
          nextMsg = await readMessage(reader, socket);
        } catch {
          socket.destroy();
          return;
        }
        if (nextMsg.type === 'close') {
          if (nextMsg.reason) {
            console.log(`closed ${nextMsg.code} ${nextMsg.reason}`);
          } else {
            console.log(`closed ${nextMsg.code}`);
          }
          if (!sentClose) {
            const cp = Buffer.alloc(2);
            cp.writeUInt16BE(nextMsg.code);
            sendFrame(socket, 8, cp);
          }
          socket.destroy();
          return;
        }
        const hash = crypto.createHash('sha1').update(nextMsg.payload).digest('hex');
        console.log(`SHA1 ${nextMsg.payload.length} -> ${hash}`);
        sendFrame(socket, 1, Buffer.from(hash, 'utf8'));
      } else if (command === 'BYE') {
        const cp = Buffer.alloc(2);
        cp.writeUInt16BE(1000);
        sendFrame(socket, 8, cp);
        sentClose = true;
        // Read until server's close
        while (true) {
          let cm: MsgResult;
          try {
            cm = await readMessage(reader, socket);
          } catch {
            socket.destroy();
            return;
          }
          if (cm.type === 'close') {
            if (cm.reason) {
              console.log(`closed ${cm.code} ${cm.reason}`);
            } else {
              console.log(`closed ${cm.code}`);
            }
            socket.destroy();
            return;
          }
          // ignore data messages during BYE close handshake
        }
      } else {
        handleCommand(command, socket);
      }
    }
    // binary messages outside SHA1 context: ignore
  }
}

async function main(): Promise<void> {
  const args = process.argv.slice(2);
  for (let i = 0; i < args.length; i++) {
    await handleSession(args[i], i + 1);
  }
  process.exit(0);
}

