}

fn random_mask() -> [u8; 4] {
    loop {
        let b = random_bytes(4);
        if b[0] | b[1] | b[2] | b[3] != 0 {
            return [b[0], b[1], b[2], b[3]];
        }
    }
}

fn base64_encode(data: &[u8]) -> String {
    const C: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut s = String::new();
    for chunk in data.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = if chunk.len() > 1 { chunk[1] as u32 } else { 0 };
        let b2 = if chunk.len() > 2 { chunk[2] as u32 } else { 0 };
        let n = (b0 << 16) | (b1 << 8) | b2;
        s.push(C[((n >> 18) & 63) as usize] as char);
        s.push(C[((n >> 12) & 63) as usize] as char);
        if chunk.len() > 1 { s.push(C[((n >> 6) & 63) as usize] as char); } else { s.push('='); }
        if chunk.len() > 2 { s.push(C[(n & 63) as usize] as char); } else { s.push('='); }
    }
    s
}

fn sha1(data: &[u8]) -> [u8; 20] {
    let mut h: [u32; 5] = [0x67452301, 0xEFCDAB89, 0x98BADCFE, 0x10325476, 0xC3D2E1F0];
    let msg_len = data.len();
    let mut padded = data.to_vec();
    padded.push(0x80);
    while padded.len() % 64 != 56 { padded.push(0); }
    padded.extend_from_slice(&((msg_len as u64) * 8).to_be_bytes());
    for chunk in padded.chunks(64) {
        let mut w = [0u32; 80];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([chunk[i*4], chunk[i*4+1], chunk[i*4+2], chunk[i*4+3]]);
        }
        for i in 16..80 {
            w[i] = (w[i-3]^w[i-8]^w[i-14]^w[i-16]).rotate_left(1);
        }
        let (mut a, mut b, mut c, mut d, mut e) = (h[0], h[1], h[2], h[3], h[4]);
        for i in 0..80 {
            let (f, k) = if i < 20 { ((b&c)|(!b&d), 0x5A827999u32) }
                else if i < 40 { (b^c^d, 0x6ED9EBA1u32) }
                else if i < 60 { ((b&c)|(b&d)|(c&d), 0x8F1BBCDCu32) }
                else { (b^c^d, 0xCA62C1D6u32) };
            let tmp = a.rotate_left(5).wrapping_add(f).wrapping_add(e).wrapping_add(k).wrapping_add(w[i]);
            e = d; d = c; c = b.rotate_left(30); b = a; a = tmp;
        }
        h[0]=h[0].wrapping_add(a); h[1]=h[1].wrapping_add(b); h[2]=h[2].wrapping_add(c);
        h[3]=h[3].wrapping_add(d); h[4]=h[4].wrapping_add(e);
    }
    let mut r = [0u8; 20];
    for i in 0..5 { r[i*4..i*4+4].copy_from_slice(&h[i].to_be_bytes()); }
    r
}

fn hex_lower(data: &[u8]) -> String {
    data.iter().map(|b| format!("{:02x}", b)).collect()
}

fn parse_url(url: &str) -> (String, u16, String) {
    let rest = url.strip_prefix("ws://").unwrap();
    let slash_pos = rest.find('/').unwrap_or(rest.len());
    let hostport = &rest[..slash_pos];
    let path = if slash_pos < rest.len() { &rest[slash_pos..] } else { "/" };
    let colon_pos = hostport.rfind(':').unwrap();
    let host = &hostport[..colon_pos];
    let port: u16 = hostport[colon_pos+1..].parse().unwrap();
    (host.to_string(), port, path.to_string())
}

struct WsReader {
    stream: TcpStream,
    buf: Vec<u8>,
    pos: usize,
}

impl WsReader {
    fn new(stream: TcpStream) -> Self {
        WsReader { stream, buf: Vec::new(), pos: 0 }
    }
    fn read_byte(&mut self) -> Option<u8> {
        if self.pos < self.buf.len() {
            let b = self.buf[self.pos]; self.pos += 1; Some(b)
        } else {
            let mut b = [0u8; 1];
            match self.stream.read_exact(&mut b) { Ok(_) => Some(b[0]), Err(_) => None }
        }
    }
    fn read_n(&mut self, n: usize) -> Option<Vec<u8>> {
        if n == 0 { return Some(vec![]); }
        let mut result = Vec::with_capacity(n);
        let avail = self.buf.len() - self.pos;
        let take = avail.min(n);
        result.extend_from_slice(&self.buf[self.pos..self.pos+take]);
        self.pos += take;
        if result.len() < n {
            let mut tmp = vec![0u8; n - result.len()];
            match self.stream.read_exact(&mut tmp) {
                Ok(_) => result.extend_from_slice(&tmp),
                Err(_) => return None,
            }
        }
        Some(result)
    }
}

fn write_frame(stream: &mut TcpStream, opcode: u8, payload: &[u8]) {
    let mut frame = Vec::new();
    frame.push(0x80 | opcode);
    let mk = random_mask();
    let len = payload.len();
    if len <= 125 {
        frame.push(0x80 | len as u8);
    } else if len <= 65535 {
        frame.push(0x80 | 126);
        frame.extend_from_slice(&(len as u16).to_be_bytes());
    } else {
        frame.push(0x80 | 127);
        frame.extend_from_slice(&(len as u64).to_be_bytes());
    }
    frame.extend_from_slice(&mk);
    for (i, b) in payload.iter().enumerate() {
        frame.push(b ^ mk[i % 4]);
    }
    stream.write_all(&frame).unwrap();
    stream.flush().unwrap();
}

fn read_frame(reader: &mut WsReader) -> Option<(bool, u8, Vec<u8>)> {
    let b0 = reader.read_byte()?;
    let b1 = reader.read_byte()?;
    let fin = (b0 & 0x80) != 0;
    let opcode = b0 & 0x0F;
    let mut plen = (b1 & 0x7F) as usize;
    if plen == 126 {
        let b = reader.read_n(2)?;
        plen = u16::from_be_bytes([b[0], b[1]]) as usize;
    } else if plen == 127 {
        let b = reader.read_n(8)?;
        let mut a = [0u8; 8]; a.copy_from_slice(&b);
        plen = u64::from_be_bytes(a) as usize;
    }
    let payload = reader.read_n(plen)?;
    Some((fin, opcode, payload))
}

fn read_message(reader: &mut WsReader, stream: &mut TcpStream, fin: bool, opcode: u8, mut payload: Vec<u8>) -> (u8, Vec<u8>) {
    let mut f = fin;
    let op = opcode;
    while !f {
        match read_frame(reader) {
            Some((f2, op2, p)) => {
                if op2 == 9 {
                    write_frame(stream, 10, &p);
                    continue;
                }
                if op2 == 10 { continue; }
                payload.extend_from_slice(&p);
                f = f2;
            }
            None => break,
        }
    }
    (op, payload)
}

fn handle_session(url: &str) {
    let (host, port, path) = parse_url(url);
    let addr = format!("{}:{}", host, port);
    let stream = match TcpStream::connect(&addr) {
        Ok(s) => s,
        Err(_) => return,
    };
    stream.set_nodelay(true).ok();

    let key_bytes = random_bytes(16);
    let key = base64_encode(&key_bytes);

    let req = format!(
        "GET {} HTTP/1.1\r\nHost: {}:{}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: {}\r\n\r\n",
        path, host, port, key
    );

    let mut stream = stream;
    stream.write_all(req.as_bytes()).unwrap();
    stream.flush().unwrap();

    let mut reader = WsReader::new(stream);

    // Read HTTP response headers
    let mut header_buf: Vec<u8> = Vec::new();
    let mut state = 0usize; // 0=normal, 1=seen \r, 2=seen \r\n, 3=seen \r\n\r
    loop {
        match reader.read_byte() {
            Some(b) => {
                header_buf.push(b);
                match state {
                    0 => { if b == b'\r' { state = 1; } }
                    1 => { if b == b'\n' { state = 2; } else { state = 0; } }
                    2 => { if b == b'\r' { state = 3; } else { state = 0; } }
                    3 => { if b == b'\n' { break; } else { state = 0; } }
                    _ => state = 0,
                }
            }
            None => return,
        }
    }

    // Parse status line
    let header_str = String::from_utf8_lossy(&header_buf).to_string();
    let lines: Vec<&str> = header_str.split("\r\n").collect();
    let status_line = lines[0];
    let parts: Vec<&str> = status_line.splitn(3, ' ').collect();
    if parts.len() < 2 {
        println!("handshake failed: 0 ");
        return;
    }
    let status_code: u16 = parts[1].parse().unwrap_or(0);
    let reason_phrase = if parts.len() >= 3 { parts[2] } else { "" };

    if status_code != 101 {
        println!("handshake failed: {} {}", status_code, reason_phrase);
        return;
    }

    // Check Sec-WebSocket-Accept
    let expected_accept = {
        let mut input = key.clone();
        input.push_str("258EAFA5-E914-47DA-95CA-C5AB0DC85B11");
        let digest = sha1(input.as_bytes());
        base64_encode(&digest)
    };

    let mut accept_ok = false;
    for line in &lines[1..] {
        if let Some(colon) = line.find(':') {
            let name = line[..colon].trim().to_lowercase();
            if name == "sec-websocket-accept" {
                let val = line[colon+1..].trim();
                if val == expected_accept { accept_ok = true; }
            }
        }
    }

    if !accept_ok {
        println!("handshake failed: bad Sec-WebSocket-Accept");
        return;
    }

    // Move leftover bytes from header_buf into reader's buffer
    // header_buf contains everything up to and including \r\n\r\n
    // The reader already consumed those bytes, so we need to figure out what's left
    // Actually, the reader consumed bytes one by one. The header_buf is what we collected.
    // But the reader's internal buf might have extra bytes from a single read() call.
    // Let's check: the reader reads one byte at a time from stream or its buf.
    // The buf was initially empty. So all bytes came from stream.read_exact(1).
    // No extra bytes in buf. Good.

    // Main frame loop
    let mut sent_close = false;

    loop {
        let (fin, opcode, payload) = match read_frame(&mut reader) {
            Some(f) => f,
            None => break,
        };

        match opcode {
            1 | 2 => {
                // Text or binary message, possibly fragmented
                let (op, msg) = read_message(&mut reader, &mut reader.stream, fin, opcode, payload);
                if op == 1 {
                    // Text command
                    let text = String::from_utf8_lossy(&msg).to_string();
                    if text == "BYE" {
                        // Send close frame with code 1000
                        let close_payload = vec![0x03, 0xE8];
                        write_frame(&mut reader.stream, 8, &close_payload);
                        sent_close = true;
                        // Read frames until close arrives
                        loop {
                            match read_frame(&mut reader) {
                                Some((_, op2, p2)) => {
                                    if op2 == 9 {
                                        write_frame(&mut reader.stream, 10, &p2);
                                    } else if op2 == 10 {
                                        // ignore
                                    } else if op2 == 8 {
                                        // Handle close
                                        let (code, reason) = parse_close_payload(&p2);
                                        if reason.is_empty() {
                                            println!("closed {}", code);
                                        } else {
                                            println!("closed {} {}", code, reason);
                                        }
                                        // Already sent close, don't send another
                                        break;
                                    }
                                }
                                None => break,
                            }
                        }
                        return;
                    } else if text.starts_with("ADD ") {
                        let rest = &text[4..];
                        let sp = rest.find(' ').unwrap();
                        let a_str = &rest[..sp];
                        let b_str = &rest[sp+1..];
                        let a: i64 = a_str.parse().unwrap();
                        let b: i64 = b_str.parse().unwrap();
                        let sum = a + b;
                        let reply = sum.to_string();
                        write_frame(&mut reader.stream, 1, reply.as_bytes());
                        println!("ADD {} {} -> {}", a_str, b_str, sum);
                    } else if text.starts_with("REV ") {
                        let txt = &text[4..];
                        let reversed: String = txt.chars().rev().collect();
                        write_frame(&mut reader.stream, 1, reversed.as_bytes());
                        println!("REV {} -> {}", txt, reversed);
                    } else if text == "SHA1" {
                        // Read next data message (binary)
                        let (bin_payload) = read_next_data(&mut reader);
                        let digest = sha1(&bin_payload);
                        let hex = hex_lower(&digest);
                        write_frame(&mut reader.stream, 1, hex.as_bytes());
                        println!("SHA1 {} -> {}", bin_payload.len(), hex);
                    }
                }
                // Binary outside SHA1 context: ignore
            }
            9 => {
                // Ping: reply with pong immediately
                write_frame(&mut reader.stream, 10, &payload);
            }
            10 => {
                // Pong: ignore
            }
            8 => {
                // Close
                let (code, reason) = parse_close_payload(&payload);
                if reason.is_empty() {
                    println!("closed {}", code);
                } else {
                    println!("closed {} {}", code, reason);
                }
                if !sent_close {
                    let cp = vec![(code >> 8) as u8, (code & 0xFF) as u8];
                    write_frame(&mut reader.stream, 8, &cp);
                }
                return;
            }
            _ => {}
        }
    }
}

fn parse_close_payload(payload: &[u8]) -> (u16, String) {
    if payload.len() >= 2 {
        let code = u16::from_be_bytes([payload[0], payload[1]]);
        let reason = String::from_utf8_lossy(&payload[2..]).to_string();
        (code, reason)
    } else {
        (1005, String::new())
    }
}

fn read_next_data(reader: &mut WsReader) -> Vec<u8> {
    loop {
        match read_frame(reader) {
            Some((fin, opcode, payload)) => {
                if opcode == 9 {
                    write_frame(&mut reader.stream, 10, &payload);
                    continue;
                }
                if opcode == 10 { continue; }
                if opcode == 1 || opcode == 2 {
                    let (_, msg) = read_message(reader, &mut reader.stream, fin, opcode, payload);
                    return msg;
                }
                if opcode == 8 {
                    // Unexpected close during SHA1 data; return empty
                    return vec![];
                }
            }
            None => return vec![],
        }
    }
}

